window.SPIEL = {"days": [{"nr": 1, "title": "Berufsausbildung", "date": "23.11.2026", "quiz": [{"q": "Was bedeutet das Wort dual im dualen System der Berufsausbildung?", "o": ["Ausbildung an zwei Lernorten", "Ausbildung in zwei Berufen zugleich", "Ausbildung mit zwei Prüfungen pro Jahr", "Ausbildung bei zwei Unternehmen"], "c": 0, "e": "Dual heißt zweifach. Gelernt wird im Ausbildungsbetrieb und in der Berufsschule."}, {"q": "Welche Rolle hat die überbetriebliche Ausbildungsstätte?", "o": ["Sie ergänzt die betriebliche Ausbildung", "Sie ersetzt die Berufsschule vollständig", "Sie schließt die Ausbildungsverträge", "Sie zahlt die Ausbildungsvergütung"], "c": 0, "e": "Die überbetriebliche Ausbildungsstätte vermittelt Inhalte, die ein Betrieb nicht selbst zeigen kann. Sie ergänzt, ersetzt aber keinen Lernort."}, {"q": "Nach welcher Grundlage unterrichtet die Berufsschule?", "o": ["Nach dem Rahmenlehrplan der KMK", "Nach dem Ausbildungsplan des Betriebs", "Nach dem Tarifvertrag der Branche", "Nach der Prüfungsordnung des Betriebsrats"], "c": 0, "e": "Die Berufsschule arbeitet nach dem Rahmenlehrplan der Kultusministerkonferenz, den die Länder in eigene Lehrpläne übernehmen."}, {"q": "Wer erlässt die Ausbildungsordnung für Industriekaufleute?", "o": ["Der Bund", "Die IHK zu Lübeck", "Das Land Schleswig-Holstein", "Die Nordstern Fahrradwerke"], "c": 0, "e": "Ausbildungsordnungen sind Rechtsverordnungen des Bundes. Sie gelten in ganz Deutschland gleich."}, {"q": "Welche Stelle ist für die Ausbildung bei Nordstern in Norderstedt zuständig?", "o": ["IHK zu Lübeck", "Handwerkskammer Hamburg", "Agentur für Arbeit Norderstedt", "Kultusministerkonferenz"], "c": 0, "e": "Norderstedt liegt im Kreis Segeberg. Für Industrieberufe dort ist die IHK zu Lübeck die zuständige Stelle."}, {"q": "Wie heißen Gewerkschaften und Arbeitgeberverbände zusammen?", "o": ["Sozialpartner", "Kammern", "Zuständige Stellen", "Lernortpartner"], "c": 0, "e": "Gewerkschaften und Arbeitgeberverbände heißen Sozialpartner. Sie wirken bei der Neuordnung von Berufen mit und schließen Tarifverträge."}, {"q": "Welches Ministerium ist seit 2025 für die Berufsbildung zuständig?", "o": ["Bundesministerium für Bildung, Familie, Senioren, Frauen und Jugend", "Bundesministerium für Arbeit und Soziales", "Bundesministerium für Wirtschaft und Energie", "Bundesministerium für Bildung und Forschung"], "c": 0, "e": "Seit 2025 liegt die Berufsbildung beim BMBFSFJ. Vorher war das BMBF zuständig."}, {"q": "Seit wann gilt die neue Ausbildungsordnung für Industriekaufleute?", "o": ["Seit dem 01.08.2024", "Seit dem 01.08.2002", "Seit dem 01.01.2026", "Seit dem 15.12.2023"], "c": 0, "e": "Die IndKflAusbV vom 12.03.2024 ist am 01.08.2024 in Kraft getreten. Die Verordnung von 2002 trat gleichzeitig außer Kraft."}, {"q": "Wie lange dauert die Ausbildung zur Industriekauffrau regulär?", "o": ["Drei Jahre", "Zwei Jahre", "Dreieinhalb Jahre", "Vier Jahre"], "c": 0, "e": "Die IndKflAusbV sieht eine Ausbildungsdauer von drei Jahren vor."}, {"q": "Was wählt der Betrieb nach der neuen Ausbildungsordnung für Industriekaufleute aus?", "o": ["Ein Einsatzgebiet, zum Beispiel Personal", "Die Berufsschule im Bundesgebiet", "Die Prüfungsfragen der Abschlussprüfung", "Zwei Wahlqualifikationen aus zehn"], "c": 0, "e": "Statt Wahlqualifikationen wählt der Betrieb ein Einsatzgebiet. Personalwirtschaft ist eines davon."}, {"q": "Wofür steht der Abschnitt A der Ausbildungsordnung Industriekaufleute?", "o": ["Für die berufsprofilgebenden Inhalte", "Für die Inhalte der Berufsschule", "Für die Regeln zur Vergütung", "Für die Pflichten des Betriebsrats"], "c": 0, "e": "Abschnitt A enthält die typischen Inhalte des Berufs, Abschnitt B die integrativen Inhalte wie Arbeitsrecht und Digitalisierung."}, {"q": "Wie viele Lernfelder hat der Rahmenlehrplan für Industriekaufleute?", "o": ["13", "10", "12", "15"], "c": 0, "e": "Der Rahmenlehrplan der KMK vom 15.12.2023 hat 13 Lernfelder mit zusammen 880 Stunden."}, {"q": "In welchem Lernfeld lernt Mia in der Berufsschule die Personalprozesse?", "o": ["Lernfeld 12 im 3. Jahr", "Lernfeld 1 im 1. Jahr", "Lernfeld 6 im 2. Jahr", "Lernfeld 13 im 3. Jahr"], "c": 0, "e": "Lernfeld 12 heißt Personalprozesse planen, steuern und kontrollieren. Es liegt im dritten Ausbildungsjahr und hat 80 Stunden."}, {"q": "Was ist ein Lernfeld?", "o": ["Ein Unterrichtsthema, das sich an einer beruflichen Aufgabe orientiert", "Ein Raum in der Berufsschule für Gruppenarbeit", "Ein Abschnitt im betrieblichen Ausbildungsplan", "Ein Prüfungsbereich der IHK-Abschlussprüfung"], "c": 0, "e": "Lernfelder ersetzen klassische Schulfächer. Gelernt wird an Aufgaben aus dem Beruf."}, {"q": "Wer erstellt den betrieblichen Ausbildungsplan für Mia?", "o": ["Nordstern als Ausbildungsbetrieb", "Die Berufsschule", "Die Kultusministerkonferenz", "Das Bundesinstitut für Berufsbildung"], "c": 0, "e": "Der Betrieb überträgt den Ausbildungsrahmenplan auf seine Abteilungen und Zeiten. Bei Nordstern macht das Aylin Demir."}, {"q": "Was beschreibt der Ausbildungsrahmenplan?", "o": ["Welche Inhalte wann vermittelt werden", "Welche Lehrkraft welches Lernfeld gibt", "Wie hoch die Vergütung jedes Jahr ist", "Welche Fragen in der Prüfung kommen"], "c": 0, "e": "Der Ausbildungsrahmenplan ist Teil der Ausbildungsordnung. Er gliedert die Inhalte sachlich und zeitlich."}, {"q": "Was ist der Ausbildungsnachweis?", "o": ["Ein Nachweis, den die Auszubildende über ihre Ausbildung führt", "Ein Zeugnis der IHK am Ende der Ausbildung", "Eine Bescheinigung über die Eintragung des Vertrags", "Ein Nachweis über die Zahlung der Vergütung"], "c": 0, "e": "Den Ausbildungsnachweis führt die Auszubildende selbst, früher hieß er Berichtsheft. Der Betrieb prüft ihn regelmäßig."}, {"q": "Was unterscheidet Ausbildende und Ausbilder?", "o": ["Ausbildende ist das Unternehmen, Ausbilder ist die Person, die ausbildet", "Ausbildende ist die Person, Ausbilder ist das Unternehmen", "Ausbildende und Ausbilder meinen immer die IHK", "Ausbildende sind die Lehrkräfte, Ausbilder die Eltern"], "c": 0, "e": "Ausbildende ist der Vertragspartner, hier Nordstern. Ausbilderin ist Aylin Demir, die tatsächlich ausbildet."}, {"q": "Mia ist 17 Jahre alt. Wer muss beim Abschluss ihres Ausbildungsvertrags zusätzlich zustimmen?", "o": ["Ihre Eltern als gesetzliche Vertreter", "Die Jugend- und Auszubildendenvertretung", "Die Berufsschule", "Die Agentur für Arbeit"], "c": 0, "e": "Minderjährige brauchen die Zustimmung ihrer gesetzlichen Vertreter. Ihre Namen stehen auch in der Niederschrift."}, {"q": "In welcher Form muss Nordstern den wesentlichen Vertragsinhalt seit dem 01.08.2024 mindestens niederlegen?", "o": ["In Textform", "Nur mündlich", "In notarieller Form", "Mit Stempel der IHK"], "c": 0, "e": "§ 11 BBiG verlangt seit dem 01.08.2024 die Textform. Ein PDF per E-Mail reicht, wenn der Empfang nachgewiesen wird."}, {"q": "Bis wann muss die Vertragsniederschrift spätestens vorliegen?", "o": ["Vor Beginn der Ausbildung", "Bis zum Ende der Probezeit", "Bis zur Zwischenprüfung", "Innerhalb von sechs Monaten"], "c": 0, "e": "Nach § 11 BBiG muss der Ausbildende unverzüglich nach Vertragsschluss, spätestens vor Beginn der Ausbildung, niederlegen."}, {"q": "Welche Angabe ist kein Mindestinhalt der Vertragsniederschrift?", "o": ["Religion der Auszubildenden", "Regelmäßige tägliche Ausbildungszeit", "Form des Ausbildungsnachweises", "Voraussetzungen der Kündigung"], "c": 0, "e": "Die Religion hat im Vertrag nichts zu suchen. Ausbildungszeit, Form des Nachweises und Kündigung sind Mindestinhalte."}, {"q": "Mias Niederschrift kam als PDF per E-Mail. Was muss Nordstern zusätzlich sicherstellen?", "o": ["Dass der Empfang nachgewiesen werden kann", "Dass die IHK das PDF unterschreibt", "Dass die Berufsschule eine Kopie stempelt", "Dass Mia das PDF ausdruckt und faxt"], "c": 0, "e": "Bei elektronischer Übermittlung muss der Empfang nachweisbar sein. Mia bestätigt den Empfang nach § 13 BBiG."}, {"q": "Was zeigt ein Organigramm?", "o": ["Die Aufbauorganisation mit Abteilungen und Unterstellungen", "Den zeitlichen Ablauf der Ausbildung", "Die Monatsgehälter aller Beschäftigten", "Die Reihenfolge der Arbeitsschritte in der Montage"], "c": 0, "e": "Ein Organigramm stellt die Aufbauorganisation als Baum dar. Es zeigt Bereiche, Abteilungen und Stellen und wer wem unterstellt ist."}, {"q": "Wer beantragt die Eintragung von Mias Vertrag in das Verzeichnis der Berufsausbildungsverhältnisse?", "o": ["Nordstern als Ausbildender", "Mia selbst", "Die Berufsschule", "Der Betriebsrat"], "c": 0, "e": "Nach § 36 BBiG beantragt der Ausbildende unverzüglich die Eintragung und fügt die Niederschrift bei."}, {"q": "Welche zusätzliche Unterlage braucht die IHK bei einer jugendlichen Auszubildenden wie Mia?", "o": ["Bescheinigung über die Erstuntersuchung", "Polizeiliches Führungszeugnis der Eltern", "Nachweis über einen bestandenen Führerschein", "Abschlusszeugnis der Grundschule"], "c": 0, "e": "Bei Jugendlichen muss die Bescheinigung über die Erstuntersuchung nach § 32 JArbSchG vorliegen."}, {"q": "Welche Folge hat es für Mia, wenn ihr Vertrag aus ihrem Verschulden nicht eingetragen ist?", "o": ["Sie wird grundsätzlich nicht zur Prüfung zugelassen", "Sie erhält automatisch eine höhere Vergütung", "Ihre Probezeit verlängert sich auf sechs Monate", "Die Berufsschule darf sie nicht mehr unterrichten"], "c": 0, "e": "Die Eintragung ist nach § 43 Abs. 1 BBiG grundsätzlich Voraussetzung für die Zulassung zur Abschlussprüfung."}, {"q": "Wie lange darf die Probezeit in einer Berufsausbildung dauern?", "o": ["Mindestens 1 und höchstens 4 Monate", "Mindestens 3 und höchstens 6 Monate", "Genau 6 Monate wie im Arbeitsvertrag", "Höchstens 2 Wochen ab Beginn"], "c": 0, "e": "§ 20 BBiG schreibt eine Probezeit von mindestens einem und höchstens vier Monaten vor."}, {"q": "Mias Ausbildung begann am 01.08.2026 mit vier Monaten Probezeit. Wann endet die Probezeit?", "o": ["Am 30.11.2026", "Am 31.10.2026", "Am 31.01.2027", "Am 01.08.2027"], "c": 0, "e": "Vier Monate ab dem 01.08. umfassen August, September, Oktober und November. Die Probezeit endet am 30.11.2026."}, {"q": "Ein Vertragsentwurf sieht für eine Auszubildende sechs Monate Probezeit vor. Wie ist das zu bewerten?", "o": ["Unzulässig, höchstens vier Monate sind erlaubt", "Zulässig, so wie im normalen Arbeitsvertrag", "Zulässig, wenn die Eltern ausdrücklich zustimmen", "Zulässig, wenn die IHK es vorher genehmigt"], "c": 0, "e": "Sechs Monate sind im Arbeitsvertrag möglich, in der Ausbildung aber nicht. § 20 BBiG begrenzt auf vier Monate."}, {"q": "Was bedeutet nichtig bei einer Klausel im Ausbildungsvertrag?", "o": ["Die Klausel gilt nicht, der Rest bleibt wirksam", "Der gesamte Vertrag ist damit sofort beendet", "Die Klausel gilt nur während der Probezeit", "Die IHK muss die Klausel neu formulieren"], "c": 0, "e": "Eine nichtige Klausel hat keine Wirkung. Die Ausbildung läuft auf Grundlage des übrigen Vertrags weiter."}, {"q": "Ab wann darf Nordstern mit Mia wirksam vereinbaren, dass sie nach der Ausbildung bleibt? Die Ausbildung endet am 31.07.2029.", "o": ["Ab dem 01.02.2029", "Ab dem 01.08.2028", "Schon bei Vertragsschluss", "Erst nach dem 31.07.2029"], "c": 0, "e": "Eine Bindung ist nur in den letzten sechs Monaten der Ausbildung erlaubt. Sechs Monate vor dem 31.07.2029 ist der 01.02.2029."}, {"q": "In welchem Paragrafen stehen die Pflichten der Ausbildenden?", "o": ["§ 14 BBiG", "§ 13 BBiG", "§ 20 BBiG", "§ 5 BBiG"], "c": 0, "e": "§ 14 BBiG regelt die Pflichten der Ausbildenden, § 13 BBiG die Pflichten der Auszubildenden."}, {"q": "Wie nennt man die Pflichten der Auszubildenden zusammengefasst?", "o": ["Lernpflicht", "Fürsorgepflicht", "Ausbildungspflicht", "Meldepflicht"], "c": 0, "e": "Die Pflichten aus § 13 BBiG werden als Lernpflicht bezeichnet. Die Ausbildungspflicht trifft den Betrieb."}, {"q": "Leon soll seinen Ausbildungsnachweis abends zu Hause schreiben. Wie ist das zu beurteilen?", "o": ["Unzulässig, er führt ihn in der Ausbildungszeit", "Zulässig, der Nachweis ist reine Privatsache", "Zulässig, wenn er dafür Überstunden bezahlt bekommt", "Unzulässig, weil nur die IHK den Nachweis führt"], "c": 0, "e": "Nach § 14 Abs. 2 BBiG muss der Betrieb Gelegenheit geben, den Nachweis während der Ausbildungszeit zu führen."}, {"q": "Ein Abteilungsleiter bittet Leon, sein Privatauto zu waschen. Warum ist das unzulässig?", "o": ["Die Aufgabe dient nicht dem Ausbildungszweck", "Leon ist noch minderjährig", "Autowaschen ist körperlich zu schwer", "Der Betriebsrat hat nicht zugestimmt"], "c": 0, "e": "§ 14 Abs. 3 BBiG erlaubt nur Aufgaben, die dem Ausbildungszweck dienen. Leon ist 19 und damit volljährig."}, {"q": "Welche Voraussetzung gilt für eine Jugend- und Auszubildendenvertretung (JAV)?", "o": ["Mindestens fünf Jugendliche oder Azubis unter 25", "Mindestens fünfzig Beschäftigte im Unternehmen", "Mindestens ein Auszubildender über 25 Jahren", "Eine vorherige Genehmigung der IHK zu Lübeck"], "c": 0, "e": "§ 60 BetrVG verlangt in der Regel mindestens fünf jugendliche Beschäftigte oder Auszubildende unter 25 Jahren."}, {"q": "Wer vertritt die Interessen von Mia in der Berufsschule und im Betrieb?", "o": ["In der Schule die Schülervertretung, im Betrieb die JAV", "In der Schule die IHK, im Betrieb die Geschäftsführung", "In beiden Lernorten die Ausbildungsberatung der IHK", "In der Schule der Betriebsrat, im Betrieb das Land"], "c": 0, "e": "Jeder Lernort hat eine eigene Interessenvertretung. In der Berufsschule ist es die Schülervertretung, im Betrieb die Jugend- und Auszubildendenvertretung."}, {"q": "Warum gilt für Mia das Jugendarbeitsschutzgesetz, für Leon aber nicht?", "o": ["Mia ist unter 18, Leon ist volljährig", "Mia ist im 1. Jahr, Leon schon im 2. Jahr", "Mia ist kaufmännisch, Leon gewerblich tätig", "Mia arbeitet in Teilzeit, Leon in Vollzeit"], "c": 0, "e": "Das JArbSchG gilt für Jugendliche von 15 bis unter 18 Jahren. Leon ist 19, beide sind kaufmännische Azubis."}, {"q": "Welcher Vorteil spricht für das duale System im Vergleich zu einer rein schulischen Ausbildung?", "o": ["Theorie und Praxis werden von Anfang an verbunden", "Die Ausbildung endet ohne Abschlussprüfung", "Der Staat zahlt allen Auszubildenden die Vergütung", "Jeder Betrieb legt die Ausbildungsinhalte frei fest"], "c": 0, "e": "Im dualen System lernen Auszubildende im Betrieb an echten Aufträgen und in der Berufsschule die Theorie dazu. Inhalte und Prüfung sind bundesweit geregelt."}, {"q": "Welche Aussage zum Berufsausbildungsvertrag stimmt?", "o": ["Er ist formfrei, die Niederschrift ist Pflicht", "Er ist nur mit Unterschrift beim Notar gültig", "Er wird erst durch die Eintragung bei der IHK wirksam", "Er gilt nur, wenn die Berufsschule zustimmt"], "c": 0, "e": "Der Vertrag selbst ist formfrei. Der Ausbildende muss den Inhalt aber nach § 11 BBiG in Textform niederlegen."}, {"q": "Welche Inhalte stehen im Abschnitt B der Ausbildungsordnung für Industriekaufleute?", "o": ["Integrative Inhalte wie Arbeitsrecht", "Nur die Inhalte des Einsatzgebiets Personal", "Die Lernfelder der Berufsschule im Land", "Die Höhe der Ausbildungsvergütung je Jahr"], "c": 0, "e": "Abschnitt B enthält Inhalte, die in allen Bereichen mitlaufen, zum Beispiel Arbeitsrecht, Arbeitssicherheit, Nachhaltigkeit und Digitalisierung."}, {"q": "Bis wann muss Nordstern die Vergütung für den laufenden Monat spätestens zahlen?", "o": ["Am letzten Arbeitstag des Monats", "Am 15. des Folgemonats", "Am ersten Arbeitstag des Monats", "Am Ende des Ausbildungsjahres"], "c": 0, "e": "§ 18 BBiG verlangt die Zahlung spätestens am letzten Arbeitstag des laufenden Monats."}, {"q": "Gilt der gesetzliche Mindestlohn von 13,90 € je Stunde für Mia als Auszubildende?", "o": ["Nein, Auszubildende sind ausgenommen", "Ja, ab dem ersten Ausbildungstag", "Ja, aber erst ab dem 18. Geburtstag", "Nur für Überstunden in der Ausbildung"], "c": 0, "e": "§ 22 MiLoG nimmt die Vergütung von Auszubildenden aus. Für sie gilt die Mindestausbildungsvergütung nach dem BBiG."}, {"q": "Wie hoch ist die Mindestausbildungsvergütung im 1. Jahr bei Ausbildungsbeginn 2026?", "o": ["724 €", "682 €", "764 €", "854 €"], "c": 0, "e": "Für Ausbildungen mit Beginn 2026 gelten 724 € im ersten Jahr. 682 € galten für Beginn 2025, 764 € gelten für Beginn 2027."}, {"q": "Welches Jahr entscheidet darüber, welche Mindestausbildungsvergütung gilt?", "o": ["Das Jahr, in dem die Ausbildung beginnt", "Das aktuelle Kalenderjahr der Zahlung", "Das Jahr der Zwischenprüfung", "Das Geburtsjahr der Auszubildenden"], "c": 0, "e": "Die Werte gelten für den Jahrgang, der im jeweiligen Kalenderjahr beginnt, und bleiben bis zum Ende fest."}, {"q": "Wie hoch ist die Mindestvergütung im 2. Jahr für den Jahrgang 2026?", "o": ["854 €", "724 €", "902 €", "977 €"], "c": 0, "e": "724 € × 1,18 = 854,32 €, gerundet 854 €."}, {"q": "Mit welchem Faktor berechnet man den Mindestwert im 3. Ausbildungsjahr?", "o": ["Wert des 1. Jahres × 1,35", "Wert des 2. Jahres × 1,18", "Wert des 1. Jahres × 1,40", "Wert des 2. Jahres × 1,35"], "c": 0, "e": "Im dritten Jahr gilt ein Aufschlag von 35 % auf den Wert des ersten Jahres, nicht auf den Vorjahreswert."}, {"q": "Berechnen Sie die Mindestvergütung im 4. Jahr für den Jahrgang 2027 bei 764 € im 1. Jahr.", "o": ["1.070 €", "1.031 €", "1.014 €", "1.100 €"], "c": 0, "e": "764 € × 1,40 = 1.069,60 €, gerundet 1.070 €."}, {"q": "Um wie viel Euro liegt Mias Vergütung im 1. Jahr über dem Mindestwert für Beginn 2026?", "o": ["426 €", "366 €", "468 €", "323 €"], "c": 0, "e": "1.150 € − 724 € = 426 €."}, {"q": "Muss sich Mia bei Nichtübernahme spätestens drei Monate vor Ausbildungsende arbeitsuchend melden?", "o": ["Nein, für betriebliche Ausbildung gilt das nicht", "Ja, spätestens drei Monate vor dem Ausbildungsende", "Ja, aber erst am Tag nach der letzten Prüfung", "Nur wenn Nordstern dies vorher schriftlich verlangt"], "c": 0, "e": "§ 38 Abs. 1 SGB III nimmt betriebliche Ausbildungsverhältnisse von der Pflicht zur frühzeitigen Meldung aus. Eine frühe Meldung ist trotzdem sinnvoll."}, {"q": "Ab wann ist die Vergütung eines nicht tarifgebundenen Betriebs in der Regel nicht mehr angemessen?", "o": ["Wenn sie mehr als 20 % unter dem Branchentarif liegt", "Wenn sie mehr als 5 % unter dem Branchentarif liegt", "Wenn sie unter dem Mindestlohn je Stunde liegt", "Wenn sie geringer ist als im Vorjahr der Firma"], "c": 0, "e": "Nach § 17 BBiG ist eine Vergütung ohne Tarifbindung in der Regel unangemessen, wenn sie mehr als 20 % unter dem Branchentarif liegt (BIBB, 2026)."}, {"q": "Der Unterricht beginnt um 07:45 Uhr. Darf Mia vorher noch im Betrieb arbeiten?", "o": ["Nein, vor Unterricht vor 9 Uhr nicht", "Ja, wenn der Weg kurz genug ist", "Ja, bis 30 Minuten vor Schulbeginn", "Nur mit Zustimmung der Eltern"], "c": 0, "e": "Vor einem Unterricht, der vor 9 Uhr beginnt, darf der Betrieb nicht beschäftigen."}, {"q": "Wann ist ein Berufsschultag für den Rest des Tages frei?", "o": ["Bei mehr als fünf Unterrichtsstunden, einmal pro Woche", "Bei mehr als drei Unterrichtsstunden, jeden Tag", "Bei genau vier Unterrichtsstunden, zweimal pro Woche", "Nur in Blockwochen mit mindestens 40 Stunden"], "c": 0, "e": "Ein Tag mit mehr als fünf Unterrichtsstunden zu je 45 Minuten ist einmal pro Woche frei."}, {"q": "Mit wie vielen Stunden wird Mias langer Berufsschultag bei Nordstern angerechnet?", "o": ["7 Stunden", "8 Stunden", "6 Stunden", "5,25 Stunden"], "c": 0, "e": "Angerechnet wird die durchschnittliche tägliche Ausbildungszeit, 35 Stunden ÷ 5 Tage = 7 Stunden. Pauschal 8 Stunden gelten nicht mehr."}, {"q": "Mia hat am Donnerstag Unterricht von 08:00 bis 11:15 Uhr und 30 Minuten Weg zum Betrieb. Wie lange arbeitet sie danach noch bei 7 Stunden Ausbildungszeit?", "o": ["3,25 Stunden", "3,75 Stunden", "4,00 Stunden", "2,75 Stunden"], "c": 0, "e": "Angerechnet werden 3,25 Stunden Unterricht plus 0,5 Stunden Weg, also 3,75 Stunden. 7 − 3,75 = 3,25 Stunden im Betrieb."}, {"q": "Für welchen Tag vor der Abschlussprüfung muss Nordstern freistellen?", "o": ["Für den Arbeitstag vor der schriftlichen Prüfung", "Für die ganze Woche vor der schriftlichen Prüfung", "Für den Tag nach der mündlichen Prüfung", "Nur für den Prüfungstag selbst, sonst nichts"], "c": 0, "e": "Neben dem Prüfungstag ist auch der Arbeitstag unmittelbar vor der schriftlichen Abschlussprüfung frei."}, {"q": "Wie lange muss eine Blockwoche mindestens dauern, damit die ganze Woche frei ist?", "o": ["25 Stunden an mindestens 5 Tagen", "20 Stunden an mindestens 4 Tagen", "30 Stunden an mindestens 5 Tagen", "35 Stunden an mindestens 5 Tagen"], "c": 0, "e": "Bei Blockunterricht mit mindestens 25 Stunden an mindestens fünf Tagen ist die Woche frei. Bis zu zwei Stunden betriebliche Veranstaltungen sind erlaubt."}, {"q": "Wonach richtet sich der Mindesturlaub von Jugendlichen?", "o": ["Nach dem Alter zu Beginn des Jahres", "Nach dem Alter am ersten Urlaubstag", "Nach dem aktuellen Ausbildungsjahr", "Nach der Zahl der Berufsschultage"], "c": 0, "e": "§ 19 JArbSchG stellt auf das Alter zu Beginn des Kalenderjahres ab."}, {"q": "Wie viele Werktage Urlaub stehen einer Jugendlichen zu, die am 1. Januar noch nicht 17 Jahre alt ist?", "o": ["27 Werktage", "30 Werktage", "25 Werktage", "24 Werktage"], "c": 0, "e": "Noch nicht 16 Jahre 30, noch nicht 17 Jahre 27, noch nicht 18 Jahre 25 Werktage."}, {"q": "Wie viele Werktage Urlaub hat Mia für 2026, wenn sie am 01.08.2026 begonnen hat?", "o": ["11,25 Werktage", "27 Werktage", "12,50 Werktage", "10,42 Werktage"], "c": 0, "e": "Mia erfüllt die Wartezeit 2026 nicht und erhält fünf Zwölftel von 27 Werktagen, 27 × 5 ÷ 12 = 11,25 Werktage."}, {"q": "Was gilt, wenn Mia während ihres Urlaubs die Berufsschule besucht?", "o": ["Sie bekommt einen weiteren Urlaubstag", "Der Schultag verfällt ganz ersatzlos", "Der Urlaub wird um eine Woche gekürzt", "Sie muss den Schultag später nacharbeiten"], "c": 0, "e": "Nach § 19 Abs. 3 JArbSchG gibt es für jeden Berufsschultag im Urlaub einen weiteren Urlaubstag."}, {"q": "Wie rechnet man Werktage bei einer Fünf-Tage-Woche in Arbeitstage um?", "o": ["Werktage ÷ 6 × 5", "Werktage ÷ 5 × 6", "Werktage × 5 ÷ 7", "Werktage − 6"], "c": 0, "e": "Werktage sind Montag bis Samstag. Bei fünf Arbeitstagen teilt man durch 6 und multipliziert mit 5."}, {"q": "Am Freitag beginnt Mias Unterricht um 07:45 Uhr. Bis wann darf sie am Donnerstag in der Spätschicht höchstens arbeiten?", "o": ["Bis 20 Uhr", "Bis 23 Uhr", "Bis 22 Uhr", "Bis 21 Uhr"], "c": 0, "e": "Vor einem Berufsschultag mit Beginn vor 9 Uhr dürfen Jugendliche auch in mehrschichtigen Betrieben nicht nach 20 Uhr arbeiten (§ 14 Abs. 4 JArbSchG)."}, {"q": "Welche tägliche Ruhezeit gilt für Leon mit 19 Jahren nach Feierabend?", "o": ["11 Stunden nach § 5 ArbZG", "12 Stunden nach dem JArbSchG", "8 Stunden nach dem BBiG", "10 Stunden nach dem BUrlG"], "c": 0, "e": "Für Erwachsene gilt eine ununterbrochene Ruhezeit von 11 Stunden. Die 12 Stunden des JArbSchG gelten nur für Jugendliche wie Mia."}, {"q": "Wie kann Nordstern einem Auszubildenden nach der Probezeit kündigen?", "o": ["Nur fristlos aus wichtigem Grund", "Ordentlich mit vier Wochen Frist", "Ordentlich zum Ende des Ausbildungsjahres", "Jederzeit ohne Grund mit zwei Wochen Frist"], "c": 0, "e": "Nach § 22 Abs. 2 BBiG bleibt dem Betrieb nach der Probezeit nur die Kündigung aus wichtigem Grund ohne Frist."}, {"q": "Leon will nach der Probezeit die Ausbildung aufgeben und Fachinformatiker lernen. Welche Kündigungsfrist gilt für ihn?", "o": ["Vier Wochen", "Zwei Wochen", "Drei Monate", "Keine Frist"], "c": 0, "e": "Auszubildende können mit vier Wochen Frist kündigen, wenn sie die Ausbildung aufgeben oder einen anderen Beruf lernen wollen."}, {"q": "Mia schreibt am 25.11.2026 per WhatsApp, dass sie aufhört. Ist das eine wirksame Kündigung?", "o": ["Nein, die Schriftform fehlt", "Ja, in der Probezeit reicht jede Form", "Ja, wenn Nordstern die Nachricht liest", "Ja, weil sie noch minderjährig ist"], "c": 0, "e": "Auch in der Probezeit muss die Kündigung schriftlich sein. Eine Nachricht per Messenger erfüllt die Schriftform nicht."}, {"q": "Innerhalb welcher Frist muss ein wichtiger Grund für eine Kündigung genutzt werden?", "o": ["Innerhalb von zwei Wochen nach Kenntnis", "Innerhalb von vier Wochen nach Kenntnis", "Innerhalb von drei Monaten nach dem Vorfall", "Bis zum Ende des Ausbildungsjahres"], "c": 0, "e": "§ 22 Abs. 4 BBiG macht die Kündigung unwirksam, wenn die Tatsachen länger als zwei Wochen bekannt sind."}, {"q": "Nordstern erfährt am 02.03.2027 von einem Diebstahl durch einen Auszubildenden. Bis wann muss die Kündigung spätestens erfolgen?", "o": ["Bis zum 16.03.2027", "Bis zum 30.03.2027", "Bis zum 09.03.2027", "Bis zum 02.06.2027"], "c": 0, "e": "Zwei Wochen nach dem 02.03.2027 ist der 16.03.2027."}, {"q": "Wem muss die Kündigung bei einer minderjährigen Auszubildenden wie Mia zugehen?", "o": ["Den Eltern als gesetzlichen Vertretern", "Der Berufsschule", "Der IHK zu Lübeck", "Der Jugend- und Auszubildendenvertretung"], "c": 0, "e": "Bei Minderjährigen wird die Kündigung erst wirksam, wenn sie den gesetzlichen Vertretern zugeht."}, {"q": "Wen muss Nordstern vor jeder Kündigung eines Auszubildenden anhören?", "o": ["Den Betriebsrat", "Die Agentur für Arbeit", "Die Berufsschule", "Den Prüfungsausschuss"], "c": 0, "e": "§ 102 BetrVG verlangt die Anhörung des Betriebsrats vor jeder Kündigung. Ohne Anhörung ist sie unwirksam."}, {"q": "Wann endet ein Ausbildungsverhältnis, wenn die Prüfung vor Ablauf der Ausbildungszeit bestanden wird?", "o": ["Mit Bekanntgabe des Ergebnisses durch den Prüfungsausschuss", "Mit Zugang des schriftlichen Zeugnisses per Post", "Immer erst mit dem vereinbarten Vertragsende", "Am letzten Tag des Monats nach der Prüfung"], "c": 0, "e": "§ 21 Abs. 2 BBiG lässt die Ausbildung mit der Bekanntgabe des Ergebnisses durch den Prüfungsausschuss enden."}, {"q": "Wie oft kann die Abschlussprüfung wiederholt werden?", "o": ["Zweimal", "Einmal", "Dreimal", "Beliebig oft"], "c": 0, "e": "Die Abschlussprüfung kann zweimal wiederholt werden."}, {"q": "Was bedeutet gestreckte Abschlussprüfung?", "o": ["Zwei zeitlich getrennte Teile zählen zusammen", "Eine Prüfung über mehrere Tage am Stück", "Eine Zwischenprüfung ohne Bewertung", "Eine Prüfung nur in der Berufsschule"], "c": 0, "e": "Bei der gestreckten Prüfung gehen Teil 1 und Teil 2 beide in das Gesamtergebnis ein."}, {"q": "Wann soll Teil 1 der Abschlussprüfung für Industriekaufleute stattfinden?", "o": ["Im vierten Ausbildungshalbjahr", "Am Ende des ersten Jahres", "Im letzten Ausbildungsmonat", "Direkt nach der Probezeit"], "c": 0, "e": "Teil 1 soll im vierten Ausbildungshalbjahr stattfinden, bei Mia also etwa im Frühjahr 2028."}, {"q": "Mit welchem Gewicht zählt der schriftliche Bereich mit Personalwesen in Teil 2?", "o": ["35 %", "25 %", "30 %", "10 %"], "c": 0, "e": "Marketing, Vertrieb, Personalwesen sowie kaufmännische Steuerung und Kontrolle zählen 35 %. Teil 1 zählt 25 %, die Fachaufgabe 30 %, WiSo 10 %."}, {"q": "Die Lagerleitung plant Mia für eine Inventur am Samstag ein. Ist das zulässig?", "o": ["Nein, für die Industrie gilt keine Ausnahme", "Ja, wenn sie dafür montags frei bekommt", "Ja, eine Inventur ist immer erlaubt", "Ja, bis zu vier Stunden ohne Ausgleich"], "c": 0, "e": "Jugendliche dürfen samstags grundsätzlich nicht arbeiten (§ 16 JArbSchG). Die Ausnahmen betreffen Branchen wie Gastronomie oder Krankenhäuser, nicht die Industrie."}, {"q": "Mia arbeitet nach der bestandenen Prüfung ohne ausdrückliche Vereinbarung weiter. Was gilt nach § 24 BBiG?", "o": ["Ein unbefristetes Arbeitsverhältnis gilt als begründet", "Ein befristetes Arbeitsverhältnis für ein Jahr entsteht", "Die Ausbildung verlängert sich um sechs Monate", "Es entsteht ein Praktikum ohne Vergütung"], "c": 0, "e": "Wer ohne ausdrückliche Vereinbarung weiterbeschäftigt wird, hat ein Arbeitsverhältnis auf unbestimmte Zeit."}, {"q": "Ab wann darf ein 17-jähriger Auszubildender in einer Bäckerei morgens frühestens arbeiten?", "o": ["Ab 4 Uhr", "Ab 6 Uhr wie alle Jugendlichen", "Ab 5 Uhr wie 16-Jährige", "Ab 3 Uhr mit Zustimmung der Eltern"], "c": 0, "e": "Grundsätzlich gilt für Jugendliche die Nachtruhe von 20 bis 6 Uhr. In Bäckereien dürfen über 16-Jährige ab 5 Uhr und über 17-Jährige ab 4 Uhr arbeiten (§ 14 JArbSchG)."}, {"q": "Für wen gilt das Jugendarbeitsschutzgesetz?", "o": ["Für Personen von 15 bis unter 18 Jahren", "Für alle Auszubildenden unter 25 Jahren", "Für alle Beschäftigten im ersten Berufsjahr", "Nur für Schülerinnen und Schüler im Ferienjob"], "c": 0, "e": "Jugendliche sind nach § 2 Abs. 2 JArbSchG Personen, die 15, aber noch nicht 18 Jahre alt sind."}, {"q": "Mia arbeitet 7 Stunden am Tag. Wie lang müssen ihre Pausen insgesamt mindestens sein?", "o": ["60 Minuten", "30 Minuten", "45 Minuten", "15 Minuten"], "c": 0, "e": "Bei mehr als sechs Stunden Arbeitszeit stehen Jugendlichen nach § 11 JArbSchG mindestens 60 Minuten Pause zu."}, {"q": "Mia hat um 16:00 Uhr Feierabend. Wann darf sie frühestens am nächsten Tag wieder arbeiten?", "o": ["Um 04:00 Uhr, wegen 12 Stunden Ruhezeit", "Um 06:00 Uhr, wegen der Nachtruhe", "Um 03:00 Uhr, wegen 11 Stunden Ruhezeit", "Um 08:00 Uhr, wegen 16 Stunden Ruhezeit"], "c": 1, "e": "Die Ruhezeit von 12 Stunden würde bis 04:00 Uhr reichen. Wegen der Nachtruhe von 20 bis 6 Uhr darf Mia aber erst ab 06:00 Uhr arbeiten."}, {"q": "Bis wie viel Uhr darf Mia mit 17 Jahren in der Spätschicht von Nordstern höchstens arbeiten?", "o": ["Bis 23 Uhr, weil Nordstern mehrschichtig arbeitet", "Bis 20 Uhr, ohne jede Ausnahme", "Bis 22 Uhr, wie in Gaststätten", "Bis 24 Uhr, mit Zustimmung der Eltern"], "c": 0, "e": "Über 16-Jährige dürfen in mehrschichtigen Betrieben bis 23 Uhr arbeiten. Vor einem Schultag mit Beginn vor 9 Uhr gilt aber 20 Uhr."}, {"q": "Was ist ein Lernort im Sinne der Berufsausbildung?", "o": ["Ein Ort, an dem die Auszubildende ihren Beruf lernt", "Die Wohnung, in der die Auszubildende während der Ausbildung lebt", "Das Büro der IHK, in dem die Verträge eingetragen werden", "Der Raum, in dem nur die Abschlussprüfung stattfindet"], "c": 0, "e": "Ein Lernort ist der Ort, an dem gelernt wird. Im dualen System sind das der Ausbildungsbetrieb und die Berufsschule."}, {"q": "Wer ist in Deutschland für die Berufsschulen verantwortlich?", "o": ["Die Länder", "Der Bund", "Die Industrie- und Handelskammern", "Die Arbeitgeberverbände"], "c": 0, "e": "Die Länder sind für die Berufsschulen verantwortlich und stimmen sich in der Kultusministerkonferenz ab. Der Bund erlässt die Ausbildungsordnungen."}, {"q": "Was versteht man unter dem Ausbildungsberufsbild?", "o": ["Eine kurze Liste der Fertigkeiten, Kenntnisse und Fähigkeiten des Berufs", "Ein Foto der Auszubildenden für die Unterlagen der IHK", "Eine Übersicht, in welcher Abteilung Mia wann eingesetzt wird", "Eine Tabelle mit den Noten aus der Berufsschule"], "c": 0, "e": "Das Ausbildungsberufsbild ist Teil der Ausbildungsordnung und zählt auf, was im Beruf gelernt wird. Die Übersicht der Abteilungen ist der betriebliche Ausbildungsplan."}, {"q": "Welche Rechtsform hat eine Ausbildungsordnung?", "o": ["Rechtsverordnung des Bundes", "Gesetz eines Bundeslandes", "Satzung der zuständigen IHK", "Tarifvertrag der Sozialpartner"], "c": 0, "e": "Ausbildungsordnungen sind Rechtsverordnungen des Bundes. Sie gelten in ganz Deutschland gleich."}, {"q": "Wie wird die neue Ausbildungsordnung für Industriekaufleute abgekürzt?", "o": ["IndKflAusbV", "BBiG", "JArbSchG", "BUrlG"], "c": 0, "e": "Die Industriekaufleuteausbildungsverordnung heißt kurz IndKflAusbV. BBiG, JArbSchG und BUrlG sind Gesetze mit allgemeinen Regeln."}, {"q": "Was trat am 01.08.2024 außer Kraft, als die neue Ausbildungsordnung für Industriekaufleute begann?", "o": ["Die alte Ausbildungsordnung von 2002", "Das Berufsbildungsgesetz", "Der Rahmenlehrplan vom 15.12.2023", "Das Jugendarbeitsschutzgesetz"], "c": 0, "e": "Mit der neuen IndKflAusbV trat die Verordnung von 2002 am selben Tag außer Kraft. BBiG und JArbSchG gelten weiter."}, {"q": "Wie viele Stunden umfasst der Rahmenlehrplan für Industriekaufleute insgesamt?", "o": ["880 Stunden", "80 Stunden", "1.320 Stunden", "600 Stunden"], "c": 0, "e": "Der Rahmenlehrplan hat 13 Lernfelder mit zusammen 880 Stunden (KMK, 2023). 80 Stunden hat allein Lernfeld 12."}, {"q": "Wie lautet der Titel von Lernfeld 12 im Rahmenlehrplan für Industriekaufleute?", "o": ["Personalprozesse planen, steuern und kontrollieren", "Personal beschaffen, einstellen und entlohnen", "Mitarbeitende führen, motivieren und beurteilen", "Entgelte abrechnen, buchen und auswerten"], "c": 0, "e": "Lernfeld 12 heißt Personalprozesse planen, steuern und kontrollieren und umfasst 80 Stunden im dritten Ausbildungsjahr (KMK, 2023)."}, {"q": "Wer ist nach dem BBiG für Ausbildungsberufe aus Industrie und Handel die zuständige Stelle?", "o": ["Die Industrie- und Handelskammer", "Die Handwerkskammer", "Die Agentur für Arbeit", "Das Kultusministerium des Landes"], "c": 0, "e": "Für Berufe aus Industrie und Handel sind die Industrie- und Handelskammern zuständig (§ 71 BBiG)."}, {"q": "Warum ist gerade die IHK zu Lübeck für die Ausbildung bei Nordstern zuständig?", "o": ["Nordstern sitzt in Norderstedt im Kreis Segeberg", "Mias Berufsschule liegt in der Stadt Lübeck", "Nordstern gehört zum Tarifgebiet Küste", "Die Geschäftsführerin wohnt in Lübeck"], "c": 0, "e": "Zuständig ist die IHK, in deren Bezirk der Betrieb liegt. Norderstedt im Kreis Segeberg gehört zur IHK zu Lübeck (IHK zu Lübeck, o. J.)."}, {"q": "Wer besucht im Auftrag der IHK die Betriebe und berät bei Fragen zur Ausbildung?", "o": ["Ausbildungsberaterinnen und Ausbildungsberater", "Die Mitglieder der Prüfungsausschüsse", "Die Lehrkräfte der Berufsschule", "Die Mitglieder des Betriebsrats"], "c": 0, "e": "Für Beratung und Überwachung setzt die IHK Ausbildungsberaterinnen und Ausbildungsberater ein (§ 76 BBiG)."}, {"q": "Was bedeutet Textform?", "o": ["Eine lesbare Erklärung ohne eigenhändige Unterschrift", "Eine Erklärung mit eigenhändiger Unterschrift auf Papier", "Eine mündliche Erklärung vor zwei Zeugen", "Eine Erklärung, die ein Notar beurkundet"], "c": 0, "e": "Textform heißt lesbar, aber ohne eigenhändige Unterschrift, zum Beispiel ein PDF per E-Mail. Für die Niederschrift reicht seit dem 01.08.2024 die Textform (§ 11 BBiG)."}, {"q": "Welche Angabe zur Ausbildungszeit gehört in die Niederschrift?", "o": ["Die regelmäßige tägliche Ausbildungszeit", "Die Uhrzeit des Arbeitsbeginns an jedem Tag", "Die geplanten Überstunden für das ganze Jahr", "Die Fahrzeit von der Wohnung zum Betrieb"], "c": 0, "e": "§ 11 BBiG verlangt die regelmäßige tägliche Ausbildungszeit, bei Mia 7 Stunden. Genaue Uhrzeiten oder Fahrzeiten gehören nicht dazu."}, {"q": "Welche Regeln gelten nach § 10 BBiG für den Ausbildungsvertrag, soweit das BBiG nichts anderes sagt?", "o": ["Die Regeln für den Arbeitsvertrag", "Nur die Regeln des Jugendarbeitsschutzes", "Die Regeln für einen Kaufvertrag", "Die Schulordnung der Berufsschule"], "c": 0, "e": "Für den Berufsausbildungsvertrag gilt das Arbeitsvertragsrecht, soweit das BBiG keine eigene Regel enthält (§ 10 BBiG)."}, {"q": "Was ist das Verzeichnis der Berufsausbildungsverhältnisse?", "o": ["Eine Liste der IHK, in der alle Ausbildungsverträge stehen", "Ein Ordner im Betrieb mit allen Ausbildungsnachweisen", "Eine Liste der Berufsschule mit allen Klassen", "Ein Register der Agentur für Arbeit mit freien Stellen"], "c": 0, "e": "Die IHK führt das Verzeichnis und trägt jeden Ausbildungsvertrag ein (§ 34 BBiG). Ohne Eintragung gibt es grundsätzlich keine Prüfungszulassung."}, {"q": "Wie unterscheidet sich die Probezeit im Arbeitsvertrag von der in der Ausbildung?", "o": ["Im Arbeitsvertrag bis sechs Monate, in der Ausbildung höchstens vier", "In der Ausbildung bis sechs Monate, im Arbeitsvertrag höchstens vier", "Für Arbeitsvertrag und Ausbildung gelten genau vier Monate", "Im Arbeitsvertrag gibt es grundsätzlich gar keine Probezeit"], "c": 0, "e": "Die Probezeit in der Ausbildung dauert 1 bis 4 Monate (§ 20 BBiG), im Arbeitsvertrag sind bis zu sechs Monate möglich. Das wird in Prüfungen oft verwechselt."}, {"q": "Was sind Ausbildungsmittel?", "o": ["Werkzeuge, Fachliteratur und Geräte, die man für die Ausbildung braucht", "Die monatliche Ausbildungsvergütung für die Auszubildende", "Zuschüsse der Agentur für Arbeit an den Ausbildungsbetrieb", "Die Lehrkräfte, die an der Berufsschule unterrichten"], "c": 0, "e": "Ausbildungsmittel sind Sachen wie Werkzeuge, Fachbücher oder ein Laptop für das mobile Ausbilden. Der Ausbildende stellt sie kostenlos (§ 14 Abs. 1 BBiG)."}, {"q": "Worauf achtet der Betriebsrat bei Nordstern in der Ausbildung vor allem?", "o": ["Dass Gesetze und Tarifverträge eingehalten werden", "Dass alle Verträge bei der IHK eingetragen werden", "Dass die Abschlussprüfung korrekt bewertet wird", "Dass die Berufsschule den Lehrplan einhält"], "c": 0, "e": "Der Betriebsrat überwacht, dass Gesetze und Tarifverträge im Betrieb eingehalten werden. Eintragung und Prüfung sind Aufgaben der IHK."}, {"q": "Wer ist bei Nordstern als Ausbildungsleiterin für die Auszubildenden zuständig?", "o": ["Aylin Demir", "Malte Brandt", "Petra Holm", "Sven Krüger"], "c": 0, "e": "Aylin Demir leitet die Ausbildung. Malte Brandt ist Personalleiter, Petra Holm Betriebsratsvorsitzende, Sven Krüger macht die Entgeltabrechnung."}, {"q": "Welchen Zweck hat die Ausbildungsvergütung?", "o": ["Sie unterstützt die Ausbildung finanziell und erkennt die Leistung an", "Sie ist ein Lohn genau für jede geleistete Arbeitsstunde", "Sie ist ein Zuschuss des Staates an die Auszubildenden", "Sie ersetzt das Kindergeld der Eltern vollständig"], "c": 0, "e": "Die Vergütung ist kein Lohn im engeren Sinn. Sie unterstützt die Ausbildung finanziell und erkennt die Leistung im Betrieb an (§ 17 BBiG)."}, {"q": "Seit wann gibt es in Deutschland eine gesetzliche Mindestausbildungsvergütung?", "o": ["Seit 2020", "Seit 2015", "Seit 2024", "Seit 2026"], "c": 0, "e": "Die Untergrenze für die Ausbildungsvergütung gibt es seit 2020. Der Betrag für das erste Jahr wird jedes Jahr fortgeschrieben."}, {"q": "Leon hat 2025 angefangen. Welcher gesetzliche Mindestbetrag galt für sein erstes Ausbildungsjahr?", "o": ["682 €", "724 €", "764 €", "649 €"], "c": 0, "e": "Für Ausbildungen mit Beginn 2025 lag der Wert bei 682 € (BIBB, 2026). 724 € gelten für Beginn 2026, 764 € für Beginn 2027."}, {"q": "Wann gilt eine tarifliche Ausbildungsvergütung als angemessen?", "o": ["Immer, auch wenn sie unter der Mindestvergütung liegt", "Nur wenn sie mindestens den Mindestlohn erreicht", "Nur wenn die IHK sie ausdrücklich genehmigt", "Nur im ersten und zweiten Ausbildungsjahr"], "c": 0, "e": "Eine Vergütung nach Tarifvertrag gilt immer als angemessen, selbst unter der Mindestausbildungsvergütung. Ohne Tarif gilt die 20 %-Grenze."}, {"q": "Wie viel der Bruttovergütung dürfen Sachleistungen wie Kost und Wohnung höchstens ausmachen?", "o": ["75 %", "25 %", "50 %", "100 %"], "c": 0, "e": "Sachleistungen dürfen höchstens 75 % der Bruttovergütung ausmachen. Mindestens ein Viertel wird also in Geld gezahlt."}, {"q": "Welche Vorschrift nimmt Auszubildende vom gesetzlichen Mindestlohn aus?", "o": ["§ 22 MiLoG", "§ 17 BBiG", "§ 3 BUrlG", "§ 8 JArbSchG"], "c": 0, "e": "§ 22 MiLoG nimmt Auszubildende aus. Für sie gilt stattdessen die Mindestausbildungsvergütung nach § 17 BBiG."}, {"q": "Was ist mit Blockunterricht gemeint?", "o": ["Unterricht über mehrere Wochen am Stück statt an einzelnen Tagen", "Unterricht nur in einem einzigen Fach über das ganze Jahr", "Unterricht, der ausschließlich am Samstag stattfindet", "Unterricht, den der Betrieb im eigenen Schulungsraum gibt"], "c": 0, "e": "Berufsschule findet an einzelnen Tagen pro Woche oder als Blockunterricht über mehrere Wochen statt. Eine Blockwoche mit mindestens 25 Stunden an fünf Tagen ist ganz frei."}, {"q": "Was sind Werktage im Urlaubsrecht?", "o": ["Alle Tage außer Sonn- und Feiertagen", "Nur die Tage von Montag bis Freitag", "Alle Kalendertage einschließlich Sonntag", "Nur die Tage mit Berufsschulunterricht"], "c": 0, "e": "Werktage sind Montag bis Samstag ohne Feiertage. Bei einer Fünf-Tage-Woche rechnet man sie in Arbeitstage um."}, {"q": "Wann entsteht der volle Urlaubsanspruch nach dem Bundesurlaubsgesetz zum ersten Mal?", "o": ["Nach sechs Monaten Beschäftigung", "Direkt am ersten Arbeitstag", "Nach drei Monaten Beschäftigung", "Erst nach einem vollen Kalenderjahr"], "c": 0, "e": "Der volle Anspruch entsteht nach einer Wartezeit von sechs Monaten (§ 4 BUrlG). Das gilt auch für Jugendliche, weil das JArbSchG insoweit auf das BUrlG verweist."}, {"q": "Was gilt nach § 5 Abs. 1 BUrlG, solange die Wartezeit noch nicht erfüllt ist?", "o": ["Für jeden vollen Monat gibt es ein Zwölftel des Jahresurlaubs", "Es gibt bis zum Ende der Wartezeit überhaupt keinen Urlaub", "Es gibt pauschal die Hälfte des Jahresurlaubs", "Es gibt sofort den vollen Jahresurlaub"], "c": 0, "e": "Vor Erfüllung der Wartezeit gibt es Teilurlaub, ein Zwölftel für jeden vollen Monat (§ 5 Abs. 1 BUrlG)."}, {"q": "Wann sollen Jugendliche ihren Urlaub nach dem Jugendarbeitsschutzgesetz möglichst nehmen?", "o": ["In den Berufsschulferien", "Während der Probezeit", "Immer im Dezember", "Kurz vor der Prüfung"], "c": 0, "e": "Der Urlaub von Jugendlichen soll in den Berufsschulferien liegen (§ 19 JArbSchG). So fällt kein Unterricht aus."}, {"q": "Wann liegt ein wichtiger Grund für eine Kündigung der Ausbildung vor?", "o": ["Wenn die Fortsetzung bis zum Ende nicht zumutbar ist", "Wenn der Betrieb irgendeinen Grund schriftlich nennt", "Wenn die IHK die Kündigung vorher genehmigt hat", "Wenn die Auszubildende einmal schlecht gelaunt war"], "c": 0, "e": "Ein wichtiger Grund liegt vor, wenn es nicht mehr zumutbar ist, die Ausbildung bis zum Ende fortzusetzen (§ 22 BBiG)."}, {"q": "Welches mildere Mittel setzt ein Betrieb vor einer Kündigung wegen Fehlverhaltens in der Regel ein?", "o": ["Eine Abmahnung", "Eine Verlängerung der Probezeit", "Eine Kürzung der Vergütung", "Eine Streichung des Urlaubs"], "c": 0, "e": "Bei Fehlverhalten wie Zuspätkommen mahnt der Betrieb meist zuerst ab. Erst bei erneutem Fehlverhalten kommt eine Kündigung aus wichtigem Grund in Betracht."}, {"q": "Wie lange dauert eine mündliche Ergänzungsprüfung bei Industriekaufleuten?", "o": ["15 Minuten", "30 Minuten", "60 Minuten", "5 Minuten"], "c": 0, "e": "Die mündliche Ergänzungsprüfung dauert 15 Minuten (IndKflAusbV). Die 30 Minuten gelten für die Fachaufgabe im Einsatzgebiet."}, {"q": "Was prüft die IHK im ersten Teil der gestreckten Prüfung bei Industriekaufleuten?", "o": ["Leistungserstellung, Logistik, Beschaffung und Buchhaltung", "Marketing, Vertrieb, Personalwesen und kaufmännische Steuerung", "Fachaufgabe im Einsatzgebiet mit Fachgespräch", "Wirtschafts- und Sozialkunde mit 60 Minuten"], "c": 0, "e": "Teil 1 prüft schriftlich Leistungserstellung, Logistik, Beschaffung und Buchhaltung in 90 Minuten (IndKflAusbV). Die anderen Bereiche gehören zu Teil 2."}, {"q": "Mit wie viel Prozent geht Teil 1 der Abschlussprüfung für Industriekaufleute in das Gesamtergebnis ein?", "o": ["25 %", "35 %", "10 %", "50 %"], "c": 0, "e": "Teil 1 zählt 25 %. In Teil 2 zählen der schriftliche Bereich 35 %, die Fachaufgabe 30 % und Wirtschafts- und Sozialkunde 10 %."}, {"q": "Wie lange dauert der Prüfungsbereich Wirtschafts- und Sozialkunde?", "o": ["60 Minuten", "90 Minuten", "150 Minuten", "30 Minuten"], "c": 0, "e": "Wirtschafts- und Sozialkunde wird 60 Minuten schriftlich geprüft. 90 Minuten dauert Teil 1, 150 Minuten der schriftliche Bereich mit Personalwesen."}, {"q": "Wann darf Nordstern das Ausbildungszeugnis elektronisch ausstellen?", "o": ["Nur mit Einwilligung der Auszubildenden", "Immer, weil Textform ausreicht", "Nie, nur auf Papier ist erlaubt", "Nur mit Erlaubnis der IHK"], "c": 0, "e": "Das Zeugnis wird schriftlich ausgestellt, elektronisch nur mit Einwilligung der Auszubildenden (§ 16 BBiG)."}, {"q": "Welches Gesetz regelt die Arbeitszeit von Leon Becker mit 19 Jahren?", "o": ["Das Arbeitszeitgesetz", "Das Jugendarbeitsschutzgesetz", "Das Bundesurlaubsgesetz", "Das Mindestlohngesetz"], "c": 0, "e": "Für Volljährige gilt das Arbeitszeitgesetz, zum Beispiel mit 8 Stunden werktäglich (§ 3 ArbZG). Das JArbSchG gilt nur für Jugendliche."}, {"q": "Welche Zeit gilt für Jugendliche nach § 14 JArbSchG grundsätzlich als Nachtruhe?", "o": ["20 bis 6 Uhr", "22 bis 5 Uhr", "23 bis 6 Uhr", "18 bis 8 Uhr"], "c": 0, "e": "Jugendliche dürfen grundsätzlich nur von 6 bis 20 Uhr beschäftigt werden. Ausnahmen gibt es ab 16 Jahren, etwa in mehrschichtigen Betrieben bis 23 Uhr."}, {"q": "An wie vielen Tagen pro Woche dürfen Jugendliche nach § 15 JArbSchG beschäftigt werden?", "o": ["An fünf Tagen", "An sechs Tagen", "An vier Tagen", "An sieben Tagen"], "c": 0, "e": "Für Jugendliche gilt die Fünf-Tage-Woche (§ 15 JArbSchG). Die beiden Ruhetage sollen möglichst hintereinander liegen."}, {"q": "Wann soll Nordstern eine jugendliche Auszubildende an die erste Nachuntersuchung erinnern?", "o": ["Nach neun Monaten Beschäftigung", "Nach drei Monaten Beschäftigung", "Nach zwölf Monaten Beschäftigung", "Nach 14 Monaten Beschäftigung"], "c": 0, "e": "Der Arbeitgeber soll nach neun Monaten an die Nachuntersuchung erinnern. Die Bescheinigung muss nach einem Jahr vorliegen (§ 33 JArbSchG)."}, {"q": "Wie alt darf die Untersuchung für die Bescheinigung über die erste Nachuntersuchung höchstens sein?", "o": ["Drei Monate", "14 Monate", "Ein Jahr", "Sechs Wochen"], "c": 0, "e": "Die Nachuntersuchung darf höchstens drei Monate zurückliegen (§ 33 JArbSchG). Die 14 Monate gelten für die Erstuntersuchung."}, {"q": "Was ist möglich, wenn eine neue Auszubildende zum Beispiel das Abitur hat?", "o": ["Die Ausbildungszeit kann auf Antrag verkürzt werden", "Die Ausbildung entfällt und sie macht nur die Prüfung", "Die Probezeit darf dann sechs Monate betragen", "Die Berufsschule ist für sie freiwillig"], "c": 0, "e": "Auf gemeinsamen Antrag kann die Ausbildungszeit verkürzt werden, zum Beispiel mit Abitur. Probezeit und Berufsschulbesuch bleiben bestehen."}, {"q": "Eine neue Auszubildende beginnt am 15.08.2026 mit zwei Monaten Probezeit. Wann endet die Probezeit?", "o": ["Am 14.10.2026", "Am 15.10.2026", "Am 31.10.2026", "Am 14.09.2026"], "c": 0, "e": "Zwei Monate ab dem 15.08.2026 enden mit Ablauf des 14.10.2026. Zwei Monate liegen im erlaubten Rahmen von 1 bis 4 Monaten (§ 20 BBiG)."}, {"q": "Ein Vertragsentwurf enthält den Satz „Nach der Ausbildung arbeitet der Auszubildende mindestens zwei Jahre bei Nordstern.“ Wie ist das zu bewerten?", "o": ["Die Klausel ist nichtig, der übrige Vertrag bleibt wirksam", "Die Klausel ist wirksam, wenn die Eltern zustimmen", "Die Klausel ist wirksam, weil Nordstern die Ausbildung bezahlt", "Der ganze Ausbildungsvertrag wird dadurch unwirksam"], "c": 0, "e": "Eine Bindung für die Zeit nach der Ausbildung ist nach § 12 Abs. 1 BBiG nichtig. Nur diese Klausel fällt weg, die Ausbildung läuft normal weiter."}, {"q": "Ein Zulieferer verlangt von seiner Auszubildenden 150 € im Monat für einen Lehrgang, der zur Ausbildung gehört. Was gilt?", "o": ["Die Vereinbarung ist nichtig, sie muss nichts zahlen", "Die Zahlung ist zulässig, wenn sie im Vertrag steht", "Sie muss die Hälfte der Kosten selbst tragen", "Die IHK muss die Zahlung vorher genehmigen"], "c": 0, "e": "Eine Vereinbarung, nach der Auszubildende für die Ausbildung bezahlen, ist nichtig (§ 12 Abs. 2 BBiG). Der Lehrgang gehört zur Ausbildung und ist für sie kostenlos."}, {"q": "Mia erzählt einer Freundin bei einem anderen Fahrradhersteller von den geplanten Preisen für neue E-Bikes. Welche Pflicht verletzt sie?", "o": ["Die Pflicht, Geschäftsgeheimnisse zu wahren", "Die Pflicht, den Ausbildungsnachweis zu führen", "Die Pflicht, Werkzeuge pfleglich zu behandeln", "Die Pflicht, an Prüfungen teilzunehmen"], "c": 0, "e": "Nach § 13 BBiG muss Mia Betriebs- und Geschäftsgeheimnisse wahren. Geplante Preise sind ein typisches Geschäftsgeheimnis."}, {"q": "Nordstern will im Lager einen fachlich guten Teamleiter als Ausbilder einsetzen, der aber keine Ausbildereignung hat. Was folgt daraus?", "o": ["Die IHK trägt neue Verträge nur ein, wenn eine geeignete Person ausbildet", "Die IHK muss den Vertrag trotzdem sofort eintragen", "Die Berufsschule übernimmt dann die betriebliche Ausbildung", "Der Auszubildende muss sich selbst einen Ausbilder suchen"], "c": 0, "e": "Ausbilden darf nur, wer persönlich und fachlich geeignet ist (§ 28 BBiG). Die IHK prüft die Eignung vor der Eintragung (§ 35 BBiG)."}, {"q": "Ein Betrieb ohne Tarif bildet ab dem 01.08.2027 eine Kauffrau aus und zahlt im zweiten Jahr 880 €. Um wie viel Euro liegt er unter der Mindestvergütung?", "o": ["22 €", "26 €", "116 €", "0 €"], "c": 0, "e": "Für Beginn 2027 gilt im zweiten Jahr 764 € × 1,18 = 901,52 €, gerundet 902 €. 902 € − 880 € = 22 €."}, {"q": "Um wie viel Euro liegt Mias Vergütung im dritten Jahr über der Mindestvergütung ihres Jahrgangs?", "o": ["323 €", "426 €", "269 €", "336 €"], "c": 0, "e": "Mia hat 2026 begonnen. Mindestwert im dritten Jahr 724 € × 1,35 = 977 €. 1.300 € − 977 € = 323 €."}, {"q": "Ein nicht tarifgebundener Betrieb zahlt bei Beginn 2026 im ersten Jahr 820 €. Der Branchentarif sieht 1.050 € vor. Wie ist die Vergütung zu beurteilen?", "o": ["In der Regel nicht angemessen, weil mehr als 20 % unter dem Tarif", "Angemessen, weil sie über der Mindestvergütung von 724 € liegt", "Angemessen, weil der Tarif nur für tarifgebundene Betriebe gilt", "Nicht angemessen, weil sie unter dem Mindestlohn liegt"], "c": 0, "e": "80 % von 1.050 € sind 840 €. 820 € liegen also mehr als 20 % unter dem Tarif und sind in der Regel nicht angemessen (BIBB, 2026). Die Mindestvergütung allein reicht nicht."}, {"q": "Eine Auszubildende beginnt am 01.09.2027 eine dreijährige Ausbildung. Wie hoch ist ihre Mindestvergütung im dritten Jahr?", "o": ["1.031 €", "977 €", "1.070 €", "1.218 €"], "c": 0, "e": "Für Beginn 2027 gilt 764 € × 1,35 = 1.031,40 €, gerundet 1.031 €. Wer 902 € × 1,35 rechnet, baut falsch auf die Stufe davor."}, {"q": "Eine Auszubildende hat 2026 begonnen und ist im August 2027 im zweiten Jahr. Welcher Mindestwert gilt für sie?", "o": ["854 € aus ihrem Jahrgang 2026", "902 € aus dem Jahrgang 2027", "764 € aus dem Jahrgang 2027", "724 € wie im ersten Jahr"], "c": 0, "e": "Der Betrag des Jahrgangs bleibt bis zum Ende der Ausbildung fest. Für Beginn 2026 gilt im zweiten Jahr 854 €, auch wenn das zweite Jahr 2027 liegt."}, {"q": "Nordstern zahlt die Vergütung für November 2026 erst am Freitag, 04.12.2026. Wie ist das zu beurteilen?", "o": ["Zu spät, spätestens am Montag, 30.11.2026", "Rechtzeitig, die Zahlung ist bis zum 15. erlaubt", "Rechtzeitig, es zählt die erste Woche des Folgemonats", "Zu spät, die Zahlung muss am 1. des Monats erfolgen"], "c": 0, "e": "Die Vergütung für den laufenden Monat ist spätestens am letzten Arbeitstag des Monats zu zahlen (§ 18 BBiG). Der 30.11.2026 ist ein Montag."}, {"q": "Leons schriftliche Abschlussprüfung findet an einem Montag statt. Welcher Tag ist zusätzlich frei?", "o": ["Der Freitag davor als letzter Arbeitstag", "Der Sonntag vor der Prüfung", "Der Dienstag nach der Prüfung", "Kein weiterer Tag, nur der Prüfungstag"], "c": 0, "e": "Freizustellen ist der Arbeitstag, der der schriftlichen Abschlussprüfung unmittelbar vorangeht (§ 15 BBiG). Vor einem Montag ist das der Freitag."}, {"q": "Leons Unterricht beginnt am Mittwoch erst um 09:30 Uhr. Darf Nordstern ihn vorher von 07:00 bis 08:30 Uhr im Büro einsetzen?", "o": ["Ja, das Verbot gilt nur vor Unterricht, der vor 9 Uhr beginnt", "Nein, an Berufsschultagen ist eine Beschäftigung nie erlaubt", "Nein, weil Leon als Volljähriger unter das JArbSchG fällt", "Ja, aber nur, wenn Leon die Zeit unbezahlt nacharbeitet"], "c": 0, "e": "Nach § 15 BBiG darf vor einem Unterricht, der vor 9 Uhr beginnt, nicht beschäftigt werden. Beginnt er um 09:30 Uhr, ist ein Einsatz davor möglich, wenn die Wegezeit passt."}, {"q": "Ein 18-jähriger Auszubildender beginnt am 01.09.2026. Wie viele Werktage gesetzlichen Mindesturlaub hat er für 2026?", "o": ["8 Werktage", "24 Werktage", "6 Werktage", "10 Werktage"], "c": 0, "e": "Er ist volljährig, es gilt das BUrlG mit 24 Werktagen. Die Wartezeit ist 2026 nicht erfüllt, also 4/12 für September bis Dezember. 24 × 4 ÷ 12 = 8 Werktage (§ 5 BUrlG)."}, {"q": "Ein Jugendlicher hat 25 Werktage Urlaub. Er beginnt am 01.10.2026. Wie viele Werktage stehen ihm für 2026 zu?", "o": ["6,25 Werktage", "7 Werktage", "25 Werktage", "6,5 Werktage"], "c": 0, "e": "Drei volle Monate im Jahr 2026 ergeben 3/12. 25 × 3 ÷ 12 = 6,25 Werktage. Ein Viertel Tag wird nicht aufgerundet (§ 5 Abs. 2 BUrlG)."}, {"q": "Leon will die Ausbildung aufgeben und studieren. Sein schriftliches Kündigungsschreiben mit Begründung geht am Mittwoch, 03.02.2027, zu. Wann endet die Ausbildung?", "o": ["Mit Ablauf des 03.03.2027", "Mit Ablauf des 28.02.2027", "Mit Ablauf des 17.02.2027", "Mit Ablauf des 31.03.2027"], "c": 0, "e": "Wer die Ausbildung aufgibt, kann mit vier Wochen Frist kündigen (§ 22 Abs. 2 BBiG). Vier Wochen ab Mittwoch, 03.02.2027, enden am Mittwoch, 03.03.2027."}, {"q": "Nordstern erfährt am Montag, 04.01.2027, von einer Tätlichkeit eines Auszubildenden und kündigt am 20.01.2027 aus wichtigem Grund. Wie ist das zu bewerten?", "o": ["Unwirksam, die Frist endete am 18.01.2027", "Wirksam, die Frist beträgt vier Wochen", "Wirksam, weil eine Tätlichkeit vorliegt", "Unwirksam, weil vorher die IHK zustimmen muss"], "c": 0, "e": "Ein wichtiger Grund muss innerhalb von zwei Wochen nach Kenntnis genutzt werden (§ 22 Abs. 4 BBiG). Die Frist lief am Montag, 18.01.2027, ab."}, {"q": "Nordstern kündigt einem volljährigen Auszubildenden nach der Probezeit mit unterschriebenem Brief aus wichtigem Grund, nennt aber keinen Grund. Was gilt?", "o": ["Die Kündigung ist unwirksam, die Gründe fehlen", "Die Kündigung ist wirksam, der Brief ist unterschrieben", "Die Gründe kann Nordstern beliebig nachreichen", "Gründe sind nur bei Minderjährigen nötig"], "c": 0, "e": "Nach der Probezeit muss die Kündigung schriftlich und unter Angabe der Gründe erfolgen (§ 22 Abs. 3 BBiG). Ohne Gründe ist sie unwirksam."}, {"q": "Ein Auszubildender verlässt Nordstern nach der Probezeit ohne Grund. Das Ausbildungsverhältnis endet am 15.03.2027. Bis wann muss Nordstern Schadensersatz geltend machen?", "o": ["Bis zum 15.06.2027", "Bis zum 29.03.2027", "Bis zum 15.04.2027", "Bis zum 15.03.2028"], "c": 0, "e": "Der Anspruch auf Schadensersatz erlischt, wenn er nicht innerhalb von drei Monaten nach Beendigung geltend gemacht wird (§ 23 BBiG)."}, {"q": "Ein Prüfling hat im schriftlichen Bereich 42 Punkte und in der mündlichen Ergänzungsprüfung 66 Punkte. Wie lautet das neue Ergebnis?", "o": ["50 Punkte", "54 Punkte", "46 Punkte", "108 Punkte"], "c": 0, "e": "Schriftlich zählt doppelt, mündlich einfach. (2 × 42 + 66) ÷ 3 = 150 ÷ 3 = 50 Punkte."}, {"q": "Gesamtergebnis und Teil 2 sind ausreichend. In Teil 2 ist der schriftliche Bereich mangelhaft, die Fachaufgabe gut und Wirtschafts- und Sozialkunde ungenügend. Was gilt?", "o": ["Nicht bestanden, weil ein Bereich ungenügend ist", "Bestanden, weil das Gesamtergebnis ausreicht", "Bestanden, weil die Fachaufgabe gut ist", "Nicht bestanden, weil Teil 1 fehlt"], "c": 0, "e": "Kein Bereich von Teil 2 darf ungenügend sein (IndKflAusbV). Ein gutes Gesamtergebnis gleicht das nicht aus."}, {"q": "Leon besteht im Sommer 2028 nicht und verlangt eine Verlängerung. Sein reguläres Ende war der 31.07.2028. Wie lange darf die Ausbildung höchstens verlängert werden?", "o": ["Bis zur Wiederholungsprüfung, höchstens bis 31.07.2029", "Bis zur Wiederholungsprüfung, höchstens bis 31.01.2029", "Ohne zeitliche Grenze bis zum Bestehen", "Gar nicht, die Ausbildung endet am 31.07.2028"], "c": 0, "e": "Auf Verlangen verlängert sich die Ausbildung bis zur nächsten Wiederholungsprüfung, höchstens um ein Jahr (§ 21 Abs. 3 BBiG)."}, {"q": "Leon will die Prüfung im Winter wiederholen. Bis wann muss die Anmeldung bei der IHK zu Lübeck vorliegen?", "o": ["Bis zum 1. September", "Bis zum 1. Februar", "Bis zum 1. Mai", "Bis zum 31. Dezember"], "c": 0, "e": "Anmeldeschluss bei der IHK zu Lübeck ist der 1. September für die Winterprüfung und der 1. Februar für die Sommerprüfung (IHK zu Lübeck, o. J.)."}, {"q": "In welchem Zeitraum liegt Mias viertes Ausbildungshalbjahr, in dem Teil 1 stattfinden soll?", "o": ["01.02.2028 bis 31.07.2028", "01.08.2027 bis 31.01.2028", "01.02.2027 bis 31.07.2027", "01.08.2028 bis 31.01.2029"], "c": 0, "e": "Mia beginnt am 01.08.2026. Die Halbjahre dauern je sechs Monate, das vierte beginnt am 01.02.2028 und endet am 31.07.2028."}, {"q": "Mia soll im Januar 2027 von Montag bis Donnerstag je 8,5 Stunden und am Freitag 7 Stunden arbeiten. Ist das zulässig?", "o": ["Nein, die Woche hat 41 Stunden und damit mehr als 40", "Ja, an einzelnen Tagen sind 8,5 Stunden erlaubt", "Ja, weil der Freitag kürzer als 8 Stunden ist", "Nein, weil Jugendliche nie mehr als 8 Stunden arbeiten"], "c": 0, "e": "4 × 8,5 + 7 = 41 Stunden. Auch mit der 8,5-Stunden-Regel bleibt die Grenze von 40 Stunden in der Woche (§ 8 JArbSchG)."}, {"q": "Ein 16-jähriger Auszubildender soll von Montag bis Donnerstag je 8,5 Stunden und am Freitag 6 Stunden arbeiten. Wie ist das zu bewerten?", "o": ["Zulässig, weil ein Tag kürzer ist und 40 Stunden nicht überschritten werden", "Unzulässig, weil an keinem Tag mehr als 8 Stunden erlaubt sind", "Unzulässig, weil Jugendliche höchstens 35 Stunden arbeiten dürfen", "Zulässig nur mit Zustimmung der IHK zu Lübeck"], "c": 0, "e": "4 × 8,5 + 6 = 40 Stunden. Weil der Freitag kürzer als 8 Stunden ist, sind an den anderen Tagen 8,5 Stunden erlaubt (§ 8 Abs. 2a JArbSchG)."}, {"q": "Mia ist von 07:30 bis 13:00 Uhr im Betrieb und macht von 12:15 bis 12:45 Uhr Pause. Wie ist das zu bewerten?", "o": ["Unzulässig, die Pause muss spätestens eine Stunde vor Arbeitsende liegen", "Zulässig, weil sie 30 Minuten Pause bei 5 Stunden Arbeit hat", "Unzulässig, weil sie 60 Minuten Pause bräuchte", "Zulässig, weil Pausen beliebig gelegt werden dürfen"], "c": 0, "e": "Mia arbeitet 5 Stunden, 30 Minuten Pause reichen. Die Pause beginnt aber erst 45 Minuten vor Feierabend. Pausen müssen spätestens eine Stunde vor Ende liegen, und länger als 4,5 Stunden ohne Pause darf sie nicht arbeiten (§ 11 JArbSchG)."}, {"q": "Ein 16-Jähriger beginnt am 01.09.2026. Die Bescheinigung über die erste Nachuntersuchung fehlt dauerhaft. Ab wann darf Nordstern ihn nicht mehr beschäftigen?", "o": ["Ab dem 01.11.2027", "Ab dem 01.09.2027", "Ab dem 01.06.2027", "Ab dem 01.03.2028"], "c": 0, "e": "Nach Ablauf von 14 Monaten ab Beschäftigungsbeginn besteht ein Beschäftigungsverbot (§ 33 JArbSchG). 14 Monate ab dem 01.09.2026 enden am 31.10.2027."}, {"q": "Ein 16-jähriger Auszubildender zum Industriemechaniker soll unter Aufsicht seines Ausbilders an einer Presse arbeiten, weil das zum Ausbildungsziel gehört. Was gilt?", "o": ["Zulässig, weil Ausbildungszweck und fachkundige Aufsicht vorliegen", "Unzulässig, gefährliche Arbeiten sind ohne Ausnahme verboten", "Zulässig nur, wenn er dafür einen Zuschlag bekommt", "Zulässig nur, wenn er schon volljährig ist"], "c": 0, "e": "Gefährliche Arbeiten sind ausnahmsweise erlaubt, wenn sie zum Erreichen des Ausbildungsziels nötig sind und eine fachkundige Person aufsieht (§ 22 JArbSchG)."}, {"q": "Ab dem 14.03.2027 ist Mia volljährig. Welche tägliche Ruhezeit gilt dann für sie?", "o": ["11 Stunden", "12 Stunden", "10 Stunden", "8 Stunden"], "c": 0, "e": "Für Erwachsene gilt eine Ruhezeit von 11 Stunden (§ 5 ArbZG). Die 12 Stunden des JArbSchG gelten nur bis zum 18. Geburtstag."}, {"q": "Aylin Demir plant, Mia im ganzen ersten Jahr nur im Lager Kartons packen zu lassen. Wie ist das zu bewerten?", "o": ["Unzulässig, die Ausbildung muss planmäßig und sachlich gegliedert sein", "Zulässig, weil der Betrieb die Einsätze frei bestimmen darf", "Zulässig, solange Mia die volle Vergütung bekommt", "Unzulässig, weil Auszubildende nie im Lager arbeiten dürfen"], "c": 0, "e": "Nordstern muss nach dem Ausbildungsplan planmäßig, zeitlich und sachlich gegliedert ausbilden (§ 14 BBiG). Ein kurzer Einsatz im Lager ist möglich, ein ganzes Jahr nur Packen nicht."}, {"q": "Leon soll in der Spätschicht bis 23:30 Uhr arbeiten. Gilt für ihn die Nachtruhe von 20 bis 6 Uhr?", "o": ["Nein, für Leon gilt als Volljährigem das Arbeitszeitgesetz", "Ja, die Nachtruhe gilt für alle Auszubildenden", "Ja, aber nur an Tagen vor der Berufsschule", "Nein, weil Nordstern mehrschichtig arbeitet"], "c": 0, "e": "Die Nachtruhe nach § 14 JArbSchG gilt nur für Jugendliche. Leon ist 19, für ihn gilt das ArbZG mit 11 Stunden Ruhezeit (§ 5 ArbZG)."}, {"q": "Leon hat seine Ausbildung 2025 begonnen. Welcher Mindestwert gilt für ihn im zweiten Ausbildungsjahr?", "o": ["805 €", "854 €", "682 €", "902 €"], "c": 0, "e": "Für Leons Jahrgang 2025 gilt 682 € × 1,18 = 804,76 €, gerundet 805 €. Leon erhält mit 1.220 € deutlich mehr."}, {"q": "Wie viel Prozent der zehn Auszubildenden von Nordstern lernen Industriekaufmann oder Industriekauffrau?", "o": ["40 %", "4 %", "25 %", "60 %"], "c": 0, "e": "Vier von zehn Auszubildenden sind Industriekaufleute. 4 ÷ 10 × 100 = 40 %."}, {"q": "Laut Berufsbildungsbericht 2026 gab es 476.700 neue Ausbildungsverträge, 2,1 % weniger als im Vorjahr. Wie viele waren es im Vorjahr ungefähr?", "o": ["Rund 487.000", "Rund 466.700", "Rund 476.700", "Rund 500.000"], "c": 0, "e": "Der neue Wert entspricht 97,9 % des Vorjahres. 476.700 ÷ 0,979 ergibt rund 487.000 Verträge (BMBFSFJ, 2026)."}, {"q": "Ein Auszubildender bei Nordstern wird nach der Probezeit vorzeitig aus eigenem Verschulden entlassen. Wer kann Schadensersatz fordern?", "o": ["Der Betrieb, wenn der Auszubildende die Lösung verschuldet hat", "Nur die IHK, weil sie den Vertrag eingetragen hat", "Nur die Berufsschule für ausgefallenen Unterricht", "Niemand, weil Ausbildungsverträge keinen Schadensersatz kennen"], "c": 0, "e": "Wird das Ausbildungsverhältnis nach der Probezeit vorzeitig gelöst, kann die Seite Schadensersatz verlangen, die den Grund nicht zu vertreten hat (§ 23 BBiG)."}, {"q": "Ein anderer Betrieb hat eine Ausbildungszeit von 38 Stunden in fünf Tagen. Mit wie vielen Stunden zählt dort ein langer Berufsschultag?", "o": ["7,6 Stunden", "7,0 Stunden", "8,0 Stunden", "6,0 Stunden"], "c": 0, "e": "Der lange Schultag zählt mit der durchschnittlichen täglichen Ausbildungszeit (§ 15 Abs. 2 BBiG). 38 ÷ 5 = 7,6 Stunden."}, {"q": "Nordstern schließt am 10.02.2027 einen Ausbildungsvertrag für den 01.08.2027. Wann beantragt Nordstern die Eintragung bei der IHK?", "o": ["Unverzüglich nach dem Vertragsschluss im Februar 2027", "Erst nach dem Ende der Probezeit im Dezember 2027", "Erst am ersten Ausbildungstag im August 2027", "Erst bei der Anmeldung zu Teil 1 der Prüfung"], "c": 0, "e": "Der Ausbildende beantragt die Eintragung unverzüglich nach Abschluss des Vertrags und legt die Niederschrift bei (§ 36 BBiG). So kann die IHK Fehler noch vor Beginn finden."}], "lernen": [{"t": "Organigramm", "x": "Schaubild der Aufbauorganisation als Baum. Es zeigt Bereiche, Abteilungen, Stellen und wer wem unterstellt ist."}, {"t": "Personalabteilung", "x": "Abteilung, die Personal plant, beschafft, einstellt, verwaltet, entlohnt, entwickelt und freistellt und Kennzahlen auswertet."}, {"t": "Duales System", "x": "Berufsausbildung an zwei Lernorten, im Betrieb und in der Berufsschule."}, {"t": "Zuständige Stelle", "x": "Stelle, die die Ausbildung berät, überwacht, Verträge einträgt und prüft, für Nordstern die IHK zu Lübeck."}, {"t": "Ausbildungsordnung", "x": "Verordnung des Bundes für einen Beruf mit Dauer, Berufsbild, Ausbildungsrahmenplan und Prüfungsanforderungen."}, {"t": "Rahmenlehrplan", "x": "Plan der Kultusministerkonferenz für den Unterricht der Berufsschule, gegliedert in Lernfelder."}, {"t": "Betrieblicher Ausbildungsplan", "x": "Plan des Betriebs, wann die Auszubildende welche Inhalte in welcher Abteilung lernt."}, {"t": "Ausbildende", "x": "Das Unternehmen, das den Ausbildungsvertrag schließt, hier die Nordstern Fahrradwerke GmbH."}, {"t": "Vertragsniederschrift", "x": "Schriftliche Festlegung des wesentlichen Vertragsinhalts in Textform mit zwölf Mindestinhalten, spätestens vor Beginn."}, {"t": "Probezeit", "x": "Erster Abschnitt der Ausbildung von 1 bis 4 Monaten, in dem beide Seiten ohne Frist kündigen können."}, {"t": "Mindestausbildungsvergütung", "x": "Gesetzliche Untergrenze der Vergütung, für Beginn 2026 im ersten Jahr 724 €."}, {"t": "Freistellung", "x": "Pflicht des Betriebs, Auszubildende für Berufsschule und Prüfungen von der Arbeit zu befreien, ohne Verlust der Vergütung."}, {"t": "Gestreckte Abschlussprüfung", "x": "Abschlussprüfung in zwei zeitlich getrennten Teilen, die beide in das Ergebnis eingehen."}, {"t": "Jugendliche", "x": "Personen von 15 bis unter 18 Jahren, für sie gilt das Jugendarbeitsschutzgesetz."}, {"t": "Ruhezeit", "x": "Ununterbrochene Freizeit nach Feierabend, für Jugendliche mindestens 12 Stunden, für Erwachsene 11 Stunden."}, {"t": "Erstuntersuchung", "x": "Ärztliche Untersuchung, ohne die eine Jugendliche nicht beschäftigt werden darf, höchstens 14 Monate vor Beginn."}, {"t": "Jugend- und Auszubildendenvertretung (JAV)", "x": "Gewählte Vertretung der Jugendlichen und Auszubildenden unter 25 Jahren im Betrieb. Sie arbeitet über den Betriebsrat."}, {"t": "Organigramm", "x": "Schaubild der Aufbauorganisation in Form einer Baumstruktur. Es zeigt Bereiche, Abteilungen und Stellen und wer wem unterstellt ist (Beiderwieden & Stickdorn, 2026)."}, {"t": "Neun Gebiete, neun Kurstage", "x": "Ausbildung, Planung, Beschaffung, Einstellung, Entlohnung, Entwicklung, Führung, Freistellung und Controlling sind die Aufgabengebiete der Personalabteilung und zugleich die Themen der Kurstage 1 bis 9."}, {"t": "Duales System", "x": "Berufsausbildung an zwei Lernorten, im Betrieb und in der Berufsschule, die sich inhaltlich abstimmen (Beiderwieden & Stickdorn, 2026)."}, {"t": "Vorteile des dualen Systems", "x": "Theorie und Praxis von Anfang an verbunden, Lernen an echten Aufträgen, Vergütung während der Ausbildung, bundesweit anerkannter Abschluss und Fachkräfte, die der Betrieb schon kennt."}, {"t": "Merke", "x": "Die IHK berät, überwacht, trägt ein und prüft. Unterrichten gehört nicht zu ihren Aufgaben."}, {"t": "Betrieblicher Ausbildungsplan", "x": "Plan des Betriebs, der den Ausbildungsrahmenplan auf die eigenen Abteilungen und Zeiten überträgt (§ 5 BBiG, Beiderwieden & Stickdorn, 2026)."}, {"t": "Probezeit", "x": "Ausbildung 1 bis 4 Monate, Arbeitsvertrag bis 6 Monate. Diese Verwechslung kostet in Prüfungen oft Punkte."}, {"t": "Überstunden", "x": "Mehrarbeit über die tägliche Ausbildungszeit hinaus wird bezahlt oder mit Freizeit ausgeglichen. Bei Jugendlichen setzt das Jugendarbeitsschutzgesetz zusätzlich enge Grenzen."}, {"t": "Gestreckte Abschlussprüfung", "x": "Abschlussprüfung in zwei zeitlich getrennten Teilen, die beide in das Gesamtergebnis eingehen (§ 5 Abs. 2 BBiG, IndKflAusbV)."}, {"t": "Drei Zeugnisse", "x": "Ausbildungszeugnis vom Betrieb, Prüfungszeugnis von der IHK, Abschlusszeugnis von der Berufsschule."}, {"t": "Jugendliche", "x": "Jugendliche im Sinne des Gesetzes sind Personen, die 15, aber noch nicht 18 Jahre alt sind (§ 2 Abs. 2 JArbSchG)."}, {"t": "Untersuchungen", "x": "Erstuntersuchung höchstens 14 Monate vor Beginn, Nachuntersuchung nach einem Jahr, ohne Nachweis nach 14 Monaten Beschäftigungsverbot."}], "sortier": [{"titel": "Pflichten im Ausbildungsvertrag", "auftrag": "Bringe jedes Paket in das Depot der Seite, die diese Pflicht nach dem BBiG hat.", "kategorien": [{"id": "a", "name": "Ausbildende (§ 14)"}, {"id": "b", "name": "Auszubildende (§ 13)"}], "items": [{"text": "Planmäßig und zeitlich gegliedert ausbilden", "kat": "a", "expl": "Nordstern muss die Ausbildung nach einem Plan durchführen (§ 14 BBiG). So erreicht Mia ihr Ziel in drei Jahren."}, {"text": "Fachbücher und Werkzeug kostenlos zur Verfügung stellen", "kat": "a", "expl": "Ausbildungsmittel stellt der Betrieb kostenlos (§ 14 BBiG). Leon muss sein Fachbuch nicht selbst kaufen."}, {"text": "Mia zum Besuch der Berufsschule anhalten", "kat": "a", "expl": "Der Betrieb muss die Azubis zum Schulbesuch anhalten (§ 14 BBiG). Hingehen muss Mia selbst."}, {"text": "Den Ausbildungsnachweis regelmäßig durchsehen", "kat": "a", "expl": "Der Betrieb prüft den Nachweis und lässt ihn in der Ausbildungszeit führen (§ 14 BBiG)."}, {"text": "Nur Aufgaben geben, die dem Ausbildungszweck dienen", "kat": "a", "expl": "Das Privatauto des Chefs waschen gehört nicht dazu. Diese Grenze muss der Betrieb beachten (§ 14 BBiG)."}, {"text": "Eine geeignete Ausbilderin wie Aylin Demir beauftragen", "kat": "a", "expl": "Ausbildende bilden selbst aus oder beauftragen ausdrücklich eine Ausbilderin (§ 14 BBiG)."}, {"text": "Die Auszubildenden charakterlich fördern", "kat": "a", "expl": "Auch die persönliche Förderung ist eine Pflicht des Betriebs (§ 14 BBiG)."}, {"text": "Sich sorgfältig bemühen, das Ausbildungsziel zu erreichen", "kat": "b", "expl": "Das ist die Lernpflicht der Auszubildenden (§ 13 BBiG). Mia muss aktiv mitlernen."}, {"text": "Am Unterricht der Berufsschule teilnehmen", "kat": "b", "expl": "Der Schulbesuch ist eine Pflicht der Auszubildenden (§ 13 BBiG)."}, {"text": "Weisungen von Aylin Demir befolgen", "kat": "b", "expl": "Auszubildende folgen den Weisungen im Rahmen der Ausbildung (§ 13 BBiG)."}, {"text": "Kundendaten und Betriebsgeheimnisse nicht weitergeben", "kat": "b", "expl": "Auszubildende müssen Geheimnisse wahren (§ 13 BBiG). Das gilt auch für Leon."}, {"text": "Den Ausbildungsnachweis führen", "kat": "b", "expl": "Schreiben muss den Nachweis die oder der Auszubildende (§ 13 BBiG). Der Betrieb prüft ihn nur."}, {"text": "Werkzeug und Geräte pfleglich behandeln", "kat": "b", "expl": "Auszubildende gehen sorgsam mit den Arbeitsmitteln um (§ 13 BBiG)."}, {"text": "Die Ordnung im Betrieb beachten", "kat": "b", "expl": "Auch die Betriebsordnung müssen Auszubildende einhalten (§ 13 BBiG)."}]}, {"titel": "Mia oder Leon, wer darf was?", "auftrag": "Ordne jede Regel der Person zu, für die sie bei Nordstern gilt.", "kategorien": [{"id": "a", "name": "Mia, 17, jugendlich"}, {"id": "b", "name": "Leon, 19, volljährig"}], "items": [{"text": "Ruhezeit nach Arbeitsende mindestens 12 Stunden", "kat": "a", "expl": "Für Jugendliche gilt eine Freizeit von mindestens 12 Stunden (§ 13 JArbSchG). Erwachsene brauchen 11 Stunden."}, {"text": "Pause von 60 Minuten bei mehr als 6 Stunden Arbeit", "kat": "a", "expl": "Jugendliche bekommen bei mehr als 6 Stunden eine Stunde Pause (§ 11 JArbSchG)."}, {"text": "Höchstens 40 Stunden Arbeit in der Woche", "kat": "a", "expl": "Jugendliche arbeiten höchstens 8 Stunden am Tag und 40 in der Woche (§ 8 JArbSchG)."}, {"text": "Keine Arbeit bei der Inventur am Samstag", "kat": "a", "expl": "Für Jugendliche gilt die Samstagsruhe (§ 16 JArbSchG). In der Industrie gibt es keine Ausnahme."}, {"text": "Ärztliche Erstuntersuchung vor Beginn der Ausbildung", "kat": "a", "expl": "Jugendliche dürfen nur mit Bescheinigung über eine Erstuntersuchung beginnen (§ 32 JArbSchG)."}, {"text": "Urlaub 2027 von 25 Werktagen nach dem Alter am 1. Januar", "kat": "a", "expl": "Mia ist am 01.01.2027 noch 17 Jahre alt. Darum hat sie 25 Werktage (§ 19 JArbSchG)."}, {"text": "Nachtruhe ab 20 Uhr, im Schichtbetrieb Arbeit bis 23 Uhr", "kat": "a", "expl": "Diese Nachtruhe gilt nur für Jugendliche (§ 14 JArbSchG)."}, {"text": "Ruhezeit nach Arbeitsende mindestens 11 Stunden", "kat": "b", "expl": "Für Erwachsene gilt das ArbZG mit 11 Stunden Ruhezeit (§ 5 ArbZG)."}, {"text": "Pause von 30 Minuten bei mehr als 6 bis 9 Stunden Arbeit", "kat": "b", "expl": "Das ist die Pausenregel für Erwachsene (§ 4 ArbZG)."}, {"text": "Bis zu 10 Stunden am Tag, wenn im Schnitt 8 Stunden", "kat": "b", "expl": "Erwachsene dürfen mit Ausgleich bis 10 Stunden arbeiten (§ 3 ArbZG). Für Mia sind 8 Stunden die Grenze."}, {"text": "Gesetzlicher Mindesturlaub von 24 Werktagen", "kat": "b", "expl": "Volljährige erhalten mindestens 24 Werktage nach dem BUrlG (§ 3 BUrlG)."}, {"text": "Arbeit an allen Werktagen von Montag bis Samstag erlaubt", "kat": "b", "expl": "Nach dem ArbZG ist der Samstag ein normaler Werktag. Für Mia gilt die Fünf-Tage-Woche."}, {"text": "Die Nachtzeit beginnt erst um 23 Uhr", "kat": "b", "expl": "Für Erwachsene ist Nachtzeit 23 bis 6 Uhr (§ 2 ArbZG). Für Jugendliche gilt 20 bis 6 Uhr."}]}]}, {"nr": 2, "title": "Personalplanung", "date": "24.11.2026", "quiz": [{"q": "Was beschreibt der quantitative Personalbedarf?", "o": ["Wie viele Arbeitskräfte der Betrieb braucht", "Welche Kenntnisse die Arbeitskräfte haben sollen", "Wie hoch das Gehalt der Arbeitskräfte ist", "Wie die Arbeitskräfte geführt werden sollen"], "c": 0, "e": "Quantitativ heißt mengenmäßig. Es geht um die Anzahl der benötigten Arbeitskräfte, meist in Vollzeitkräften gerechnet."}, {"q": "Was versteht man unter dem Bruttopersonalbedarf?", "o": ["Den gesamten Bedarf an Arbeitskräften zum Planungszeitpunkt", "Die Zahl der Beschäftigten, die heute im Betrieb arbeiten", "Die Zahl der Stellen, die neu besetzt werden müssen", "Die Summe aller Bruttolöhne in einem Jahr"], "c": 0, "e": "Der Bruttopersonalbedarf ist der gesamte Bedarf, also Einsatzbedarf plus Reservebedarf. Die neu zu besetzenden Stellen sind der Nettobedarf (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was bedeutet Minderbedarf?", "o": ["Der Betrieb hat mehr Personal, als er braucht", "Der Betrieb braucht weniger Auszubildende als früher", "Der Betrieb hat weniger Personal, als er braucht", "Der Betrieb zahlt weniger als den Tariflohn"], "c": 0, "e": "Ein negativer Nettobedarf heißt Minderbedarf oder Freistellungsbedarf. Der Bestand ist größer als der Bedarf."}, {"q": "Wie berechnet man den fortgeschriebenen Personalbestand?", "o": ["Ist-Bestand − sichere Abgänge + sichere Zugänge", "Ist-Bestand + sichere Abgänge − sichere Zugänge", "Bruttobedarf − Ist-Bestand + Reservebedarf", "Ist-Bestand − alle möglichen Abgänge"], "c": 0, "e": "Man nimmt den heutigen Bestand, zieht die sicheren Abgänge ab und zählt die sicheren Zugänge dazu (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was ist ein sicherer Zugang im Sinne der Personalplanung?", "o": ["Ein Auszubildender mit fester Übernahmezusage", "Eine Bewerbung, die gerade eingegangen ist", "Ein Praktikant, der vielleicht wiederkommt", "Eine Stelle, die im Internet ausgeschrieben ist"], "c": 0, "e": "Sicher ist ein Zugang nur, wenn er feststeht. Bei Nordstern sind das zum Beispiel die übernommenen Auszubildenden."}, {"q": "Welche Teilplanung beantwortet die Leitfrage Wen haben wir?", "o": ["Personalbestandsplanung", "Personalbedarfsplanung", "Personaleinsatzplanung", "Personalfreistellungsplanung"], "c": 0, "e": "Die Personalbestandsplanung erfasst den heutigen Bestand und seine Veränderung. Die Bedarfsplanung fragt dagegen, wen der Betrieb braucht."}, {"q": "In der Montage arbeiten 100 Vollzeitkräfte. 2027 gibt es 4 Renteneintritte, 3 Kündigungen und 2 übernommene Auszubildende. Wie hoch ist der fortgeschriebene Bestand?", "o": ["95 Vollzeitkräfte", "91 Vollzeitkräfte", "93 Vollzeitkräfte", "109 Vollzeitkräfte"], "c": 0, "e": "100 − 4 − 3 + 2 = 95. Wer 91 erhält, hat die Zugänge abgezogen statt addiert."}, {"q": "Wie hoch ist der Nettopersonalbedarf der Montage 2027?", "o": ["25 Vollzeitkräfte", "20 Vollzeitkräfte", "27 Vollzeitkräfte", "7 Vollzeitkräfte"], "c": 0, "e": "Bruttobedarf 120 minus fortgeschriebener Bestand 95 ergibt 25. Die 27 entstehen, wenn man die 2 sicheren Zugänge vergisst."}, {"q": "Wie viele Räder montiert eine Vollzeitkraft bei Nordstern im Jahr?", "o": ["300 Räder", "1.500 Räder", "500 Räder", "250 Räder"], "c": 0, "e": "1.500 produktive Stunden ÷ 5 Stunden je Rad = 300 Räder. Mit dieser Kennzahl lässt sich der Bedarf prüfen, 36.000 ÷ 300 = 120."}, {"q": "Welche innere Einflussgröße bestimmt den Personalbedarf eines Industriebetriebs am stärksten?", "o": ["Der Absatz- und Produktionsplan", "Die Gestaltung der Kantine", "Die Zahl der Parkplätze", "Die Farbe des Firmenlogos"], "c": 0, "e": "Wie viel produziert und verkauft werden soll, bestimmt die benötigten Arbeitsstunden. Bei Nordstern hängt die Montage direkt an der Zahl der Räder."}, {"q": "Ein Tarifvertrag senkt die Wochenarbeitszeit, die Produktion bleibt gleich. Was passiert mit dem Personalbedarf?", "o": ["Er steigt, weil jede Kraft weniger Stunden leistet", "Er sinkt, weil weniger gearbeitet wird", "Er bleibt gleich, weil die Produktion gleich bleibt", "Er sinkt, weil die Lohnkosten steigen"], "c": 0, "e": "Die benötigten Stunden bleiben gleich, aber jede Kraft leistet weniger Stunden. Deshalb werden mehr Kräfte gebraucht."}, {"q": "Nordstern setzt in der Lackiererei eine stärker automatisierte Anlage ein. Wie wirkt das auf den Personalbedarf dort?", "o": ["Der Bedarf sinkt, weil die Anlage Handarbeit ersetzt", "Der Bedarf steigt, weil die Anlage teuer ist", "Der Bedarf bleibt gleich, weil Technik keine Rolle spielt", "Der Bedarf steigt, weil die Anlage Reservebedarf erzeugt"], "c": 0, "e": "Investitionen in Technik können Arbeit ersetzen. Bei Nordstern sinkt der Arbeitszeitbedarf der Lackiererei auf 40.500 Stunden."}, {"q": "Muss der Betriebsrat der Personalplanung zustimmen?", "o": ["Nein, er wird unterrichtet und beraten", "Ja, ohne Zustimmung ist der Plan unwirksam", "Ja, aber nur bei Betrieben mit Tarifbindung", "Nein, er muss nicht einmal informiert werden"], "c": 0, "e": "Nach § 92 BetrVG wird der Betriebsrat unterrichtet und es wird mit ihm beraten. Eine Zustimmung ist nicht nötig, eine Information aber Pflicht."}, {"q": "Welcher Teilplan steht am Anfang der Personalplanung?", "o": ["Die Personalbedarfsplanung", "Die Personalkostenplanung", "Die Personalfreistellungsplanung", "Die Personalentwicklungsplanung"], "c": 0, "e": "Erst wenn der Bedarf feststeht, kann der Betrieb Beschaffung, Einsatz, Entwicklung, Freistellung und Kosten planen."}, {"q": "Was ist die Aufgabe der Personaleinsatzplanung?", "o": ["Vorhandene Beschäftigte auf Stellen und Schichten verteilen", "Neue Beschäftigte auf dem externen Arbeitsmarkt suchen", "Die Höhe der Löhne für das nächste Jahr festlegen", "Kündigungen vorbereiten und gegenüber dem Betriebsrat begründen"], "c": 0, "e": "Die Einsatzplanung ordnet die vorhandenen Menschen den Stellen und Schichten zu. Suche gehört zur Beschaffung, Löhne zur Kostenplanung."}, {"q": "Eine Abteilung braucht 25 Vollzeitkräfte. Besetzt werden 24 Vollzeitstellen und zwei halbe Stellen. Wie viele Köpfe arbeiten dort?", "o": ["26 Köpfe", "25 Köpfe", "24 Köpfe", "27 Köpfe"], "c": 0, "e": "24 Vollzeitkräfte plus 2 Teilzeitkräfte ergeben 26 Köpfe. Zusammen leisten sie 24 + 0,5 + 0,5 = 25 Vollzeitkräfte."}, {"q": "Was ist ein Nachteil der einfachen Schätzung durch eine Führungskraft?", "o": ["Sie ist ungenau und kann von eigenen Interessen geprägt sein", "Sie dauert meist mehrere Jahre und bindet viele Fachleute", "Sie ist nach dem Betriebsverfassungsgesetz verboten", "Sie verlangt ein teures Rechenprogramm mit vielen Daten"], "c": 0, "e": "Schätzungen gehen schnell, beruhen aber nur auf Erfahrung. Eine Führungskraft könnte zum Beispiel den Bedarf ihrer Abteilung bewusst hoch ansetzen."}, {"q": "Wie läuft eine Expertenrunde zur Bedarfsschätzung ab?", "o": ["Mehrere Fachleute schätzen unabhängig, dann werden die Werte besprochen", "Eine einzige Führungskraft schätzt und legt den Wert sofort verbindlich fest", "Die Beschäftigten stimmen in einer Wahl über den Bedarf ab", "Ein Rechenprogramm ersetzt die Einschätzung aller Fachleute"], "c": 0, "e": "Bei der Expertenrunde werden mehrere unabhängige Schätzungen verglichen und gemeinsam besprochen. Das macht das Ergebnis genauer als eine Einzelschätzung."}, {"q": "Der Stellenplan 2027 der Verwaltung sieht 42 Stellen vor. Besetzt sind 40, es gibt 3 sichere Abgänge und 1 sicheren Zugang. Wie hoch ist der Nettobedarf?", "o": ["4 Stellen", "2 Stellen", "6 Stellen", "5 Stellen"], "c": 0, "e": "Fortgeschriebener Bestand 40 − 3 + 1 = 38. Nettobedarf 42 − 38 = 4."}, {"q": "Wie hoch ist der fortgeschriebene Bestand der Verwaltung, wenn 40 Stellen besetzt sind, 3 Personen ausscheiden und 1 Auszubildende übernommen wird?", "o": ["38", "36", "42", "44"], "c": 0, "e": "40 − 3 + 1 = 38. Die übernommene Auszubildende wird addiert."}, {"q": "Im Einkauf kündigt eine Person, gleichzeitig wird dort eine Auszubildende übernommen. Die Stellenzahl bleibt gleich. Warum ist der Nettobedarf im Einkauf null?", "o": ["Der sichere Zugang gleicht den sicheren Abgang aus", "Kündigungen werden in der Planung nie berücksichtigt", "Auszubildende zählen doppelt in der Rechnung", "Im Einkauf gibt es keinen Stellenplan"], "c": 0, "e": "Ein Abgang und ein Zugang heben sich auf. Der fortgeschriebene Bestand entspricht dann wieder der Stellenzahl."}, {"q": "Das Lager braucht 2027 insgesamt 39.000 Arbeitsstunden. Eine Kraft leistet 1.500 produktive Stunden. Wie hoch ist der Bruttobedarf?", "o": ["26 Vollzeitkräfte", "25 Vollzeitkräfte", "24 Vollzeitkräfte", "39 Vollzeitkräfte"], "c": 0, "e": "39.000 ÷ 1.500 = 26 Vollzeitkräfte."}, {"q": "Das Lager hat 25 Vollzeitkräfte, 2 sichere Abgänge, 1 sicheren Zugang und einen Bruttobedarf von 26. Wie hoch ist der Nettobedarf?", "o": ["2 Vollzeitkräfte", "1 Vollzeitkraft", "3 Vollzeitkräfte", "4 Vollzeitkräfte"], "c": 0, "e": "Fortgeschriebener Bestand 25 − 2 + 1 = 24. Nettobedarf 26 − 24 = 2."}, {"q": "Die Lackiererei hat 30 Vollzeitkräfte, 1 sicheren Abgang und einen Bruttobedarf von 27. Wie lautet der Nettobedarf?", "o": ["−2, also ein Minderbedarf", "+2, also ein Beschaffungsbedarf", "−3, also ein Minderbedarf", "+3, also ein Beschaffungsbedarf"], "c": 0, "e": "Fortgeschriebener Bestand 30 − 1 = 29. Nettobedarf 27 − 29 = −2. Der Bestand ist größer als der Bedarf."}, {"q": "In der Qualitätssicherung sind täglich 10 Prüfplätze zu besetzen, die Ausfallquote liegt bei 10 %. Wie hoch ist der Bruttobedarf?", "o": ["11 Personen", "10 Personen", "9 Personen", "20 Personen"], "c": 0, "e": "Reservebedarf 10 × 10 % = 1. Bruttobedarf 10 + 1 = 11."}, {"q": "Ein Bereich braucht täglich 8 besetzte Arbeitsplätze, die Ausfallquote beträgt 25 %. Wie hoch ist der Bruttobedarf?", "o": ["10 Personen", "8 Personen", "9 Personen", "12 Personen"], "c": 0, "e": "Reservebedarf 8 × 25 % = 2. Bruttobedarf 8 + 2 = 10."}, {"q": "Im Vertrieb bearbeitet eine Vollzeitkraft im Jahr 400 Aufträge. Erwartet werden 6.200 Aufträge. Wie hoch ist der Bruttobedarf?", "o": ["15,5 Vollzeitkräfte, etwa 15 volle und eine halbe Stelle", "15 Vollzeitkräfte, Nachkommastellen fallen immer weg", "16,5 Vollzeitkräfte", "155 Vollzeitkräfte"], "c": 0, "e": "6.200 ÷ 400 = 15,5. Nachkommastellen werden als Teilzeitstelle gedeutet oder gerundet."}, {"q": "Bruttobedarf 55, Ist-Bestand 60, sichere Abgänge 5, sichere Zugänge 3. Welches Ergebnis ist richtig?", "o": ["Nettobedarf −3, also Minderbedarf", "Nettobedarf +3, also Beschaffungsbedarf", "Nettobedarf −5, also Minderbedarf", "Nettobedarf 0, also kein Handlungsbedarf"], "c": 0, "e": "Fortgeschriebener Bestand 60 − 5 + 3 = 58. Nettobedarf 55 − 58 = −3."}, {"q": "Ein Monteur sagt in der Pause, er werde vielleicht nächstes Jahr kündigen. Wie behandelt die Personalplanung diese Aussage?", "o": ["Sie zählt nicht als sicherer Abgang", "Sie zählt als sicherer Abgang", "Sie zählt als sicherer Zugang", "Sie erhöht den Reservebedarf um eine Person"], "c": 0, "e": "In die Fortschreibung gehören nur feststehende Veränderungen. Eine bloße Absicht ist kein sicherer Abgang."}, {"q": "Warum plant Nordstern in der Montage keinen eigenen Reservebedarf ein?", "o": ["Die Ausfallzeiten sind in den 1.500 produktiven Stunden schon abgezogen", "In der Montage gibt es dank Schichtarbeit keine Ausfälle", "Für die Produktion ist ein Reservebedarf gesetzlich nicht erlaubt", "Der Betriebsrat hat den Reservebedarf in der Montage abgelehnt"], "c": 0, "e": "Die 1.500 Stunden sind die Stunden, in denen wirklich montiert wird. Urlaub, Krankheit und Weiterbildung sind darin bereits berücksichtigt."}, {"q": "Welche Aussage zu Brutto- und Nettopersonalbedarf ist richtig?", "o": ["Der Nettobedarf ist der Teil, der nach Abzug des fortgeschriebenen Bestands bleibt", "Der Nettobedarf ist immer größer als der Bruttobedarf derselben Abteilung", "Der Bruttobedarf enthält nur die Stellen, die neu besetzt werden müssen", "Brutto- und Nettobedarf sind zwei Namen für dieselbe Zahl im Plan"], "c": 0, "e": "Brutto ist der Gesamtbedarf, netto ist der Rest nach Abzug des Personals, das sicher noch da ist."}, {"q": "Der Nettopersonalbedarf einer Abteilung ist negativ. Welcher Teilplan wird dann wichtig?", "o": ["Die Freistellungsplanung", "Die Beschaffungsplanung", "Die Ausbildungsplanung", "Die Werbeplanung"], "c": 0, "e": "Bei Minderbedarf muss der Betrieb überlegen, wie er Personal abbaut oder anders einsetzt. Das ist Aufgabe der Freistellungsplanung."}, {"q": "Der Nettopersonalbedarf der Montage beträgt 25. Welcher Teilplan schließt sich vor allem an?", "o": ["Die Beschaffungsplanung", "Die Freistellungsplanung", "Die Absatzplanung", "Die Investitionsplanung"], "c": 0, "e": "Ein positiver Nettobedarf bedeutet, dass Personal gewonnen werden muss. Die Wege dazu sind Thema des dritten Kurstags."}, {"q": "Nordstern versetzt eine Sachbearbeiterin vom Einkauf in die Personalabteilung. Wie wirkt das in der Planung?", "o": ["Abgang im Einkauf, Zugang im Personal, im Gesamtbetrieb keine Änderung", "Abgang im Einkauf und auch im Gesamtbetrieb ein Abgang", "Zugang im Einkauf, weil dort eine Stelle frei wird", "Versetzungen werden in der Planung nie berücksichtigt"], "c": 0, "e": "Eine Versetzung ist in der abgebenden Abteilung ein Abgang und in der aufnehmenden ein Zugang. Für den ganzen Betrieb gleicht sie sich aus."}, {"q": "Welchen Beitrag leistet die Personalkostenplanung innerhalb der Personalplanung?", "o": ["Sie berechnet, was das geplante Personal im Planungsjahr kostet", "Sie legt fest, welche Beschäftigte im Planungsjahr befördert werden", "Sie verteilt die Beschäftigten auf die Früh- und Spätschichten", "Sie bestimmt die Zahl der Ausbildungsplätze für das nächste Jahr"], "c": 0, "e": "Die Personalkostenplanung rechnet Entgelte, Arbeitgeberanteile und weitere Kosten für das Planungsjahr aus."}, {"q": "Was bedeutet zeitliche Personalplanung?", "o": ["Festlegen, ab wann das Personal zur Verfügung stehen muss", "Festlegen, wie lange eine Besprechung höchstens dauern darf", "Festlegen, an welchem Tag die Löhne überwiesen werden", "Festlegen, wie viele Pausen am Tag erlaubt sind"], "c": 0, "e": "Die zeitliche Planung beantwortet die Frage nach dem Wann. Neue Monteure müssen zum Beispiel vor dem Produktionsanstieg eingearbeitet sein."}, {"q": "Was versteht man unter Demografie als Einflussgröße?", "o": ["Die Entwicklung der Bevölkerung nach dem Alter", "Die Zahl der Mitglieder im Betriebsrat", "Die Zahl der verkauften Lastenräder im Jahr", "Die Höhe der Zinsen für Kredite der Banken"], "c": 0, "e": "Wenn viele Menschen in Rente gehen und weniger junge nachkommen, wird es schwerer, Personal zu finden. Das ist eine äußere Einflussgröße."}, {"q": "Was bedeutet Fluktuation?", "o": ["Das Ausscheiden und Ersetzen von Beschäftigten", "Die Schwankung der Rohstoffpreise", "Der Wechsel zwischen Früh- und Spätschicht", "Die Veränderung der Lagerbestände"], "c": 0, "e": "Fluktuation beschreibt den Wechsel von Beschäftigten, die den Betrieb verlassen und ersetzt werden. Hohe Fluktuation erhöht den Ersatzbedarf."}, {"q": "Nordstern versetzt 2 Kräfte aus der Lackiererei in die Montage. Wie viele Kräfte muss die Montage dann noch extern beschaffen?", "o": ["23 Vollzeitkräfte", "25 Vollzeitkräfte", "27 Vollzeitkräfte", "21 Vollzeitkräfte"], "c": 0, "e": "Der Nettobedarf der Montage beträgt 25. Zwei Stellen werden intern besetzt, also bleiben 25 − 2 = 23 für die externe Beschaffung."}, {"q": "Mit welcher Frage befasst sich der qualitative Personalbedarf?", "o": ["Welche Kenntnisse und Fähigkeiten gebraucht werden", "Wie viele Vollzeitkräfte im Planungsjahr fehlen", "Wie hoch die Personalkosten im Planungsjahr sind", "Wie viele Beschäftigte im Jahr ausscheiden"], "c": 0, "e": "Qualitativ bezieht sich auf die Art und Güte der Arbeitskraft. Die Anzahl gehört zum quantitativen Bedarf (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was ist eine Stelle im organisatorischen Sinn?", "o": ["Die kleinste organisatorische Einheit mit Aufgaben für eine Person", "Der Schreibtisch, an dem eine bestimmte Person sitzt", "Eine Abteilung mit mehreren Teams und einer Leitung", "Der Arbeitsvertrag einer einzelnen beschäftigten Person"], "c": 0, "e": "Eine Stelle bündelt Aufgaben für eine Person und besteht unabhängig davon, wer sie gerade besetzt."}, {"q": "Eine Monteurin, deren Stelle beschrieben ist, geht in Rente. Was passiert mit der Stellenbeschreibung?", "o": ["Sie bleibt gültig und dient für die Neubesetzung", "Sie wird gelöscht und für die Nachfolge ganz neu geschrieben", "Sie geht mit der Monteurin in die Rentenakte über", "Sie verliert ihre Gültigkeit am letzten Arbeitstag"], "c": 0, "e": "Die Stellenbeschreibung gilt für die Stelle, nicht für die Person. Sie wird nur angepasst, wenn sich die Aufgaben ändern."}, {"q": "Was beschreiben die Befugnisse in einer Stellenbeschreibung?", "o": ["Was die Person auf der Stelle selbst entscheiden darf", "Welche Schulabschlüsse die Person mitbringen muss", "Welche Hobbys die Person in der Freizeit hat", "Wie viele Urlaubstage die Person im Jahr erhält"], "c": 0, "e": "Befugnisse legen den Entscheidungsspielraum fest, bei der Teamleitung Montage zum Beispiel Materialbestellungen bis 500 €."}, {"q": "Was unterscheidet die Stellenbeschreibung von der Stellenausschreibung?", "o": ["Die Ausschreibung macht eine freie Stelle bekannt und beruht auf der Beschreibung", "Es handelt sich um dasselbe Dokument", "Die Beschreibung richtet sich an Bewerbende, die Ausschreibung an den Betriebsrat", "Die Ausschreibung beschreibt eine Person, die Beschreibung den Arbeitsmarkt"], "c": 0, "e": "Die Stellenbeschreibung beschreibt eine Stelle dauerhaft und personenunabhängig. Die Stellenausschreibung sucht für eine freie Stelle Bewerberinnen und Bewerber."}, {"q": "Warum nutzen Tarifbetriebe Stellenbeschreibungen oft bei der Eingruppierung?", "o": ["Das Entgelt richtet sich nach der Tätigkeit, nicht nach der Person", "Das Entgelt richtet sich nach dem Alter der Person", "Das Entgelt wird jedes Jahr frei mit allen verhandelt", "Das Entgelt hängt allein von der Betriebszugehörigkeit ab"], "c": 0, "e": "Die Entgeltgruppe hängt von den Aufgaben der Stelle ab. Die Stellenbeschreibung zeigt diese Aufgaben."}, {"q": "Welches Merkmal gehört zur Fachkompetenz?", "o": ["Kenntnisse über die Montage von E-Bike-Antrieben", "Die Fähigkeit, Streit im Team zu schlichten", "Die Bereitschaft, Verantwortung zu übernehmen", "Die Fähigkeit, sich selbst gut zu motivieren"], "c": 0, "e": "Fachkompetenz ist fachliches Wissen und Können. Streit schlichten gehört zur Sozialkompetenz, Verantwortung und Selbstmotivation zur Selbstkompetenz."}, {"q": "Was versteht man unter Handlungskompetenz?", "o": ["Das Zusammenspiel von Fach-, Methoden-, Sozial- und Selbstkompetenz", "Die Erlaubnis, im Namen des Betriebs Verträge zu schließen", "Die Fähigkeit, schnell und ohne Pause zu arbeiten", "Das Recht des Betriebsrats, bei Einstellungen mitzuwirken"], "c": 0, "e": "Die vier Kompetenzbereiche ergeben zusammen die Handlungskompetenz. Vertragsvollmachten sind Befugnisse, keine Kompetenz im Sinne des Profils."}, {"q": "Was gilt für eine Muss-Anforderung?", "o": ["Wer sie nicht erfüllt, kommt für die Stelle nicht infrage", "Sie ist wünschenswert, aber nicht entscheidend", "Sie gilt nur für Auszubildende im ersten Jahr", "Sie wird erst nach der Probezeit geprüft"], "c": 0, "e": "Muss-Anforderungen sind zwingend. Kann-Anforderungen sind erwünscht und helfen bei der Auswahl."}, {"q": "Welche Anforderung ist im Profil der Teamleitung Montage nur eine Kann-Anforderung?", "o": ["Englischkenntnisse für Gespräche mit Lieferanten", "Facharbeiterbrief und Erfahrung in der Montage", "Führen und Anleiten neuer Monteurinnen und Monteure", "Belastbarkeit und Bereitschaft zur Verantwortung"], "c": 0, "e": "Englisch ist für die Teamleitung erwünscht, aber nicht zwingend. Fach-, Sozial- und Selbstkompetenz sind Muss-Anforderungen."}, {"q": "Was droht, wenn ein Betrieb zu viele Muss-Anforderungen festlegt?", "o": ["Er findet am Arbeitsmarkt kaum passende Personen", "Er muss mehr Steuern zahlen", "Er verliert die Tarifbindung", "Er muss die Stelle sofort streichen"], "c": 0, "e": "Je mehr zwingende Bedingungen, desto kleiner ist der Kreis geeigneter Personen. Gute Bewerbungen werden abgeschreckt."}, {"q": "Was beschreibt das Qualifikationsprofil?", "o": ["Was eine bestimmte Person tatsächlich kann", "Was eine Stelle von einer Person verlangt", "Welche Aufgaben eine Abteilung insgesamt hat", "Welche Entgeltgruppe eine Stelle erhält"], "c": 0, "e": "Das Qualifikationsprofil oder Eignungsprofil zeigt die Fähigkeiten einer Person. Die Anforderungen der Stelle stehen im Anforderungsprofil."}, {"q": "Welche Maßnahme passt zu den Lücken von Jonas Petersen?", "o": ["Schulung zur Schichtplanung und Führungsseminar", "Sofortige Abmahnung wegen fehlender Kenntnisse", "Versetzung ins Lager ohne weitere Prüfung", "Senkung seines Entgelts um eine Entgeltgruppe"], "c": 0, "e": "Kleine Lücken schließt man durch Personalentwicklung. Danach kann Jonas die Stelle übernehmen. Mehr dazu am sechsten Kurstag."}, {"q": "Woraus wird das Anforderungsprofil abgeleitet?", "o": ["Aus den Aufgaben in der Stellenbeschreibung", "Aus dem Lebenslauf der bisherigen Person", "Aus der Gewinn- und Verlustrechnung", "Aus dem Urlaubsplan der Abteilung"], "c": 0, "e": "Für jede Aufgabe fragt man, was eine Person können muss. So entsteht aus der Aufgabenliste eine Anforderungsliste."}, {"q": "Im Anforderungsprofil von Nordstern steht bei der Sozialkompetenz die Stufe 5. Was bedeutet das?", "o": ["Die Anforderung ist sehr hoch", "Die Anforderung ist gering", "Die Anforderung ist nur eine Kann-Anforderung", "Die Anforderung wird nicht geprüft"], "c": 0, "e": "Die Skala reicht von 1 für gering bis 5 für sehr hoch. Die Teamleitung muss viele neue Kräfte führen und anleiten."}, {"q": "Zu welchem Kompetenzbereich gehört Pünktlichkeit?", "o": ["Selbstkompetenz", "Fachkompetenz", "Methodenkompetenz", "Sozialkompetenz"], "c": 0, "e": "Pünktlichkeit ist eine Frage der eigenen Haltung und Zuverlässigkeit, also Selbstkompetenz."}, {"q": "Welches Modell macht vor allem die Lage der Arbeitszeit flexibel?", "o": ["Gleitzeit", "Teilzeit", "Jobsharing", "Jahresarbeitszeit"], "c": 0, "e": "Bei der Gleitzeit wählen die Beschäftigten Beginn und Ende selbst. Die Dauer pro Woche bleibt im Kern gleich."}, {"q": "Was macht mobiles Arbeiten vor allem flexibel?", "o": ["Den Ort der Arbeit", "Die Höhe des Entgelts", "Die Zahl der Urlaubstage", "Die Dauer der Probezeit"], "c": 0, "e": "Beim mobilen Arbeiten wird außerhalb des Betriebs gearbeitet, etwa zu Hause oder unterwegs."}, {"q": "Welcher Nachteil kann mit Stellenbeschreibungen verbunden sein?", "o": ["Sie müssen laufend gepflegt werden und veralten schnell", "Sie verhindern die Einarbeitung neuer Kräfte", "Sie gelten nur für eine bestimmte Person", "Sie verbieten die Eingruppierung nach Tarif"], "c": 0, "e": "Erstellung und Pflege kosten Zeit. Ändern sich die Aufgaben, ist die Beschreibung schnell veraltet und kann starr wirken."}, {"q": "Ein Vertrag sieht Arbeit auf Abruf vor, eine wöchentliche Arbeitszeit ist nicht festgelegt. Was gilt?", "o": ["20 Stunden pro Woche gelten als vereinbart", "10 Stunden pro Woche gelten als vereinbart", "Bezahlt werden nur die tatsächlich abgerufenen Stunden", "Der ganze Arbeitsvertrag ist nichtig"], "c": 0, "e": "Fehlt die Festlegung, gilt nach § 12 TzBfG eine wöchentliche Arbeitszeit von 20 Stunden. Die früher genannten 10 Stunden sind seit 2019 überholt."}, {"q": "Eine Teamleiterin möchte ein halbes Jahr reisen und danach auf ihre Stelle zurückkehren. Welches Modell passt?", "o": ["Sabbatical", "Kurzarbeit", "Altersteilzeit", "Arbeit auf Abruf"], "c": 0, "e": "Beim Sabbatical nimmt eine Person mehrere Monate frei, unbezahlt oder mit angespartem Zeitguthaben, und kehrt danach auf ihre Stelle zurück."}, {"q": "Was bedeutet Kernzeit bei der Gleitzeit?", "o": ["Die Zeit, in der alle anwesend sein müssen", "Die Zeit, in der niemand arbeiten darf", "Die Zeit, in der Überstunden bezahlt werden", "Die Zeit, in der die Kantine geöffnet ist"], "c": 0, "e": "In der Kernzeit besteht Anwesenheitspflicht. Außerhalb der Kernzeit, aber innerhalb der Rahmenzeit, wählen die Beschäftigten selbst."}, {"q": "Warum darf eine Beschäftigte bei Nordstern nicht die ganze Rahmenzeit von 06:30 bis 19:00 Uhr arbeiten?", "o": ["Die Arbeitszeit würde die Grenze von 10 Stunden überschreiten", "Die Kantine schließt schon vor dem Ende der Rahmenzeit", "Gleitzeit erlaubt nur Arbeit innerhalb der Kernzeit", "Der Betriebsrat muss jeden einzelnen Tag genehmigen"], "c": 0, "e": "12,5 Stunden minus Pause ergeben deutlich mehr als 10 Stunden. Das erlaubt § 3 ArbZG nicht."}, {"q": "Lisa Wagner arbeitet von 07:30 bis 16:30 Uhr mit 45 Minuten Pause. Ihr Soll sind 7 Stunden. Wie verändert sich ihr Zeitkonto?", "o": ["Plus 1 Stunde 15 Minuten", "Plus 2 Stunden", "Plus 45 Minuten", "Minus 15 Minuten"], "c": 0, "e": "9 Stunden Anwesenheit minus 45 Minuten Pause ergeben 8 Stunden 15 Minuten. Das sind 1 Stunde 15 Minuten über dem Soll."}, {"q": "Ein Zeitkonto steht bei plus 55 Stunden. Im nächsten Monat kommen 8 Plusstunden dazu. Was gilt nach den Regeln von Nordstern?", "o": ["Die Grenze von 60 Stunden wird um 3 Stunden überschritten", "Die Grenze von 60 Stunden wird um 8 Stunden überschritten", "Das Konto bleibt mit 63 Stunden innerhalb der Grenze", "Das Konto wird automatisch auf null gesetzt"], "c": 0, "e": "55 + 8 = 63 Stunden. Die Obergrenze liegt bei 60, also 3 Stunden zu viel. Die Führungskraft muss für Ausgleich sorgen."}, {"q": "Was gilt bei Kurzarbeit?", "o": ["Nach einer Anzeige zahlt die Agentur für Arbeit Kurzarbeitergeld", "Der Arbeitgeber führt sie ohne den Betriebsrat ein", "Die Beschäftigten arbeiten länger ohne Lohnausgleich", "Kurzarbeitergeld fließt ohne zeitliche Grenze"], "c": 0, "e": "Bei erheblichem, vorübergehendem Arbeitsausfall zahlt die Agentur für Arbeit Kurzarbeitergeld, gesetzlich bis zu 12 Monate (§ 104 SGB III). Der Betriebsrat bestimmt bei der Einführung mit."}, {"q": "Nordstern verteilt die Arbeitszeit so, dass 26 Wochen mit 40 Stunden und 26 Wochen mit 30 Stunden gearbeitet wird. Wie viele Stunden sind das im Jahr?", "o": ["1.820 Stunden", "1.560 Stunden", "2.080 Stunden", "1.750 Stunden"], "c": 0, "e": "26 × 40 + 26 × 30 = 1.040 + 780 = 1.820 Stunden. Das entspricht 52 × 35 Stunden."}, {"q": "Eine Sachbearbeiterin in EG 9 mit 3.950 € bei 35 Stunden wechselt auf 21 Stunden. Wie hoch ist ihr Monatsentgelt im vereinfachten Beispiel?", "o": ["2.370 €", "2.100 €", "2.633 €", "1.975 €"], "c": 0, "e": "3.950 € × 21 ÷ 35 = 2.370 €. Das Entgelt sinkt anteilig mit den Stunden."}, {"q": "Was versteht man unter Jobsharing?", "o": ["Mehrere Personen teilen sich einen Arbeitsplatz", "Eine Person arbeitet für zwei Betriebe gleichzeitig", "Beschäftigte tauschen regelmäßig ihre Abteilungen", "Ein Betrieb verleiht Personal an einen anderen Betrieb"], "c": 0, "e": "Beim Jobsharing teilen sich zwei oder mehr Personen eine Stelle und stimmen ihre Zeiten ab. Regelmäßiger Wechsel der Abteilung ist Job Rotation."}, {"q": "Was kennzeichnet die Brückenteilzeit?", "o": ["Teilzeit für 1 bis 5 Jahre mit Rückkehr zur alten Stundenzahl", "Teilzeit nur für Auszubildende in der Berufsschulzeit", "Teilzeit ohne Entgelt für längstens drei Monate", "Teilzeit, die nur in Betrieben unter 15 Beschäftigten gilt"], "c": 0, "e": "Die Brückenteilzeit nach § 9a TzBfG ist zeitlich begrenzt. Danach kehrt die Person zur vorherigen Arbeitszeit zurück. Sie gilt ab mehr als 45 Beschäftigten."}, {"q": "Wie unterscheiden sich Job Splitting und Job Pairing?", "o": ["Beim Job Pairing tragen die Partner gemeinsam Verantwortung für die Stelle", "Beim Job Splitting teilen sich zwei Personen einen Vertrag", "Job Pairing ist eine Form der Kurzarbeit", "Beim Job Splitting arbeiten die Partner immer gleichzeitig"], "c": 0, "e": "Beim Job Splitting hat jede Person einen eigenen Vertrag und eigene Aufgaben. Beim Job Pairing sind die Partner gemeinsam für die ganze Stelle verantwortlich."}, {"q": "Ein Monteur hat bis 21:00 Uhr Spätschicht. Warum darf er am nächsten Tag nicht um 06:00 Uhr in der Frühschicht beginnen?", "o": ["Die Ruhezeit betrüge nur 9 statt mindestens 11 Stunden", "Er hätte dann mehr als 48 Stunden in der Woche gearbeitet", "Frühschichten sind für Monteure grundsätzlich verboten", "Er hätte dann keinen Anspruch mehr auf eine Pause"], "c": 0, "e": "Zwischen 21:00 und 06:00 Uhr liegen 9 Stunden. § 5 ArbZG verlangt mindestens 11 Stunden ununterbrochene Ruhezeit."}, {"q": "Welche Vorschrift gibt dem Betriebsrat ein Mitbestimmungsrecht bei der Ausgestaltung mobiler Arbeit?", "o": ["§ 87 Abs. 1 Nr. 14 BetrVG", "§ 92 BetrVG", "§ 5 ArbZG", "§ 8 TzBfG"], "c": 0, "e": "§ 87 Abs. 1 Nr. 14 BetrVG betrifft die Ausgestaltung mobiler Arbeit. § 92 BetrVG regelt die Personalplanung, § 5 ArbZG die Ruhezeit."}, {"q": "Wie lange dürfen Erwachsene nach § 3 ArbZG werktäglich arbeiten?", "o": ["8 Stunden, bis zu 10 Stunden mit Ausgleich", "10 Stunden, bis zu 12 Stunden mit Ausgleich", "7 Stunden, bis zu 9 Stunden mit Ausgleich", "9 Stunden, ohne jede Verlängerung"], "c": 0, "e": "Regel sind 8 Stunden. Eine Verlängerung auf 10 Stunden ist erlaubt, wenn der Durchschnitt von 8 Stunden eingehalten wird."}, {"q": "Ein Lagerist arbeitet 7 Stunden 30 Minuten. Wie lang muss seine Pause mindestens sein?", "o": ["30 Minuten", "15 Minuten", "45 Minuten", "60 Minuten"], "c": 0, "e": "Bei mehr als 6 bis 9 Stunden sind mindestens 30 Minuten Pause vorgeschrieben (§ 4 ArbZG)."}, {"q": "Eine Beschäftigte arbeitet 9 Stunden 30 Minuten. Wie lang muss ihre Pause mindestens sein?", "o": ["45 Minuten", "30 Minuten", "60 Minuten", "20 Minuten"], "c": 0, "e": "Bei mehr als 9 Stunden sind mindestens 45 Minuten Pause vorgeschrieben (§ 4 ArbZG)."}, {"q": "Wie lange darf jemand nach dem ArbZG höchstens ohne Pause hintereinander arbeiten?", "o": ["6 Stunden", "4 Stunden", "8 Stunden", "9 Stunden"], "c": 0, "e": "Länger als 6 Stunden hintereinander darf niemand ohne Ruhepause beschäftigt werden. Pausen müssen mindestens 15 Minuten dauern."}, {"q": "Wie lange muss die ununterbrochene Ruhezeit nach dem Ende der täglichen Arbeitszeit mindestens sein?", "o": ["11 Stunden", "8 Stunden", "12 Stunden", "10 Stunden"], "c": 0, "e": "§ 5 ArbZG verlangt für Erwachsene mindestens 11 Stunden. Für Jugendliche sind es nach dem JArbSchG 12 Stunden."}, {"q": "Warum sind nach § 3 ArbZG rechnerisch bis zu 48 Stunden pro Woche erlaubt?", "o": ["Weil Werktage Montag bis Samstag sind und 6 × 8 = 48 ergibt", "Weil die Wochenarbeitszeit in jedem Tarifvertrag 48 Stunden beträgt", "Weil 5 Arbeitstage zu je 9,6 Stunden immer erlaubt sind", "Weil der Sonntag als halber Werktag mitgezählt wird"], "c": 0, "e": "Das Gesetz spricht von werktäglich 8 Stunden. Werktage sind Montag bis Samstag, also 6 × 8 = 48 Stunden."}, {"q": "Was verlangt § 16 Abs. 2 ArbZG?", "o": ["Arbeitszeit über 8 Stunden werktäglich aufzeichnen und 2 Jahre aufbewahren", "Jede Minute der Arbeitszeit elektronisch und sofort an das Amt melden", "Arbeitszeit nur bei Auszubildenden aufzeichnen und 6 Monate aufbewahren", "Arbeitszeit nur sonntags aufzeichnen und 10 Jahre aufbewahren"], "c": 0, "e": "Das Gesetz selbst verlangt nur die Aufzeichnung der Zeit über 8 Stunden werktäglich. Die weitergehende Pflicht stammt aus der Rechtsprechung."}, {"q": "Was hat das Bundesarbeitsgericht am 13.09.2022 zur Arbeitszeiterfassung entschieden?", "o": ["Arbeitgeber müssen Beginn und Ende der täglichen Arbeitszeit erfassen", "Arbeitgeber dürfen die Arbeitszeit grundsätzlich nicht erfassen", "Nur Betriebe mit Betriebsrat müssen die Arbeitszeit erfassen", "Die Erfassung ist nur in der Pflege und im Handwerk nötig"], "c": 0, "e": "Das BAG leitet die Pflicht aus § 3 Abs. 2 Nr. 1 ArbSchG ab. Eine bestimmte Form schreibt es nicht vor (BAG, 2022)."}, {"q": "Wie ist der Stand des Referentenentwurfs zur elektronischen Arbeitszeiterfassung vom 18.06.2026?", "o": ["Er ist geplant, aber nicht beschlossen und nicht in Kraft", "Er gilt seit dem 01.07.2026 für alle Betriebe", "Er wurde vom Bundestag endgültig abgelehnt", "Er gilt nur für Betriebe mit Tarifbindung"], "c": 0, "e": "Bis mindestens Oktober 2026 gab es keinen Kabinettsbeschluss (Handwerkskammer Niederbayern-Oberpfalz, 2026). Es gilt weiter die Pflicht nach dem BAG."}, {"q": "Welcher Begriff passt zu dieser Beschreibung? Ein Betrieb legt im Voraus fest, wie viele Beschäftigte er mit welcher Qualifikation wann und wo braucht.", "o": ["Personalplanung", "Personalverwaltung", "Personalcontrolling", "Personalführung"], "c": 0, "e": "Die vorausschauende Festlegung von Anzahl, Qualifikation, Zeitpunkt und Ort heißt Personalplanung. Verwaltung, Controlling und Führung sind andere Aufgaben der Personalwirtschaft."}, {"q": "Was bedeutet das Wort quantitativ in der Personalplanung?", "o": ["Mengenmäßig, es geht um die Zahl der Kräfte", "Nach Art und Güte der Fähigkeiten", "Nach dem Ort, an dem gearbeitet wird", "Nach den Kosten, die eine Kraft verursacht"], "c": 0, "e": "Quantitativ heißt mengenmäßig. Die Frage nach den Fähigkeiten ist die qualitative Seite der Planung."}, {"q": "In welcher Reihenfolge läuft die Bedarfsrechnung ab?", "o": ["Bruttobedarf, Fortschreibung des Bestands, Nettobedarf, Maßnahmen", "Nettobedarf, Bruttobedarf, Fortschreibung des Bestands, Maßnahmen", "Maßnahmen, Bruttobedarf, Nettobedarf, Fortschreibung des Bestands", "Fortschreibung des Bestands, Maßnahmen, Nettobedarf, Bruttobedarf"], "c": 0, "e": "Zuerst wird der gesamte Bedarf ermittelt, dann der Bestand fortgeschrieben. Aus beidem folgt der Nettobedarf, erst danach plant der Betrieb Maßnahmen."}, {"q": "Was kostet es den Betrieb, wenn er dauerhaft mehr Personal hat, als er braucht?", "o": ["Der Betrieb zahlt Löhne, obwohl die Arbeit fehlt", "Die Zuschläge für Überstunden steigen stark an", "Kunden müssen länger auf ihre Räder warten", "Die Beschäftigten sind dauernd überlastet"], "c": 0, "e": "Zu viel Personal verursacht Kosten ohne Gegenleistung. Überstunden, Lieferverzug und Überlastung sind typische Folgen einer Unterbesetzung."}, {"q": "Wie hängen die wirtschaftlichen und die sozialen Ziele der Personalplanung zusammen?", "o": ["Zufriedene Beschäftigte kündigen seltener, das spart Kosten", "Die Ziele schließen sich in jedem Fall gegenseitig aus", "Soziale Ziele gelten nur in Betrieben ohne Gewinnabsicht", "Wirtschaftliche Ziele gelten nur für die Geschäftsführung"], "c": 0, "e": "Die Ziele stehen nicht zwingend im Widerspruch. Weniger Kündigungen und Fehlzeiten sparen Kosten für Suche und Einarbeitung."}, {"q": "Welcher Teilplan legt fest, wer welche Weiterbildung erhält?", "o": ["Die Personalentwicklungsplanung", "Die Personaleinsatzplanung", "Die Personalkostenplanung", "Die Personalbeschaffungsplanung"], "c": 0, "e": "Die Entwicklungsplanung bestimmt die Weiterbildungen. Die Einsatzplanung verteilt das vorhandene Personal auf Stellen und Schichten."}, {"q": "Was ist mit der Konjunktur als Einflussgröße auf den Personalbedarf gemeint?", "o": ["Die allgemeine Lage der Wirtschaft", "Die Zahl der Beschäftigten im Betrieb", "Der Altersaufbau der Bevölkerung", "Die Lage der Pausen am Arbeitstag"], "c": 0, "e": "Konjunktur bezeichnet die allgemeine Wirtschaftslage. Sie wirkt von außen auf die Nachfrage und damit auf den Personalbedarf."}, {"q": "Welche Wirkung hat der demografische Wandel auf die Personalplanung?", "o": ["Ersatz für erfahrene Fachkräfte zu finden wird schwieriger", "Der Bedarf an Personal sinkt in jedem Betrieb von allein", "Die gesetzliche Wochenarbeitszeit wird dadurch verlängert", "Die Zahl der Auszubildenden steigt automatisch jedes Jahr"], "c": 0, "e": "Gehen viele erfahrene Fachkräfte in Rente, steigt der Ersatzbedarf, und passende Nachfolger sind schwerer zu finden."}, {"q": "Worüber berät der Arbeitgeber nach § 92 BetrVG mit dem Betriebsrat?", "o": ["Über Art und Umfang der Maßnahmen und die Vermeidung von Härten", "Über die Höhe des Gewinns und die Verteilung an die Gesellschafter", "Über die Verkaufspreise der E-Bikes im nächsten Katalog", "Über die Auswahl der Lieferanten für Rahmen und Akkus"], "c": 0, "e": "Die Beratung betrifft Art und Umfang der personellen Maßnahmen und wie Härten für Beschäftigte vermieden werden (§ 92 BetrVG)."}, {"q": "Welchen Nutzen hat es, wenn der Betriebsrat früh und offen an der Planung beteiligt wird?", "o": ["Gerüchte und Misstrauen im Betrieb werden vermieden", "Der Plan muss danach niemandem mehr erklärt werden", "Der Betrieb braucht dann keine Bedarfsrechnung mehr", "Die Beschäftigten verlieren ihr Recht auf Kündigung"], "c": 0, "e": "Eine frühe Beteiligung schafft Vertrauen, und gute Vorschläge des Betriebsrats fließen rechtzeitig in die Planung ein."}, {"q": "Wie heißt der Teil des Bruttobedarfs, der nur die eigentliche Arbeit abdeckt, ohne Zuschlag für Ausfälle?", "o": ["Einsatzbedarf", "Reservebedarf", "Ersatzbedarf", "Minderbedarf"], "c": 0, "e": "Der Einsatzbedarf umfasst die Menschen für die eigentliche Arbeit. Der Reservebedarf kommt für Urlaub, Krankheit und Weiterbildung hinzu."}, {"q": "Was bedeutet es, den Personalbestand fortzuschreiben?", "o": ["Den heutigen Bestand bis zum Planungszeitpunkt weiterrechnen", "Den Stellenplan des Vorjahres unverändert neu ausdrucken", "Die Personalakten aller Beschäftigten handschriftlich ergänzen", "Die Gehälter aller Beschäftigten für das Folgejahr erhöhen"], "c": 0, "e": "Fortschreiben heißt, vom Ist-Bestand ausgehend die sicheren Abgänge abzuziehen und die sicheren Zugänge zu addieren."}, {"q": "Wie berücksichtigt ein Betrieb Abgänge, die nur vermutet werden?", "o": ["Über Erfahrungswerte zur Fluktuation, nicht in der Fortschreibung", "Er zieht jede Vermutung voll vom Ist-Bestand ab", "Er rechnet vermutete Abgänge als sichere Zugänge", "Er lässt jede Form von Fluktuation dauerhaft außer Acht"], "c": 0, "e": "In die Fortschreibung gehören nur feststehende Bewegungen. Unsicherheiten fängt der Betrieb eher über Erfahrungswerte zur Fluktuation auf."}, {"q": "Warum rechnet die Personalplanung meist in Vollzeitkräften statt in Köpfen?", "o": ["Teilzeitkräfte zählen nach ihrem Stundenanteil, so sind Werte vergleichbar", "Teilzeitkräfte dürfen in einer Personalplanung nicht erfasst werden", "Köpfe darf der Betrieb aus Gründen des Datenschutzes nie zählen", "Der Betriebsrat schreibt die Rechnung in Vollzeitkräften gesetzlich vor"], "c": 0, "e": "Eine Vollzeitkraft steht für die volle Wochenarbeitszeit. Zwei halbe Stellen ergeben zusammen eine Vollzeitkraft, aber zwei Köpfe."}, {"q": "Was ist ein Stellenplan?", "o": ["Eine Übersicht aller Stellen, die es im Planungsjahr geben soll", "Ein Plan, der festlegt, wer wann in welcher Schicht arbeitet", "Eine Liste aller Bewerbungen, die im Jahr eingegangen sind", "Ein Plan, der die Urlaubstage aller Beschäftigten verteilt"], "c": 0, "e": "Der Stellenplan zeigt alle Stellen des Planungsjahres, meist nach Abteilungen geordnet. Er ist die Grundlage der Stellenplanmethode."}, {"q": "Was versteht man bei der Kennzahlenmethode unter Arbeitsproduktivität?", "o": ["Die Menge, die eine Vollzeitkraft im Jahr schafft", "Den Gewinn, den der Betrieb je Rad erzielt", "Die Zahl der Krankheitstage je Beschäftigten", "Den Lohn, den eine Kraft je Stunde erhält"], "c": 0, "e": "Arbeitsproduktivität ist zum Beispiel die Zahl der Räder, die eine Vollzeitkraft im Jahr montiert. Mit ihr lässt sich der Bedarf ebenfalls berechnen."}, {"q": "Wie rechnet man den Bruttobedarf mit der Arbeitsproduktivität aus?", "o": ["Geplante Menge ÷ Menge je Vollzeitkraft", "Geplante Menge × Menge je Vollzeitkraft", "Arbeitsstunden ÷ geplante Menge", "Geplante Menge − Menge je Vollzeitkraft"], "c": 0, "e": "Man teilt die geplante Menge durch die Menge, die eine Vollzeitkraft schafft. Bei Nordstern sind das 36.000 ÷ 300 = 120."}, {"q": "Warum kombinieren viele Betriebe mehrere Verfahren der Bedarfsermittlung?", "o": ["Jedes Verfahren hat Stärken und Schwächen, zusammen wird das Ergebnis sicherer", "Ein Gesetz schreibt mindestens drei Verfahren für jede Abteilung vor", "Ein einziges Verfahren ist nur in Betrieben ohne Betriebsrat erlaubt", "Die Verfahren ergeben nur dann ein Ergebnis, wenn alle gleichzeitig laufen"], "c": 0, "e": "Kennzahlen sind genau, brauchen aber Daten. Schätzungen sind schnell, aber ungenau. Die Kombination gleicht Schwächen aus (Oechsler & Paul, 2019)."}, {"q": "Warum muss die Personalabteilung mit der Beschaffung beginnen, bevor die Produktion steigt?", "o": ["Suche und Einarbeitung neuer Kräfte brauchen Zeit", "Neue Kräfte dürfen erst nach einem Jahr Probezeit arbeiten", "Der Betriebsrat muss jeder Stellenanzeige ein Jahr vorher zustimmen", "Die Agentur für Arbeit vermittelt nur zum Jahresbeginn"], "c": 0, "e": "Die Suche nach Fachkräften kann Monate dauern, und neue Kräfte müssen eingearbeitet werden. Deshalb gehört die zeitliche Frage zur Planung."}, {"q": "Was bedeutet es, dass eine Stellenbeschreibung personenunabhängig ist?", "o": ["Sie beschreibt die Aufgaben der Stelle, nicht den Menschen darauf", "Sie darf von keiner Person im Betrieb gelesen werden", "Sie wird ohne Mitwirkung einer Führungskraft erstellt", "Sie gilt nur, solange die Stelle unbesetzt bleibt"], "c": 0, "e": "Die Stellenbeschreibung hängt an der Stelle. Sie bleibt bei einem Wechsel der Person gültig und wird nur bei neuen Aufgaben angepasst."}, {"q": "Was regelt der Eintrag Stellvertretung in einer Stellenbeschreibung?", "o": ["Wer die Aufgaben übernimmt, wenn die Stelleninhaberin fehlt", "Wer das Monatsentgelt der Stelleninhaberin überweist", "Wer die Stelleninhaberin am Jahresende beurteilt", "Wer die Pausen der Stelleninhaberin genehmigt"], "c": 0, "e": "Die Stellvertretung legt fest, wer bei Urlaub oder Krankheit einspringt. Bei der Teamleitung Montage Frühschicht ist das die Teamleitung Spätschicht."}, {"q": "Wie hängen Befugnisse und Verantwortung einer Stelle zusammen?", "o": ["Je mehr eine Stelle entscheiden darf, desto größer ist ihre Verantwortung", "Eine Stelle mit vielen Befugnissen trägt keine eigene Verantwortung", "Befugnisse und Verantwortung stehen nie in einer Stellenbeschreibung", "Verantwortung haben nur Stellen ohne jede Befugnis"], "c": 0, "e": "Wer mehr selbst entscheiden darf, muss für diese Entscheidungen auch einstehen. Deshalb stehen Befugnisse und Verantwortung zusammen in der Stellenbeschreibung."}, {"q": "Was bedeutet Kompetenz im Sinne eines Anforderungsprofils?", "o": ["Wissen und Fähigkeiten in einer Situation sinnvoll anwenden", "Das Recht, Verträge im Namen des Betriebs zu unterschreiben", "Die Zuständigkeit einer Abteilung für ein bestimmtes Thema", "Die Zahl der Jahre, die jemand schon im Beruf arbeitet"], "c": 0, "e": "Kompetenz heißt, Wissen und Fähigkeiten in einer Situation sinnvoll einzusetzen. Die vier Bereiche bilden zusammen die Handlungskompetenz."}, {"q": "Welcher andere Name wird für die Selbstkompetenz verwendet?", "o": ["Personalkompetenz", "Fachkompetenz", "Methodenkompetenz", "Führungskompetenz"], "c": 0, "e": "Selbstkompetenz heißt auch Personalkompetenz. Sie betrifft die eigene Person, etwa Zuverlässigkeit und Lernbereitschaft."}, {"q": "Eine Sachbearbeiterin beschafft gezielt Informationen und wertet sie geordnet aus. Welchen Kompetenzbereich zeigt sie damit?", "o": ["Methodenkompetenz", "Fachkompetenz", "Sozialkompetenz", "Selbstkompetenz"], "c": 0, "e": "Informationen beschaffen, Arbeit planen und Probleme systematisch lösen gehört zur Methodenkompetenz."}, {"q": "In der Eselsbrücke Hand, Kopf, Herz und Rückgrat steht das Herz für welchen Bereich?", "o": ["Sozialkompetenz", "Fachkompetenz", "Methodenkompetenz", "Selbstkompetenz"], "c": 0, "e": "Das Herz steht für den Umgang mit anderen Menschen, also für die Sozialkompetenz. Die Hand ist Fach, der Kopf Methode, das Rückgrat Selbstkompetenz."}, {"q": "Ein Monteur bildet sich freiwillig fort und lernt gern Neues dazu. Welcher Kompetenzbereich wird damit beschrieben?", "o": ["Selbstkompetenz", "Fachkompetenz", "Methodenkompetenz", "Sozialkompetenz"], "c": 0, "e": "Lernbereitschaft ist eine Eigenschaft der eigenen Person und gehört damit zur Selbstkompetenz."}, {"q": "Wozu dienen Kann-Anforderungen bei der Auswahl?", "o": ["Sie helfen, zwischen sonst gleich geeigneten Personen zu entscheiden", "Sie schließen jede Person aus, die sie nicht vollständig erfüllt", "Sie gelten nur für Auszubildende im ersten Ausbildungsjahr", "Sie ersetzen die Muss-Anforderungen, wenn niemand passt"], "c": 0, "e": "Kann-Anforderungen sind erwünscht, aber nicht zwingend. Sie geben den Ausschlag, wenn mehrere Personen die Muss-Anforderungen erfüllen."}, {"q": "Wie wird das Qualifikationsprofil einer Person auch genannt?", "o": ["Eignungsprofil", "Anforderungsprofil", "Stellenprofil", "Entgeltprofil"], "c": 0, "e": "Das Qualifikationsprofil heißt auch Eignungsprofil. Es zeigt, was eine bestimmte Person tatsächlich kann."}, {"q": "Warum werden Anforderungsprofil und Qualifikationsprofil mit derselben Skala erstellt?", "o": ["Nur so lassen sich die Profile Stufe für Stufe vergleichen", "Weil das Arbeitszeitgesetz eine Skala von 1 bis 5 vorschreibt", "Damit die Entgeltgruppe automatisch aus der Skala folgt", "Weil der Betriebsrat jede andere Skala verbieten muss"], "c": 0, "e": "Gleiche Kompetenzbereiche und gleiche Skala machen den Profilabgleich erst möglich. So werden Lücken und Überdeckungen sichtbar."}, {"q": "Was bedeutet Passung beim Profilabgleich?", "o": ["Anforderung und Qualifikation stimmen überein", "Die Qualifikation liegt unter der Anforderung", "Die Qualifikation liegt weit über der Anforderung", "Es gibt für die Stelle noch kein Anforderungsprofil"], "c": 0, "e": "Passung heißt, die Person kann genau das, was die Stelle verlangt. Darunter liegt eine Unterdeckung, darüber eine Überdeckung."}, {"q": "Welche drei Größen der Arbeitszeit können Arbeitszeitmodelle flexibel machen?", "o": ["Dauer, Lage und Ort der Arbeit", "Lohn, Urlaub und Ort der Arbeit", "Dauer, Lohn und Kündigungsfrist", "Urlaub, Probezeit und Lage der Arbeit"], "c": 0, "e": "Arbeitszeitmodelle legen fest, wie lange, wann und wo gearbeitet wird. Viele Modelle verbinden mehrere dieser Seiten."}, {"q": "Was ist bei der Gleitzeit die Rahmenzeit?", "o": ["Die Zeitspanne, in der überhaupt gearbeitet werden darf", "Die Zeitspanne, in der alle anwesend sein müssen", "Die Zeitspanne, in der nur Überstunden zählen", "Die Zeitspanne, in der die Pause liegen muss"], "c": 0, "e": "Die Rahmenzeit ist die Wahlzeit, bei Nordstern von 06:30 bis 19:00 Uhr. Die Kernzeit mit Anwesenheitspflicht liegt darin."}, {"q": "Was kennzeichnet Schichtarbeit?", "o": ["Gruppen von Beschäftigten arbeiten nacheinander am selben Arbeitsplatz", "Alle Beschäftigten arbeiten gleichzeitig in einer einzigen langen Schicht", "Jede Person wählt Beginn und Ende ihrer Arbeit ganz frei", "Zwei Personen teilen sich eine Stelle und stimmen sich ab"], "c": 0, "e": "Bei Schichtarbeit lösen sich Gruppen am selben Platz ab, bei Nordstern Früh- und Spätschicht. Freie Wahl ist Gleitzeit, geteilte Stellen sind Jobsharing."}, {"q": "Was wird auf einem Arbeitszeitkonto gebucht?", "o": ["Die Abweichungen der Arbeitszeit vom täglichen Soll", "Die monatlichen Entgelte aller Beschäftigten", "Die Beiträge zur Sozialversicherung", "Die Zahl der Krankheitstage im Jahr"], "c": 0, "e": "Mehrarbeit wird als Plus, weniger Arbeit als Minus gebucht. So lassen sich Schwankungen über Wochen und Monate ausgleichen."}, {"q": "Was bedeutet der Begriff Entgrenzung bei flexiblen Arbeitszeitmodellen?", "o": ["Arbeit und Freizeit verschwimmen ineinander", "Der Betrieb öffnet seine Werkstore für Kunden", "Die Wochenarbeitszeit wird tariflich begrenzt", "Die Kernzeit wird für alle Beschäftigten gestrichen"], "c": 0, "e": "Entgrenzung heißt, dass Arbeit in die Freizeit hineinreicht, etwa durch späte E-Mails zu Hause. Das Risiko ist bei Vertrauensarbeitszeit und mobilem Arbeiten besonders groß."}, {"q": "Worauf kommt es bei der Vertrauensarbeitszeit vor allem an?", "o": ["Auf das Ergebnis der Arbeit", "Auf die genaue Anwesenheit im Büro", "Auf die Zahl der Pausen am Tag", "Auf das Alter der beschäftigten Person"], "c": 0, "e": "Bei der Vertrauensarbeitszeit verzichtet der Arbeitgeber auf die Kontrolle der Anwesenheit, entscheidend ist das Ergebnis. Erfasst werden muss die Arbeitszeit trotzdem."}, {"q": "Wo hat Nordstern Kernzeit, Kontogrenzen und Schichtwechsel festgelegt?", "o": ["In Betriebsvereinbarungen mit dem Betriebsrat", "In jedem einzelnen Arbeitsvertrag getrennt", "Im Arbeitszeitgesetz für alle Betriebe", "In den Stellenbeschreibungen der Abteilungen"], "c": 0, "e": "Lage der Arbeitszeit und Pausen unterliegen der Mitbestimmung (§ 87 Abs. 1 Nr. 2 BetrVG). Deshalb regelt Nordstern sie in Betriebsvereinbarungen."}, {"q": "Ab welcher Betriebsgröße haben Beschäftigte Anspruch auf Brückenteilzeit?", "o": ["Bei mehr als 45 Beschäftigten", "Bei mehr als 15 Beschäftigten", "Bei mehr als 10 Beschäftigten", "Bei mehr als 100 Beschäftigten"], "c": 0, "e": "Die Brückenteilzeit nach § 9a TzBfG setzt mehr als 45 Beschäftigte voraus. Für die allgemeine Teilzeit nach § 8 TzBfG reichen mehr als 15."}, {"q": "Welche Zeit ist nach § 2 ArbZG Nachtzeit?", "o": ["Von 23 bis 6 Uhr", "Von 20 bis 6 Uhr", "Von 22 bis 5 Uhr", "Von 0 bis 8 Uhr"], "c": 0, "e": "Nachtzeit im Sinne des Arbeitszeitgesetzes ist die Zeit von 23 bis 6 Uhr (§ 2 ArbZG)."}, {"q": "Was gilt nach § 9 ArbZG grundsätzlich an Sonn- und Feiertagen?", "o": ["Arbeitsruhe von 0 bis 24 Uhr", "Arbeit bis höchstens 6 Stunden", "Arbeit nur mit doppelter Pause", "Arbeitsruhe nur am Vormittag"], "c": 0, "e": "An Sonn- und Feiertagen dürfen Beschäftigte grundsätzlich von 0 bis 24 Uhr nicht arbeiten (§ 9 ArbZG). Ausnahmen gibt es nur für bestimmte Bereiche."}, {"q": "In welche Abschnitte darf die Ruhepause nach § 4 ArbZG aufgeteilt werden?", "o": ["In Abschnitte von mindestens 15 Minuten", "In Abschnitte von mindestens 5 Minuten", "In Abschnitte von mindestens 30 Minuten", "Eine Aufteilung ist nicht erlaubt"], "c": 0, "e": "Die Pause darf in Abschnitte von je mindestens 15 Minuten geteilt werden (§ 4 ArbZG). Kürzere Unterbrechungen zählen nicht als Pause."}, {"q": "Was ist ein Referentenentwurf?", "o": ["Ein erster Gesetzesentwurf aus einem Ministerium", "Ein Urteil des Bundesarbeitsgerichts", "Ein fertiges Gesetz, das schon gilt", "Eine Betriebsvereinbarung mit dem Betriebsrat"], "c": 0, "e": "Ein Referentenentwurf ist der erste Entwurf eines Ministeriums. Bis zum Inkrafttreten fehlen noch mehrere Schritte (Handwerkskammer Niederbayern-Oberpfalz, 2026)."}, {"q": "Aus welcher Vorschrift leitet das Bundesarbeitsgericht die Pflicht zur Erfassung der Arbeitszeit ab?", "o": ["§ 3 Abs. 2 Nr. 1 ArbSchG", "§ 16 Abs. 2 ArbZG", "§ 8 TzBfG", "§ 92 BetrVG"], "c": 0, "e": "Das BAG stützt die Pflicht auf das Arbeitsschutzgesetz und legt es im Licht des europäischen Rechts aus (BAG, 2022). § 16 Abs. 2 ArbZG betrifft nur Zeiten über 8 Stunden."}, {"q": "Bleibt der fortgeschriebene Bestand der Montage bei 95 Vollzeitkräften und sinkt der Bruttobedarf durch die bessere Linie auf 100, wie hoch ist dann der Nettobedarf?", "o": ["5 Vollzeitkräfte", "25 Vollzeitkräfte", "−5 Vollzeitkräfte", "0 Vollzeitkräfte"], "c": 0, "e": "Nettobedarf = 100 − 95 = 5. Es bleibt ein kleiner Beschaffungsbedarf, der nur noch die Abgänge teilweise ersetzt."}, {"q": "An einer neuen Prüfstrecke müssen täglich 20 Plätze besetzt sein. Die Ausfallquote beträgt 15 %. Wie hoch ist der Bruttobedarf?", "o": ["23 Personen", "20 Personen", "21 Personen", "35 Personen"], "c": 0, "e": "Reservebedarf 20 × 15 % = 3 Personen. Bruttobedarf = Einsatzbedarf 20 + Reservebedarf 3 = 23 Personen."}, {"q": "Der Bruttobedarf einer Abteilung beträgt 46 Vollzeitkräfte, der fortgeschriebene Bestand ebenfalls 46. Was folgt daraus?", "o": ["Es besteht weder Beschaffungs- noch Freistellungsbedarf", "Es besteht ein Beschaffungsbedarf von 46 Kräften", "Es besteht ein Freistellungsbedarf von 46 Kräften", "Die Abteilung muss aufgelöst werden"], "c": 0, "e": "Nettobedarf = 46 − 46 = 0. Der Bestand deckt den Bedarf genau, es sind keine Einstellungen und keine Freistellungen nötig."}, {"q": "In einer Abteilung arbeiten 12 Vollzeitkräfte mit 35 Stunden und 6 Teilzeitkräfte mit je 17,5 Stunden. Wie viele Vollzeitkräfte sind das?", "o": ["15 Vollzeitkräfte", "18 Vollzeitkräfte", "12 Vollzeitkräfte", "21 Vollzeitkräfte"], "c": 0, "e": "Eine Kraft mit 17,5 Stunden ist eine halbe Vollzeitkraft. 12 + 6 × 0,5 = 15 Vollzeitkräfte, aber 18 Köpfe."}, {"q": "Ein Nettobedarf von 4 Vollzeitkräften soll ausschließlich mit Stellen zu je 28 Stunden pro Woche gedeckt werden. Wie viele Personen braucht Nordstern?", "o": ["5 Personen", "4 Personen", "6 Personen", "8 Personen"], "c": 0, "e": "Eine Stelle mit 28 Stunden entspricht 28 ÷ 35 = 0,8 Vollzeitkräften. 4 ÷ 0,8 = 5 Personen."}, {"q": "Die IT von Nordstern soll 2027 statt 10 nun 11 Stellen bekommen. Heute sind 9 Stellen besetzt, eine Person geht sicher in Rente. Wie hoch ist der Nettobedarf der IT?", "o": ["3 Stellen", "2 Stellen", "1 Stelle", "4 Stellen"], "c": 0, "e": "Fortgeschriebener Bestand 9 − 1 = 8. Nettobedarf 11 − 8 = 3, davon 1 Ersatzbedarf und 2 Neubedarf."}, {"q": "Eine Monteurin in EG 7 möchte bei Nordstern von 35 auf 28 Wochenstunden wechseln. Wie wirkt sich das auf die Personalplanung der Montage aus?", "o": ["Es fehlen 0,2 Vollzeitkräfte, der Nettobedarf steigt entsprechend", "Es fehlt eine ganze Vollzeitkraft, weil ein Kopf wegfällt", "Der Bedarf sinkt um 0,8 Vollzeitkräfte, weil sie Teilzeit arbeitet", "Nichts ändert sich, weil sie weiterhin im Betrieb bleibt"], "c": 0, "e": "Sie zählt künftig 28 ÷ 35 = 0,8 Vollzeitkräfte. Es fehlen 0,2 Vollzeitkräfte, die der Betrieb anders decken muss."}, {"q": "Malte Brandt will dem Betriebsrat die Personalplanung 2027 erst zeigen, wenn alle Stellenanzeigen veröffentlicht sind. Wie ist das zu beurteilen?", "o": ["Unzulässig, der Betriebsrat ist rechtzeitig vorher zu unterrichten", "Zulässig, weil der Betriebsrat ohnehin nicht zustimmen muss", "Zulässig, weil die Planung ein Geschäftsgeheimnis ist", "Unzulässig, weil jede Anzeige vom Betriebsrat geschrieben wird"], "c": 0, "e": "Der Arbeitgeber muss rechtzeitig und umfassend unterrichten und mit dem Betriebsrat beraten (§ 92 BetrVG). Dass kein Zustimmungsrecht besteht, erlaubt keine späte Unterrichtung."}, {"q": "Petra Holm schlägt als Betriebsratsvorsitzende vor, mehr Auszubildende zu übernehmen. Wie muss Nordstern damit umgehen?", "o": ["Den Vorschlag beraten, ohne an ihn gebunden zu sein", "Den Vorschlag ohne Prüfung umsetzen", "Den Vorschlag als unzulässig ablehnen", "Den Vorschlag dem Arbeitsgericht vorlegen"], "c": 0, "e": "Der Betriebsrat hat bei der Personalplanung ein Vorschlagsrecht (§ 92 BetrVG). Der Arbeitgeber berät darüber, entscheidet aber selbst."}, {"q": "Eine Abteilung fertigt 2027 insgesamt 24.000 Bauteile mit je 0,5 Stunden Arbeitszeit. Eine Vollzeitkraft leistet 1.500 produktive Stunden. Wie hoch ist der Bruttobedarf?", "o": ["8 Vollzeitkräfte", "16 Vollzeitkräfte", "12 Vollzeitkräfte", "5 Vollzeitkräfte"], "c": 0, "e": "Arbeitszeitbedarf 24.000 × 0,5 = 12.000 Stunden. Bruttobedarf 12.000 ÷ 1.500 = 8 Vollzeitkräfte."}, {"q": "Die Teamleitung Montage Frühschicht möchte allein Material für 800 € bestellen. Was gilt nach ihrer Stellenbeschreibung bei Nordstern?", "o": ["Sie darf allein nur bis 500 € bestellen", "Sie darf jede Summe allein bestellen", "Sie darf überhaupt kein Material bestellen", "Sie darf allein bis 1.000 € bestellen"], "c": 0, "e": "In der Stellenbeschreibung steht die Befugnis, Material bis 500 € zu bestellen. Für 800 € braucht sie die Freigabe der Leitung Montage."}, {"q": "Eine Bewerberin erfüllt alle Kann-Anforderungen, liegt aber bei einer Muss-Anforderung deutlich unter der verlangten Stufe. Was folgt daraus für die Auswahl?", "o": ["Sie kommt für die Stelle so nicht infrage", "Sie wird wegen der Kann-Anforderungen sofort eingestellt", "Die Muss-Anforderung wird für sie gestrichen", "Kann-Anforderungen gleichen jede Lücke aus"], "c": 0, "e": "Muss-Anforderungen sind zwingend. Wer sie nicht erfüllt, kommt nicht infrage, auch wenn alle Kann-Anforderungen erfüllt sind."}, {"q": "Zwei interne Kräfte erfüllen alle Muss-Anforderungen der Teamleitung Montage gleich gut. Nur eine von ihnen spricht gut Englisch. Was gibt bei Nordstern den Ausschlag?", "o": ["Die Kann-Anforderung Englischkenntnisse für Lieferanten", "Das Alter der beiden Personen", "Die Entfernung von der Wohnung zum Werk", "Der Familienstand der beiden Personen"], "c": 0, "e": "Englisch ist im Anforderungsprofil eine Kann-Anforderung. Sie hilft bei der Wahl zwischen sonst gleich geeigneten Personen. Alter, Wohnort und Familienstand sind keine Anforderungen der Stelle."}, {"q": "Jonas Petersen hat das Führungsseminar und die Schulung zur Schichtplanung abgeschlossen. Wie verändert sich sein Profilabgleich mit der Teamleitung?", "o": ["Aus der Unterdeckung wird eine Passung", "Aus der Passung wird eine Unterdeckung", "Aus der Überdeckung wird eine Unterdeckung", "Am Profilabgleich ändert sich nichts"], "c": 0, "e": "Vorher fehlte bei Methode und Sozial je eine Stufe. Schließen die Maßnahmen diese Lücken, stimmen Anforderung und Qualifikation überein."}, {"q": "Ein Gleitzeitkonto steht bei plus 48 Stunden. In der nächsten Woche arbeitet die Person 41 Stunden bei einem Soll von 35 Stunden. Wie hoch ist der neue Stand?", "o": ["Plus 54 Stunden, die Grenze ist eingehalten", "Plus 54 Stunden, die Grenze ist überschritten", "Plus 89 Stunden, die Grenze ist überschritten", "Plus 42 Stunden, die Grenze ist eingehalten"], "c": 0, "e": "Die Woche bringt 41 − 35 = 6 Plusstunden. 48 + 6 = 54 Stunden, das liegt unter der Grenze von plus 60 Stunden."}, {"q": "Ein Konto steht bei minus 14 Stunden. In der folgenden Woche werden nur 29 Stunden gearbeitet, das Soll sind 35. Was gilt nach den Regeln von Nordstern?", "o": ["Der Stand beträgt minus 20 Stunden, die Grenze ist gerade noch eingehalten", "Der Stand beträgt minus 20 Stunden, die Grenze ist um 6 Stunden überschritten", "Der Stand beträgt minus 8 Stunden, die Grenze ist eingehalten", "Der Stand beträgt minus 43 Stunden, die Grenze ist überschritten"], "c": 0, "e": "Die Woche bringt 29 − 35 = −6 Stunden. −14 − 6 = −20 Stunden. Das ist genau die untere Grenze von minus 20 Stunden."}, {"q": "Ein Konto steht bei plus 58 Stunden. Für die Inventur sind 4 weitere Plusstunden geplant. Was muss die Führungskraft tun?", "o": ["Für Ausgleich sorgen, weil 62 Stunden die Grenze um 2 überschreiten", "Nichts, weil 62 Stunden noch innerhalb der Grenze liegen", "Das Konto auf null setzen und die Stunden streichen", "Die Grenze für diese Person auf 100 Stunden erhöhen"], "c": 0, "e": "58 + 4 = 62 Stunden überschreiten die Grenze von plus 60 Stunden um 2. Die Führungskraft muss vorher für Ausgleich sorgen, etwa durch Freizeit."}, {"q": "Aylin Demir beginnt um 06:30 Uhr und will so lange wie erlaubt arbeiten. Sie macht die vorgeschriebene Pause. Wann muss sie spätestens gehen?", "o": ["Um 17:15 Uhr", "Um 16:30 Uhr", "Um 17:00 Uhr", "Um 19:00 Uhr"], "c": 0, "e": "Höchstens 10 Stunden Arbeit, bei mehr als 9 Stunden mindestens 45 Minuten Pause. 06:30 Uhr plus 10 Stunden 45 Minuten ergibt 17:15 Uhr."}, {"q": "Lisa Wagner wechselt auf 28 Stunden pro Woche an vier Tagen. Wie hoch ist ihr tägliches Soll?", "o": ["7 Stunden", "5,6 Stunden", "8 Stunden", "6 Stunden"], "c": 0, "e": "28 Stunden ÷ 4 Tage = 7 Stunden am Tag. Bei fünf Tagen wären es 5,6 Stunden."}, {"q": "Sven Krüger kommt um 07:10 Uhr, geht um 15:10 Uhr und macht 30 Minuten Pause. Sein Soll beträgt 7 Stunden. Wie verändert sich sein Zeitkonto?", "o": ["Plus 30 Minuten", "Plus 1 Stunde", "Minus 30 Minuten", "Plus 1 Stunde 30 Minuten"], "c": 0, "e": "Arbeitszeit = 8 Stunden Anwesenheit − 30 Minuten Pause = 7 Stunden 30 Minuten. Saldo = 7 Stunden 30 Minuten − 7 Stunden = plus 30 Minuten."}, {"q": "Jonas Petersen arbeitet mit Jahresarbeitszeit im Mai 40 und im November 30 Stunden pro Woche. Was gilt für sein Monatsgrundentgelt in EG 7?", "o": ["Es bleibt in beiden Monaten bei 3.600 €", "Es steigt im Mai und sinkt im November", "Es wird nur im Mai voll ausgezahlt", "Es wird erst am Jahresende ausgezahlt"], "c": 0, "e": "Bei der Jahresarbeitszeit schwanken die Stunden, das Monatsentgelt bleibt gleich. Im Jahresdurchschnitt ergibt sich die vereinbarte Stundenzahl."}, {"q": "Eine Sachbearbeiterin ist erst seit vier Monaten bei Nordstern Fahrradwerke beschäftigt und will Teilzeit nach § 8 TzBfG verlangen. Wie ist die Lage?", "o": ["Noch kein Anspruch, das Arbeitsverhältnis muss länger als 6 Monate bestehen", "Anspruch besteht, weil Nordstern mehr als 15 Beschäftigte hat", "Kein Anspruch, weil Nordstern mehr als 45 Beschäftigte hat", "Anspruch besteht nur, wenn der Betriebsrat zustimmt"], "c": 0, "e": "Beide Voraussetzungen müssen erfüllt sein. Nordstern ist groß genug, aber die Wartezeit von mehr als 6 Monaten fehlt noch (§ 8 TzBfG)."}, {"q": "Ein Monteur arbeitet genau 9 Stunden. Welche Pause ist nach § 4 ArbZG mindestens vorgeschrieben?", "o": ["30 Minuten", "45 Minuten", "60 Minuten", "15 Minuten"], "c": 0, "e": "45 Minuten gelten erst bei mehr als 9 Stunden. Bei genau 9 Stunden reichen 30 Minuten."}, {"q": "In der Verwaltung soll jemand von 06:30 bis 17:00 Uhr mit 30 Minuten Pause arbeiten. Wie ist der Plan nach dem ArbZG zu beurteilen?", "o": ["Unzulässig, bei 10 Stunden Arbeit sind 45 Minuten Pause nötig", "Zulässig, weil die Arbeitszeit genau 10 Stunden beträgt", "Unzulässig, weil mehr als 8 Stunden nie erlaubt sind", "Zulässig, weil die Rahmenzeit eingehalten wird"], "c": 0, "e": "Anwesenheit 10 Stunden 30 Minuten minus 30 Minuten ergibt 10 Stunden Arbeit. Das ist die Höchstgrenze, aber bei mehr als 9 Stunden sind 45 Minuten Pause Pflicht (§ 4 ArbZG)."}, {"q": "Ein Beschäftigter arbeitet bis 22:30 Uhr und soll am nächsten Morgen um 08:00 Uhr beginnen. Was gilt?", "o": ["Unzulässig, die Ruhezeit beträgt nur 9,5 Stunden", "Zulässig, die Ruhezeit beträgt mehr als 8 Stunden", "Unzulässig, nach 22 Uhr darf nie gearbeitet werden", "Zulässig, weil er am nächsten Tag kürzer arbeitet"], "c": 0, "e": "Von 22:30 bis 08:00 Uhr sind es 9 Stunden 30 Minuten. Nötig sind mindestens 11 Stunden ununterbrochene Ruhezeit (§ 5 ArbZG)."}, {"q": "Ein Monteur hat in einer Woche Frühschicht bis 13:30 Uhr und beginnt am nächsten Tag die Spätschicht um 13:30 Uhr. Wie ist dieser Wechsel zu beurteilen?", "o": ["Zulässig, die Ruhezeit beträgt 24 Stunden", "Unzulässig, die Ruhezeit beträgt nur 9 Stunden", "Unzulässig, Schichtwechsel sind nur sonntags erlaubt", "Zulässig, aber nur mit Zustimmung jedes Kunden"], "c": 0, "e": "Von 13:30 Uhr bis 13:30 Uhr am Folgetag liegen 24 Stunden. Kritisch ist nur der Wechsel von Spät auf Früh mit 9 Stunden Ruhezeit."}, {"q": "Die Spätschicht der Montage endet um 21:00 Uhr. Arbeiten die Monteure damit in der Nachtzeit nach dem ArbZG?", "o": ["Nein, die Nachtzeit beginnt erst um 23 Uhr", "Ja, die Nachtzeit beginnt schon um 20 Uhr", "Ja, jede Arbeit nach 18 Uhr ist Nachtarbeit", "Nein, Schichtarbeit ist nie Nachtarbeit"], "c": 0, "e": "Nachtzeit ist die Zeit von 23 bis 6 Uhr (§ 2 ArbZG). Die Spätschicht endet vorher."}, {"q": "Wie viele Stunden dürfen Erwachsene in einer Woche mit sechs Werktagen höchstens arbeiten, wenn der Ausgleich nach § 3 ArbZG gesichert ist?", "o": ["60 Stunden, also 6 × 10 Stunden", "48 Stunden, also 6 × 8 Stunden", "50 Stunden, also 5 × 10 Stunden", "70 Stunden, also 7 × 10 Stunden"], "c": 0, "e": "An jedem Werktag sind bis zu 10 Stunden möglich, wenn im Durchschnitt von 6 Kalendermonaten oder 24 Wochen 8 Stunden nicht überschritten werden. Kurzfristig ergeben sich so 60 Stunden."}, {"q": "Die Lagerleitung plant die Inventur bei Nordstern an einem Sonntag. Wie ist das nach dem ArbZG zu beurteilen?", "o": ["Grundsätzlich unzulässig, an Sonntagen gilt Arbeitsruhe", "Zulässig, weil Sonntag ein normaler Werktag ist", "Zulässig, wenn die Pausen verdoppelt werden", "Unzulässig nur für Beschäftigte in Teilzeit"], "c": 0, "e": "An Sonn- und Feiertagen gilt grundsätzlich Arbeitsruhe von 0 bis 24 Uhr (§ 9 ArbZG). Der Samstag ist dagegen ein Werktag."}, {"q": "Mia Schulz ist 17 Jahre alt. Ihre Abteilung möchte, dass sie an einem Tag 9 Stunden arbeitet. Was gilt?", "o": ["Unzulässig, für sie gilt das JArbSchG mit höchstens 8 Stunden täglich", "Zulässig, weil das ArbZG bis 10 Stunden am Tag erlaubt", "Zulässig, wenn sie dafür 45 Minuten Pause macht", "Unzulässig, weil Auszubildende höchstens 6 Stunden arbeiten"], "c": 0, "e": "Für Jugendliche unter 18 Jahren gilt das JArbSchG mit höchstens 8 Stunden täglich und 40 Stunden wöchentlich (§ 8 JArbSchG). Die 10 Stunden des ArbZG gelten für sie nicht."}, {"q": "Leon Becker ist 19 Jahre alt und Auszubildender bei Nordstern. Welche Arbeitszeitregeln gelten für ihn?", "o": ["Die Regeln des ArbZG für Erwachsene", "Die Regeln des JArbSchG für Jugendliche", "Keine Regeln, weil er Auszubildender ist", "Nur die Regeln seines Arbeitszeitkontos"], "c": 0, "e": "Das JArbSchG gilt nur bis unter 18 Jahre. Mit 19 Jahren fällt Leon unter das ArbZG mit 8 Stunden, bis 10 Stunden mit Ausgleich."}, {"q": "Im Vertrieb von Nordstern wird Vertrauensarbeitszeit eingeführt. Die Leitung sagt, damit entfalle jede Zeiterfassung. Wie ist das zu beurteilen?", "o": ["Falsch, die Pflicht zur Erfassung nach dem BAG bleibt bestehen", "Richtig, Vertrauensarbeitszeit schließt jede Erfassung aus", "Richtig, die Pflicht gilt nur für die Montage im Schichtbetrieb", "Falsch, ab sofort ist eine Stempeluhr gesetzlich vorgeschrieben"], "c": 0, "e": "Vertrauensarbeitszeit verzichtet auf Kontrolle der Anwesenheit, nicht auf die Erfassung (BAG, 2022). Eine bestimmte Form wie die Stempeluhr ist nicht vorgeschrieben."}, {"q": "Ein Monteur arbeitet an einem Tag 9 Stunden. Welche Pflicht ergibt sich für Nordstern unmittelbar aus § 16 Abs. 2 ArbZG?", "o": ["Die Stunde über 8 Stunden aufzeichnen und 2 Jahre aufbewahren", "Die Stunde über 8 Stunden der Krankenkasse melden", "Die Stunde über 8 Stunden mit 50 % Zuschlag bezahlen", "Die Stunde über 8 Stunden vom Betriebsrat genehmigen lassen"], "c": 0, "e": "§ 16 Abs. 2 ArbZG verlangt, die Arbeitszeit über 8 Stunden werktäglich aufzuzeichnen und mindestens 2 Jahre aufzubewahren. Zuschläge regelt das ArbZG hier nicht."}, {"q": "Kann Nordstern den dauerhaften Nettobedarf von 25 Vollzeitkräften in der Montage über Arbeitszeitkonten decken?", "o": ["Nein, Konten fangen nur kurzfristige Schwankungen auf", "Ja, jede Kraft sammelt dafür einfach dauerhaft Plusstunden", "Ja, wenn alle Beschäftigten in Vertrauensarbeitszeit arbeiten", "Nein, weil Arbeitszeitkonten in der Montage verboten sind"], "c": 0, "e": "Die Kontogrenze von plus 60 Stunden wäre schnell erreicht. Ein dauerhaft höherer Bedarf verlangt zusätzliche Kräfte, nicht nur mehr Stunden."}], "lernen": [{"t": "Personalplanung", "x": "Vorausschauende Festlegung, wie viele Beschäftigte mit welcher Qualifikation wann und wo gebraucht werden."}, {"t": "Bruttopersonalbedarf", "x": "Gesamter Bedarf an Arbeitskräften zum Planungszeitpunkt, also Einsatzbedarf plus Reservebedarf."}, {"t": "Reservebedarf", "x": "Zuschlag für Ausfälle durch Urlaub, Krankheit und Weiterbildung."}, {"t": "Fortgeschriebener Personalbestand", "x": "Ist-Bestand minus sichere Abgänge plus sichere Zugänge bis zum Planungszeitpunkt."}, {"t": "Nettopersonalbedarf", "x": "Bruttopersonalbedarf minus fortgeschriebener Bestand. Positiv heißt beschaffen, negativ heißt Minderbedarf."}, {"t": "Ersatzbedarf", "x": "Bedarf, um ausscheidende Beschäftigte zu ersetzen, etwa nach Rente oder Kündigung."}, {"t": "Neubedarf", "x": "Bedarf an zusätzlichen Stellen, etwa durch mehr Produktion oder kürzere Arbeitszeit. Auch Zusatz- oder Mehrbedarf genannt."}, {"t": "Minderbedarf", "x": "Negativer Nettobedarf. Der Betrieb hat mehr Personal, als er braucht, man spricht auch von Freistellungsbedarf."}, {"t": "Stellenplan", "x": "Übersicht aller Stellen, die es im Planungsjahr geben soll, meist nach Abteilungen geordnet."}, {"t": "Kennzahlenmethode", "x": "Bedarfsermittlung mit Zahlen aus dem Betrieb, etwa Arbeitszeitbedarf geteilt durch Jahresstunden je Kraft."}, {"t": "Stellenbeschreibung", "x": "Schriftliche, personenunabhängige Beschreibung einer Stelle mit Einordnung, Ziel, Aufgaben und Befugnissen."}, {"t": "Anforderungsprofil", "x": "Übersicht, welche Fach-, Methoden-, Sozial- und Selbstkompetenz eine Stelle verlangt."}, {"t": "Profilabgleich", "x": "Vergleich von Anforderungsprofil und Qualifikationsprofil einer Person, um Lücken zu erkennen."}, {"t": "Kernzeit", "x": "Teil der Gleitzeit mit Anwesenheitspflicht, bei Nordstern von 09:00 bis 14:00 Uhr."}, {"t": "Arbeitszeitkonto", "x": "Konto für Plus- und Minusstunden, bei Nordstern zwischen plus 60 und minus 20 Stunden."}, {"t": "Ruhezeit", "x": "Ununterbrochene Freizeit nach dem Ende der täglichen Arbeit, für Erwachsene mindestens 11 Stunden."}, {"t": "Personalbestandsplanung", "x": "Teilplan mit der Leitfrage Wen haben wir? Er erfasst den heutigen Bestand und seine sicheren Veränderungen."}, {"t": "Stellenbesetzungsplan", "x": "Stellenplan, der zusätzlich zeigt, welche Person auf welcher Stelle sitzt. Er liefert den Ist-Bestand."}, {"t": "Stellenausschreibung", "x": "Bekanntmachung einer freien Stelle intern oder extern. Sie beruht auf der Stellenbeschreibung."}, {"t": "Arbeit auf Abruf", "x": "Arbeit nach Arbeitsanfall. Ohne vereinbarte Wochenstunden gelten 20 Stunden, Ankündigung mindestens vier Tage vorher."}, {"t": "Kurzarbeit", "x": "Vorübergehend verkürzte Arbeitszeit bei Arbeitsausfall. Die Agentur für Arbeit zahlt Kurzarbeitergeld."}, {"t": "Sabbatical", "x": "Längere Auszeit von mehreren Monaten mit Rückkehr auf die bisherige Stelle."}, {"t": "Personalplanung", "x": "Personalplanung ist die vorausschauende Festlegung, wie viele Beschäftigte mit welcher Qualifikation zu welchem Zeitpunkt an welchem Ort benötigt werden (Beiderwieden & Stickdorn, 2026)."}, {"t": "Zwei Zielgruppen", "x": "Wirtschaftliche Ziele schützen den Betrieb vor Kosten und Lieferproblemen. Soziale Ziele schützen die Beschäftigten vor Überlastung und Unsicherheit. Gute Personalplanung verbindet beide."}, {"t": "Brutto und Netto", "x": "Bruttopersonalbedarf ist Einsatzbedarf plus Reservebedarf. Nettopersonalbedarf ist Bruttopersonalbedarf minus fortgeschriebener Personalbestand (Beiderwieden & Stickdorn, 2026)."}, {"t": "Positiv oder negativ", "x": "Ein positiver Nettobedarf führt zur Beschaffung, ein negativer zur Freistellungsplanung. Zuerst prüft der Betrieb interne Lösungen wie Versetzung oder das Nichtbesetzen frei werdender Stellen."}, {"t": "Qualitativer Personalbedarf", "x": "Der qualitative Personalbedarf beschreibt, welche Kenntnisse, Fähigkeiten und Eigenschaften die Beschäftigten für ihre Stellen benötigen (Beiderwieden & Stickdorn, 2026)."}, {"t": "Stelle statt Person", "x": "Die Stellenbeschreibung beschreibt die Stelle, nicht den Menschen. Sie bleibt gültig, wenn die Stelle neu besetzt wird, und muss nur angepasst werden, wenn sich die Aufgaben ändern."}, {"t": "Dauer, Lage, Ort", "x": "Jedes Arbeitszeitmodell lässt sich danach einordnen, ob es die Dauer, die Lage oder den Ort der Arbeit flexibel macht. Viele Modelle verbinden mehrere dieser Seiten."}, {"t": "Kurzarbeit", "x": "Vorübergehende Verkürzung der Arbeitszeit bei erheblichem Arbeitsausfall. Die Agentur für Arbeit gleicht einen Teil des Entgeltausfalls mit Kurzarbeitergeld aus (§ 104 SGB III)."}, {"t": "Die Zahlenreihe 8, 10, 30, 45, 11", "x": "8 Stunden Regel, 10 Stunden höchstens mit Ausgleich, 30 Minuten Pause ab mehr als 6 Stunden, 45 Minuten ab mehr als 9 Stunden, 11 Stunden Ruhezeit."}, {"t": "Werktag", "x": "Werktage sind alle Tage von Montag bis Samstag, die keine gesetzlichen Feiertage sind. Deshalb erlaubt die 8-Stunden-Regel rechnerisch 48 Stunden pro Woche (§ 3 ArbZG)."}, {"t": "Referentenentwurf", "x": "Ein Referentenentwurf ist ein erster Gesetzesentwurf aus einem Ministerium. Danach folgen Kabinettsbeschluss, Beratung im Bundestag und Bundesrat und die Verkündung. Erst dann gilt das Gesetz (Handwerkskammer Niederbayern-Oberpfalz, 2026)."}], "sortier": [{"titel": "Welcher Personalbedarf entsteht?", "auftrag": "Ordne jeden Fall der Art von Personalbedarf zu, die er bei Nordstern auslöst.", "kategorien": [{"id": "a", "name": "Ersatzbedarf"}, {"id": "b", "name": "Neubedarf"}, {"id": "c", "name": "Reservebedarf"}], "items": [{"text": "Vier Monteure gehen 2027 in Rente", "kat": "a", "expl": "Die Stellen gibt es weiter, nur die Personen gehen. Ersatzbedarf ersetzt solche Abgänge."}, {"text": "Drei Monteure kündigen 2027 selbst", "kat": "a", "expl": "Eine Kündigung ist ein Abgang. Die Stelle muss neu besetzt werden, das ist Ersatzbedarf."}, {"text": "Ein befristeter Vertrag im Lager läuft aus", "kat": "a", "expl": "Endet eine Befristung, fällt eine Person weg. Für sie entsteht Ersatzbedarf."}, {"text": "Eine Sachbearbeiterin geht in Elternzeit", "kat": "a", "expl": "Elternzeit zählt als Abgang auf Zeit. Die Vertretung ist Ersatzbedarf."}, {"text": "Zwei Beschäftigte im Rechnungswesen gehen in Rente", "kat": "a", "expl": "Im Stellenplan bleiben die Stellen gleich. Es geht nur um Ersatz für die Abgänge."}, {"text": "Produktion steigt von 30.000 auf 36.000 Räder", "kat": "b", "expl": "Mehr Räder brauchen 20 zusätzliche Vollzeitkräfte. Zusätzliche Stellen sind Neubedarf."}, {"text": "Neue Teamleitung in der Frühschicht der Montage", "kat": "b", "expl": "Diese Stelle gab es bisher nicht. Darum ist es Neubedarf."}, {"text": "Stellenplan Personal 2027 sieht 7 statt 6 Stellen vor", "kat": "b", "expl": "Eine Stelle kommt neu hinzu. Das ist Neubedarf, kein Ersatz."}, {"text": "Die IT bekommt 2027 eine zusätzliche Stelle", "kat": "b", "expl": "Im Stellenplan steigt die IT von 9 auf 10 Stellen. Das ist Neubedarf."}, {"text": "Neues Lastenradmodell braucht zusätzliche Monteure", "kat": "b", "expl": "Ein neues Produkt schafft zusätzliche Arbeit. Dafür entsteht Neubedarf."}, {"text": "Ausfallquote von 10 % für Urlaub und Krankheit einplanen", "kat": "c", "expl": "Der Zuschlag für Ausfallzeiten heißt Reservebedarf. Er gehört zum Bruttobedarf."}, {"text": "Eine Person extra für 10 Prüfplätze in der Qualitätssicherung", "kat": "c", "expl": "10 × 10 % ergibt 1 Person Reserve. So sind alle Plätze täglich besetzt."}, {"text": "Zuschlag für die Weiterbildungstage der Beschäftigten", "kat": "c", "expl": "Wer im Seminar sitzt, fehlt am Platz. Dafür plant der Betrieb Reservebedarf ein."}, {"text": "Vertretung für erwartete Krankheitstage einrechnen", "kat": "c", "expl": "Krankheit ist eine Ausfallzeit. Der Ausgleich dafür ist Reservebedarf."}, {"text": "Puffer, damit jeden Tag alle Prüfplätze besetzt sind", "kat": "c", "expl": "Der Puffer zum Einsatzbedarf heißt Reservebedarf. Einsatzbedarf plus Reserve ergibt den Bruttobedarf."}]}, {"titel": "Arbeitszeit im Check nach dem ArbZG", "auftrag": "Prüfe jeden Plan für erwachsene Beschäftigte und bringe ihn in das richtige Depot.", "kategorien": [{"id": "a", "name": "Zulässig nach ArbZG"}, {"id": "b", "name": "Verstoß gegen ArbZG"}], "items": [{"text": "Lisa arbeitet 8 Std. 15 Min. mit 45 Min. Pause", "kat": "a", "expl": "Bis 10 Stunden sind mit Ausgleich erlaubt. Bei mehr als 6 Stunden reichen 30 Minuten Pause."}, {"text": "9 Std. 30 Min. Arbeit, 45 Min. Pause, Ausgleich folgt", "kat": "a", "expl": "Bei mehr als 9 Stunden braucht es 45 Minuten Pause. Die Grenze von 10 Stunden ist eingehalten."}, {"text": "Lager 06:00 bis 13:30 Uhr mit 30 Min. Pause", "kat": "a", "expl": "Das sind 7 Stunden Arbeit mit der nötigen Pause von 30 Minuten (§ 4 ArbZG)."}, {"text": "Spätschicht bis 21:00, nächste Schicht ab 08:00 Uhr", "kat": "a", "expl": "Dazwischen liegen genau 11 Stunden. Das reicht als Ruhezeit (§ 5 ArbZG)."}, {"text": "Samstag 5 Stunden Inventur im Lager", "kat": "a", "expl": "Der Samstag ist nach dem ArbZG ein Werktag. Bei 5 Stunden ist keine Pause nötig."}, {"text": "Pause von 30 Min. in zwei Teilen zu je 15 Min.", "kat": "a", "expl": "Pausen dürfen geteilt werden, wenn jeder Teil mindestens 15 Minuten dauert (§ 4 ArbZG)."}, {"text": "Verwaltung 06:30 bis 19:00 Uhr mit 45 Min. Pause", "kat": "b", "expl": "Das sind 11 Std. 45 Min. Arbeit. Mehr als 10 Stunden am Tag sind verboten (§ 3 ArbZG)."}, {"text": "Spätschicht bis 21:00, Frühschicht am nächsten Tag ab 06:00", "kat": "b", "expl": "Dann liegen nur 9 Stunden Ruhezeit dazwischen. Nötig sind 11 Stunden (§ 5 ArbZG)."}, {"text": "Lager 06:00 bis 13:00 Uhr ganz ohne Pause", "kat": "b", "expl": "Niemand darf länger als 6 Stunden ohne Pause arbeiten (§ 4 ArbZG)."}, {"text": "9 Std. 30 Min. Arbeit mit nur 30 Min. Pause", "kat": "b", "expl": "Bei mehr als 9 Stunden Arbeit sind 45 Minuten Pause Pflicht (§ 4 ArbZG)."}, {"text": "Pause in drei Teilen zu je 10 Minuten", "kat": "b", "expl": "Ein Pausenteil muss mindestens 15 Minuten lang sein. 10 Minuten zählen nicht als Pause."}, {"text": "Dauerhaft 10 Std. täglich ganz ohne Ausgleich", "kat": "b", "expl": "10 Stunden sind nur erlaubt, wenn im Schnitt von 6 Monaten 8 Stunden nicht überschritten werden."}]}]}, {"nr": 3, "title": "Personalbeschaffung", "date": "25.11.2026", "quiz": [{"q": "Wann muss ein Betrieb Personal beschaffen?", "o": ["Wenn der Bruttobedarf dem Ist-Bestand entspricht", "Wenn der Betriebsrat neu gewählt wurde", "Wenn der Nettopersonalbedarf negativ ist", "Wenn der Nettopersonalbedarf positiv ist"], "c": 3, "e": "Ein positiver Nettopersonalbedarf bedeutet, dass Arbeitskräfte fehlen. Ein negativer Nettobedarf ist ein Minderbedarf und führt zur Freistellung."}, {"q": "Nordstern hat für die Montage 2027 einen Bruttobedarf von 120, einen Ist-Bestand von 100, 7 sichere Abgänge und 2 sichere Zugänge. Wie hoch ist der Nettopersonalbedarf?", "o": ["13", "25", "27", "20"], "c": 1, "e": "Fortgeschriebener Bestand 100 − 7 + 2 = 95. Nettobedarf 120 − 95 = 25."}, {"q": "Welcher Weg ist interne Personalbeschaffung mit Personalbewegung?", "o": ["Versetzung einer Monteurin aus der Vormontage", "Anzeige auf einem Online-Portal", "Mehrarbeit in der Montage", "Einsatz einer Leiharbeitskraft"], "c": 0, "e": "Bei einer Versetzung wechselt eine Person die Stelle, das ist eine Personalbewegung. Mehrarbeit ist intern ohne Bewegung, Portal und Leasing sind extern."}, {"q": "Was kann der Betriebsrat nach § 93 BetrVG verlangen?", "o": ["Dass freie Stellen vorher im Betrieb ausgeschrieben werden", "Dass jede Anzeige in der Zeitung erscheint", "Dass er die Bewerbenden selbst auswählt", "Dass freie Stellen nur mit internen Personen besetzt werden"], "c": 0, "e": "§ 93 BetrVG gibt dem Betriebsrat das Recht, eine innerbetriebliche Ausschreibung zu verlangen. Eine interne Besetzung erzwingt er damit nicht."}, {"q": "Der Betriebsrat hat eine interne Ausschreibung verlangt, sie unterbleibt aber. Was darf der Betriebsrat tun?", "o": ["Die Zustimmung zur Einstellung verweigern", "Ein Bußgeld gegen die Personalleitung festsetzen", "Die Stelle selbst im Internet ausschreiben", "Den Arbeitsvertrag selbst kündigen"], "c": 0, "e": "Die fehlende Ausschreibung trotz Verlangen ist ein Grund für die Zustimmungsverweigerung nach § 99 Abs. 2 Nr. 5 BetrVG."}, {"q": "Nordstern schreibt die Stelle Sachbearbeitung Personal intern aus. Darf Nordstern gleichzeitig extern suchen?", "o": ["Ja, intern und extern parallel ist zulässig", "Nur wenn sich niemand intern bewirbt", "Nein, erst nach Ablauf eines Jahres", "Nur mit Zustimmung der Agentur für Arbeit"], "c": 0, "e": "Die interne Ausschreibung verbietet keine externe Suche. Der Betrieb darf beide Wege kombinieren und die geeignetste Person auswählen."}, {"q": "Was unterscheidet die Stellenanzeige von der Stellenbeschreibung?", "o": ["Die Anzeige wirbt auf dem Arbeitsmarkt um Bewerbende", "Die Anzeige ist ein internes Organisationsmittel", "Die Beschreibung nennt das Angebot an Bewerbende", "Die Beschreibung erscheint in Jobbörsen"], "c": 0, "e": "Die Stellenbeschreibung ordnet die Stelle nach innen. Die Stellenanzeige ist Werbung nach außen und baut auf der Beschreibung auf (Beiderwieden & Stickdorn, 2026)."}, {"q": "Wer bestimmt bei der Anordnung von Überstunden für eine Gruppe von Beschäftigten mit?", "o": ["Der Betriebsrat", "Die Krankenkasse", "Die Berufsgenossenschaft", "Die Industrie- und Handelskammer"], "c": 0, "e": "Die vorübergehende Verlängerung der betriebsüblichen Arbeitszeit ist nach § 87 Abs. 1 Nr. 3 BetrVG mitbestimmungspflichtig."}, {"q": "Welcher Weg gehört zur externen Personalbeschaffung?", "o": ["Aufstockung einer Teilzeitstelle", "Aushang am Schwarzen Brett im Betrieb", "Versetzung aus dem Lager in die Montage", "Stellenangebot in der Jobbörse der Agentur für Arbeit"], "c": 3, "e": "Die Jobbörse spricht Menschen außerhalb des Betriebs an. Versetzung, Aufstockung und Aushang sind interne Wege."}, {"q": "Was ist ein typischer Vorteil der internen Personalbeschaffung?", "o": ["Es entsteht nie eine neue Lücke", "Es kommen viele neue Ideen von außen", "Die Person und ihre Leistung sind bekannt", "Die Auswahl ist besonders groß"], "c": 2, "e": "Intern kennt der Betrieb die Person, das senkt das Risiko. Auswahl und neue Ideen sind dagegen Vorteile der externen Beschaffung."}, {"q": "Was spricht typischerweise gegen die Suche auf dem externen Arbeitsmarkt?", "o": ["Höheres Risiko einer Fehlbesetzung", "Betriebsblindheit der neuen Person", "Pflicht zur Zustimmung der Agentur für Arbeit", "Zu kleine Auswahl an Bewerbenden"], "c": 0, "e": "Externe Personen kennt der Betrieb nur aus Unterlagen und Gesprächen, das Risiko ist höher. Betriebsblindheit ist eher ein Problem interner Lösungen."}, {"q": "Was versteht man unter Direktansprache oder Active Sourcing?", "o": ["Aushang einer Stelle in der Kantine", "Automatische Absage an alle Bewerbenden", "Versetzung auf Anordnung des Arbeitgebers", "Gezieltes Ansprechen geeigneter Personen, die nicht aktiv suchen"], "c": 3, "e": "Bei der Direktansprache sprechen Betrieb oder Personalberater passende Menschen gezielt an, oft über Netzwerke wie LinkedIn."}, {"q": "Wie heißt Personalleasing im Gesetz?", "o": ["Werkvertrag", "Arbeitsvermittlung", "Personalentwicklung", "Arbeitnehmerüberlassung"], "c": 3, "e": "Das Arbeitnehmerüberlassungsgesetz (AÜG) regelt das Personalleasing, also Zeitarbeit oder Leiharbeit."}, {"q": "Wer ist beim Personalleasing der Arbeitgeber der Leiharbeitskraft?", "o": ["Der Betriebsrat des Entleihers", "Der Entleiher", "Der Verleiher", "Die Agentur für Arbeit"], "c": 2, "e": "Der Verleiher schließt den Arbeitsvertrag und zahlt das Entgelt. Der Entleiher setzt die Leiharbeitskraft nur ein."}, {"q": "Was braucht ein Verleiher, um Arbeitnehmer überlassen zu dürfen?", "o": ["Eine Erlaubnis nach § 1 Abs. 1 AÜG", "Die Zustimmung der Gewerkschaft", "Ein Zertifikat der Krankenkasse", "Eine Eintragung bei der IHK zu Lübeck"], "c": 0, "e": "Arbeitnehmerüberlassung ist erlaubnispflichtig. Die Erlaubnis erteilt die Bundesagentur für Arbeit."}, {"q": "Wie lange darf eine Leiharbeitskraft ohne abweichenden Tarifvertrag höchstens beim selben Entleiher arbeiten?", "o": ["18 Monate", "6 Monate", "36 Monate", "24 Monate"], "c": 0, "e": "Die Überlassungshöchstdauer beträgt 18 aufeinanderfolgende Monate (§ 1 Abs. 1b AÜG). Tarifverträge der Einsatzbranche können abweichen."}, {"q": "Welche Form braucht der Überlassungsvertrag zwischen Verleiher und Entleiher?", "o": ["Eintragung im Handelsregister", "Notarielle Beurkundung", "Keine Form, ein Anruf reicht", "Textform, eine E-Mail genügt"], "c": 3, "e": "Seit 2025 genügt für den Überlassungsvertrag die Textform (§ 12 Abs. 1 AÜG)."}, {"q": "Was bedeutet der Grundsatz Equal Pay beim Personalleasing?", "o": ["Gleiches Entgelt wie vergleichbare Stammbeschäftigte", "Gleicher Stundensatz für alle Verleiher", "Gleiche Prämie für Entleiher und Verleiher", "Gleicher Lohn für alle Leiharbeitskräfte in Deutschland"], "c": 0, "e": "Leiharbeitskräfte haben Anspruch auf die gleichen Arbeitsbedingungen und das gleiche Entgelt wie vergleichbare Stammbeschäftigte (§ 8 AÜG). Ein Tarifvertrag darf beim Entgelt meist nur in den ersten neun Monaten abweichen."}, {"q": "Muss der Betriebsrat von Nordstern beteiligt werden, bevor eine Leiharbeitskraft in der Montage eingesetzt wird?", "o": ["Nein, Leiharbeitskräfte sind nicht bei Nordstern angestellt", "Nur wenn der Einsatz länger als 18 Monate dauert", "Nur der Betriebsrat des Verleihers muss zustimmen", "Ja, wie bei einer Einstellung nach § 99 BetrVG"], "c": 3, "e": "Nach § 14 Abs. 3 AÜG ist der Betriebsrat des Entleihers vor der Übernahme einer Leiharbeitskraft nach § 99 BetrVG zu beteiligen."}, {"q": "Nordstern leiht 6 Monteure für 12 Wochen zu je 35 Stunden. Der Verrechnungssatz beträgt 34,00 € je Stunde. Was kostet das?", "o": ["85.680,00 €", "99.960,00 €", "71.400,00 €", "14.280,00 €"], "c": 0, "e": "6 × 12 × 35 = 2.520 Stunden. 2.520 × 34,00 € = 85.680,00 €."}, {"q": "Warum ist der Verrechnungssatz eines Verleihers höher als der Stundenlohn der Stammbeschäftigten?", "o": ["Leiharbeitskräfte arbeiten gesetzlich weniger Stunden", "Der Entleiher zahlt zusätzlich die Lohnsteuer doppelt", "Der Staat zahlt einen Zuschlag an den Verleiher", "Er deckt Nebenkosten, Verwaltung und Gewinn des Verleihers"], "c": 3, "e": "Der Verleiher muss aus dem Stundensatz das Entgelt, die Arbeitgeberanteile, die Verwaltung und seinen Gewinn finanzieren."}, {"q": "Was schuldet der Verleiher dem Entleiher beim Personalleasing?", "o": ["Die Überlassung geeigneter Arbeitskräfte", "Ein fertiges Arbeitsergebnis wie beim Werkvertrag", "Die Haftung für jeden Fehler der Leiharbeitskraft", "Das Entgelt für die Stammbeschäftigten"], "c": 0, "e": "Der Verleiher schuldet nur geeignete Arbeitskräfte, die nach den Weisungen des Entleihers arbeiten. Für das Ergebnis haftet er nicht. Ein Ergebnis schuldet der Unternehmer beim Werkvertrag (§ 631 BGB)."}, {"q": "Ein Personalberater verlangt 20 % eines Jahresgehalts. Die Stelle ist mit 3.950 € im Monat bewertet, Sonderzahlungen bleiben außen vor. Wie hoch ist das Honorar?", "o": ["7.900 €", "11.850 €", "790 €", "9.480 €"], "c": 3, "e": "3.950 € × 12 = 47.400 €. 47.400 € × 20 % = 9.480 €."}, {"q": "Wie hoch ist die Ersparnis, wenn Nordstern statt des Personalberaters für 9.480 € das Online-Portal für 1.200 € nutzt?", "o": ["8.280 €", "10.680 €", "7.900 €", "9.480 €"], "c": 0, "e": "9.480 € − 1.200 € = 8.280 €."}, {"q": "Über das Online-Portal kamen 30 Bewerbungen, die Anzeige kostete 1.200 €. Wie hoch sind die Kosten je Bewerbung über das Portal?", "o": ["18,75 €", "40,00 €", "400,00 €", "36,00 €"], "c": 1, "e": "Kosten je Bewerbung = Kosten des Weges ÷ Bewerbungen über diesen Weg = 1.200 € ÷ 30 = 40,00 €. 18,75 € wäre der Wert für alle 64 Bewerbungen."}, {"q": "Warum reicht ein reiner Vergleich der direkten Kosten zur Wahl des Beschaffungswegs nicht aus?", "o": ["Eine Fehlbesetzung verursacht oft viel höhere Folgekosten", "Der Betriebsrat legt die Kosten fest", "Direkte Kosten dürfen nicht verglichen werden", "Das AGG verbietet Kostenvergleiche"], "c": 0, "e": "Einarbeitung, Kündigung und neue Suche nach einem Fehlgriff sind teuer. Darum zählt auch die Treffsicherheit eines Weges."}, {"q": "Was bedeutet Employer Branding?", "o": ["Eintragung der Firma ins Markenregister", "Aufbau einer attraktiven Arbeitgebermarke", "Bewertung der Beschäftigten durch Vorgesetzte", "Werbung für neue Fahrradmodelle"], "c": 1, "e": "Employer Branding macht den Betrieb als Arbeitgeber bekannt und attraktiv (Beiderwieden & Stickdorn, 2026)."}, {"q": "Welcher Schritt ist im Kreislauf des Employer Branding besonders wichtig, damit die Marke glaubwürdig bleibt?", "o": ["Das Versprechen jedes Jahr ändern", "Das Versprechen im Arbeitsalltag einlösen", "Bewertungen im Internet löschen lassen", "Möglichst viele Werbeanzeigen schalten"], "c": 1, "e": "Stimmt das Versprechen im Alltag nicht, entstehen Enttäuschung und schlechte Bewertungen. Das schadet der Marke mehr als jede fehlende Anzeige."}, {"q": "Wofür steht das A am Anfang der AIDA-Formel?", "o": ["Action, also Handlung", "Angebot, also Leistung", "Attention, also Aufmerksamkeit", "Analyse, also Untersuchung"], "c": 2, "e": "AIDA steht für Attention, Interest, Desire und Action. Das erste A ist die Aufmerksamkeit, das letzte A die Handlung."}, {"q": "Welcher Teil einer Stellenanzeige gehört zur Stufe Action?", "o": ["Vorstellung des Unternehmens", "Logo und Stellenbezeichnung", "Bewerbungsweg, Frist und Ansprechperson", "Beschreibung der Aufgaben"], "c": 2, "e": "Action fordert zur Bewerbung auf. Dafür braucht die Leserin den Weg, die Frist und eine Ansprechperson."}, {"q": "Woher stammen die Inhalte für den Baustein Ihr Profil in der Stellenanzeige?", "o": ["Aus dem Anforderungsprofil der Stelle", "Aus der Krankenkassenmeldung", "Aus der Gewinn- und Verlustrechnung", "Aus dem Tarifvertrag der Gewerkschaft"], "c": 0, "e": "Das Anforderungsprofil aus der qualitativen Personalplanung beschreibt, welche Kenntnisse und Fähigkeiten die Stelle verlangt."}, {"q": "Gilt das AGG schon für Bewerberinnen und Bewerber?", "o": ["Nur bei Betrieben mit mehr als 500 Beschäftigten", "Nein, erst ab dem ersten Arbeitstag", "Ja, sie gelten als Beschäftigte im Sinne des AGG", "Nein, erst nach bestandener Probezeit"], "c": 2, "e": "Nach § 6 Abs. 1 AGG gelten auch Bewerbende als Beschäftigte. Der Schutz beginnt also mit der Stellenanzeige."}, {"q": "Welche Vorschrift verbietet eine benachteiligende Stellenausschreibung?", "o": ["§ 11 AGG", "§ 3 ArbZG", "§ 93 BetrVG", "§ 12 AÜG"], "c": 0, "e": "§ 11 AGG verbietet, Stellen unter Verstoß gegen das Benachteiligungsverbot auszuschreiben. § 93 BetrVG regelt die interne Ausschreibung auf Verlangen des Betriebsrats."}, {"q": "Ein Betrieb lehnt einen Bewerber ab, weil er wegen des Namens eine bestimmte Herkunft vermutet. Die Vermutung ist falsch. Liegt eine Benachteiligung nach dem AGG vor?", "o": ["Ja, es reicht, dass der Arbeitgeber das Merkmal annimmt", "Nein, weil das Merkmal tatsächlich nicht vorliegt", "Nein, weil Namen kein geschütztes Merkmal sind", "Nur wenn der Betriebsrat widersprochen hat"], "c": 0, "e": "Nach § 7 Abs. 1 AGG liegt eine Benachteiligung auch dann vor, wenn der Arbeitgeber ein geschütztes Merkmal nur annimmt."}, {"q": "Warum sollte Nordstern in einer Anzeige kein Foto verlangen?", "o": ["Die Agentur für Arbeit verbietet Fotos", "Ein Foto zeigt geschützte Merkmale wie Alter oder Herkunft", "Fotos lassen sich nicht digital speichern", "Fotos sind in Bewerbungen gesetzlich verboten"], "c": 1, "e": "Ein Foto kann zu unbewussten Benachteiligungen führen und dient im Streitfall als Indiz. Bewerbende dürfen freiwillig ein Foto beilegen."}, {"q": "Wann ist eine unterschiedliche Behandlung wegen eines geschützten Merkmals ausnahmsweise erlaubt?", "o": ["Wenn es eine wesentliche und entscheidende berufliche Anforderung ist", "Wenn das Team schon überwiegend jung ist", "Wenn die Stelle befristet ist", "Wenn die Abteilungsleitung es wünscht"], "c": 0, "e": "§ 8 AGG erlaubt eine unterschiedliche Behandlung nur, wenn das Merkmal wegen der Art der Tätigkeit eine wesentliche und entscheidende berufliche Anforderung ist."}, {"q": "Was gilt nach § 22 AGG, wenn eine abgelehnte Person Indizien für eine Benachteiligung vorlegt?", "o": ["Die Person muss die Benachteiligung lückenlos beweisen", "Der Arbeitgeber muss beweisen, dass er nicht benachteiligt hat", "Der Betriebsrat entscheidet allein über den Fall", "Die Indizien werden nicht berücksichtigt"], "c": 1, "e": "§ 22 AGG enthält eine Beweislastumkehr. Indizien wie eine Anzeige mit Altersgrenze reichen, dann trägt der Arbeitgeber die Beweislast."}, {"q": "Welche Formulierung ist für die Stelle bei Nordstern AGG-konform?", "o": ["Sachbearbeiter Personal, deutscher Herkunft", "Personalsachbearbeiterin bis 30 Jahre", "Junger Personalsachbearbeiter gesucht", "Sachbearbeitung Personal (m/w/d)"], "c": 3, "e": "Die neutrale Bezeichnung mit Zusatz (m/w/d) spricht alle an. Die anderen Titel benachteiligen nach Geschlecht, Alter oder Herkunft."}, {"q": "Was ist zur EU-Entgelttransparenzrichtlinie im November 2026 richtig?", "o": ["Ein deutsches Umsetzungsgesetz ist noch nicht beschlossen", "Sie gilt nur für Leiharbeitskräfte", "Sie hat das AGG vollständig ersetzt", "Sie verpflichtet Bewerbende, ihr altes Gehalt zu nennen"], "c": 0, "e": "Die Richtlinie sieht unter anderem Gehaltsangaben vor dem Gespräch vor. Deutschland hat sie bis November 2026 noch nicht umgesetzt, darum ist sie nur geplant."}, {"q": "Nordstern sucht 25 Monteure. Welche Kombination von Wegen ist sinnvoll?", "o": ["Agentur für Arbeit, Portal und Empfehlungen kombinieren", "Nur eine Ausschreibung am Schwarzen Brett", "Nur Mehrarbeit der vorhandenen Monteure", "Nur ein Personalberater für alle 25 Stellen"], "c": 0, "e": "Bei vielen gleichartigen Stellen braucht man Reichweite zu vertretbaren Kosten. Ein Mix aus mehreren externen Wegen ist sinnvoll, ergänzt um interne Lösungen."}, {"q": "Nordstern Service GmbH sucht eine Fachkraft für die Werkstatt in Hamburg und braucht sie nächste Woche für drei Monate. Welcher Weg passt am besten?", "o": ["Personalleasing über einen Verleiher", "Anzeige mit Bewerbungsfrist von zwei Monaten", "Auftrag an einen Personalberater für Führungskräfte", "Ausbildung eines neuen Azubis"], "c": 0, "e": "Für einen kurzen, sofortigen Bedarf ist Leiharbeit schnell und flexibel. Ausbildung und lange Fristen passen nicht zum Zeitdruck."}, {"q": "Bei Nordstern gehen 64 Bewerbungen ein, 12 kommen in die engere Wahl. Wie hoch ist die Quote der engeren Wahl?", "o": ["5,33 %", "81,25 %", "18,75 %", "12,00 %"], "c": 2, "e": "12 ÷ 64 × 100 = 18,75 %. 81,25 % wäre der Anteil der Bewerbungen, die nicht in die engere Wahl kommen."}, {"q": "Wie hoch ist die Einstellungsquote bei 64 Bewerbungen und 1 Einstellung?", "o": ["15,63 %", "1,56 %", "0,64 %", "6,40 %"], "c": 1, "e": "1 ÷ 64 × 100 = 1,5625 %, gerundet 1,56 %."}, {"q": "Warum hat die Personalauswahl die Form eines Trichters?", "o": ["Oben werden viele mit wenig Aufwand geprüft, unten wenige mit viel Aufwand", "Der Betriebsrat sortiert oben, die Personalabteilung unten", "Mit jeder Stufe werden mehr Bewerbungen eingeladen", "Alle Bewerbenden durchlaufen dieselben Gespräche"], "c": 0, "e": "Die Zahl der Personen sinkt von Stufe zu Stufe, die Prüfung je Person wird genauer und aufwendiger."}, {"q": "Wann sollte Nordstern die Absagen an die zweit- und drittbeste Person verschicken?", "o": ["Nach der Zustimmung des Betriebsrats zur Einstellung", "Schon vor der Einladung zum Gespräch", "Sofort am Tag nach dem letzten Gespräch", "Erst nach dem Ende der Probezeit"], "c": 0, "e": "Lehnt der Betriebsrat ab, braucht Nordstern eventuell eine andere Person. Ein halbes Jahr zu warten wäre unfair gegenüber den Bewerbenden."}, {"q": "Was prüft die formale Analyse von Bewerbungsunterlagen?", "o": ["Ob die Person auf dem Foto sympathisch wirkt", "Ob der Betriebsrat schon zugestimmt hat", "Ob das Gehalt im Tarif liegt", "Vollständigkeit und äußere Form der Unterlagen"], "c": 3, "e": "Die formale Prüfung bewertet Vollständigkeit, Ordnung und Fehlerfreiheit. Die inhaltliche Prüfung vergleicht mit dem Anforderungsprofil."}, {"q": "Was ist das Ziel der inhaltlichen Analyse von Bewerbungsunterlagen?", "o": ["Rechtschreibfehler zählen", "Eignung mit dem Anforderungsprofil vergleichen", "Die Schriftart des Anschreibens bewerten", "Das Alter der Person bestimmen"], "c": 1, "e": "Inhaltlich wird geprüft, ob Ausbildung, Erfahrung und Kenntnisse zur Stelle passen."}, {"q": "Was untersucht die Zeitfolgeanalyse eines Lebenslaufs?", "o": ["Die Höhe des bisherigen Gehalts", "Lücken und auffällig häufige Wechsel", "Die Schulnoten der Grundschule", "Die Zahl der Hobbys"], "c": 1, "e": "Die Zeitfolgeanalyse betrachtet den zeitlichen Ablauf des Werdegangs, also Lücken und Wechsel."}, {"q": "Was untersucht die Positionsanalyse?", "o": ["Wie viele Bewerbungen sie insgesamt verschickt hat", "Ob das Foto rechts oder links oben steht", "Ob die Person in der Nähe des Betriebs wohnt", "Ob die Person Verantwortung übernommen hat und aufgestiegen ist"], "c": 3, "e": "Die Positionsanalyse zeigt die berufliche Entwicklung, etwa vom Einkauf in die Personalarbeit oder von der Sachbearbeitung zur Teamleitung."}, {"q": "Wann erhält eine Beschäftigte ein qualifiziertes Zeugnis?", "o": ["Auf ihr eigenes Verlangen", "Nur bei einer Kündigung durch den Arbeitgeber", "Immer automatisch nach der Probezeit", "Nur wenn der Betriebsrat zustimmt"], "c": 0, "e": "Das qualifizierte Zeugnis mit Leistung und Verhalten gibt es auf Verlangen der Beschäftigten (§ 109 GewO)."}, {"q": "Welche Note bedeutet die Formulierung „stets zu unserer vollsten Zufriedenheit“?", "o": ["gut", "befriedigend", "sehr gut", "ausreichend"], "c": 2, "e": "„Stets zu unserer vollsten Zufriedenheit“ ist die Formel für sehr gut. Ohne stets oder mit voll sinkt die Note."}, {"q": "Ein kirchlicher Kindergarten fragt eine Bewerberin nach ihrer Religion. Was gilt?", "o": ["Die Frage kann in diesem Tendenzbetrieb zulässig sein", "Die Frage ist in jedem Betrieb ausnahmslos verboten", "Die Frage ist nur mit Zustimmung der IHK erlaubt", "Die Bewerberin muss stets schweigen"], "c": 0, "e": "Tendenzbetriebe wie Kirchen oder Parteien vertreten eine bestimmte Richtung. Dort kann die Frage nach Religion oder Parteizugehörigkeit ausnahmsweise zulässig sein (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was ist ein Bewerbermanagementsystem?", "o": ["Ein Gremium aus Betriebsrat und Geschäftsleitung", "Software, die Bewerbungen erfasst, ordnet und den Status steuert", "Ein Ordner für Papierbewerbungen im Personalbüro", "Eine Vorschrift im Arbeitszeitgesetz"], "c": 1, "e": "Ein BMS bündelt alle digitalen Bewerbungen, verschickt Eingangsbestätigungen, sammelt Bewertungen und erinnert an Fristen."}, {"q": "Das Online-Formular von Nordstern enthält einen einheitlichen Fragenkatalog. Was gilt nach § 94 BetrVG?", "o": ["Er ist ohne Weiteres frei gestaltbar", "Er muss von der IHK geprüft werden", "Der Fragebogen braucht die Zustimmung des Betriebsrats", "Die Agentur für Arbeit muss ihn genehmigen"], "c": 2, "e": "Ein einheitlicher Fragebogen ist ein Personalfragebogen und braucht nach § 94 BetrVG die Zustimmung des Betriebsrats."}, {"q": "Darf eine Software bei Nordstern allein über Absagen entscheiden?", "o": ["Nein, ein Mensch muss prüfen und entscheiden", "Ja, wenn die Software teuer genug war", "Ja, bei mehr als 50 Bewerbungen", "Ja, wenn die Bewerbung per E-Mail kam"], "c": 0, "e": "Entscheidungen mit rechtlicher Wirkung dürfen nach Art. 22 DSGVO grundsätzlich nicht ausschließlich automatisiert getroffen werden."}, {"q": "Was ist ein Muss-Kriterium für die Stelle Sachbearbeitung Personal bei Nordstern?", "o": ["Mitgliedschaft im Sportverein", "Abgeschlossene kaufmännische Ausbildung", "Wohnort direkt in Norderstedt", "Erfahrung mit einer bestimmten Personalsoftware"], "c": 1, "e": "Die Ausbildung ist zwingend. Erfahrung mit einer Personalsoftware ist ein Kann-Kriterium, also ein Plus."}, {"q": "Malte Brandt sortiert die Bewerbungen in die Gruppen A, B und C. Was gilt für Gruppe C?", "o": ["Mindestens ein Muss-Kriterium fehlt, es folgt eine Absage", "Alle Kriterien sind erfüllt, sie kommt in die engere Wahl", "Sie wird automatisch zum Gespräch eingeladen", "Sie wird an den Betriebsrat zur Auswahl gegeben"], "c": 0, "e": "Gruppe A geht in die engere Wahl, Gruppe B in die Reserve, Gruppe C erfüllt nicht alle Muss-Kriterien und erhält eine Absage."}, {"q": "Was enthält eine Kurzbewerbung?", "o": ["Anschreiben und Lebenslauf, Zeugnisse folgen auf Anforderung", "Nur ein Foto und die Telefonnummer", "Alle Zeugnisse, aber kein Lebenslauf", "Ausschließlich Arbeitsproben und Referenzen"], "c": 0, "e": "Bei einer Kurzbewerbung schickt die Person zunächst nur Anschreiben und Lebenslauf. Weitere Unterlagen reicht sie nach, wenn der Betrieb Interesse zeigt (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was kennzeichnet ein strukturiertes Vorstellungsgespräch?", "o": ["Jede Person bekommt ganz andere, spontane Fragen", "Alle Personen bekommen nach einem Leitfaden dieselben Kernfragen", "Das Gespräch findet ohne jede Vorbereitung statt", "Nur die bewerbende Person stellt Fragen"], "c": 1, "e": "Leitfaden und Bewertungsbogen machen Antworten vergleichbar und verringern den Einfluss von Vorurteilen (Oechsler & Paul, 2019)."}, {"q": "Welche Phase steht in einem typischen Vorstellungsgespräch am Ende?", "o": ["Begrüßung mit Small Talk", "Vorstellung des Unternehmens", "Werdegang der Person", "Konditionen und nächste Schritte"], "c": 3, "e": "Am Schluss geht es um Eintrittstermin, Gehaltsvorstellung und das weitere Vorgehen."}, {"q": "Nordstern lädt eine Bewerberin aus Kiel zum Gespräch ein und schließt keine Erstattung aus. Wer trägt die Fahrtkosten?", "o": ["Nordstern, nach § 670 BGB analog", "Die Agentur für Arbeit", "Der Betriebsrat aus seinem Budget", "Die Bewerberin selbst"], "c": 0, "e": "Wer einlädt, muss die erforderlichen Vorstellungskosten ersetzen, wenn er das nicht vorher ausdrücklich ausgeschlossen hat."}, {"q": "Darf der Arbeitgeber nach einer Schwangerschaft fragen?", "o": ["Ja, wenn die Stelle in der Verwaltung ist", "Ja, wenn der Betriebsrat zustimmt", "Nein, die Frage ist unzulässig", "Ja, bei befristeten Stellen immer"], "c": 2, "e": "Die Frage nach einer Schwangerschaft benachteiligt wegen des Geschlechts und ist unzulässig, auch bei befristeten Stellen."}, {"q": "Darf Nordstern als tarifgebundener Betrieb nach der Mitgliedschaft in der IG Metall fragen?", "o": ["Ja, weil Nordstern tarifgebunden ist", "Ja, aber nur bei Monteuren", "Nein, die Gewerkschaftszugehörigkeit ist geschützt", "Ja, wenn die Frage schriftlich gestellt wird"], "c": 2, "e": "Die Koalitionsfreiheit schützt die Gewerkschaftsmitgliedschaft. Die Frage ist vor der Einstellung unzulässig."}, {"q": "Wann ist die Frage nach Vorstrafen zulässig?", "o": ["Wenn die Vorstrafe für die Stelle einschlägig ist", "Nie, unter keinen denkbaren Umständen", "Immer, bei jeder Stelle im Betrieb", "Nur bei Bewerbenden über 50 Jahre"], "c": 0, "e": "Zulässig ist nur die Frage nach einschlägigen Vorstrafen, etwa nach Vermögensdelikten bei einer Tätigkeit mit Geld."}, {"q": "Was bedeutet das Recht zur Lüge?", "o": ["Zeugnisse dürfen falsche Noten enthalten", "Bewerbende dürfen bei allen Fragen im Gespräch lügen", "Arbeitgeber dürfen über das Gehalt der Stelle lügen", "Auf unzulässige Fragen darf man folgenlos falsch antworten"], "c": 3, "e": "Das Recht zur Lüge gilt nur bei unzulässigen Fragen. Bei zulässigen Fragen muss wahrheitsgemäß geantwortet werden."}, {"q": "Warum darf eine Bewerberin auf eine unzulässige Frage lügen, statt einfach zu schweigen?", "o": ["Schweigen ist im Gespräch gesetzlich verboten", "Lügen ist immer höflicher als Schweigen", "Der Betriebsrat schreibt jede Antwort mit", "Schweigen würde die Antwort praktisch verraten"], "c": 3, "e": "Wer bei der Frage nach einer Schwangerschaft schweigt, lässt Rückschlüsse zu. Darum schützt die Rechtsprechung die falsche Antwort."}, {"q": "Ein Bewerber gibt an, die IHK-Prüfung bestanden zu haben, hat sie aber nicht. Was kann Nordstern tun?", "o": ["Nichts, es gilt das Recht zur Lüge", "Eine Entschädigung nach dem AGG verlangen", "Den Arbeitsvertrag wegen arglistiger Täuschung anfechten", "Den Betriebsrat gerichtlich auflösen lassen"], "c": 2, "e": "Die Frage nach dem Abschluss ist zulässig. Eine Lüge ist arglistige Täuschung, der Vertrag kann nach § 123 BGB angefochten werden."}, {"q": "Was gehört zur Offenbarungspflicht von Bewerbenden?", "o": ["Ungefragt die Religion angeben", "Umstände nennen, die die Arbeit unmöglich machen", "Ungefragt alle Krankheiten der letzten Jahre nennen", "Den bisherigen Kontostand offenlegen"], "c": 1, "e": "Ohne Frage muss nur mitgeteilt werden, was die Arbeitsleistung unmöglich macht, etwa ein fehlender Führerschein bei einer Fahrerstelle."}, {"q": "Was passiert in der Postkorbübung eines Assessment-Centers?", "o": ["Ein Betriebsarzt untersucht die körperliche Belastbarkeit", "Viele Vorgänge unter Zeitdruck nach Dringlichkeit ordnen", "Die Teilnehmenden sortieren echte Briefe der Post", "Die Gruppe diskutiert frei über ihre Hobbys"], "c": 1, "e": "Der Postkorb prüft Organisation, Prioritäten und Entscheidungsfähigkeit unter Zeitdruck."}, {"q": "Welcher Test ist für die Stelle Sachbearbeitung Personal besonders praxisnah?", "o": ["Test zur körperlichen Kraft", "Fragebogen zur politischen Meinung", "Arbeitsprobe mit einer Excel-Tabelle zum Urlaub", "Graphologisches Gutachten der Handschrift ohne Einwilligung"], "c": 2, "e": "Eine Arbeitsprobe bildet eine typische Aufgabe der Stelle ab. Tests brauchen Bezug zur Stelle und die Einwilligung der Person."}, {"q": "In welcher Reihenfolge läuft eine Nutzwertanalyse ab?", "o": ["Punkte, Kriterien, addieren, Gewichte, multiplizieren", "Addieren, Punkte, Kriterien, Gewichte, multiplizieren", "Gewichte nach dem Gespräch passend festlegen, dann Punkte", "Kriterien, Gewichte, Punkte, multiplizieren, addieren"], "c": 3, "e": "Erst Kriterien und Gewichte festlegen, dann Punkte vergeben, mit dem Gewicht multiplizieren und alles addieren."}, {"q": "Worin liegt die wichtigste Grenze einer Nutzwertanalyse?", "o": ["Kriterien, Gewichte und Punkte beruhen auf subjektiven Einschätzungen", "Sie lässt sich nur für Investitionen in Maschinen einsetzen", "Sie braucht immer die Zustimmung der Agentur für Arbeit", "Sie darf höchstens drei Kriterien enthalten"], "c": 0, "e": "Die Nutzwertanalyse macht eine Entscheidung transparent. Weil Menschen Kriterien, Gewichte und Punkte festlegen, bleibt sie aber subjektiv (Beiderwieden & Stickdorn, 2026)."}, {"q": "Jana Hoffmann erhält 8 Punkte bei den Fachkenntnissen, Gewicht 30 %. Wie hoch sind die gewichteten Punkte?", "o": ["0,24", "24,00", "3,80", "2,40"], "c": 3, "e": "8 × 0,30 = 2,40."}, {"q": "Murat Yilmaz hat die Punkte 9, 9, 6, 6, 6 bei den Gewichten 30 %, 20 %, 20 %, 15 %, 15 %. Wie hoch ist sein Nutzwert?", "o": ["36,00", "7,20", "7,80", "7,50"], "c": 3, "e": "2,70 + 1,80 + 1,20 + 0,90 + 0,90 = 7,50."}, {"q": "In welchen Unternehmen muss der Betriebsrat einer Einstellung nach § 99 BetrVG zustimmen?", "o": ["In allen Unternehmen ab 5 Beschäftigten", "In Unternehmen mit mehr als 20 wahlberechtigten Beschäftigten", "Nur in Betrieben ohne jede Tarifbindung", "Nur in Unternehmen mit mehr als 500 Beschäftigten"], "c": 1, "e": "§ 99 Abs. 1 BetrVG gilt in Unternehmen mit in der Regel mehr als 20 wahlberechtigten Beschäftigten."}, {"q": "Nordstern unterrichtet den Betriebsrat am Montag, dem 11.01.2027. Bis wann muss er eine Verweigerung schriftlich mitteilen?", "o": ["Bis Montag, 25.01.2027", "Bis Donnerstag, 11.02.2027", "Bis Montag, 18.01.2027", "Bis Freitag, 15.01.2027"], "c": 2, "e": "Die Frist beträgt eine Woche. Sie endet am Montag der folgenden Woche, also am 18.01.2027."}, {"q": "Der Betriebsrat reagiert innerhalb der Woche nicht. Was gilt?", "o": ["Das Arbeitsgericht entscheidet von selbst", "Die Frist verlängert sich automatisch um einen Monat", "Die Einstellung ist endgültig verboten", "Die Zustimmung gilt als erteilt"], "c": 3, "e": "Ohne fristgerechte schriftliche Verweigerung gilt die Zustimmung als erteilt (§ 99 Abs. 3 BetrVG)."}, {"q": "Der Betriebsrat verweigert die Zustimmung fristgerecht und mit Grund. Was kann Nordstern tun?", "o": ["Den Betriebsrat schriftlich abmahnen", "Beim Arbeitsgericht die Ersetzung der Zustimmung beantragen", "Die Person trotzdem ohne Weiteres dauerhaft einstellen", "Die IHK zu Lübeck um Zustimmung bitten"], "c": 1, "e": "Nach § 99 Abs. 4 BetrVG kann der Arbeitgeber beim Arbeitsgericht beantragen, die Zustimmung zu ersetzen."}, {"q": "Die Nordstern Service GmbH hat 18 Beschäftigte. Was gilt dort für Einstellungen?", "o": ["Jede Einstellung braucht die Zustimmung der IHK", "Das AGG gilt dort ebenfalls nicht", "Der Betriebsrat der Muttergesellschaft muss zustimmen", "§ 99 BetrVG gilt nicht, weil höchstens 20 Wahlberechtigte"], "c": 3, "e": "Die Schwelle von mehr als 20 wahlberechtigten Beschäftigten wird nicht erreicht. Das AGG gilt aber in jedem Betrieb."}, {"q": "Innerhalb welcher Frist muss eine abgelehnte Person eine Entschädigung nach dem AGG schriftlich geltend machen?", "o": ["Innerhalb von 3 Wochen", "Innerhalb von 3 Jahren", "Innerhalb von 2 Monaten", "Innerhalb von 4 Monaten"], "c": 2, "e": "§ 15 Abs. 4 AGG nennt zwei Monate. Die Verlängerung auf vier Monate ist nur geplant und noch nicht beschlossen (Deutscher Bundestag, 2026)."}, {"q": "Eine Person wäre auch ohne Benachteiligung nicht eingestellt worden. Wie hoch ist die Entschädigung bei EG 9 mit 3.950 € höchstens?", "o": ["11.850 €", "47.400 €", "7.900 €", "3.950 €"], "c": 0, "e": "Die Entschädigung ist dann auf drei Monatsentgelte begrenzt (§ 15 Abs. 2 AGG), 3 × 3.950 € = 11.850 €."}, {"q": "Welche fünf Seiten der Personalbeschaffung nennt das Skript?", "o": ["Lohn, Steuer, Urlaub, Probezeit und Kündigung", "Ausbildung, Prüfung, Zeugnis, Übernahme und Rente", "Anzahl, Qualifikation, Zeit, Ort und Kosten", "Planung, Werbung, Verkauf, Versand und Service"], "c": 2, "e": "Personalbeschaffung stellt Arbeitskräfte in richtiger Anzahl, mit passender Qualifikation, zur richtigen Zeit, am richtigen Ort und zu vertretbaren Kosten bereit (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was folgt aus einem negativen Nettopersonalbedarf?", "o": ["Die Zahl der Auszubildenden steigt automatisch", "Der Betriebsrat muss neu gewählt werden", "Es müssen sofort neue Anzeigen geschaltet werden", "Es gibt einen Minderbedarf, es geht um Freistellung"], "c": 3, "e": "Nur ein positiver Nettobedarf führt zur Beschaffung. Ist er negativ, hat der Betrieb zu viel Personal, dann geht es um Personalfreistellung."}, {"q": "Was ist das Kennzeichen der internen Beschaffung mit Personalbewegung?", "o": ["Eine Person aus dem Betrieb wechselt auf eine andere Stelle", "Eine Person bleibt auf ihrem Platz und arbeitet länger", "Eine freie Stelle wird ersatzlos aus dem Stellenplan gestrichen", "Eine Leiharbeitskraft kommt für drei Monate in den Betrieb"], "c": 0, "e": "Mit Personalbewegung heißt, dass jemand aus dem eigenen Betrieb die Stelle wechselt, etwa durch Ausschreibung, Versetzung oder Übernahme nach der Ausbildung."}, {"q": "Warum zählt Personalentwicklung zur internen Beschaffung ohne Personalbewegung?", "o": ["Neue Fachkräfte werden vom Arbeitsmarkt eingestellt", "Ein Personalberater sucht passende Führungskräfte", "Vorhandene Beschäftigte werden für zusätzliche Aufgaben geschult", "Die Agentur für Arbeit schickt geeignete Arbeitsuchende"], "c": 2, "e": "Bei der Personalentwicklung qualifiziert der Betrieb die eigenen Leute, damit sie neue Aufgaben übernehmen. Es kommt niemand von außen dazu."}, {"q": "Was regelt § 92 BetrVG für die Personalplanung?", "o": ["Der Betriebsrat stellt den Personalplan ganz allein auf", "Ohne Personalplan darf keine Anzeige erscheinen", "Die Personalplanung braucht eine Genehmigung der IHK", "Der Arbeitgeber unterrichtet den Betriebsrat und berät mit ihm"], "c": 3, "e": "Schon bei der Personalplanung muss der Arbeitgeber den Betriebsrat unterrichten und mit ihm beraten (§ 92 BetrVG). Ein Recht, den Plan selbst aufzustellen, hat der Betriebsrat nicht."}, {"q": "Wann wird die innerbetriebliche Ausschreibung für den Arbeitgeber zur Pflicht?", "o": ["Sobald mehr als 20 Bewerbungen erwartet werden", "Nur bei Stellen mit Führungsaufgaben", "Wenn der Betriebsrat sie verlangt hat", "Bei jeder Stelle ab EG 9 automatisch"], "c": 2, "e": "Eine allgemeine Pflicht zur internen Ausschreibung gibt es nicht. Sie entsteht erst, wenn der Betriebsrat sie verlangt (§ 93 BetrVG)."}, {"q": "Was bedeutet der Begriff Betriebsblindheit?", "o": ["Die Beschäftigten sehen am Bildschirm wegen schlechter Beleuchtung wenig", "Der Betrieb hat keine Website und ist auf dem Arbeitsmarkt unbekannt", "Die Personalabteilung kennt die Namen der eigenen Beschäftigten nicht", "Es kommen wenig neue Ideen, weil alle nur die eigenen Abläufe kennen"], "c": 3, "e": "Betriebsblindheit ist ein Nachteil der internen Beschaffung. Wer nur den eigenen Betrieb kennt, bringt selten neue Ideen mit."}, {"q": "Welchen Vorteil bringt es, eine Stelle mit einer Person von außen zu besetzen?", "o": ["Im Betrieb entsteht keine neue Lücke", "Die Person ist dem Betrieb schon gut bekannt", "Die Kosten sind in der Regel am geringsten", "Die Einarbeitung ist besonders kurz"], "c": 0, "e": "Kommt die Person von außen, wird keine andere Stelle im Betrieb frei. Kurze Einarbeitung, bekannte Person und geringe Kosten sind Vorteile der internen Beschaffung."}, {"q": "Wofür steht das Akronym HAPPEN im Skript?", "o": ["Für die geschützten Merkmale nach dem AGG", "Für externe Wege von Hochschulen bis Netzwerke", "Für die sechs Bausteine einer Stellenanzeige", "Für die Phasen eines Vorstellungsgesprächs"], "c": 1, "e": "HAPPEN steht für Hochschulen und Messen, Agentur für Arbeit, Portale, Personalberater und Personalleasing, Empfehlungen sowie Netzwerke und eigene Website."}, {"q": "Welcher Reim beschreibt die übliche Reihenfolge der Suche?", "o": ["Erst die Welt, dann das Geld", "Erst der Lohn, dann die Person", "Erst hinaus, dann ins Haus", "Erst ins Haus, dann hinaus"], "c": 3, "e": "Zuerst prüft der Betrieb interne Lösungen, danach sucht er extern. Das schließt eine parallele Suche nicht aus."}, {"q": "Was bietet die Jobbörse der Agentur für Arbeit den Betrieben?", "o": ["Eine Garantie für eine Einstellung binnen einer Woche", "Eine bezahlte Direktansprache von Führungskräften", "Eine Pflicht, jede freie Stelle dort zu melden", "Eine kostenlose Plattform für Stellenangebote"], "c": 3, "e": "Die Agentur für Arbeit vermittelt Arbeitsuchende und bietet mit der Jobbörse eine kostenlose Plattform. Eine Einstellung garantiert sie nicht."}, {"q": "Wann wirken die eigene Website und Social Media als Beschaffungsweg besonders gut?", "o": ["Wenn die freie Stelle geheim bleiben soll", "Wenn nur Personen über 60 Jahre gesucht werden", "Wenn der Betrieb als Arbeitgeber schon bekannt ist", "Wenn der Betriebsrat das ausdrücklich verlangt"], "c": 2, "e": "Website und Social Media sind günstig. Sie wirken aber vor allem, wenn Menschen den Betrieb schon kennen und gezielt nach ihm suchen."}, {"q": "Wann zahlt Nordstern im Empfehlungsprogramm die Prämie?", "o": ["Am Ende jedes Kalenderjahres für alle Beschäftigten", "Wenn die empfohlene Person zum Gespräch kommt", "Wenn die empfohlene Person die Probezeit besteht", "Sobald eine beschäftigte Person einen Namen nennt"], "c": 2, "e": "Im Beispiel zahlt Nordstern 500 € Prämie, wenn die empfohlene Person eingestellt wird und die Probezeit besteht. So lohnt sich nur eine passende Empfehlung."}, {"q": "Wie heißt eine Bewerbung, die ohne vorherige Stellenanzeige beim Betrieb eingeht?", "o": ["Versetzung", "Active Sourcing", "Initiativbewerbung", "Interne Ausschreibung"], "c": 2, "e": "Bei einer Initiativbewerbung bewirbt sich die Person von sich aus. Active Sourcing ist dagegen die gezielte Ansprache durch den Betrieb."}, {"q": "Was ist der Verrechnungssatz beim Personalleasing?", "o": ["Der Lohn, den die Leiharbeitskraft vom Entleiher erhält", "Der Steuersatz, der auf Leiharbeit anfällt", "Die Gebühr für die Erlaubnis nach dem Gesetz", "Der Stundensatz, den der Entleiher an den Verleiher zahlt"], "c": 3, "e": "Der Entleiher bezahlt den Verleiher mit einem Stundensatz. Daraus zahlt der Verleiher das Entgelt der Leiharbeitskraft, seine Verwaltung und seinen Gewinn."}, {"q": "Wer zahlt einer Leiharbeitskraft das Entgelt während ihres Urlaubs?", "o": ["Der Entleiher", "Der Verleiher", "Die Krankenkasse", "Die Agentur für Arbeit"], "c": 1, "e": "Der Verleiher ist Arbeitgeber und zahlt das Entgelt, auch bei Urlaub und Krankheit."}, {"q": "Nach welcher Vorschrift gelten Bewerbende im Datenschutz als Beschäftigte?", "o": ["§ 26 Abs. 8 BDSG", "§ 93 BetrVG", "§ 11 AGG", "§ 3 ArbZG"], "c": 0, "e": "Bewerbende zählen im Datenschutz als Beschäftigte (§ 26 Abs. 8 BDSG). Darum gelten für ihre Daten die Regeln des Beschäftigtendatenschutzes."}, {"q": "Welche Formel beschreibt die Kosten für Personalleasing?", "o": ["Verrechnungssatz ÷ Leiharbeitskräfte × Wochen × Stunden je Woche", "Leiharbeitskräfte + Wochen + Stunden je Woche + Verrechnungssatz", "Leiharbeitskräfte × Wochen × Stunden je Woche × Verrechnungssatz", "Stunden je Woche × Verrechnungssatz ÷ 12 Monate × Leiharbeitskräfte"], "c": 2, "e": "Man rechnet alle Einsatzstunden aus und multipliziert sie mit dem Stundensatz des Verleihers (Beiderwieden & Stickdorn, 2026)."}, {"q": "Wie berechnet man die Kosten je Bewerbung für einen Beschaffungsweg?", "o": ["Kosten aller Wege ÷ Zahl aller Vorstellungsgespräche", "Kosten des Weges × Bewerbungen über diesen Weg", "Kosten des Weges ÷ Bewerbungen über diesen Weg", "Bewerbungen über diesen Weg ÷ Kosten des Weges"], "c": 2, "e": "Die Kosten des Weges werden durch die Zahl der Bewerbungen geteilt, die über genau diesen Weg kamen. Bei Nordstern sind das 1.200 € ÷ 30 = 40,00 €."}, {"q": "Warum sind die Kosten je Einstellung oft aussagekräftiger als die Kosten je Bewerbung?", "o": ["Der Betriebsrat legt die Kosten je Einstellung verbindlich fest", "Am Ende zählt die passende Person, nicht die Menge der Bewerbungen", "Die Kosten je Einstellung sind immer kleiner als je Bewerbung", "Bewerbungen dürfen aus Gründen des Datenschutzes nicht gezählt werden"], "c": 1, "e": "Viele Bewerbungen nützen wenig, wenn keine passende Person dabei ist. Deshalb zeigt die Zahl der Kosten je Einstellung besser, wie gut ein Weg wirklich ist."}, {"q": "Welche Aussage zur Arbeitgebermarke trifft zu?", "o": ["Bewerbende vergleichen Arbeitgeber heute ähnlich wie Produkte", "Eine Arbeitgebermarke wirkt ausschließlich auf die Kunden", "Eine Arbeitgebermarke macht jede Stellenanzeige überflüssig", "Eine Arbeitgebermarke kommt ohne Ehrlichkeit gut aus"], "c": 0, "e": "In Zeiten von Fachkräftemangel suchen sich Menschen ihren Arbeitgeber aus. Eine ehrliche Arbeitgebermarke hilft, im Vergleich aufzufallen (Beiderwieden & Stickdorn, 2026)."}, {"q": "Warum schadet ein Arbeitgeberversprechen, das im Alltag nicht stimmt?", "o": ["Es macht jede Anzeige im Portal deutlich teurer", "Es verstößt in jedem Fall gegen das Arbeitszeitgesetz", "Neue Beschäftigte werden enttäuscht und die Marke verliert Vertrauen", "Es verhindert grundsätzlich die Zustimmung des Betriebsrats"], "c": 2, "e": "Entscheidend beim Employer Branding ist die Ehrlichkeit. Ein falsches Versprechen enttäuscht neue Beschäftigte und schadet mehr, als es nützt."}, {"q": "Was bedeutet Desire in der AIDA-Formel bei einer Stellenanzeige?", "o": ["Die Aufmerksamkeit mit einem klaren Titel wecken", "Den Wunsch nach der Stelle wecken, etwa mit dem Angebot", "Die Bewerbenden mit einem Test nach Wissen prüfen", "Den Bewerbungsweg mit Frist und Ansprechperson nennen"], "c": 1, "e": "Desire heißt Wunsch. In der Anzeige weckt vor allem der Baustein Wir bieten mit Entgelt, Arbeitszeit und Zusatzleistungen den Wunsch nach der Stelle."}, {"q": "Was ist bei einer Stellenanzeige gesetzlich vor allem vorgeschrieben?", "o": ["Dass sie das Firmenlogo zeigt", "Dass sie niemanden benachteiligt", "Dass sie in einer Zeitung erscheint", "Dass sie genau sechs Bausteine hat"], "c": 1, "e": "Die sechs Bausteine sind bewährte Praxis. Gesetzlich gefordert ist vor allem, dass die Anzeige nicht gegen das Benachteiligungsverbot verstößt (§ 11 AGG)."}, {"q": "Warum sollte eine Stellenanzeige Muss- und Kann-Anforderungen klar trennen?", "o": ["Bewerbende erkennen, was zwingend und was nur wünschenswert ist", "Das AGG verbietet Kann-Anforderungen in jeder Stellenanzeige", "Der Betriebsrat stimmt sonst der Veröffentlichung nicht zu", "Kann-Anforderungen legen die Entgeltgruppe der Stelle fest"], "c": 0, "e": "Eine klare Trennung hilft passenden Personen bei der Entscheidung und hält unpassende Bewerbungen fern. Zugleich lassen sich die Kriterien später in der Vorauswahl nutzen."}, {"q": "Was sieht die EU-Entgelttransparenzrichtlinie für Bewerbende vor?", "o": ["Information über Einstiegsentgelt oder Gehaltsspanne vor dem Gespräch", "Wegfall des Vorstellungsgesprächs bei allen tarifgebundenen Betrieben", "Pflicht der Bewerbenden, alle früheren Arbeitsverträge vorzulegen", "Pflicht zum Foto in jeder Bewerbung für eine Stelle in der Industrie"], "c": 0, "e": "Die Richtlinie sieht vor, dass Bewerbende vor dem Gespräch das Einstiegsentgelt oder eine Spanne erfahren. Ein deutsches Umsetzungsgesetz gibt es im November 2026 noch nicht, sie ist also nur geplant."}, {"q": "Wie viele geschützte Merkmale zählt § 1 AGG auf?", "o": ["Acht", "Sechs", "Vier", "Zehn"], "c": 1, "e": "Geschützt sind Rasse oder ethnische Herkunft, Geschlecht, Religion oder Weltanschauung, Behinderung, Alter und sexuelle Identität (§ 1 AGG)."}, {"q": "Warum kann die Formulierung Berufseinsteiger mit wenigen Jahren Erfahrung riskant sein?", "o": ["Sie braucht vor der Veröffentlichung eine Zustimmung der IHK", "Sie kann ältere Personen indirekt wegen des Alters benachteiligen", "Sie benachteiligt ausschließlich Auszubildende im ersten Jahr", "Sie verstößt gegen die Höchstarbeitszeit nach dem Arbeitszeitgesetz"], "c": 1, "e": "Wer nur wenige Jahre Erfahrung sucht, schließt indirekt ältere Menschen aus. Solche versteckten Hinweise können ein Indiz für eine Benachteiligung wegen des Alters sein."}, {"q": "Welche Wirkung hat eine Stellenanzeige, die gegen das AGG verstößt, in einem späteren Streit?", "o": ["Sie hat im Streit keinerlei Bedeutung", "Sie gilt als Indiz für eine Benachteiligung", "Sie wird automatisch mit Haft bestraft", "Sie führt zum Verlust der Tarifbindung"], "c": 1, "e": "Ein Verstoß in der Anzeige ist ein Indiz. Dann muss der Arbeitgeber beweisen, dass er nicht benachteiligt hat (§ 22 AGG)."}, {"q": "Gibt es für die Stelle Sachbearbeitung Personal eine Ausnahme nach § 8 AGG?", "o": ["Ja, für das Geschlecht, weil die Abteilung klein ist", "Ja, für das Alter, weil die Stelle viel Erfahrung erfordert", "Nein, kein Merkmal ist dort entscheidende berufliche Anforderung", "Ja, wenn die Geschäftsführung es schriftlich festlegt"], "c": 2, "e": "Eine Ausnahme gibt es nur, wenn ein Merkmal wegen der Art der Tätigkeit wesentlich und entscheidend ist (§ 8 AGG). Für eine kaufmännische Sachbearbeitung trifft das nicht zu."}, {"q": "Was ist nach Oechsler und Paul das Ziel der Personalauswahl?", "o": ["Die Stelle möglichst schnell mit irgendwem besetzen", "Die Person mit dem niedrigsten Gehaltswunsch nehmen", "Möglichst viele Bewerbungen in kurzer Zeit sammeln", "Die Person finden, die am besten zum Anforderungsprofil passt"], "c": 3, "e": "Personalauswahl bedeutet, unter mehreren Bewerbenden die Person zu finden, die am besten zum Anforderungsprofil passt (Oechsler & Paul, 2019)."}, {"q": "Warum verzichten manche Betriebe heute auf das Anschreiben?", "o": ["Die Bewerbung soll einfacher werden, die Motivation folgt im Gespräch", "Anschreiben lassen sich in einem Portal technisch nicht hochladen", "Der Betriebsrat verlangt, dass nur der Lebenslauf gelesen wird", "Das AGG verbietet Anschreiben bei allen kaufmännischen Stellen"], "c": 0, "e": "Ein Verzicht auf das Anschreiben senkt die Hürde für eine Bewerbung. Die Motivation fragen solche Betriebe dann im Vorstellungsgespräch ab."}, {"q": "Welche Prüfung der Unterlagen ist für die Auswahl wichtiger und warum?", "o": ["Die formale, weil Ordnung über die Eignung entscheidet", "Die inhaltliche, weil die Eignung mehr zählt als ein Tippfehler", "Keine Prüfung zählt, entscheidend ist nur das Gespräch", "Die formale, weil sie das Vorstellungsgespräch ersetzt"], "c": 1, "e": "Ein kleiner Tippfehler sagt wenig über die Eignung als Sachbearbeitung. Eine fehlende kaufmännische Ausbildung sagt viel. Darum ist die inhaltliche Prüfung wichtiger."}, {"q": "Welche Frage stellt die Branchenanalyse an einen Lebenslauf?", "o": ["Ob die Person beruflich aufgestiegen ist", "Ob alle Unterlagen vollständig vorliegen", "Ob die Erfahrung aus einer passenden Branche stammt", "Ob der Lebenslauf zeitliche Lücken enthält"], "c": 2, "e": "Die Branchenanalyse fragt, ob die Erfahrung zur Branche des Betriebs passt, bei Nordstern also zur Industrie. Lücken prüft die Zeitfolgeanalyse, den Aufstieg die Positionsanalyse."}, {"q": "Was bedeutet beredtes Schweigen in einem Arbeitszeugnis?", "o": ["Eine erwartete Aussage fehlt und fällt gerade dadurch auf", "Das Zeugnis wurde nur mündlich und ohne Text erteilt", "Die Person hat im Vorstellungsgespräch kaum gesprochen", "Das Zeugnis trägt keine Unterschrift des Arbeitgebers"], "c": 0, "e": "Fehlt etwa bei einer Sachbearbeitung jede Aussage zur Zuverlässigkeit, fällt das auf. Das Weglassen kann also etwas aussagen."}, {"q": "Wo steckt die Gesamtnote zur Leistung in einem qualifizierten Zeugnis meist?", "o": ["In der Überschrift des Zeugnisses", "Im Briefkopf des Betriebs", "Im Ausstellungsdatum", "In der Zufriedenheitsformel"], "c": 3, "e": "Die Note zur Leistung steckt meist in der Zufriedenheitsformel. Kleine Wörter wie stets oder vollsten machen den Unterschied."}, {"q": "Was darf ein Arbeitszeugnis nach § 109 Abs. 2 GewO nicht enthalten?", "o": ["Eine Bewertung der Leistung", "Versteckte negative Aussagen", "Angaben zu Art und Dauer der Tätigkeit", "Die Unterschrift des Arbeitgebers"], "c": 1, "e": "Ein Zeugnis muss klar und verständlich sein und darf keine versteckten negativen Aussagen enthalten (§ 109 Abs. 2 GewO)."}, {"q": "Wie ist das Vorstellungsgespräch bei Nordstern personell besetzt?", "o": ["Der Betriebsrat führt das Gespräch ganz allein", "Eine einzige Person führt das Gespräch und schreibt mit", "Die bewerbende Person führt selbst das Protokoll", "Zwei Personen führen das Gespräch, eine dritte schreibt mit"], "c": 3, "e": "Bei Nordstern führen Malte Brandt und die Teamleitung das Gespräch, eine dritte Person protokolliert. Mehrere Beteiligte machen das Urteil objektiver."}, {"q": "Was misst ein Persönlichkeitstest?", "o": ["Die Fähigkeit zum logischen Denken", "Die Rechenfähigkeit unter Zeitdruck", "Die körperliche Belastbarkeit", "Eigenschaften wie Gewissenhaftigkeit"], "c": 3, "e": "Persönlichkeitstests erfassen Eigenschaften wie Gewissenhaftigkeit. Rechenfähigkeit misst ein Leistungstest, logisches Denken ein Intelligenztest."}, {"q": "Wofür braucht der Arbeitgeber nach § 95 BetrVG die Zustimmung des Betriebsrats?", "o": ["Für allgemeine Auswahlrichtlinien", "Für die Einladung zum Gespräch", "Für jede einzelne Stellenanzeige", "Für die Höhe der Fahrtkosten"], "c": 0, "e": "Allgemeine Regeln für die Auswahl, sogenannte Auswahlrichtlinien, brauchen die Zustimmung des Betriebsrats (§ 95 BetrVG)."}, {"q": "In der Lackiererei von Nordstern sollen die vorhandenen Beschäftigten eine neue Anlage zusätzlich bedienen und werden dafür geschult. Welcher Weg liegt vor?", "o": ["Externe Beschaffung über einen Verleiher mit gültiger Erlaubnis", "Externe Beschaffung über eine Initiativbewerbung aus der Region", "Interne Beschaffung ohne Personalbewegung durch Personalentwicklung", "Interne Beschaffung mit Personalbewegung durch eine Versetzung"], "c": 2, "e": "Niemand wechselt die Stelle und niemand kommt von außen. Die Beschäftigten werden für neue Aufgaben qualifiziert, das ist Personalentwicklung als interner Weg ohne Personalbewegung."}, {"q": "Der Betriebsrat von Nordstern hat keine interne Ausschreibung verlangt. Nordstern sucht eine Fachkraft für Lagerlogistik nur extern. Was gilt?", "o": ["Der Betriebsrat darf deshalb in jedem Fall die Zustimmung verweigern", "Die Stelle muss zusätzlich bei der IHK zu Lübeck gemeldet werden", "Das ist zulässig, ohne Verlangen gibt es keine Pflicht zur internen Ausschreibung", "Das ist unzulässig, jede Stelle muss zuerst im Betrieb ausgeschrieben werden"], "c": 2, "e": "Die interne Ausschreibung wird erst durch das Verlangen des Betriebsrats zur Pflicht (§ 93 BetrVG). Ohne Verlangen fehlt auch der Verweigerungsgrund aus § 99 Abs. 2 Nr. 5 BetrVG."}, {"q": "Ein Personalberater verlangt für die Teamleitung Qualität in EG 11 mit 4.500 € im Monat 25 % eines Jahresgehalts. Wie hoch ist das Honorar?", "o": ["13.500 €", "11.250 €", "10.800 €", "1.125 €"], "c": 0, "e": "Jahresgehalt 4.500 € × 12 = 54.000 €. Honorar 54.000 € × 0,25 = 13.500 €."}, {"q": "Ein Stand auf einer Jobmesse in Hamburg kostet Nordstern 900 € und bringt 15 Bewerbungen. Wie hoch sind die Kosten je Bewerbung?", "o": ["135,00 €", "16,67 €", "60,00 €", "6,00 €"], "c": 2, "e": "Kosten je Bewerbung = Kosten des Weges ÷ Bewerbungen über diesen Weg. 900 € ÷ 15 = 60,00 €."}, {"q": "Über den Messestand für 900 € stellt Nordstern am Ende 2 Personen ein. Wie hoch sind die direkten Kosten je Einstellung?", "o": ["60,00 €", "1.800,00 €", "450,00 €", "900,00 €"], "c": 2, "e": "Kosten je Einstellung = 900 € ÷ 2 = 450,00 €. Diese Kennzahl zeigt besser als die Kosten je Bewerbung, was ein Weg wirklich bringt."}, {"q": "Ein Personalberater würde für eine Stelle in EG 7 8.640 € kosten. Wie viele Portalanzeigen zu je 1.200 € könnte Nordstern dafür vollständig bezahlen?", "o": ["72 Anzeigen", "7 Anzeigen", "6 Anzeigen", "8 Anzeigen"], "c": 1, "e": "8.640 € ÷ 1.200 € = 7,2. Voll bezahlen lassen sich also 7 Anzeigen."}, {"q": "Ein Verleiher rechnet für eine Leiharbeitskraft bei Nordstern 152,25 Stunden im Monat zu 34,00 € ab. Welchen Betrag zahlt Nordstern je Monat?", "o": ["5.716,50 €", "3.600,00 €", "5.176,50 €", "4.476,50 €"], "c": 2, "e": "152,25 Stunden × 34,00 € = 5.176,50 €. Zum Vergleich kostet eine eigene Kraft in EG 7 im Monat 3.600 € brutto zuzüglich Arbeitgeberanteil."}, {"q": "Der Stundenlohn in EG 5 beträgt bei Nordstern 3.250 € ÷ 152,25 Stunden, gerundet 21,35 €. Wie groß ist der Unterschied zum Verrechnungssatz von 34,00 € je Stunde?", "o": ["10,35 €", "21,35 €", "12,65 €", "13,65 €"], "c": 2, "e": "34,00 € − 21,35 € = 12,65 € je Stunde. Der Unterschied deckt beim Verleiher Nebenkosten, Verwaltung und Gewinn."}, {"q": "Ein Verleiher ohne Erlaubnis bietet Nordstern besonders günstige Monteure an. Wie sollte Nordstern entscheiden?", "o": ["Ablehnen, weil der Verleiher eine Erlaubnis nach § 1 Abs. 1 AÜG braucht", "Annehmen, wenn die Monteure höchstens drei Monate bleiben", "Annehmen, wenn der Vertrag nur mündlich geschlossen wird", "Annehmen, weil beim Personalleasing allein der Preis entscheidet"], "c": 0, "e": "Wer Arbeitnehmer überlässt, braucht eine Erlaubnis (§ 1 Abs. 1 AÜG). Nordstern sollte nur mit Verleihern arbeiten, die diese Erlaubnis haben."}, {"q": "Nordstern wirbt auf seiner Website mit Gleitzeit für alle Beschäftigten. In der Montage gibt es aber Schichtbetrieb ohne Gleitzeit. Wie ist das zu beurteilen?", "o": ["Das Versprechen stimmt im Alltag nicht und schadet der Arbeitgebermarke", "Das ist unproblematisch, weil Werbung für Arbeitgeber immer übertreiben darf", "Das ist geschickt, weil dadurch insgesamt deutlich mehr Bewerbungen eingehen", "Das betrifft nur den Betriebsrat und nicht die Bewerbenden"], "c": 0, "e": "Employer Branding lebt von Ehrlichkeit. Gleitzeit gibt es bei Nordstern nur in der Verwaltung. Neue Monteure wären enttäuscht, und die Marke verliert Glaubwürdigkeit."}, {"q": "Ein abgelehnter Bewerber ruft bei Malte Brandt an und verlangt eine Entschädigung nach dem AGG. Einen Brief schickt er nicht. Was gilt?", "o": ["Ein Anspruch besteht nur für Beschäftigte nach bestandener Probezeit", "Ein Anruf reicht aus, wenn Malte Brandt ihn sorgfältig notiert", "Der Anspruch muss schriftlich geltend gemacht werden, ein Anruf reicht nicht", "Der Anspruch muss zuerst beim Betriebsrat schriftlich beantragt werden"], "c": 2, "e": "Nach § 15 Abs. 4 AGG ist der Anspruch schriftlich geltend zu machen. Bewerbende sind durch das AGG geschützt, auch ohne Arbeitsvertrag."}, {"q": "Von den 64 Bewerbungen bei Nordstern fielen 32 in Gruppe C. Welcher Anteil ist das?", "o": ["18,75 %", "32 %", "31,25 %", "50 %"], "c": 3, "e": "32 ÷ 64 × 100 = 50 %. Die Hälfte der Bewerbungen erfüllte mindestens ein Muss-Kriterium nicht."}, {"q": "Nordstern lädt 5 der 64 Bewerbenden zum Gespräch ein. Wie hoch ist der Anteil der Eingeladenen an allen Bewerbungen?", "o": ["7,81 %", "41,67 %", "12,80 %", "5,00 %"], "c": 0, "e": "5 ÷ 64 × 100 = 7,81 % (gerundet). 41,67 % wäre die Quote bezogen auf die 12 Personen der engeren Wahl."}, {"q": "Im Lebenslauf einer Bewerberin fehlen Angaben für März bis November 2023. Welche Frage im Gespräch ist am besten geeignet?", "o": ["Warum haben Sie in dieser Zeit überhaupt nichts gearbeitet?", "Hatten Sie in dieser Zeit finanzielle Probleme oder Schulden?", "Waren Sie in dieser Zeit vielleicht schwanger oder in Elternzeit?", "Erzählen Sie mir gern, was Sie von März bis November 2023 gemacht haben."], "c": 3, "e": "Lücken spricht man offen und wertschätzend an. Fragen nach Schwangerschaft oder Vermögen sind unzulässig, eine Unterstellung hilft nicht."}, {"q": "Ein Bewerber war 2019 bis 2021 Lagerhelfer, 2021 bis 2024 Schichtführer im Lager und ist seit 2024 Teamleiter Logistik. Was zeigt die Positionsanalyse?", "o": ["Fehlende Erfahrung im Bereich Lager und Logistik", "Einen klaren Aufstieg mit wachsender Verantwortung", "Eine auffällige Lücke von mehreren Jahren im Werdegang", "Viele Wechsel zwischen Firmen in sehr kurzer Zeit"], "c": 1, "e": "Die Positionsanalyse prüft, ob die Person Verantwortung übernommen hat und aufgestiegen ist. Vom Helfer über den Schichtführer zur Teamleitung ist ein deutlicher Aufstieg."}, {"q": "Frau A hat im Zeugnis stets zu unserer vollen Zufriedenheit, Frau B stets zu unserer Zufriedenheit. Welche Aussage trifft zu?", "o": ["Frau B hat die bessere Leistungsbewertung", "Frau A und Frau B haben die Note sehr gut", "Es sind zwei einfache Zeugnisse ohne Note", "Frau A hat die bessere Leistungsbewertung"], "c": 3, "e": "Stets zu unserer vollen Zufriedenheit steht für gut, stets zu unserer Zufriedenheit für befriedigend. Beide Zeugnisse bewerten die Leistung, sind also qualifiziert."}, {"q": "Ein anderer Betrieb schreibt in die Einladung ausdrücklich, dass Fahrtkosten nicht erstattet werden. Wer trägt die Kosten?", "o": ["Die Berufsgenossenschaft des Betriebs", "Trotzdem der einladende Betrieb", "Der Betriebsrat aus seinem Budget", "Die bewerbende Person selbst"], "c": 3, "e": "Die Pflicht zur Erstattung entfällt, wenn der Arbeitgeber sie vorher ausdrücklich ausgeschlossen hat. Dann trägt die bewerbende Person ihre Kosten selbst."}, {"q": "Eine Bewerberin wird bei Nordstern vor der Einstellung gefragt, ob sie schwerbehindert ist. Wie bewertet das Skript diese Frage?", "o": ["Sie ist wegen des Benachteiligungsverbots riskant und sollte unterbleiben", "Sie ist nur zulässig, wenn sie vorher schriftlich im Fragebogen steht", "Sie ist für den Arbeitgeber bei jeder Einstellung gesetzlich vorgeschrieben", "Sie ist bei jeder Stelle zulässig und gehört in jedes Vorstellungsgespräch"], "c": 0, "e": "Behinderung ist ein geschütztes Merkmal (§ 1 AGG). Die Frage vor der Einstellung ist riskant, weil eine Absage dann als Benachteiligung gedeutet werden kann."}, {"q": "Jana Hoffmann fragt im Gespräch bei Nordstern nach den Möglichkeiten zur Weiterbildung. In welcher Phase passiert das typischerweise?", "o": ["Begrüßung mit Small Talk", "Vorstellung des Unternehmens", "Eigene Fragen der Person", "Werdegang der Person"], "c": 2, "e": "Nach den Fach- und Motivfragen stellt die Person ihre eigenen Fragen. Danach folgen Konditionen und nächste Schritte."}, {"q": "Warum führt Nordstern für die eine Stelle Sachbearbeitung Personal kein Assessment-Center durch?", "o": ["Es darf nur für Leiharbeitskräfte genutzt werden", "Für eine einzige Sachbearbeitungsstelle ist es zu aufwendig", "Für kaufmännische Stellen ist es gesetzlich verboten", "Der Betriebsrat lehnt solche Verfahren grundsätzlich ab"], "c": 1, "e": "Ein AC ist teuer und braucht viel Planung. Für eine einzelne Sachbearbeitung nutzt Nordstern stattdessen eine kurze Arbeitsprobe mit Excel."}, {"q": "In einer Übung soll eine Teilnehmerin als Teamleitung mit einem Mitarbeiter sprechen, der oft zu spät kommt. Welche Übung des Assessment-Centers ist das?", "o": ["Rollenspiel", "Postkorb", "Präsentation", "Fallstudie"], "c": 0, "e": "Im Rollenspiel spielt die Person eine typische Gesprächssituation, zum Beispiel ein Kritikgespräch, mit einem Gegenüber durch."}, {"q": "Wie viele gewichtete Punkte bringt das Kriterium Kommunikation für Jana Hoffmann, wenn sie dort 9 von 10 Punkten hat und das Kriterium mit 20 % zählt?", "o": ["2,70", "1,80", "0,18", "18,00"], "c": 1, "e": "Gewichtete Punkte = Punkte × Gewicht. 9 × 0,20 = 1,80."}, {"q": "Jana Hoffmann erreicht einen Nutzwert von 7,80, Sophie Lange von 7,10. Wie groß ist der Abstand?", "o": ["0,70", "1,70", "0,40", "0,30"], "c": 0, "e": "7,80 − 7,10 = 0,70. Der Abstand zu Murat Yilmaz mit 7,50 beträgt dagegen nur 0,30."}, {"q": "Für eine Stelle im Lager nutzt Nordstern Fachwissen 50 %, Zuverlässigkeit 30 % und Teamfähigkeit 20 %. Ein Bewerber erhält 7, 8 und 6 Punkte. Wie hoch ist sein Nutzwert?", "o": ["21,00", "7,10", "7,00", "7,30"], "c": 1, "e": "7 × 0,50 + 8 × 0,30 + 6 × 0,20 = 3,50 + 2,40 + 1,20 = 7,10."}, {"q": "Bei denselben Gewichten von 50 %, 30 % und 20 % erhält eine Bewerberin für das Lager 6, 9 und 9 Punkte. Wie hoch ist ihr Nutzwert?", "o": ["7,50", "8,00", "24,00", "7,20"], "c": 0, "e": "6 × 0,50 + 9 × 0,30 + 9 × 0,20 = 3,00 + 2,70 + 1,80 = 7,50. Sie liegt damit vor dem Bewerber mit 7,10."}, {"q": "Jana Hoffmann mit 7,80 und Murat Yilmaz mit 7,50 liegen bei Nordstern knapp beieinander. Was empfiehlt das Skript?", "o": ["Jana Hoffmann und Murat Yilmaz ablehnen und neu ausschreiben", "Die Entscheidung per Los treffen, weil der Abstand so gering ist", "Ohne jedes Gespräch automatisch die Person mit dem höheren Wert nehmen", "Die Gründe besprechen, weil die Analyse nur eine Entscheidungshilfe ist"], "c": 3, "e": "Die Nutzwertanalyse ist eine Entscheidungshilfe, keine Maschine. Bei knappen Ergebnissen sollte der Betrieb die Gründe besprechen."}, {"q": "Malte Brandt unterrichtet den Betriebsrat am Mittwoch, 03.02.2027, über die Einstellung eines Monteurs. Wann endet die Frist für einen Widerspruch?", "o": ["Am Freitag, 05.02.2027", "Am Mittwoch, 10.02.2027", "Am Mittwoch, 17.02.2027", "Am Mittwoch, 03.03.2027"], "c": 1, "e": "Der Betriebsrat muss innerhalb einer Woche widersprechen (§ 99 Abs. 3 BetrVG). Eine Woche nach Mittwoch, dem 03.02.2027, ist Mittwoch, der 10.02.2027."}, {"q": "Der Betriebsrat von Nordstern widerspricht der Einstellung eines Monteurs innerhalb der Woche, aber nur mündlich in einem Gespräch. Was gilt?", "o": ["Der Widerspruch ist wirksam, weil mündlich innerhalb der Frist immer genügt", "Der Widerspruch reicht nicht, nach Fristablauf gilt die Zustimmung als erteilt", "Nordstern muss die Stelle nun zwingend neu intern und extern ausschreiben", "Die Frist verlängert sich dadurch automatisch um eine weitere Woche"], "c": 1, "e": "Der Betriebsrat muss schriftlich und mit Gründen widersprechen (§ 99 Abs. 3 BetrVG). Ein mündlicher Widerspruch genügt nicht."}, {"q": "Der Betriebsrat verweigert die Zustimmung zur Einstellung einer Bewerberin, weil sie ihm unsympathisch ist. Was gilt?", "o": ["Das ist ein zulässiger Grund zur Verweigerung", "Die Bewerberin muss sich erneut bewerben", "Nordstern darf die Bewerberin dann nie einstellen", "Das ist kein Grund aus § 99 Abs. 2 BetrVG"], "c": 3, "e": "Der Betriebsrat darf nur aus den Gründen in § 99 Abs. 2 BetrVG verweigern, etwa bei einem Gesetzesverstoß. Sympathie gehört nicht dazu."}, {"q": "Wer darf bei Nordstern auf die Daten der Bewerbenden zugreifen?", "o": ["Jede Kundin und jeder Kunde auf eine Nachfrage", "Nur die am Auswahlverfahren beteiligten Personen", "Andere Betriebe aus der Region für ihre Suche", "Alle Beschäftigten über das Intranet des Betriebs"], "c": 1, "e": "Bewerberdaten sind personenbezogene Daten. Zugriff haben nur die Beteiligten, also etwa Personalabteilung, Teamleitung und Betriebsrat."}, {"q": "Nordstern will die Adressen aller Bewerbenden nutzen, um Werbung für neue E-Bikes zu verschicken. Wie ist das zu beurteilen?", "o": ["Zulässig, sobald sechs Monate nach der Absage vergangen sind", "Unzulässig, die Daten dienen nur der Entscheidung über die Einstellung", "Zulässig, weil die Daten ohnehin schon im System gespeichert sind", "Zulässig, wenn der Betriebsrat der Werbung vorher zustimmt"], "c": 1, "e": "Nordstern darf Bewerberdaten nur verarbeiten, soweit das für die Entscheidung über die Einstellung erforderlich ist (Art. 6 Abs. 1 DSGVO). Werbung gehört nicht dazu."}, {"q": "Nordstern sucht eine Leitung für die neue Abteilung Akkuprüfung mit seltenem Spezialwissen. Intern gibt es niemanden. Welcher Weg passt am besten?", "o": ["Ein Personalberater mit Direktansprache", "Die Übernahme eines Auszubildenden nach der Prüfung", "Ein Aushang am Schwarzen Brett in der Kantine", "Mehrarbeit der Beschäftigten in der Qualitätssicherung"], "c": 0, "e": "Für Führungskräfte und seltene Spezialisten lohnt sich ein Personalberater. Er spricht gezielt auch Menschen an, die gerade nicht suchen."}], "lernen": [{"t": "Personalbeschaffung", "x": "Alle Maßnahmen, mit denen ein Betrieb fehlende Arbeitskräfte in richtiger Zahl, Qualifikation, Zeit, Ort und zu vertretbaren Kosten bereitstellt."}, {"t": "Interne Personalbeschaffung", "x": "Besetzung mit Beschäftigten aus dem eigenen Betrieb, mit Personalbewegung (Versetzung, Ausschreibung, Übernahme) oder ohne (Mehrarbeit, Aufstockung, Personalentwicklung)."}, {"t": "Innerbetriebliche Stellenausschreibung", "x": "Veröffentlichung einer freien Stelle im Betrieb. Der Betriebsrat kann sie verlangen (§ 93 BetrVG)."}, {"t": "Externe Personalbeschaffung", "x": "Suche auf dem Arbeitsmarkt, etwa über Agentur für Arbeit, Online-Portale, Website, Hochschulen, Personalberater oder Empfehlungen."}, {"t": "Personalleasing", "x": "Arbeitnehmerüberlassung. Ein Verleiher überlässt eigene Beschäftigte an einen Entleiher, der sie nach seinen Weisungen einsetzt."}, {"t": "Equal Pay", "x": "Leiharbeitskräfte erhalten grundsätzlich das gleiche Entgelt wie vergleichbare Stammbeschäftigte des Entleihers."}, {"t": "Employer Branding", "x": "Aufbau einer attraktiven Arbeitgebermarke, die Bewerbende anzieht und Beschäftigte bindet."}, {"t": "AIDA", "x": "Aufbauformel für Anzeigen mit Attention, Interest, Desire und Action."}, {"t": "Zeitfolgeanalyse", "x": "Prüfung des Lebenslaufs auf Lücken und häufige Wechsel."}, {"t": "Recht zur Lüge", "x": "Auf unzulässige Fragen im Vorstellungsgespräch darf die Person ohne Folgen falsch antworten."}, {"t": "Assessment-Center", "x": "Gruppenauswahlverfahren, in dem mehrere Beobachter mehrere Personen in mehreren Übungen nach festen Kriterien bewerten."}, {"t": "Nutzwertanalyse", "x": "Punktbewertung mit gewichteten Kriterien, die eine Auswahlentscheidung nachvollziehbar macht."}, {"t": "Zustimmung des Betriebsrats", "x": "In Unternehmen mit mehr als 20 wahlberechtigten Beschäftigten muss der Betriebsrat jeder Einstellung zustimmen, Widerspruch nur schriftlich mit Grund in einer Woche."}, {"t": "Stellenanzeige", "x": "Werbemittel für den Arbeitsmarkt, das aus Stellenbeschreibung und Anforderungsprofil das Wichtigste auswählt und das Angebot des Betriebs nennt. Die Stellenbeschreibung ist dagegen ein internes Organisationsmittel."}, {"t": "Werkvertrag", "x": "Vertrag, bei dem der Unternehmer ein fertiges Ergebnis schuldet und seinen Leuten selbst die Weisungen gibt. Beim Personalleasing schuldet der Verleiher nur geeignete Arbeitskräfte."}, {"t": "Kurzbewerbung", "x": "Bewerbung nur mit Anschreiben und Lebenslauf, weitere Unterlagen wie Zeugnisse werden auf Anforderung nachgereicht."}, {"t": "Tendenzbetrieb", "x": "Betrieb mit einer bestimmten geistigen oder politischen Ausrichtung, etwa eine Kirche oder Partei. Dort kann die Frage nach Religion oder Parteizugehörigkeit zulässig sein."}, {"t": "Personalbeschaffung", "x": "Personalbeschaffung umfasst alle Maßnahmen, mit denen ein Betrieb benötigte Arbeitskräfte in richtiger Anzahl, mit passender Qualifikation, zum richtigen Zeitpunkt, am richtigen Ort und zu vertretbaren Kosten bereitstellt (Beiderwieden & Stickdorn, 2026)."}, {"t": "Nur bei positivem Nettobedarf", "x": "Ist der Nettopersonalbedarf positiv, wird beschafft. Ist er negativ, besteht ein Minderbedarf, dann geht es um Personalfreistellung (mehr dazu am Tag 8)."}, {"t": "§ 93 BetrVG in einem Satz", "x": "Der Betriebsrat kann eine interne Ausschreibung verlangen. Fehlt sie trotz Verlangen, ist das ein Grund, die Zustimmung zur Einstellung zu verweigern."}, {"t": "Es gibt kein besser oder schlechter", "x": "Die Wahl hängt von der Stelle ab. Für Führungsaufgaben mit Betriebswissen passt oft intern, für viele neue Stellen oder neues Fachwissen eher extern. Meist kombiniert der Betrieb beide Wege."}, {"t": "Arbeitnehmerüberlassung", "x": "Ein Verleiher überlässt im Rahmen seiner wirtschaftlichen Tätigkeit Arbeitnehmer an einen Entleiher, der sie nach seinen Weisungen einsetzt (§ 1 Abs. 1 AÜG)."}, {"t": "Überlassung oder Werkvertrag?", "x": "Beim Personalleasing schuldet der Verleiher geeignete Arbeitskräfte, beim Werkvertrag schuldet der Unternehmer ein Ergebnis. Wer die Weisungen gibt, zeigt den Unterschied."}, {"t": "Employer Branding", "x": "Aufbau und Pflege einer Arbeitgebermarke, die den Betrieb für Bewerbende attraktiv und für Beschäftigte bindend macht (Beiderwieden & Stickdorn, 2026)."}, {"t": "Sechs Bausteine", "x": "Wir sind, Stelle, Ihre Aufgaben, Ihr Profil, Wir bieten, Kontakt mit Frist."}, {"t": "Beschreibung oder Anzeige", "x": "Die Stellenbeschreibung ordnet die Stelle nach innen, die Stellenanzeige wirbt nach außen. Die Anzeige baut auf der Beschreibung auf."}, {"t": "Erlaubt ist, was die Stelle wirklich braucht", "x": "Sachliche Anforderungen wie Ausbildung, Erfahrung, Sprachniveau, Belastbarkeit oder Führerschein sind zulässig."}, {"t": "Absagen erst nach der Zustimmung", "x": "Schicken Sie Absagen an die besten Personen erst, wenn der Betriebsrat zugestimmt hat. Lehnt er ab, braucht man vielleicht die zweitbeste Person."}, {"t": "Der ganze Beschaffungsprozess", "x": "Bedarf ermitteln, Stelle beschreiben, Weg wählen, ausschreiben, auswählen, Betriebsrat beteiligen, Vertrag schließen, einarbeiten."}, {"t": "Formale und inhaltliche Prüfung", "x": "Die formale Prüfung bewertet Vollständigkeit und äußere Form der Unterlagen, die inhaltliche Prüfung die Eignung im Vergleich zum Anforderungsprofil (Beiderwieden & Stickdorn, 2026)."}, {"t": "Erst der Inhalt, dann die Form", "x": "Für die Auswahl zählt vor allem, ob die Person die Muss-Anforderungen der Stelle erfüllt."}, {"t": "Kurzbewerbung", "x": "Bewerbung nur mit Anschreiben und Lebenslauf, weitere Unterlagen wie Zeugnisse werden auf Anforderung nachgereicht (Beiderwieden & Stickdorn, 2026)."}, {"t": "Strukturiert ist fairer", "x": "Gleiche Fragen, gleiche Bewertungsmaßstäbe, mehrere Gesprächsführende. So werden Antworten vergleichbar und Vorurteile weniger wirksam."}, {"t": "Recht zur Lüge", "x": "Auf eine unzulässige Frage darf die Person falsch antworten, ohne dass der Arbeitgeber den Vertrag deshalb anfechten kann. Bei zulässigen Fragen droht die Anfechtung wegen arglistiger Täuschung (§ 123 BGB)."}, {"t": "Assessment-Center", "x": "Mehrere Beobachter bewerten mehrere Kandidaten in mehreren Übungen nach festgelegten Kriterien (Oechsler & Paul, 2019)."}, {"t": "§ 99 BetrVG in Zahlen", "x": "Mehr als 20 wahlberechtigte Beschäftigte, eine Woche Frist, schriftlich mit Gründen, sonst gilt die Zustimmung als erteilt."}], "sortier": [{"titel": "Intern oder extern beschaffen?", "auftrag": "Ordne jeden Weg und jedes Merkmal der internen oder der externen Personalbeschaffung zu.", "kategorien": [{"id": "a", "name": "Interne Beschaffung"}, {"id": "b", "name": "Externe Beschaffung"}], "items": [{"text": "Stelle im Intranet und am Aushang ausschreiben", "kat": "a", "expl": "Intranet und Aushang erreichen nur die eigenen Beschäftigten. Das ist interne Beschaffung."}, {"text": "Übernahme der Auszubildenden nach der Prüfung", "kat": "a", "expl": "Die Azubis sind schon im Betrieb. Die Übernahme ist ein interner Weg mit Personalbewegung."}, {"text": "Eine Teilzeitkraft stockt auf 35 Stunden auf", "kat": "a", "expl": "Niemand kommt neu hinzu. Das ist interne Beschaffung ohne Personalbewegung."}, {"text": "Versetzung einer Monteurin aus der Vormontage", "kat": "a", "expl": "Die Person wechselt nur die Abteilung. Sie bleibt im Betrieb."}, {"text": "Vorteil, die Person und ihre Leistung sind bekannt", "kat": "a", "expl": "Bei eigenen Beschäftigten kennt Nordstern die Leistung schon. Das spricht für intern."}, {"text": "Nachteil, an anderer Stelle entsteht eine neue Lücke", "kat": "a", "expl": "Wer intern wechselt, fehlt am alten Platz. Diese Lücke ist ein Nachteil der internen Suche."}, {"text": "Mehrarbeit der vorhandenen Belegschaft", "kat": "a", "expl": "Die eigenen Leute arbeiten mehr. Das ist intern ohne Personalbewegung, mit Grenzen nach dem ArbZG."}, {"text": "Stellenangebot in der Jobbörse der Agentur für Arbeit", "kat": "b", "expl": "Die Jobbörse spricht den Arbeitsmarkt an. Sie ist für Nordstern kostenlos."}, {"text": "Anzeige im Online-Portal für 1.200 €", "kat": "b", "expl": "Ein Online-Portal sucht außerhalb des Betriebs. Das ist externe Beschaffung."}, {"text": "Personalberater für 20 % eines Jahresgehalts", "kat": "b", "expl": "Der Berater sucht auf dem Arbeitsmarkt. Bei EG 9 kostet das 9.480 €."}, {"text": "Leiharbeitnehmer über einen Verleiher einsetzen", "kat": "b", "expl": "Personalleasing holt Personal von außen. Es ist ein externer Weg nach dem AÜG."}, {"text": "Vorteil, neue Ideen kommen von außen in den Betrieb", "kat": "b", "expl": "Neue Personen bringen fremde Erfahrung mit. Das ist ein Vorteil der externen Suche."}, {"text": "Nachteil, hohe Kosten und Risiko einer Fehlbesetzung", "kat": "b", "expl": "Externe Suche dauert lange und kostet viel. Die Person ist noch unbekannt."}, {"text": "Stand auf einer Jobmesse in der Region", "kat": "b", "expl": "Auf der Messe trifft Nordstern Bewerbende von außen. Das ist externe Beschaffung."}]}, {"titel": "Darf Nordstern das fragen?", "auftrag": "Entscheide für jede Frage im Gespräch für die Stelle Sachbearbeitung Personal, ob sie zulässig ist.", "kategorien": [{"id": "a", "name": "Zulässige Frage"}, {"id": "b", "name": "Unzulässige Frage"}], "items": [{"text": "Welche Personalsoftware haben Sie bisher genutzt?", "kat": "a", "expl": "Die Frage betrifft fachliche Kenntnisse für die Stelle. Sie ist zulässig."}, {"text": "Wie lang ist Ihre Kündigungsfrist?", "kat": "a", "expl": "Nordstern muss den Eintrittstermin planen. Darum darf es danach fragen."}, {"text": "Welche Gehaltsvorstellung haben Sie?", "kat": "a", "expl": "Das Gehalt gehört zum Vertrag. Die Frage hat Bezug zur Stelle."}, {"text": "Welche Ausbildung haben Sie abgeschlossen?", "kat": "a", "expl": "Die Ausbildung ist eine Anforderung der Stelle. Fragen dazu sind erlaubt."}, {"text": "Wie gut sind Ihre Excel-Kenntnisse?", "kat": "a", "expl": "Excel steht im Profil der Anzeige. Die Frage dient der Auswahl."}, {"text": "Wann könnten Sie bei uns anfangen?", "kat": "a", "expl": "Der Eintritt ist für die Planung wichtig. Diese Frage ist zulässig."}, {"text": "Welche Erfahrung haben Sie mit Bewerbermanagement?", "kat": "a", "expl": "Bewerbermanagement gehört zu den Aufgaben der Stelle. Die Frage ist erlaubt."}, {"text": "Planen Sie in den nächsten Jahren Kinder?", "kat": "b", "expl": "Familienplanung hat keinen Bezug zur Stelle und benachteiligt wegen des Geschlechts. Es gilt das Recht zur Lüge."}, {"text": "Sind Sie Mitglied der IG Metall?", "kat": "b", "expl": "Die Mitgliedschaft in einer Gewerkschaft ist geschützt. Die Frage ist unzulässig."}, {"text": "Welcher Religion gehören Sie an?", "kat": "b", "expl": "Nordstern ist kein kirchlicher Betrieb. Die Religion geht den Arbeitgeber nichts an."}, {"text": "In welcher Partei sind Sie Mitglied?", "kat": "b", "expl": "Die Parteizugehörigkeit hat nichts mit der Stelle zu tun. Die Frage ist verboten."}, {"text": "Sind Sie zurzeit schwanger?", "kat": "b", "expl": "Die Frage benachteiligt Frauen. Eine falsche Antwort hat keine Folgen."}, {"text": "Wie hoch sind Ihre Ersparnisse?", "kat": "b", "expl": "Das Vermögen ist privat und für diese Stelle ohne Bedeutung. Die Frage ist unzulässig."}, {"text": "Wie ist Ihr allgemeiner Gesundheitszustand?", "kat": "b", "expl": "Allgemeine Fragen zur Gesundheit sind nicht erlaubt. Es zählt nur, was für die Stelle entscheidend ist."}]}]}, {"nr": 4, "title": "Personaleinstellung", "date": "26.11.2026", "quiz": [{"q": "Welches Merkmal kennzeichnet einen Arbeitnehmer nach § 611a BGB am stärksten?", "o": ["Er arbeitet weisungsgebunden im Dienst eines anderen", "Er trägt das unternehmerische Risiko selbst und wirbt Kunden", "Er bestimmt Ort und Zeit der Arbeit frei", "Er stellt dem Auftraggeber Rechnungen"], "c": 0, "e": "Weisungsgebundenheit und Eingliederung in fremde Organisation sind die Kernmerkmale. Selbstständige tragen eigenes Risiko und entscheiden frei."}, {"q": "Der Arbeitsvertrag von Jana Hoffmann enthält eine Versetzungsklausel. Was darf Nordstern damit?", "o": ["Eine andere, gleichwertige und gleich bezahlte Tätigkeit zuweisen", "Jede Tätigkeit zuweisen, auch mit niedrigerem Entgelt", "Das vereinbarte Entgelt einseitig kürzen", "Die Probezeit auf zwölf Monate verlängern"], "c": 0, "e": "Eine Versetzungsklausel erlaubt nur gleichwertige Tätigkeiten, die den Fähigkeiten entsprechen und gleich bezahlt werden. Sie bleibt im Rahmen des Weisungsrechts (§ 106 GewO)."}, {"q": "Was versteht man unter Schriftform?", "o": ["Papierdokument mit eigenhändiger Unterschrift", "PDF-Datei im Anhang einer E-Mail", "Nachricht über einen Messenger-Dienst", "Eingescannte Unterschrift auf einem Foto per Messenger"], "c": 0, "e": "Schriftform verlangt die eigenhändige Unterschrift auf dem Dokument. PDF, Messenger und Scan sind höchstens Textform."}, {"q": "Welches Gesetz verpflichtet den Arbeitgeber, die wesentlichen Arbeitsbedingungen aufzuschreiben?", "o": ["Nachweisgesetz", "Tarifvertragsgesetz", "Bundesurlaubsgesetz", "Berufsbildungsgesetz für alle Beschäftigten"], "c": 0, "e": "§ 2 NachwG verlangt den Nachweis der wesentlichen Vertragsbedingungen. Das BBiG gilt nur für Ausbildungsverhältnisse."}, {"q": "Seit wann darf der Nachweis der Arbeitsbedingungen grundsätzlich in Textform erfolgen?", "o": ["Seit dem 01.01.2025", "Seit dem 01.08.2022", "Seit dem 01.01.2020", "Seit dem 01.01.2027"], "c": 0, "e": "Das Vierte Bürokratieentlastungsgesetz hat die Textform zum 01.01.2025 zugelassen. Die Fassung von 2022 verlangte noch Papier."}, {"q": "Bis wann müssen Name, Entgelt und Arbeitszeit spätestens nachgewiesen sein?", "o": ["Am ersten Arbeitstag", "Am siebten Kalendertag", "Einen Monat nach Beginn", "Mit Ende der Probezeit"], "c": 0, "e": "Nach § 2 Abs. 1 NachwG gehören Parteien, Entgelt und Arbeitszeit zu den Angaben, die am ersten Arbeitstag vorliegen müssen."}, {"q": "Jana Hoffmann beginnt am 01.02.2027. Bis wann muss die Probezeit spätestens nachgewiesen sein?", "o": ["Bis zum 08.02.2027", "Bis zum 01.02.2027", "Bis zum 01.03.2027", "Bis zum 31.07.2027"], "c": 0, "e": "Die Probezeit gehört zu den Angaben, die spätestens am siebten Kalendertag nach Beginn vorliegen müssen. Sieben Tage nach dem 01.02. ist der 08.02.2027."}, {"q": "Welche Folge hat ein Verstoß gegen die Nachweispflicht?", "o": ["Ordnungswidrigkeit mit Bußgeld bis 2.000 €", "Der Arbeitsvertrag wird rückwirkend nichtig und muss neu geschlossen werden", "Der Vertrag gilt als befristet", "Die Probezeit verlängert sich automatisch"], "c": 0, "e": "Nach § 4 NachwG ist der Verstoß eine Ordnungswidrigkeit. Der Arbeitsvertrag selbst bleibt wirksam."}, {"q": "Wann ist kein gesonderter Nachweis nach dem Nachweisgesetz nötig?", "o": ["Wenn der ausgehändigte Vertrag alle Angaben enthält", "Wenn die Person Mitglied der zuständigen Gewerkschaft ist", "Wenn der Betrieb weniger als 20 Beschäftigte hat", "Wenn der Vertrag befristet ist"], "c": 0, "e": "§ 2 Abs. 5 NachwG lässt den Nachweis entfallen, soweit ein schriftlicher Vertrag mit allen Angaben ausgehändigt wurde."}, {"q": "Welches Gesetz regelt die Befristung von Arbeitsverträgen?", "o": ["Teilzeit- und Befristungsgesetz", "Kündigungsschutzgesetz", "Arbeitszeitgesetz mit seinen Sonderregeln", "Mindestlohngesetz"], "c": 0, "e": "Die Befristung regeln §§ 14 bis 21 TzBfG. Das KSchG betrifft die Kündigung."}, {"q": "Wie lange darf eine sachgrundlose Befristung bei einer normalen Neueinstellung höchstens dauern?", "o": ["Zwei Jahre", "Ein Jahr", "Drei Jahre", "Fünf Jahre"], "c": 0, "e": "§ 14 Abs. 2 TzBfG erlaubt höchstens zwei Jahre. Längere Zeiten gelten nur bei Neugründung oder ab 52 Jahren unter Voraussetzungen."}, {"q": "Wie oft darf ein sachgrundlos befristeter Vertrag innerhalb von zwei Jahren höchstens verlängert werden?", "o": ["Dreimal", "Einmal", "Zweimal", "Viermal"], "c": 0, "e": "Bis zur Gesamtdauer von zwei Jahren sind höchstens drei Verlängerungen zulässig (§ 14 Abs. 2 TzBfG)."}, {"q": "Wann ist eine sachgrundlose Befristung bei Nordstern ausgeschlossen?", "o": ["Wenn die Person früher schon bei Nordstern angestellt war", "Wenn die Person zum ersten Mal bei Nordstern arbeitet", "Wenn die Person in der Montage im Zweischichtbetrieb arbeitet", "Wenn die Person in Teilzeit arbeitet"], "c": 0, "e": "Das Vorbeschäftigungsverbot in § 14 Abs. 2 TzBfG schließt eine sachgrundlose Befristung bei früherem Arbeitsverhältnis mit demselben Arbeitgeber aus."}, {"q": "Was gilt, wenn eine Befristung nicht schriftlich vereinbart wurde?", "o": ["Der Vertrag gilt als unbefristet", "Der Vertrag ist insgesamt nichtig", "Der Vertrag endet nach der Probezeit", "Der Vertrag endet nach zwei Jahren"], "c": 0, "e": "Fehlt die Schriftform, ist nur die Befristung unwirksam. Der Arbeitsvertrag besteht weiter, und zwar unbefristet."}, {"q": "Bis wann muss eine Befristung spätestens unterschrieben sein?", "o": ["Vor Beginn der Arbeit", "Bis zum Ende der ersten Woche", "Bis zum Ende der Probezeit", "Bis zur ersten Gehaltsabrechnung"], "c": 0, "e": "Wird erst nach Arbeitsbeginn unterschrieben, ist bereits ein mündlicher, unbefristeter Vertrag entstanden."}, {"q": "Unter welcher Voraussetzung kann ein befristeter Vertrag während der Laufzeit ordentlich gekündigt werden?", "o": ["Wenn die Kündigung im Vertrag oder Tarif vereinbart ist", "Immer, mit einer gesetzlichen Frist von vier Wochen zum Monatsende", "Nie, auch nicht bei Vereinbarung", "Nur mit Zustimmung der Agentur für Arbeit"], "c": 0, "e": "§ 15 Abs. 4 TzBfG erlaubt die ordentliche Kündigung nur, wenn sie einzelvertraglich oder im anwendbaren Tarifvertrag vereinbart ist."}, {"q": "Nach Ablauf seiner Befristung arbeitet ein Lagerhelfer mit Wissen des Lagerleiters einfach weiter. Nordstern widerspricht nicht. Was gilt?", "o": ["Es entsteht ein unbefristetes Arbeitsverhältnis", "Der Vertrag verlängert sich um genau ein Jahr", "Er arbeitet ab sofort ohne Vertrag und hat keinen Anspruch auf Lohn", "Die Probezeit beginnt neu"], "c": 0, "e": "§ 15 Abs. 6 TzBfG ordnet bei widerspruchsloser Fortsetzung ein unbefristetes Arbeitsverhältnis an."}, {"q": "Wann endet eine Zweckbefristung, etwa bis zur Rückkehr einer Kollegin aus der Elternzeit?", "o": ["Mit Erreichen des Zwecks, frühestens zwei Wochen nach schriftlicher Mitteilung", "Sofort am Tag der Rückkehr ohne Mitteilung", "Immer erst nach zwei Jahren", "Erst nach einer schriftlichen Kündigung mit einer Frist von vier Wochen"], "c": 0, "e": "§ 15 Abs. 2 TzBfG verlangt eine schriftliche Unterrichtung über die Zweckerreichung. Der Vertrag endet frühestens zwei Wochen danach."}, {"q": "Was ist seit dem 01.01.2026 bei Beschäftigten nach Erreichen der Regelaltersgrenze neu?", "o": ["Sachgrundlose Befristung auch beim bisherigen Arbeitgeber möglich", "Sie dürfen nur noch in Teilzeit arbeiten", "Ihr Arbeitsvertrag endet automatisch mit dem Rentenbeginn ohne Ausnahme", "Sie brauchen keinen Arbeitsvertrag mehr"], "c": 0, "e": "§ 41 SGB VI erlaubt seit 2026 nach Erreichen der Regelaltersgrenze eine sachgrundlose Befristung auch mit demselben Arbeitgeber."}, {"q": "Wie lange darf eine Probezeit im Arbeitsvertrag höchstens dauern?", "o": ["Sechs Monate", "Drei Monate", "Vier Monate", "Zwölf Monate"], "c": 0, "e": "§ 622 Abs. 3 BGB begrenzt die Probezeit mit verkürzter Kündigungsfrist auf sechs Monate. Vier Monate ist die Höchstgrenze in der Ausbildung."}, {"q": "Welche Kündigungsfrist gilt während einer vereinbarten Probezeit?", "o": ["Zwei Wochen", "Vier Wochen zum 15. oder Monatsende", "Ein Monat zum Monatsende", "Keine Frist, Kündigung sofort"], "c": 0, "e": "In der Probezeit beträgt die Frist nach § 622 Abs. 3 BGB zwei Wochen. Eine Kündigung ohne Frist und ohne wichtigen Grund gibt es in der Probezeit nur in der Ausbildung (§ 22 Abs. 1 BBiG)."}, {"q": "Jana Hoffmann beginnt am 01.02.2027 mit sechs Monaten Probezeit. Wann endet die Probezeit?", "o": ["Am 31.07.2027", "Am 01.08.2027", "Am 30.06.2027", "Am 31.08.2027"], "c": 0, "e": "Sechs Monate ab dem 01.02. enden mit Ablauf des 31.07.2027."}, {"q": "Worin unterscheidet sich die Probezeit von der Wartezeit des Kündigungsschutzgesetzes?", "o": ["Die Wartezeit gilt automatisch, die Probezeit nur nach Vereinbarung", "Die Probezeit regelt den Kündigungsschutz, die Wartezeit den Urlaub", "Beides ist dasselbe und dauert immer drei Monate", "Die Wartezeit gilt nur für Auszubildende"], "c": 0, "e": "Die Wartezeit von sechs Monaten nach § 1 KSchG gilt immer. Die Probezeit verkürzt nur die Kündigungsfrist und muss vereinbart sein."}, {"q": "Ein Vertrag ist auf sechs Monate befristet. Was gilt für die Probezeit?", "o": ["Sie muss im Verhältnis zur Dauer der Befristung stehen", "Sie muss immer genau sechs Monate betragen", "Sie ist bei Befristung verboten", "Sie verlängert die Befristung automatisch um die Probezeit"], "c": 0, "e": "Nach § 15 Abs. 3 TzBfG muss die Probezeit zur Dauer und Art der Tätigkeit passen. Sechs Monate Probezeit bei sechs Monaten Vertrag wären zu lang."}, {"q": "Welche Form braucht ein Tarifvertrag?", "o": ["Schriftform", "Textform genügt", "Mündliche Einigung genügt", "Notarielle Beurkundung"], "c": 0, "e": "§ 1 Abs. 2 TVG schreibt für Tarifverträge die Schriftform vor."}, {"q": "Was regelt ein Tarifvertrag über vermögenswirksame Leistungen?", "o": ["Den Arbeitgeberanteil zu einem Sparvertrag der Beschäftigten", "Die Höhe der Lohnsteuer für alle Beschäftigten", "Die Verteilung der Arbeitszeit auf die Wochentage", "Die Kündigungsfrist während der Probezeit"], "c": 0, "e": "Vermögenswirksame Leistungen zahlt der Arbeitgeber zusätzlich zum Entgelt in einen Sparvertrag. Die Höhe seines Anteils steht im Tarifvertrag (Beiderwieden & Stickdorn, 2026)."}, {"q": "Welcher Tarifvertrag legt fest, nach welchen Merkmalen Tätigkeiten den Entgeltgruppen zugeordnet werden?", "o": ["Rahmentarifvertrag", "Manteltarifvertrag", "Haustarifvertrag", "Arbeitsvertrag"], "c": 0, "e": "Der Rahmentarifvertrag beschreibt Entgeltgruppen und Eingruppierungsmerkmale."}, {"q": "Welcher Tarifvertrag wird meist am häufigsten neu verhandelt?", "o": ["Der Entgelttarifvertrag", "Der Manteltarifvertrag", "Der Rahmentarifvertrag", "Die Betriebsvereinbarung"], "c": 0, "e": "Der Entgelttarifvertrag hat meist eine kurze Laufzeit von ein bis zwei Jahren."}, {"q": "Wodurch unterscheidet sich ein Haustarifvertrag von einem Flächentarifvertrag?", "o": ["Er wird von einem einzelnen Unternehmen abgeschlossen", "Er gilt für eine ganze Branche in einer Region", "Er wird vom Betriebsrat abgeschlossen", "Er wird ohne Gewerkschaft zwischen Geschäftsführung und Belegschaft geschlossen"], "c": 0, "e": "Den Haustarif schließt ein einzelner Arbeitgeber mit der Gewerkschaft. Der Flächentarif gilt für die Verbandsmitglieder einer Branche und Region."}, {"q": "Warum ist Nordstern an den Tarifvertrag der Metall- und Elektroindustrie gebunden?", "o": ["Weil Nordstern Mitglied im Arbeitgeberverband ist", "Weil Nordstern mehr als 200 Beschäftigte in Norderstedt hat", "Weil Nordstern einen Betriebsrat hat", "Weil Nordstern Auszubildende beschäftigt"], "c": 0, "e": "Tarifgebunden sind nach § 3 TVG die Mitglieder der Tarifparteien. Größe, Betriebsrat oder Ausbildung begründen keine Tarifbindung."}, {"q": "Jana Hoffmann ist kein Mitglied der IG Metall. Wie erhält sie trotzdem das Tarifentgelt?", "o": ["Über eine Bezugnahmeklausel im Arbeitsvertrag", "Über eine Anordnung der IHK zu Lübeck für alle Industriebetriebe", "Über die DEÜV-Anmeldung", "Über das Nachweisgesetz"], "c": 0, "e": "Nordstern verweist im Arbeitsvertrag auf die Tarifverträge. So gelten sie für alle Beschäftigten, auch ohne Gewerkschaftsmitgliedschaft."}, {"q": "Was bedeutet Nachwirkung eines Tarifvertrags?", "o": ["Nach Ablauf gelten die Regeln weiter, bis eine neue Abmachung sie ersetzt", "Der Tarif gilt rückwirkend für fünf Jahre", "Nach Ablauf entfallen alle tariflichen Ansprüche sofort und ersatzlos", "Der Tarif gilt nur noch für Auszubildende"], "c": 0, "e": "§ 4 Abs. 5 TVG lässt die Rechtsnormen nach Ablauf weitergelten, bis sie durch eine andere Abmachung ersetzt werden."}, {"q": "Ein Facharbeiter in EG 7 vereinbart im Vertrag 3.500 € statt 3.600 €. Welches Entgelt erhält er?", "o": ["3.600 €", "3.500 €", "3.550 €", "2.900 €"], "c": 0, "e": "Die ungünstigere Vereinbarung ist unwirksam. Es gilt der Tarifwert von 3.600 €."}, {"q": "Wie hoch ist der Stundenlohn in EG 9 der vereinfachten Nordstern-Tabelle?", "o": ["25,94 €", "22,57 €", "26,33 €", "23,65 €"], "c": 0, "e": "3.950 € ÷ 152,25 Stunden = 25,94 €. 23,65 € ist der Stundenlohn in EG 7."}, {"q": "Woraus ergibt sich der Teiler 152,25 Stunden im Nordstern-Beispiel?", "o": ["35 Wochenstunden × 4,35 Wochen", "40 Wochenstunden × 4,35 Wochen", "35 Wochenstunden × 4 Wochen", "38 Wochenstunden × 4 Wochen"], "c": 0, "e": "35 × 4,35 = 152,25. Mit 40 Stunden ergäben sich 174 Stunden."}, {"q": "Was bedeutet Friedenspflicht?", "o": ["Kein Arbeitskampf über tariflich geregelte Fragen während der Laufzeit", "Beschäftigte dürfen während der Laufzeit keine Kritik am Arbeitgeber äußern", "Der Betriebsrat darf keine Einwände erheben", "Streiks sind in Deutschland grundsätzlich verboten"], "c": 0, "e": "Die Friedenspflicht schließt Streiks über Inhalte des laufenden Tarifvertrags aus. Nach Ablauf sind Arbeitskämpfe zulässig."}, {"q": "Wann darf die IG Metall für höhere Entgelte bei Nordstern streiken?", "o": ["Nach Ablauf des Entgelttarifvertrags", "Jederzeit während der Laufzeit", "Nur mit vorheriger Zustimmung der Geschäftsführung von Nordstern", "Nur am Ende eines Geschäftsjahres"], "c": 0, "e": "Während der Laufzeit gilt die Friedenspflicht. Erst danach ist ein Arbeitskampf über die Entgelthöhe möglich."}, {"q": "Wer muss bei Nordstern der Eingruppierung einer neuen Sachbearbeiterin zustimmen?", "o": ["Der Betriebsrat", "Die IG Metall", "Die IHK zu Lübeck", "Die Krankenkasse"], "c": 0, "e": "Nach § 99 BetrVG braucht Nordstern als Unternehmen mit mehr als 20 wahlberechtigten Beschäftigten die Zustimmung des Betriebsrats bei Einstellung und Eingruppierung."}, {"q": "Wie ermittelt die Personalabteilung das Tarifentgelt für eine neue Stelle?", "o": ["Stelle mit dem Rahmentarif vergleichen, dann Betrag im Entgelttarif ablesen", "Gehaltswunsch erfragen, dann die passende Entgeltgruppe wählen", "Betrag im Manteltarif ablesen, dann die Stelle beschreiben", "Den Betriebsrat den Betrag frei festlegen lassen"], "c": 0, "e": "Die Eingruppierung läuft in zwei Schritten. Die Tätigkeitsmerkmale im Rahmentarif bestimmen die Entgeltgruppe, der Entgelttarif nennt den Betrag (Beiderwieden & Stickdorn, 2026)."}, {"q": "Warum gilt bei der Nordstern Service GmbH kein Tarifvertrag?", "o": ["Sie ist nicht Mitglied im Arbeitgeberverband und hat keinen Haustarif", "Sie hat weniger als 50 Beschäftigte und ist deshalb vom Tarifrecht befreit", "Tarifverträge gelten nur in Schleswig-Holstein", "Die Muttergesellschaft hat es ihr untersagt"], "c": 0, "e": "Tarifgebunden sind nur Mitglieder der Tarifparteien oder Arbeitgeber mit eigenem Haustarif (§ 3 TVG). Die Betriebsgröße spielt keine Rolle."}, {"q": "Warum braucht die Service GmbH bei einer Einstellung keine Zustimmung nach § 99 BetrVG?", "o": ["Sie hat nicht mehr als 20 wahlberechtigte Arbeitnehmer", "Sie ist nicht tarifgebunden", "Sie liegt in Hamburg und damit außerhalb des Kreises Segeberg", "Sie stellt nur befristet ein"], "c": 0, "e": "§ 99 BetrVG gilt in Unternehmen mit in der Regel mehr als 20 wahlberechtigten Arbeitnehmern. Die Service GmbH hat 18 Beschäftigte."}, {"q": "Was gehört zum kollektiven Arbeitsrecht?", "o": ["Tarifvertragsrecht und Betriebsverfassungsrecht", "Der einzelne Arbeitsvertrag von Jana Hoffmann", "Der Urlaubsanspruch einer einzelnen Person", "Die Probezeit im Vertrag eines Monteurs"], "c": 0, "e": "Das kollektive Arbeitsrecht regelt die Beziehungen der Gruppen, also Tarifverträge sowie Betriebsrat und Betriebsvereinbarungen. Das einzelne Arbeitsverhältnis gehört zum individuellen Arbeitsrecht (Beiderwieden & Stickdorn, 2026)."}, {"q": "Welche Reihenfolge der Rechtsquellen von oben nach unten ist richtig?", "o": ["Gesetz, Tarifvertrag, Betriebsvereinbarung, Arbeitsvertrag", "Tarifvertrag, Gesetz, Arbeitsvertrag, Betriebsvereinbarung", "Arbeitsvertrag, Betriebsvereinbarung, Tarifvertrag, Gesetz", "Gesetz, Arbeitsvertrag, Tarifvertrag, Betriebsvereinbarung"], "c": 0, "e": "Die höhere Ebene setzt die Untergrenze für die niedrigere. Ganz unten folgt noch das Weisungsrecht."}, {"q": "Was darf eine niedrigere Regelungsebene gegenüber einer höheren?", "o": ["Bessere Bedingungen für die Beschäftigten vorsehen", "Den gesetzlichen Mindesturlaub kürzen", "Den Mindestlohn unterschreiten, wenn die Person freiwillig unterschreibt", "Die höhere Ebene vollständig aufheben"], "c": 0, "e": "Nach unten darf nur zugunsten der Beschäftigten abgewichen werden. Gesetzliche Mindeststandards sind zwingend."}, {"q": "Wer schließt eine Betriebsvereinbarung ab?", "o": ["Arbeitgeber und Betriebsrat", "Gewerkschaft und Arbeitgeberverband", "Arbeitgeber und einzelne Beschäftigte", "Betriebsrat und Gewerkschaft"], "c": 0, "e": "Die Betriebsvereinbarung ist ein Vertrag zwischen Arbeitgeber und Betriebsrat. Tarifverträge schließen Gewerkschaft und Arbeitgeberseite."}, {"q": "Wie hoch ist der gesetzliche Mindestlohn im Jahr 2026?", "o": ["13,90 € brutto je Stunde", "12,82 € brutto je Stunde", "14,60 € brutto je Stunde", "12,41 € brutto je Stunde"], "c": 0, "e": "Seit 01.01.2026 gilt 13,90 € (MiLoV5). 12,82 € galt 2025, 14,60 € gilt ab 2027."}, {"q": "Wie wird die Höhe des Mindestlohns festgelegt?", "o": ["Per Verordnung der Bundesregierung auf Vorschlag der Mindestlohnkommission", "Durch einen jährlichen Beschluss jeder einzelnen IHK für ihren Bezirk", "Durch Vereinbarung mit dem Betriebsrat jedes Betriebs", "Durch Abstimmung der Arbeitnehmer bei der Krankenkasse"], "c": 0, "e": "Die Mindestlohnkommission aus Gewerkschaften und Arbeitgebern schlägt vor, die Bundesregierung setzt per Rechtsverordnung um (§ 1 MiLoG)."}, {"q": "Mit wie vielen Stunden im Monat rechnet man bei einer 40-Stunden-Woche im Kurs?", "o": ["174 Stunden", "152,25 Stunden", "160 Stunden", "168 Stunden"], "c": 0, "e": "40 × 4,35 = 174 Stunden. 152,25 Stunden gelten für die 35-Stunden-Woche bei Nordstern Fahrradwerke."}, {"q": "Wie hoch ist der Mindestmonatslohn 2026 bei 40 Wochenstunden?", "o": ["2.418,60 €", "2.116,28 €", "2.540,40 €", "2.224,00 €"], "c": 0, "e": "13,90 € × 40 × 4,35 = 13,90 × 174 = 2.418,60 €. 2.540,40 € wäre der Wert für 2027."}, {"q": "Woraus ergibt sich heute die Sozialversicherungsnummer einer neuen Beschäftigten?", "o": ["Aus dem Versicherungsnummernnachweis der Rentenversicherung", "Aus der Lohnsteuerbescheinigung des Finanzamts", "Aus der Mitgliedskarte der Gewerkschaft", "Aus dem Arbeitszeugnis des früheren Arbeitgebers"], "c": 0, "e": "Seit 2023 stellt die Rentenversicherung keinen Sozialversicherungsausweis mehr aus. Die Nummer steht im Versicherungsnummernnachweis."}, {"q": "Wie viele Werktage Urlaub garantiert das Bundesurlaubsgesetz mindestens?", "o": ["24 Werktage", "20 Werktage", "25 Werktage", "30 Werktage"], "c": 0, "e": "§ 3 BUrlG nennt 24 Werktage. Das entspricht 20 Arbeitstagen bei einer Fünf-Tage-Woche."}, {"q": "Welche Tage zählen nach dem Bundesurlaubsgesetz als Werktage?", "o": ["Alle Kalendertage außer Sonn- und gesetzlichen Feiertagen", "Nur Montag bis Freitag", "Alle Tage, an denen der Betrieb geöffnet hat, auch Sonntage", "Alle Kalendertage einschließlich Sonntag"], "c": 0, "e": "Nach § 3 Abs. 2 BUrlG zählt auch der Samstag als Werktag."}, {"q": "Wie viele Arbeitstage Mindesturlaub hat eine Vollzeitkraft mit Fünf-Tage-Woche?", "o": ["20 Arbeitstage", "24 Arbeitstage", "25 Arbeitstage", "18 Arbeitstage"], "c": 0, "e": "24 Werktage ÷ 6 × 5 = 20 Arbeitstage."}, {"q": "Ein Mechaniker beginnt am 01.09. bei der Service GmbH (Fünf-Tage-Woche, 20 Tage Mindesturlaub). Wie viel Teilurlaub hat er im Eintrittsjahr mindestens?", "o": ["7 Arbeitstage", "6 Arbeitstage", "8 Arbeitstage", "20 Arbeitstage"], "c": 0, "e": "4 × 20 ÷ 12 = 6,67 Tage. Bruchteile ab einem halben Tag werden aufgerundet, also 7 Tage."}, {"q": "Bis wann darf Urlaub aus dringenden Gründen ins Folgejahr übertragen werden?", "o": ["Bis zum 31. März des Folgejahres", "Bis zum 30. Juni des Folgejahres", "Bis zum 31. Dezember des Folgejahres", "Bis zum 31. Januar des Folgejahres"], "c": 0, "e": "Nach § 7 Abs. 3 BUrlG muss übertragener Urlaub in den ersten drei Monaten des Folgejahres genommen werden."}, {"q": "Was passiert mit Resturlaub, wenn das Arbeitsverhältnis endet und der Urlaub nicht mehr genommen werden kann?", "o": ["Er wird abgegolten, also ausgezahlt", "Er verfällt immer ersatzlos", "Er wird auf den nächsten Arbeitgeber übertragen", "Er wird mit Überstunden verrechnet"], "c": 0, "e": "§ 7 Abs. 4 BUrlG sieht bei Beendigung die Abgeltung vor."}, {"q": "Wie lange zahlt der Arbeitgeber bei unverschuldeter Krankheit das Entgelt weiter?", "o": ["Bis zu sechs Wochen", "Bis zu vier Wochen", "Bis zu zwölf Wochen", "Unbegrenzt bis zur Genesung"], "c": 0, "e": "§ 3 EFZG gewährt bis zu sechs Wochen Entgeltfortzahlung. Danach zahlt die Krankenkasse Krankengeld."}, {"q": "Ab wann besteht der Anspruch auf Entgeltfortzahlung im Krankheitsfall?", "o": ["Nach vier Wochen ununterbrochenem Arbeitsverhältnis", "Ab dem ersten Arbeitstag ohne jede Wartezeit", "Erst nach dem Ende einer vereinbarten Probezeit", "Erst nach sechs Monaten"], "c": 0, "e": "§ 3 Abs. 3 EFZG verlangt eine Wartezeit von vier Wochen."}, {"q": "Wie erhält der Arbeitgeber bei gesetzlich Versicherten die Arbeitsunfähigkeitsdaten?", "o": ["Er ruft die eAU bei der Krankenkasse ab", "Er bekommt sie per Post von der Arztpraxis", "Er fragt sie beim Finanzamt ab", "Er erhält sie von der Berufsgenossenschaft"], "c": 0, "e": "Seit Einführung der elektronischen Arbeitsunfähigkeitsbescheinigung ruft der Arbeitgeber die Daten bei der Krankenkasse ab."}, {"q": "Wie viele Stunden darf ein Erwachsener nach dem Arbeitszeitgesetz werktäglich höchstens arbeiten?", "o": ["Acht Stunden, mit Ausgleich bis zehn Stunden", "Zehn Stunden an jedem Werktag ohne jeden Ausgleich", "Zwölf Stunden bei Bedarf", "Sieben Stunden, mit Ausgleich bis neun"], "c": 0, "e": "§ 3 ArbZG erlaubt acht Stunden, verlängerbar auf zehn, wenn im Durchschnitt von sechs Monaten oder 24 Wochen acht Stunden eingehalten werden."}, {"q": "Wie lang muss die ununterbrochene Ruhezeit zwischen zwei Arbeitstagen für Erwachsene mindestens sein?", "o": ["Elf Stunden", "Acht Stunden", "Zwölf Stunden", "Zehn Stunden"], "c": 0, "e": "§ 5 ArbZG verlangt elf Stunden. Zwölf Stunden gelten für Jugendliche nach dem JArbSchG."}, {"q": "Was unterscheidet Urlaubsentgelt von Urlaubsgeld?", "o": ["Urlaubsentgelt ist das während des Urlaubs weitergezahlte Entgelt", "Urlaubsgeld ist in jedem Arbeitsverhältnis gesetzlich vorgeschrieben", "Urlaubsentgelt gibt es nur in tarifgebundenen Betrieben", "Die Begriffe bezeichnen dieselbe Zahlung"], "c": 0, "e": "Urlaubsentgelt ist das normale Entgelt im Urlaub nach dem Durchschnitt der letzten 13 Wochen (§ 11 BUrlG). Urlaubsgeld ist eine Extrazahlung nur aus Tarif oder Vertrag."}, {"q": "Gilt das AGG auch nach der Einstellung im laufenden Arbeitsverhältnis?", "o": ["Ja, etwa bei Entgelt, Beförderung und Kündigung", "Nein, nur bei Stellenanzeigen", "Nur in Betrieben mit Tarifvertrag", "Nur in Betrieben mit mehr als 20 Beschäftigten und Betriebsrat"], "c": 0, "e": "Das Benachteiligungsverbot nach § 7 AGG gilt im ganzen Arbeitsverhältnis und unabhängig von Betriebsgröße und Tarif."}, {"q": "Wann beginnt die Schutzfrist vor der Entbindung nach dem Mutterschutzgesetz?", "o": ["Sechs Wochen vor der Entbindung", "Acht Wochen vor der Entbindung", "Vier Wochen vor der Entbindung", "Mit Bekanntgabe der Schwangerschaft"], "c": 0, "e": "§ 3 MuSchG sieht sechs Wochen vor und acht Wochen nach der Entbindung vor."}, {"q": "Wie lange besteht das Kündigungsverbot nach § 17 MuSchG nach der Entbindung mindestens?", "o": ["Vier Monate", "Sechs Wochen", "Zwei Jahre", "Ein Jahr"], "c": 0, "e": "Das Kündigungsverbot gilt bis zum Ende der Schutzfrist, mindestens aber bis vier Monate nach der Entbindung."}, {"q": "Was ist seit dem 01.06.2025 im Mutterschutz neu?", "o": ["Gestaffelte Schutzfristen nach einer Fehlgeburt ab der 13. Woche", "Die Schutzfrist vor der Geburt entfällt", "Der Kündigungsschutz gilt nur noch zwei Monate", "Väter erhalten seitdem dieselbe Schutzfrist wie Mütter"], "c": 0, "e": "Das Mutterschutzanpassungsgesetz führte Schutzfristen nach Fehlgeburten ab der 13. Schwangerschaftswoche ein."}, {"q": "Welche Pflicht ist eine Hauptpflicht der beschäftigten Person?", "o": ["Die Arbeitspflicht", "Die Fürsorgepflicht", "Die Pflicht zur Ausstellung eines Zeugnisses", "Die Entgeltzahlungspflicht"], "c": 0, "e": "Nach § 611a BGB ist die Arbeitspflicht die Hauptpflicht der Beschäftigten. Fürsorge, Zeugnis und Entgelt sind Pflichten des Arbeitgebers."}, {"q": "Welche Pflicht des Arbeitgebers regelt § 618 BGB?", "o": ["Schutz von Leben und Gesundheit am Arbeitsplatz", "Zahlung des Mindestlohns", "Ausstellung des Arbeitszeugnisses", "Anmeldung der Beschäftigten bei der Krankenkasse"], "c": 0, "e": "§ 618 BGB ist eine Ausprägung der Fürsorgepflicht. Das Zeugnis regelt § 109 GewO."}, {"q": "Nach welchem Maßstab muss der Arbeitgeber sein Weisungsrecht ausüben?", "o": ["Nach billigem Ermessen", "Nach freiem Belieben", "Nach Mehrheitsbeschluss der Belegschaft", "Nach Vorgabe der Krankenkasse"], "c": 0, "e": "Billiges Ermessen heißt, die Interessen beider Seiten fair abzuwägen (§ 106 GewO)."}, {"q": "Der Montageleiter setzt einen Monteur von der Früh- in die Spätschicht. Was gilt?", "o": ["Das ist im Rahmen des Vertrags vom Weisungsrecht gedeckt", "Dafür ist immer ein neuer Arbeitsvertrag nötig", "Das verstößt immer gegen das Arbeitszeitgesetz", "Das darf nur die Geschäftsführerin persönlich und schriftlich anordnen"], "c": 0, "e": "Die Lage der Arbeitszeit kann per Weisung bestimmt werden, solange Vertrag, Tarif und Gesetz eingehalten werden."}, {"q": "Darf Nordstern Jana Hoffmann per Weisung dauerhaft in die Montage versetzen?", "o": ["Nein, ihr Vertrag sieht eine kaufmännische Tätigkeit vor", "Ja, das Weisungsrecht erlaubt jede Tätigkeit", "Ja, wenn die Montage dringend mehr Personal braucht als geplant", "Ja, wenn sie dafür mehr Geld bekommt"], "c": 0, "e": "Das Weisungsrecht endet an den Grenzen des Arbeitsvertrags. Eine ganz andere Tätigkeit bräuchte eine Vertragsänderung."}, {"q": "Was versteht man unter Personalstammdaten?", "o": ["Daten, die sich selten ändern und bei jeder Abrechnung gebraucht werden", "Daten, die sich jeden Monat ändern, etwa Überstunden", "Nur die Bewerbungsunterlagen abgelehnter Personen", "Die monatlichen Umsatzzahlen und Kosten der Personalabteilung"], "c": 0, "e": "Stammdaten wie Name, Steuer-ID oder Entgeltgruppe bleiben lange gleich. Monatliche Werte wie Überstunden sind Bewegungsdaten."}, {"q": "Wozu dient die Urlaubsbescheinigung des vorherigen Arbeitgebers?", "o": ["Sie verhindert einen doppelten Urlaubsanspruch im selben Jahr", "Sie ersetzt das Arbeitszeugnis", "Sie ist für die Bildung der Lohnsteuerklasse beim Finanzamt nötig", "Sie verlängert die Probezeit"], "c": 0, "e": "Bereits gewährter Urlaub wird angerechnet, damit im selben Kalenderjahr kein doppelter Anspruch entsteht."}, {"q": "Welches Recht haben Beschäftigte nach § 83 BetrVG?", "o": ["Einsicht in die eigene Personalakte", "Einsicht in die Akten aller Kollegen", "Löschung aller Abrechnungsdaten nach einem Jahr", "Mitbestimmung bei jeder Einstellung"], "c": 0, "e": "§ 83 BetrVG gibt das Recht auf Einsicht in die eigene Personalakte, auf Wunsch mit einem Betriebsratsmitglied."}, {"q": "An wen geht die DEÜV-Anmeldung einer neuen Beschäftigten?", "o": ["An die Krankenkasse als Einzugsstelle", "An das Finanzamt am Wohnort der Beschäftigten", "An die IHK zu Lübeck", "An den Betriebsrat"], "c": 0, "e": "Nach § 28a Abs. 1 SGB IV meldet der Arbeitgeber an die Krankenkasse, die die Daten an die anderen Zweige weiterleitet."}, {"q": "Bis wann muss die DEÜV-Anmeldung spätestens erfolgen?", "o": ["Mit der ersten folgenden Entgeltabrechnung, spätestens sechs Wochen nach Beginn", "Spätestens am Tag vor dem Arbeitsbeginn per Post", "Spätestens zum Ende der Probezeit", "Einmal jährlich mit der Jahresmeldung"], "c": 0, "e": "§ 6 DEÜV bestimmt die Frist mit der ersten folgenden Entgeltabrechnung, spätestens innerhalb von sechs Wochen."}, {"q": "Jana Hoffmann beginnt am 01.02.2027. Was ist der späteste Termin für die DEÜV-Anmeldung?", "o": ["15.03.2027", "01.03.2027", "08.02.2027", "31.07.2027"], "c": 0, "e": "01.02.2027 plus sechs Wochen, also 42 Tage, ergibt den 15.03.2027."}, {"q": "Warum braucht Nordstern Fahrradwerke für neue Beschäftigte keine Sofortmeldung?", "o": ["Die Fahrradherstellung gehört nicht zu den Branchen in § 28a Abs. 4 SGB IV", "Nordstern hat mehr als 200 Beschäftigte und einen eigenen Betriebsrat", "Nordstern ist tarifgebunden", "Sofortmeldungen wurden 2025 abgeschafft"], "c": 0, "e": "Die Sofortmeldung gilt nur für bestimmte Branchen wie Bau, Gastronomie oder Logistik. Maßgeblich ist die Branche, nicht Größe oder Tarif."}, {"q": "Wie erhält Nordstern die Steuerklasse von Jana Hoffmann?", "o": ["Durch Abruf der ELStAM beim Bundeszentralamt für Steuern", "Durch eine Lohnsteuerkarte aus Papier von der Gemeinde", "Durch eine Anfrage bei der Krankenkasse", "Durch eine Schätzung der Personalabteilung"], "c": 0, "e": "Nach § 39e EStG ruft der Arbeitgeber die elektronischen Lohnsteuerabzugsmerkmale mit Steuer-ID und Geburtsdatum ab."}, {"q": "Welche Folge hatte das Urteil des EuGH vom 30.03.2023 für § 26 BDSG?", "o": ["§ 26 Abs. 1 Satz 1 BDSG gilt als wahrscheinlich nicht mehr anwendbar", "§ 26 BDSG wurde sofort aus dem Gesetz gestrichen", "Arbeitgeber dürfen seitdem gar keine Beschäftigtendaten mehr speichern", "Der Betriebsrat muss seitdem jede einzelne Datenspeicherung genehmigen"], "c": 0, "e": "Der Paragraf steht noch im Gesetz. Nach dem Urteil zu einer gleich lautenden hessischen Regel stützt man sich aber auf Art. 6 Abs. 1 DSGVO."}, {"q": "Wie heißt das Merkmal, nach dem der Arbeitgeber über Inhalt, Ort und Zeit der Arbeit bestimmen darf?", "o": ["Weisungsgebundenheit", "Tarifautonomie", "Günstigkeitsprinzip", "Formfreiheit"], "c": 0, "e": "Weisungsgebunden heißt, dass der Arbeitgeber Inhalt, Ort und Zeit der Arbeit festlegen darf. Das ist nach § 611a BGB das wichtigste Merkmal eines Arbeitsverhältnisses."}, {"q": "Was bedeutet es, dass der Arbeitsvertrag ein gegenseitiger Vertrag ist?", "o": ["Jeder Pflicht der einen Seite steht ein Recht der anderen Seite gegenüber", "Jede Seite darf den Vertrag jederzeit ohne Frist beenden", "Der Vertrag muss von beiden Seiten notariell beglaubigt werden", "Arbeitgeber und Beschäftigte zahlen gleich hohe Gewerkschaftsbeiträge"], "c": 0, "e": "Gegenseitig heißt, dass sich Pflichten und Rechte gegenüberstehen. Die Arbeitspflicht der beschäftigten Person entspricht dem Anspruch des Arbeitgebers auf Arbeit, die Entgeltpflicht dem Anspruch auf Entgelt."}, {"q": "Was folgt daraus, dass die Arbeit nach dem Arbeitsvertrag persönlich zu leisten ist?", "o": ["Die beschäftigte Person darf keine Ersatzperson zur Arbeit schicken", "Die beschäftigte Person muss jeden Tag im Büro der Leitung erscheinen", "Die beschäftigte Person darf nur allein und nie im Team arbeiten", "Die beschäftigte Person haftet für jeden Fehler mit ihrem Vermögen"], "c": 0, "e": "Persönlich leisten heißt, dass niemand anderes die Arbeit an ihrer Stelle erledigen darf. Ist eine Beschäftigte verhindert, schickt sie keine Vertretung, sondern meldet sich ab."}, {"q": "Was besagt der Grundsatz der Formfreiheit beim Arbeitsvertrag?", "o": ["Ein unbefristeter Arbeitsvertrag kann auch mündlich wirksam geschlossen werden", "Ein Arbeitsvertrag ist nur mit eigenhändiger Unterschrift beider Seiten wirksam", "Der Arbeitgeber darf den Inhalt des Vertrags später frei verändern", "Arbeitsverträge dürfen in jeder Sprache und ohne Datum abgefasst werden"], "c": 0, "e": "Im Arbeitsrecht gilt die Formfreiheit. Ein unbefristeter Vertrag entsteht auch mündlich. Ausnahmen gibt es etwa für die Befristung und die Kündigung."}, {"q": "Worin liegt der wesentliche Unterschied zwischen Textform und Schriftform?", "o": ["Bei der Textform ist keine eigenhändige Unterschrift nötig", "Bei der Textform muss ein Notar den Text beglaubigen", "Bei der Schriftform genügt eine lesbare Nachricht im Messenger", "Bei der Schriftform reicht eine eingescannte Unterschrift im PDF"], "c": 0, "e": "Schriftform bedeutet Papier mit eigenhändiger Unterschrift. Textform bedeutet eine lesbare, speicherbare Erklärung, zum Beispiel ein PDF, ohne Unterschrift."}, {"q": "Welche Form braucht ein Aufhebungsvertrag, mit dem Nordstern und eine Beschäftigte das Arbeitsverhältnis einvernehmlich beenden?", "o": ["Schriftform", "Textform", "Keine besondere Form", "Notarielle Beurkundung"], "c": 0, "e": "Nach § 623 BGB brauchen Kündigung und Aufhebungsvertrag die Schriftform. Eine E-Mail oder ein PDF ohne Originalunterschrift reicht nicht."}, {"q": "In welcher Form muss der wesentliche Inhalt eines Ausbildungsvertrags festgehalten werden?", "o": ["In Textform", "Nur mündlich", "In notarieller Form", "Als Aushang am Schwarzen Brett"], "c": 0, "e": "Nach § 11 BBiG wird der wesentliche Inhalt des Ausbildungsvertrags in Textform niedergelegt. Ein speicherbares Dokument ohne eigenhändige Unterschrift genügt."}, {"q": "Welchen Zweck hat das Nachweisgesetz?", "o": ["Beschäftigte sollen ihre wesentlichen Arbeitsbedingungen schwarz auf weiß haben", "Arbeitgeber sollen ihre Beschäftigten bei der Krankenkasse anmelden", "Gewerkschaften sollen alle Arbeitsverträge vorab genehmigen", "Der Staat soll die Höhe der Gehälter in jedem Betrieb festlegen"], "c": 0, "e": "Weil Arbeitsverträge formfrei sind, schützt das Nachweisgesetz die Beschäftigten. Sie erhalten die wesentlichen Bedingungen schriftlich und können so zum Beispiel Fehler in der Abrechnung erkennen."}, {"q": "Bis wann muss Nordstern eine Änderung der wesentlichen Arbeitsbedingungen mitteilen?", "o": ["Spätestens an dem Tag, an dem die Änderung wirksam wird", "Spätestens einen Monat nach dem Wirksamwerden der Änderung", "Erst mit dem nächsten Arbeitszeugnis", "Nur auf ausdrückliche Nachfrage der beschäftigten Person"], "c": 0, "e": "Nach § 3 NachwG muss eine Änderung spätestens an dem Tag mitgeteilt werden, an dem sie wirksam wird. Bei Nordstern wird sie als Nachtrag ausgehändigt und in die Personalakte gelegt."}, {"q": "Wie nennt man eine Befristung, die an einem festen Datum endet, etwa am 31.12.2027?", "o": ["Kalendermäßige Befristung", "Zweckbefristung", "Kettenbefristung", "Probebefristung"], "c": 0, "e": "Eine kalendermäßige Befristung endet an einem bestimmten Datum. Eine Zweckbefristung endet, wenn ein vereinbarter Zweck erreicht ist, etwa die Rückkehr einer Kollegin."}, {"q": "Ist die Liste der Sachgründe in § 14 Abs. 1 TzBfG abschließend?", "o": ["Nein, auch andere ähnlich gewichtige Gründe sind möglich", "Ja, nur die genannten Gründe sind erlaubt", "Nein, der Arbeitgeber darf jeden beliebigen Grund angeben", "Ja, und der Betriebsrat muss jeden Grund vorher genehmigen"], "c": 0, "e": "Das Gesetz nennt acht Beispiele. Andere Gründe sind möglich, wenn sie ähnlich gewichtig sind. Ein beliebiger Grund reicht aber nicht."}, {"q": "Wie lange darf eine Befristung mit Sachgrund dauern?", "o": ["Auch länger als zwei Jahre, solange der Grund besteht", "Höchstens zwei Jahre, wie jede andere Befristung", "Höchstens sechs Monate, wie die Probezeit", "Genau so lange, wie der Betriebsrat festlegt"], "c": 0, "e": "Die Zwei-Jahres-Grenze gilt nur für die sachgrundlose Befristung. Mit Sachgrund, etwa einer Vertretung in der Elternzeit, darf länger befristet werden, solange der Grund trägt."}, {"q": "Was ist ein Arbeitgeberverband?", "o": ["Ein Zusammenschluss von Arbeitgebern, der mit der Gewerkschaft Tarifverträge aushandelt", "Eine Behörde, die die Arbeitsverträge aller Betriebe einer Branche prüft", "Die Vertretung der Beschäftigten innerhalb eines einzelnen Betriebs", "Eine Versicherung, die Arbeitgeber gegen Streikschäden absichert"], "c": 0, "e": "Im Arbeitgeberverband schließen sich Arbeitgeber einer Branche zusammen. Nordstern ist Mitglied im Arbeitgeberverband der Metall- und Elektroindustrie, der mit der IG Metall verhandelt."}, {"q": "Welches Mittel des Arbeitskampfs steht der Arbeitgeberseite zur Verfügung?", "o": ["Die Aussperrung", "Der Warnstreik", "Die Allgemeinverbindlicherklärung", "Die Friedenspflicht"], "c": 0, "e": "Die Gewerkschaft kann zum Warnstreik und Streik aufrufen, die Arbeitgeberseite kann aussperren. Die Allgemeinverbindlicherklärung ist kein Kampfmittel, sondern ein Akt des Ministeriums."}, {"q": "Womit beginnt eine Tarifrunde, wenn ein Tarifvertrag ausläuft?", "o": ["Die Gewerkschaft stellt eine Forderung", "Die Arbeitgeber sperren aus", "Das Ministerium erklärt den Tarif für allgemeinverbindlich", "Die Beschäftigten unterschreiben neue Arbeitsverträge"], "c": 0, "e": "Am Anfang steht die Forderung der Gewerkschaft, danach wird verhandelt. Erst wenn keine Einigung gelingt, kommt es zu Warnstreiks, Streiks oder Aussperrung."}, {"q": "Was bedeutet die Schutzfunktion eines Tarifvertrags?", "o": ["Er schützt die einzelne beschäftigte Person, die beim Aushandeln meist schwächer ist", "Er schützt den Arbeitgeber vor zu vielen Bewerbungen auf eine Stelle", "Er schützt die Maschinen im Betrieb vor Schäden durch Streik", "Er schützt die Daten der Beschäftigten vor dem Zugriff des Betriebsrats"], "c": 0, "e": "Die einzelne beschäftigte Person ist beim Verhandeln meist schwächer als der Arbeitgeber. Der Tarifvertrag gleicht das aus, indem er Mindestbedingungen festlegt."}, {"q": "Welche Funktion des Tarifvertrags ist gemeint, wenn Betriebe einer Branche mit vergleichbaren Personalkosten im Wettbewerb stehen?", "o": ["Ordnungsfunktion", "Schutzfunktion", "Friedensfunktion", "Kontrollfunktion"], "c": 0, "e": "Die Ordnungsfunktion sorgt für einheitliche Arbeitsbedingungen in einer Branche. Die Friedensfunktion sorgt für Ruhe während der Laufzeit, die Schutzfunktion schützt die Beschäftigten."}, {"q": "Welche Art von Tarifvertrag gilt bei Nordstern, wenn man nach den Vertragsparteien unterscheidet?", "o": ["Ein Flächentarifvertrag des Verbands für Branche und Region", "Ein Haustarifvertrag nur für die Nordstern Fahrradwerke GmbH", "Eine Betriebsvereinbarung mit dem Betriebsrat", "Ein Einzelvertrag mit jeder beschäftigten Person"], "c": 0, "e": "Der Arbeitgeberverband der Metall- und Elektroindustrie verhandelt für die ganze Branche im Tarifgebiet Küste. Das ist ein Flächentarifvertrag."}, {"q": "Was bedeutet es, dass Tarifnormen zwingend wirken?", "o": ["Auf tarifliche Rechte kann man nicht zum eigenen Nachteil verzichten", "Der Tarifvertrag muss jedes Jahr neu unterschrieben werden", "Jede beschäftigte Person muss der Gewerkschaft beitreten", "Der Arbeitgeber muss jede Forderung der Gewerkschaft erfüllen"], "c": 0, "e": "Zwingend heißt, dass ungünstigere Vereinbarungen nicht wirksam sind, auch wenn sie unterschrieben wurden. Unmittelbar heißt, dass die Regeln gelten, ohne im Arbeitsvertrag zu stehen (§ 4 Abs. 1 TVG)."}, {"q": "Was ist eine Öffnungsklausel?", "o": ["Eine Erlaubnis im Tarifvertrag, von seinen Regeln abzuweichen", "Eine Klausel, die dem Betriebsrat Zugang zu allen Büros gewährt", "Eine Regel über die Öffnungszeiten des Werksverkaufs", "Eine Klausel, nach der der Tarifvertrag jederzeit gekündigt werden kann"], "c": 0, "e": "Nach § 4 Abs. 3 TVG ist eine Abweichung vom Tarif erlaubt, wenn der Tarif sie selbst gestattet oder sie für die Beschäftigten günstiger ist. Die Erlaubnis im Tarif heißt Öffnungsklausel."}, {"q": "Wer erklärt einen Tarifvertrag für allgemeinverbindlich?", "o": ["Das Bundesministerium für Arbeit und Soziales", "Der Deutsche Bundestag", "Die Industrie- und Handelskammer", "Das Arbeitsgericht am Sitz des Verbands"], "c": 0, "e": "Nach § 5 TVG entscheidet das BMAS. Dafür braucht es einen gemeinsamen Antrag der Tarifparteien, das Einvernehmen mit dem Tarifausschuss und ein öffentliches Interesse."}, {"q": "Woraus ergibt sich die Friedenspflicht?", "o": ["Aus dem Tarifvertrag selbst", "Aus einer ausdrücklichen Regel im Tarifvertragsgesetz", "Aus dem Arbeitsvertrag jeder einzelnen Person", "Aus einer Anordnung der Bundesregierung"], "c": 0, "e": "Die Friedenspflicht steht nicht ausdrücklich im Gesetz. Sie folgt aus dem Tarifvertrag und gilt für die darin geregelten Fragen während der Laufzeit."}, {"q": "Was versteht man unter Eingruppierung?", "o": ["Die Zuordnung einer Tätigkeit zu einer Entgeltgruppe", "Die Aufnahme einer Person in die Gewerkschaft", "Die Einteilung der Beschäftigten in Früh- und Spätschicht", "Die Zuordnung eines Betriebs zu einem Tarifgebiet"], "c": 0, "e": "Bei der Eingruppierung wird die Tätigkeit einer Entgeltgruppe zugeordnet, etwa Sachbearbeitung kaufmännisch in EG 9. Die Merkmale dafür beschreibt der Rahmentarifvertrag."}, {"q": "Welcher Begriff wird gleichbedeutend mit Einzelvertrag verwendet?", "o": ["Individualvertrag", "Kollektivvertrag", "Haustarifvertrag", "Betriebsvereinbarung"], "c": 0, "e": "Ein Einzelvertrag oder Individualvertrag wird nur zwischen Arbeitgeber und einzelner beschäftigter Person ausgehandelt. Tarifvertrag und Betriebsvereinbarung sind kollektive Regelungen."}, {"q": "Welche Regel steht bei Nordstern typischerweise in einer Betriebsvereinbarung?", "o": ["Die Gleitzeitregelung für die Verwaltung", "Die Höhe des gesetzlichen Mindestlohns", "Die Höhe des Entgelts in EG 9", "Die Kündigungsfrist in der Probezeit"], "c": 0, "e": "Eine Betriebsvereinbarung schließen Arbeitgeber und Betriebsrat, zum Beispiel zur Gleitzeit. Mindestlohn und Probezeitfrist stehen im Gesetz, die Entgeltbeträge im Tarifvertrag."}, {"q": "Was geschieht mit einer Vertragsklausel, die weniger als den gesetzlichen Mindesturlaub vorsieht?", "o": ["Sie ist insoweit unwirksam, und es gilt der gesetzliche Urlaub", "Sie gilt, weil die Person den Vertrag unterschrieben hat", "Der ganze Arbeitsvertrag wird dadurch unwirksam", "Sie gilt nur im ersten Beschäftigungsjahr"], "c": 0, "e": "Gesetzliche Mindeststandards sind zwingend. Eine schlechtere Regel im Vertrag ist insoweit unwirksam, der Rest des Vertrags bleibt bestehen."}, {"q": "Worauf bezieht sich der gesetzliche Mindestlohn von 13,90 € im Jahr 2026?", "o": ["Auf jede Zeitstunde, brutto", "Auf jede Zeitstunde, netto", "Auf den Monat bei Vollzeit", "Auf jedes gefertigte Stück im Akkord"], "c": 0, "e": "Der Mindestlohn ist ein Bruttobetrag je Zeitstunde (§ 1 MiLoG). Für einen Monatsvergleich rechnet man mit den Wochenstunden und 4,35 Wochen um."}, {"q": "Wie werden Bruchteile von Urlaubstagen beim Teilurlaub behandelt?", "o": ["Bruchteile ab einem halben Tag werden auf einen vollen Tag aufgerundet", "Bruchteile werden immer auf den vollen Tag abgerundet", "Bruchteile werden immer als Geld ausgezahlt", "Bruchteile verfallen am Jahresende ersatzlos"], "c": 0, "e": "Nach § 5 BUrlG werden Bruchteile von mindestens einem halben Tag aufgerundet. Aus 6,67 Tagen werden also 7 Tage."}, {"q": "Warum rechnet man die 24 Werktage des Bundesurlaubsgesetzes bei einer Fünf-Tage-Woche in 20 Arbeitstage um?", "o": ["Weil das Gesetz von sechs Werktagen pro Woche ausgeht", "Weil Samstage nie als Urlaubstage zählen dürfen", "Weil Teilzeitkräfte weniger Erholung brauchen", "Weil der Tarifvertrag vier Tage abzieht"], "c": 0, "e": "Werktage sind alle Tage außer Sonn- und Feiertagen, also sechs pro Woche. Bei fünf Arbeitstagen rechnet man 24 ÷ 6 × 5 = 20 Arbeitstage. Die Erholungszeit bleibt gleich, vier Wochen."}, {"q": "Wer zahlt, wenn eine neue Beschäftigte in den ersten vier Wochen ihres Arbeitsverhältnisses krank wird?", "o": ["Die Krankenkasse zahlt Krankengeld", "Der Arbeitgeber zahlt das volle Entgelt", "Die Berufsgenossenschaft zahlt Verletztengeld", "Niemand, sie erhält kein Geld"], "c": 0, "e": "Der Anspruch auf Entgeltfortzahlung entsteht erst nach vier Wochen ununterbrochenem Arbeitsverhältnis (§ 3 EFZG). Vorher springt die Krankenkasse mit Krankengeld ein."}, {"q": "In welchem Zeitraum muss ein Durchschnitt von acht Stunden je Werktag eingehalten werden, wenn an einzelnen Tagen bis zu zehn Stunden gearbeitet wird?", "o": ["In sechs Kalendermonaten oder 24 Wochen", "In einer Kalenderwoche", "In zwölf Kalendermonaten oder 52 Wochen", "In einem Kalendermonat"], "c": 0, "e": "Nach § 3 ArbZG darf auf zehn Stunden verlängert werden, wenn im Durchschnitt von sechs Kalendermonaten oder 24 Wochen acht Stunden je Werktag nicht überschritten werden."}, {"q": "Unter welcher Bedingung darf eine Schwangere in den sechs Wochen vor der Entbindung beschäftigt werden?", "o": ["Wenn sie sich ausdrücklich dazu bereit erklärt", "Wenn der Betriebsrat zustimmt", "Wenn sie nur halbtags arbeitet", "Unter keinen Umständen"], "c": 0, "e": "In der Schutzfrist vor der Entbindung darf die Frau nur arbeiten, wenn sie das ausdrücklich will. Nach der Entbindung gilt dagegen ein Beschäftigungsverbot (§ 3 MuSchG)."}, {"q": "Wann greift das Kündigungsverbot nach § 17 MuSchG, wenn der Arbeitgeber von der Schwangerschaft noch nichts wusste?", "o": ["Wenn die Frau sie innerhalb von zwei Wochen nach Zugang der Kündigung mitteilt", "Nur wenn sie die Schwangerschaft schon im Vorstellungsgespräch genannt hat", "Nur wenn der Betriebsrat vorher informiert wurde", "Nur in Betrieben mit mehr als zehn Beschäftigten"], "c": 0, "e": "Das Kündigungsverbot gilt, wenn der Arbeitgeber Bescheid weiß oder die Frau es ihm innerhalb von zwei Wochen nach Zugang der Kündigung mitteilt. Es gilt in jedem Betrieb."}, {"q": "Welche Pflicht ist die wichtigste Nebenpflicht des Arbeitgebers?", "o": ["Die Fürsorgepflicht", "Die Arbeitspflicht", "Die Treuepflicht", "Die Verschwiegenheitspflicht der Beschäftigten"], "c": 0, "e": "Hauptpflicht des Arbeitgebers ist die Entgeltzahlung, wichtigste Nebenpflicht die Fürsorge. Dazu gehört nach § 618 BGB der Schutz von Leben und Gesundheit."}, {"q": "Was bedeutet die Beschäftigungspflicht des Arbeitgebers?", "o": ["Er muss die Person tatsächlich arbeiten lassen und nicht nur bezahlen", "Er muss jedes Jahr eine bestimmte Zahl an Personen neu einstellen", "Er muss Beschäftigte nach der Probezeit immer unbefristet übernehmen", "Er muss Arbeitslose bevorzugt beschäftigen"], "c": 0, "e": "Zu den Pflichten des Arbeitgebers gehört die tatsächliche Beschäftigung. Die Person hat ein Interesse daran, ihre Fähigkeiten einzusetzen und nicht nur Geld zu erhalten."}, {"q": "Welche Angabe ist kein Stammdatum, weil sie sich typischerweise jeden Monat ändert?", "o": ["Die Zahl der geleisteten Überstunden", "Die Steuer-ID", "Das Eintrittsdatum", "Die Sozialversicherungsnummer"], "c": 0, "e": "Stammdaten ändern sich selten und werden bei jeder Abrechnung gebraucht. Überstunden fallen jeden Monat anders an und sind deshalb Bewegungsdaten der Abrechnung."}, {"q": "Wofür steht die Abkürzung ELStAM?", "o": ["Elektronische Lohnsteuerabzugsmerkmale", "Elektronische Leistungsstammdaten", "Einheitliche Lohnsteuer-Abrechnungsmeldung", "Elektronische Lohn- und Stundenaufstellung"], "c": 0, "e": "ELStAM sind die elektronischen Lohnsteuerabzugsmerkmale, etwa Steuerklasse, Kinderfreibeträge und Kirchensteuermerkmal. Der Arbeitgeber ruft sie ab (§ 39e EStG)."}, {"q": "Wer darf bei Nordstern auf eine Personalakte zugreifen?", "o": ["Nur Personen, die sie für ihre Aufgabe brauchen", "Alle Führungskräfte des Unternehmens", "Alle Beschäftigten derselben Abteilung", "Jede Person mit einem Werksausweis"], "c": 0, "e": "Die Personalakte ist vertraulich. Zugriff haben nur Personen, die sie für ihre Arbeit benötigen, etwa die Personalabteilung."}, {"q": "Wen dürfen Beschäftigte bei der Einsicht in ihre Personalakte hinzuziehen?", "o": ["Ein Mitglied des Betriebsrats", "Eine beliebige Kollegin aus der Montage", "Einen Vertreter der Krankenkasse", "Die Geschäftsführerin eines anderen Unternehmens"], "c": 0, "e": "Nach § 83 BetrVG dürfen Beschäftigte ihre Personalakte einsehen und dazu ein Betriebsratsmitglied hinzuziehen."}, {"q": "Warum heißt die Krankenkasse bei der Anmeldung zur Sozialversicherung Einzugsstelle?", "o": ["Sie nimmt Meldung und Beiträge entgegen und leitet sie an die anderen Zweige weiter", "Sie zieht die Lohnsteuer für das Finanzamt ein", "Sie entscheidet über den Einzug in eine Werkswohnung", "Sie zieht die Gewerkschaftsbeiträge der Beschäftigten ein"], "c": 0, "e": "Die Krankenkasse ist Einzugsstelle. Sie erhält die DEÜV-Meldung und die Beiträge und gibt die Daten an Renten-, Pflege- und Arbeitslosenversicherung weiter."}, {"q": "An wen geht eine Sofortmeldung?", "o": ["An die Datenstelle der Rentenversicherung", "An das Bundeszentralamt für Steuern", "An die Agentur für Arbeit am Wohnort", "An den Betriebsrat des Unternehmens"], "c": 0, "e": "Die Sofortmeldung geht spätestens bei Arbeitsaufnahme an die Datenstelle der Rentenversicherung. Sie ist nur in den Branchen nach § 28a Abs. 4 SGB IV vorgeschrieben."}, {"q": "Welchen Stand hat ein eigenes Beschäftigtendatengesetz im November 2026?", "o": ["Es ist geplant, aber nicht beschlossen", "Es gilt seit dem 01.01.2026", "Es wurde vom EuGH für unwirksam erklärt", "Es gilt nur in Hessen"], "c": 0, "e": "Ein eigenes Beschäftigtendatengesetz ist geplant, aber noch nicht beschlossen. In der Praxis stützen sich Arbeitgeber auf Art. 6 Abs. 1 DSGVO."}, {"q": "Welche Aufgabe hat eine Patin bei der Einarbeitung?", "o": ["Sie begleitet die neue Person als erfahrene Kollegin in den ersten Wochen", "Sie entscheidet über die Eingruppierung der neuen Person", "Sie unterschreibt den Arbeitsvertrag für den Arbeitgeber", "Sie meldet die neue Person bei der Krankenkasse an"], "c": 0, "e": "Die Patin ist eine erfahrene Kollegin, die Fragen beantwortet und bei ersten Aufgaben hilft. Eine gute Einarbeitung senkt das Risiko einer Kündigung in der Probezeit (Beiderwieden & Stickdorn, 2026)."}, {"q": "Herr Brandt bietet Jana Hoffmann am 14.01.2027 die Stelle an. Sie sagt am 15.01.2027 zu. Arbeitsbeginn ist der 01.02.2027. Wann ist der Arbeitsvertrag geschlossen?", "o": ["Am 15.01.2027 mit ihrer Annahme", "Am 14.01.2027 mit dem Angebot", "Am 01.02.2027 mit dem ersten Arbeitstag", "Erst mit der ersten Gehaltszahlung"], "c": 0, "e": "Der Vertrag entsteht durch Angebot und Annahme. Mit der Zusage am 15.01.2027 ist er geschlossen, auch wenn die Arbeit erst im Februar beginnt."}, {"q": "Jana Hoffmann wechselt ab dem 01.09.2027 auf eigenen Wunsch auf 30 Wochenstunden. Bis wann muss Nordstern ihr die Änderung schriftlich mitteilen?", "o": ["Spätestens am 01.09.2027", "Spätestens am 08.09.2027", "Spätestens am 01.10.2027", "Gar nicht, weil sie die Änderung selbst wollte"], "c": 0, "e": "Ändert sich eine wesentliche Bedingung, muss die Änderung spätestens an dem Tag mitgeteilt werden, an dem sie wirksam wird (§ 3 NachwG). Das gilt auch, wenn die Person sie selbst gewünscht hat."}, {"q": "Nordstern schickt einem neuen Lageristen den Nachweis der Arbeitsbedingungen als PDF per E-Mail. Warum ist das grundsätzlich erlaubt?", "o": ["Weil Fahrradherstellung keine ausgeschlossene Branche ist", "Weil Lagerarbeit nie unter das Nachweisgesetz fällt", "Weil der Lagerist sich noch in der Probezeit befindet", "Weil Nordstern an einen Tarifvertrag gebunden ist"], "c": 0, "e": "Die Textform ist seit 2025 erlaubt, außer in Branchen mit hohem Schwarzarbeitsrisiko wie Bau, Gaststätten oder Logistikgewerbe. Entscheidend ist die Branche des Arbeitgebers. Nordstern stellt Fahrräder her, also genügt das PDF mit Empfangsnachweis."}, {"q": "Herr Brandt will den Monteur Daniel Wrobel, der noch nie bei Nordstern war, ab dem 01.09.2027 sachgrundlos befristen. Bis zu welchem Datum ist das höchstens möglich?", "o": ["Bis 31.08.2029", "Bis 31.08.2028", "Bis 31.12.2029", "Bis 31.08.2030"], "c": 0, "e": "Die sachgrundlose Befristung darf insgesamt zwei Jahre dauern. Ab dem 01.09.2027 endet sie also spätestens am 31.08.2029 (§ 14 Abs. 2 TzBfG)."}, {"q": "Elif Kurt war 2025 bei der Nordstern Service GmbH angestellt. Nun will die Nordstern Fahrradwerke GmbH sie sachgrundlos befristet einstellen. Was gilt?", "o": ["Das ist möglich, weil die Service GmbH ein anderer Arbeitgeber ist", "Das ist ausgeschlossen, weil die Firmen zur selben Gruppe gehören", "Das ist nur mit Zustimmung der IG Metall möglich", "Das ist nur für höchstens sechs Monate möglich"], "c": 0, "e": "Das Verbot der Vorbeschäftigung bezieht sich auf denselben Arbeitgeber. Jede GmbH ist ein eigener Arbeitgeber. Ein früherer Vertrag bei der Tochter hindert die Mutter deshalb nicht."}, {"q": "Eine Sachbearbeiterin in der Verwaltung geht für drei Jahre in Elternzeit. Darf Nordstern ihre Vertretung für drei Jahre befristen?", "o": ["Ja, mit dem Sachgrund Vertretung", "Nein, Befristungen sind höchstens zwei Jahre erlaubt", "Ja, aber nur ohne Sachgrund", "Nein, eine Vertretung darf nur sechs Monate dauern"], "c": 0, "e": "Bei einer Befristung mit Sachgrund gibt es keine Zwei-Jahres-Grenze. Die Vertretung ist ein gesetzlicher Sachgrund nach § 14 Abs. 1 TzBfG."}, {"q": "Ein neuer Monteur erhält in der Probezeit eine schriftliche Kündigung, die ihm am Freitag, 07.05.2027, zugeht. Wann endet das Arbeitsverhältnis?", "o": ["Mit Ablauf des 21.05.2027", "Mit Ablauf des 14.05.2027", "Am 31.05.2027", "Am 15.06.2027"], "c": 0, "e": "In der Probezeit beträgt die Frist zwei Wochen zu jedem Tag (§ 622 Abs. 3 BGB). Die Frist beginnt am 08.05.2027 und endet mit Ablauf des 21.05.2027."}, {"q": "Ein Monteur beginnt am 01.03.2027 bei Nordstern. Im Vertrag steht keine Probezeit. Ab wann gilt für ihn der allgemeine Kündigungsschutz?", "o": ["Ab dem 01.09.2027", "Sofort ab dem 01.03.2027", "Ab dem 01.03.2028", "Erst nach Ende einer Probezeit, die hier fehlt"], "c": 0, "e": "Die Wartezeit nach § 1 KSchG gilt immer, auch ohne Probezeit. Nach mehr als sechs Monaten, also ab dem 01.09.2027, hat er allgemeinen Kündigungsschutz, weil Nordstern mehr als zehn Arbeitnehmer hat."}, {"q": "Eine Abteilungsleiterin in EG 13 hat im Vertrag 5.150 € stehen. Wie viel Euro würde Nordstern ihr im Jahr zu wenig zahlen, wenn der Vertragswert gelten würde?", "o": ["1.800 €", "150 €", "2.400 €", "1.500 €"], "c": 0, "e": "Der Tarifwert in EG 13 beträgt 5.300 €. Der Vertrag liegt 150 € darunter und ist insoweit unwirksam. Im Jahr sind das 150 × 12 = 1.800 €."}, {"q": "Eine Teamleitung in EG 11 fragt nach ihrem Entgelt pro Arbeitsstunde. Welcher Betrag ergibt sich mit dem Teiler von Nordstern?", "o": ["29,56 €", "25,94 €", "34,81 €", "25,86 €"], "c": 0, "e": "Der Stundenlohn ergibt sich aus 4.500 € ÷ 152,25 Stunden = 29,56 €. Der Wert 25,86 € entsteht, wenn man fälschlich durch 174 Stunden teilt."}, {"q": "Um wie viel Euro liegt der Stundenlohn eines angelernten Monteurs in EG 5 über dem eines Helfers in EG 3?", "o": ["2,30 €", "3,50 €", "1,85 €", "2,95 €"], "c": 0, "e": "EG 5 ergibt 3.250 ÷ 152,25 = 21,35 €, EG 3 ergibt 2.900 ÷ 152,25 = 19,05 €. Die Differenz beträgt 21,35 − 19,05 = 2,30 €."}, {"q": "Lisa Wagner ist in EG 9 eingruppiert, Jonas Petersen in EG 7. Wie groß ist der Unterschied der Monatsgrundentgelte über ein ganzes Jahr?", "o": ["4.200 €", "350 €", "3.500 €", "2.100 €"], "c": 0, "e": "EG 9 hat 3.950 €, EG 7 hat 3.600 €. Die Differenz beträgt 350 € im Monat, im Jahr also 350 × 12 = 4.200 €."}, {"q": "Herr Brandt informiert den Betriebsrat am Montag, 04.01.2027, über eine geplante Einstellung. Der Betriebsrat meldet sich nicht. Wann gilt die Zustimmung als erteilt?", "o": ["Nach Ablauf des 11.01.2027", "Sofort am 04.01.2027", "Nach Ablauf des 18.01.2027", "Nie, ohne Antwort darf nicht eingestellt werden"], "c": 0, "e": "Der Betriebsrat hat nach § 99 BetrVG eine Woche Zeit, schriftlich mit Gründen zu widersprechen. Schweigt er, gilt die Zustimmung nach Ablauf der Woche als erteilt."}, {"q": "Petra Holm teilt Herrn Brandt nach zehn Tagen mündlich mit, der Betriebsrat sei gegen eine Einstellung. Was gilt?", "o": ["Die Zustimmung gilt als erteilt", "Die Einstellung ist damit endgültig verboten", "Herr Brandt muss die Stelle neu ausschreiben", "Der Betriebsrat erhält eine weitere Woche Zeit"], "c": 0, "e": "Der Widerspruch muss innerhalb einer Woche schriftlich mit Gründen erfolgen (§ 99 BetrVG). Ein mündlicher Widerspruch nach zehn Tagen reicht nicht."}, {"q": "Eine Teilzeitkraft der Service GmbH arbeitet 20 Stunden pro Woche. Welches Monatsentgelt muss sie 2026 mindestens erhalten?", "o": ["1.209,30 €", "1.112,00 €", "1.270,20 €", "2.418,60 €"], "c": 0, "e": "20 Stunden × 4,35 Wochen = 87 Stunden im Monat. 87 × 13,90 € = 1.209,30 €. Der Wert 1.270,20 € gilt erst ab 2027 mit 14,60 €."}, {"q": "Eine Werkstattkraft der Service GmbH arbeitet 30 Stunden pro Woche. Welches Monatsentgelt ist ab dem 01.01.2027 mindestens zu zahlen?", "o": ["1.905,30 €", "1.813,95 €", "1.752,00 €", "2.540,40 €"], "c": 0, "e": "30 × 4,35 = 130,5 Stunden. 130,5 × 14,60 € = 1.905,30 €. Mit dem Mindestlohn 2026 von 13,90 € wären es 1.813,95 €."}, {"q": "Welche Ebene der Rangfolge fehlt bei der Nordstern Service GmbH?", "o": ["Der Tarifvertrag", "Das Gesetz", "Der Arbeitsvertrag", "Das Weisungsrecht"], "c": 0, "e": "Die Service GmbH ist nicht tarifgebunden. Deshalb steht der Arbeitsvertrag dort direkt unter dem Gesetz und gegebenenfalls einer Betriebsvereinbarung."}, {"q": "Eine Teilzeitkraft der Service GmbH arbeitet ganzjährig an drei Tagen pro Woche. Wie viele Arbeitstage Mindesturlaub hat sie?", "o": ["12 Arbeitstage", "20 Arbeitstage", "24 Arbeitstage", "10 Arbeitstage"], "c": 0, "e": "Man rechnet 24 Werktage ÷ 6 × 3 = 12 Arbeitstage. Sie hat damit wie Vollzeitkräfte vier Wochen Erholung."}, {"q": "Ein neuer Mechaniker fängt am 01.10. in der Werkstatt an, Fünf-Tage-Woche, nur gesetzlicher Urlaub. Wie viele Urlaubstage stehen ihm bis zum 31.12. zu?", "o": ["5 Arbeitstage", "20 Arbeitstage", "6 Arbeitstage", "3 Arbeitstage"], "c": 0, "e": "Er erfüllt die Wartezeit von sechs Monaten im Eintrittsjahr nicht. Für drei volle Monate erhält er 3 × 20 ÷ 12 = 5 Arbeitstage (§ 5 BUrlG)."}, {"q": "Eine Teilzeitkraft mit Vier-Tage-Woche beginnt am 01.10. bei der Service GmbH. Wie viel gesetzlichen Teilurlaub hat sie im Eintrittsjahr?", "o": ["4 Arbeitstage", "5 Arbeitstage", "16 Arbeitstage", "3 Arbeitstage"], "c": 0, "e": "Ihr Jahresurlaub beträgt 24 ÷ 6 × 4 = 16 Arbeitstage. Für drei volle Monate sind das 3 × 16 ÷ 12 = 4 Arbeitstage."}, {"q": "Im Verleih der Service GmbH arbeitet eine Kraft von Montag bis Samstag. Ihr Vertrag sieht 22 Urlaubstage vor. Was gilt?", "o": ["Sie hat Anspruch auf mindestens 24 Werktage", "Die 22 Tage sind wirksam, weil sie unterschrieben hat", "Sie hat Anspruch auf genau 20 Arbeitstage", "Bei sechs Arbeitstagen gibt es keinen gesetzlichen Mindesturlaub"], "c": 0, "e": "Bei einer Sechs-Tage-Woche entsprechen die 24 Werktage genau 24 Urlaubstagen. Die 22 Tage liegen darunter und sind insoweit unwirksam."}, {"q": "Jana Hoffmann beginnt am 01.02.2027 mit einer Fünf-Tage-Woche. Wie viel gesetzlichen Mindesturlaub hat sie im Jahr 2027?", "o": ["Den vollen Mindesturlaub von 20 Arbeitstagen", "Teilurlaub von 11 Arbeitstagen", "Teilurlaub von 18 Arbeitstagen", "Keinen Urlaub, weil die Probezeit erst am 31.07.2027 endet"], "c": 0, "e": "Die Wartezeit von sechs Monaten endet am 31.07.2027, also noch im Eintrittsjahr. Damit entsteht 2027 der volle gesetzliche Anspruch von 20 Arbeitstagen (§ 4 BUrlG). Teilurlaub gibt es nur, wenn die Wartezeit im Eintrittsjahr nicht erfüllt wird."}, {"q": "Jana Hoffmann beginnt am Montag, 01.02.2027. Ab welchem Tag müsste Nordstern ihr bei Krankheit erstmals das Entgelt fortzahlen?", "o": ["Ab dem 01.03.2027", "Ab dem 01.02.2027", "Ab dem 15.02.2027", "Ab dem 01.08.2027"], "c": 0, "e": "Der Anspruch entsteht nach vier Wochen ununterbrochenem Arbeitsverhältnis (§ 3 EFZG). Die vier Wochen dauern vom 01.02. bis 28.02.2027, ab dem 01.03.2027 zahlt Nordstern."}, {"q": "Ein langjähriger Monteur ist ab Donnerstag, 01.04.2027, für acht Wochen krank. Bis wann zahlt Nordstern das Entgelt fort?", "o": ["Bis zum 12.05.2027", "Bis zum 29.04.2027", "Bis zum 26.05.2027", "Bis zum 31.05.2027"], "c": 0, "e": "Die Entgeltfortzahlung dauert bis zu sechs Wochen, das sind 42 Kalendertage. Vom 01.04.2027 an ist der letzte Tag der 12.05.2027. Danach zahlt die Krankenkasse Krankengeld."}, {"q": "Ein Monteur ist ab Montag krank und weiß, dass es eine Woche dauern wird. Bis wann muss die Arbeitsunfähigkeit spätestens ärztlich festgestellt sein?", "o": ["Am Donnerstag", "Am Montag", "Am folgenden Montag", "Erst am Ende der Krankheit"], "c": 0, "e": "Dauert die Arbeitsunfähigkeit länger als drei Kalendertage, muss sie spätestens am darauffolgenden Arbeitstag ärztlich festgestellt sein (§ 5 EFZG). Nach Montag, Dienstag und Mittwoch ist das der Donnerstag."}, {"q": "Ein Lagerist ist am Montag krank, meldet sich aber erst am Mittwoch bei seinem Vorgesetzten. Welche Pflicht hat er verletzt?", "o": ["Die Pflicht zur unverzüglichen Krankmeldung", "Die Pflicht, dem Vorgesetzten seine Diagnose zu nennen", "Die Pflicht, am ersten Tag einen Papierschein abzugeben", "Keine Pflicht, zwei Tage Verspätung sind erlaubt"], "c": 0, "e": "Die Arbeitsunfähigkeit ist dem Arbeitgeber unverzüglich, also am ersten Tag, zu melden (§ 5 EFZG). Die Diagnose muss er nicht nennen, und gesetzlich Versicherte geben keinen Papierschein mehr ab."}, {"q": "Ein Mechaniker der Service GmbH beendet seine Spätschicht um 22:00 Uhr. Wann darf er am nächsten Tag frühestens wieder anfangen?", "o": ["Um 09:00 Uhr", "Um 06:00 Uhr", "Um 08:00 Uhr", "Um 10:00 Uhr"], "c": 0, "e": "Zwischen zwei Arbeitstagen müssen mindestens elf Stunden ununterbrochene Ruhezeit liegen (§ 5 ArbZG). Von 22:00 Uhr an gerechnet ist das 09:00 Uhr."}, {"q": "Eine Aushilfe der Service GmbH arbeitet an einem Tag genau sechs Stunden. Braucht sie nach dem Arbeitszeitgesetz eine Pause?", "o": ["Nein, sie braucht keine Pause", "Ja, sie braucht mindestens 30 Minuten", "Ja, sie braucht mindestens 15 Minuten", "Ja, sie braucht mindestens 45 Minuten"], "c": 0, "e": "Nach § 4 ArbZG braucht man bei mehr als sechs bis neun Stunden 30 Minuten Pause. Bei genau sechs Stunden ist keine Pause vorgeschrieben, sie kann aber freiwillig gewährt werden."}, {"q": "Eine Sachbearbeiterin in EG 9 erfährt, dass ihr männlicher Kollege mit gleicher Tätigkeit ohne sachlichen Grund 300 € mehr erhält. Was gilt?", "o": ["Das ist eine unzulässige Benachteiligung wegen des Geschlechts", "Das ist zulässig, weil Entgelte frei verhandelbar sind", "Das ist zulässig, solange jeder über dem Mindestlohn liegt", "Das AGG gilt nur bei der Stellenanzeige, nicht beim Entgelt"], "c": 0, "e": "Das AGG gilt im ganzen Arbeitsverhältnis, auch beim Entgelt (§ 7 AGG). Gleiche Tätigkeit ohne sachlichen Grund schlechter zu bezahlen, ist eine Benachteiligung wegen des Geschlechts."}, {"q": "Ein 58-jähriger Lagerist wird nicht befördert. Der Lagerleiter sagt, er sei für die neue Aufgabe zu alt. Wie ist das zu beurteilen?", "o": ["Als Benachteiligung wegen des Alters nach dem AGG", "Als zulässige Entscheidung im Rahmen des Weisungsrechts", "Als Frage, die nur den Tarifvertrag betrifft", "Als zulässig, weil Beförderungen nicht unter das AGG fallen"], "c": 0, "e": "Alter ist ein geschütztes Merkmal nach § 1 AGG. Das Verbot der Benachteiligung gilt auch bei Beförderungen."}, {"q": "Eine Monteurin erwartet ihr Kind am 15.09.2027. Wann beginnt ihre Schutzfrist vor der Entbindung?", "o": ["Am 04.08.2027", "Am 21.07.2027", "Am 18.08.2027", "Am 15.08.2027"], "c": 0, "e": "Die Schutzfrist beginnt sechs Wochen, also 42 Tage, vor der Entbindung. Vom 15.09.2027 zurückgerechnet ist das der 04.08.2027."}, {"q": "Eine Beschäftigte bringt am 15.09.2027 Zwillinge zur Welt. Wie lange gilt das Beschäftigungsverbot nach der Entbindung?", "o": ["Zwölf Wochen, also bis zum 08.12.2027", "Acht Wochen, also bis zum 10.11.2027", "Sechs Wochen, also bis zum 27.10.2027", "Vier Monate, also bis zum 15.01.2028"], "c": 0, "e": "Bei Mehrlingsgeburten verlängert sich die Schutzfrist nach der Entbindung von acht auf zwölf Wochen (§ 3 MuSchG). Zwölf Wochen nach dem 15.09.2027 ist der 08.12.2027."}, {"q": "Einer Verleihkraft der Service GmbH geht am 03.03.2027 eine Kündigung zu. Am 12.03.2027 teilt sie mit, dass sie schwanger ist. Was gilt?", "o": ["Die Kündigung ist unzulässig", "Die Kündigung bleibt wirksam, weil der Arbeitgeber nichts wusste", "Die Kündigung ist wirksam, weil der Betrieb klein ist", "Die Kündigung wird nur um vier Wochen verschoben"], "c": 0, "e": "Das Kündigungsverbot nach § 17 MuSchG gilt auch, wenn die Frau die Schwangerschaft innerhalb von zwei Wochen nach Zugang der Kündigung mitteilt. Es gilt in jedem Betrieb, unabhängig von der Größe."}, {"q": "Ein Monteur von Nordstern baut am Wochenende aus eigenen Teilen E-Bikes und verkauft sie an Fahrradhändler, die sonst bei Nordstern bestellen. Welche Pflicht ist berührt?", "o": ["Das Verbot, dem Arbeitgeber Konkurrenz zu machen", "Die Fürsorgepflicht des Arbeitgebers", "Die Pflicht zur Verschwiegenheit über Gehälter", "Die Pflicht, Urlaub im laufenden Jahr zu nehmen"], "c": 0, "e": "Während des Arbeitsverhältnisses dürfen Beschäftigte ihrem Arbeitgeber keine Konkurrenz machen. Das Wettbewerbsverbot gehört zur Treuepflicht."}, {"q": "Ein Lagerist bemerkt am Abend einen Wasserschaden über den Kartons mit Akkus und geht einfach nach Hause. Welche Pflicht verletzt er?", "o": ["Die Pflicht, Schäden vom Arbeitgeber abzuwenden", "Die Pflicht zur Entgeltzahlung", "Die Pflicht, Urlaub rechtzeitig zu beantragen", "Die Pflicht zur Gleichbehandlung"], "c": 0, "e": "Zur Treuepflicht gehört, Schäden vom Arbeitgeber abzuwenden. Er hätte den Schaden zumindest melden müssen."}, {"q": "Welche zusätzliche Unterlage braucht Nordstern vor dem Ausbildungsbeginn von Mia Schulz, 17 Jahre?", "o": ["Eine ärztliche Bescheinigung über die Erstuntersuchung", "Ein polizeiliches Führungszeugnis aus der Gemeinde", "Die Lohnsteuerkarte ihrer Eltern aus Papier", "Eine Urlaubsbescheinigung ihrer bisherigen Schule"], "c": 0, "e": "Bei Jugendlichen kommt die Bescheinigung über die ärztliche Erstuntersuchung zu den normalen Unterlagen hinzu. Die Steuermerkmale ruft Nordstern elektronisch ab."}, {"q": "Bis zu welchem Datum muss Nordstern die neue Lagerfachkraft mit Beginn am 01.07.2027 spätestens bei der Krankenkasse anmelden?", "o": ["Der 12.08.2027", "Der 01.08.2027", "Der 15.07.2027", "Der 01.07.2027"], "c": 0, "e": "Die Anmeldung erfolgt mit der ersten folgenden Entgeltabrechnung, spätestens sechs Wochen nach Beginn (§ 6 DEÜV). 01.07.2027 plus 42 Tage ergibt den 12.08.2027."}, {"q": "Jana Hoffmann ist seit drei Monaten bei Nordstern. Welches Gespräch sieht ihr Einarbeitungsplan jetzt vor?", "o": ["Ein Zwischengespräch", "Ein Kündigungsgespräch", "Ein zweites Vorstellungsgespräch", "Ein Gespräch über die Eingruppierung in EG 11"], "c": 0, "e": "Nach drei Monaten gibt es ein Zwischengespräch, vor dem Ende der Probezeit am 31.07.2027 ein Abschlussgespräch. In beiden geht es um Leistung, Zufriedenheit und offene Fragen auf beiden Seiten."}], "lernen": [{"t": "Arbeitsvertrag", "x": "Vertrag, in dem sich eine Person zu weisungsgebundener Arbeit und der Arbeitgeber zur Zahlung des Entgelts verpflichtet (§ 611a BGB)."}, {"t": "Schriftform", "x": "Papierdokument mit eigenhändiger Unterschrift, nötig etwa bei Befristung und Kündigung."}, {"t": "Textform", "x": "Lesbare, speicherbare Erklärung ohne Unterschrift, etwa ein PDF per E-Mail, seit 2025 für den Nachweis erlaubt."}, {"t": "Nachweisgesetz", "x": "Gesetz, nach dem der Arbeitgeber 15 wesentliche Arbeitsbedingungen innerhalb fester Fristen aufschreiben und aushändigen muss."}, {"t": "Sachgrund", "x": "Sachlicher Anlass für eine Befristung, zum Beispiel Vertretung, vorübergehender Bedarf oder Erprobung."}, {"t": "Sachgrundlose Befristung", "x": "Befristung ohne Grund, nur bei Neueinstellung, höchstens zwei Jahre mit höchstens drei Verlängerungen."}, {"t": "Probezeit", "x": "Vereinbarte Anfangszeit von höchstens sechs Monaten mit einer Kündigungsfrist von zwei Wochen."}, {"t": "Tarifautonomie", "x": "Recht von Gewerkschaften und Arbeitgebern, Arbeitsbedingungen ohne den Staat in Tarifverträgen zu regeln."}, {"t": "Manteltarifvertrag", "x": "Tarifvertrag mit allgemeinen Arbeitsbedingungen wie Arbeitszeit, Urlaub und Kündigungsfristen."}, {"t": "Günstigkeitsprinzip", "x": "Vom Tarif darf nur abgewichen werden, wenn es der Tarif erlaubt oder es für Beschäftigte günstiger ist."}, {"t": "Friedenspflicht", "x": "Während der Laufzeit eines Tarifvertrags kein Arbeitskampf über die darin geregelten Fragen."}, {"t": "Allgemeinverbindlichkeit", "x": "Erklärung durch das BMAS, dass ein Tarifvertrag auch für nicht gebundene Betriebe der Branche gilt."}, {"t": "Mindestlohn", "x": "Gesetzliche Lohnuntergrenze, 2026 13,90 € und ab 2027 14,60 € brutto je Stunde."}, {"t": "Weisungsrecht", "x": "Recht des Arbeitgebers, Inhalt, Ort und Zeit der Arbeit nach billigem Ermessen festzulegen (§ 106 GewO)."}, {"t": "Personalstammdaten", "x": "Daten, die sich selten ändern und für jede Abrechnung gebraucht werden, etwa Steuer-ID, SV-Nummer, Entgeltgruppe."}, {"t": "DEÜV-Anmeldung", "x": "Anmeldung zur Sozialversicherung bei der Krankenkasse mit der ersten Abrechnung, spätestens sechs Wochen nach Beginn."}, {"t": "ELStAM", "x": "Elektronische Lohnsteuerabzugsmerkmale wie Steuerklasse und Kirchensteuermerkmal, die der Arbeitgeber abruft."}, {"t": "Betriebsvereinbarung", "x": "Schriftlicher Vertrag zwischen Arbeitgeber und Betriebsrat, etwa zu Arbeitszeitverteilung, Pausen oder Gleitzeit. Er gilt unmittelbar und zwingend für die Beschäftigten im Betrieb."}, {"t": "Kollektives Arbeitsrecht", "x": "Tarifvertragsrecht und Betriebsverfassungsrecht. Das individuelle Arbeitsrecht regelt dagegen das einzelne Arbeitsverhältnis."}, {"t": "Vermögenswirksame Leistungen", "x": "Zuschuss des Arbeitgebers zu einem Sparvertrag der Beschäftigten, die Höhe steht meist im Tarifvertrag."}, {"t": "Urlaubsentgelt", "x": "Das normale Entgelt, das während des Urlaubs weitergezahlt wird. Urlaubsgeld ist dagegen eine zusätzliche Zahlung aus Tarif oder Vertrag."}, {"t": "Versicherungsnummernnachweis", "x": "Schreiben der Rentenversicherung mit der Sozialversicherungsnummer, ersetzt seit 2023 den Sozialversicherungsausweis."}, {"t": "Salvatorische Klausel", "x": "Vertragsklausel, nach der der übrige Vertrag wirksam bleibt, wenn eine einzelne Regel unwirksam ist."}, {"t": "Arbeitnehmer", "x": "Arbeitnehmer ist, wer im Dienst eines anderen weisungsgebundene, fremdbestimmte Arbeit in persönlicher Abhängigkeit leistet (§ 611a BGB)."}, {"t": "Formfrei, aber nicht formlos", "x": "Der Arbeitsvertrag selbst ist formfrei. Befristung, Kündigung und Aufhebungsvertrag brauchen die Schriftform. Wer das vergisst, hat am Ende einen unbefristeten Vertrag oder eine unwirksame Kündigung."}, {"t": "Salvatorische Klausel", "x": "Vertragsklausel, nach der der übrige Vertrag wirksam bleibt, wenn eine einzelne Regel unwirksam ist (Beiderwieden & Stickdorn, 2026)."}, {"t": "Sachgrund", "x": "Ein Sachgrund ist ein sachlicher Anlass, der eine Befristung rechtfertigt, etwa Vertretung, vorübergehender Bedarf oder Erprobung (§ 14 Abs. 1 TzBfG)."}, {"t": "Probezeit und Wartezeit", "x": "Probezeit heißt kurze Kündigungsfrist von zwei Wochen. Wartezeit heißt, dass der Kündigungsschutz erst nach sechs Monaten beginnt. Beides dauert oft sechs Monate, ist aber nicht dasselbe."}, {"t": "Tarifautonomie", "x": "Tarifautonomie ist das Recht von Gewerkschaften und Arbeitgebern, Arbeitsbedingungen ohne staatliche Einmischung in Tarifverträgen zu regeln (Art. 9 Abs. 3 GG, Beiderwieden & Stickdorn, 2026)."}, {"t": "Tarifbindung", "x": "Tarifbindung bedeutet, dass ein Tarifvertrag für ein Arbeitsverhältnis unmittelbar und zwingend gilt, weil beide Seiten Mitglied der Tarifparteien sind oder der Tarif allgemeinverbindlich ist (§ 3 TVG, § 4 Abs. 1 TVG)."}, {"t": "Eingruppierung in zwei Schritten", "x": "Erst die Stellenbeschreibung mit den Merkmalen im Rahmentarif vergleichen und die Entgeltgruppe bestimmen, dann den Betrag im Entgelttarif ablesen."}, {"t": "Einzelvertrag", "x": "Ein Einzelvertrag ist ein Arbeitsvertrag, dessen Bedingungen nur zwischen Arbeitgeber und einzelner beschäftigter Person vereinbart werden, ohne Tarifvertrag. Untergrenze sind die Gesetze, zum Beispiel § 1 MiLoG und § 3 BUrlG."}, {"t": "Nach unten nur besser", "x": "Jede niedrigere Ebene darf die höhere nur zugunsten der Beschäftigten verändern. Schlechtere Regeln sind unwirksam."}, {"t": "Kollektives Arbeitsrecht", "x": "Teil des Arbeitsrechts, der die Beziehungen zwischen Gewerkschaften, Arbeitgeberverbänden, Arbeitgebern und Betriebsräten regelt, vor allem Tarifvertragsrecht und Betriebsverfassungsrecht (Beiderwieden & Stickdorn, 2026)."}, {"t": "Werktag", "x": "Werktage sind alle Kalendertage, die nicht Sonntag oder gesetzlicher Feiertag sind. Der Samstag zählt also mit (§ 3 Abs. 2 BUrlG)."}, {"t": "Sechs vor, acht nach", "x": "Die Schutzfrist dauert sechs Wochen vor und acht Wochen nach der Entbindung. Der Kündigungsschutz reicht mindestens bis vier Monate nach der Entbindung."}, {"t": "Personalakte", "x": "Die Personalakte ist die Sammlung aller Unterlagen, die das Arbeitsverhältnis einer bestimmten Person betreffen. Beschäftigte dürfen sie einsehen (§ 83 BetrVG)."}, {"t": "Stammdaten pflegen", "x": "Ändert sich etwas, etwa die Anschrift, die Bankverbindung oder nach einer Heirat die Steuerklasse, muss das Stammblatt sofort aktualisiert werden. Sonst stimmt die nächste Abrechnung nicht."}, {"t": "Rechtsgrundlage für Beschäftigtendaten", "x": "Beschäftigtendaten dürfen verarbeitet werden, wenn das für den Arbeitsvertrag oder wegen einer gesetzlichen Pflicht erforderlich ist (Art. 6 Abs. 1 DSGVO)."}, {"t": "So wenig wie möglich", "x": "Nur Daten erheben, die wirklich gebraucht werden, Zugriff auf wenige Personen beschränken und Daten löschen, wenn sie nicht mehr nötig sind."}], "sortier": [{"titel": "Welcher Tarifvertrag regelt das?", "auftrag": "Ordne jede Regel der Art von Tarifvertrag zu, in der sie bei Nordstern steht.", "kategorien": [{"id": "a", "name": "Manteltarifvertrag"}, {"id": "b", "name": "Rahmentarifvertrag"}, {"id": "c", "name": "Entgelttarifvertrag"}], "items": [{"text": "Wöchentliche Arbeitszeit von 35 Stunden", "kat": "a", "expl": "Die Arbeitszeit ist eine allgemeine Arbeitsbedingung. Sie steht im Manteltarifvertrag."}, {"text": "30 Urlaubstage im Jahr (vereinfachtes Beispiel)", "kat": "a", "expl": "Der Urlaub gehört zu den allgemeinen Bedingungen im Manteltarifvertrag."}, {"text": "Zuschläge für Überstunden und Schichtarbeit", "kat": "a", "expl": "Zuschläge regelt der Manteltarifvertrag zusammen mit Arbeitszeit und Urlaub."}, {"text": "Kündigungsfristen für die Beschäftigten", "kat": "a", "expl": "Auch Kündigungsfristen sind allgemeine Bedingungen. Sie stehen im Manteltarifvertrag."}, {"text": "Läuft meist mehrere Jahre", "kat": "a", "expl": "Allgemeine Bedingungen ändern sich selten. Darum läuft der Manteltarifvertrag lange."}, {"text": "Beschreibt die Entgeltgruppen EG 3 bis EG 13", "kat": "b", "expl": "Der Rahmentarifvertrag legt die Gruppen und ihre Merkmale fest."}, {"text": "Legt fest, welche Tätigkeit in welche Gruppe gehört", "kat": "b", "expl": "Das nennt man Eingruppierung. Sie folgt aus dem Rahmentarifvertrag."}, {"text": "Merkmal, eine abgeschlossene kaufmännische Ausbildung", "kat": "b", "expl": "Solche Tätigkeitsmerkmale stehen im Rahmentarifvertrag. Danach wird eingruppiert."}, {"text": "Ziel, gleiche Anforderungen gleich zu bezahlen", "kat": "b", "expl": "Genau dafür gibt es den Rahmentarifvertrag mit festen Merkmalen je Gruppe."}, {"text": "Sachbearbeitung kaufmännisch gehört in EG 9", "kat": "b", "expl": "Die Zuordnung der Tätigkeit zur Gruppe ist Eingruppierung. Sie steht im Rahmentarifvertrag."}, {"text": "EG 9 erhält 3.950 € im Monat", "kat": "c", "expl": "Der Euro-Betrag je Gruppe steht im Entgelttarifvertrag (vereinfachtes Beispiel)."}, {"text": "EG 7 erhält 3.600 € im Monat", "kat": "c", "expl": "Konkrete Beträge nennt der Entgelttarifvertrag. Das ist eine vereinfachte Tabelle."}, {"text": "Nennt die konkreten Euro-Beträge je Gruppe", "kat": "c", "expl": "Das ist die Aufgabe des Entgelttarifvertrags."}, {"text": "Läuft meist nur ein bis zwei Jahre", "kat": "c", "expl": "Über Geld wird am häufigsten neu verhandelt. Darum läuft der Entgelttarifvertrag kurz."}, {"text": "Früher Lohn- und Gehaltstarifvertrag genannt", "kat": "c", "expl": "Das ist der alte Name des Entgelttarifvertrags."}]}, {"titel": "Gesetz, Tarif oder Vertrag?", "auftrag": "Bestimme, auf welcher Ebene die Regel für die Fahrradwerke oder die Service GmbH festgelegt ist.", "kategorien": [{"id": "a", "name": "Gesetz"}, {"id": "b", "name": "Tarifvertrag"}, {"id": "c", "name": "Arbeitsvertrag"}], "items": [{"text": "Mindestlohn von 13,90 € je Stunde im Jahr 2026", "kat": "a", "expl": "Der Mindestlohn folgt aus dem MiLoG und der Verordnung MiLoV5. Er gilt auch ohne Tarif."}, {"text": "Mindestens 24 Werktage Urlaub im Jahr", "kat": "a", "expl": "Den Mindesturlaub regelt das Gesetz (§ 3 BUrlG)."}, {"text": "Entgeltfortzahlung bei Krankheit bis zu 6 Wochen", "kat": "a", "expl": "Das steht im Entgeltfortzahlungsgesetz (§ 3 EFZG)."}, {"text": "Schutzfrist von 6 Wochen vor der Entbindung", "kat": "a", "expl": "Die Schutzfrist steht im Mutterschutzgesetz. Sie gilt in jedem Betrieb."}, {"text": "Ruhezeit von mindestens 11 Stunden", "kat": "a", "expl": "Die Ruhezeit regelt das Arbeitszeitgesetz (§ 5 ArbZG)."}, {"text": "35-Stunden-Woche in den Fahrradwerken", "kat": "b", "expl": "Nordstern ist im Arbeitgeberverband und an den Metalltarif gebunden. Daraus kommen die 35 Stunden."}, {"text": "Monatsentgelt von 3.600 € für EG 7", "kat": "b", "expl": "Der Betrag stammt aus der Entgelttabelle des Tarifs (vereinfachtes Beispiel)."}, {"text": "Entgeltgruppen EG 3 bis EG 13 in den Fahrradwerken", "kat": "b", "expl": "Die Gruppen legt der Tarifvertrag fest. Die Service GmbH hat sie nicht."}, {"text": "30 Urlaubstage laut Manteltarif (Beispiel)", "kat": "b", "expl": "Mehr Urlaub als im Gesetz kommt hier aus dem Tarifvertrag."}, {"text": "Gilt für Mitglieder von IG Metall und Arbeitgeberverband", "kat": "b", "expl": "Tarifgebunden sind die Mitglieder der Tarifparteien (§ 3 TVG)."}, {"text": "40-Stunden-Woche bei der Service GmbH", "kat": "c", "expl": "Die Tochter hat keinen Tarif. Die Arbeitszeit steht im Einzelvertrag."}, {"text": "Mechaniker der Service GmbH erhält 2.900 € im Monat", "kat": "c", "expl": "Ohne Tarif wird das Entgelt einzeln vereinbart, mindestens in Höhe des Mindestlohns."}, {"text": "Jana Hoffmann arbeitet als Sachbearbeiterin Personal", "kat": "c", "expl": "Die Tätigkeit wird im Arbeitsvertrag vereinbart."}, {"text": "Probezeit von 6 Monaten für Jana Hoffmann", "kat": "c", "expl": "Das Gesetz erlaubt bis zu 6 Monate. Vereinbart wird die Probezeit im Arbeitsvertrag."}, {"text": "Facharbeiter erhält 3.750 € statt Tarif 3.600 €", "kat": "c", "expl": "Der Vertrag darf günstiger sein als der Tarif. Das ist das Günstigkeitsprinzip."}]}]}, {"nr": 5, "title": "Personalentlohnung", "date": "27.11.2026", "quiz": [{"q": "Welcher Begriff ist der Oberbegriff für jede Gegenleistung des Arbeitgebers für die Arbeit?", "o": ["Entgelt", "Gehalt", "Prämie", "Zulage"], "c": 0, "e": "Entgelt umfasst Lohn, Gehalt, Ausbildungsvergütung, Zulagen, Zuschläge und Sonderzahlungen. Gehalt, Prämie und Zulage sind nur Teile davon."}, {"q": "Wer erhält bei Nordstern typischerweise Lohn?", "o": ["Jonas, Facharbeiter in der Montage", "Lisa, Sachbearbeiterin im Vertrieb", "Mia, Auszubildende Industriekauffrau", "Malte Brandt, Personalleiter"], "c": 0, "e": "Lohn bekommen gewerbliche Beschäftigte wie Monteure. Kaufmännische Angestellte bekommen Gehalt, Auszubildende eine Ausbildungsvergütung."}, {"q": "Was versteht man unter dem Bruttoentgelt?", "o": ["Das Entgelt vor allen Abzügen", "Das Entgelt nach Abzug der Steuern", "Den Auszahlungsbetrag auf das Konto", "Die Kosten des Arbeitgebers insgesamt"], "c": 0, "e": "Brutto ist der Betrag vor Steuern und Sozialversicherung. Der Auszahlungsbetrag ist das Netto, die Arbeitgeberkosten liegen über dem Brutto."}, {"q": "Wann ist ein Entgelt anforderungsgerecht?", "o": ["Wenn schwierigere Stellen besser bezahlt werden", "Wenn jede Person genau gleich viel verdient", "Wenn Familien mit Kindern einen Zuschlag erhalten", "Wenn allein die gefertigte Stückzahl zählt"], "c": 0, "e": "Anforderungsgerecht richtet sich nach den Anforderungen der Stelle, die mit der Arbeitsbewertung ermittelt werden. Familienzuschläge gehören zur sozialen Gerechtigkeit."}, {"q": "Was wird bei der Arbeitsbewertung bewertet?", "o": ["Die Anforderungen der Stelle", "Die Leistung der Person", "Das Verhalten im Team", "Die Zahl der Fehltage"], "c": 0, "e": "Die Arbeitsbewertung betrachtet die Stelle und nicht den Menschen. Die persönliche Leistung wird getrennt in der Leistungsbewertung beurteilt."}, {"q": "Bei welchem Verfahren werden für einzelne Anforderungsmerkmale Punkte vergeben und addiert?", "o": ["Stufenwertzahlverfahren", "Rangfolgeverfahren", "Lohngruppenverfahren", "Stückgeldverfahren"], "c": 0, "e": "Beim Stufenwertzahlverfahren erhält jedes Merkmal eine Stufe mit Punkten. Die Summe der Punkte bestimmt die Entgeltgruppe."}, {"q": "Wie hoch ist der Stundenlohn in EG 7 bei Nordstern (3.600 €, Teiler 152,25)?", "o": ["23,65 €", "22,50 €", "24,00 €", "20,69 €"], "c": 0, "e": "3.600 € ÷ 152,25 Std. = 23,645 €, gerundet 23,65 €. 24,00 € ist der Akkordrichtsatz in der Rahmenmontage."}, {"q": "Woraus ergibt sich der Teiler 152,25 Stunden bei Nordstern?", "o": ["35 Wochenstunden × 4,35 Wochen", "40 Wochenstunden × 3,8 Wochen", "7 Tagesstunden × 21,75 Tage", "35 Wochenstunden × 4,5 Wochen"], "c": 0, "e": "Nordstern hat eine 35-Stunden-Woche, ein Monat hat im Durchschnitt 4,35 Wochen. 35 × 4,35 = 152,25 Stunden."}, {"q": "In welchem Bereich von Nordstern passt Zeitlohn besonders gut?", "o": ["Qualitätssicherung", "Serienmontage der Rahmen", "Stückweise Vormontage", "Zählbare Lackierung in Serie"], "c": 0, "e": "In der Qualitätssicherung zählt Sorgfalt mehr als Tempo, und die Menge lässt sich schlecht als Leistung messen. Serienarbeiten eignen sich eher für Akkord."}, {"q": "Bei welcher Tätigkeit ist Akkordlohn am wenigsten geeignet?", "o": ["Planung einer neuen Lastenrad-Baureihe", "Montage gleicher Lastenrad-Rahmen", "Verpacken gleicher Ersatzteile", "Einspeichen gleicher Laufräder"], "c": 0, "e": "Planung ist geistige Arbeit ohne gleichartige, zählbare Stücke. Die anderen Tätigkeiten wiederholen sich und lassen sich gut zählen."}, {"q": "Woraus besteht der Akkordrichtsatz?", "o": ["Grundlohn plus Akkordzuschlag", "Grundlohn minus Akkordzuschlag", "Stückgeld mal Vorgabezeit", "Minutenfaktor mal Stückzahl"], "c": 0, "e": "Der Akkordrichtsatz ist der Stundenverdienst bei Normalleistung. Er setzt sich aus Grundlohn und Akkordzuschlag zusammen."}, {"q": "Wie hoch ist der Akkordrichtsatz in der Rahmenmontage bei Nordstern (Grundlohn 20,00 €, Zuschlag 20 %)?", "o": ["24,00 €", "20,00 €", "22,00 €", "40,00 €"], "c": 0, "e": "20 % von 20,00 € sind 4,00 €. 20,00 € + 4,00 € = 24,00 € je Stunde."}, {"q": "Die Vorgabezeit für einen Lastenrad-Rahmen beträgt 15 Minuten. Wie hoch ist die Normalleistung je Stunde?", "o": ["4 Stück", "15 Stück", "5 Stück", "6 Stück"], "c": 0, "e": "Normalleistung = 60 Minuten ÷ Vorgabezeit. 60 ÷ 15 = 4 Stück je Stunde."}, {"q": "Wie hoch ist das Stückgeld bei einem Richtsatz von 24,00 € und einer Normalleistung von 4 Stück?", "o": ["6,00 €", "5,00 €", "4,00 €", "0,40 €"], "c": 0, "e": "Stückgeld = Richtsatz ÷ Normalleistung = 24,00 € ÷ 4 = 6,00 €. Wer den Grundlohn teilt, kommt fälschlich auf 5,00 €."}, {"q": "Wie hoch ist der Minutenfaktor bei einem Akkordrichtsatz von 24,00 €?", "o": ["0,40 €", "0,33 €", "0,24 €", "1,60 €"], "c": 0, "e": "Minutenfaktor = Richtsatz ÷ 60 Minuten = 24,00 € ÷ 60 = 0,40 € je Vorgabeminute. 0,33 € wäre der Grundlohn geteilt durch 60."}, {"q": "Wie berechnet man den Lohn im Zeitakkord?", "o": ["Stückzahl × Vorgabezeit × Minutenfaktor", "Arbeitsstunden × Grundlohn × Akkordzuschlag", "Stückzahl × Grundlohn ÷ 60 Minuten", "Vorgabezeit × Richtsatz × 60 Minuten"], "c": 0, "e": "Im Zeitakkord wird für jedes Stück die Vorgabezeit gutgeschrieben und mit dem Minutenfaktor bezahlt. Das Ergebnis entspricht dem Stückgeldakkord."}, {"q": "Warum ist der Zeitakkord in der Praxis oft beliebter als der Stückgeldakkord?", "o": ["Bei Tariferhöhung ändert sich nur der Minutenfaktor", "Er führt bei gleicher Menge immer zu höherem Lohn", "Er kommt ganz ohne Vorgabezeiten aus", "Er gilt ohne jede Mitbestimmung des Betriebsrats"], "c": 0, "e": "Die Vorgabezeiten bleiben bei einer Lohnerhöhung gleich, nur der Minutenfaktor wird neu berechnet. Das Ergebnis ist bei beiden Verfahren gleich."}, {"q": "Ein Monteur schafft 5 Rahmen je Stunde. Wie hoch ist sein Stundenverdienst im Stückgeldakkord?", "o": ["30,00 €", "24,00 €", "25,00 €", "36,00 €"], "c": 0, "e": "5 Stück × 6,00 € = 30,00 €. Im Zeitakkord ergibt sich ebenso 5 × 15 Min. × 0,40 € = 30,00 €."}, {"q": "Wie hoch ist der Leistungsgrad, wenn ein Monteur 5 statt 4 Rahmen je Stunde schafft?", "o": ["125 %", "80 %", "120 %", "150 %"], "c": 0, "e": "Leistungsgrad = Ist-Leistung ÷ Normalleistung × 100 = 5 ÷ 4 × 100 = 125 %. Wer den Bruch umdreht, erhält falsch 80 %."}, {"q": "Ein Monteur montiert an einem Tag in 8 Stunden 40 Rahmen. Wie hoch ist sein Tageslohn im Akkord?", "o": ["240,00 €", "192,00 €", "160,00 €", "200,00 €"], "c": 0, "e": "40 × 6,00 € = 240,00 €. 192,00 € wären 8 Stunden zum Richtsatz bei Normalleistung, 160,00 € die Garantie."}, {"q": "Wegen einer Maschinenstörung schafft ein Monteur in einer Stunde nur 3 Rahmen. Was erhält er für diese Stunde?", "o": ["20,00 €", "18,00 €", "24,00 €", "13,90 €"], "c": 0, "e": "Rechnerisch wären es 3 × 6,00 € = 18,00 €. Die Mindestlohngarantie sichert aber den Grundlohn von 20,00 € je Stunde."}, {"q": "Ein Monteur montiert in 8 Stunden 36 Rahmen (Normalleistung 4 Stück je Stunde). Wie hoch ist sein Leistungsgrad?", "o": ["112,5 %", "88,9 %", "120,0 %", "108,0 %"], "c": 0, "e": "Normalleistung am Tag 8 × 4 = 32 Stück. Leistungsgrad 36 ÷ 32 × 100 = 112,5 %."}, {"q": "Welcher Teil des Akkordrichtsatzes ist bei Nordstern garantiert?", "o": ["Nur der Grundlohn von 20,00 €", "Der volle Richtsatz von 24,00 €", "Nur der Zuschlag von 4,00 €", "Der Stundenlohn von 30,00 €"], "c": 0, "e": "Garantiert ist der Grundlohn. Den Akkordzuschlag erhält nur, wer mindestens die Normalleistung erreicht."}, {"q": "Für eine Lastenrad-Gabel gilt eine Vorgabezeit von 12 Minuten. Wie hoch ist die Normalleistung je Stunde?", "o": ["5 Stück", "4 Stück", "12 Stück", "6 Stück"], "c": 0, "e": "Normalleistung = 60 Minuten ÷ 12 Minuten = 5 Stück je Stunde."}, {"q": "Wie hoch ist das Stückgeld für die Gabel mit 12 Minuten Vorgabezeit bei einem Richtsatz von 24,00 €?", "o": ["4,80 €", "6,00 €", "2,00 €", "5,00 €"], "c": 0, "e": "Normalleistung 5 Stück, Stückgeld 24,00 € ÷ 5 = 4,80 €. Kontrolle über den Zeitakkord 12 Min. × 0,40 € = 4,80 €."}, {"q": "Wie setzt sich der Prämienlohn zusammen?", "o": ["Grundlohn plus Prämie", "Stückgeld plus Minutenfaktor", "Gehalt minus Abzüge", "Akkordzuschlag ohne Grundlohn"], "c": 0, "e": "Beim Prämienlohn gibt es einen festen Grundlohn und zusätzlich eine Prämie für eine messbare Mehrleistung."}, {"q": "Was belohnt eine Qualitätsprämie?", "o": ["Weniger Ausschuss oder Nacharbeit", "Eine höhere Stückzahl", "Eine lange Betriebszugehörigkeit", "Einen höheren Jahresgewinn"], "c": 0, "e": "Die Qualitätsprämie belohnt gute Arbeitsergebnisse. Mehr Stück belohnt die Mengenprämie, den Gewinn die Erfolgsbeteiligung."}, {"q": "Eine Monteurin in EG 5 (3.250 €) erhält 8 % Qualitätsprämie. Wie hoch ist die Prämie?", "o": ["260,00 €", "325,00 €", "240,00 €", "406,25 €"], "c": 0, "e": "3.250 € × 8 % = 260,00 €. Das Brutto mit Prämie beträgt 3.510,00 €."}, {"q": "Eine Vertriebsmitarbeiterin erhält zusätzlich zum Gehalt 2 % vom vermittelten Umsatz. Wie nennt man diese Zahlung?", "o": ["Provision", "Zulage", "Akkordzuschlag", "Sachbezug"], "c": 0, "e": "Die Provision ist eine Umsatzbeteiligung und im Vertrieb üblich. Sie hängt vom Umsatz ab, den die Mitarbeiterin vermittelt."}, {"q": "Welche Form der Erfolgsbeteiligung macht Beschäftigte zu Miteigentümern?", "o": ["Kapitalbeteiligung, zum Beispiel Belegschaftsaktien", "Umsatzbeteiligung, zum Beispiel eine Provision", "Gewinnbeteiligung als jährliche Barzahlung", "Qualitätsprämie in der Lackiererei von Nordstern"], "c": 0, "e": "Bei der Kapitalbeteiligung erwerben Beschäftigte Anteile am Unternehmen. Bei Gewinn- und Umsatzbeteiligung bekommen sie Geld, aber keine Anteile."}, {"q": "Nordstern verteilt 240.000 € Gewinnbeteiligung gleichmäßig auf 240 Beschäftigte. Wie viel erhält jede Person?", "o": ["1.000 €", "100 €", "2.400 €", "10.000 €"], "c": 0, "e": "240.000 € ÷ 240 = 1.000 € je Person. Die Zahlung ist steuer- und beitragspflichtig."}, {"q": "Welche Zahlung ist eine Zulage?", "o": ["Schmutzzulage in der Lackiererei", "25 % mehr für Überstunden", "Weihnachtsgeld im November", "Provision für den Vertrieb"], "c": 0, "e": "Eine Zulage gibt es für eine besondere Art der Arbeit, zum Beispiel Schmutz oder Lärm. Überstundengeld ist ein Zuschlag, Weihnachtsgeld eine Sonderzahlung."}, {"q": "Jonas hat einen Stundenlohn von 23,65 € und leistet 10 Überstunden. Wie hoch ist die Überstundenvergütung ohne Zuschlag?", "o": ["236,50 €", "295,63 €", "59,13 €", "240,00 €"], "c": 0, "e": "10 × 23,65 € = 236,50 €. Mit dem Zuschlag von 59,13 € kommen insgesamt 295,63 € hinzu."}, {"q": "Wie hoch ist der Überstundenzuschlag von 25 % auf 236,50 €?", "o": ["59,13 €", "59,12 €", "23,65 €", "94,60 €"], "c": 0, "e": "236,50 € × 25 % = 59,125 €, kaufmännisch gerundet 59,13 €. Das Brutto von Jonas beträgt damit 3.895,63 €."}, {"q": "Wie hoch ist der gesetzliche Mindestlohn je Stunde im Jahr 2026?", "o": ["13,90 €", "12,82 €", "14,60 €", "12,41 €"], "c": 0, "e": "Seit dem 01.01.2026 gilt ein Mindestlohn von 13,90 € brutto je Stunde. 12,82 € galt 2025, 14,60 € gilt ab 2027."}, {"q": "Wie hoch ist der beschlossene Mindestlohn ab dem 01.01.2027?", "o": ["14,60 €", "15,00 €", "13,90 €", "14,20 €"], "c": 0, "e": "Die Fünfte Mindestlohnanpassungsverordnung legt 14,60 € ab dem 01.01.2027 fest."}, {"q": "Die Nordstern Service GmbH hat eine 40-Stunden-Woche (174 Stunden im Monat). Welches Monatsentgelt muss sie 2026 mindestens zahlen?", "o": ["2.418,60 €", "2.116,28 €", "2.300,00 €", "2.540,40 €"], "c": 0, "e": "174 Std. × 13,90 € = 2.418,60 €. Ein Angebot von 2.300 € läge mit 13,22 € je Stunde unter dem Mindestlohn."}, {"q": "Wie viele volle Stunden darf ein Minijobber mit 13,90 € je Stunde 2026 höchstens im Monat arbeiten (Grenze 603 €)?", "o": ["43 Stunden", "44 Stunden", "47 Stunden", "40 Stunden"], "c": 0, "e": "603 € ÷ 13,90 € = 43,38. Bei 43 Stunden ergeben sich 597,70 €, bei 44 Stunden wären es 611,60 € und damit zu viel."}, {"q": "Wie berechnet man das Nettoentgelt?", "o": ["Brutto minus Steuern minus SV-Anteil Arbeitnehmer", "Brutto minus Steuern minus SV-Anteil Arbeitgeber", "Brutto plus SV-Anteil Arbeitgeber", "Brutto minus Lohnsteuer, ohne Sozialversicherung"], "c": 0, "e": "Vom Brutto werden Lohnsteuer, Soli, Kirchensteuer und der Arbeitnehmeranteil zur Sozialversicherung abgezogen. Der Arbeitgeberanteil wird zusätzlich gezahlt und nicht abgezogen."}, {"q": "Wo ruft der Arbeitgeber die ELStAM ab?", "o": ["Beim Bundeszentralamt für Steuern", "Bei der Krankenkasse der Beschäftigten", "Bei der örtlichen Agentur für Arbeit", "Beim Einwohnermeldeamt der Stadt"], "c": 0, "e": "Der Arbeitgeber ruft die Merkmale elektronisch mit Steuer-ID und Geburtsdatum beim Bundeszentralamt für Steuern ab (§ 39e EStG)."}, {"q": "Welche Steuerklasse hat Lisa Wagner (ledig, keine Kinder)?", "o": ["I", "II", "IV", "VI"], "c": 0, "e": "Ledige haben Steuerklasse I. Klasse II ist für Alleinerziehende, IV für Verheiratete, VI für ein zweites Arbeitsverhältnis."}, {"q": "Welche Steuerklasse erhält eine alleinerziehende Mutter mit Entlastungsbetrag?", "o": ["II", "I", "III", "V"], "c": 0, "e": "Steuerklasse II berücksichtigt den Entlastungsbetrag für Alleinerziehende."}, {"q": "Eine Monteurin von Nordstern arbeitet am Wochenende zusätzlich in einem Fahrradladen. Welche Steuerklasse gilt für den Nebenjob?", "o": ["VI", "I", "V", "II"], "c": 0, "e": "Für jedes zweite und weitere Arbeitsverhältnis gilt Steuerklasse VI. Sie hat keine Freibeträge und deshalb den höchsten Abzug."}, {"q": "Wann lohnt sich für ein Ehepaar die Kombination der Steuerklassen III und V?", "o": ["Wenn ein Partner deutlich mehr verdient", "Wenn die Partner genau gleich viel verdienen", "Wenn jeder Partner einen Nebenjob hat", "Wenn die Partner noch in der Ausbildung sind"], "c": 0, "e": "Mit III und V zahlt der Besserverdienende wenig, der andere viel Lohnsteuer. Das passt bei großen Unterschieden, bei ähnlichem Einkommen eher IV und IV."}, {"q": "Laut Tabellenauszug 2026 (ohne Kinder, älter als 23) beträgt die Lohnsteuer bei 3.950,00 € in Steuerklasse I wie viel?", "o": ["512,25 €", "192,16 €", "928,16 €", "500,16 €"], "c": 0, "e": "In der Zeile 3.950,00 € und der Spalte I und IV steht 512,25 €. 192,16 € gilt für Klasse III, 928,16 € für Klasse V."}, {"q": "Bis wann muss Nordstern die Lohnsteuer für November 2026 anmelden und abführen?", "o": ["Bis zum 10.12.2026", "Bis zum 26.11.2026", "Bis zum 31.12.2026", "Bis zum 15.01.2027"], "c": 0, "e": "Die Lohnsteuer wird bis zum 10. des Folgemonats angemeldet und abgeführt (§ 41a Abs. 1 EStG). Der 26.11. ist der Fälligkeitstag der SV-Beiträge."}, {"q": "Wie hoch ist der Grundfreibetrag 2026 für eine einzelne Person?", "o": ["12.348 €", "11.784 €", "24.696 €", "13.800 €"], "c": 0, "e": "Der Grundfreibetrag 2026 beträgt 12.348 €. 24.696 € gilt bei Zusammenveranlagung, 13.800 € ist der Jahreslohn von Mia."}, {"q": "Wie hoch ist der volle Satz des Solidaritätszuschlags?", "o": ["5,5 % der Lohnsteuer", "5,5 % des Bruttoentgelts", "9 % der Lohnsteuer", "7,5 % der Lohnsteuer"], "c": 0, "e": "Der Soli bemisst sich nach der Lohnsteuer, nicht nach dem Brutto. Wegen der Freigrenze fällt er aber meist gar nicht an."}, {"q": "Warum zahlt Lisa Wagner keinen Solidaritätszuschlag?", "o": ["Ihre Jahreslohnsteuer liegt unter der Freigrenze", "Steuerklasse I ist vom Soli grundsätzlich befreit", "Wer Kirchensteuer zahlt, zahlt keinen Soli", "Kinderlose zahlen grundsätzlich keinen Soli mehr"], "c": 0, "e": "Lisa zahlt im Jahr 6.147 € Lohnsteuer, der Soli fällt aber erst über 20.350 € an. Steuerklasse, Kirchensteuer oder Kinderlosigkeit befreien nicht."}, {"q": "Wie hoch ist die Kirchensteuer von Lisa bei einer Lohnsteuer von 512,25 €?", "o": ["46,10 €", "46,11 €", "40,98 €", "28,17 €"], "c": 0, "e": "512,25 € × 9 % = 46,1025 €. Cent-Bruchteile werden abgerundet, also 46,10 €. 40,98 € wären 8 %."}, {"q": "Wie hoch ist der allgemeine Beitragssatz der Krankenversicherung 2026?", "o": ["14,6 %", "14,0 %", "17,5 %", "18,6 %"], "c": 0, "e": "Der allgemeine Beitragssatz beträgt 14,6 % (§ 241 SGB V). 17,5 % ist der Satz inklusive durchschnittlichem Zusatzbeitrag, 18,6 % gilt für die RV."}, {"q": "Wie hoch ist der durchschnittliche Zusatzbeitrag der Krankenversicherung 2026?", "o": ["2,9 %", "2,5 %", "1,7 %", "3,6 %"], "c": 0, "e": "Das Bundesgesundheitsministerium hat den durchschnittlichen Zusatzbeitrag 2026 auf 2,9 % festgelegt. 2025 lag er bei 2,5 %."}, {"q": "Wie hoch ist der KV-Anteil des Arbeitnehmers im Kurs (14,6 % + 2,9 % Zusatzbeitrag)?", "o": ["8,75 %", "7,3 %", "10,2 %", "17,5 %"], "c": 0, "e": "Allgemeiner Beitrag und Zusatzbeitrag werden je zur Hälfte getragen. 7,3 % + 1,45 % = 8,75 %."}, {"q": "Wie hoch ist der Arbeitnehmeranteil zur Rentenversicherung 2026?", "o": ["9,3 %", "18,6 %", "9,8 %", "8,75 %"], "c": 0, "e": "Der RV-Beitragssatz beträgt 18,6 % (§ 158 SGB VI), Arbeitnehmer und Arbeitgeber tragen je 9,3 %."}, {"q": "Was geschieht mit den Beiträgen zur gesetzlichen Krankenversicherung?", "o": ["Sie fließen in den Gesundheitsfonds, der an die Kassen verteilt", "Jede Krankenkasse behält sie vollständig für ihre Mitglieder", "Sie werden mit der Lohnsteuer an das Finanzamt überwiesen", "Sie gehen direkt an die Deutsche Rentenversicherung"], "c": 0, "e": "Die KV-Beiträge fließen in den Gesundheitsfonds (§ 271 SGB V). Er verteilt Zuweisungen an die Kassen nach Alter, Geschlecht und Krankheitsrisiko der Versicherten."}, {"q": "Wie hoch ist der Beitragssatz der Pflegeversicherung 2026 ohne Zuschlag und Abschlag?", "o": ["3,6 %", "3,4 %", "4,2 %", "2,4 %"], "c": 0, "e": "Die PV hat 3,6 % (§ 55 Abs. 1 SGB XI), je 1,8 % für Arbeitnehmer und Arbeitgeber. 4,2 % ergibt sich mit Kinderlosenzuschlag."}, {"q": "Wer trägt den Kinderlosenzuschlag in der Pflegeversicherung?", "o": ["Nur der Arbeitnehmer", "Nur der Arbeitgeber", "AN und AG je zur Hälfte", "Die Pflegekasse selbst"], "c": 0, "e": "Den Zuschlag zahlt allein der Arbeitnehmer. Der Arbeitgeber bleibt bei 1,8 %, deshalb sind die Anteile bei Lisa verschieden."}, {"q": "Welchen PV-Satz zahlt Jonas Petersen mit zwei Kindern unter 25?", "o": ["1,55 %", "1,8 %", "1,3 %", "2,4 %"], "c": 0, "e": "Ab dem zweiten Kind gibt es 0,25 Punkte Abschlag je Kind. 1,8 % − 0,25 % = 1,55 %."}, {"q": "Welchen PV-Satz zahlt eine Arbeitnehmerin mit drei Kindern unter 25?", "o": ["1,3 %", "1,05 %", "1,55 %", "1,8 %"], "c": 0, "e": "Für das zweite und dritte Kind gibt es je 0,25 Punkte Abschlag. 1,8 % − 0,5 % = 1,3 %."}, {"q": "Warum zahlt Mia Schulz (17 Jahre, kinderlos) in der PV nur 1,8 %?", "o": ["Sie ist jünger als 23 Jahre", "Auszubildende sind von der PV befreit", "Ihr Entgelt liegt unter 325 €", "Der Arbeitgeber zahlt ihren Zuschlag"], "c": 0, "e": "Der Kinderlosenzuschlag gilt erst ab dem 23. Geburtstag. Mia ist nicht befreit, und mit 1.150 € liegt sie über der Geringverdienergrenze von 325 €."}, {"q": "Was bedeutet die Beitragsbemessungsgrenze?", "o": ["Entgelt über der Grenze ist beitragsfrei", "Wer mehr verdient, ist nicht mehr versichert", "Unter der Grenze zahlt der Arbeitgeber allein", "Über der Grenze verdoppeln sich die Beiträge"], "c": 0, "e": "Die Beiträge werden höchstens von der Grenze berechnet, der übersteigende Teil ist beitragsfrei. Die Versicherung selbst bleibt bestehen."}, {"q": "Ein Bereichsleiter verdient 6.200 € im Monat. Wie hoch ist sein KV-Anteil (8,75 %)?", "o": ["508,59 €", "542,50 €", "576,60 €", "470,88 €"], "c": 0, "e": "Der KV-Beitrag wird nur bis zur BBG von 5.812,50 € berechnet. 5.812,50 € × 8,75 % = 508,59 €. 542,50 € wären 8,75 % von 6.200 €."}, {"q": "Ab welchem Jahresentgelt dürfen Arbeitnehmer 2026 in eine private Krankenversicherung wechseln?", "o": ["Über 77.400 €", "Über 69.750 €", "Über 101.400 €", "Über 47.400 €"], "c": 0, "e": "Die allgemeine Versicherungspflichtgrenze beträgt 77.400 €. 69.750 € ist die BBG der KV, 101.400 € die BBG der RV."}, {"q": "Wie hoch ist der PV-Anteil von Lisa (26 Jahre, kinderlos) bei 3.950,00 €?", "o": ["94,80 €", "71,10 €", "61,23 €", "142,20 €"], "c": 0, "e": "Lisa zahlt mit Kinderlosenzuschlag 2,4 %. 3.950,00 € × 2,4 % = 94,80 €. 71,10 € ist der AG-Anteil mit 1,8 %."}, {"q": "Wie hoch ist der gesamte SV-Anteil von Lisa Wagner?", "o": ["859,13 €", "835,43 €", "1.694,56 €", "814,18 €"], "c": 0, "e": "345,63 € + 94,80 € + 367,35 € + 51,35 € = 859,13 €. 835,43 € ist ihr AG-Anteil, 814,18 € der SV-Anteil von Jonas."}, {"q": "Wie hoch ist das Nettoentgelt von Lisa Wagner im November 2026?", "o": ["2.532,52 €", "2.578,62 €", "2.891,79 €", "3.090,87 €"], "c": 0, "e": "3.950,00 € − 558,35 € Steuern − 859,13 € SV = 2.532,52 €. 2.578,62 € ergäbe sich, wenn man die Kirchensteuer vergisst."}, {"q": "Welche Lohnsteuer wird für Jonas (3.895,63 €, Steuerklasse III, zwei Kinder) laut Tabelle einbehalten?", "o": ["189,66 €", "509,16 €", "0,00 €", "923,75 €"], "c": 0, "e": "Die passende Tabelle weist 189,66 € aus. In Steuerklasse I wären es 509,16 €, in Klasse V 923,75 €."}, {"q": "Wie hoch sind die Arbeitgeberkosten für Lisa Wagner im November 2026?", "o": ["4.785,43 €", "3.950,00 €", "4.809,13 €", "5.644,56 €"], "c": 0, "e": "Arbeitgeberkosten = Brutto + AG-Anteil = 3.950,00 € + 835,43 € = 4.785,43 €. 4.809,13 € entstünde, wenn man fälschlich den AN-Anteil addiert."}, {"q": "In welcher Reihenfolge läuft die monatliche Entgeltabrechnung ab?", "o": ["Abrechnen, Gehaltsliste, melden, überweisen, buchen", "Buchen, abrechnen, überweisen, melden, Gehaltsliste", "Überweisen, abrechnen, buchen, Gehaltsliste, melden", "Gehaltsliste, buchen, abrechnen, melden, überweisen"], "c": 0, "e": "Zuerst werden die Abrechnungen erstellt und in der Gehaltsliste summiert. Die Summen werden an Krankenkasse und Finanzamt gemeldet, danach überwiesen und zum Schluss gebucht."}, {"q": "Wie viel überweist Nordstern laut Gehaltsliste November an das Finanzamt?", "o": ["748,01 €", "701,91 €", "1.916,54 €", "558,35 €"], "c": 0, "e": "Lohnsteuer 701,91 € plus Kirchensteuer 46,10 € ergibt 748,01 €. Soli fällt nicht an."}, {"q": "Wie viel überweist Nordstern laut Gehaltsliste November insgesamt an die Krankenkassen?", "o": ["3.819,12 €", "1.916,54 €", "1.902,58 €", "6.331,08 €"], "c": 0, "e": "An die Krankenkassen gehen AN-Anteile und AG-Anteile, also 1.916,54 € + 1.902,58 € = 3.819,12 €. 6.331,08 € ist die Summe der Nettoentgelte."}, {"q": "Wie lautet der Buchungssatz für die Überweisung der SV-Beiträge am 26.11.2026?", "o": ["2640 SV-Vorauszahlung an 2800 Bank", "2800 Bank an 2640 SV-Vorauszahlung", "6400 AG-Anteil an 2800 Bank", "4830 Verbindlichkeiten an 2800 Bank"], "c": 0, "e": "Die Vorauszahlung erhöht das aktive Bestandskonto 2640 im Soll und mindert die Bank im Haben."}, {"q": "Auf welches Konto bucht Nordstern den Arbeitgeberanteil für die kaufmännische Auszubildende Mia?", "o": ["6410 AG-Anteil SV Gehaltsbereich", "6400 AG-Anteil SV Lohnbereich", "6360 Vergütungen an Auszubildende", "6200 Löhne (gewerbliche Beschäftigte)"], "c": 0, "e": "Mia ist kaufmännische Auszubildende und gehört zum Gehaltsbereich. Deshalb wird ihr AG-Anteil wie der von Lisa auf 6410 gebucht."}, {"q": "Auf welchem Konto bucht Nordstern die einbehaltene Lohnsteuer und Kirchensteuer?", "o": ["4830 Sonst. Verb. gegenüber Finanzbehörden", "4840 Verb. gegenüber SV-Trägern", "2640 SV-Vorauszahlung (Bestandskonto)", "6300 Gehälter und Zulagen (Aufwand)"], "c": 0, "e": "Die Steuern schuldet Nordstern dem Finanzamt, deshalb stehen sie auf 4830. Ein Konto 4840 gibt es im verwendeten Westermann-IKR nicht."}, {"q": "Wann gilt ein Entgelt als marktgerecht?", "o": ["Wenn es mit dem Entgelt anderer Betriebe mithalten kann", "Wenn es genau dem gesetzlichen Mindestlohn entspricht", "Wenn es nur nach der Stückzahl berechnet wird", "Wenn es jedes Jahr um den gleichen Betrag steigt"], "c": 0, "e": "Marktgerecht heißt, dass der Betrieb im Vergleich zu anderen Betrieben mithalten kann. Sonst wandern Fachkräfte zu besser zahlenden Betrieben ab (Beiderwieden & Stickdorn, 2026)."}, {"q": "Unter welchem zweiten Namen ist das Lohngruppenverfahren bekannt?", "o": ["Katalogverfahren", "Stufenwertverfahren", "Punktbewertungsverfahren", "Rangreihenverfahren"], "c": 0, "e": "Das Lohngruppenverfahren heißt auch Katalogverfahren. Der Tarifvertrag beschreibt Entgeltgruppen mit Beispielen wie in einem Katalog, und jede Stelle wird einer Gruppe zugeordnet."}, {"q": "Was geschieht im Rangfolgeverfahren?", "o": ["Alle Stellen werden als Ganzes von leicht bis schwer geordnet", "Jedes Merkmal einer Stelle bekommt eine eigene Punktzahl", "Die Stückzahl jeder Person wird über einen Monat gezählt", "Die Stellen werden nach dem Alter der Inhaber geordnet"], "c": 0, "e": "Das Rangfolgeverfahren ist summarisch. Man vergleicht die Stellen als Ganzes und bringt sie in eine Reihenfolge nach ihrer Schwierigkeit."}, {"q": "Die Arbeitsbewertung bewertet die Stelle. Womit wird die persönliche Leistung einer Person beurteilt?", "o": ["Mit der Leistungsbewertung", "Mit der analytischen Stellenbewertung", "Mit dem Lohngruppenverfahren", "Mit dem Rangfolgeverfahren"], "c": 0, "e": "Stelle und Person werden getrennt bewertet. Die Leistungsbewertung beurteilt den Menschen, Leistungslohn wie Akkord oder Prämie setzt das Ergebnis in Geld um."}, {"q": "Lisa Wagner bekommt ein festes Gehalt. Was gilt, wenn ein Monat 23 statt 20 Arbeitstage hat?", "o": ["Das Gehalt bleibt gleich hoch", "Das Gehalt steigt um drei Tagessätze", "Das Gehalt sinkt im kurzen Monat anteilig", "Das Gehalt wird nach Stunden neu berechnet"], "c": 0, "e": "Das Gehalt ist ein fester Monatsbetrag. Es hängt nicht davon ab, wie viele Arbeitstage der Monat hat."}, {"q": "Viele Tarifverträge sprechen heute einheitlich von Entgelt. Warum trennt die Buchhaltung trotzdem Lohn und Gehalt?", "o": ["Der IKR hat eigene Konten für Löhne und Gehälter", "Lohn ist steuerfrei, Gehalt ist steuerpflichtig", "Gehälter werden in der Buchhaltung nicht erfasst", "Löhne werden nur bei Minijobs gezahlt"], "c": 0, "e": "Im Industriekontenrahmen gibt es eigene Aufwandskonten, 6200 für Löhne und 6300 für Gehälter. Deshalb bleibt die Unterscheidung für die Buchung wichtig."}, {"q": "Warum ist Zeitlohn bei der Instandhaltung der Maschinen sinnvoll?", "o": ["Die Arbeitsmenge lässt sich schlecht im Voraus messen", "Instandhaltung ist vom Mindestlohn ausgenommen", "Instandhaltung wiederholt sich jeden Tag genau gleich", "Für Instandhaltung gibt es feste Vorgabezeiten"], "c": 0, "e": "Reparaturen sind jedes Mal anders, ihre Menge kann man schlecht zählen. Sorgfalt ist wichtiger als Tempo, deshalb passt Zeitlohn."}, {"q": "Wie setzen viele Betriebe beim Zeitlohn trotzdem einen Leistungsanreiz?", "o": ["Mit einer Leistungszulage oder einer Prämie", "Mit einer Kürzung des Entgelts bei Krankheit", "Mit einem Verzicht auf den Tarifvertrag", "Mit einem Wechsel in die Steuerklasse VI"], "c": 0, "e": "Zeitlohn allein bietet keinen direkten Anreiz. Eine Leistungszulage oder Prämie belohnt zusätzlich eine gute Leistung."}, {"q": "Wofür zahlt Nordstern beim Akkord den Akkordzuschlag?", "o": ["Als Ausgleich für die höhere Belastung", "Als Ausgleich für Arbeit in der Nacht", "Als Ersatz für das Weihnachtsgeld", "Als Vorauszahlung auf die Lohnsteuer"], "c": 0, "e": "Akkordarbeit ist anstrengender, weil das Tempo zählt. Der Zuschlag von 20 % auf den Grundlohn gleicht diese Belastung aus."}, {"q": "Was beschreibt die Normalleistung?", "o": ["Die Menge je Stunde bei normalem Tempo", "Die höchste Menge, die je erreicht wurde", "Die Menge eines Beschäftigten im ersten Monat", "Die Menge, die der Betriebsrat vorschreibt"], "c": 0, "e": "Normalleistung ist die Menge, die ein geübter Beschäftigter bei normalem Tempo je Stunde schafft. Sie ergibt sich aus 60 Minuten geteilt durch die Vorgabezeit."}, {"q": "Was wird einem Beschäftigten im Zeitakkord für jedes fertige Stück gutgeschrieben?", "o": ["Die Vorgabezeit", "Die tatsächlich gebrauchte Zeit", "Die anteilige Pausenzeit", "Die durchschnittliche Rüstzeit"], "c": 0, "e": "Im Zeitakkord bekommt man je Stück die Vorgabezeit gutgeschrieben, egal wie lange man wirklich brauchte. Jede Vorgabeminute wird mit dem Minutenfaktor bezahlt."}, {"q": "Wovon hängt der Akkordlohn bei gleichem Stückgeld ab?", "o": ["Von der geschafften Stückzahl", "Von der Zahl der Anwesenheitstage", "Von der Steuerklasse der Person", "Von der Zahl der Kinder"], "c": 0, "e": "Akkord bezahlt die Menge. Bei festem Stückgeld steigt der Lohn mit jeder zusätzlich geschafften Einheit."}, {"q": "Warum eignet sich eine Prämie besonders dort, wo eine Maschine das Tempo vorgibt?", "o": ["Dort bestimmen Sorgfalt und Aufmerksamkeit den Erfolg", "Dort lässt sich überhaupt keine Leistung messen", "Dort ist der gesetzliche Mindestlohn ausgesetzt", "Dort gilt grundsätzlich kein Tarifvertrag"], "c": 0, "e": "Wenn die Maschine das Tempo festlegt, passt Akkord nicht. Eine Prämie kann aber Qualität, Ersparnis oder Termintreue belohnen."}, {"q": "Welche Prämie belohnt eine höhere Stückzahl?", "o": ["Mengenprämie", "Ersparnisprämie", "Terminprämie", "Qualitätsprämie"], "c": 0, "e": "Die Mengenprämie belohnt mehr Stück. Die Ersparnisprämie belohnt geringeren Verbrauch, die Terminprämie Pünktlichkeit, die Qualitätsprämie weniger Ausschuss."}, {"q": "Ein Team in der Lackiererei verbraucht weniger Lack und Strom als geplant. Welche Prämie passt dazu?", "o": ["Ersparnisprämie", "Mengenprämie", "Terminprämie", "Treueprämie"], "c": 0, "e": "Ein geringerer Verbrauch von Material oder Energie wird mit der Ersparnisprämie belohnt (Beiderwieden & Stickdorn, 2026)."}, {"q": "Die Vormontage liefert alle Aufträge pünktlich zum zugesagten Datum. Welche Prämie belohnt das?", "o": ["Terminprämie", "Qualitätsprämie", "Mengenprämie", "Ersparnisprämie"], "c": 0, "e": "Die Terminprämie belohnt die pünktliche Erledigung von Aufträgen."}, {"q": "Wessen Erfolg belohnt eine Erfolgsbeteiligung?", "o": ["Den Erfolg des ganzen Unternehmens", "Die Stückzahl einer einzelnen Person", "Die Qualität eines einzelnen Teams", "Die Pünktlichkeit eines Lieferanten"], "c": 0, "e": "Die Erfolgsbeteiligung knüpft nicht an die Einzelleistung an, sondern an den Erfolg des Unternehmens, zum Beispiel an Gewinn oder Umsatz."}, {"q": "Zu welcher Form der Erfolgsbeteiligung gehört die Provision im Vertrieb?", "o": ["Umsatzbeteiligung", "Kapitalbeteiligung", "Gewinnbeteiligung", "Leistungszulage"], "c": 0, "e": "Die Provision ist ein Prozentsatz vom vermittelten Umsatz. Sie ist deshalb eine Form der Umsatzbeteiligung."}, {"q": "Eine Vorarbeiterin bekommt für ihre Führungsaufgabe monatlich zusätzlich 150 €. Wie heißt dieser Bestandteil?", "o": ["Funktionszulage", "Überstundenzuschlag", "Sonderzahlung", "Provision"], "c": 0, "e": "Eine Zulage wird für eine besondere Art der Arbeit gezahlt. Für eine Führungsaufgabe heißt sie Funktionszulage."}, {"q": "Wie ist der Stand der angekündigten Steuerfreiheit für Überstundenzuschläge im November 2026?", "o": ["Sie ist geplant, aber nicht in Kraft", "Sie gilt seit dem 01.01.2026", "Sie gilt rückwirkend für das Jahr 2025", "Sie wurde nur für Minijobs eingeführt"], "c": 0, "e": "Die Steuerfreiheit ist politisch angekündigt, ein Gesetz gibt es nicht. 2026 sind Überstundenzuschläge voll steuerpflichtig (lohndirekt, 2026)."}, {"q": "Wo ist der gesetzliche Mindestlohn geregelt?", "o": ["Im Mindestlohngesetz", "Im Tarifvertrag der Metallindustrie", "In einer Betriebsvereinbarung", "Im Einkommensteuergesetz"], "c": 0, "e": "Der Anspruch auf den Mindestlohn steht in § 1 MiLoG. Die genaue Höhe legt die Bundesregierung per Verordnung fest, für 2026 und 2027 mit der MiLoV5."}, {"q": "Auf welcher gesetzlichen Grundlage behält der Arbeitgeber bei jeder Lohnzahlung Lohnsteuer ein?", "o": ["§ 38 EStG", "§ 23 SGB IV", "§ 22 MiLoG", "§ 55 SGB XI"], "c": 0, "e": "Nach § 38 EStG wird die Einkommensteuer der Arbeitnehmer durch Abzug vom Arbeitslohn erhoben. Der Arbeitgeber muss sie bei jeder Lohnzahlung einbehalten."}, {"q": "Was kann passieren, wenn der Arbeitgeber die Abzüge falsch berechnet?", "o": ["Er kann für die fehlenden Beträge haften", "Die Beschäftigten tragen den Fehler immer allein", "Die Krankenkasse übernimmt den Fehler", "Nichts, weil die Abzüge nur geschätzt werden"], "c": 0, "e": "Der Arbeitgeber ist verpflichtet, Steuern und Beiträge richtig einzubehalten und abzuführen. Rechnet er falsch, kann er dafür haften."}, {"q": "Mit welcher Probe kontrolliert man eine Entgeltabrechnung?", "o": ["Netto + Steuern + SV-Anteil AN = Brutto", "Netto + SV-Anteil AG = Brutto", "Brutto + Steuern = Arbeitgeberkosten", "Netto − Steuern = SV-Anteil AN"], "c": 0, "e": "Rechnet man alle Abzüge wieder zum Netto dazu, muss das Brutto herauskommen. Bei Lisa ergibt 2.532,52 € + 558,35 € + 859,13 € genau 3.950,00 €."}, {"q": "Welche Steuerklasse ist für Ehepaare gedacht, in denen die Partner ähnlich viel verdienen?", "o": ["IV", "III", "V", "II"], "c": 0, "e": "Bei ähnlichem Einkommen wählen Verheiratete meist IV und IV. Die Kombination III und V lohnt sich, wenn ein Partner deutlich mehr verdient."}, {"q": "Ein Partner hat Steuerklasse III gewählt. Welche Klasse hat der andere Partner, wenn er ebenfalls arbeitet?", "o": ["V", "IV", "I", "VI"], "c": 0, "e": "III und V gehören zusammen. Der Partner mit dem höheren Lohn hat III, der andere V mit einer höheren Lohnsteuer."}, {"q": "Was geschieht mit den ELStAM, wenn eine Beschäftigte heiratet oder aus der Kirche austritt?", "o": ["Der Arbeitgeber bekommt die Änderung elektronisch mitgeteilt", "Sie muss eine Lohnsteuerkarte aus Papier abgeben", "Der Arbeitgeber schätzt die neuen Merkmale selbst", "Die Krankenkasse ändert die Steuerklasse"], "c": 0, "e": "Ändert sich ein Merkmal, stellt das Bundeszentralamt für Steuern die neuen ELStAM bereit und der Arbeitgeber erhält eine Mitteilung (§ 39e EStG)."}, {"q": "Wie hoch ist der Arbeitnehmer-Pauschbetrag 2026?", "o": ["1.230 €", "1.000 €", "1.430 €", "2.460 €"], "c": 0, "e": "Der Arbeitnehmer-Pauschbetrag beträgt 2026 1.230 € im Jahr. Er ist in der Lohnsteuertabelle schon berücksichtigt (BMF, 2025a)."}, {"q": "Was gilt beim Solidaritätszuschlag, wenn die Jahreslohnsteuer knapp über der Freigrenze liegt?", "o": ["Es gilt eine Milderungszone mit geringerem Soli", "Sofort gilt der volle Satz von 5,5 %", "Der Soli entfällt dann vollständig", "Der Arbeitgeber zahlt den Soli allein"], "c": 0, "e": "Damit der Soli nicht sprunghaft steigt, gibt es über der Freigrenze eine Milderungszone. Erst danach gilt der volle Satz von 5,5 % (SolZG 1995)."}, {"q": "Nach welchem Ort richtet sich der Kirchensteuersatz beim Lohnsteuerabzug?", "o": ["Nach der Betriebsstätte des Arbeitgebers", "Nach dem Geburtsort der Beschäftigten", "Nach dem Sitz der Krankenkasse", "Nach dem Wohnort der Geschäftsführung"], "c": 0, "e": "Beim Lohnsteuerabzug zählt die Betriebsstätte. Für Nordstern in Norderstedt gilt deshalb der Satz von Schleswig-Holstein mit 9 % (Lohn-Info, 2026)."}, {"q": "Warum senken Kinderfreibeträge die monatliche Lohnsteuer nicht?", "o": ["Weil die Eltern Kindergeld bekommen", "Weil Kinder erst ab 18 Jahren zählen", "Weil der Arbeitgeber die Kinder nicht kennt", "Weil nur verheiratete Eltern sie erhalten"], "c": 0, "e": "Die Familie wird während des Jahres über das Kindergeld entlastet. Die Kinderfreibeträge wirken in der Abrechnung nur auf Soli und Kirchensteuer (§ 51a Abs. 2a EStG)."}, {"q": "Wer muss Kirchensteuer zahlen?", "o": ["Mitglieder einer steuererhebenden Kirche", "Alle Beschäftigten in Schleswig-Holstein", "Nur Beschäftigte mit Steuerklasse III", "Nur Beschäftigte, die älter als 25 sind"], "c": 0, "e": "Kirchensteuer zahlen nur Mitglieder einer Religionsgemeinschaft, die Kirchensteuer erhebt, zum Beispiel der evangelischen oder katholischen Kirche."}, {"q": "Welcher Zweig der Sozialversicherung zahlt bei Erwerbsminderung?", "o": ["Rentenversicherung", "Arbeitslosenversicherung", "Pflegeversicherung", "Krankenversicherung"], "c": 0, "e": "Die Rentenversicherung zahlt im Alter und bei Erwerbsminderung. Die Krankenversicherung zahlt bei Krankheit, die Pflegeversicherung bei Pflegebedürftigkeit."}, {"q": "Welcher Zusatzbeitrag zur Krankenversicherung gilt in der Praxis für eine Beschäftigte?", "o": ["Der Satz ihrer eigenen Krankenkasse", "Immer genau der Durchschnitt von 2,9 %", "Der Satz der Kasse des Arbeitgebers", "Der niedrigste Satz in Deutschland"], "c": 0, "e": "Jede Kasse legt ihren Zusatzbeitrag selbst fest. Im Kurs rechnen wir vereinfacht für alle mit dem Durchschnitt von 2,9 % (BMG, 2025)."}, {"q": "Wie hoch ist 2026 der gesamte Arbeitnehmeranteil zur Sozialversicherung für eine Person mit Kind (Zusatzbeitrag 2,9 %)?", "o": ["21,15 %", "20,75 %", "42,30 %", "18,60 %"], "c": 0, "e": "KV 8,75 % + PV 1,8 % + RV 9,3 % + AV 1,3 % = 21,15 %. Der Arbeitgeber zahlt noch einmal denselben Satz, zusammen 42,30 %."}, {"q": "Welchen PV-Satz zahlt ein Arbeitnehmer mit fünf Kindern unter 25 Jahren?", "o": ["0,8 %", "1,05 %", "0,55 %", "1,8 %"], "c": 0, "e": "Vom 2. bis zum 5. Kind sinkt der Satz um je 0,25 Punkte. 1,8 % − 4 × 0,25 % = 0,8 % (§ 55 Abs. 3 SGB XI)."}, {"q": "Warum gelten in Sachsen andere Anteile zur Pflegeversicherung?", "o": ["Wegen des Buß- und Bettags als Feiertag", "Wegen eines höheren Zusatzbeitrags", "Weil dort keine Bemessungsgrenze gilt", "Weil dort keine Kirchensteuer erhoben wird"], "c": 0, "e": "Sachsen hat den Buß- und Bettag als Feiertag behalten. Dafür zahlen Arbeitnehmer dort einen höheren und Arbeitgeber einen niedrigeren PV-Anteil (Barmer, 2026a)."}, {"q": "Bei welchem Monatsentgelt beginnt 2026 der Übergangsbereich?", "o": ["Bei 603,01 €", "Bei 556,01 €", "Bei 325,01 €", "Bei 2.000,01 €"], "c": 0, "e": "Bis 603 € liegt ein Minijob vor. Der Übergangsbereich reicht von 603,01 € bis 2.000,00 € im Monat (§ 20 Abs. 2 SGB IV)."}, {"q": "Was unterscheidet die Versicherungspflichtgrenze von der Beitragsbemessungsgrenze?", "o": ["Sie entscheidet über den Wechsel in die private KV", "Sie begrenzt die Höhe der Rentenbeiträge", "Sie gilt nur für Auszubildende", "Sie ist dasselbe wie die Minijob-Grenze"], "c": 0, "e": "Die Versicherungspflichtgrenze von 77.400 € im Jahr entscheidet, ob man privat krankenversichert sein darf. Die Beitragsbemessungsgrenze begrenzt dagegen die Beiträge (TK, 2026a)."}, {"q": "Wie hoch ist 2026 die jährliche Beitragsbemessungsgrenze in der Renten- und Arbeitslosenversicherung?", "o": ["101.400 €", "69.750 €", "77.400 €", "96.600 €"], "c": 0, "e": "In RV und AV gilt 2026 bundeseinheitlich 101.400 € im Jahr, also 8.450,00 € im Monat. 69.750 € ist die Grenze in KV und PV (TK, 2026a)."}, {"q": "Warum zahlt Nordstern keine Umlage U1?", "o": ["U1 gilt nur für Betriebe bis 30 Beschäftigte", "U1 wurde zum 01.01.2026 abgeschafft", "U1 zahlen allein die Beschäftigten selbst", "U1 gilt nur für Betriebe in Sachsen"], "c": 0, "e": "Die Umlage U1 für die Entgeltfortzahlung bei Krankheit zahlen nur kleine Betriebe mit höchstens 30 Beschäftigten. Nordstern hat 240 Beschäftigte."}, {"q": "Welche Kontenart ist 4830 Sonstige Verbindlichkeiten gegenüber Finanzbehörden?", "o": ["Passives Bestandskonto", "Aufwandskonto der Klasse 6", "Aktives Bestandskonto", "Ertragskonto der Klasse 5"], "c": 0, "e": "4830 zeigt eine Schuld gegenüber dem Finanzamt. Schulden stehen auf passiven Bestandskonten, Zugänge im Haben."}, {"q": "Wie wirkt der Arbeitgeberanteil zur Sozialversicherung in der Buchhaltung?", "o": ["Als zusätzlicher Personalaufwand", "Als Minderung des Bruttogehalts", "Als Forderung an die Beschäftigten", "Als Teil der Lohnsteuer"], "c": 0, "e": "Der AG-Anteil ist Aufwand des Betriebs zusätzlich zum Brutto. Er wird auf 6400 oder 6410 gebucht (Westermann Gruppe, 2025)."}, {"q": "Warum braucht Nordstern im Bruttoverfahren mit SV-Vorauszahlung kein Verbindlichkeitskonto für SV-Träger?", "o": ["Die Beiträge sind vor der Gehaltsbuchung bezahlt", "SV-Beiträge werden gar nicht gebucht", "Die Beiträge gehen an das Finanzamt", "Der Arbeitgeber zahlt keine SV-Beiträge"], "c": 0, "e": "Die Beiträge werden schon am drittletzten Bankarbeitstag auf 2640 vorausgezahlt. Bei der Gehaltsbuchung wird nur noch gegen 2640 verrechnet, eine Schuld bleibt nicht offen."}, {"q": "Eine angelernte Monteurin in EG 5 verdient 3.250 € im Monat. Welcher Stundenlohn ergibt sich bei Nordstern?", "o": ["21,35 €", "18,57 €", "21,67 €", "20,31 €"], "c": 0, "e": "3.250 € ÷ 152,25 Std. = 21,346 €, gerundet 21,35 €. Der Teiler 152,25 ergibt sich aus 35 Std. × 4,35 Wochen."}, {"q": "Um wie viel Euro liegt der Stundenlohn einer Abteilungsleitung (EG 13, 5.300 €) über dem einer Sachbearbeitung (EG 9, 3.950 €)?", "o": ["8,87 €", "9,13 €", "7,87 €", "8,55 €"], "c": 0, "e": "EG 13 ergibt 5.300 € ÷ 152,25 = 34,81 €, EG 9 ergibt 25,94 €. Der Abstand beträgt 34,81 € − 25,94 € = 8,87 €."}, {"q": "Wie hoch ist das Stückgeld für einen Rahmen mit 15 Minuten Vorgabezeit, wenn der Akkordrichtsatz 25,20 € beträgt?", "o": ["6,30 €", "6,00 €", "5,25 €", "6,60 €"], "c": 0, "e": "Normalleistung 60 ÷ 15 = 4 Stück. Stückgeld 25,20 € ÷ 4 = 6,30 €."}, {"q": "Ein Monteur montiert in 7,5 Stunden 33 Rahmen (Vorgabezeit 15 Minuten, Minutenfaktor 0,40 €). Wie hoch ist sein Lohn im Zeitakkord?", "o": ["198,00 €", "180,00 €", "150,00 €", "132,00 €"], "c": 0, "e": "33 × 15 Min. × 0,40 € = 198,00 €. Bei Normalleistung wären es 7,5 × 24,00 € = 180,00 €, die Garantie läge bei 150,00 €."}, {"q": "Welcher Leistungsgrad ergibt sich bei 33 Rahmen in 7,5 Stunden (Normalleistung 4 Rahmen je Stunde)?", "o": ["110 %", "90,9 %", "82,5 %", "132 %"], "c": 0, "e": "Soll sind 7,5 × 4 = 30 Rahmen. Leistungsgrad 33 ÷ 30 × 100 = 110 %."}, {"q": "Ein geübter Monteur braucht für einen Rahmen tatsächlich nur 10 statt 15 Minuten. Wie hoch ist sein Stundenverdienst im Stückgeldakkord (6,00 € je Stück)?", "o": ["36,00 €", "30,00 €", "24,00 €", "40,00 €"], "c": 0, "e": "In 60 Minuten schafft er 60 ÷ 10 = 6 Rahmen. 6 × 6,00 € = 36,00 €, das entspricht einem Leistungsgrad von 150 %."}, {"q": "Ab wie vielen Rahmen an einem 8-Stunden-Tag verdient ein Monteur im Akkord mehr als die Garantie von 20,00 € je Stunde (Stückgeld 6,00 €)?", "o": ["Ab 27 Rahmen", "Ab 32 Rahmen", "Ab 26 Rahmen", "Ab 20 Rahmen"], "c": 0, "e": "Die Garantie beträgt 8 × 20,00 € = 160,00 €. 160,00 € ÷ 6,00 € = 26,67. Erst mit 27 Rahmen (162,00 €) liegt der Akkordlohn darüber."}, {"q": "Ein Monteur montiert an einem 8-Stunden-Tag nur 24 Rahmen, weil Material fehlte (Stückgeld 6,00 €). Was zahlt Nordstern für den Tag?", "o": ["160,00 €", "144,00 €", "192,00 €", "111,20 €"], "c": 0, "e": "Rechnerisch ergeben sich 24 × 6,00 € = 144,00 €. Die Garantie sichert 8 × 20,00 € = 160,00 €, also wird dieser Betrag gezahlt."}, {"q": "Die Lackiererei spart im Quartal 4.000 € Lack. 25 % der Ersparnis gehen zu gleichen Teilen an 10 Beschäftigte. Wie hoch ist die Prämie je Person?", "o": ["100,00 €", "400,00 €", "250,00 €", "40,00 €"], "c": 0, "e": "25 % von 4.000 € sind 1.000 €. Verteilt auf 10 Personen ergibt das 100,00 € je Person als Ersparnisprämie."}, {"q": "Die Nordstern Service GmbH verteilt 27.000 € Gewinnbeteiligung gleichmäßig auf ihre 18 Beschäftigten. Wie viel erhält jede Person?", "o": ["1.500 €", "1.350 €", "2.700 €", "1.000 €"], "c": 0, "e": "27.000 € ÷ 18 = 1.500 €. Der Betrag ist steuer- und beitragspflichtig und wird wie eine Sonderzahlung abgerechnet."}, {"q": "Svea Lorenzen aus dem Vertrieb erhält 3.950 € Gehalt und 1,5 % Provision auf 120.000 € vermittelten Umsatz. Wie hoch ist ihr Bruttoentgelt in diesem Monat?", "o": ["5.750,00 €", "5.450,00 €", "4.130,00 €", "5.135,00 €"], "c": 0, "e": "Provision 120.000 € × 1,5 % = 1.800,00 €. Brutto 3.950,00 € + 1.800,00 € = 5.750,00 €."}, {"q": "Nordstern möchte in der Endkontrolle mehr Sorgfalt belohnen, ohne Zeitdruck zu erzeugen. Welche Lösung passt am besten?", "o": ["Zeitlohn mit Qualitätsprämie", "Reiner Stückgeldakkord", "Zeitakkord mit kurzer Vorgabezeit", "Provision auf den Umsatz"], "c": 0, "e": "In der Endkontrolle zählt Sorgfalt. Zeitlohn vermeidet Hetze, die Qualitätsprämie belohnt wenige übersehene Fehler."}, {"q": "Dr. Katrin Lorenz will alle 240 Beschäftigten am guten Jahresergebnis 2026 beteiligen. Welche Form passt?", "o": ["Gewinnbeteiligung", "Mengenprämie", "Stückgeldakkord", "Erschwerniszulage"], "c": 0, "e": "Eine Beteiligung am Jahresergebnis des ganzen Unternehmens ist eine Gewinnbeteiligung, also eine Form der Erfolgsbeteiligung."}, {"q": "Ein Helfer in EG 3 (19,05 € je Stunde) leistet 6 Überstunden mit 25 % Zuschlag. Wie hoch sind Überstundenvergütung und Zuschlag zusammen?", "o": ["142,88 €", "114,30 €", "142,87 €", "133,35 €"], "c": 0, "e": "Vergütung 6 × 19,05 € = 114,30 €. Zuschlag 114,30 € × 25 % = 28,575 €, gerundet 28,58 €. Zusammen 142,88 €."}, {"q": "Eine Teilzeitkraft der Nordstern Service GmbH arbeitet 30 Wochenstunden. Welches Monatsentgelt braucht sie ab 01.01.2027 mindestens (4,35 Wochen je Monat)?", "o": ["1.905,30 €", "1.813,95 €", "1.752,00 €", "2.540,40 €"], "c": 0, "e": "30 × 4,35 = 130,5 Stunden im Monat. 130,5 × 14,60 € = 1.905,30 €. 1.813,95 € wäre der Wert mit dem Mindestlohn 2026."}, {"q": "Welches Monatsentgelt müsste ein Betrieb mit 35-Stunden-Woche (152,25 Stunden im Monat) 2026 mindestens zahlen?", "o": ["2.116,28 €", "2.418,60 €", "2.222,85 €", "1.951,85 €"], "c": 0, "e": "152,25 × 13,90 € = 2.116,275 €, gerundet 2.116,28 €. Alle Entgeltgruppen von Nordstern liegen deutlich darüber."}, {"q": "Leon Becker (19 Jahre, 2. Ausbildungsjahr, 1.220 €) fragt, ob er Anspruch auf 13,90 € je Stunde hat. Was ist richtig?", "o": ["Nein, Auszubildende sind ausgenommen", "Ja, weil er schon volljährig ist", "Ja, ab dem 2. Ausbildungsjahr", "Nein, weil Nordstern einen Tarifvertrag hat"], "c": 0, "e": "Nach § 22 MiLoG haben Auszubildende keinen Anspruch auf den Mindestlohn, auch wenn sie volljährig sind. Für sie gilt die Mindestausbildungsvergütung."}, {"q": "Ein Monteur verdient 3.600 € und bekommt im November zusätzlich 400 € Weihnachtsgeld. Wie hoch ist sein Bruttoentgelt im November?", "o": ["4.000,00 €", "3.600,00 €", "3.200,00 €", "4.400,00 €"], "c": 0, "e": "Das Weihnachtsgeld ist eine Sonderzahlung und gehört zum Brutto. 3.600,00 € + 400,00 € = 4.000,00 €."}, {"q": "Im Stufenwertzahlverfahren erhält eine Stelle für Können 12, Verantwortung 8, Belastung 6 und Umgebungseinflüsse 4 Punkte. Wie viele Punkte hat die Stelle?", "o": ["30 Punkte", "26 Punkte", "24 Punkte", "12 Punkte"], "c": 0, "e": "Im Stufenwertzahlverfahren werden die Punkte der Merkmale addiert. 12 + 8 + 6 + 4 = 30. Die Summe bestimmt die Entgeltgruppe."}, {"q": "Eine Stelle in der Lackiererei wird höher eingestuft, weil dort Lärm und Lackdämpfe auftreten. Welcher Grundsatz wird damit umgesetzt?", "o": ["Anforderungsgerechtigkeit", "Leistungsgerechtigkeit", "Sozialgerechtigkeit", "Marktgerechtigkeit"], "c": 0, "e": "Umgebungseinflüsse sind Anforderungen der Stelle. Eine höhere Einstufung dafür ist anforderungsgerecht."}, {"q": "Nordstern zahlt einer IT-Spezialistin mehr als die Tabelle vorsieht, weil andere Betriebe ihr mehr bieten. Welcher Grundsatz steht dahinter?", "o": ["Marktgerechtigkeit", "Anforderungsgerechtigkeit", "Sozialgerechtigkeit", "Leistungsgerechtigkeit"], "c": 0, "e": "Wer mit anderen Betrieben um Fachkräfte konkurriert, muss marktgerecht zahlen. Sonst wechselt die Spezialistin zu einem anderen Arbeitgeber."}, {"q": "Zwei Prüfer in der Qualitätssicherung (EG 7, Zeitlohn) prüfen im November unterschiedlich viele Räder. Was gilt für ihr Grundentgelt?", "o": ["Es ist gleich hoch", "Der schnellere Prüfer bekommt automatisch mehr", "Der langsamere Prüfer bekommt weniger", "Es richtet sich nach der Zahl der Räder"], "c": 0, "e": "Im Zeitlohn wird die Zeit bezahlt, nicht die Menge. Beide Prüfer erhalten in EG 7 3.600 € Grundentgelt."}, {"q": "Merve Celik (Einkauf, 3.900,00 €, Steuerklasse I, kinderlos, katholisch) hat laut Tabellenauszug 500,16 € Lohnsteuer. Wie hoch ist ihre Kirchensteuer?", "o": ["45,01 €", "45,02 €", "40,01 €", "27,51 €"], "c": 0, "e": "500,16 € × 9 % = 45,0144 €. Cent-Bruchteile werden abgerundet, also 45,01 €."}, {"q": "Merve Celik hat 3.900,00 € Brutto, Steuern von 545,17 € und einen SV-Anteil von 848,25 €. Wie hoch ist ihr Nettoentgelt?", "o": ["2.506,58 €", "3.051,75 €", "3.354,83 €", "2.551,59 €"], "c": 0, "e": "3.900,00 € − 545,17 € − 848,25 € = 2.506,58 €. 2.551,59 € entsteht, wenn man die Kirchensteuer vergisst."}, {"q": "Die Ehefrau eines Monteurs hat Steuerklasse V und verdient 3.950,00 €. Welche Lohnsteuer weist der Tabellenauszug aus?", "o": ["928,16 €", "512,25 €", "972,41 €", "192,16 €"], "c": 0, "e": "In der Zeile 3.950,00 € und der Spalte V steht 928,16 €. 972,41 € gehört zu Klasse VI, 192,16 € zu Klasse III."}, {"q": "Eine 28-jährige kinderlose Monteurin in EG 5 verdient 3.250,00 €. Wie hoch ist ihr PV-Anteil?", "o": ["78,00 €", "58,50 €", "19,50 €", "117,00 €"], "c": 0, "e": "Kinderlos ab 23 bedeutet 2,4 %. 3.250 € × 2,4 % = 78,00 €. 58,50 € wäre der Anteil mit 1,8 %."}, {"q": "Ein Helfer in EG 3 (2.900,00 €) hat ein Kind. Wie hoch ist sein SV-Anteil insgesamt?", "o": ["613,35 €", "630,75 €", "1.226,70 €", "507,50 €"], "c": 0, "e": "KV 253,75 € + PV 52,20 € + RV 269,70 € + AV 37,70 € = 613,35 €. 630,75 € würde sich mit dem Kinderlosenzuschlag ergeben."}, {"q": "Ein Vertriebsleiter verdient 7.000,00 € im Monat. Wie hoch ist sein Arbeitnehmeranteil zur Rentenversicherung?", "o": ["651,00 €", "540,56 €", "785,85 €", "1.302,00 €"], "c": 0, "e": "7.000 € liegt unter 8.450,00 €, also 7.000 € × 9,3 % = 651,00 €. 540,56 € wäre fälschlich von 5.812,50 € gerechnet."}, {"q": "Leon Becker (1.220,00 €, 19 Jahre, kinderlos, keine Kirche) zahlt keine Lohnsteuer. Wie hoch ist sein Netto?", "o": ["961,97 €", "954,65 €", "1.220,00 €", "1.113,25 €"], "c": 0, "e": "SV-Anteil KV 106,75 € + PV 21,96 € + RV 113,46 € + AV 15,86 € = 258,03 €. Netto 1.220,00 € − 258,03 € = 961,97 €. Unter 23 gibt es keinen Kinderlosenzuschlag."}, {"q": "Welche Arbeitgeberkosten entstehen für eine kinderlose Monteurin in EG 5 (3.250,00 €)?", "o": ["3.937,38 €", "3.956,88 €", "3.250,00 €", "3.993,63 €"], "c": 0, "e": "AG-Anteil KV 284,38 € + PV 58,50 € + RV 302,25 € + AV 42,25 € = 687,38 €. Kosten 3.250,00 € + 687,38 € = 3.937,38 €. Der Arbeitgeber zahlt in der PV nur 1,8 %."}, {"q": "Ein Beschäftigter mit 3.600 € Brutto wechselt zu einer Kasse mit 2,5 % statt 2,9 % Zusatzbeitrag. Um wie viel sinkt sein KV-Anteil im Monat?", "o": ["7,20 €", "14,40 €", "3,60 €", "0,40 €"], "c": 0, "e": "Der Zusatzbeitrag sinkt um 0,4 Punkte, davon trägt er die Hälfte, also 0,2 %. 3.600 € × 0,2 % = 7,20 €."}, {"q": "Wie viel zahlt Nordstern laut Gehaltsliste November insgesamt an Rentenversicherungsbeiträgen (AN und AG)?", "o": ["1.673,18 €", "836,59 €", "1.916,54 €", "1.694,56 €"], "c": 0, "e": "Die AN-Anteile zur RV betragen 836,59 €, die AG-Anteile ebenso. Zusammen 2 × 836,59 € = 1.673,18 €."}, {"q": "Wie viel fließt für November insgesamt vom Bankkonto ab (26.11., 30.11. und 10.12.)?", "o": ["10.898,21 €, genau die Arbeitgeberkosten", "8.995,63 €, genau das Bruttoentgelt", "6.331,08 €, genau die Auszahlung", "12.814,75 €, Kosten plus SV-Anteil AN"], "c": 0, "e": "3.819,12 € + 6.331,08 € + 748,01 € = 10.898,21 €. Das sind Brutto 8.995,63 € plus AG-Anteil 1.902,58 €, also die Arbeitgeberkosten."}, {"q": "Welcher Saldo steht auf Konto 2640 nach Buchung 1 (26.11.) und Buchung 2 (30.11.), aber vor Buchung 3?", "o": ["1.902,58 € im Soll", "1.916,54 € im Soll", "3.819,12 € im Haben", "0,00 €"], "c": 0, "e": "Soll 3.819,12 € minus Haben 1.916,54 € ergibt 1.902,58 € im Soll. Erst Buchung 3 mit dem AG-Anteil gleicht das Konto aus."}, {"q": "Wie lautet die Einzelbuchung der Lohnzahlung für Jonas Petersen am 30.11.?", "o": ["6200 3.895,63 € an 2800 2.891,79 €, 4830 189,66 €, 2640 814,18 €", "6300 3.895,63 € an 2800 2.891,79 €, 4830 189,66 €, 2640 814,18 €", "6200 2.891,79 € an 2800 2.891,79 €, 4830 189,66 €, 2640 814,18 €", "6200 3.895,63 € an 2800 2.891,79 €, 4830 1.003,84 €"], "c": 0, "e": "Jonas ist gewerblich, sein Brutto ist Aufwand auf 6200. Netto geht an die Bank, Steuern auf 4830, der SV-Anteil wird mit der Vorauszahlung auf 2640 verrechnet."}, {"q": "Wie bucht Nordstern den Arbeitgeberanteil für Jonas Petersen (823,92 €)?", "o": ["6400 an 2640", "6410 an 2640", "6400 an 2800", "2640 an 6400"], "c": 0, "e": "Der AG-Anteil im Lohnbereich ist Aufwand auf 6400. Er wird gegen die Vorauszahlung auf 2640 gebucht, weil das Geld schon am 26.11. überwiesen wurde."}, {"q": "Leon Becker (Industriekaufmann, 1.220,00 €, Netto 961,97 €, SV-Anteil AN 258,03 €) bekommt seine Vergütung. Wie lautet die Buchung?", "o": ["6360 1.220,00 € an 2800 961,97 €, 2640 258,03 €", "6300 1.220,00 € an 2800 961,97 €, 2640 258,03 €", "6360 1.478,03 € an 2800 1.220,00 €, 2640 258,03 €", "6360 1.220,00 € an 2800 961,97 €, 4830 258,03 €"], "c": 0, "e": "Die Vergütung kaufmännischer Auszubildender ist Aufwand auf 6360. Lohnsteuer fällt nicht an, der SV-Anteil wird gegen 2640 gebucht."}, {"q": "Nordstern würde die SV-Vorauszahlung für November nur für Lisa Wagner buchen. Welcher Betrag stünde in Buchung 1?", "o": ["1.694,56 €", "859,13 €", "835,43 €", "2.532,52 €"], "c": 0, "e": "Vorausgezahlt wird der Gesamtbeitrag aus AN-Anteil 859,13 € und AG-Anteil 835,43 €, also 1.694,56 €."}, {"q": "Die Oktobergehälter 2026 sind ausgezahlt. Welcher Termin gilt für die einbehaltene Lohnsteuer?", "o": ["Anmeldung und Zahlung bis 10.11.2026", "Zahlung am drittletzten Bankarbeitstag im Oktober", "Anmeldung und Zahlung bis 31.10.2026", "Anmeldung und Zahlung bis 10.10.2026"], "c": 0, "e": "Die Lohnsteuer ist bis zum 10. des Folgemonats anzumelden und abzuführen (§ 41a Abs. 1 EStG). Für Oktober ist das der 10.11.2026."}, {"q": "Jonas Petersen hat im Dezember keine Überstunden, sein Brutto beträgt 3.600,00 €. Wie hoch ist sein KV-Anteil?", "o": ["315,00 €", "340,87 €", "262,80 €", "630,00 €"], "c": 0, "e": "3.600 € × 8,75 % = 315,00 €. 262,80 € wäre nur der allgemeine Satz von 7,3 % ohne Zusatzbeitrag."}, {"q": "Angenommen, Lisa Wagner (3.950,00 €) bekommt ein Kind. Wie ändert sich ihr PV-Anteil?", "o": ["Er sinkt um 23,70 € auf 71,10 €", "Er sinkt um 9,88 € auf 84,92 €", "Er bleibt bei 94,80 €", "Er sinkt um 33,57 € auf 61,23 €"], "c": 0, "e": "Mit einem Kind entfällt der Kinderlosenzuschlag. 3.950 € × 1,8 % = 71,10 € statt 94,80 €, also 23,70 € weniger."}, {"q": "Wie hoch wäre die Kirchensteuer von Lisa (Lohnsteuer 512,25 €), wenn die Betriebsstätte in Bayern läge?", "o": ["40,98 €", "46,10 €", "40,99 €", "28,17 €"], "c": 0, "e": "In Bayern beträgt die Kirchensteuer 8 %. 512,25 € × 8 % = 40,98 €, Cent-Bruchteile werden abgerundet."}, {"q": "Ein evangelischer Monteur hat Steuerklasse III und 3.950,00 € (Tabellenauszug ohne Kinder). Wie hoch ist seine Kirchensteuer?", "o": ["17,29 €", "17,30 €", "15,37 €", "46,10 €"], "c": 0, "e": "Laut Tabelle beträgt die Lohnsteuer 192,16 €. 192,16 € × 9 % = 17,2944 €, abgerundet 17,29 €."}, {"q": "Für welche Person der Gehaltsliste November ist der AG-Anteil zur SV genauso hoch wie der AN-Anteil?", "o": ["Mia Schulz", "Lisa Wagner", "Jonas Petersen", "Lisa Wagner und Jonas Petersen"], "c": 0, "e": "Mia zahlt in der PV 1,8 % wie der Arbeitgeber, deshalb sind beide Anteile 243,23 €. Bei Lisa und Jonas weicht der PV-Satz des AN ab."}], "lernen": [{"t": "Bruttoentgelt", "x": "Das vereinbarte Entgelt vor allen Abzügen, also Grundentgelt plus Zulagen, Zuschläge und Überstunden."}, {"t": "Nettoentgelt", "x": "Das Entgelt nach Abzug von Steuern und Arbeitnehmeranteil zur Sozialversicherung. Ohne weitere Abzüge ist es der Auszahlungsbetrag."}, {"t": "Zeitlohn", "x": "Entgelt für die Dauer der Arbeitszeit, unabhängig von der Menge. Bei Angestellten heißt der feste Monatsbetrag Gehalt."}, {"t": "Akkordlohn", "x": "Leistungslohn, der sich nach der geschafften Menge richtet. Es gibt den Stückgeldakkord und den Zeitakkord."}, {"t": "Akkordrichtsatz", "x": "Stundenverdienst bei Normalleistung, also Grundlohn plus Akkordzuschlag. Bei Nordstern 24,00 € je Stunde."}, {"t": "Vorgabezeit", "x": "Zeit, die ein geübter Beschäftigter bei Normalleistung für ein Stück braucht. Beim Lastenrad-Rahmen 15 Minuten."}, {"t": "Leistungsgrad", "x": "Ist-Leistung geteilt durch Normalleistung mal 100. Zeigt in Prozent, wie viel schneller oder langsamer jemand arbeitet."}, {"t": "Prämienlohn", "x": "Grundlohn plus Prämie für eine messbare Mehrleistung, zum Beispiel für Menge, Qualität oder Ersparnis."}, {"t": "Erfolgsbeteiligung", "x": "Beteiligung der Beschäftigten am Erfolg des Unternehmens, zum Beispiel am Gewinn oder am Umsatz."}, {"t": "ELStAM", "x": "Elektronische Lohnsteuerabzugsmerkmale wie Steuerklasse, Kinderfreibeträge und Religion. Der Arbeitgeber ruft sie elektronisch beim Bundeszentralamt für Steuern ab."}, {"t": "Beitragsbemessungsgrenze", "x": "Höchstbetrag, bis zu dem Sozialversicherungsbeiträge berechnet werden. 2026 monatlich 5.812,50 € in KV und PV, 8.450,00 € in RV und AV."}, {"t": "SV-Vorauszahlung (2640)", "x": "Aktives Bestandskonto im IKR. Hier bucht Nordstern die Zahlung der SV-Beiträge vor der Gehaltszahlung, danach wird sie mit den Beiträgen verrechnet."}, {"t": "Auszahlungsbetrag", "x": "Betrag, der tatsächlich überwiesen wird, also Nettoentgelt minus persönliche Abzüge wie VL-Sparbetrag oder Vorschussverrechnung."}, {"t": "Vermögenswirksame Leistungen (VL)", "x": "Sparbeträge, die der Arbeitgeber vom Netto einbehält und langfristig anlegt. Ein Arbeitgeberzuschuss dazu erhöht das Brutto."}, {"t": "Vorschuss", "x": "Vorab gezahlter Teil des Entgelts. Er ist eine Forderung an den Beschäftigten (2650) und wird bei der nächsten Zahlung vom Netto abgezogen."}, {"t": "Steuer-Identifikationsnummer", "x": "Elfstellige, lebenslang gültige Nummer des Bundeszentralamts für Steuern. Mit ihr ruft der Arbeitgeber die ELStAM ab."}, {"t": "Gesundheitsfonds", "x": "Topf der gesetzlichen Krankenversicherung, der Beiträge und Bundeszuschuss sammelt und nach Risiko an die Krankenkassen verteilt."}, {"t": "Beitragsnachweis", "x": "Meldung der Sozialversicherungsbeiträge eines Monats an die Krankenkasse, spätestens zwei Arbeitstage vor der Fälligkeit."}, {"t": "Entgelt", "x": "Entgelt ist jede Gegenleistung des Arbeitgebers für die Arbeit, also Lohn, Gehalt, Ausbildungsvergütung, Zulagen, Zuschläge und Sonderzahlungen (Beiderwieden & Stickdorn, 2026)."}, {"t": "Akkordrichtsatz und Vorgabezeit", "x": "Der Akkordrichtsatz ist Grundlohn plus Akkordzuschlag. Die Vorgabezeit ist die Zeit je Stück bei Normalleistung. Normalleistung = 60 Minuten ÷ Vorgabezeit (Beiderwieden & Stickdorn, 2026)."}, {"t": "Prämie statt Akkord", "x": "Akkord belohnt nur die Menge. Eine Prämie kann jede messbare Mehrleistung belohnen, und der Grundlohn bleibt dabei sicher."}, {"t": "Mindestlohn auf einen Blick", "x": "2026 gilt 13,90 € je Stunde, ab 01.01.2027 gilt 14,60 €. Auszubildende sind ausgenommen (§ 22 MiLoG)."}, {"t": "ELStAM", "x": "Elektronische Lohnsteuerabzugsmerkmale sind Steuerklasse, Kinderfreibeträge, Religion und Freibeträge. Der Arbeitgeber ruft sie mit Steuer-ID und Geburtsdatum elektronisch ab (§ 39e EStG)."}, {"t": "Soli und KiSt auf einen Blick", "x": "Soli 5,5 % der Lohnsteuer, aber erst über 20.350 € Jahreslohnsteuer (Klasse III 40.700 €). Kirchensteuer in Schleswig-Holstein 9 % der Lohnsteuer, Cent-Bruchteile abrunden."}, {"t": "Gesamtsozialversicherungsbeitrag", "x": "Summe der Beiträge zur KV, PV, RV und AV, die Arbeitnehmer und Arbeitgeber zusammen schulden. Der Arbeitgeber zahlt ihn bis zum drittletzten Bankarbeitstag an die Krankenkasse (§ 23 Abs. 1 SGB IV)."}, {"t": "Gesundheitsfonds", "x": "Gemeinsamer Topf der gesetzlichen Krankenversicherung. Er sammelt die Beiträge und einen Bundeszuschuss und verteilt Zuweisungen an die Krankenkassen nach Alter, Geschlecht und Krankheitsrisiko der Versicherten (§ 271 SGB V)."}, {"t": "Warum Jonas mehr Netto hat", "x": "Steuerklasse III senkt die Lohnsteuer stark, Kirchensteuer fällt weg, und der Abschlag für das zweite Kind senkt seinen PV-Beitrag auf 1,55 %."}, {"t": "Fünf Schritte der Entgeltabrechnung", "x": "Abrechnungen erstellen, Summen in der Gehaltsliste erfassen, Summen an Krankenkasse und Finanzamt melden, alle Beträge überweisen, alle Vorgänge buchen."}, {"t": "Vermögenswirksame Leistungen", "x": "Sparbeträge, die der Arbeitgeber vom Netto einbehält und langfristig für die Beschäftigten anlegt. Ein Arbeitgeberzuschuss dazu erhöht das Bruttoentgelt (Beiderwieden & Stickdorn, 2026)."}], "sortier": [{"titel": "Zeit, Menge oder Prämie?", "auftrag": "Ordne jede Aussage der Entgeltform zu, zu der sie bei Nordstern passt.", "kategorien": [{"id": "a", "name": "Zeitlohn"}, {"id": "b", "name": "Akkordlohn"}, {"id": "c", "name": "Prämienlohn"}], "items": [{"text": "Lisa erhält jeden Monat 3.950 € Gehalt", "kat": "a", "expl": "Das Gehalt ist ein fester Monatsbetrag. Es bezahlt die Zeit, nicht die Menge."}, {"text": "Lohn gleich Stundenlohn mal Arbeitsstunden", "kat": "a", "expl": "Das ist die Formel für den Zeitlohn. Bezahlt wird jede Stunde."}, {"text": "Passt bei gefährlicher Arbeit oder hohem Qualitätsanspruch", "kat": "a", "expl": "Ohne Zeitdruck wird sorgfältiger gearbeitet. Darum eignet sich hier Zeitlohn."}, {"text": "Nachteil, es gibt keinen Leistungsanreiz", "kat": "a", "expl": "Wer mehr schafft, verdient nicht mehr. Das ist die Schwäche des Zeitlohns."}, {"text": "Bezahlt wird die Anwesenheitszeit", "kat": "a", "expl": "Beim Zeitlohn zählt die Zeit im Betrieb."}, {"text": "Stückgeld von 6,00 € je montiertem Rahmen", "kat": "b", "expl": "24,00 € ÷ 4 Stück ergeben 6,00 € je Stück. Das ist Stückgeldakkord."}, {"text": "Minutenfaktor 0,40 € bei 15 Minuten Vorgabezeit", "kat": "b", "expl": "24,00 € ÷ 60 ergeben 0,40 € je Minute. Das ist Zeitakkord."}, {"text": "Leistungsgrad 125 % bei 5 statt 4 Stück je Stunde", "kat": "b", "expl": "5 ÷ 4 × 100 = 125 %. Im Akkord steigt der Lohn mit der Menge."}, {"text": "Nur bei gut messbarer, gleichartiger Arbeit", "kat": "b", "expl": "Akkord setzt voraus, dass sich die Menge zählen lässt und die Arbeit sich wiederholt."}, {"text": "Bezahlt wird die Menge, nicht die Zeit", "kat": "b", "expl": "Das ist der Kern des Akkordlohns."}, {"text": "8 % Extra bei höchstens 2 % Nacharbeit", "kat": "c", "expl": "Das ist eine Qualitätsprämie auf den Grundlohn. Sie belohnt gute Qualität."}, {"text": "Grundlohn plus Zusatz für messbare Mehrleistung", "kat": "c", "expl": "Prämienlohn besteht aus einem sicheren Grundlohn und einer Prämie."}, {"text": "Bonus für weniger Materialverbrauch", "kat": "c", "expl": "Das ist eine Ersparnisprämie, eine Art des Prämienlohns."}, {"text": "Extra für pünktlich ausgelieferte Lastenräder", "kat": "c", "expl": "Wer Termine hält, bekommt eine Terminprämie."}, {"text": "Passt, wenn das Ergebnis nur teils beeinflussbar ist", "kat": "c", "expl": "Hier ist reiner Akkord nicht fair. Eine Prämie auf den Grundlohn passt besser."}]}, {"titel": "Steuer oder Sozialversicherung?", "auftrag": "Ordne jeden Abzug und jede Regel der Steuer oder der Sozialversicherung zu.", "kategorien": [{"id": "a", "name": "Steuer ans Finanzamt"}, {"id": "b", "name": "SV an die Krankenkasse"}], "items": [{"text": "Lohnsteuer 512,25 € bei Lisa in Steuerklasse I", "kat": "a", "expl": "Die Lohnsteuer liest Nordstern aus der Tabelle ab. Sie geht an das Finanzamt."}, {"text": "Kirchensteuer 9 % der Lohnsteuer in Schleswig-Holstein", "kat": "a", "expl": "Die Kirchensteuer wird mit der Lohnsteuer an das Finanzamt abgeführt."}, {"text": "Solidaritätszuschlag mit Freigrenze 20.350 €", "kat": "a", "expl": "Der Soli ist eine Steuer. Bei Lisa liegt die Jahreslohnsteuer unter der Freigrenze."}, {"text": "Anmeldung bis zum 10. des Folgemonats", "kat": "a", "expl": "Das ist die Frist für die Lohnsteuer-Anmeldung beim Finanzamt."}, {"text": "Abzug hängt von der Steuerklasse aus den ELStAM ab", "kat": "a", "expl": "Die ELStAM liefern die Steuermerkmale. Sie bestimmen die Lohnsteuer."}, {"text": "Kinderfreibeträge mindern nur Soli und Kirchensteuer", "kat": "a", "expl": "Diese Freibeträge wirken nur bei den Steuern, nicht bei der Lohnsteuer selbst."}, {"text": "Krankenversicherung mit 8,75 % Arbeitnehmeranteil", "kat": "b", "expl": "14,6 % plus 2,9 % Zusatzbeitrag ergeben 17,5 %. Die Hälfte zahlt der Arbeitnehmer."}, {"text": "Pflegeversicherung 2,4 % für Lisa, kinderlos ab 23", "kat": "b", "expl": "Kinderlose ab 23 zahlen 0,6 Punkte mehr. Der Beitrag geht an die Krankenkasse."}, {"text": "Rentenversicherung mit 9,3 % Arbeitnehmeranteil", "kat": "b", "expl": "18,6 % werden je zur Hälfte getragen. Das ist ein SV-Beitrag."}, {"text": "Arbeitslosenversicherung mit 1,3 % Arbeitnehmeranteil", "kat": "b", "expl": "2,6 % werden geteilt. Auch dieser Beitrag geht an die Krankenkasse."}, {"text": "Fällig am drittletzten Bankarbeitstag des Monats", "kat": "b", "expl": "So früh sind die SV-Beiträge fällig, im November 2026 am 26.11."}, {"text": "Bemessungsgrenze KV und PV 5.812,50 € im Monat", "kat": "b", "expl": "Bis zu dieser Grenze werden SV-Beiträge berechnet. Darüber ist das Entgelt beitragsfrei."}]}]}, {"nr": 6, "title": "Personalentwicklung", "date": "30.11.2026", "quiz": [{"q": "Was versteht man unter Personalentwicklung?", "o": ["Alle geplanten Maßnahmen zur Qualifizierung der Beschäftigten", "Alle Maßnahmen zur Suche neuer Beschäftigter am Arbeitsmarkt", "Die Berechnung des Personalbedarfs für das nächste Jahr", "Die monatliche Abrechnung von Löhnen und Gehältern"], "c": 0, "e": "Personalentwicklung umfasst alle geplanten Maßnahmen, mit denen die Qualifikation der Beschäftigten erhalten, verbessert und angepasst wird. Suche, Bedarfsrechnung und Abrechnung sind andere Aufgaben der Personalwirtschaft."}, {"q": "Was umfasst Personalentwicklung im weiten Sinn?", "o": ["Bildung, Förderung und Organisationsentwicklung", "Nur die Fort- und Weiterbildung der Beschäftigten", "Nur die Suche neuer Beschäftigter am Arbeitsmarkt", "Nur die Abrechnung von Seminargebühren"], "c": 0, "e": "Im engen Sinn ist Personalentwicklung nur Fort- und Weiterbildung. Im weiten Sinn umfasst sie Bildung und Förderung und ist eng mit der Organisationsentwicklung verzahnt."}, {"q": "Welches Ziel verfolgen vor allem die Beschäftigten mit Personalentwicklung?", "o": ["Die Senkung der Personalaufwandsquote", "Ein besseres Ansehen des Betriebs als Arbeitgeber", "Beruflicher Aufstieg und höheres Entgelt", "Weniger Kosten für Stellenanzeigen"], "c": 2, "e": "Beschäftigte wollen aufsteigen, mehr verdienen und ihren Arbeitsplatz sichern. Kosten und Ansehen sind Ziele des Betriebs."}, {"q": "Welche drei Bereiche der Personalentwicklung verwenden wir im Kurs?", "o": ["Planung, Beschaffung und Einsatz", "Bildung, Förderung und Organisationsentwicklung", "Ausbildung, Entgelt und Freistellung", "Führung, Motivation und Kontrolle"], "c": 1, "e": "Personalentwicklung im weiten Sinn gliedert sich in Bildung, Förderung und Organisationsentwicklung. Diese Einteilung gilt im ganzen Kurs."}, {"q": "Welches Instrument gehört zum Bereich Förderung?", "o": ["Berufsausbildung zur Industriekauffrau", "Karriereplanung für eine Nachwuchskraft", "Umschulung zur Fachkraft für Lagerlogistik", "Neuer Ablauf für die gesamte Montagelinie"], "c": 1, "e": "Förderung betrifft die Laufbahn einer Person, zum Beispiel Karriereplanung, Job Rotation, Coaching und Mentoring. Ausbildung und Umschulung sind Bildung, ein neuer Gesamtablauf ist Organisationsentwicklung."}, {"q": "Was kennzeichnet die Organisationsentwicklung?", "o": ["Es lernt immer nur eine einzelne Person allein", "Ganze Gruppen und Abläufe verändern sich gemeinsam", "Sie findet ausschließlich in der Berufsschule statt", "Sie ersetzt die Berufsausbildung vollständig"], "c": 1, "e": "Bei der Organisationsentwicklung verändern sich Teams, Strukturen und Abläufe. Beispiele sind Teamentwicklung oder die Einführung teilautonomer Gruppen."}, {"q": "Was soll die Anpassungsfortbildung nach dem BBiG leisten?", "o": ["Die berufliche Handlungsfähigkeit erhalten und anpassen", "Zu einer völlig anderen beruflichen Tätigkeit befähigen", "Die erste berufliche Handlungsfähigkeit vermitteln", "Auf eine Tätigkeit ohne Berufsabschluss vorbereiten"], "c": 0, "e": "Die Anpassungsfortbildung erhält die Handlungsfähigkeit und passt sie an neue Anforderungen an (§ 1 Abs. 4 BBiG). Die Person bleibt auf ihrer Stelle."}, {"q": "Was ist das Kennzeichen einer Aufstiegsfortbildung?", "o": ["Sie hält das Wissen auf der bisherigen Stelle aktuell", "Sie ist nur für Auszubildende im dritten Jahr gedacht", "Sie erweitert die Fähigkeiten und ermöglicht eine höhere Stelle", "Sie ersetzt die Abschlussprüfung vor der IHK"], "c": 2, "e": "Die Aufstiegsfortbildung erweitert die berufliche Handlungsfähigkeit und ermöglicht den Aufstieg, zum Beispiel zum Industriemeister oder zur Industriefachwirtin."}, {"q": "Wozu soll eine Umschulung nach dem BBiG befähigen?", "o": ["Zu einer anderen beruflichen Tätigkeit", "Zur Leitung einer Abteilung im selben Beruf", "Zur Bedienung einer neuen Maschine", "Zum Bestehen der Probezeit im Arbeitsvertrag"], "c": 0, "e": "Die Umschulung soll zu einer anderen beruflichen Tätigkeit befähigen (§ 1 Abs. 5 BBiG). Die Teilnehmenden dieses Kurses machen genau das."}, {"q": "Die Monteure von Nordstern lernen in zwei Tagen die neue Motorsteuerung der E-Bikes. Welche Bildungsart liegt vor?", "o": ["Berufsausbildung", "Umschulung", "Aufstiegsfortbildung", "Anpassungsfortbildung"], "c": 3, "e": "Die Monteure bleiben auf ihrer Stelle und bringen ihr Wissen auf den neuesten Stand. Das ist eine Anpassungsfortbildung."}, {"q": "Was bedeutet Lernen on the job?", "o": ["Lernen in einem Seminar außerhalb des Betriebs", "Lernen direkt am Arbeitsplatz während der Arbeit", "Lernen in der Freizeit ohne Bezug zur Arbeit", "Lernen nur in der Zeit vor dem Ruhestand"], "c": 1, "e": "On the job heißt am Arbeitsplatz, zum Beispiel durch Unterweisung, Projektarbeit oder Job Rotation."}, {"q": "Welches Instrument ist ein typisches Beispiel für near the job?", "o": ["Studium an einer Hochschule", "Ruhestandsvorbereitung", "Qualitätszirkel", "Traineeprogramm"], "c": 2, "e": "Near the job heißt arbeitsplatznah. Der Qualitätszirkel trifft sich nahe am Arbeitsplatz und bearbeitet Probleme aus dem Alltag."}, {"q": "Was beschreibt der Begriff into the job?", "o": ["Die Einarbeitung neuer Beschäftigter", "Die Vorbereitung auf den Ruhestand", "Ein Seminar für erfahrene Führungskräfte", "Die Kündigung durch den Arbeitgeber"], "c": 0, "e": "Into the job umfasst den Einstieg, also Einarbeitung und Traineeprogramme. Für die neuen Monteure 2027 braucht Nordstern einen Einarbeitungsplan."}, {"q": "Was ist ein Vorteil von Lernen on the job?", "o": ["Völlige Ruhe ohne Störungen aus dem Alltag", "Neue Ideen von externen Fachleuten", "Das Gelernte wird sofort angewendet", "Hohe Seminargebühren schaffen Verbindlichkeit"], "c": 2, "e": "Der große Vorteil ist der direkte Praxisbezug. Ruhe und externe Ideen sind eher Vorteile von off the job."}, {"q": "Was ist ein Qualitätszirkel?", "o": ["Ein einmaliges Treffen der Geschäftsführung", "Eine kleine Gruppe, die regelmäßig Probleme aus ihrem Bereich löst", "Eine Prüfung der IHK am Ende der Ausbildung", "Ein Online-Kurs zur Qualitätssicherung"], "c": 1, "e": "Im Qualitätszirkel treffen sich Beschäftigte eines Bereichs regelmäßig, meist moderiert, und erarbeiten Lösungen für Probleme aus dem Alltag."}, {"q": "Was bedeutet Job Rotation?", "o": ["Mehr gleichartige Aufgaben am selben Platz", "Planmäßiger Wechsel zwischen Arbeitsplätzen", "Übernahme von Planungs- und Kontrollaufgaben", "Wechsel der Schicht von früh auf spät"], "c": 1, "e": "Bei der Job Rotation wechseln Beschäftigte planmäßig zwischen Arbeitsplätzen und lernen so mehrere Plätze kennen. Ein Schichtwechsel allein ist keine Job Rotation."}, {"q": "Was bedeutet Job Enlargement?", "o": ["Aufgabenerweiterung auf gleichem Niveau", "Aufgabenbereicherung mit mehr Entscheidung", "Vergrößerung der Abteilung durch Neueinstellungen", "Verlängerung der wöchentlichen Arbeitszeit"], "c": 0, "e": "Job Enlargement ist eine horizontale, quantitative Erweiterung. Es kommen mehr Aufgaben derselben Art dazu."}, {"q": "Ein Monteur montiert künftig nicht nur den Lenker, sondern stellt zusätzlich die Schaltung ein. Welches Instrument liegt vor?", "o": ["Job Enrichment", "Job Enlargement", "Job Rotation", "Coaching"], "c": 1, "e": "Es kommt eine gleichartige Aufgabe auf demselben Niveau dazu. Das ist Job Enlargement."}, {"q": "Ein Monteur darf fertige Lastenräder künftig selbst prüfen und freigeben. Welches Instrument liegt vor?", "o": ["Job Enlargement", "Mentoring", "Job Rotation", "Job Enrichment"], "c": 3, "e": "Prüfen und Freigeben ist eine Kontroll- und Entscheidungsaufgabe. Die Verantwortung steigt, also liegt Job Enrichment vor."}, {"q": "Was ist eine teilautonome Gruppe?", "o": ["Ein Team, das seine Arbeit weitgehend selbst plant und kontrolliert", "Eine Gruppe von Auszubildenden in der Berufsschule", "Ein Ausschuss des Betriebsrats für Weiterbildung", "Eine Gruppe von Leiharbeitskräften aus einem Verleih"], "c": 0, "e": "Eine teilautonome Gruppe erledigt eine abgeschlossene Aufgabe und plant, verteilt und kontrolliert ihre Arbeit weitgehend selbst."}, {"q": "Wie werden Job Enlargement und Job Enrichment in Fachbüchern oft unterschieden?", "o": ["Enlargement horizontal, Enrichment vertikal", "Enlargement vertikal, Enrichment horizontal", "Enlargement qualitativ, Enrichment quantitativ", "Enlargement extern, Enrichment intern"], "c": 0, "e": "Job Enlargement erweitert horizontal und quantitativ, Job Enrichment bereichert vertikal und qualitativ."}, {"q": "Was ist Mentoring?", "o": ["Ein Online-Kurs mit Abschlusstest", "Eine Prüfung der Leistung durch den Betriebsrat", "Eine erfahrene Person aus dem Betrieb begleitet eine Nachwuchskraft", "Ein planmäßiger Wechsel zwischen Abteilungen"], "c": 2, "e": "Beim Mentoring gibt eine erfahrene Person aus dem eigenen Betrieb Wissen, Erfahrung und Kontakte an eine Nachwuchskraft weiter."}, {"q": "Worin unterscheidet sich Mentoring typischerweise von Coaching?", "o": ["Mentoring läuft meist länger und mit einer Person aus dem Betrieb", "Mentoring ist immer teurer als Coaching", "Mentoring gibt es nur für Auszubildende", "Mentoring findet nur off the job im Seminar statt"], "c": 0, "e": "Mentoring dauert oft ein bis zwei Jahre und wird von einer erfahrenen Person aus dem Haus geleistet. Coaching ist meist extern und zeitlich enger begrenzt."}, {"q": "Für welche Situation eignet sich Coaching besonders?", "o": ["Eine neue Abteilungsleiterin hat Konflikte im Team", "Ein Auszubildender braucht einen Ausbildungsplan", "Ein Lager braucht mehr Regalfläche", "Die Lohnabrechnung muss korrigiert werden"], "c": 0, "e": "Coaching wird oft bei Führungskräften eingesetzt, die eine schwierige Situation selbst lösen sollen."}, {"q": "Was versteht man unter E-Learning?", "o": ["Lernen mit digitalen Medien wie Online-Kursen und Lernvideos", "Lernen ausschließlich mit Büchern in der Bibliothek", "Lernen durch Beobachtung an der Montagelinie", "Lernen durch ein Gespräch mit dem Betriebsrat"], "c": 0, "e": "E-Learning nutzt digitale Medien. Es zählt im Kurs zu off the job, kann aber auch am Arbeitsplatz genutzt werden."}, {"q": "Was bedeutet Blended Learning?", "o": ["Lernen nur in Präsenz ohne Technik", "Mischung aus E-Learning und Präsenzphasen", "Lernen in gemischten Altersgruppen", "Wechsel zwischen Früh- und Spätschicht"], "c": 1, "e": "Blended Learning verbindet digitale Lernphasen mit Präsenzterminen. So werden die Vorteile beider Formen genutzt."}, {"q": "Bis zu welchem Betrag werden Lehrgangs- und Prüfungsgebühren beim Aufstiegs-BAföG nach geltendem Stand 2026 gefördert?", "o": ["5.000 €", "15.000 €", "18.000 €", "25.000 €"], "c": 1, "e": "Nach geltendem Stand sind es bis 15.000 €. Die 18.000 € gehören zur geplanten Reform, die noch nicht beschlossen ist."}, {"q": "Wie hoch ist beim Aufstiegs-BAföG nach geltendem Stand der Zuschussanteil an den Lehrgangs- und Prüfungsgebühren?", "o": ["25 %", "40 %", "50 %", "75 %"], "c": 2, "e": "Die Hälfte der Lehrgangs- und Prüfungsgebühren ist ein Zuschuss. Für den Rest kann ein Darlehen genutzt werden."}, {"q": "Was passiert beim Aufstiegs-BAföG nach geltendem Stand, wenn die Prüfung bestanden wird?", "o": ["Die Hälfte des Restdarlehens für die Gebühren wird erlassen", "Das gesamte Darlehen muss sofort zurückgezahlt werden", "Der Arbeitgeber muss das Darlehen übernehmen", "Der Zuschuss muss zurückgezahlt werden"], "c": 0, "e": "Bei Bestehen werden 50 % des Restdarlehens für Lehrgangs- und Prüfungsgebühren erlassen. Der Zuschuss muss nie zurückgezahlt werden."}, {"q": "Lehrgang und Prüfung kosten 5.400 €. Wie hoch ist der Zuschuss nach Aufstiegs-BAföG?", "o": ["1.350 €", "2.700 €", "4.050 €", "5.400 €"], "c": 1, "e": "Der Zuschuss beträgt 50 %. 5.400 € × 50 % = 2.700 €."}, {"q": "Lehrgang und Prüfung kosten 5.400 €. Wie hoch ist der Eigenanteil bei bestandener Prüfung nach geltendem Stand?", "o": ["2.700 €", "675 €", "1.350 €", "4.050 €"], "c": 2, "e": "Zuschuss 2.700 €, Darlehen 2.700 €, Erlass 50 % davon = 1.350 €. Es bleiben 2.700 € − 1.350 € = 1.350 € Eigenanteil."}, {"q": "Wie unterscheidet man Fortbildung und Weiterbildung genau genommen?", "o": ["Fortbildung vertieft den Beruf, Weiterbildung dient der Neuorientierung", "Fortbildung ist immer extern, Weiterbildung immer intern", "Fortbildung gibt es nur für Azubis, Weiterbildung nur für Meister", "Fortbildung ist kostenlos, Weiterbildung zahlt die Person"], "c": 0, "e": "Fortbildung bringt zusätzliche Qualifikation im eigenen Beruf. Weiterbildung steht für Veränderung und Neuorientierung und wird oft als Oberbegriff genutzt."}, {"q": "Was ist das Ziel einer Outplacement-Beratung?", "o": ["Gekündigte finden eine neue Stelle oder machen sich selbstständig", "Neue Beschäftigte werden in den Betrieb eingearbeitet", "Beschäftigte wechseln planmäßig zwischen Abteilungen", "Auszubildende bereiten sich auf die Prüfung vor"], "c": 0, "e": "Outplacement-Beratung gehört zu out of the job. Sie hilft vor allem Führungskräften nach einer Trennung, beruflich neu Fuß zu fassen, und schützt das Ansehen des Betriebs."}, {"q": "In welcher Reihenfolge läuft die Vier-Stufen-Methode der Unterweisung ab?", "o": ["Vorbereiten, vormachen, nachmachen, üben", "Vormachen, vorbereiten, üben, nachmachen", "Nachmachen, vormachen, üben, vorbereiten", "Üben, vorbereiten, nachmachen, vormachen"], "c": 0, "e": "Zuerst wird vorbereitet, dann macht die unterweisende Person vor und erklärt. Danach macht die lernende Person nach und erklärt selbst, zum Schluss übt sie selbstständig."}, {"q": "Leon Becker arbeitet im 2. Ausbildungsjahr je drei Monate im Einkauf, im Vertrieb und im Personal. Welches Instrument liegt vor?", "o": ["Job Enrichment", "Job Rotation", "Coaching", "Qualitätszirkel"], "c": 1, "e": "Leon wechselt planmäßig zwischen Abteilungen. Das ist Job Rotation, die in der Ausbildung häufig genutzt wird."}, {"q": "Welcher mögliche Zielkonflikt besteht bei teurer Weiterbildung?", "o": ["Die Person wechselt nach der Weiterbildung zur Konkurrenz", "Die Person verdient nach der Weiterbildung weniger", "Der Betrieb verliert sein Recht auf Ausbildung", "Der Betriebsrat muss aufgelöst werden"], "c": 0, "e": "Der Betrieb investiert und fürchtet, dass die gut qualifizierte Person den Betrieb verlässt. Das ist ein typischer Zielkonflikt."}, {"q": "Welche Aussage zur Personalentwicklung ist richtig?", "o": ["Sie ist eine Daueraufgabe und kein einmaliges Seminar", "Sie endet mit dem Abschluss der Berufsausbildung", "Sie ist nur in Betrieben mit Tarifbindung erlaubt", "Sie wird ausschließlich von der IHK organisiert"], "c": 0, "e": "Technik und Anforderungen ändern sich ständig. Deshalb ist Personalentwicklung eine dauernde Aufgabe des Betriebs."}, {"q": "Welche Maßnahme ist ein Beispiel für Organisationsentwicklung bei Nordstern?", "o": ["Einführung teilautonomer Gruppen in der Lastenradmontage", "Seminar einer einzelnen Sachbearbeiterin zu Excel", "Ausbildung von Mia Schulz zur Industriekauffrau", "Coaching für eine einzelne Abteilungsleiterin"], "c": 0, "e": "Wenn sich ganze Gruppen und Abläufe verändern, liegt Organisationsentwicklung vor. Die anderen Beispiele betreffen einzelne Personen."}, {"q": "Welche Reihenfolge der Lernorte entspricht dem Verlauf einer Laufbahn?", "o": ["into the job, on the job, out of the job", "out of the job, on the job, into the job", "on the job, into the job, out of the job", "into the job, out of the job, on the job"], "c": 0, "e": "Am Anfang steht die Einarbeitung, dann folgt das Lernen während der Beschäftigung, am Ende die Vorbereitung auf den Ausstieg."}, {"q": "Mit welchem Schritt beginnt der Personalentwicklungsprozess?", "o": ["Mit der Erfolgskontrolle", "Mit der Bedarfsanalyse", "Mit der Durchführung eines Seminars", "Mit der Auswahl eines Seminaranbieters"], "c": 1, "e": "Am Anfang steht die Bedarfsanalyse. Erst wenn klar ist, was fehlt, können Ziele und Maßnahmen geplant werden."}, {"q": "Welche Reihenfolge der Schritte im Personalentwicklungsprozess ist richtig?", "o": ["Bedarf, Ziele, Planung, Durchführung, Erfolgskontrolle, Transfer", "Planung, Bedarf, Ziele, Erfolgskontrolle, Durchführung, Transfer", "Ziele, Durchführung, Bedarf, Planung, Transfer, Erfolgskontrolle", "Durchführung, Planung, Ziele, Bedarf, Transfer, Erfolgskontrolle"], "c": 0, "e": "Der Prozess beginnt mit der Bedarfsanalyse und führt über Ziele, Planung und Durchführung zu Erfolgskontrolle und Transfer."}, {"q": "Welche zwei Profile werden in der Bedarfsanalyse verglichen?", "o": ["Anforderungsprofil und Qualifikationsprofil", "Unternehmensprofil und Kundenprofil", "Lohnprofil und Steuerprofil", "Bewerberprofil und Stellenanzeige"], "c": 0, "e": "Das Anforderungsprofil zeigt, was die Stelle verlangt. Das Qualifikationsprofil zeigt, was die Person kann."}, {"q": "Wie wird der Entwicklungsbedarf berechnet?", "o": ["Qualifikationsprofil minus Anforderungsprofil", "Anforderungsprofil plus Qualifikationsprofil", "Anforderungsprofil minus Qualifikationsprofil", "Anforderungsprofil mal Qualifikationsprofil"], "c": 2, "e": "Entwicklungsbedarf = Anforderungsprofil − Qualifikationsprofil. Man zieht ab, was die Person kann, von dem, was die Stelle verlangt."}, {"q": "Was beschreibt das Qualifikationsprofil?", "o": ["Was eine Stelle von der Person verlangt", "Was eine Person tatsächlich kann", "Welche Entgeltgruppe eine Stelle hat", "Welche Ausbildung der Betrieb anbietet"], "c": 1, "e": "Das Qualifikationsprofil, auch Fähigkeitsprofil, beschreibt Wissen, Können und Verhalten der Person. Was die Stelle verlangt, steht im Anforderungsprofil."}, {"q": "Für die Teamleitung wird Führung mit Stufe 4 verlangt, Jonas Petersen hat Stufe 2. Wie groß ist die Lücke?", "o": ["1 Stufe", "6 Stufen", "3 Stufen", "2 Stufen"], "c": 3, "e": "Soll minus Ist ergibt 4 − 2 = 2 Stufen Entwicklungsbedarf."}, {"q": "Bei welchem Merkmal hat Jonas laut Soll-Ist-Vergleich den größten Bedarf?", "o": ["Fachwissen Montage", "IT und ERP-System", "Führung von Personen", "Schichtplanung"], "c": 2, "e": "Bei der Führung beträgt die Lücke 2 Stufen, bei Kommunikation und Schichtplanung je 1 Stufe, beim Fachwissen und ERP-System 0."}, {"q": "Nordstern führt 2027 ein neues Lagerverwaltungssystem ein. Welche Quelle des Bedarfs liegt vor?", "o": ["Neue Technik im Betrieb", "Wunsch nach einer Aufstiegsfortbildung", "Beurteilungsfehler einer Führungskraft", "Ablauf der Probezeit"], "c": 0, "e": "Der Bedarf entsteht durch neue Technik. Die Beschäftigten im Lager brauchen Wissen für das neue System."}, {"q": "Welche Art von Lernziel ist es, wenn Jonas die Regeln für Pausen und Ruhezeiten im Schichtplan kennen soll?", "o": ["Verhaltensziel", "Könnensziel", "Wissensziel", "Ergebnisziel"], "c": 2, "e": "Es geht um Kenntnisse, also um ein Wissensziel. Ein Könnensziel wäre, den Plan selbst zu erstellen."}, {"q": "Jonas soll Gespräche im Team ruhig und fair führen. Welche Art von Lernziel liegt vor?", "o": ["Wissensziel", "Verhaltensziel", "Kostenziel", "Mengenziel"], "c": 1, "e": "Das Auftreten und die Zusammenarbeit betreffen das Verhalten. Deshalb ist es ein Verhaltensziel."}, {"q": "Ein Bildungsunternehmen schult nur Beschäftigte von Nordstern in der eigenen Werkhalle. Wie nennt man diese Maßnahme?", "o": ["Externe Maßnahme als Inhouse-Seminar", "Interne Maßnahme, weil sie im Betrieb stattfindet", "Offenes Seminar für die Allgemeinheit", "Lernstatt nach Wahl der Beschäftigten"], "c": 0, "e": "Ob eine Maßnahme intern oder extern ist, hängt vom Träger ab, nicht vom Ort. Ein fremder Anbieter im Betrieb führt ein geschlossenes Inhouse-Seminar durch."}, {"q": "Was gilt für die Durchführung im Entwicklungsplan von Jonas Petersen?", "o": ["Seminar, Mentoring und Stellvertretung werden kombiniert", "Ein einziges Seminar reicht für die neue Stelle aus", "Jonas lernt ausschließlich per E-Learning", "Die Durchführung findet erst nach der Erfolgskontrolle statt"], "c": 0, "e": "Wirksam ist meist eine Kombination aus Theorie off the job, Begleitung durch einen Mentor und Übung on the job."}, {"q": "Welche Ebene der Erfolgskontrolle misst ein Fragebogen direkt am Seminarende?", "o": ["Zufriedenheit", "Verhalten am Arbeitsplatz", "Ergebnis für den Betrieb", "Fluktuation"], "c": 0, "e": "Der Fragebogen zeigt, ob die Teilnehmenden zufrieden waren. Über den Nutzen sagt er wenig."}, {"q": "Mit welcher Methode prüft man den Lernerfolg einer Maßnahme?", "o": ["Mit einem Test oder einer praktischen Aufgabe", "Mit dem Umsatz des Folgejahres", "Mit der Teilnehmerliste des Seminars", "Mit der Rechnung des Seminaranbieters"], "c": 0, "e": "Ob Wissen und Können angekommen sind, zeigt ein Test, eine Prüfung oder eine praktische Aufgabe."}, {"q": "Die Führungskraft beobachtet vier Wochen nach dem Seminar, ob die Person das Gelernte anwendet. Welche Ebene wird geprüft?", "o": ["Zufriedenheit", "Lernerfolg", "Verhalten am Arbeitsplatz", "Ergebnis für den Betrieb"], "c": 2, "e": "Die Beobachtung im Alltag zeigt, ob sich das Verhalten am Arbeitsplatz geändert hat."}, {"q": "Welche Ebene der Erfolgskontrolle ist am schwersten zu messen?", "o": ["Ergebnis für den Betrieb", "Zufriedenheit", "Lernerfolg", "Anwesenheit im Seminar"], "c": 0, "e": "Beim Ergebnis wirken viele Einflüsse zusammen. Deshalb ist es am schwersten zu messen, aber am aussagekräftigsten."}, {"q": "Was bedeutet Transfer in der Personalentwicklung?", "o": ["Die Überweisung der Seminargebühr", "Die Versetzung in einen anderen Betrieb", "Die Übertragung des Gelernten an den Arbeitsplatz", "Die Fahrt zum Seminarort"], "c": 2, "e": "Transfer heißt, dass das Gelernte im Arbeitsalltag angewendet wird. Ohne Transfer ist der Nutzen einer Maßnahme gering."}, {"q": "Wer ist der wichtigste Faktor für einen gelungenen Transfer?", "o": ["Die Seminaranbieterin", "Die IHK", "Die Agentur für Arbeit", "Die direkte Führungskraft"], "c": 3, "e": "Die Führungskraft schafft Gelegenheiten zum Üben, gibt Rückmeldung und fragt im Nachgespräch nach."}, {"q": "Wofür steht das A in der SMART-Regel für Entwicklungsziele?", "o": ["akzeptiert", "allgemein", "ausführlich", "abgeschlossen"], "c": 0, "e": "SMART steht für spezifisch, messbar, akzeptiert, realistisch und terminiert. Ein Ziel, das die Person nicht mitträgt, wird selten erreicht."}, {"q": "Was ist eine Personalbeurteilung?", "o": ["Einschätzung von Leistung und Verhalten nach festen Kriterien", "Berechnung des Nettoentgelts aus dem Bruttoentgelt", "Prüfung der Bewerbungsunterlagen vor der Einstellung", "Zählung der Beschäftigten zum Jahresende"], "c": 0, "e": "Bei der Personalbeurteilung schätzt meist die Führungskraft Leistung und Verhalten einer beschäftigten Person nach festgelegten Kriterien ein."}, {"q": "Was ist eine Regelbeurteilung?", "o": ["Eine Beurteilung nur bei einer Kündigung", "Eine Beurteilung in festen Abständen, zum Beispiel jährlich", "Eine Beurteilung nur durch den Betriebsrat", "Eine Beurteilung nach jeder Schicht"], "c": 1, "e": "Die Regelbeurteilung findet regelmäßig statt. Die Anlassbeurteilung gibt es bei besonderen Ereignissen."}, {"q": "Zu welcher Kompetenzart gehören Zeitmanagement und Projektmanagement?", "o": ["Methodenkompetenz", "Sozialkompetenz", "Fachkompetenz", "Persönlichkeitskompetenz"], "c": 0, "e": "Methodenkompetenz umfasst Lern- und Arbeitstechniken wie Zeit- und Projektmanagement. Sie zählt wie Sozial- und Persönlichkeitskompetenz zu den Schlüsselkompetenzen."}, {"q": "Was unterscheidet die gebundene von der freien Beurteilung?", "o": ["Bei der gebundenen werden Stufen auf einem Bogen angekreuzt", "Bei der gebundenen schreibt die Führungskraft einen freien Text", "Die gebundene ist nur mündlich erlaubt", "Die gebundene wird nur von Kolleginnen erstellt"], "c": 0, "e": "Die gebundene Beurteilung nutzt einen Bogen mit festen Kriterien und Stufen. Die freie Beurteilung ist ein Text ohne Vorgaben."}, {"q": "Was ist eine 360-Grad-Beurteilung?", "o": ["Eine Beurteilung durch mehrere Seiten, etwa Vorgesetzte, Kollegen und Mitarbeitende", "Eine Beurteilung, die genau 360 Minuten dauert", "Eine Beurteilung, die nur einmal im Berufsleben stattfindet", "Eine Beurteilung durch einen externen Personalberater"], "c": 0, "e": "Bei der 360-Grad-Beurteilung geben mehrere Personen aus dem Umfeld Rückmeldung. So entsteht ein vollständigeres Bild."}, {"q": "Eine Sachbearbeiterin spricht sehr gut Englisch und wird deshalb auch bei Zuverlässigkeit sehr gut bewertet. Welcher Fehler liegt vor?", "o": ["Tendenz zur Mitte", "Nikolaus-Effekt", "Halo-Effekt", "Strengefehler"], "c": 2, "e": "Ein auffälliges Merkmal überstrahlt die anderen. Das ist der Halo-Effekt, benannt nach dem Heiligenschein."}, {"q": "Was beschreibt der Nikolaus-Effekt?", "o": ["Nur das Verhalten kurz vor der Beurteilung wird berücksichtigt", "Alle Beschäftigten bekommen ein Geschenk zur Beurteilung", "Die Beurteilung findet immer im Dezember statt", "Ältere Beschäftigte werden immer besser beurteilt"], "c": 0, "e": "Beim Nikolaus-Effekt prägen die letzten Wochen das Urteil über das ganze Jahr. Notizen über das ganze Jahr helfen dagegen."}, {"q": "Eine Teamleiterin bewertet alle zwölf Personen ihrer Schicht in allen Merkmalen mit Stufe 3 von 5. Welcher Fehler liegt vor?", "o": ["Halo-Effekt", "Tendenz zur Mitte", "Sympathiefehler", "Nikolaus-Effekt"], "c": 1, "e": "Wer sich nicht festlegen will und nur mittlere Stufen vergibt, macht den Fehler der Tendenz zur Mitte."}, {"q": "Ein Vorgesetzter bewertet einen Kollegen aus seinem Fußballverein besser als andere. Welcher Fehler liegt vor?", "o": ["Tendenz zur Mitte", "Strengefehler", "Nikolaus-Effekt", "Sympathiefehler"], "c": 3, "e": "Persönliche Nähe beeinflusst das Urteil. Eine zweite beurteilende Person kann den Sympathiefehler verringern."}, {"q": "Welches Recht haben Beschäftigte nach § 82 Abs. 2 BetrVG bei der Beurteilung?", "o": ["Sie können verlangen, dass die Beurteilung ihrer Leistung mit ihnen erörtert wird", "Sie dürfen ihre Beurteilung selbst ohne Führungskraft schreiben", "Sie können die Beurteilung jederzeit ohne Grund löschen lassen", "Sie bestimmen allein, wer sie beurteilt"], "c": 0, "e": "Nach § 82 Abs. 2 BetrVG können Beschäftigte verlangen, dass die Beurteilung ihrer Leistung und ihre beruflichen Entwicklungsmöglichkeiten mit ihnen erörtert werden."}, {"q": "Was gilt nach § 94 Abs. 2 BetrVG für allgemeine Beurteilungsgrundsätze?", "o": ["Sie brauchen die Zustimmung des Betriebsrats", "Sie werden allein von der IHK festgelegt", "Sie sind in Betrieben mit Betriebsrat verboten", "Sie gelten nur für Auszubildende"], "c": 0, "e": "Allgemeine Beurteilungsgrundsätze sind zustimmungspflichtig. So wirkt der Betriebsrat an fairen Regeln mit."}, {"q": "Wann hat der Betriebsrat nach § 97 Abs. 2 BetrVG ein Mitbestimmungsrecht?", "o": ["Wenn sich Tätigkeiten so ändern, dass die Kenntnisse nicht mehr ausreichen", "Wenn ein Beschäftigter privat einen Sprachkurs bucht", "Wenn der Betrieb seine Bankverbindung ändert", "Wenn eine Bewerbung per E-Mail eingeht"], "c": 0, "e": "Ändern Maßnahmen des Arbeitgebers die Tätigkeiten so, dass die Kenntnisse nicht mehr reichen, bestimmt der Betriebsrat bei der Einführung von Bildungsmaßnahmen mit."}, {"q": "Wobei bestimmt der Betriebsrat nach § 98 BetrVG mit?", "o": ["Bei der Durchführung betrieblicher Bildungsmaßnahmen", "Bei der Höhe der Lohnsteuer", "Bei der Wahl der Krankenkasse einzelner Beschäftigter", "Bei der Preisgestaltung der Lastenräder"], "c": 0, "e": "Nach § 98 Abs. 1 BetrVG bestimmt der Betriebsrat bei der Durchführung betrieblicher Bildungsmaßnahmen mit."}, {"q": "Zwölf Monteure besuchen eine Schulung für je 450,00 €. Wie hoch sind die Seminargebühren?", "o": ["4.500,00 €", "5.400,00 €", "5.040,00 €", "3.973,20 €"], "c": 1, "e": "12 × 450,00 € = 5.400,00 €."}, {"q": "Zwölf Monteure fehlen je 14 Stunden. Der Stundenlohn beträgt 23,65 €. Wie hoch sind die Kosten der Ausfallzeit vereinfacht?", "o": ["331,10 €", "2.838,00 €", "5.400,00 €", "3.973,20 €"], "c": 3, "e": "12 × 14 Std. = 168 Std. 168 × 23,65 € = 3.973,20 €."}, {"q": "Eine Schulung kostet 9.373,20 € und spart danach 946,00 € je Monat. Wie lange dauert es ungefähr, bis sie sich bezahlt gemacht hat?", "o": ["Etwa 9,9 Monate", "Etwa 4,5 Monate", "Etwa 12,4 Monate", "Etwa 99 Monate"], "c": 0, "e": "Amortisationszeit = Kosten ÷ Nutzen je Monat = 9.373,20 € ÷ 946,00 € = 9,9 Monate."}, {"q": "Wie berechnet man die Amortisationszeit einer Weiterbildung in Monaten?", "o": ["Kosten der Maßnahme geteilt durch Nutzen je Monat", "Nutzen je Monat geteilt durch Kosten der Maßnahme", "Kosten der Maßnahme mal Nutzen je Monat", "Kosten der Maßnahme minus Nutzen je Jahr"], "c": 0, "e": "Man teilt die gesamten Kosten durch die monatliche Ersparnis und erhält die Monate bis zur Deckung der Kosten."}, {"q": "Nordstern vergleicht eine interne und eine externe Schulung. Welche Kosten entstehen in beiden Fällen?", "o": ["Ausfall der Arbeitszeit der Teilnehmenden", "Seminarpreis des fremden Anbieters", "Vorbereitungszeit der eigenen Abteilungsleitung", "Fahrtkosten zum Ort des Anbieters"], "c": 0, "e": "Die Teilnehmenden fehlen in beiden Fällen am Arbeitsplatz. Seminarpreis und Fahrtkosten entstehen nur extern, die Vorbereitungszeit der eigenen Referentin nur intern."}, {"q": "Darf Nordstern Mia Schulz an den Kosten ihrer Ausbildung beteiligen?", "o": ["Ja, bis zur Hälfte der Kosten", "Ja, wenn sie volljährig wird", "Nein, eine solche Vereinbarung ist nichtig", "Nur mit Zustimmung der IHK"], "c": 2, "e": "Eine Vereinbarung, nach der Auszubildende für die Ausbildung zahlen, ist nichtig (§ 12 Abs. 2 BBiG)."}, {"q": "Was ist bei einer Rückzahlungsklausel für eine teure Fortbildung zu beachten?", "o": ["Sie muss fair gestaltet sein, die Rückzahlung sinkt mit der Zeit", "Sie verpflichtet zur Rückzahlung des vollen Betrags auf Lebenszeit", "Sie gilt automatisch für jede Schulung ohne Vereinbarung", "Sie ist auch für Auszubildende in der Erstausbildung erlaubt"], "c": 0, "e": "Rückzahlungsklauseln werden vereinbart und müssen fair sein, etwa mit sinkendem Betrag. In der Erstausbildung sind Zahlungen der Auszubildenden ausgeschlossen."}, {"q": "Warum ist eine gute Bedarfsanalyse auch aus Kostensicht wichtig?", "o": ["Weil sonst Geld für unpassende Maßnahmen ausgegeben wird", "Weil sie die Seminargebühren gesetzlich halbiert", "Weil sie die Lohnsteuer der Teilnehmenden senkt", "Weil ohne sie keine Abschlussprüfung möglich ist"], "c": 0, "e": "Wer den Bedarf falsch einschätzt, schickt Beschäftigte in die falschen Maßnahmen. Das kostet Geld und bringt keinen Nutzen."}, {"q": "Was bedeutet das Wort Qualifikation in der Personalentwicklung?", "o": ["Wissen, Können und Verhalten, das eine Person für ihre Arbeit braucht", "Die Entgeltgruppe, in die eine Person im Tarifvertrag eingestuft ist", "Die Zahl der Jahre, die eine Person schon im Betrieb arbeitet", "Die Durchschnittsnote im letzten Zeugnis der allgemeinbildenden Schule"], "c": 0, "e": "Qualifikation meint das Wissen, das Können und das Verhalten, das für die Arbeit nötig ist. Entgeltgruppe und Betriebszugehörigkeit sind andere Merkmale."}, {"q": "Welche Situation ist im Sinne des Kurses keine Personalentwicklung?", "o": ["Eine Einarbeitung mit festem Plan, Ansprechperson und Rückmeldung", "Ein zufälliger Tipp unter Kollegen in der Kaffeepause", "Eine geplante Schulung zur neuen Software mit festem Termin", "Ein Mentoring über ein Jahr mit vereinbarten Treffen"], "c": 1, "e": "Personalentwicklung ist geplant. Ein zufälliger Tipp ist hilfreich, aber keine geplante Maßnahme."}, {"q": "Was versteht man unter Fluktuation?", "o": ["Beschäftigte verlassen den Betrieb und müssen ersetzt werden", "Beschäftigte wechseln jede Woche zwischen Früh- und Spätschicht", "Die Löhne im Betrieb steigen jedes Jahr um einen festen Betrag", "Die Zahl der Aufträge schwankt zwischen Sommer und Winter"], "c": 0, "e": "Fluktuation bedeutet, dass Beschäftigte den Betrieb verlassen und ihre Stellen neu besetzt werden müssen. Personalentwicklung kann die Fluktuation senken."}, {"q": "Welches Ziel der Personalentwicklung gehört vor allem zur Sicht des Betriebs?", "o": ["Persönliche Entfaltung im Beruf", "Interessantere eigene Aufgaben", "Senkung der Fluktuation", "Höheres eigenes Entgelt"], "c": 2, "e": "Eine geringere Fluktuation spart dem Betrieb Kosten für Suche und Einarbeitung. Die anderen Ziele sind typische Ziele der Beschäftigten."}, {"q": "Wie hängt die Personalentwicklung mit der Personalbeschaffung zusammen?", "o": ["Gute Entwicklung eigener Kräfte kann externe Beschaffung verringern", "Personalentwicklung ersetzt jede Form der Beschaffung vollständig", "Personalentwicklung ist nur vor der ersten Stellenanzeige erlaubt", "Die Aufgaben haben im Personalkreislauf nichts miteinander zu tun"], "c": 0, "e": "Im Personalkreislauf hängen die Aufgaben zusammen. Wer eigene Beschäftigte entwickelt, muss seltener extern suchen und spart Anzeigen- und Beraterkosten."}, {"q": "Welcher Bereich der Personalentwicklung betrifft vor allem Wissen und Können?", "o": ["Bildung", "Förderung", "Organisationsentwicklung", "Personalcontrolling"], "c": 0, "e": "Die Bildung mit Ausbildung, Fortbildung und Umschulung erweitert Wissen und Können. Die Förderung stellt die Laufbahn der Person in den Mittelpunkt."}, {"q": "Welche Frage steht beim Bereich Förderung im Mittelpunkt?", "o": ["Wie entwickelt sich die Laufbahn der Person und wo wird sie eingesetzt?", "Wie viele Räder soll die Montage im nächsten Jahr insgesamt bauen?", "Wie hoch ist der Beitragssatz zur Pflegeversicherung im Jahr 2026?", "Welche Abteilung bekommt im nächsten Jahr eine neue Maschine?"], "c": 0, "e": "Förderung fragt nicht nur, was eine Person lernt, sondern auch, wo sie künftig eingesetzt wird. Dazu gehören Karriereplanung, Job Rotation, Coaching und Mentoring."}, {"q": "Was ist Karriereplanung?", "o": ["Die Planung der nächsten beruflichen Schritte einer Person", "Die Planung, welche Firmenwagen neu gekauft werden", "Die Einteilung der Urlaubszeiten für alle Beschäftigten", "Die Berechnung des Nettopersonalbedarfs der Montage"], "c": 0, "e": "Karriereplanung legt fest, welche beruflichen Schritte eine Person als Nächstes gehen kann. Sie gehört zum Bereich Förderung."}, {"q": "Wie ist Organisationsentwicklung meist angelegt?", "o": ["Langfristig und mit aktiver Beteiligung der Beschäftigten", "Kurzfristig und ohne Information der betroffenen Beschäftigten", "Nur für die Geschäftsführung und die Abteilungsleitungen", "Nur als eintägige Veranstaltung am Ende des Geschäftsjahres"], "c": 0, "e": "Organisationsentwicklung verändert ganze Teams und Abläufe. Das braucht Zeit und gelingt nur, wenn die Beschäftigten aktiv mitwirken."}, {"q": "Was vermittelt die Berufsausbildung nach dem Berufsbildungsgesetz?", "o": ["Die erste berufliche Handlungsfähigkeit in einem geordneten Ausbildungsgang", "Eine Qualifikation für den Aufstieg zur Meisterin oder zum Meister", "Einen Hochschulabschluss in Betriebswirtschaft oder Technik", "Eine kurze Einweisung in eine einzelne neue Maschine"], "c": 0, "e": "Die Berufsausbildung führt zum ersten Berufsabschluss. Für Nordstern ist sie das wichtigste Instrument, um eigene Fachkräfte zu gewinnen."}, {"q": "Warum dauert eine Umschulung oft kürzer als eine Erstausbildung?", "o": ["Weil Erwachsene Berufs- und Lebenserfahrung mitbringen", "Weil bei einer Umschulung keine Prüfung stattfindet", "Weil das Gesetz für Umschulungen nur sechs Monate erlaubt", "Weil bei einer Umschulung nur in der Freizeit gelernt wird"], "c": 0, "e": "Umschülerinnen und Umschüler bringen Erfahrung mit. Deshalb kann die Dauer oft verkürzt werden, eine Prüfung gibt es trotzdem."}, {"q": "Zu welcher Bildungsart passt das Bild einer Treppe?", "o": ["Aufstiegsfortbildung", "Anpassungsfortbildung", "Einarbeitung neuer Kräfte", "Vorbereitung auf den Ruhestand"], "c": 0, "e": "Nach der Aufstiegsfortbildung steht man eine Stufe höher. Die Anpassungsfortbildung gleicht eher einem Laufband, man bleibt auf derselben Höhe."}, {"q": "Wo findet Lernen near the job statt?", "o": ["Nahe am Arbeitsplatz, aber nicht in der laufenden Arbeit", "Mitten in der laufenden Arbeit an der Montagelinie", "In einem Seminarhotel in einer anderen Stadt", "Zu Hause nach dem Ausscheiden aus dem Betrieb"], "c": 0, "e": "Near the job findet in der Nähe des Arbeitsplatzes statt, zum Beispiel im Besprechungsraum neben der Halle. Typisch sind Qualitätszirkel und Lernstatt."}, {"q": "Zu welchem Lernort gehört ein Traineeprogramm für Nachwuchskräfte?", "o": ["into the job", "out of the job", "near the job", "along the job"], "c": 0, "e": "Into the job umfasst den Einstieg in den Betrieb, also Einarbeitung und Traineeprogramme."}, {"q": "Was versteht man unter Arbeitsgestaltung als Instrument der Personalentwicklung?", "o": ["Die Arbeit selbst wird so verändert, dass die Beschäftigten dazulernen", "Die Werkhalle wird neu gestrichen und besser beleuchtet", "Die wöchentliche Arbeitszeit wird für alle gekürzt", "Der Stundenlohn wird für alle Beschäftigten erhöht"], "c": 0, "e": "Bei der Arbeitsgestaltung ändern sich Aufgaben oder Arbeitsplätze. Dazu gehören Job Rotation, Job Enlargement, Job Enrichment und teilautonome Gruppen."}, {"q": "Welches Instrument beschreibt man kurz mit mehr vom Gleichen?", "o": ["Job Enlargement", "Job Enrichment", "Mentoring", "Coaching"], "c": 0, "e": "Beim Job Enlargement kommen gleichartige Aufgaben auf demselben Niveau dazu. Das nennt man horizontal oder quantitativ."}, {"q": "Wofür steht das Wort rich in der Eselsbrücke zu Job Enrichment?", "o": ["Die Aufgabe wird reicher an Verantwortung", "Die Person wird reicher, weil sie mehr verdient", "Die Abteilung wird größer und bekommt mehr Plätze", "Die Arbeitszeit wird länger und reicher an Pausen"], "c": 0, "e": "Rich heißt reich. Beim Job Enrichment kommen planende, kontrollierende oder entscheidende Aufgaben dazu, die Verantwortung steigt."}, {"q": "Was bleibt bei der Job Rotation gleich?", "o": ["Die Aufgaben an jedem einzelnen Arbeitsplatz", "Der Arbeitsplatz, an dem die Person arbeitet", "Die Zahl der Plätze, die eine Person beherrscht", "Die Einsatzmöglichkeiten der Person im Betrieb"], "c": 0, "e": "Bei der Job Rotation wechselt die Person den Platz, die Aufgaben an jedem Platz bleiben gleich. Dadurch kann sie danach an mehreren Plätzen arbeiten."}, {"q": "Was unterscheidet die teilautonome Gruppe vom Job Enrichment einer einzelnen Person?", "o": ["Ein ganzes Team plant, verteilt und kontrolliert eine abgeschlossene Aufgabe", "Nur eine Person bekommt zusätzliche Aufgaben auf demselben Niveau", "Die Gruppe hat weniger Verantwortung als vorher jede einzelne Person", "Die Gruppe darf nur in der Verwaltung und nie in der Montage arbeiten"], "c": 0, "e": "Bei der teilautonomen Gruppe übernimmt ein Team Planung, Verteilung und Kontrolle selbst. Beim Job Enrichment bekommt eine einzelne Person mehr Verantwortung."}, {"q": "Was bedeutet Hilfe zur Selbsthilfe beim Coaching?", "o": ["Die Person findet mit Fragen des Coaches eigene Lösungen", "Der Coach erledigt die schwierigen Aufgaben selbst", "Die Kollegen übernehmen dauerhaft die Arbeit der Person", "Die Person bekommt nur eine fertige Checkliste per Post"], "c": 0, "e": "Ein Coach gibt keine fertigen Lösungen vor. Er stellt Fragen und hilft der Person, selbst einen Weg zu finden."}, {"q": "Wie lange läuft ein Mentoring häufig?", "o": ["Ein bis zwei Jahre", "Einen Nachmittag", "Genau eine Woche", "Bis zur Rente"], "c": 0, "e": "Mentoring ist auf längere Zeit angelegt, oft ein bis zwei Jahre. Die erfahrene Person begleitet die Nachwuchskraft in dieser Zeit."}, {"q": "Zu welchem Lernort zählt E-Learning im Kurs in der Regel?", "o": ["off the job", "into the job", "out of the job", "near the job"], "c": 0, "e": "E-Learning findet nicht in der laufenden Arbeit statt und zählt deshalb zu off the job. Es kann aber auch am Arbeitsplatz genutzt werden."}, {"q": "Worin unterscheiden sich Zuschuss und Darlehen?", "o": ["Ein Zuschuss muss nicht zurückgezahlt werden, ein Darlehen grundsätzlich schon", "Ein Darlehen muss nie zurückgezahlt werden, ein Zuschuss dagegen immer", "Zuschuss und Darlehen müssen direkt nach dem Lehrgang zurückgezahlt werden", "Ein Zuschuss wird nur gezahlt, wenn die Prüfung nicht bestanden wird"], "c": 0, "e": "Den Zuschuss behält die geförderte Person. Das Darlehen wird zurückgezahlt, bei bestandener Prüfung aber zur Hälfte erlassen."}, {"q": "Ab wann soll die geplante Reform des Aufstiegs-BAföG nach dem Kabinettsbeschluss gelten?", "o": ["Ab dem 01.08.2027", "Ab dem 01.01.2026", "Ab dem 01.08.2026", "Ab dem 01.01.2030"], "c": 0, "e": "Nach dem Kabinettsbeschluss vom Juli 2026 soll die Reform ab dem 01.08.2027 gelten. Beschlossen ist sie noch nicht (Bundesregierung, 2026)."}, {"q": "Welche Aussage zum Stand der Reform des Aufstiegs-BAföG im November 2026 ist richtig?", "o": ["Sie ist geplant, aber noch nicht beschlossen", "Sie gilt bereits seit Januar 2026 für alle", "Sie wurde vom Bundestag endgültig abgelehnt", "Sie betrifft nur Studierende an Hochschulen"], "c": 0, "e": "Die Reform ist ein Regierungsentwurf. Im Kurs rechnen wir deshalb mit dem geltenden Recht."}, {"q": "Welchem Grundprinzip folgt der Personalentwicklungsprozess?", "o": ["Planen, durchführen, kontrollieren und verbessern", "Kaufen, lagern, verkaufen und liefern", "Einstellen, bezahlen und kündigen", "Buchen, prüfen und abschließen"], "c": 0, "e": "Der Prozess folgt dem Prinzip planen, durchführen, kontrollieren und verbessern, das auch aus dem Qualitätsmanagement bekannt ist."}, {"q": "Was geschieht im Schritt Ziele festlegen?", "o": ["Man beschreibt, was die Person nach der Maßnahme können soll", "Man bezahlt die Rechnung des Seminaranbieters", "Man misst die Fehlerquote ein Jahr nach der Maßnahme", "Man schreibt das Arbeitszeugnis der Person"], "c": 0, "e": "Aus dem festgestellten Bedarf werden Ziele abgeleitet. Sie beschreiben prüfbar, was die Person nach der Maßnahme können soll."}, {"q": "Welcher Schritt folgt im Personalentwicklungsprozess direkt auf die Durchführung?", "o": ["Erfolgskontrolle", "Bedarfsanalyse", "Ziele festlegen", "Planung"], "c": 0, "e": "Die Reihenfolge lautet Bedarfsanalyse, Ziele, Planung, Durchführung, Erfolgskontrolle und Transfer."}, {"q": "Welcher andere Name wird für das Qualifikationsprofil verwendet?", "o": ["Fähigkeitsprofil", "Stellenplan", "Entgeltprofil", "Organigramm"], "c": 0, "e": "Das Qualifikationsprofil heißt auch Fähigkeitsprofil. Es beschreibt, was eine Person tatsächlich kann."}, {"q": "Warum nutzen gute Betriebe mehrere Quellen für die Bedarfsanalyse?", "o": ["Weil jede einzelne Quelle nur einen Ausschnitt zeigt", "Weil das Gesetz genau drei Quellen vorschreibt", "Weil einzelne Quellen nach einem Jahr verfallen", "Weil der Betriebsrat sonst die Maßnahme verbietet"], "c": 0, "e": "Betrieb, Personalplanung, Beurteilung, Gespräch, Beschäftigte und Betriebsrat zeigen jeweils nur einen Teil. Zusammen ergibt sich ein vollständiges Bild."}, {"q": "Was beschreibt ein Könnensziel?", "o": ["Eine Fertigkeit, etwa einen Schichtplan selbst zu erstellen", "Das Auftreten im Team, etwa ruhig und fair zu bleiben", "Reine Kenntnisse, etwa die Pausenregeln zu nennen", "Den Umsatz, etwa 5 % mehr verkaufte Lastenräder"], "c": 0, "e": "Könnensziele betreffen Fertigkeiten. Kenntnisse gehören zu Wissenszielen, das Auftreten zu Verhaltenszielen."}, {"q": "Welche Entscheidung gehört zur Planung einer Maßnahme?", "o": ["Ob ein interner oder ein externer Anbieter die Maßnahme durchführt", "Welche Note die Person in der nächsten Beurteilung bekommt", "Wie hoch die Kirchensteuer der teilnehmenden Person ist", "Wann die nächste Wahl des Betriebsrats stattfinden soll"], "c": 0, "e": "In der Planung wird festgelegt, wer was lernt, wann, wo, wie und zu welchen Kosten. Dazu gehört die Wahl zwischen internen und externen Anbietern."}, {"q": "Was wird nach einer Maßnahme in der Personalakte abgelegt?", "o": ["Teilnahmebescheinigungen und Zertifikate", "Private Urlaubsfotos der Teilnehmenden", "Steuerbescheide der Ehepartner", "Werbeprospekte des Seminaranbieters"], "c": 0, "e": "Die Durchführung wird dokumentiert. Bescheinigungen helfen später bei der Erfolgskontrolle und beim Personalcontrolling."}, {"q": "Warum sagt die Ebene Zufriedenheit allein wenig über den Nutzen einer Maßnahme?", "o": ["Ein unterhaltsames Seminar kann gut bewertet werden, ohne dass jemand etwas lernt", "Die Zufriedenheit der Teilnehmenden lässt sich grundsätzlich nicht abfragen", "Die Zufriedenheit misst bereits den Gewinn des Betriebs im Folgejahr", "Eine Befragung zur Zufriedenheit ist in Betrieben rechtlich verboten"], "c": 0, "e": "Der Fragebogen am Seminarende ist einfach, zeigt aber nur, ob es gefallen hat. Lernerfolg, Verhalten und Ergebnis werden damit nicht gemessen."}, {"q": "Welche Reihenfolge der Ebenen der Erfolgskontrolle ist von unten nach oben richtig?", "o": ["Zufriedenheit, Lernerfolg, Verhalten, Ergebnis", "Lernerfolg, Zufriedenheit, Ergebnis, Verhalten", "Ergebnis, Verhalten, Lernerfolg, Zufriedenheit", "Verhalten, Ergebnis, Zufriedenheit, Lernerfolg"], "c": 0, "e": "Die vier Fragen lauten gefällt es, kann ich es, tue ich es und bringt es was. Jede Ebene ist eine Stufe höher."}, {"q": "Wann beginnt die Sicherung des Transfers?", "o": ["Schon vor der Maßnahme im Vorgespräch", "Erst ein Jahr nach der Maßnahme", "Nur während der laufenden Maßnahme", "Erst bei der nächsten Regelbeurteilung"], "c": 0, "e": "Transfersicherung beginnt vor der Maßnahme. Im Vorgespräch klären Führungskraft und Beschäftigte Ziele und Erwartungen."}, {"q": "Was ist ein Transferplan?", "o": ["Eine Liste, was die Person in den nächsten Wochen konkret ausprobiert", "Ein Plan für die Anreise mit Bahn und Auto zum Seminarort", "Eine Überweisung der Seminargebühr an den Anbieter", "Ein Plan für die Versetzung in eine Tochtergesellschaft"], "c": 0, "e": "Nach der Maßnahme schreibt die Person auf, was sie konkret anwenden will. So wird das Gelernte in den Alltag übertragen."}, {"q": "Welches Beurteilungskriterium kommt bei Führungskräften hinzu?", "o": ["Führungsverhalten", "Zuverlässigkeit", "Arbeitsqualität", "Fachwissen"], "c": 0, "e": "Leistung und Verhalten werden bei allen beurteilt. Bei Führungskräften kommt das Führungsverhalten dazu."}, {"q": "Was beschreibt der Mildefehler?", "o": ["Alle Beschäftigten werden zu gut bewertet", "Ein Merkmal überstrahlt alle anderen", "Nur die letzten Wochen werden beachtet", "Alle bekommen nur mittlere Stufen"], "c": 0, "e": "Beim Mildefehler fallen alle Bewertungen zu gut aus, beim Strengefehler zu schlecht. Schulung und Vergleich der Beurteilenden helfen dagegen."}, {"q": "Welche Gegenmaßnahme hilft besonders gegen den Nikolaus-Effekt?", "o": ["Notizen über den ganzen Beurteilungszeitraum", "Beurteilungen nur noch im Dezember schreiben", "Beurteilungen nur noch mündlich abgeben", "Nur den ersten Eindruck festhalten"], "c": 0, "e": "Beim Nikolaus-Effekt zählt nur die Zeit kurz vor der Beurteilung. Notizen über das ganze Jahr sorgen für ein vollständiges Bild."}, {"q": "Wie verändern sich die Rechte des Betriebsrats von § 96 bis § 98 BetrVG?", "o": ["Sie werden stärker, vom Fördern über das Beraten bis zum Mitbestimmen", "Sie werden schwächer, vom Mitbestimmen bis zur bloßen Information", "Sie bleiben in allen drei Paragrafen genau gleich stark", "Sie gelten in allen drei Paragrafen nur für Auszubildende"], "c": 0, "e": "§ 96 BetrVG fördert, § 97 BetrVG berät und § 98 BetrVG bestimmt mit. Je höher die Zahl, desto stärker das Recht."}, {"q": "Was versteht man unter der Amortisationszeit einer Weiterbildung?", "o": ["Die Zeit, bis der Nutzen die Kosten der Maßnahme deckt", "Die Dauer des Seminars in Stunden oder Tagen", "Die Zeit bis zur nächsten Regelbeurteilung", "Die Frist, in der die Rechnung bezahlt werden muss"], "c": 0, "e": "Die Amortisationszeit zeigt, nach wie vielen Monaten sich eine Maßnahme bezahlt gemacht hat."}, {"q": "Mit welcher Kennzahl misst Nordstern den Umfang der Weiterbildung im ganzen Betrieb?", "o": ["Weiterbildungstage je Beschäftigten", "Krankenquote", "Personalaufwandsquote", "Überstundenquote"], "c": 0, "e": "Die Kennzahl Weiterbildungstage je Beschäftigten teilt alle Weiterbildungstage durch den durchschnittlichen Personalbestand. Weitere Kennzahlen folgen an Tag 9."}, {"q": "Ein ehemaliger Koch beginnt mit 34 Jahren bei Nordstern eine verkürzte Ausbildung zum Industriemechaniker. Welche Bildungsart liegt vor?", "o": ["Anpassungsfortbildung", "Aufstiegsfortbildung", "Umschulung", "Einarbeitung"], "c": 2, "e": "Die Umschulung befähigt zu einer anderen beruflichen Tätigkeit (§ 1 Abs. 5 BBiG). Der Koch lernt einen neuen Beruf."}, {"q": "Personalleiter Malte Brandt plant, die Vormontage auf teilautonome Gruppen umzustellen. Zu welchem Bereich der Personalentwicklung gehört das?", "o": ["Bildung im Sinne des BBiG", "Förderung einzelner Personen", "Organisationsentwicklung", "Personalcontrolling"], "c": 2, "e": "Hier verändert sich nicht eine einzelne Person, sondern die Arbeit einer ganzen Gruppe. Das ist Organisationsentwicklung."}, {"q": "Im Ausbildungsvertrag von Leon Becker soll stehen, dass er bei vorzeitigem Ende der Ausbildung die Ausbildungskosten erstatten muss. Was gilt?", "o": ["Die Vereinbarung ist nichtig", "Sie gilt, sobald er volljährig ist", "Sie gilt nur für die Hälfte der Kosten", "Sie gilt, wenn die IHK zustimmt"], "c": 0, "e": "Auszubildende dürfen nicht verpflichtet werden, für die Berufsausbildung eine Entschädigung zu zahlen. Eine solche Vereinbarung ist nichtig (§ 12 Abs. 2 BBiG)."}, {"q": "Ein neuer Industriemechaniker bekommt bei Nordstern für die ersten drei Monate einen Paten und einen Einarbeitungsplan. Zu welchem Lernort gehört das?", "o": ["out of the job", "into the job", "near the job", "off the job"], "c": 1, "e": "Into the job umfasst den Einstieg in den Betrieb, also die Einarbeitung neuer Beschäftigter."}, {"q": "Ein Meister der Montage besucht vor seinem Renteneintritt 2027 ein Seminar zur Vorbereitung auf den Ruhestand. Zu welchem Lernort gehört das?", "o": ["into the job", "near the job", "out of the job", "on the job"], "c": 2, "e": "Out of the job umfasst die Vorbereitung auf den Ruhestand und die Begleitung beim Ausscheiden."}, {"q": "Die Qualitätssicherung lernt eine neue Messsoftware zuerst mit kurzen Lernvideos und klärt Fragen danach in einem Workshop vor Ort. Wie heißt diese Lernform?", "o": ["Blended Learning", "Job Enlargement", "Mentoring", "Lernstatt"], "c": 0, "e": "Blended Learning ist die Mischung aus E-Learning und Präsenzphasen."}, {"q": "Eine Sachbearbeiterin im Vertrieb erfasst künftig neben Inlandsaufträgen auch Auslandsaufträge nach demselben Ablauf. Welches Instrument liegt vor?", "o": ["Job Enrichment", "Job Rotation", "Job Enlargement", "Mentoring"], "c": 2, "e": "Es kommen gleichartige Aufgaben auf demselben Niveau dazu. Planung, Kontrolle oder Entscheidung kommen nicht hinzu, deshalb ist es Job Enlargement."}, {"q": "Eine Lagerfachkraft legt künftig selbst die Reihenfolge ihrer Aufträge fest und prüft die fertigen Sendungen vor dem Versand. Welches Instrument liegt vor?", "o": ["Job Enrichment", "Job Enlargement", "Job Rotation", "Qualitätszirkel"], "c": 0, "e": "Mit Planung und Kontrolle kommen Aufgaben einer höheren Ebene dazu. Die Verantwortung steigt, das ist Job Enrichment."}, {"q": "Anna Fischer besteht die Prüfung nicht. Die Kosten betragen 6.800 €. Welchen Betrag trägt sie nach geltendem Aufstiegs-BAföG selbst?", "o": ["1.700 €", "6.800 €", "3.400 €", "0 €"], "c": 2, "e": "Der Zuschuss von 3.400 € bleibt. Ohne Bestehen gibt es keinen Erlass, also muss das Darlehen von 3.400 € voll zurückgezahlt werden."}, {"q": "Bei einer Meisterfortbildung beträgt der Eigenanteil nach Bestehen 2.250 €. Wie hoch waren die Lehrgangs- und Prüfungsgebühren?", "o": ["4.500 €", "6.750 €", "11.250 €", "9.000 €"], "c": 3, "e": "Bei Bestehen bleibt ein Viertel der Kosten als Eigenanteil. Also 2.250 € × 4 = 9.000 €."}, {"q": "Lehrgang und Prüfung kosten 8.400 €. Wie viel Euro werden nach geltendem Aufstiegs-BAföG bei bestandener Prüfung erlassen?", "o": ["2.100 €", "4.200 €", "1.050 €", "6.300 €"], "c": 0, "e": "Zuschuss 8.400 € × 50 % = 4.200 €. Darlehen 4.200 €. Erlass 4.200 € × 50 % = 2.100 €."}, {"q": "Bei einer Fortbildung beträgt der Zuschuss nach Aufstiegs-BAföG 3.100 €. Wie hoch sind die Lehrgangs- und Prüfungsgebühren?", "o": ["3.100 €", "6.200 €", "12.400 €", "4.650 €"], "c": 1, "e": "Der Zuschuss ist die Hälfte der Gebühren. Also 3.100 € × 2 = 6.200 €."}, {"q": "Bei Nordstern gehen 2027 vier Monteure in Rente, und für sie werden Nachfolger vorbereitet. Aus welcher Quelle stammt dieser Entwicklungsbedarf?", "o": ["Aus der Personalplanung", "Aus einem Beurteilungsfehler", "Aus dem Zufriedenheitsbogen", "Aus der Gehaltsabrechnung"], "c": 0, "e": "Die Personalplanung zeigt, wo Abgänge und Wachstum neue Qualifikationen verlangen."}, {"q": "Welches Entwicklungsziel für Anna Fischer ist prüfbar formuliert?", "o": ["Bis 31.03.2027 führt Anna die Lieferantengespräche für Rahmenrohre selbstständig", "Anna soll im Einkauf künftig deutlich sicherer und überzeugender auftreten", "Anna soll sich im kommenden Jahr beruflich und persönlich weiterentwickeln", "Anna soll wieder mehr Freude an ihrer Arbeit im Einkauf haben"], "c": 0, "e": "Nur das erste Ziel nennt Inhalt, Maßstab und Termin. Die anderen Ziele kann man später nicht überprüfen."}, {"q": "Aylin Demir vereinbart mit Mia Schulz das Ziel, dass Mia Anrufe von Kunden freundlich und geduldig entgegennimmt. Welche Zielart liegt vor?", "o": ["Wissensziel", "Könnensziel", "Verhaltensziel", "Kostenziel"], "c": 2, "e": "Das Ziel beschreibt das Auftreten gegenüber anderen. Das ist ein Verhaltensziel."}, {"q": "Eine neue Teamleiterin im Lager soll gut auf ihre Aufgabe vorbereitet werden. Welche Kombination ist am wirksamsten?", "o": ["Seminar, Mentor und Stellvertretung zusammen", "Ein einziges eintägiges Seminar ohne jede weitere Begleitung im Betrieb", "Ein einzelnes Lernvideo, das sie in ihrer Freizeit ansehen soll", "Ein Fragebogen zur Zufriedenheit, den sie vor dem Start ausfüllt"], "c": 0, "e": "Theorie off the job, Begleitung und Übung on the job ergänzen sich. Ein einzelnes Seminar bringt wenig, wenn danach nichts geübt wird."}, {"q": "Nach einer Schulung zur Lackiertechnik sinkt die Zahl der Lackschäden bei Nordstern von 120 auf 80 je Monat. Welche Ebene der Erfolgskontrolle zeigt diese Zahl?", "o": ["Zufriedenheit", "Lernerfolg", "Verhalten am Arbeitsplatz", "Ergebnis für den Betrieb"], "c": 3, "e": "Weniger Lackschäden sind ein messbares Ergebnis für den Betrieb. Das ist die höchste Ebene der Erfolgskontrolle."}, {"q": "Die Lackschäden sinken von 120 auf 80 je Monat. Um wie viel Prozent sind sie gesunken?", "o": ["40,0 %", "33,3 %", "50,0 %", "66,7 %"], "c": 1, "e": "Rückgang 120 − 80 = 40. Anteil 40 ÷ 120 × 100 = 33,3 %."}, {"q": "Die Teilnehmenden eines Excel-Kurses der Verwaltung lösen am Ende eine Prüfaufgabe mit einer Gehaltsliste. Welche Ebene wird geprüft?", "o": ["Zufriedenheit", "Verhalten am Arbeitsplatz", "Lernerfolg", "Ergebnis für den Betrieb"], "c": 2, "e": "Ein Test oder eine praktische Aufgabe zeigt, ob Wissen und Können angekommen sind. Das ist der Lernerfolg."}, {"q": "Was sollte die Teamleitung von Lisa Wagner tun, um den Transfer nach dem Seminar zu sichern?", "o": ["Ihr bald eine echte Kundenverhandlung übertragen und danach Rückmeldung geben", "Sie erst bei der Regelbeurteilung im nächsten Jahr auf das Seminar ansprechen", "Jeden Fehler in der ersten Verhandlung sofort mit einer Abmahnung beantworten", "Die Seminarunterlagen einsammeln, damit sie im Büro nicht herumliegen"], "c": 0, "e": "Die Führungskraft ist der wichtigste Faktor für den Transfer. Sie schafft Gelegenheiten zum Üben, gibt Rückmeldung und lässt Fehler zu."}, {"q": "Ein Meister beurteilt einen neuen Monteur das ganze Jahr nach seinem ungeschickten ersten Arbeitstag. Welcher Fehler liegt vor?", "o": ["Fehler des ersten Eindrucks", "Nikolaus-Effekt am Jahresende", "Tendenz zur mittleren Stufe", "Mildefehler bei allen Merkmalen"], "c": 0, "e": "Der erste Eindruck prägt das Urteil, obwohl sich die Leistung später verändert hat. Notizen über das ganze Jahr helfen dagegen."}, {"q": "Eine Teamleiterin der Montage bewertet alle Beschäftigten sehr gut, weil sie keinen Ärger im Team will. Welcher Fehler liegt vor?", "o": ["Strengefehler", "Halo-Effekt", "Mildefehler", "Nikolaus-Effekt"], "c": 2, "e": "Beim Mildefehler werden alle zu gut bewertet. Die Beurteilung verliert dadurch ihren Nutzen für Entwicklung und Entgelt."}, {"q": "Nordstern will einen neuen Beurteilungsbogen mit festen Kriterien für alle Beschäftigten einführen. Was gilt?", "o": ["Der Betriebsrat muss dem Bogen zustimmen", "Die Geschäftsführung entscheidet allein, weil es um eine reine Formularfrage geht", "Die IHK zu Lübeck muss den Bogen vorher prüfen und genehmigen", "Jede beschäftigte Person muss dem Bogen einzeln schriftlich zustimmen"], "c": 0, "e": "Allgemeine Beurteilungsgrundsätze brauchen die Zustimmung des Betriebsrats (§ 94 Abs. 2 BetrVG)."}, {"q": "Ein Monteur hält seine Leistungsbeurteilung für falsch. Was kann er tun?", "o": ["Er kann verlangen, dass die Beurteilung mit ihm erörtert wird", "Er kann die Beurteilung ohne Gespräch selbst neu schreiben", "Er kann verlangen, dass künftig nur noch Kollegen ihn beurteilen", "Er kann die Beurteilung beim Finanzamt anfechten"], "c": 0, "e": "Beschäftigte können verlangen, dass die Beurteilung ihrer Leistung mit ihnen erörtert wird (§ 82 Abs. 2 BetrVG)."}, {"q": "Nordstern stellt die Lackiererei auf ein neues Pulverlackverfahren um. Die Kenntnisse der Lackierer reichen dafür nicht mehr aus. Welches Recht hat der Betriebsrat?", "o": ["Er bestimmt bei der Einführung der Bildungsmaßnahmen mit", "Er wird erst nach der Umstellung schriftlich informiert", "Er hat bei dieser Umstellung keinerlei Rechte", "Er darf die Umstellung der Technik allein verbieten"], "c": 0, "e": "Ändern sich Tätigkeiten so, dass die Kenntnisse nicht mehr ausreichen, bestimmt der Betriebsrat bei der Einführung von Bildungsmaßnahmen mit (§ 97 Abs. 2 BetrVG)."}, {"q": "Nordstern will eine Person zur Ausbilderin der Industriemechaniker bestellen, die fachlich nicht geeignet ist. Was kann Petra Holm für den Betriebsrat tun?", "o": ["Der Bestellung widersprechen", "Die Person sofort selbst kündigen", "Die Ausbildung im Betrieb beenden", "Nur eine Beschwerde bei der Bank einreichen"], "c": 0, "e": "Der Betriebsrat kann der Bestellung widersprechen, wenn die Person fachlich oder persönlich nicht geeignet ist (§ 98 Abs. 2 BetrVG). Kündigen kann nur der Arbeitgeber."}, {"q": "Arbeitgeber und Betriebsrat von Nordstern einigen sich bei der Beratung über Maßnahmen der Berufsbildung nicht. Wer kann um Vermittlung angerufen werden?", "o": ["Die Einigungsstelle", "Die IHK zu Lübeck", "Das Finanzamt", "Die Krankenkasse"], "c": 0, "e": "Kommt keine Einigung zustande, können Arbeitgeber oder Betriebsrat die Einigungsstelle um Vermittlung anrufen (§ 96 Abs. 1a BetrVG)."}, {"q": "Petra Holm möchte, dass auch Teilzeitkräfte am Excel-Seminar der Verwaltung teilnehmen. Auf welches Recht kann sich der Betriebsrat stützen?", "o": ["Er kann Vorschläge für die Teilnehmenden machen", "Er kann die Teilnehmenden allein bestimmen", "Er kann die Seminargebühr selbst festlegen", "Er kann das Seminar ohne Arbeitgeber buchen"], "c": 0, "e": "Der Betriebsrat kann vorschlagen, welche Beschäftigte an betrieblichen Bildungsmaßnahmen teilnehmen (§ 98 Abs. 3 BetrVG). So wird Weiterbildung gerecht verteilt."}, {"q": "Wie hoch ist der Überschuss der Lackiererschulung im ersten Jahr bei Kosten von 5.324,40 € und einem Nutzen von 591,25 € je Monat?", "o": ["1.770,60 €", "7.095,00 €", "5.324,40 €", "2.770,60 €"], "c": 0, "e": "Nutzen im Jahr 12 × 591,25 € = 7.095,00 €. Überschuss 7.095,00 € − 5.324,40 € = 1.770,60 €."}, {"q": "Im Vertrieb von Nordstern mit 15 Beschäftigten gab es 54 Weiterbildungstage. Wie viele Weiterbildungstage sind das je Beschäftigten?", "o": ["0,28 Tage", "3,0 Tage", "3,6 Tage", "4,5 Tage"], "c": 2, "e": "Weiterbildungstage je Beschäftigten = 54 ÷ 15 = 3,6 Tage. Das liegt über dem Wert des ganzen Betriebs von 3,0 Tagen."}, {"q": "Wie viele Weiterbildungstage hätte Nordstern 2025 bei durchschnittlich 236 Beschäftigten gebraucht, um 3,5 Tage je Beschäftigten zu erreichen?", "o": ["708 Tage", "674 Tage", "826 Tage", "944 Tage"], "c": 2, "e": "Benötigte Tage = 236 × 3,5 = 826 Tage. Tatsächlich waren es 708 Tage, also 3,0 Tage je Beschäftigten."}, {"q": "In der Verwaltung von Nordstern mit 40 Beschäftigten gab es 150 Weiterbildungstage. Welcher Wert ergibt sich je Beschäftigten?", "o": ["3,0 Tage", "3,75 Tage", "0,27 Tage", "4,0 Tage"], "c": 1, "e": "Weiterbildungstage je Beschäftigten = 150 ÷ 40 = 3,75 Tage."}, {"q": "Bei Nordstern steigen die Weiterbildungstage je Beschäftigten von 3,0 auf 3,5. Was zeigt diese Kennzahl nicht?", "o": ["Ob das Gelernte am Arbeitsplatz angewendet wird", "Wie viele Tage im Schnitt auf eine Person kommen", "Dass der Umfang der Weiterbildung gestiegen ist", "Wie sich der Wert gegenüber dem Vorjahr verändert"], "c": 0, "e": "Die Kennzahl misst nur die Menge der Weiterbildung. Ob sie wirkt, zeigen erst Erfolgskontrolle und Transfer."}, {"q": "Ein Meister bucht für sein Team ein Seminar zur Kundenkommunikation, nur weil es gerade günstig ist. Warum ist das aus Kostensicht problematisch?", "o": ["Ohne Bedarfsanalyse wird Geld für eine unpassende Maßnahme ausgegeben", "Günstige Seminare sind in Betrieben mit Tarifbindung grundsätzlich verboten", "Der Betrieb darf Seminare nur buchen, wenn sie mindestens zwei Tage dauern", "Die Seminargebühr wird bei günstigen Angeboten vom Lohn abgezogen"], "c": 0, "e": "Der Bedarf muss zuerst mit einem Soll-Ist-Vergleich ermittelt werden. Sonst passt die Maßnahme nicht zur Lücke, und das Geld ist verloren."}], "lernen": [{"t": "Personalentwicklung", "x": "Alle geplanten Maßnahmen, mit denen die Qualifikation der Beschäftigten erhalten, verbessert und angepasst wird."}, {"t": "Anpassungsfortbildung", "x": "Fortbildung, die das Wissen auf der bisherigen Stelle auf den neuesten Stand bringt."}, {"t": "Aufstiegsfortbildung", "x": "Fortbildung, die zu einer höheren Stelle führt, zum Beispiel Fachwirt oder Meister."}, {"t": "Umschulung", "x": "Bildungsmaßnahme, die zu einer anderen beruflichen Tätigkeit befähigt."}, {"t": "on the job", "x": "Lernen direkt am Arbeitsplatz während der Arbeit."}, {"t": "off the job", "x": "Lernen außerhalb des Arbeitsplatzes, zum Beispiel im Seminar oder beim E-Learning."}, {"t": "Job Rotation", "x": "Planmäßiger Wechsel zwischen verschiedenen Arbeitsplätzen."}, {"t": "Job Enlargement", "x": "Aufgabenerweiterung mit gleichartigen Aufgaben auf demselben Niveau."}, {"t": "Job Enrichment", "x": "Aufgabenbereicherung mit Planung, Kontrolle oder Entscheidung, die Verantwortung steigt."}, {"t": "Mentoring", "x": "Eine erfahrene Person aus dem Betrieb begleitet eine Nachwuchskraft über längere Zeit."}, {"t": "Soll-Ist-Vergleich", "x": "Vergleich von Anforderungsprofil und Qualifikationsprofil, die Differenz ist der Entwicklungsbedarf."}, {"t": "Transfer", "x": "Übertragung des Gelernten vom Lernort an den Arbeitsplatz."}, {"t": "Halo-Effekt", "x": "Beurteilungsfehler, bei dem ein auffälliges Merkmal das Urteil über alle anderen prägt."}, {"t": "Amortisationszeit", "x": "Zeit, bis der Nutzen einer Maßnahme ihre Kosten gedeckt hat."}, {"t": "Vier-Stufen-Methode", "x": "Unterweisung am Arbeitsplatz in vier Stufen, vorbereiten, vormachen und erklären, nachmachen und erklären lassen, üben."}, {"t": "Traineeprogramm", "x": "Planmäßige Einarbeitung von Hochschulabsolventen durch mehrere Abteilungen mit Seminaren, meist ein bis zwei Jahre, into the job."}, {"t": "along the job", "x": "Berufsbegleitende, laufbahnbezogene Instrumente wie Karriereplanung, Coaching, Mentoring und Supervision."}, {"t": "Outplacement-Beratung", "x": "Beratung, die vor allem Führungskräften nach einer Trennung hilft, eine neue Stelle zu finden, out of the job."}, {"t": "Supervision", "x": "Begleitete Reflexion der Zusammenarbeit mit einer ausgebildeten Supervisorin für Personen, Teams oder Organisationen."}, {"t": "Kompetenzlücke", "x": "Die Anforderungen der Stelle liegen über den Fähigkeiten der Person. Gegenteil ist die Anforderungslücke."}, {"t": "SMART-Regel", "x": "Ziele sind spezifisch, messbar, akzeptiert, realistisch und terminiert."}, {"t": "Inhouse-Seminar", "x": "Externe Schulung durch einen fremden Anbieter in den Räumen des Betriebs. Intern oder extern richtet sich nach dem Träger."}, {"t": "Roter Faden", "x": "Woche 1 hat Menschen in den Betrieb gebracht. Woche 2 fragt, wie man sie entwickelt, führt, bei Bedarf freistellt und alles mit Kennzahlen steuert."}, {"t": "Personalentwicklung", "x": "Alle geplanten Maßnahmen, mit denen die Qualifikation der Beschäftigten erhalten, verbessert und an neue Anforderungen angepasst wird (Beiderwieden & Stickdorn, 2026)."}, {"t": "Drei Voraussetzungen für die Teilnahme", "x": "Bedarf, Potenzial und Motivation müssen zusammenkommen. Ohne Bedarf ist die Maßnahme überflüssig, ohne Potenzial überfordert sie, ohne Motivation wird das Gelernte nicht genutzt."}, {"t": "Anpassung und Aufstieg", "x": "Anpassungsfortbildung erhält und passt die berufliche Handlungsfähigkeit an. Aufstiegsfortbildung erweitert sie und ermöglicht den beruflichen Aufstieg (§ 1 Abs. 4 BBiG)."}, {"t": "Fortbildung und Weiterbildung", "x": "Fortbildung vertieft die Qualifikation im eigenen Beruf. Weiterbildung zielt auf Veränderung und Neuorientierung und wird oft als Oberbegriff für alles Lernen nach der Erstausbildung genutzt (Beiderwieden & Stickdorn, 2026)."}, {"t": "Sechs Gruppen in zeitlicher Folge", "x": "into the job beim Einstieg, on, near und off the job während der Beschäftigung, along the job entlang der Laufbahn, out of the job beim Ausstieg."}, {"t": "Vier-Stufen-Methode", "x": "Unterweisung in vier Stufen, nämlich vorbereiten, vormachen und erklären, nachmachen und erklären lassen sowie üben mit Kontrolle (Beiderwieden & Stickdorn, 2026)."}, {"t": "Zwei Instrumente für den Ausstieg", "x": "Outplacement-Beratung hilft bei einer Trennung vom Betrieb, Ruhestandsvorbereitung beim Übergang in die Rente."}, {"t": "Sechs Schritte", "x": "Bedarfsanalyse, Ziele, Planung, Durchführung, Erfolgskontrolle, Transfer. Danach beginnt der Kreislauf von vorn."}, {"t": "Kompetenzlücke und Anforderungslücke", "x": "Kompetenzlücke heißt, die Anforderungen der Stelle liegen über den Fähigkeiten der Person, sie wird weitergebildet. Anforderungslücke heißt, die Fähigkeiten liegen über den Anforderungen, die Person wird gefördert (Beiderwieden & Stickdorn, 2026)."}, {"t": "Drei Arten von Lernzielen", "x": "Wissensziele betreffen Kenntnisse, Könnensziele Fertigkeiten und Verhaltensziele das Auftreten und die Zusammenarbeit (Oechsler & Paul, 2019)."}, {"t": "Interne und externe Maßnahme", "x": "Entscheidend ist, wer die Maßnahme plant und durchführt. Der eigene Betrieb macht sie zur internen, ein fremder Anbieter zur externen Maßnahme, auch wenn sie als Inhouse-Seminar im Betrieb stattfindet (Beiderwieden & Stickdorn, 2026)."}, {"t": "Kombination wirkt", "x": "Theorie im Seminar, Begleitung durch einen Mentor und Übung mit echter Verantwortung ergänzen sich. Ein Seminar allein bringt wenig, wenn danach nichts geübt wird."}, {"t": "Halo-Effekt", "x": "Beurteilungsfehler, bei dem ein einzelnes auffälliges Merkmal das Urteil über alle anderen Merkmale prägt (Oechsler & Paul, 2019)."}, {"t": "Abstufung der Rechte", "x": "Fördern und beraten nach § 96 BetrVG, beraten und bei veränderten Tätigkeiten mitbestimmen nach § 97 BetrVG, mitbestimmen bei der Durchführung nach § 98 BetrVG."}], "sortier": [{"titel": "On, near oder off the job?", "auftrag": "Bringe jedes Instrument in das Depot, das zeigt, wie nah am Arbeitsplatz gelernt wird.", "kategorien": [{"id": "a", "name": "on the job"}, {"id": "b", "name": "near the job"}, {"id": "c", "name": "off the job"}], "items": [{"text": "Unterweisung am Arbeitsplatz mit der Vier-Stufen-Methode", "kat": "a", "expl": "Gelernt wird direkt bei der Arbeit. Die Unterweisung ist das wichtigste Instrument on the job."}, {"text": "Job Rotation, Leon wechselt alle drei Monate die Abteilung", "kat": "a", "expl": "Der planmäßige Wechsel der Arbeitsplätze findet in der laufenden Arbeit statt."}, {"text": "Job Enlargement, ein Monteur stellt auch die Schaltung ein", "kat": "a", "expl": "Mehr gleichartige Aufgaben am eigenen Platz. Gelernt wird bei der Arbeit."}, {"text": "Job Enrichment, ein Monteur gibt Räder selbst frei", "kat": "a", "expl": "Mehr Verantwortung am eigenen Arbeitsplatz. Das zählt zu on the job."}, {"text": "Teilautonome Gruppe plant Schicht und Qualität selbst", "kat": "a", "expl": "Das Team lernt, indem es seine Arbeit selbst steuert. Das ist on the job."}, {"text": "Qualitätszirkel sucht Ursachen für Lackschäden", "kat": "b", "expl": "Die Gruppe trifft sich nah am Arbeitsplatz, aber nicht in der laufenden Arbeit."}, {"text": "Lernstatt, sechs bis acht Beschäftigte lernen gemeinsam", "kat": "b", "expl": "Die Lernstatt findet im Betrieb statt, aber außerhalb der normalen Arbeit."}, {"text": "Auslandseinsatz bei einem Lieferanten", "kat": "b", "expl": "Ein Auslandseinsatz zählt laut Lehrbuch zu near the job."}, {"text": "Regelmäßige, freiwillige Treffen mit Moderation", "kat": "b", "expl": "So arbeiten Lernstatt und Qualitätszirkel. Das Ergebnis fließt direkt in die Arbeit zurück."}, {"text": "Zweitägiges Seminar zur Lastenrad-Elektrik", "kat": "c", "expl": "Ein Seminar findet in einer eigenen Lernumgebung statt. Das ist off the job."}, {"text": "Sven Krüger besucht ein IHK-Seminar zur Entgeltabrechnung", "kat": "c", "expl": "Gelernt wird außerhalb des Arbeitsplatzes. Das ist Fortbildung off the job."}, {"text": "E-Learning mit Lernvideos und Online-Kursen", "kat": "c", "expl": "E-Learning findet nicht in der laufenden Arbeit statt. Es zählt zu off the job."}, {"text": "Berufsbegleitendes Studium", "kat": "c", "expl": "Ein Studium ist Lernen außerhalb des Arbeitsplatzes."}, {"text": "Vorteil Ruhe zum Lernen, Nachteil schwieriger Transfer", "kat": "c", "expl": "Weit weg vom Platz lernt man ungestört. Das Gelernte in die Praxis zu bringen, ist aber schwer."}]}, {"titel": "Schritte im Entwicklungsprozess", "auftrag": "Ordne jede Tätigkeit dem passenden Schritt im Personalentwicklungsprozess zu.", "kategorien": [{"id": "a", "name": "Bedarfsanalyse"}, {"id": "b", "name": "Ziele und Planung"}, {"id": "c", "name": "Kontrolle und Transfer"}], "items": [{"text": "Anforderungsprofil mit Qualifikationsprofil vergleichen", "kat": "a", "expl": "Der Soll-Ist-Vergleich zeigt den Entwicklungsbedarf. Das ist der erste Schritt."}, {"text": "Lücke Führung bei Jonas, Soll 4 und Ist 2", "kat": "a", "expl": "Soll minus Ist ergibt eine Lücke von 2 Stufen. So wird der Bedarf sichtbar."}, {"text": "Neues Lagerverwaltungssystem zeigt Schulungsbedarf", "kat": "a", "expl": "Neue Technik ist eine Quelle für Bedarf. Er wird in der Bedarfsanalyse erfasst."}, {"text": "Ist-Profil und Potenzial der Person erfassen", "kat": "a", "expl": "Das ist die Personalanalyse. Sie gehört zur Bedarfsanalyse."}, {"text": "Bis 30.06.2027 führt Jonas die Spätschicht selbstständig", "kat": "b", "expl": "Das ist ein SMART-Ziel mit Inhalt, Maß und Termin."}, {"text": "Termin, Ort und Budget der Schulung festlegen", "kat": "b", "expl": "Diese Punkte klärt die Planung der Maßnahme."}, {"text": "Vertretung während des Seminars organisieren", "kat": "b", "expl": "Wer im Seminar ist, fehlt im Betrieb. Die Vertretung wird vorher geplant."}, {"text": "Entscheiden, ob intern oder extern geschult wird", "kat": "b", "expl": "Die Wahl des Anbieters gehört zur Planung. Dabei werden die Kosten verglichen."}, {"text": "Ziel spezifisch, messbar, akzeptiert, realistisch, terminiert", "kat": "b", "expl": "Das sind die SMART-Regeln. Sie helfen beim Festlegen der Ziele."}, {"text": "Zufriedenheit der Teilnehmenden nach dem Seminar abfragen", "kat": "c", "expl": "Das ist die erste Ebene der Erfolgskontrolle."}, {"text": "Lernerfolg mit einem Test prüfen", "kat": "c", "expl": "Ein Test misst, was gelernt wurde. Das ist Erfolgskontrolle."}, {"text": "Verhalten am Arbeitsplatz nach der Schulung beobachten", "kat": "c", "expl": "Hier zeigt sich, ob das Gelernte im Alltag ankommt."}, {"text": "Amortisation der Schulung nach 9,9 Monaten berechnen", "kat": "c", "expl": "Kosten und Nutzen zeigen das Ergebnis für den Betrieb. Das ist die höchste Ebene der Kontrolle."}, {"text": "Transferplan und Nachgespräch mit der Führungskraft", "kat": "c", "expl": "Damit wird das Gelernte im Alltag gesichert. Das ist Transfersicherung."}]}]}, {"nr": 7, "title": "Personalführung", "date": "01.12.2026", "quiz": [{"q": "Was versteht man unter Personalführung?", "o": ["Zielgerichtete Beeinflussung des Verhaltens von Mitarbeitenden", "Verwaltung der Personalakten und Stammdaten", "Berechnung von Löhnen und Gehältern", "Planung des künftigen Personalbedarfs"], "c": 0, "e": "Personalführung beeinflusst das Verhalten der Mitarbeitenden so, dass die Unternehmensziele erreicht werden. Verwaltung, Entgelt und Planung sind andere Bereiche der Personalwirtschaft."}, {"q": "Was ist ein Führungsstil?", "o": ["Das typische, wiederkehrende Verhalten einer Führungskraft", "Eine einmalige Anweisung in einer Notlage", "Die Kleiderordnung für Führungskräfte im Betrieb", "Ein Vertrag zwischen Betriebsrat und Arbeitgeber"], "c": 0, "e": "Ein Führungsstil beschreibt, wie sich eine Führungskraft immer wieder gegenüber ihren Mitarbeitenden verhält."}, {"q": "Welche drei Führungsstile unterscheidet Kurt Lewin?", "o": ["Autoritär, demokratisch, laissez-faire", "Patriarchalisch, charismatisch, bürokratisch", "Unterweisen, überzeugen, delegieren", "Theorie X, Theorie Y, Theorie Z"], "c": 0, "e": "Lewin, Lippitt und White unterschieden 1939 den autoritären, den demokratischen und den Laissez-faire-Stil. In deutschen Lehrbüchern heißt der demokratische Stil oft kooperativ."}, {"q": "Woran erkennt man den autoritären Führungsstil?", "o": ["Die Führungskraft entscheidet allein und kontrolliert", "Das Team entscheidet in einem festgelegten Rahmen", "Die Führungskraft gibt kaum Ziele vor", "Vorschläge des Teams bestimmen die Entscheidung"], "c": 0, "e": "Beim autoritären Stil entscheidet die Führungskraft ohne Beteiligung der Mitarbeitenden und kontrolliert die Ausführung."}, {"q": "Was bedeutet der Begriff Laissez-faire?", "o": ["Machen lassen", "Gemeinsam entscheiden", "Streng kontrollieren", "Schnell befehlen"], "c": 0, "e": "Laissez-faire kommt aus dem Französischen und bedeutet so viel wie machen lassen. Die Führungskraft greift kaum ein."}, {"q": "Was kennzeichnet den patriarchalischen Führungsstil?", "o": ["Streng, aber väterlich wohlwollend, Treue wird erwartet", "Entscheidungen werden im Rahmen an das Team abgegeben", "Geführt wird vor allem über Regeln und Dokumente", "Die Führungskraft stellt nur die Arbeitsmittel bereit"], "c": 0, "e": "Der Patriarch führt wie ein Familienoberhaupt. Er sorgt für seine Leute, erwartet Dankbarkeit und Treue und delegiert keine Entscheidungen."}, {"q": "Welcher Nachteil ist typisch für den Laissez-faire-Stil?", "o": ["Orientierungslosigkeit und Konflikte im Team", "Zu viele Anweisungen der Führungskraft", "Zu lange Abstimmungsrunden mit dem Team", "Zu starke Kontrolle jeder einzelnen Tätigkeit"], "c": 0, "e": "Ohne Ziele und Rückmeldung wissen Mitarbeitende oft nicht, was erwartet wird. Das führt zu Unklarheit, Streit und schwacher Leistung."}, {"q": "In der Lackiererei von Nordstern geht der Feueralarm los. Welcher Stil passt?", "o": ["Autoritär", "Kooperativ", "Laissez-faire", "Beratend"], "c": 0, "e": "Im Notfall zählt jede Sekunde. Klare Anweisungen ohne Diskussion schützen Leben, deshalb passt der autoritäre Stil."}, {"q": "Sandra Kowalski ist im Lager kaum anwesend und gibt kaum Ziele vor. Welcher Stil liegt vor?", "o": ["Laissez-faire", "Autoritär", "Kooperativ", "Patriarchalisch"], "c": 0, "e": "Wer kaum eingreift und keine Ziele vorgibt, führt im Laissez-faire-Stil."}, {"q": "Was beschreibt das Kontinuum nach Tannenbaum und Schmidt?", "o": ["Abgestufte Stile zwischen autoritär und autonom", "Fünf Stufen menschlicher Bedürfnisse", "Vier Reifegrade von Mitarbeitenden", "Zwei Menschenbilder von Führungskräften"], "c": 0, "e": "Tannenbaum und Schmidt ordnen die Führungsstile auf einer durchgehenden Skala von vorgesetztenzentriert bis mitarbeiterzentriert."}, {"q": "Der Teamleiter entscheidet über den Schichtplan, versucht aber vorher, das Team von seiner Entscheidung zu überzeugen. Welche Stufe ist das?", "o": ["Patriarchalisch", "Autoritär", "Beratend", "Delegativ"], "c": 0, "e": "Beim patriarchalischen Stil entscheidet die Führungskraft allein, will das Team aber überzeugen, bevor sie anordnet."}, {"q": "Das Team entwickelt Vorschläge, und die Teamleiterin wählt einen davon aus. Welche Stufe liegt vor?", "o": ["Kooperativ", "Informierend", "Autonom", "Patriarchalisch"], "c": 0, "e": "Beim kooperativen Stil kommen die Vorschläge aus der Gruppe, die Entscheidung trifft die Führungskraft."}, {"q": "Wonach richtet sich der Führungsstil im Modell von Hersey und Blanchard?", "o": ["Nach dem Reifegrad der Mitarbeitenden", "Nach der Größe des Unternehmens", "Nach dem Gehalt der Führungskraft", "Nach der Zahl der Betriebsratsmitglieder"], "c": 0, "e": "Hersey und Blanchard koppeln den Stil an den Reifegrad, also an Fähigkeit und Bereitschaft der Mitarbeitenden."}, {"q": "Welcher Stil passt nach Hersey und Blanchard zum Reifegrad M1?", "o": ["S1 unterweisen", "S2 überzeugen", "S3 beteiligen", "S4 delegieren"], "c": 0, "e": "Bei M1 kann die Person die Aufgabe noch nicht und ist unsicher. Sie braucht genaue Anweisungen, also S1."}, {"q": "Paul Neumann ist seit vier Wochen in der Montage, sehr motiviert, kann aber noch wenig. Welcher Stil passt?", "o": ["S2 überzeugen", "S1 unterweisen", "S3 beteiligen", "S4 delegieren"], "c": 0, "e": "Paul will, kann aber noch wenig. Das ist Reifegrad M2. Passend ist S2 mit viel Erklärung und Unterstützung."}, {"q": "Ewa Nowak ist seit 15 Jahren Facharbeiterin, zuverlässig und engagiert. Welcher Stil passt?", "o": ["S4 delegieren", "S1 unterweisen", "S2 überzeugen", "Autoritär mit stündlicher Kontrolle"], "c": 0, "e": "Ewa kann und will. Das ist Reifegrad M4, also kann man ihr Aufgaben übertragen."}, {"q": "Welche Kombination beschreibt den Stil S2 überzeugen?", "o": ["Hohe Aufgaben- und hohe Beziehungsorientierung", "Hohe Aufgaben- und niedrige Beziehungsorientierung", "Niedrige Aufgaben- und hohe Beziehungsorientierung", "Niedrige Aufgaben- und niedrige Beziehungsorientierung"], "c": 0, "e": "Bei S2 gibt die Führungskraft noch viele Vorgaben und unterstützt gleichzeitig stark."}, {"q": "Welcher Stil zeigt wenig Aufgaben- und wenig Beziehungsorientierung?", "o": ["S4 delegieren", "S1 unterweisen", "S2 überzeugen", "S3 beteiligen"], "c": 0, "e": "Bei S4 kann und will die Person. Die Führungskraft überträgt die Aufgabe und hält sich bei Anweisungen und Unterstützung zurück."}, {"q": "Was ist das Ziel des situativen Führens auf lange Sicht?", "o": ["Mitarbeitende reifer machen und schrittweise loslassen", "Mitarbeitende dauerhaft im Stil S1 halten", "Den Betriebsrat aus Entscheidungen heraushalten", "Einen festen Stil für alle Personen einführen"], "c": 0, "e": "Die Führungskraft soll den Reifegrad erhöhen und dann weniger anleiten, bis sie delegieren kann."}, {"q": "Mia Schulz hat am 01.08.2026 ihre Ausbildung begonnen. Welcher Stil passt in den ersten Wochen?", "o": ["S1 unterweisen", "S4 delegieren", "Laissez-faire", "Autonom"], "c": 0, "e": "Mia kennt die Abläufe noch nicht und ist unsicher. Sie braucht genaue Anleitung. Delegieren würde sie überfordern."}, {"q": "Was ist nach Herzberg das Gegenteil von Unzufriedenheit?", "o": ["Nicht-Unzufriedenheit", "Zufriedenheit", "Nicht-Zufriedenheit", "Leistungsbereitschaft"], "c": 0, "e": "Herzberg trennt zwei Skalen. Gute Hygienefaktoren beseitigen Unzufriedenheit, erzeugen aber nur Nicht-Unzufriedenheit und noch keine Zufriedenheit."}, {"q": "Was beschreibt der Verdrängungseffekt?", "o": ["Äußere Belohnungen können die innere Freude schwächen", "Neue Mitarbeitende verdrängen erfahrene Kollegen", "Hygienefaktoren verdrängen alle Motivatoren", "Der Betriebsrat verdrängt die Führungskraft"], "c": 0, "e": "Wird eine gern getane Tätigkeit nur noch mit Geld belohnt, kann die intrinsische Motivation nachlassen."}, {"q": "Wie viele Bedürfnisstufen beschreibt Maslow?", "o": ["Fünf", "Drei", "Vier", "Sieben"], "c": 0, "e": "Maslow nennt physiologische Bedürfnisse, Sicherheit, soziale Bedürfnisse, Wertschätzung und Selbstverwirklichung."}, {"q": "Welche Stufe steht bei Maslow ganz oben?", "o": ["Selbstverwirklichung", "Wertschätzung", "Sicherheit", "Soziale Bedürfnisse"], "c": 0, "e": "Die Selbstverwirklichung bildet die Spitze. Dort geht es darum, die eigenen Fähigkeiten voll zu entfalten."}, {"q": "Welche Stufe folgt bei Maslow direkt auf die physiologischen Bedürfnisse?", "o": ["Sicherheit", "Soziale Bedürfnisse", "Wertschätzung", "Selbstverwirklichung"], "c": 0, "e": "Nach Essen, Trinken und Schlaf folgen die Sicherheitsbedürfnisse wie Schutz und ein sicheres Einkommen."}, {"q": "Welche Stufen nennt man bei Maslow Defizitbedürfnisse?", "o": ["Die vier unteren Stufen", "Nur die Selbstverwirklichung", "Nur die physiologischen Bedürfnisse", "Die beiden oberen Stufen"], "c": 0, "e": "Physiologische Bedürfnisse, Sicherheit, soziale Bedürfnisse und Wertschätzung sind Defizitbedürfnisse, weil ihr Fehlen als Mangel empfunden wird."}, {"q": "Ein unbefristeter Arbeitsvertrag bei Nordstern spricht vor allem welche Maslow-Stufe an?", "o": ["Sicherheit", "Selbstverwirklichung", "Wertschätzung", "Soziale Bedürfnisse"], "c": 0, "e": "Ein unbefristeter Vertrag gibt Sicherheit über Arbeitsplatz und Einkommen."}, {"q": "Was kritisiert man häufig an Maslows Modell?", "o": ["Die Reihenfolge gilt nicht für alle Menschen gleich", "Es hat zu viele Stufen für die Praxis", "Es beschreibt nur die Bedürfnisse von Führungskräften", "Es verbietet Prämien im Betrieb"], "c": 0, "e": "Menschen können mehrere Bedürfnisse zugleich haben, und die Rangfolge ist kulturell und individuell verschieden."}, {"q": "Wie heißen die beiden Faktorgruppen bei Herzberg?", "o": ["Hygienefaktoren und Motivatoren", "Defizit- und Wachstumsbedürfnisse", "Theorie X und Theorie Y", "Aufgaben- und Beziehungsorientierung"], "c": 0, "e": "Herzberg unterscheidet Hygienefaktoren, die Unzufriedenheit verhindern, und Motivatoren, die Zufriedenheit erzeugen."}, {"q": "Was bewirken gute Hygienefaktoren nach Herzberg?", "o": ["Sie verhindern Unzufriedenheit", "Sie erzeugen dauerhaft hohe Motivation", "Sie ersetzen jede Anerkennung", "Sie machen Kontrolle überflüssig"], "c": 0, "e": "Gute Hygienefaktoren führen nur zu einem Zustand ohne Unzufriedenheit. Motivation entsteht erst durch Motivatoren."}, {"q": "Nordstern erhöht die Entgelte nach dem neuen Metalltarif. Was erwartet Herzberg?", "o": ["Weniger Unzufriedenheit, aber keine dauerhafte Motivation", "Dauerhaft deutlich mehr Leistungsbereitschaft", "Mehr Unzufriedenheit wegen höherer Abzüge", "Keinerlei Wirkung auf die Zufriedenheit"], "c": 0, "e": "Entgelt ist ein Hygienefaktor. Eine Erhöhung beseitigt Unzufriedenheit, erzeugt aber allein keine dauerhafte Motivation."}, {"q": "Ewa Nowak übernimmt die Einarbeitung neuer Kollegen in der Montage. Wie ordnet Herzberg das ein?", "o": ["Als Motivator Verantwortung", "Als Hygienefaktor Arbeitsbedingungen", "Als Hygienefaktor Entgelt", "Als Hygienefaktor Unternehmenspolitik"], "c": 0, "e": "Ewa erhält mehr Verantwortung, also einen Motivator. Das entspricht dem Job Enrichment."}, {"q": "Welche Reihenfolge empfiehlt Herzberg für die Praxis?", "o": ["Erst Hygienefaktoren sichern, dann Motivatoren schaffen", "Erst Motivatoren schaffen, Hygienefaktoren sind egal", "Nur Hygienefaktoren verbessern, Motivatoren schaden", "Nur Prämien zahlen, alles andere ist unwichtig"], "c": 0, "e": "Sind die Hygienefaktoren schlecht, nützen Motivatoren wenig. Deshalb zuerst die Grundlagen sichern und dann motivieren."}, {"q": "Welches Menschenbild beschreibt McGregor mit Theorie X?", "o": ["Der Mensch ist arbeitsunlustig und muss kontrolliert werden", "Der Mensch sucht Verantwortung und kontrolliert sich selbst", "Der Mensch arbeitet nur in Gruppen gern", "Der Mensch richtet sich nur nach Bedürfnisstufen"], "c": 0, "e": "Theorie X unterstellt Arbeitsunlust, Scheu vor Verantwortung und den Bedarf an Druck und Kontrolle."}, {"q": "Welcher Führungsstil folgt typischerweise aus Theorie X?", "o": ["Autoritär mit viel Kontrolle", "Kooperativ mit Zielvereinbarung", "Delegativ mit großem Freiraum", "Autonom ohne jede Vorgabe"], "c": 0, "e": "Wer Menschen für arbeitsunlustig hält, führt mit Anweisung, Druck und Kontrolle, also autoritär."}, {"q": "Was ist mit einer sich selbst erfüllenden Prophezeiung bei McGregor gemeint?", "o": ["Misstrauen erzeugt das befürchtete Verhalten", "Gute Ziele erreichen sich ohne Arbeit von selbst", "Führungskräfte sagen den Umsatz genau voraus", "Mitarbeitende kündigen immer nach einem Jahr"], "c": 0, "e": "Strenge Kontrolle aus Misstrauen führt zu Dienst nach Vorschrift. Das scheint das Misstrauen zu bestätigen."}, {"q": "Was empfiehlt McGregor Führungskräften bei Mitarbeitenden, die sich wie nach Theorie X verhalten?", "o": ["Von Y ausgehen und sie schrittweise selbstständiger machen", "Dauerhaft streng kontrollieren, weil sich nichts ändert", "Sie ganz in Ruhe lassen, bis sie sich selbst motivieren", "Ihnen sofort die volle Budgetverantwortung übertragen"], "c": 0, "e": "McGregor hielt Theorie Y für zutreffender. X-Verhalten soll nach und nach durch mehr Verantwortung und Selbstbestimmung in Richtung Y entwickelt werden."}, {"q": "Jan Richter kontrolliert jede Stunde, weil er glaubt, sonst würde niemand arbeiten. Welche Annahme steckt dahinter?", "o": ["Theorie X", "Theorie Y", "Motivator Anerkennung", "Reifegrad M4"], "c": 0, "e": "Die Annahme, Menschen arbeiten nur unter Kontrolle, entspricht dem Menschenbild der Theorie X."}, {"q": "Was kennzeichnet agile Führung, wie sie das Lehrbuch beschreibt?", "o": ["Teams steuern sich in kurzen Schritten weitgehend selbst", "Die Führungskraft plant jede Einzelheit im Voraus", "Es gibt weder Ziele noch Abstimmungen im Team", "Nur die Geschäftsführung darf Entscheidungen treffen"], "c": 0, "e": "Agile Teams planen selbst und stimmen sich eng ab. Die Führungskraft gibt Ziel und Rahmen vor und unterstützt."}, {"q": "Was beschreibt eine Führungstechnik?", "o": ["Das Verfahren, mit dem geführt wird", "Die Persönlichkeit der Führungskraft", "Die Höhe des Gehalts der Führungskraft", "Den Aufbau der Personalabteilung"], "c": 0, "e": "Führungstechniken sind Regeln und Verfahren, etwa Führen über Ziele, Ausnahmen oder Delegation. Das Verhalten beschreibt der Führungsstil."}, {"q": "Was bedeutet Management by Objectives?", "o": ["Führen durch Ziele", "Führen nach dem Ausnahmeprinzip", "Führen durch Übertragen von Aufgaben", "Führen durch ständige Anwesenheit"], "c": 0, "e": "Objectives heißt Ziele. Bei MbO werden Ziele vereinbart, und der Weg bleibt den Mitarbeitenden überlassen."}, {"q": "Welches Menschenbild passt am besten zu Management by Objectives?", "o": ["Theorie Y nach McGregor", "Theorie X nach McGregor", "Laissez-faire nach Lewin", "Reifegrad M1 nach Hersey und Blanchard"], "c": 0, "e": "MbO setzt voraus, dass Menschen sich selbst steuern und Verantwortung übernehmen. Das entspricht Theorie Y."}, {"q": "Was versteht man unter einer Zielkaskade?", "o": ["Ziele werden von oben nach unten abgeleitet", "Ziele werden jedes Jahr zufällig neu verteilt", "Nur die Geschäftsführung bekommt Ziele", "Mitarbeitende legen die Unternehmensziele fest"], "c": 0, "e": "Aus den Unternehmenszielen werden Ziele für Bereiche, Teams und Personen abgeleitet, wie bei einem Wasserfall."}, {"q": "Ein Ziel nennt ein festes Datum, bis wann es erreicht sein soll. Welches SMART-Merkmal ist damit erfüllt?", "o": ["Terminiert", "Spezifisch", "Attraktiv", "Realistisch"], "c": 0, "e": "T steht für terminiert. Ein festes Datum legt fest, bis wann das Ziel erreicht sein soll."}, {"q": "Warum ist das Ziel „Der Vertrieb soll mehr verkaufen“ nicht SMART?", "o": ["Es fehlen Zahl und Termin", "Es ist zu kurz formuliert", "Es betrifft den falschen Bereich", "Es wurde nicht von der IHK genehmigt"], "c": 0, "e": "Mehr verkaufen ist weder messbar noch terminiert. Man kann am Ende nicht sicher sagen, ob das Ziel erreicht ist."}, {"q": "Was bedeutet das R in SMART für die Führungskraft?", "o": ["Das Ziel muss erreichbar sein", "Das Ziel muss möglichst bequem sein", "Das Ziel muss vom Betriebsrat stammen", "Das Ziel muss jedes Jahr gleich bleiben"], "c": 0, "e": "R heißt realistisch. Ein Ziel soll anspruchsvoll, aber machbar sein, sonst frustriert es."}, {"q": "Wie berechnet man den Zielerreichungsgrad eines Ziels?", "o": ["Ist ÷ Soll × 100", "Soll ÷ Ist × 100", "Ist − Soll × 100", "Soll × Ist ÷ 100"], "c": 0, "e": "Der erreichte Wert wird durch den Sollwert geteilt und mit 100 multipliziert. So erhält man den Anteil in Prozent."}, {"q": "Lisa Wagner gewinnt 9 von 12 geplanten Fachhändlern. Wie hoch ist ihr Zielerreichungsgrad bei diesem Ziel?", "o": ["75 %", "133 %", "90 %", "25 %"], "c": 0, "e": "9 ÷ 12 × 100 = 75 %. 133 % entsteht, wenn man Soll durch Ist teilt."}, {"q": "Ziel 1 ist zu 75 % erreicht (Gewicht 50 %), Ziel 2 und 3 zu je 100 % (Gewicht 30 % und 20 %). Wie hoch ist der Gesamtwert?", "o": ["87,5 %", "91,7 %", "75,0 %", "82,5 %"], "c": 0, "e": "0,50 × 75 + 0,30 × 100 + 0,20 × 100 = 37,5 + 30 + 20 = 87,5 %. 91,7 % wäre der ungewichtete Durchschnitt."}, {"q": "Welcher Nachteil ist typisch für Management by Objectives?", "o": ["Es zählt leicht nur noch, was messbar ist", "Die Mitarbeitenden erhalten zu wenig Freiraum", "Die Führungskraft muss jeden Schritt kontrollieren", "Es gibt am Ende keine Ergebnisse"], "c": 0, "e": "Freundlichkeit oder Hilfsbereitschaft lassen sich schwer messen und werden bei reinem Zielfokus leicht vernachlässigt."}, {"q": "Was bedeutet Management by Exception?", "o": ["Eingreifen nur bei Abweichungen über festgelegte Grenzen", "Führen ausschließlich über vereinbarte Ziele", "Übertragen aller Entscheidungen an den Betriebsrat", "Ausnahmsweise Führen ohne jede Regel"], "c": 0, "e": "Beim Ausnahmeprinzip entscheiden die Mitarbeitenden im Normalfall selbst. Die Führungskraft greift nur im Ausnahmefall ein."}, {"q": "In einer Woche werden 600 Räder montiert, 21 müssen nachgearbeitet werden. Wie hoch ist die Nacharbeitsquote?", "o": ["3,5 %", "2,1 %", "28,6 %", "0,35 %"], "c": 0, "e": "21 ÷ 600 × 100 = 3,5 %. Die Toleranzgrenze von 3,0 % ist damit überschritten."}, {"q": "Die Toleranzgrenze für Nacharbeit liegt bei 3,0 %. In welcher Woche muss Jan Richter nach dem Ausnahmeprinzip eingreifen?", "o": ["Woche mit 3,5 %", "Woche mit 2,5 %", "Woche mit 2,0 %", "Woche mit 1,5 %"], "c": 0, "e": "Nur 3,5 % liegt über der Grenze von 3,0 %. In den anderen Wochen entscheidet das Team selbst."}, {"q": "Welche Beschreibung passt zu Management by Delegation?", "o": ["Führen durch Übertragen von Aufgaben mit Befugnis", "Führen durch genaue Anweisung jedes Schritts", "Führen nur über Kennzahlen und Grenzen", "Führen durch Abgabe aller Führungsverantwortung"], "c": 0, "e": "Bei MbD werden Aufgaben dauerhaft mit Entscheidungsbefugnis und Verantwortung übertragen. Die Führungsverantwortung bleibt bei der Führungskraft."}, {"q": "Jan Richter überträgt Ewa Nowak die Einteilung der Arbeitsplätze. Welche Verantwortung behält Jan?", "o": ["Die Führungsverantwortung", "Die Handlungsverantwortung", "Gar keine Verantwortung mehr", "Nur die Verantwortung für den Urlaub"], "c": 0, "e": "Ewa trägt die Handlungsverantwortung für die Einteilung. Jan bleibt für Auswahl, Information und gelegentliche Kontrolle verantwortlich."}, {"q": "Was versteht man unter Rückdelegation?", "o": ["Eine übertragene Aufgabe wandert zur Führungskraft zurück", "Die Führungskraft delegiert an ihre eigene Chefin", "Ein Azubi wird an die Berufsschule zurückgeschickt", "Der Betriebsrat gibt eine Aufgabe an die IHK ab"], "c": 0, "e": "Fragt die Person bei jeder Kleinigkeit nach und die Führungskraft entscheidet, ist die Aufgabe zurückdelegiert."}, {"q": "Zu welcher Führungstechnik gehört das Harzburger Modell?", "o": ["Management by Delegation", "Management by Objectives", "Management by Exception", "Management by Walking Around"], "c": 0, "e": "Das Harzburger Modell ist eine deutsche Form der Delegation von Verantwortung mit Stellenbeschreibungen."}, {"q": "Welche Kritik wird am Harzburger Modell häufig geäußert?", "o": ["Es ist bürokratisch und starr", "Es überträgt zu wenig Verantwortung", "Es verbietet jede Stellenbeschreibung", "Es gilt nur für Kleinbetriebe"], "c": 0, "e": "Viele Regeln und viel Papier machten das Modell schwerfällig. Heute gilt es eher als historisches Beispiel."}, {"q": "Welche Vorschrift verlangt die Zustimmung des Betriebsrats zu allgemeinen Beurteilungsgrundsätzen?", "o": ["§ 94 Abs. 2 BetrVG", "§ 82 Abs. 2 BetrVG", "§ 87 Abs. 1 Nr. 10 BetrVG", "§ 167 Abs. 2 SGB IX"], "c": 0, "e": "Allgemeine Beurteilungsgrundsätze brauchen nach § 94 Abs. 2 BetrVG die Zustimmung des Betriebsrats."}, {"q": "Was ist ein Mitarbeitergespräch?", "o": ["Ein geplantes Gespräch mit Anlass, Ziel und Struktur", "Ein zufälliger Plausch in der Kaffeeküche", "Ein Gespräch nur zwischen zwei Kollegen ohne Führung", "Eine Rede der Geschäftsführung auf der Betriebsversammlung"], "c": 0, "e": "Ein Mitarbeitergespräch findet zwischen Führungskraft und Mitarbeitenden statt und ist vorbereitet und strukturiert."}, {"q": "Was ist typischer Inhalt eines Jahresgesprächs?", "o": ["Rückblick, Zusammenarbeit, Entwicklung und neue Ziele", "Nur die Berechnung der Lohnsteuer", "Die Kündigung des Arbeitsverhältnisses", "Die Bestellung neuer Lagerregale"], "c": 0, "e": "Im Jahresgespräch werden das vergangene Jahr, die Zusammenarbeit und die Entwicklung besprochen und oft neue Ziele vereinbart."}, {"q": "Tim Berger kam in zwei Wochen dreimal zu spät zur Spätschicht. Welches Gespräch passt?", "o": ["Kritikgespräch", "Anerkennungsgespräch", "Rückkehrgespräch", "Austrittsgespräch"], "c": 0, "e": "Bei Fehlverhalten führt die Führungskraft ein Kritikgespräch mit dem Ziel, dass sich das Verhalten ändert."}, {"q": "Wie unterscheidet sich ein Kritikgespräch von einer Abmahnung?", "o": ["Die Abmahnung ist eine arbeitsrechtliche Rüge mit Warnung", "Das Kritikgespräch ist immer eine Kündigung", "Die Abmahnung ersetzt jedes Gespräch dauerhaft", "Beim Kritikgespräch entscheidet der Betriebsrat"], "c": 0, "e": "Das Kritikgespräch ist ein Führungsinstrument. Die Abmahnung rügt einen Pflichtverstoß und warnt vor Folgen, mehr dazu am Tag 8."}, {"q": "Zwischen Früh- und Spätschicht gibt es Streit über die Übergabe. Welches Gespräch ist sinnvoll?", "o": ["Konfliktgespräch mit beiden Seiten", "Rückkehrgespräch mit der Frühschicht", "Anerkennungsgespräch mit der Spätschicht", "Zielvereinbarung mit der Geschäftsführung"], "c": 0, "e": "Im Konfliktgespräch hört die Führungskraft beide Seiten an und sucht mit ihnen eine gemeinsame Lösung."}, {"q": "Wann muss der Arbeitgeber ein betriebliches Eingliederungsmanagement anbieten?", "o": ["Bei mehr als sechs Wochen Arbeitsunfähigkeit in zwölf Monaten", "Nach jedem einzelnen Krankheitstag", "Nur bei Arbeitsunfällen im Betrieb", "Erst nach drei Jahren Krankheit"], "c": 0, "e": "Nach § 167 Abs. 2 SGB IX ist das Eingliederungsmanagement anzubieten, wenn Beschäftigte innerhalb eines Jahres länger als sechs Wochen ununterbrochen oder wiederholt arbeitsunfähig sind."}, {"q": "Welche Phasen hat ein Mitarbeitergespräch?", "o": ["Vorbereitung, Durchführung, Nachbereitung", "Planung, Beschaffung, Freistellung", "Bewerbung, Auswahl, Einstellung", "Anhörung, Kündigung, Zeugnis"], "c": 0, "e": "Jedes Gespräch wird vorbereitet, strukturiert durchgeführt und nachbereitet. Die anderen Abfolgen gehören zu anderen Personalthemen."}, {"q": "Wer sollte im Hauptteil des Gesprächs zuerst seine Sicht schildern?", "o": ["Die Mitarbeiterin oder der Mitarbeiter", "Die Führungskraft", "Der Betriebsrat", "Die Personalleitung"], "c": 0, "e": "Wer zuerst die Mitarbeitenden hört, erfährt Ursachen und zeigt Wertschätzung. Danach folgt die Sicht der Führungskraft."}, {"q": "Was ist eine gute Vereinbarung am Ende des Gesprächs?", "o": ["Wer tut was bis wann", "Wir schauen mal, wie es läuft", "Alles bleibt wie bisher", "Die Führungskraft entscheidet später allein"], "c": 0, "e": "Vereinbarungen sollen konkret sein, mit Person, Maßnahme und Termin. Nur so lassen sie sich überprüfen."}, {"q": "Was ist eine Ich-Botschaft?", "o": ["Eine Aussage über die eigene Wahrnehmung und Wirkung", "Ein Vorwurf, der mit Du beginnt", "Ein Lob nur über die eigene Leistung", "Eine schriftliche Mitteilung an die Personalakte"], "c": 0, "e": "Die Ich-Botschaft beschreibt, was ich wahrgenommen habe und wie es auf mich wirkt, ohne die Person anzugreifen."}, {"q": "Welche Aussage ist eine Ich-Botschaft?", "o": ["Ich habe dreimal auf dich gewartet", "Du kommst immer zu spät", "Du bist total unzuverlässig", "Man kann sich auf dich nie verlassen"], "c": 0, "e": "Nur die erste Aussage beschreibt eine eigene Beobachtung. Die anderen bewerten die Person und verallgemeinern."}, {"q": "Wofür stehen die drei W der WWW-Regel?", "o": ["Wahrnehmung, Wirkung, Wunsch", "Wer, was, wann", "Wissen, Wollen, Werden", "Warnung, Wut, Wiedergutmachung"], "c": 0, "e": "Zuerst die Beobachtung, dann die Wirkung auf mich oder das Team, dann der Wunsch für die Zukunft."}, {"q": "Warum sollte man Wörter wie immer und nie im Feedback vermeiden?", "o": ["Sie verallgemeinern und sind meist nicht wahr", "Sie sind im Betrieb gesetzlich verboten", "Sie machen Feedback zu konkret", "Sie gelten als Ich-Botschaften"], "c": 0, "e": "Verallgemeinerungen fordern Widerspruch heraus, weil es fast immer Ausnahmen gibt. Konkrete Beispiele sind überzeugender."}, {"q": "Was ist das Problem der Sandwich-Methode?", "o": ["Das Lob wirkt oft unecht und verliert an Wert", "Sie ist nur in der Gastronomie erlaubt", "Sie enthält keinerlei Kritik", "Sie verlangt eine schriftliche Abmahnung"], "c": 0, "e": "Wird Kritik immer zwischen zwei Lobstücke gepackt, wartet man beim Lob nur noch auf das Aber. Ehrliches Lob und klare Kritik wirken getrennt besser."}, {"q": "Sandra Kowalski sagt zu Tim, „Du bist faul“. Welche Feedback-Regel verletzt sie vor allem?", "o": ["Beschreiben statt bewerten", "Feedback zeitnah geben", "Mit einem Wunsch beginnen", "Feedback schriftlich geben"], "c": 0, "e": "Faul ist eine Bewertung der Person. Besser wäre eine konkrete Beschreibung des Verhaltens mit Ich-Botschaft."}, {"q": "Eine Führungskraft spricht mit einem Mitarbeiter über eine Fortbildung und seinen künftigen beruflichen Weg. Welche Gesprächsart liegt vor?", "o": ["Entwicklungsgespräch", "Konfliktgespräch", "Kritikgespräch", "Rückkehrgespräch"], "c": 0, "e": "Im Entwicklungsgespräch geht es um die berufliche Zukunft und die passende Förderung."}, {"q": "Welche Aufgabe ist eine personenbezogene Führungsaufgabe?", "o": ["Den Produktionsplan für Mai erstellen", "Ergebnisse mit dem Soll vergleichen", "Einen Streit im Team schlichten", "Zwischen zwei Angeboten entscheiden"], "c": 2, "e": "Konflikte lösen betrifft die Menschen und ist deshalb personenbezogen. Planen, kontrollieren und entscheiden sind sachbezogene Aufgaben."}, {"q": "Warum bilden die sachbezogenen Führungsaufgaben einen Kreislauf?", "o": ["Aus jeder Kontrolle ergeben sich neue Ziele", "Jede Aufgabe kommt nur einmal im Jahr vor", "Die Reihenfolge der Schritte ist beliebig", "Die Kontrolle steht immer ganz am Anfang"], "c": 0, "e": "Ziele setzen, planen, entscheiden, übertragen und kontrollieren folgen aufeinander. Das Ergebnis der Kontrolle führt zu neuen Zielen, deshalb schließt sich der Kreis."}, {"q": "Mit welchen Personen führten Lewin, Lippitt und White ihre Versuche durch?", "o": ["Mit Monteuren in einem großen Autowerk", "Mit Ingenieuren und Buchhaltern", "Mit Freizeitgruppen von Jungen", "Mit Studierenden einer Hochschule"], "c": 2, "e": "Lewin und seine Kollegen leiteten 1939 Freizeitgruppen von Jungen auf drei Arten. Ingenieure und Buchhalter hat Herzberg befragt (Lewin et al., 1939)."}, {"q": "Wie wird Lewins demokratischer Stil in deutschen Lehrbüchern meist genannt?", "o": ["Patriarchalisch", "Kooperativ", "Autonom", "Situativ"], "c": 1, "e": "Im Original heißt der Stil demokratisch. In deutschen Lehrbüchern ist die Bezeichnung kooperativ üblich (Beiderwieden & Stickdorn, 2026)."}, {"q": "Für welche Gruppe kann der Laissez-faire-Stil am ehesten passen?", "o": ["Für neue Aushilfen am ersten Arbeitstag", "Für hoch qualifizierte Fachleute mit klarem Ziel", "Für Auszubildende in der ersten Woche", "Für ein Team mitten in einem Notfall"], "c": 1, "e": "Fachleute mit klarem Ziel können sich selbst steuern. Neue Kräfte und Teams im Notfall brauchen dagegen klare Anleitung."}, {"q": "Tannenbaum und Schmidt ordnen Führungsstile auf einem Kontinuum an. Welche Darstellungsform ist mit diesem Wort gemeint?", "o": ["Eine Rangfolge von fünf Bedürfnissen", "Ein Kreislauf mit vier Stationen", "Eine durchgehende Skala zwischen zwei Polen", "Eine Matrix mit vier gleich großen Feldern"], "c": 2, "e": "Ein Kontinuum ist eine stufenlose Skala. Tannenbaum und Schmidt ordnen die Führungsstile darauf zwischen zwei Polen an (Tannenbaum & Schmidt, 1958)."}, {"q": "Wie heißen die beiden Pole des Kontinuums im Original?", "o": ["Aufgabenorientiert und beziehungsorientiert", "Vorgesetztenzentriert und mitarbeiterzentriert", "Intrinsisch und extrinsisch motiviert", "Hygieneorientiert und motivatororientiert"], "c": 1, "e": "Am einen Ende entscheidet die Führungskraft allein, am anderen die Gruppe. Aufgaben- und Beziehungsorientierung sind die Achsen bei Hersey und Blanchard."}, {"q": "Was geschieht beim beratenden Stil, bevor die Führungskraft entscheidet?", "o": ["Sie stellt ihre Absicht vor und hört die Meinungen an", "Das Team entscheidet allein in einem festen Rahmen", "Sie entscheidet ohne jede Information an das Team", "Das Team stimmt ab, und die Mehrheit gilt sofort"], "c": 0, "e": "Beim beratenden Stil informiert die Führungskraft vorher und hört zu. Die Entscheidung trifft sie danach aber selbst."}, {"q": "Welche Stufe liegt im Kontinuum zwischen patriarchalisch und beratend?", "o": ["Kooperativ", "Delegativ", "Informierend", "Autonom"], "c": 2, "e": "Die Reihenfolge lautet autoritär, patriarchalisch, informierend, beratend, kooperativ, delegativ und autonom (Beiderwieden & Stickdorn, 2026)."}, {"q": "Welche Aussage beschreibt den autonomen Stil?", "o": ["Die Führungskraft entscheidet und ordnet an", "Die Führungskraft koordiniert nur noch", "Das Team macht Vorschläge, sie wählt aus", "Sie erklärt ihre Entscheidung und lässt Fragen zu"], "c": 1, "e": "Beim autonomen Stil entscheidet die Gruppe völlig selbst. Die Führungskraft koordiniert nur noch nach innen und außen."}, {"q": "Worauf bezieht sich der Reifegrad nach Hersey und Blanchard?", "o": ["Auf das Lebensalter der Person", "Immer auf eine bestimmte Aufgabe", "Auf die ganze Berufslaufbahn gleich", "Auf die Entgeltgruppe im Tarif"], "c": 1, "e": "Der Reifegrad gilt für eine konkrete Aufgabe. Eine erfahrene Monteurin kann bei einer neuen Software ganz am Anfang stehen (Hersey & Blanchard, 1969)."}, {"q": "Welche Beschreibung passt zum Reifegrad M3?", "o": ["Die Person kann die Aufgabe nicht und ist unsicher", "Die Person will, kann aber noch wenig", "Die Person kann die Aufgabe, ist aber unsicher", "Die Person kann die Aufgabe und will sie auch"], "c": 2, "e": "Bei M3 ist die Fähigkeit hoch, die Bereitschaft oder das Selbstvertrauen aber gering. M1 kann nicht, M2 will, kann aber wenig, M4 kann und will."}, {"q": "Was tut die Führungskraft beim Stil S1 unterweisen?", "o": ["Sie sagt genau, was, wie und wann zu tun ist", "Sie überträgt die Aufgabe und hält sich zurück", "Sie entscheidet gemeinsam mit der Person", "Sie lässt die Person ohne Vorgaben arbeiten"], "c": 0, "e": "S1 bedeutet viel Anweisung und wenig Beziehung. Die Führungskraft gibt genaue Vorgaben, weil die Person die Aufgabe noch nicht kann."}, {"q": "Was versteht man unter Motivation?", "o": ["Die Pflicht, alle Anweisungen auszuführen", "Die Bereitschaft, sich für ein Ziel anzustrengen", "Die Höhe des monatlichen Bruttoentgelts", "Die Anzahl der geleisteten Überstunden"], "c": 1, "e": "Motivation ist die Bereitschaft, sich für ein Ziel einzusetzen. Sie entsteht aus Motiven und lässt sich nicht einfach anordnen (Oechsler & Paul, 2019)."}, {"q": "Was sind Motive?", "o": ["Innere Beweggründe wie der Wunsch nach Sicherheit", "Äußere Vorschriften aus der Arbeitsordnung", "Kennzahlen aus dem Personalcontrolling", "Gesetzliche Pflichten der Beschäftigten"], "c": 0, "e": "Motive sind innere Beweggründe, etwa der Wunsch nach Sicherheit, Anerkennung oder Erfolg. Aus ihnen entsteht Motivation."}, {"q": "Warum muss man äußere Anreize oft immer weiter erhöhen?", "o": ["Sie wirken meist nur, solange sie gezahlt werden", "Sie sind gesetzlich an die Inflation gebunden", "Der Betriebsrat verlangt jedes Jahr mehr", "Sie gelten nach einem Jahr als unzulässig"], "c": 0, "e": "Extrinsische Anreize nutzen sich ab. Ihre Wirkung hält oft nur so lange an, wie sie gezahlt werden (Beiderwieden & Stickdorn, 2026)."}, {"q": "Warum heißt die Selbstverwirklichung bei Maslow Wachstumsbedürfnis?", "o": ["Weil sie als Erstes erfüllt sein muss", "Weil sie nie ganz erfüllt ist", "Weil sie nur bei Kindern vorkommt", "Weil Geld sie vollständig erfüllt"], "c": 1, "e": "Die vier unteren Stufen sind Defizitbedürfnisse. Die Selbstverwirklichung ist nie ganz erfüllt und heißt deshalb Wachstumsbedürfnis."}, {"q": "Welche Stufe ist bei Maslow die vierte von unten?", "o": ["Soziale Bedürfnisse", "Sicherheit", "Wertschätzung", "Selbstverwirklichung"], "c": 2, "e": "Von unten nach oben folgen physiologische Bedürfnisse, Sicherheit, soziale Bedürfnisse, Wertschätzung und Selbstverwirklichung (Maslow, 1943)."}, {"q": "Welche Personen befragten Herzberg, Mausner und Snyderman?", "o": ["Jugendliche in Freizeitgruppen", "Auszubildende im Handwerk", "Ingenieure und Buchhalter", "Offiziere im Militär"], "c": 2, "e": "Herzberg und seine Kollegen fragten Ingenieure und Buchhalter nach besonders guten und schlechten Situationen bei der Arbeit (Herzberg et al., 1959)."}, {"q": "Welcher Zustand entsteht nach Herzberg, wenn alle Hygienefaktoren gut sind?", "o": ["Dauerhafte Begeisterung", "Hohe Leistungsbereitschaft", "Keine Unzufriedenheit", "Echte Zufriedenheit"], "c": 2, "e": "Gute Hygienefaktoren beseitigen nur die Unzufriedenheit. Zufriedenheit und Leistungsbereitschaft entstehen erst durch Motivatoren."}, {"q": "Welche Gestaltung der Arbeit empfahl Herzberg selbst?", "o": ["Job Rotation", "Job Enrichment", "Personalleasing", "Mehr Kontrolle"], "c": 1, "e": "Herzberg empfahl, die Arbeit inhaltlich anzureichern. Das ist Job Enrichment, das am sechsten Kurstag behandelt wurde."}, {"q": "Wie sieht Theorie Y die Arbeit für den Menschen?", "o": ["Als reine Last, die man meidet", "So natürlich wie Spiel und Ruhe", "Nur mit Strafe erträglich", "Allein als Mittel zum Gelderwerb"], "c": 1, "e": "Nach Theorie Y ist Arbeit für den Menschen etwas Natürliches. Er will leisten und übernimmt Verantwortung (McGregor, 1960)."}, {"q": "Welches Menschenbild hielt McGregor selbst für zutreffender?", "o": ["Theorie X", "Theorie Y", "Einen Mittelweg aus X und Y", "Das Bild von Kurt Lewin"], "c": 1, "e": "McGregor hielt Theorie Y für das passendere Bild der meisten Menschen. Kontrolle gibt es auch dort, aber vor allem über Ergebnisse."}, {"q": "Wie wird bei Theorie Y vor allem kontrolliert?", "o": ["Gar nicht, denn Ziele gibt es nicht", "Durch Rundgänge zu jeder vollen Stunde", "Durch Strafen bei jedem kleinen Fehler", "Über Ergebnisse statt durch Dauerbeobachtung"], "c": 3, "e": "Auch bei Theorie Y gibt es Ziele und Rückmeldung. Die Kontrolle richtet sich aber auf Ergebnisse und nicht auf ständige Aufsicht."}, {"q": "Wofür steht die Abkürzung MbE?", "o": ["Management by Evaluation", "Management by Education", "Management by Exception", "Management by Experience"], "c": 2, "e": "MbE steht für Management by Exception, also Führen nach dem Ausnahmeprinzip."}, {"q": "Wie lautet die deutsche Bezeichnung für Management by Delegation?", "o": ["Führen durch vereinbarte Ziele", "Führen durch Übertragen von Aufgaben", "Führen nach dem Ausnahmeprinzip", "Führen durch ständige Kontrolle"], "c": 1, "e": "Bei Management by Delegation gibt die Führungskraft Aufgaben dauerhaft ab, zusammen mit Befugnis und Verantwortung."}, {"q": "Was geschieht im Zwischengespräch bei Management by Objectives?", "o": ["Der Stand wird geprüft und bei Bedarf nachgesteuert", "Die Prämie für das Jahr wird sofort ausgezahlt", "Die Ziele werden zum ersten Mal festgelegt", "Die Beurteilung wird endgültig unterschrieben"], "c": 0, "e": "Im Lauf des Jahres prüfen beide Seiten, wie weit die Ziele erreicht sind. Bei Bedarf wird nachgesteuert, die Zielkontrolle folgt am Jahresende."}, {"q": "Wie ergibt sich der gewichtete Gesamtwert mehrerer Ziele?", "o": ["Alle Sollwerte werden addiert und halbiert", "Jede Zielerreichung mal Gewicht, dann addieren", "Nur das schlechteste Ziel wird gezählt", "Alle Gewichte werden miteinander multipliziert"], "c": 1, "e": "Jeder Zielerreichungsgrad wird mit seinem Gewicht multipliziert. Die Ergebnisse werden zum Gesamtwert addiert (Beiderwieden & Stickdorn, 2026)."}, {"q": "Warum begrenzen manche Betriebe die Zielerreichung je Ziel nach oben?", "o": ["Weil ein Gesetz das so vorschreibt", "Damit ein Ziel nicht alle anderen ausgleicht", "Damit niemand mehr Entgelt erhält", "Weil Ziele sonst nicht messbar wären"], "c": 1, "e": "Eine Obergrenze, etwa 120 %, verhindert, dass ein stark übererfülltes Ziel die schwachen Ziele verdeckt."}, {"q": "Welche Art von Ziel ist eine vereinbarte Schulung im neuen Kundenprogramm?", "o": ["Ein reines Umsatzziel", "Ein Entwicklungsziel", "Eine Toleranzgrenze", "Eine Zielvorgabe"], "c": 1, "e": "Neben Leistungszielen gibt es Entwicklungsziele. Eine Schulung entwickelt die Fähigkeiten der Person weiter."}, {"q": "Was passiert, wenn bei Management by Exception die Toleranzgrenzen zu eng sind?", "o": ["Probleme werden zu spät erkannt", "Die Führungskraft muss ständig eingreifen", "Die Mitarbeitenden haben mehr Freiraum", "Die Grenzen werden nie überschritten"], "c": 1, "e": "Zu enge Grenzen werden dauernd überschritten, und die Führungskraft wird nicht entlastet. Zu weite Grenzen führen dazu, dass Probleme zu spät auffallen."}, {"q": "Was bedeutet Kompetenz bei der Delegation?", "o": ["Das Fachwissen aus der Ausbildung", "Die Befugnis, selbst zu entscheiden", "Die Pflicht, für das Ergebnis einzustehen", "Die genaue Beschreibung der Aufgabe"], "c": 1, "e": "Kompetenz meint hier die Befugnis. Die Aufgabe sagt, was zu tun ist, die Verantwortung, wofür man einsteht."}, {"q": "Wo wurde das Harzburger Modell entwickelt?", "o": ["An einer Hochschule in den USA", "In einem Autowerk in Japan", "An einer Akademie in Bad Harzburg", "Im Bundesministerium für Arbeit"], "c": 2, "e": "Das Modell stammt von einer Führungsakademie in Bad Harzburg. Es war vor allem in den sechziger und siebziger Jahren verbreitet (Oechsler & Paul, 2019)."}, {"q": "Was ist mit Führen durch Präsenz vor Ort gemeint?", "o": ["Die Führungskraft arbeitet nur im Homeoffice", "Sie kommt regelmäßig an die Arbeitsplätze und hört zu", "Sie meldet sich nur bei großen Abweichungen", "Sie lässt die Anwesenheit elektronisch erfassen"], "c": 1, "e": "Bei diesem Instrument ist die Führungskraft sichtbar. Sie schaut regelmäßig an den Arbeitsplätzen vorbei und hört den Beschäftigten zu (Oechsler & Paul, 2019)."}, {"q": "Wofür hat der Betriebsrat nach § 87 Abs. 1 Nr. 10 BetrVG ein Mitbestimmungsrecht?", "o": ["Für die Wahl der Geschäftsführung", "Für die Höhe der Lohnsteuer", "Für Grundsätze der Lohngestaltung", "Für die Preise der Produkte"], "c": 2, "e": "Hängt eine Prämie von Zielen ab, geht es um Grundsätze der betrieblichen Lohngestaltung. Dafür hat der Betriebsrat ein Mitbestimmungsrecht."}, {"q": "Welches Recht gibt § 83 Abs. 1 BetrVG den Beschäftigten?", "o": ["Sie dürfen ihre Personalakte einsehen", "Sie dürfen ihre Ziele allein festlegen", "Sie dürfen jede Beurteilung ablehnen", "Sie dürfen den Vorgesetzten auswählen"], "c": 0, "e": "Beschäftigte haben das Recht, ihre Personalakte einzusehen. Dort liegen zum Beispiel Protokolle von Zielvereinbarungen."}, {"q": "Was gehört zum Abschluss eines Mitarbeitergesprächs?", "o": ["Neue Vorwürfe sammeln", "Den Raum für das Gespräch buchen", "Ergebnisse zusammenfassen und Prüftermin klären", "Die Sicht der Person zum ersten Mal hören"], "c": 2, "e": "Am Ende werden die Ergebnisse zusammengefasst, ein Termin zur Überprüfung festgelegt, und das Gespräch endet positiv."}, {"q": "Warum notiert die Führungskraft vor einem Kritikgespräch Beispiele mit Datum?", "o": ["Damit sie später eine Strafe festlegen kann", "Damit sie konkret beschreiben kann", "Weil das Gesetz eine Liste verlangt", "Damit das Gespräch kürzer wird"], "c": 1, "e": "Konkrete Beispiele mit Datum helfen, sachlich zu beschreiben statt zu verallgemeinern. So kann die Person das Verhalten nachvollziehen."}, {"q": "Warum führt eine Du-Botschaft oft zu Abwehr?", "o": ["Sie ist zu freundlich formuliert", "Sie greift die Person selbst an", "Sie nennt einen konkreten Wunsch", "Sie beschreibt nur eigene Gefühle"], "c": 1, "e": "Du-Botschaften wie „Du bist unzuverlässig“ bewerten die Person. Darauf reagieren Menschen mit Rechtfertigung oder Abwehr."}, {"q": "Worauf soll sich Feedback beziehen?", "o": ["Auf Verhalten, das die Person ändern kann", "Auf die Herkunft der Person", "Auf feste Charaktereigenschaften", "Auf das Aussehen der Person"], "c": 0, "e": "Feedback hilft nur, wenn die Person etwas ändern kann. Deshalb bezieht es sich auf Verhalten und nicht auf Eigenschaften."}, {"q": "Warum gilt Feedback als Geschenk?", "o": ["Weil es immer nur Lob enthält", "Weil es zeigt, was man selbst nicht sieht", "Weil man es nicht beachten muss", "Weil es mit einer Prämie verbunden ist"], "c": 1, "e": "Rückmeldung zeigt, wie das eigene Verhalten auf andere wirkt. Das kann man selbst oft nicht erkennen (Oechsler & Paul, 2019)."}, {"q": "Was bedeutet beim Beobachtungsbogen im Rollenspiel die Bewertung null?", "o": ["Sehr gut gelungen", "Gut gelungen", "Teilweise erfüllt", "Fehlt völlig"], "c": 2, "e": "Die Skala lautet plus plus für sehr gut, plus für gut, null für teilweise und minus für fehlt."}, {"q": "Sandra Kowalski gibt einer neuen Lageraushilfe bei Nordstern am ersten Tag keine Einweisung. Wie ist das zu beurteilen?", "o": ["Unpassend, die Aushilfe braucht S1 unterweisen", "Passend, Aushilfen lernen am besten allein", "Passend, denn Laissez-faire motiviert immer", "Unpassend, die Aushilfe braucht S4 delegieren"], "c": 0, "e": "Die Aushilfe kann die Aufgabe noch nicht und ist unsicher, also Reifegrad M1. Sie braucht genaue Anweisungen nach Stil S1."}, {"q": "Sven Krüger macht die Entgeltabrechnung bei Nordstern seit zehn Jahren fehlerfrei und gern. Welcher Stil passt bei dieser Aufgabe?", "o": ["S1 unterweisen", "S2 überzeugen", "S3 beteiligen", "S4 delegieren"], "c": 3, "e": "Sven kann und will, das ist Reifegrad M4. Die Führungskraft kann die Aufgabe übertragen und sich zurückhalten."}, {"q": "Bei Nordstern gibt es Gerüchte über einen Stellenabbau in der Vormontage. Welche Stufe nach Maslow ist vor allem betroffen?", "o": ["Wertschätzung", "Sicherheit", "Selbstverwirklichung", "Soziale Bedürfnisse"], "c": 1, "e": "Die Angst um den Arbeitsplatz betrifft das Bedürfnis nach Sicherheit. Bei Herzberg ist die Arbeitsplatzsicherheit ein Hygienefaktor."}, {"q": "In der Lackiererei von Nordstern klagen viele über Lärm. Was bewirkt ein besserer Lärmschutz nach Herzberg?", "o": ["Er verringert die Unzufriedenheit", "Er erzeugt dauerhafte Begeisterung", "Er ersetzt jede Form von Lob", "Er wirkt als stärkster Motivator"], "c": 0, "e": "Arbeitsbedingungen sind ein Hygienefaktor. Bessere Bedingungen beseitigen Unzufriedenheit, erzeugen aber noch keine Motivation."}, {"q": "Ein Meister bei Nordstern misstraut seinem Team und prüft jede Pause mit der Stoppuhr. Was ist nach McGregor zu erwarten?", "o": ["Mehr Eigeninitiative im Team", "Dienst nach Vorschrift im Team", "Höhere Bereitschaft zur Verantwortung", "Mehr Vorschläge zur Verbesserung"], "c": 1, "e": "Strenge Kontrolle aus Misstrauen führt oft dazu, dass nur noch das Nötigste getan wird. Das bestätigt scheinbar das Misstrauen."}, {"q": "Für Mia Schulz wird bei Nordstern das Ziel „Bis 31.03.2027 besser telefonieren“ notiert. Welches SMART-Merkmal fehlt vor allem?", "o": ["Terminiert", "Messbar", "Realistisch", "Attraktiv"], "c": 1, "e": "Ein Datum ist genannt. Es fehlt aber eine Zahl oder ein klares Merkmal, an dem man das Ergebnis messen kann."}, {"q": "Welche Zielformulierung für das Lager von Nordstern ist SMART?", "o": ["Das Lager arbeitet künftig deutlich fehlerfreier", "Die Fehler im Lager sollen bald spürbar sinken", "Die Kommissionierfehler sinken bis 30.09.2027 von 1,2 % auf 0,8 %", "Bis Ende 2027 soll das Lager einfach besser werden"], "c": 2, "e": "Nur dieses Ziel nennt eine klare Messgröße, Ausgangs- und Zielwert sowie einen Termin."}, {"q": "Lisa Wagner soll 2027 bei Nordstern 60 neue Fachhändler gewinnen, im Vorjahr waren es 8. Welches SMART-Merkmal ist gefährdet?", "o": ["Spezifisch", "Messbar", "Terminiert", "Realistisch"], "c": 3, "e": "Ein Sprung von 8 auf 60 ist kaum zu schaffen. Ein unrealistisches Ziel führt zu Frust statt zu Motivation."}, {"q": "Lisa Wagner beantwortet 76 % der Händleranfragen rechtzeitig, das Soll liegt bei 95 %. Wie hoch ist der Zielerreichungsgrad?", "o": ["19 %", "76 %", "80 %", "125 %"], "c": 2, "e": "76 ÷ 95 × 100 = 80 %. Man teilt den Istwert durch den Sollwert, nicht den Abstand."}, {"q": "Ein Ziel ist zu 80 % erreicht und hat ein Gewicht von 30 %. Wie viele Prozentpunkte trägt es zum Gesamtwert bei?", "o": ["24 Prozentpunkte", "50 Prozentpunkte", "110 Prozentpunkte", "2,4 Prozentpunkte"], "c": 0, "e": "Gewichteter Beitrag = 0,30 × 80 = 24 Prozentpunkte."}, {"q": "Frank Meier hat mit einer Mitarbeiterin zwei Ziele vereinbart. Ziel 1 ist zu 80 % erreicht (Gewicht 60 %), Ziel 2 zu 110 % (Gewicht 40 %). Wie hoch ist der Gesamtwert?", "o": ["88 %", "90 %", "92 %", "95 %"], "c": 2, "e": "0,60 × 80 = 48 und 0,40 × 110 = 44. Gesamtwert 48 + 44 = 92 %."}, {"q": "In einer Zielvereinbarung haben zwei Ziele die Gewichte 45 % und 35 %. Welches Gewicht muss das dritte Ziel haben?", "o": ["10 %", "20 %", "25 %", "35 %"], "c": 1, "e": "Die Gewichte ergeben zusammen 100 %. Also 100 − 45 − 35 = 20 %."}, {"q": "Ein Mitarbeiter erreicht drei Ziele zu 90 %, 100 % und 60 %. Die Gewichte sind 50 %, 25 % und 25 %. Wie hoch ist der Gesamtwert?", "o": ["85 %", "83,3 %", "80 %", "90 %"], "c": 0, "e": "0,50 × 90 = 45, 0,25 × 100 = 25 und 0,25 × 60 = 15. Gesamtwert 45 + 25 + 15 = 85 %. Der einfache Durchschnitt von 83,3 % beachtet die Gewichte nicht."}, {"q": "Lisa Wagner hat das Soll von 12 Fachhändlern. Wie viele Händler muss sie mindestens gewinnen, um bei diesem Ziel wenigstens 90 % zu erreichen?", "o": ["9", "10", "11", "12"], "c": 2, "e": "90 % von 12 sind 10,8 Händler. Halbe Verträge gibt es nicht, also braucht sie mindestens 11. Das sind 11 ÷ 12 × 100 = 91,67 %."}, {"q": "Bei Nordstern gibt es eine Zielprämie erst ab 90 % Gesamtzielerreichung. Eine Mitarbeiterin erreicht 87,5 %. Was folgt daraus?", "o": ["Sie erhält keine Prämie", "Sie erhält die volle Prämie", "Sie erhält die halbe Prämie", "Die Prämie wird auf 90 % aufgerundet"], "c": 0, "e": "87,5 % liegen unter der Schwelle von 90 %. Deshalb wird nach dieser Regel keine Prämie gezahlt."}, {"q": "In einer Woche werden in der Montage 480 Räder montiert und 12 nachgearbeitet. Die Grenze liegt bei 3,0 %. Was ist richtig?", "o": ["Quote 2,5 %, kein Eingreifen nötig", "Quote 2,5 %, Eingreifen nötig", "Quote 4,0 %, Eingreifen nötig", "Quote 0,4 %, kein Eingreifen nötig"], "c": 0, "e": "12 ÷ 480 × 100 = 2,5 %. Die Grenze von 3,0 % ist nicht überschritten, Jan Richter bleibt im Hintergrund."}, {"q": "In einer Woche werden 640 Räder montiert. Die Grenze für Nacharbeit liegt bei 3,0 %. Ab wie vielen nachgearbeiteten Rädern ist sie überschritten?", "o": ["19", "20", "22", "30"], "c": 1, "e": "3,0 % von 640 sind 19,2 Räder. Bei 19 Rädern liegt die Quote bei 2,97 %, bei 20 Rädern bei 3,13 %. Ab 20 Rädern ist die Grenze überschritten."}, {"q": "Im Lager von Nordstern wird Sandra Kowalski informiert, wenn die Bestandsabweichung über 0,5 % liegt. Bei 8.000 Teilen im Soll fehlen 48 Teile. Was folgt?", "o": ["Quote 0,48 %, keine Meldung", "Quote 0,6 %, Sandra wird informiert", "Quote 6,0 %, keine Meldung", "Quote 0,06 %, Sandra wird informiert"], "c": 1, "e": "48 ÷ 8.000 × 100 = 0,6 %. Die Grenze von 0,5 % ist überschritten, also muss Sandra Kowalski informiert werden."}, {"q": "Jan Richter meldet sich in der Montage von Nordstern nur, wenn die Nacharbeitsquote über der Grenze liegt. Was sollte er zusätzlich tun?", "o": ["Die Grenze auf 0,5 % senken", "Gute Wochen kurz anerkennen", "Jede Station stündlich prüfen", "Die Kennzahl nicht mehr messen"], "c": 1, "e": "Wer nur bei Problemen auftaucht, wird mit Fehlern verbunden. Ein kurzes Lob in guten Wochen stärkt den Motivator Anerkennung."}, {"q": "Ewa Nowak fragt Jan Richter bei jeder Kleinigkeit zur Einteilung der Stationen, und Jan entscheidet dann selbst. Was sollte Jan tun?", "o": ["Ewa ermutigen und die Entscheidung bei ihr lassen", "Die Einteilung wieder dauerhaft selbst übernehmen", "Ewa eine Abmahnung wegen der Fragen erteilen", "Die Aufgabe ohne Gespräch an Paul weitergeben"], "c": 0, "e": "Es droht eine Rückdelegation. Jan sollte Ewa ermutigen und die Entscheidung bei ihr lassen (Beiderwieden & Stickdorn, 2026)."}, {"q": "Malte Brandt überträgt Jana Hoffmann die Organisation der Bewerbertage 2027. Sie darf aber weder Räume buchen noch Geld freigeben. Was fehlt?", "o": ["Die Aufgabe", "Die Kompetenz", "Die Motivation", "Die Stellenbeschreibung"], "c": 1, "e": "Jana hat eine Aufgabe, aber keine Befugnis zum Entscheiden. Ohne Kompetenz kann sie keine Verantwortung tragen, die Delegation ist unvollständig."}, {"q": "Sandra Kowalski legt fest, dass das Lagerteam von Nordstern im Normalfall selbst entscheidet und sie nur bei festen Grenzwerten eingreift. Welche Technik nutzt sie?", "o": ["Management by Objectives", "Management by Delegation", "Management by Exception", "Das Harzburger Modell"], "c": 2, "e": "Eingreifen nur bei Überschreitung vorher festgelegter Grenzen ist das Ausnahmeprinzip."}, {"q": "Tim Berger möchte das Protokoll seines Kritikgesprächs in seiner Personalakte bei Nordstern lesen. Was gilt?", "o": ["Das ist nur mit Zustimmung der Teamleitung erlaubt", "Er darf seine Personalakte einsehen", "Das ist erst nach dem Ausscheiden möglich", "Er darf nur die Zeugnisse sehen"], "c": 1, "e": "Beschäftigte haben das Recht, ihre Personalakte einzusehen (§ 83 Abs. 1 BetrVG)."}, {"q": "Paul Neumann war innerhalb von zwölf Monaten 3 Wochen im Februar und 4 Wochen im Oktober arbeitsunfähig. Was muss Nordstern tun?", "o": ["Nichts, weil es keine sechs Wochen am Stück waren", "Ein betriebliches Eingliederungsmanagement anbieten", "Paul sofort nach seiner Diagnose fragen", "Paul eine Abmahnung wegen der Fehlzeit geben"], "c": 1, "e": "Zusammen sind es 7 Wochen und damit mehr als sechs Wochen wiederholte Arbeitsunfähigkeit in einem Jahr. Dann ist ein Eingliederungsmanagement anzubieten (§ 167 Abs. 2 SGB IX)."}, {"q": "Jonas Petersen war in den letzten zwölf Monaten insgesamt 5 Wochen krank. Was ist bei Nordstern sinnvoll?", "o": ["Ein Rückkehrgespräch ohne Frage nach der Diagnose", "Ein Eingliederungsmanagement ist schon Pflicht", "Ein Gespräch nur in Anwesenheit des Arztes", "Ein Kritikgespräch wegen der Fehlzeiten"], "c": 0, "e": "5 Wochen liegen unter der Schwelle von sechs Wochen. Ein Rückkehrgespräch erleichtert trotzdem den Wiedereinstieg, nach der Diagnose wird nicht gefragt."}, {"q": "Sven Krüger hat die Umstellung der Entgeltabrechnung bei Nordstern fehlerfrei und vor dem Termin geschafft. Welches Gespräch passt?", "o": ["Kritikgespräch", "Konfliktgespräch", "Anerkennungsgespräch", "Rückkehrgespräch"], "c": 2, "e": "Eine besondere Leistung wird im Anerkennungsgespräch gewürdigt, am besten konkret und zeitnah."}, {"q": "Jonas Petersen und Paul Neumann streiten seit Tagen an ihrer Station über die Reihenfolge der Arbeitsschritte. Wie geht Jan Richter am besten vor?", "o": ["Er hört Jonas und Paul an und sucht mit ihnen eine Lösung", "Er führt mit Paul allein ein Kritikgespräch", "Er wartet ab, bis sich der Streit selbst löst", "Er versetzt die zwei ohne Gespräch in andere Teams"], "c": 0, "e": "Bei Streit zwischen Personen passt das Konfliktgespräch. Die Führungskraft hört beide Seiten an und erarbeitet mit ihnen eine Lösung."}, {"q": "Sandra Kowalski beginnt ein Kritikgespräch mit Tim Berger, indem sie zehn Minuten lang ihre eigene Sicht schildert. Welcher Fehler liegt vor?", "o": ["Das Gespräch findet unter vier Augen statt", "Tim sollte zuerst seine Sicht schildern", "Sie hat konkrete Beispiele vorbereitet", "Sie nennt den Anlass zu Beginn"], "c": 1, "e": "Im Hauptteil kommt zuerst die Mitarbeiterin oder der Mitarbeiter zu Wort. So erfährt die Führungskraft Ursachen, an die sie nicht gedacht hat."}, {"q": "Welche Rückmeldung an Leon Becker folgt bei Nordstern der WWW-Regel?", "o": ["„Du bist bei Bestellungen viel zu schlampig.“", "„Du machst ständig Fehler, das nervt alle.“", "„Ich sah zwei falsche Mengen, das kostet Zeit, prüf bitte vor dem Senden.“", "„Mach das einfach in Zukunft besser.“"], "c": 2, "e": "Die richtige Antwort nennt Wahrnehmung, Wirkung und Wunsch. Die anderen bewerten die Person oder bleiben unkonkret."}, {"q": "Frank Meier sagt zu Lisa Wagner „Super Folien, leider waren die Zahlen falsch, aber tolle Farben“. Welches Problem hat diese Rückmeldung?", "o": ["Das Lob wirkt unecht und verliert an Wert", "Die Kritik ist zu konkret beschrieben", "Die Rückmeldung ist eine Ich-Botschaft", "Die Rückmeldung kommt zu spät"], "c": 0, "e": "Das ist die Sandwich-Methode. Die Kritik wird zwischen Lob versteckt, das Lob wirkt dadurch unecht. Besser sind ehrliche Anerkennung und klare Kritik jeweils für sich."}, {"q": "Lisa Wagner erhält von einer Kollegin eine kritische Rückmeldung zu ihrer Präsentation. Wie verhält sie sich richtig?", "o": ["Sie hört ruhig zu und fragt bei Unklarem nach", "Sie erklärt sofort, warum alles richtig war", "Sie gibt sofort eine Gegenkritik zurück", "Sie beendet das Gespräch ohne ein Wort"], "c": 0, "e": "Feedback nimmt man an, indem man zuhört, nachfragt und sich bedankt. Ob man den Hinweis umsetzt, entscheidet man danach in Ruhe."}, {"q": "Im Rollenspiel zu Fall A bei Nordstern beobachtet eine dritte Person das Gespräch. Was ist ihre Aufgabe?", "o": ["Mit dem Bogen beobachten und danach Rückmeldung geben", "Das Gespräch unterbrechen, sobald ein Fehler passiert", "Die Rolle der Teamleitung ab der Hälfte übernehmen", "Eine Note für die Klausur des Kurses vergeben"], "c": 0, "e": "Die beobachtende Person füllt den Bogen aus und gibt nach dem Gespräch fünf Minuten Rückmeldung nach den Feedback-Regeln."}], "lernen": [{"t": "Personalführung", "x": "Zielgerichtete Beeinflussung des Verhaltens von Mitarbeitenden, damit die Unternehmensziele erreicht werden."}, {"t": "Führungsstil", "x": "Typisches, wiederkehrendes Verhalten einer Führungskraft gegenüber ihren Mitarbeitenden."}, {"t": "Kooperativer Führungsstil", "x": "Die Führungskraft beteiligt die Mitarbeitenden an Entscheidungen und bespricht Ziele mit ihnen."}, {"t": "Laissez-faire", "x": "Führungsstil, bei dem die Führungskraft kaum eingreift und wenig Ziele vorgibt, wörtlich machen lassen."}, {"t": "Reifegrad", "x": "Fähigkeit und Bereitschaft einer Person für eine bestimmte Aufgabe, Grundlage des situativen Führens."}, {"t": "Hygienefaktoren", "x": "Faktoren wie Entgelt oder Arbeitsbedingungen, die Unzufriedenheit verhindern, aber nicht motivieren."}, {"t": "Motivatoren", "x": "Faktoren wie Anerkennung oder Verantwortung, die Zufriedenheit und Leistungsbereitschaft erzeugen."}, {"t": "Intrinsische Motivation", "x": "Antrieb, der aus der Tätigkeit selbst entsteht, etwa aus Freude oder Interesse."}, {"t": "Theorie X und Y", "x": "Zwei Menschenbilder nach McGregor, X unterstellt Arbeitsunlust, Y Leistungswillen und Verantwortungsbereitschaft."}, {"t": "Management by Objectives", "x": "Führen durch vereinbarte Ziele, der Weg zum Ziel bleibt den Mitarbeitenden überlassen."}, {"t": "SMART", "x": "Regel für gute Ziele, spezifisch, messbar, attraktiv, realistisch und terminiert."}, {"t": "Management by Exception", "x": "Führen nach dem Ausnahmeprinzip, die Führungskraft greift nur bei Überschreitung von Toleranzgrenzen ein."}, {"t": "Management by Delegation", "x": "Führen durch Übertragen von Aufgabe, Kompetenz und Verantwortung."}, {"t": "Ich-Botschaft", "x": "Rückmeldung, die die eigene Wahrnehmung und Wirkung beschreibt, statt die andere Person anzugreifen."}, {"t": "Patriarchalischer Führungsstil", "x": "Strenger, aber väterlich wohlwollender Stil. Die Führungskraft sorgt für ihre Leute, erwartet Treue und gibt keine Entscheidungen ab."}, {"t": "Bürokratischer Führungsstil", "x": "Führung vor allem über Regeln, Stellenbeschreibungen und schriftliche Berichte. Der Betrieb wirkt wie ein Apparat."}, {"t": "Defizitbedürfnisse", "x": "Bedürfnisse, deren Fehlen als Mangel spürbar ist. Ist der Mangel beseitigt, treiben sie kaum noch an."}, {"t": "Entwicklungsgespräch", "x": "Gespräch über den künftigen beruflichen Weg, etwa über Fortbildung, neue Aufgaben oder Aufstieg."}, {"t": "Personalführung", "x": "Personalführung ist die zielgerichtete Beeinflussung des Verhaltens von Mitarbeitenden, damit die Ziele des Unternehmens erreicht werden (Beiderwieden & Stickdorn, 2026)."}, {"t": "Führungsstil", "x": "Ein Führungsstil ist die grundlegende und dauerhafte Art, wie eine Führungskraft informiert, beurteilt, fördert, motiviert, delegiert, Ziele setzt, kontrolliert und entscheidet (Beiderwieden & Stickdorn, 2026)."}, {"t": "Intrinsisch und extrinsisch", "x": "Intrinsische Motivation entsteht aus der Tätigkeit selbst. Extrinsische Motivation entsteht durch Anreize von außen, etwa Entgelt, Lob oder Strafe (Oechsler & Paul, 2019)."}, {"t": "Zwei getrennte Skalen", "x": "Hygienefaktoren bewegen sich zwischen Unzufriedenheit und Nicht-Unzufriedenheit. Motivatoren bewegen sich zwischen Nicht-Zufriedenheit und Zufriedenheit. Wer nur die Hygienefaktoren verbessert, erreicht keine echte Zufriedenheit."}, {"t": "Menschenbild wirkt", "x": "Wie eine Führungskraft über Menschen denkt, bestimmt, wie sie führt. Misstrauen erzeugt oft genau das Verhalten, das man befürchtet."}, {"t": "Fünf Regeln für gute Führung", "x": "Stil anpassen, Hygienefaktoren sichern, Motivatoren schaffen, Vertrauen zeigen, Ziele vereinbaren und regelmäßig sprechen."}, {"t": "Führungstechnik", "x": "Eine Führungstechnik ist ein Verfahren, mit dem Führungskräfte ihre Mitarbeitenden planmäßig steuern, etwa über Ziele, Ausnahmen oder übertragene Aufgaben (Beiderwieden & Stickdorn, 2026)."}, {"t": "Vereinbaren statt vorgeben", "x": "Ein Ziel, an dem die Mitarbeitenden mitgewirkt haben, wird eher angenommen und mit mehr Einsatz verfolgt als ein Ziel, das nur verkündet wird."}, {"t": "Checkliste Zielvereinbarungsgespräch", "x": "Vorher, sind Unternehmensziele, Ist-Stand und Stellenbeschreibung bekannt? Sind Termin, Raum und Unterlagen vereinbart? Im Gespräch, wurde die Sicht des Mitarbeitenden gehört? Ist jedes Ziel SMART? Sind Mittel, Weiterbildung und Meilensteine geklärt? Nachher, ist die Vereinbarung schriftlich festgehalten und das Zwischengespräch terminiert?"}, {"t": "Zuerst zuhören", "x": "Im Hauptteil kommen zuerst die Mitarbeitenden zu Wort. Wer zuerst zuhört, erfährt Ursachen, an die er selbst nicht gedacht hat, und zeigt Wertschätzung."}], "sortier": [{"titel": "Herzberg im Betrieb", "auftrag": "Entscheide für jede Maßnahme, ob sie nach Herzberg Unzufriedenheit verhindert oder motiviert.", "kategorien": [{"id": "a", "name": "Hygienefaktor"}, {"id": "b", "name": "Motivator"}], "items": [{"text": "Neuer Pausenraum in der Montage", "kat": "a", "expl": "Bessere Arbeitsbedingungen verhindern Unzufriedenheit. Sie motivieren aber nicht dauerhaft."}, {"text": "Tariferhöhung im Metalltarif", "kat": "a", "expl": "Entgelt ist nach Herzberg ein Hygienefaktor."}, {"text": "Unbefristeter Vertrag statt Befristung", "kat": "a", "expl": "Ein sicherer Arbeitsplatz verhindert Unzufriedenheit. Er ist ein Hygienefaktor."}, {"text": "Gutes Verhältnis zur Teamleitung", "kat": "a", "expl": "Die Beziehung zur Führung zählt zu den Hygienefaktoren."}, {"text": "Neue Kantine für alle Beschäftigten", "kat": "a", "expl": "Auch das ist eine Arbeitsbedingung. Sie verhindert Unzufriedenheit."}, {"text": "Klare und faire Unternehmenspolitik", "kat": "a", "expl": "Die Unternehmenspolitik ist nach Herzberg ein Hygienefaktor."}, {"text": "Ewa Nowak übernimmt die Einarbeitung neuer Kollegen", "kat": "b", "expl": "Mehr Verantwortung erzeugt echte Zufriedenheit. Sie ist ein Motivator."}, {"text": "Lob der Geschäftsführerin für das Lastenrad-Team", "kat": "b", "expl": "Anerkennung ist ein Motivator."}, {"text": "Eigenes Projekt mit Verantwortung", "kat": "b", "expl": "Verantwortung motiviert von innen. Sie ist ein Motivator."}, {"text": "Aufstieg vom Facharbeiter zur Teamleitung", "kat": "b", "expl": "Aufstieg und Entwicklung zählen zu den Motivatoren."}, {"text": "Interessante und abwechslungsreiche Aufgaben", "kat": "b", "expl": "Ein spannender Arbeitsinhalt ist ein Motivator."}, {"text": "Erfolgserlebnis, das Team schafft den Liefertermin", "kat": "b", "expl": "Leistung und Erfolg sind nach Herzberg Motivatoren."}]}, {"titel": "Welche Führungstechnik steckt dahinter?", "auftrag": "Ordne jede Aussage der passenden Führungstechnik zu.", "kategorien": [{"id": "a", "name": "MbO, Ziele"}, {"id": "b", "name": "MbE, Ausnahmen"}, {"id": "c", "name": "MbD, Delegation"}], "items": [{"text": "Lisa soll bis 31.12.2027 zwölf neue Fachhändler gewinnen", "kat": "a", "expl": "Das ist ein vereinbartes Ziel mit Zahl und Termin. Das ist Management by Objectives."}, {"text": "Führungskraft und Mitarbeiterin vereinbaren SMART-Ziele", "kat": "a", "expl": "Führen über vereinbarte Ziele ist der Kern von MbO."}, {"text": "Der Weg zum Ziel bleibt der Person überlassen", "kat": "a", "expl": "Bei MbO zählt das Ergebnis. Wie es erreicht wird, entscheidet die Person."}, {"text": "Zielerreichungsgrad gleich Ist ÷ Soll × 100", "kat": "a", "expl": "Mit dieser Formel prüft man am Jahresende die vereinbarten Ziele."}, {"text": "Nachteil, es zählt oft nur, was messbar ist", "kat": "a", "expl": "Weil Ziele messbar sein sollen, geraten andere Aufgaben aus dem Blick. Das ist ein Nachteil von MbO."}, {"text": "Teamleitung greift erst ab 3,0 % Nacharbeit ein", "kat": "b", "expl": "Unter der Grenze läuft alles allein. Eingreifen nur bei Abweichung ist MbE."}, {"text": "Toleranzgrenzen werden vorher festgelegt", "kat": "b", "expl": "Ohne feste Grenzen weiß niemand, wann die Ausnahme beginnt. Das gehört zu MbE."}, {"text": "Brandt greift nur ein, wenn ein Team das Budget deutlich überschreitet", "kat": "b", "expl": "Die Führung handelt nur im Ausnahmefall. Das ist Management by Exception."}, {"text": "Woche 3 mit 3,5 % Nacharbeit löst ein Eingreifen aus", "kat": "b", "expl": "3,5 % liegen über der Grenze von 3,0 %. Jetzt ist die Führungskraft gefragt."}, {"text": "Führungskraft wird nur bei Abweichungen informiert", "kat": "b", "expl": "Im Normalfall läuft die Arbeit ohne Meldung. Das entlastet die Führung bei MbE."}, {"text": "Aufgabe, Kompetenz und Verantwortung werden übertragen", "kat": "c", "expl": "Diese drei gehören bei MbD immer zusammen."}, {"text": "Mitarbeitende tragen die Handlungsverantwortung", "kat": "c", "expl": "Wer eine delegierte Aufgabe hat, steht für die Ausführung ein."}, {"text": "Führungskraft behält die Führungsverantwortung", "kat": "c", "expl": "Auch bei Delegation bleibt die Führungskraft für Auswahl und Kontrolle verantwortlich."}, {"text": "Rückdelegation an die Führungskraft vermeiden", "kat": "c", "expl": "Wer eine Aufgabe übernommen hat, gibt sie nicht einfach zurück. Das ist eine Regel der Delegation."}, {"text": "Harzburger Modell mit Stellenbeschreibungen", "kat": "c", "expl": "Das Harzburger Modell ist die bekannte Form von Management by Delegation."}]}]}, {"nr": 8, "title": "Personalfreistellung", "date": "02.12.2026", "quiz": [{"q": "Was versteht man unter Personalfreistellung?", "o": ["Abbau einer personellen Überdeckung im Betrieb", "Befreiung von der Arbeitspflicht während des Urlaubs", "Einstellung zusätzlicher Fachkräfte für die Montage", "Freistellung von Betriebsratsmitgliedern für Sitzungen"], "c": 0, "e": "Personalfreistellung umfasst alle Maßnahmen, mit denen ein Betrieb mehr Personal abbaut, als er braucht. Sie ist das Gegenstück zur Personalbeschaffung."}, {"q": "Woran erkennt man in der Personalbedarfsrechnung einen Freistellungsbedarf?", "o": ["Der Nettopersonalbedarf ist negativ.", "Der Bruttopersonalbedarf ist höher als der Ist-Bestand.", "Die sicheren Zugänge sind höher als die Abgänge.", "Der Ersatzbedarf ist größer als null."], "c": 0, "e": "Nettopersonalbedarf gleich Bruttobedarf minus fortgeschriebener Bestand. Ist das Ergebnis negativ, sind mehr Beschäftigte da als nötig."}, {"q": "Die Lackiererei von Nordstern braucht 2027 noch 26 Personen. Heute arbeiten dort 30, eine Person geht sicher in Rente. Wie hoch ist der Nettopersonalbedarf?", "o": ["− 3", "− 4", "+ 3", "− 5"], "c": 0, "e": "Fortgeschriebener Bestand 30 − 1 = 29. Nettobedarf 26 − 29 = − 3, also drei Personen Freistellungsbedarf."}, {"q": "Was kennzeichnet die interne Personalfreistellung?", "o": ["Alle Beschäftigten bleiben im Unternehmen.", "Der Personalbestand sinkt sofort spürbar.", "Arbeitsverhältnisse enden durch Vereinbarung.", "Freie Stellen werden extern ausgeschrieben."], "c": 0, "e": "Bei der internen Freistellung ändert der Betrieb Arbeitszeit, Ort oder Aufgaben. Niemand verliert seinen Arbeitsplatz."}, {"q": "Warum gilt der Einstellungsstopp nur als indirekte Freistellung?", "o": ["Er beendet kein bestehendes Arbeitsverhältnis.", "Er braucht immer die Zustimmung der IHK.", "Er gilt nur für Auszubildende im Betrieb.", "Er senkt die Arbeitszeit aller Beschäftigten."], "c": 0, "e": "Beim Einstellungsstopp werden frei werdende Stellen nicht nachbesetzt. Der Bestand sinkt nur langsam durch natürliche Fluktuation."}, {"q": "Was bedeutet Kurzarbeit?", "o": ["Die Arbeitszeit sinkt vorübergehend wegen Arbeitsausfall.", "Beschäftigte werden dauerhaft in Teilzeit versetzt.", "Arbeitsverträge werden nur noch befristet verlängert.", "Pausen werden gekürzt, um Kosten zu sparen."], "c": 0, "e": "Kurzarbeit ist eine vorübergehende Verkürzung der Arbeitszeit, etwa bei Auftragsmangel. Die Beschäftigten bleiben angestellt."}, {"q": "Wer bestimmt bei der Einführung von Kurzarbeit bei Nordstern mit?", "o": ["Der Betriebsrat nach § 87 Abs. 1 Nr. 3 BetrVG", "Die IHK zu Lübeck als zuständige Stelle", "Die Krankenkasse als Einzugsstelle", "Das Arbeitsgericht in einem Eilverfahren"], "c": 0, "e": "Die vorübergehende Verkürzung der betriebsüblichen Arbeitszeit unterliegt der Mitbestimmung des Betriebsrats. Ohne Einigung darf Nordstern keine Kurzarbeit einführen."}, {"q": "Was zahlt die Agentur für Arbeit bei Kurzarbeit unter bestimmten Voraussetzungen?", "o": ["Kurzarbeitergeld für einen Teil des Lohnausfalls", "Den vollen Lohn für alle ausgefallenen Stunden", "Eine Abfindung für jede ausgefallene Woche", "Einen Zuschuss für neue Maschinen im Betrieb"], "c": 0, "e": "Kurzarbeitergeld gleicht einen Teil des Entgeltausfalls aus. Den vollen Lohn ersetzt es nicht."}, {"q": "Was versteht man unter natürlicher Fluktuation?", "o": ["Abgänge durch Rente oder Eigenkündigung", "Kündigungen des Arbeitgebers wegen Auftragsmangel", "Wechsel von Beschäftigten zwischen Abteilungen", "Saisonale Einstellung von Aushilfskräften"], "c": 0, "e": "Natürliche Fluktuation sind Abgänge, die ohne Zutun des Arbeitgebers entstehen. Ein Einstellungsstopp nutzt sie, um den Bestand zu senken."}, {"q": "Wie endet ein kalendermäßig befristeter Arbeitsvertrag?", "o": ["Mit Ablauf der vereinbarten Zeit ohne Kündigung", "Nur durch eine ordentliche Kündigung mit Frist", "Durch einen Beschluss des Betriebsrats", "Automatisch nach sechs Monaten Probezeit"], "c": 0, "e": "Nach § 15 Abs. 1 TzBfG endet der befristete Vertrag mit Ablauf der vereinbarten Zeit. Eine Kündigung ist dafür nicht nötig."}, {"q": "Was ist ein Aufhebungsvertrag?", "o": ["Eine Einigung beider Seiten über das Ende", "Eine einseitige Erklärung des Arbeitgebers", "Ein Vertrag zur Rücknahme einer Abmahnung", "Eine Kündigung mit Angebot neuer Bedingungen"], "c": 0, "e": "Beim Aufhebungsvertrag beenden Arbeitgeber und Arbeitnehmer das Arbeitsverhältnis gemeinsam. Die Kündigung mit Angebot ist dagegen die Änderungskündigung."}, {"q": "Welches Risiko trägt ein Arbeitnehmer, der einen Aufhebungsvertrag unterschreibt?", "o": ["Sperrzeit beim Arbeitslosengeld bis zu 12 Wochen", "Verlust aller Rentenansprüche aus der Beschäftigung", "Rückzahlung des letzten Monatsgehalts", "Verbot einer neuen Beschäftigung für ein Jahr"], "c": 0, "e": "Wer an der eigenen Arbeitslosigkeit mitwirkt, kann nach § 159 SGB III eine Sperrzeit bekommen. In dieser Zeit wird kein Arbeitslosengeld gezahlt."}, {"q": "Was ist eine Kündigung im rechtlichen Sinn?", "o": ["Eine einseitige Erklärung, die zugehen muss", "Ein Vertrag, dem jede Seite zustimmen muss", "Ein Antrag, den der Betriebsrat genehmigt", "Eine Mitteilung, die das Gericht bestätigt"], "c": 0, "e": "Die Kündigung ist eine einseitige empfangsbedürftige Willenserklärung. Die andere Seite muss nicht zustimmen, aber die Kündigung muss ihr zugehen."}, {"q": "Was kennzeichnet die ordentliche Kündigung?", "o": ["Sie beendet das Arbeitsverhältnis nach einer Frist.", "Sie wirkt immer sofort am Tag des Zugangs.", "Sie ist nur aus einem wichtigen Grund möglich.", "Sie gilt nur für befristete Arbeitsverträge."], "c": 0, "e": "Die ordentliche Kündigung ist der Normalfall und wirkt erst nach Ablauf der Kündigungsfrist, etwa nach § 622 BGB. Einen wichtigen Grund braucht die außerordentliche Kündigung."}, {"q": "Wer darf ein Arbeitsverhältnis außerordentlich kündigen?", "o": ["Arbeitgeber und Arbeitnehmer", "Nur der Arbeitgeber", "Nur der Betriebsrat", "Nur das Arbeitsgericht"], "c": 0, "e": "§ 626 BGB gibt beiden Vertragsparteien das Recht zur Kündigung aus wichtigem Grund. Ein Arbeitnehmer kann zum Beispiel fristlos kündigen, wenn der Lohn über Monate ausbleibt."}, {"q": "Der Lagerleiter von Nordstern erfährt am Mittwoch, 02.12.2026, von einem Diebstahl. Bis wann muss die fristlose Kündigung zugehen?", "o": ["Bis 16.12.2026", "Bis 09.12.2026", "Bis 31.12.2026", "Bis 23.12.2026"], "c": 0, "e": "Die Zweiwochenfrist des § 626 Abs. 2 BGB beginnt am Tag nach der Kenntnis und endet am gleichen Wochentag zwei Wochen später, also am Mittwoch, 16.12.2026."}, {"q": "Was gilt, wenn der Arbeitgeber die Zweiwochenfrist des § 626 BGB verpasst?", "o": ["Eine fristlose Kündigung ist nicht mehr möglich.", "Die Frist verlängert sich um zwei Wochen.", "Der Betriebsrat entscheidet über die Kündigung.", "Die Kündigung wird zur Änderungskündigung."], "c": 0, "e": "Die Zweiwochenfrist ist eine Ausschlussfrist. Danach bleibt dem Arbeitgeber nur noch die ordentliche Kündigung."}, {"q": "Was ist eine Änderungskündigung?", "o": ["Kündigung mit Angebot geänderter Bedingungen", "Änderung des Vertrags durch eine Weisung", "Rücknahme einer bereits erklärten Kündigung", "Kündigung, deren Frist später geändert wird"], "c": 0, "e": "Nach § 2 KSchG kündigt der Arbeitgeber und bietet zugleich die Fortsetzung zu neuen Bedingungen an. Eine Weisung reicht nur, wenn die Änderung vom Vertrag gedeckt ist."}, {"q": "Bis wann muss ein Arbeitnehmer erklären, dass er eine Änderungskündigung unter Vorbehalt annimmt?", "o": ["Innerhalb der Frist, spätestens drei Wochen nach Zugang", "Innerhalb von zwei Wochen nach Ende des Vertrags", "Jederzeit bis zum Urteil des Arbeitsgerichts", "Innerhalb von sechs Monaten nach dem Zugang"], "c": 0, "e": "§ 2 KSchG verlangt den Vorbehalt innerhalb der Kündigungsfrist, spätestens innerhalb von drei Wochen nach Zugang. Danach kann das Gericht die Änderung prüfen."}, {"q": "Welchen Vorteil hat die Annahme einer Änderungskündigung unter Vorbehalt für den Arbeitnehmer?", "o": ["Er behält seinen Arbeitsplatz in jedem Fall.", "Er erhält in jedem Fall eine Abfindung.", "Er muss die neue Tätigkeit nie ausüben.", "Seine Kündigungsfrist verdoppelt sich."], "c": 0, "e": "Gewinnt er vor Gericht, gelten die alten Bedingungen. Verliert er, arbeitet er zu den neuen Bedingungen weiter. Den Arbeitsplatz verliert er so nicht."}, {"q": "Welche Form verlangt § 623 BGB für eine Kündigung?", "o": ["Schriftform mit eigenhändiger Unterschrift", "Textform, zum Beispiel per E-Mail", "Mündliche Erklärung vor zwei Zeugen", "Elektronische Form mit digitaler Signatur"], "c": 0, "e": "Kündigung und Aufhebungsvertrag brauchen die Schriftform. Die elektronische Form ist ausdrücklich ausgeschlossen, Textform reicht nicht."}, {"q": "Wann wird eine Kündigung wirksam?", "o": ["Mit dem Zugang beim Empfänger", "Mit dem Datum auf dem Schreiben", "Mit der Unterschrift des Arbeitgebers", "Mit der Ablage in der Personalakte"], "c": 0, "e": "Eine Kündigung wirkt erst, wenn sie so in den Bereich des Empfängers gelangt, dass er sie zur Kenntnis nehmen kann. Vom Zugang aus werden alle Fristen berechnet."}, {"q": "Wie lautet die Grundkündigungsfrist nach § 622 Abs. 1 BGB?", "o": ["4 Wochen zum 15. oder zum Monatsende", "4 Wochen zum Ende eines Quartals", "1 Monat zum Ende eines Kalendermonats", "2 Wochen zu jedem beliebigen Tag"], "c": 0, "e": "Die Grundfrist gilt für Arbeitnehmer und Arbeitgeber. Zwei Wochen gelten nur in einer vereinbarten Probezeit."}, {"q": "Welche gesetzliche Frist gilt bei einer Arbeitgeberkündigung nach 12 Jahren Betriebszugehörigkeit?", "o": ["5 Monate zum Monatsende", "4 Monate zum Monatsende", "6 Monate zum Monatsende", "5 Monate zum 15. oder Monatsende"], "c": 0, "e": "§ 622 Abs. 2 Satz 1 Nr. 5 BGB nennt für 12 Jahre fünf Monate zum Ende eines Kalendermonats. Den 15. als Endtermin gibt es nur bei der Grundfrist."}, {"q": "Thomas Albers ist seit 01.03.2014 bei Nordstern. Die Kündigung geht ihm am 02.12.2026 zu. Wann endet sein Arbeitsverhältnis?", "o": ["31.05.2027", "30.04.2027", "02.05.2027", "30.06.2027"], "c": 0, "e": "12 Jahre und 9 Monate ergeben fünf Monate zum Monatsende. Die Frist läuft bis 02.05.2027, das nächste Monatsende ist der 31.05.2027."}, {"q": "Bis wann hätte die Kündigung von Thomas Albers zugehen müssen, damit sein Arbeitsverhältnis schon am 30.04.2027 endet?", "o": ["Bis 30.11.2026", "Bis 02.12.2026", "Bis 31.10.2026", "Bis 15.11.2026"], "c": 0, "e": "Fünf Monate vor dem 30.04.2027 ist der 30.11.2026. Ging die Kündigung bis dahin zu, war das Ende im April erreichbar."}, {"q": "Wann beginnt eine Kündigungsfrist zu laufen?", "o": ["Am Tag nach dem Zugang der Kündigung", "Am Tag des Zugangs um 0 Uhr", "Am ersten Tag des folgenden Monats", "Am Tag der Stellungnahme des Betriebsrats"], "c": 0, "e": "Der Tag des Zugangs wird nicht mitgezählt. Die Frist beginnt am folgenden Tag."}, {"q": "Katja Brückner aus dem Vertrieb kündigt selbst, ihre Kündigung geht am 02.12.2026 zu. Sie ist seit drei Jahren dabei. Wann endet ihr Arbeitsverhältnis nach Gesetz?", "o": ["31.12.2026", "30.12.2026", "31.01.2027", "15.12.2026"], "c": 0, "e": "Für die Eigenkündigung gilt die Grundfrist. Vier Wochen enden am 30.12.2026, der nächste Endtermin ist der 31.12.2026."}, {"q": "Bis wann muss eine Kündigung mit der Grundfrist spätestens zugehen, damit das Arbeitsverhältnis am 31.12.2026 endet?", "o": ["03.12.2026", "01.12.2026", "30.11.2026", "04.12.2026"], "c": 0, "e": "Vier Wochen gleich 28 Tage. Geht die Kündigung am Donnerstag, 03.12.2026, zu, endet die Frist am Donnerstag, 31.12.2026."}, {"q": "Jana Klein ist seit 01.10.2026 Montagehelferin mit sechs Monaten Probezeit. Die Kündigung geht am Mittwoch, 02.12.2026, zu. Wann endet das Arbeitsverhältnis?", "o": ["16.12.2026", "15.12.2026", "31.12.2026", "30.12.2026"], "c": 0, "e": "Zwei Wochen ab dem 03.12.2026 enden am Mittwoch, 16.12.2026. Ein Monatsende ist in der Probezeit nicht nötig."}, {"q": "Nordstern kündigt einem Mitarbeiter, der seit 1 Jahr und 8 Monaten beschäftigt ist und keine Probezeit mehr hat. Welche gesetzliche Frist gilt?", "o": ["4 Wochen zum 15. oder Monatsende", "1 Monat zum Monatsende", "2 Wochen zu jedem Tag", "2 Monate zum Monatsende"], "c": 0, "e": "Unter zwei Jahren Betriebszugehörigkeit gilt die Grundfrist. Die erste Verlängerung auf einen Monat beginnt erst ab zwei Jahren."}, {"q": "Nordstern kündigt einer Lagerfachkraft mit 6 Jahren Betriebszugehörigkeit. Die Kündigung geht am 02.12.2026 zu. Wann endet das Arbeitsverhältnis?", "o": ["28.02.2027", "31.01.2027", "02.02.2027", "31.03.2027"], "c": 0, "e": "Ab 5 Jahren gelten zwei Monate zum Monatsende. Die Frist läuft bis 02.02.2027, Ende ist der 28.02.2027."}, {"q": "Ein Meister ist seit 16 Jahren bei Nordstern. Mit welcher gesetzlichen Frist kann Nordstern ihm ordentlich kündigen?", "o": ["6 Monate zum Monatsende", "7 Monate zum Monatsende", "5 Monate zum Monatsende", "4 Wochen zum 15. oder Monatsende"], "c": 0, "e": "Die letzte erreichte Stufe ist 15 Jahre. Dafür nennt § 622 Abs. 2 BGB sechs Monate zum Monatsende, sieben Monate gelten erst ab 20 Jahren."}, {"q": "Nordstern kündigt einem Monteur, der seit 2 Jahren und 3 Monaten im Betrieb ist. Welche gesetzliche Frist gilt?", "o": ["1 Monat zum Monatsende", "4 Wochen zum 15. oder Monatsende", "2 Monate zum Monatsende", "2 Wochen zu jedem Tag"], "c": 0, "e": "Ab zwei Jahren Betriebszugehörigkeit gilt bei Kündigung durch den Arbeitgeber ein Monat zum Monatsende."}, {"q": "Die Nordstern Service GmbH hat 18 Beschäftigte. Was erlaubt § 622 Abs. 5 BGB dort im Arbeitsvertrag?", "o": ["Mindestens 4 Wochen Frist ohne festen Endtermin", "Eine Kündigung ganz ohne jede Frist", "Zwei Wochen Frist auch nach der Probezeit", "Eine längere Frist nur für die Beschäftigten"], "c": 0, "e": "In Unternehmen mit nicht mehr als 20 Beschäftigten ohne Azubis darf der Vertrag den festen Endtermin weglassen. Die Frist muss aber mindestens vier Wochen betragen."}, {"q": "An welchem Tag endet eine Frist von vier Wochen?", "o": ["Am gleichen Wochentag wie der Zugangstag", "Immer an einem Freitag", "Am letzten Werktag des Monats", "Am 28. Tag nach dem Monatsersten"], "c": 0, "e": "Wochenfristen enden an dem Wochentag, der dem Zugangstag entspricht. Geht die Kündigung an einem Mittwoch zu, endet die Frist an einem Mittwoch."}, {"q": "Ein Vertriebsmitarbeiter mit drei Monaten Kündigungsfrist möchte schon zum 31.01.2027 zu einem neuen Arbeitgeber wechseln. Welche Lösung passt?", "o": ["Aufhebungsvertrag zum 31.01.2027", "Kündigung per E-Mail zum 31.01.2027", "Änderungskündigung durch den Mitarbeiter", "Fristlose Kündigung ohne besonderen Grund"], "c": 0, "e": "Mit einem Aufhebungsvertrag können beide Seiten ein frei gewähltes Ende vereinbaren. Eine Kündigung per E-Mail wäre unwirksam, eine fristlose braucht einen wichtigen Grund."}, {"q": "Was bedeutet eine Umschulung als Maßnahme der internen Freistellung?", "o": ["Beschäftigte lernen eine neue Tätigkeit im Betrieb.", "Beschäftigte verlassen den Betrieb mit Abfindung.", "Der Arbeitsvertrag endet mit der Prüfung.", "Die Arbeitszeit wird ohne Ausgleich gekürzt."], "c": 0, "e": "Die Umschulung bereitet auf eine andere Aufgabe vor, zum Beispiel auf die Arbeit in der Montage. Die Person bleibt beschäftigt."}, {"q": "Was versteht man unter Outplacement?", "o": ["Vom Arbeitgeber bezahlte Hilfe bei der Stellensuche", "Versetzung an einen Standort im Ausland", "Auslagerung der Lohnabrechnung an Dienstleister", "Freistellung für die Arbeit im Betriebsrat"], "c": 0, "e": "Beim Outplacement unterstützt eine Beratung ausscheidende Beschäftigte bei der beruflichen Neuorientierung. Der bisherige Arbeitgeber trägt die Kosten."}, {"q": "Wovor schützt das Kündigungsschutzgesetz die Beschäftigten?", "o": ["Vor sozial ungerechtfertigten Kündigungen", "Vor jeder Beendigung, auch durch Aufhebung", "Vor einer Versetzung in eine andere Abteilung", "Vor dem Auslaufen befristeter Verträge"], "c": 0, "e": "Das KSchG verlangt einen anerkannten Grund für eine Kündigung. Aufhebungsverträge und Befristungen fallen nicht darunter."}, {"q": "Wie wird eine Teilzeitkraft mit 20 Wochenstunden beim Schwellenwert des KSchG gezählt?", "o": ["Mit 0,5", "Mit 0,75", "Mit 1,0", "Gar nicht"], "c": 0, "e": "Bis 20 Wochenstunden zählt eine Teilzeitkraft mit 0,5, bis 30 Stunden mit 0,75, darüber voll."}, {"q": "Die Nordstern Service GmbH hat 12 Vollzeitkräfte, 4 Teilzeitkräfte mit 20 Stunden und 2 Azubis. Mit wie vielen Arbeitnehmern zählt sie beim Schwellenwert?", "o": ["14", "18", "16", "12"], "c": 0, "e": "12 × 1 + 4 × 0,5 = 14, Azubis zählen nicht. 14 ist mehr als 10, das KSchG gilt."}, {"q": "Welcher Fall ist ein typisches Beispiel für eine personenbedingte Kündigung?", "o": ["Dauerhafte Krankheit mit negativer Prognose", "Wiederholtes unentschuldigtes Fehlen", "Wegfall des Arbeitsplatzes durch Software", "Beleidigung eines Vorgesetzten"], "c": 0, "e": "Personenbedingt heißt, die Person kann die Arbeit nicht mehr leisten, ohne dass ihr ein Vorwurf gemacht wird. Fehlen und Beleidigen sind Verhalten, der Wegfall ist betriebsbedingt."}, {"q": "Welcher Sachverhalt ist ein betriebsbedingter Kündigungsgrund?", "o": ["Arbeitsplatz fällt durch Automatisierung weg.", "Mitarbeiter ist dauerhaft arbeitsunfähig.", "Mitarbeiter beleidigt wiederholt Kunden.", "Mitarbeiter verlangt Elternzeit."], "c": 0, "e": "Betriebsbedingt heißt, der Betrieb braucht den Arbeitsplatz nicht mehr. Wer Elternzeit verlangt, ist sogar besonders geschützt."}, {"q": "Was bedeutet der Grundsatz der Verhältnismäßigkeit bei einer Kündigung?", "o": ["Die Kündigung ist nur das letzte Mittel.", "Die Abfindung entspricht stets dem Gehalt.", "Die Frist richtet sich nach dem Lebensalter.", "Jeder Abteilung wird gleich oft gekündigt."], "c": 0, "e": "Gibt es ein milderes Mittel wie Abmahnung, Versetzung oder Umschulung, muss der Arbeitgeber es zuerst nutzen."}, {"q": "In welchem Fall ist vor einer verhaltensbedingten Kündigung in der Regel keine Abmahnung nötig?", "o": ["Bei sehr schweren Verstößen wie Diebstahl", "Beim ersten Zuspätkommen um zehn Minuten", "Wenn der Betriebsrat vorher zustimmt", "Wenn der Verstoß ein Jahr zurückliegt"], "c": 0, "e": "Bei schweren Pflichtverletzungen ist das Vertrauen sofort zerstört. Eine Warnung wäre dann sinnlos."}, {"q": "Thomas Albers wurde zweimal wegen unentschuldigten Fehlens abgemahnt und fehlt erneut. Welche Kündigung spricht Nordstern aus?", "o": ["Ordentliche verhaltensbedingte Kündigung", "Betriebsbedingte Änderungskündigung", "Personenbedingte fristlose Kündigung", "Aufhebungsvertrag durch den Betriebsrat"], "c": 0, "e": "Der wiederholte, abgemahnte Pflichtverstoß ist ein Grund im Verhalten. Nordstern kündigt ordentlich mit der Frist bis 31.05.2027."}, {"q": "Die Kündigung ist Thomas Albers am Mittwoch, 02.12.2026, zugegangen. Bis wann muss er Kündigungsschutzklage erheben?", "o": ["Bis 23.12.2026", "Bis 16.12.2026", "Bis 31.12.2026", "Bis 02.01.2027"], "c": 0, "e": "Nach § 4 KSchG gilt eine Frist von drei Wochen ab Zugang. Sie endet am Mittwoch, 23.12.2026."}, {"q": "Was gilt, wenn ein Arbeitnehmer die Klagefrist von drei Wochen versäumt?", "o": ["Die Kündigung gilt als von Anfang an wirksam.", "Das Gericht verlängert die Frist automatisch.", "Der Betriebsrat muss die Klage erheben.", "Die Kündigung wird zu einer Abmahnung."], "c": 0, "e": "§ 7 KSchG ordnet an, dass die Kündigung dann als wirksam gilt, selbst wenn sie fehlerhaft war."}, {"q": "Im Rechnungswesen von Nordstern haben vier vergleichbare Beschäftigte 53, 87, 29 und 62 Sozialpunkte. Wem wird betriebsbedingt gekündigt?", "o": ["Carla Jung mit 29 Punkten", "Anna Roth mit 53 Punkten", "Deniz Arslan mit 62 Punkten", "Bernd Vogel mit 87 Punkten"], "c": 0, "e": "Die wenigsten Punkte bedeuten die geringste Schutzbedürftigkeit. Das Punkteschema ist ein vereinfachtes Beispiel, kein Gesetz."}, {"q": "Welche Beschäftigten werden in die Sozialauswahl einbezogen?", "o": ["Beschäftigte mit austauschbarer Tätigkeit", "Alle Beschäftigten des ganzen Unternehmens", "Nur Beschäftigte, die älter als 50 sind", "Nur die Mitglieder des Betriebsrats"], "c": 0, "e": "Verglichen werden Beschäftigte, die nach ihrer Tätigkeit gegeneinander austauschbar sind. Betriebsratsmitglieder sind ordentlich gar nicht kündbar."}, {"q": "Wie hoch ist die Abfindung nach § 1a KSchG?", "o": ["0,5 Monatsverdienste je Beschäftigungsjahr", "1 Monatsverdienst je Beschäftigungsjahr", "3 Monatsverdienste unabhängig von der Dauer", "0,5 Monatsverdienste je Lebensjahr"], "c": 0, "e": "§ 1a KSchG nennt einen halben Monatsverdienst für jedes Jahr des Arbeitsverhältnisses. Mehr als sechs Monate werden aufgerundet."}, {"q": "Eine Sachbearbeiterin verdient 3.950 € im Monat und ist 2 Jahre und 7 Monate beschäftigt. Wie hoch ist die Abfindung nach § 1a KSchG?", "o": ["5.925,00 €", "3.950,00 €", "5.135,00 €", "11.850,00 €"], "c": 0, "e": "Sieben Monate sind mehr als sechs, also wird auf 3 Jahre aufgerundet. 0,5 × 3.950 € × 3 = 5.925,00 €."}, {"q": "Haben gekündigte Beschäftigte grundsätzlich einen gesetzlichen Anspruch auf eine Abfindung?", "o": ["Nein, nur in besonderen Fällen wie nach § 1a KSchG", "Ja, immer ein Monatsgehalt je Beschäftigungsjahr", "Ja, aber nur nach einer fristlosen Kündigung", "Ja, sobald der Betriebsrat widersprochen hat"], "c": 0, "e": "Einen allgemeinen Anspruch gibt es nicht. Abfindungen entstehen meist durch Vergleich, Sozialplan, § 1a oder gerichtliche Auflösung nach § 9 KSchG."}, {"q": "Innerhalb welcher Frist kann ein Gekündigter nach § 3 KSchG Einspruch beim Betriebsrat einlegen?", "o": ["Innerhalb einer Woche", "Innerhalb von drei Tagen", "Innerhalb von drei Wochen", "Innerhalb eines Monats"], "c": 0, "e": "Der Einspruch ist binnen einer Woche nach der Kündigung möglich. Er ersetzt die Klage innerhalb von drei Wochen nicht."}, {"q": "Wie hoch ist die Abfindung bei einer gerichtlichen Auflösung nach § 9 KSchG in der Regel höchstens?", "o": ["12 Monatsverdienste", "6 Monatsverdienste", "24 Monatsverdienste", "3 Monatsverdienste"], "c": 0, "e": "§ 10 KSchG nennt bis zu 12 Monatsverdienste. Für ältere Beschäftigte mit langer Betriebszugehörigkeit sind bis zu 15 oder 18 möglich."}, {"q": "Womit beginnt ein Kündigungsschutzverfahren vor dem Arbeitsgericht in der Regel?", "o": ["Mit einer Güteverhandlung, in der eine Einigung gesucht wird", "Mit einer Anhörung des Betriebsrats durch das Gericht", "Mit einem schriftlichen Urteil ohne Verhandlung", "Mit einem Schlichtungsverfahren bei der IHK"], "c": 0, "e": "Zuerst versucht das Gericht in der Güteverhandlung eine gütliche Einigung, oft einen Vergleich mit Abfindung. Scheitert sie, geht der Prozess weiter."}, {"q": "In welcher Reihenfolge prüft man sinnvoll, ob eine ordentliche Kündigung wirksam ist?", "o": ["Form und Zugang, Betriebsrat, besonderer Schutz, Grund, Frist, Klagefrist", "Klagefrist, Frist, Grund, Betriebsrat, Form und Zugang", "Grund, Abfindung, Frist, Form und Zugang, Betriebsrat", "Betriebsrat, Abfindung, Klagefrist, Form und Zugang"], "c": 0, "e": "Das Prüfschema beginnt mit den formalen Voraussetzungen, prüft dann besonderen Schutz und sozialen Grund und endet mit Kündigungsfrist und Klagefrist."}, {"q": "Ein Mechaniker der Nordstern Service GmbH ist erst seit vier Monaten beschäftigt. Hat er allgemeinen Kündigungsschutz?", "o": ["Nein, die Wartezeit ist noch nicht erfüllt.", "Ja, weil der Betrieb mehr als 10 AN hat.", "Ja, weil seine Probezeit abgelaufen ist.", "Nein, weil Teilzeitkräfte nicht zählen."], "c": 0, "e": "Der Schwellenwert ist zwar erfüllt, aber das Arbeitsverhältnis muss länger als sechs Monate bestehen."}, {"q": "Wer muss im Prozess die Tatsachen beweisen, die eine Kündigung sozial rechtfertigen?", "o": ["Der Arbeitgeber", "Der Arbeitnehmer", "Der Betriebsrat", "Die Agentur für Arbeit"], "c": 0, "e": "Nach § 1 Abs. 2 KSchG trägt der Arbeitgeber die Beweislast für die Kündigungsgründe."}, {"q": "Wann muss der Betriebsrat nach § 102 BetrVG angehört werden?", "o": ["Vor jeder Kündigung", "Nur vor fristlosen Kündigungen", "Nur nach Ablauf der Probezeit", "Nur in Betrieben mit über 500 AN"], "c": 0, "e": "Die Anhörung ist vor jeder Kündigung nötig, ordentlich wie außerordentlich, auch in der Probezeit."}, {"q": "Was ist die Folge, wenn Nordstern den Betriebsrat vor einer Kündigung nicht anhört?", "o": ["Die Kündigung ist unwirksam.", "Die Kündigungsfrist verdoppelt sich.", "Die Kündigung gilt als Abmahnung.", "Der Betriebsrat zahlt eine Abfindung."], "c": 0, "e": "§ 102 Abs. 1 BetrVG bestimmt, dass eine ohne Anhörung ausgesprochene Kündigung unwirksam ist."}, {"q": "Wie viel Zeit hat der Betriebsrat, um Bedenken gegen eine ordentliche Kündigung zu äußern?", "o": ["Eine Woche", "Drei Tage", "Zwei Wochen", "Drei Wochen"], "c": 0, "e": "Bei der ordentlichen Kündigung muss der Betriebsrat seine Bedenken innerhalb einer Woche schriftlich mitteilen."}, {"q": "Innerhalb welcher Zeit muss der Betriebsrat Bedenken gegen eine außerordentliche Kündigung mitteilen?", "o": ["Unverzüglich, spätestens innerhalb von drei Tagen", "Innerhalb einer Woche nach der Mitteilung", "Innerhalb von zwei Wochen nach Kenntnis", "Bis zum Ende der Kündigungsfrist"], "c": 0, "e": "Für die außerordentliche Kündigung gilt eine kurze Frist von höchstens drei Tagen, weil auch der Arbeitgeber unter Zeitdruck steht."}, {"q": "Der Betriebsrat von Nordstern erhält die Anhörung zur ordentlichen Kündigung von Thomas Albers am Dienstag, 24.11.2026. Wann endet seine Frist?", "o": ["Am 01.12.2026", "Am 27.11.2026", "Am 08.12.2026", "Am 30.11.2026"], "c": 0, "e": "Eine Woche nach Dienstag, 24.11.2026, ist Dienstag, 01.12.2026. Am 02.12.2026 kann Nordstern die Kündigung übergeben."}, {"q": "Wie kann einem Mitglied des Betriebsrats gekündigt werden?", "o": ["Nur außerordentlich mit Zustimmung des Betriebsrats", "Ordentlich mit doppelter Kündigungsfrist", "Ordentlich nach Anhörung der IHK", "Jederzeit, solange die Amtszeit läuft"], "c": 0, "e": "§ 15 KSchG schließt die ordentliche Kündigung aus. Die außerordentliche braucht nach § 103 BetrVG die Zustimmung des Betriebsrats, die das Arbeitsgericht ersetzen kann."}, {"q": "Wie lange wirkt der Kündigungsschutz eines Betriebsratsmitglieds nach dem Ende seiner Amtszeit nach?", "o": ["Ein Jahr", "Sechs Monate", "Drei Jahre", "Er wirkt gar nicht nach."], "c": 0, "e": "Nach § 15 KSchG bleibt die ordentliche Kündigung noch ein Jahr nach Ende der Amtszeit ausgeschlossen."}, {"q": "Bis wann kann eine Frau dem Arbeitgeber ihre Schwangerschaft mitteilen, damit eine Kündigung unzulässig wird?", "o": ["Innerhalb von zwei Wochen nach Zugang", "Innerhalb von drei Tagen nach Zugang", "Innerhalb von drei Monaten nach Zugang", "Nur vor dem Zugang der Kündigung"], "c": 0, "e": "Wusste der Arbeitgeber nichts, genügt eine Mitteilung binnen zwei Wochen nach Zugang der Kündigung."}, {"q": "Wer kann die Kündigung einer schwangeren Frau ausnahmsweise für zulässig erklären?", "o": ["Die zuständige Landesbehörde", "Der Betriebsrat des Betriebs", "Die Krankenkasse der Frau", "Das Integrationsamt"], "c": 0, "e": "Nur in besonderen Fällen, die nicht mit der Schwangerschaft zusammenhängen, kann die Landesbehörde zustimmen. Das Integrationsamt ist für schwerbehinderte Menschen zuständig."}, {"q": "Ab wann besteht der Kündigungsschutz nach § 18 BEEG bei einer Elternzeit für ein Kind unter drei Jahren?", "o": ["Ab Verlangen, frühestens acht Wochen vor Beginn", "Erst ab dem ersten Tag der Elternzeit", "Schon zwölf Monate vor der Geburt", "Ab Verlangen, frühestens zwei Jahre vorher"], "c": 0, "e": "Der Schutz beginnt mit dem Verlangen, aber frühestens acht Wochen vor Beginn. Bei Elternzeit zwischen drittem und achtem Geburtstag sind es 14 Wochen."}, {"q": "Was braucht Nordstern vor der Kündigung eines schwerbehinderten Mitarbeiters, der seit vier Jahren beschäftigt ist?", "o": ["Die vorherige Zustimmung des Integrationsamts", "Eine nachträgliche Mitteilung an die Krankenkasse", "Die Zustimmung der Agentur für Arbeit", "Die Zustimmung der IHK zu Lübeck"], "c": 0, "e": "§ 168 SGB IX verlangt die vorherige Zustimmung des Integrationsamts, in einigen Ländern Inklusionsamt genannt."}, {"q": "Leon Becker ist Auszubildender im 2. Ausbildungsjahr. Wie kann Nordstern das Ausbildungsverhältnis kündigen?", "o": ["Nur aus wichtigem Grund ohne Frist", "Ordentlich mit vier Wochen Frist", "Ordentlich mit einem Monat Frist", "Gar nicht, auch nicht bei Diebstahl"], "c": 0, "e": "Nach der Probezeit erlaubt § 22 Abs. 2 BBiG dem Ausbildenden nur die Kündigung aus wichtigem Grund, schriftlich mit Gründen."}, {"q": "Wer muss ein Arbeitszeugnis unterschreiben?", "o": ["Arbeitgeber oder eine bevollmächtigte, ranghöhere Person", "Eine beliebige Kollegin mit eingescannter Unterschrift", "Die oder der Vorsitzende des Betriebsrats", "Der Arbeitnehmer selbst zur Bestätigung"], "c": 0, "e": "Das Zeugnis wird handschriftlich vom Arbeitgeber oder einer bevollmächtigten Person unterschrieben, die über dem Beurteilten steht. Ihre Stellung muss erkennbar sein."}, {"q": "Was kennzeichnet ein qualifiziertes Arbeitszeugnis?", "o": ["Leistung und Verhalten, nur auf Verlangen", "Nur Art und Dauer, immer automatisch", "Zusätzlich Gehalt und Krankheitstage", "Nur für Führungskräfte vorgesehen"], "c": 0, "e": "Das qualifizierte Zeugnis bewertet zusätzlich Leistung und Verhalten. Krankheitstage oder Gehalt gehören nicht hinein."}, {"q": "Unter welcher Bedingung darf Nordstern ein Arbeitszeugnis in elektronischer Form erteilen?", "o": ["Nur mit Einwilligung des Arbeitnehmers", "Immer als E-Mail ohne Unterschrift", "Nie, Zeugnisse gibt es nur auf Papier", "Nur wenn der Betriebsrat zustimmt"], "c": 0, "e": "Seit 2025 erlaubt § 109 Abs. 3 GewO die elektronische Form, wenn der Arbeitnehmer einwilligt."}, {"q": "In einem Zeugnis steht, er trug durch seine Geselligkeit zur Verbesserung des Betriebsklimas bei. Wie wird dieser Satz in der Praxis häufig gelesen?", "o": ["Als versteckter Hinweis auf Alkohol am Arbeitsplatz", "Als Lob für besonders gute Teamarbeit", "Als Hinweis auf besondere Führungsqualitäten", "Als neutrale Aussage ohne jede Bedeutung"], "c": 0, "e": "Der Satz gilt als typischer Zeugniscode. Solche versteckten Aussagen sind nach § 109 Abs. 2 GewO unzulässig, der Arbeitnehmer kann eine Berichtigung verlangen."}, {"q": "Welche Note bedeutet die Formulierung zu unserer Zufriedenheit ohne weitere Verstärkung?", "o": ["ausreichend", "befriedigend", "gut", "mangelhaft"], "c": 0, "e": "Ohne stets und ohne voll bleibt nur die Grundform. Sie steht für die Note 4."}, {"q": "Wer muss im Streit über die Zeugnisnote Belege liefern, wenn der Arbeitnehmer eine bessere Note als befriedigend verlangt?", "o": ["Der Arbeitnehmer", "Der Arbeitgeber", "Der Betriebsrat", "Die IHK"], "c": 0, "e": "Befriedigend gilt als Durchschnitt. Für eine bessere Note muss der Arbeitnehmer seine Leistung darlegen, für eine schlechtere der Arbeitgeber."}, {"q": "Was geschieht mit Resturlaub, der wegen der Beendigung nicht mehr genommen werden kann?", "o": ["Er wird in Geld abgegolten.", "Er verfällt am letzten Arbeitstag.", "Er wird mit der Abfindung verrechnet.", "Er wird auf die Arbeitslosenzeit angerechnet."], "c": 0, "e": "§ 7 Abs. 4 BUrlG schreibt die Abgeltung vor, wenn der Urlaub wegen der Beendigung nicht mehr gewährt werden kann."}, {"q": "Thomas Albers scheidet am 31.05.2027 aus und hat vereinfacht 30 Urlaubstage im Jahr. Wie viele Urlaubstage stehen ihm für 2027 zu?", "o": ["13 Tage", "12 Tage", "15 Tage", "30 Tage"], "c": 0, "e": "Er scheidet in der ersten Jahreshälfte aus. 5 ÷ 12 × 30 = 12,5 Tage, aufgerundet 13 Tage nach § 5 BUrlG."}, {"q": "Was bedeutet eine personelle Überdeckung?", "o": ["Es arbeiten mehr Menschen im Betrieb, als für die geplante Arbeit nötig sind", "Es fehlen im Betrieb Fachkräfte für die geplante Produktion des nächsten Jahres", "Die Personalkosten liegen über dem Wert, der im Vorjahr geplant wurde", "Mehrere Beschäftigte arbeiten mit der gleichen Stellenbeschreibung"], "c": 0, "e": "Überdeckung heißt, es sind mehr Menschen da, als für die geplante Arbeit gebraucht werden. Fehlende Fachkräfte wären eine Unterdeckung, die zur Personalbeschaffung führt."}, {"q": "In welcher Reihenfolge geht ein guter Betrieb bei der Freistellung vor?", "o": ["Erst sanfte Maßnahmen prüfen, dann Arbeitsverhältnisse beenden", "Erst kündigen, danach freie Stellen im Betrieb suchen", "Erst Abfindungen anbieten, danach den Bedarf berechnen", "Erst neue Stellen ausschreiben, dann Kurzarbeit einführen"], "c": 0, "e": "Zuerst werden Maßnahmen geprüft, bei denen niemand den Arbeitsplatz verliert. Erst wenn das nicht reicht, folgen Maßnahmen, die Arbeitsverhältnisse beenden."}, {"q": "Was bleibt bei einer internen Freistellung unverändert?", "o": ["Der Personalbestand nach Köpfen", "Die Arbeitszeit einzelner Beschäftigter", "Der Arbeitsplatz einzelner Beschäftigter", "Die Aufgaben einzelner Beschäftigter"], "c": 0, "e": "Bei der internen Freistellung bleiben alle im Unternehmen. Der Betrieb ändert Arbeitszeit, Arbeitsort oder Aufgaben, der Bestand nach Köpfen bleibt gleich."}, {"q": "Ab welcher Unternehmensgröße braucht eine Versetzung die Zustimmung des Betriebsrats nach § 99 BetrVG?", "o": ["Bei mehr als 20 wahlberechtigten Beschäftigten", "Bei mehr als 5 wahlberechtigten Beschäftigten", "Bei mehr als 100 wahlberechtigten Beschäftigten", "Bei mehr als 500 wahlberechtigten Beschäftigten"], "c": 0, "e": "§ 99 BetrVG gilt in Unternehmen mit in der Regel mehr als 20 wahlberechtigten Beschäftigten. Bei Nordstern mit 240 Beschäftigten ist das erfüllt."}, {"q": "Womit gewinnt ein Betrieb oft die Zustimmung zu einem Aufhebungsvertrag?", "o": ["Mit einer Abfindung oder einem guten Zeugnis", "Mit einer Verlängerung der Probezeit", "Mit einer Abmahnung in der Personalakte", "Mit einer Kürzung des Resturlaubs"], "c": 0, "e": "Damit der Arbeitnehmer zustimmt, bietet der Betrieb oft eine Abfindung, ein gutes Zeugnis oder eine bezahlte Freistellung bis zum Ende an."}, {"q": "Was bedeutet eine Sperrzeit beim Arbeitslosengeld?", "o": ["In dieser Zeit wird kein Arbeitslosengeld gezahlt.", "In dieser Zeit darf man keine neue Stelle antreten.", "In dieser Zeit muss der Arbeitgeber weiter Lohn zahlen.", "In dieser Zeit gilt ein besonderer Kündigungsschutz."], "c": 0, "e": "Während einer Sperrzeit ruht der Anspruch, es fließt kein Arbeitslosengeld. Nach § 159 SGB III kann sie bei Mitwirkung am eigenen Jobverlust bis zu 12 Wochen dauern."}, {"q": "Verlangt das BGB für eine ordentliche Kündigung einen Grund?", "o": ["Nein, einen Grund braucht es erst, wenn das KSchG gilt", "Ja, jede ordentliche Kündigung braucht einen wichtigen Grund", "Ja, der Grund muss immer im Kündigungsschreiben stehen", "Nein, und auch das KSchG verlangt nie einen Grund"], "c": 0, "e": "Das BGB verlangt für die ordentliche Kündigung keinen Grund. Gilt das KSchG, muss die Kündigung aber sozial gerechtfertigt sein (§ 1 Abs. 2 KSchG)."}, {"q": "In welchem Fall kann ein Beschäftigter selbst fristlos kündigen?", "o": ["Der Lohn wird über Monate nicht gezahlt.", "Er hat ein besseres Angebot bekommen.", "Er möchte vor seinem Urlaub aufhören.", "Ihm gefällt der neue Schichtplan nicht."], "c": 0, "e": "Auch Beschäftigte brauchen für eine fristlose Kündigung einen wichtigen Grund nach § 626 Abs. 1 BGB. Monatelang fehlender Lohn ist ein solcher Grund, ein besseres Angebot nicht."}, {"q": "Was wird bei der Prüfung eines wichtigen Grundes nach § 626 Abs. 1 BGB immer vorgenommen?", "o": ["Eine Interessenabwägung im Einzelfall", "Eine Sozialauswahl unter allen Beschäftigten", "Eine Befragung der gesamten Belegschaft", "Eine Prüfung durch das Integrationsamt"], "c": 0, "e": "Ob die Fortsetzung bis zum Fristende unzumutbar ist, wird immer unter Abwägung aller Umstände des Einzelfalls geprüft. Die Sozialauswahl gehört zur betriebsbedingten Kündigung."}, {"q": "Wann braucht ein Arbeitgeber eine Änderungskündigung statt einer einfachen Anweisung?", "o": ["Wenn die Änderung nicht vom Weisungsrecht gedeckt ist", "Wenn eine Mitarbeiterin nur eine neue Kollegin bekommt", "Wenn sich die Pause um wenige Minuten verschiebt", "Wenn der Arbeitsvertrag die Änderung schon erlaubt"], "c": 0, "e": "Was der Vertrag schon erlaubt, kann der Arbeitgeber anweisen. Will er Arbeitszeit, Ort, Tätigkeit oder Entgelt darüber hinaus ändern, braucht er eine Zustimmung oder eine Änderungskündigung (§ 2 KSchG)."}, {"q": "Was geschieht, wenn ein Arbeitnehmer das Angebot einer Änderungskündigung ganz ablehnt?", "o": ["Die Kündigung wirkt wie eine Beendigungskündigung.", "Die alten Bedingungen gelten einfach weiter.", "Der Betriebsrat legt neue Bedingungen fest.", "Der Arbeitgeber muss immer eine Abfindung zahlen."], "c": 0, "e": "Lehnt er ab, bleibt nur die Kündigung übrig, und das Arbeitsverhältnis endet nach Ablauf der Frist. Er kann dagegen Kündigungsschutzklage erheben."}, {"q": "Warum wurde die Regel zu Beschäftigungsjahren vor dem 25. Geburtstag gestrichen?", "o": ["Sie verstieß gegen das Verbot der Altersdiskriminierung.", "Sie war für die Betriebe zu teuer geworden.", "Sie galt nur für Auszubildende und war überflüssig.", "Sie widersprach der Schriftform der Kündigung."], "c": 0, "e": "Die Regel benachteiligte junge Beschäftigte wegen ihres Alters. Sie wurde mit Wirkung zum 01.01.2019 aus § 622 BGB gestrichen, seitdem zählen alle Jahre."}, {"q": "Wie lang ist die längste gesetzliche Kündigungsfrist nach § 622 Abs. 2 BGB?", "o": ["7 Monate zum Monatsende ab 20 Jahren", "8 Monate zum Monatsende ab 25 Jahren", "12 Monate zum Monatsende ab 30 Jahren", "7 Monate zum Quartalsende ab 15 Jahren"], "c": 0, "e": "Die Treppe endet bei 20 Jahren Betriebszugehörigkeit mit 7 Monaten zum Monatsende. Längere gesetzliche Fristen gibt es nicht, ein Tarifvertrag kann aber abweichen."}, {"q": "An welchem Tag endet eine Frist, die in Monaten berechnet wird?", "o": ["Am Tag mit der gleichen Zahl wie der Zugangstag", "Am gleichen Wochentag wie der Zugangstag", "Immer am ersten Tag des Folgemonats", "Immer am letzten Werktag des Monats"], "c": 0, "e": "Bei Monatsfristen endet die Frist am Tag mit der gleichen Zahl, etwa vom 02.12. bis zum 02.05. Danach springt man zum nächsten zulässigen Endtermin."}, {"q": "Warum heißt der Schutz nach dem KSchG allgemeiner Kündigungsschutz?", "o": ["Er gilt für alle Arbeitnehmer, sobald die Bedingungen erfüllt sind", "Er gilt nur für Schwangere und für schwerbehinderte Menschen", "Er gilt nur für Beschäftigte, die nach Tarifvertrag bezahlt werden", "Er gilt allgemein auch für jeden Aufhebungsvertrag im Betrieb"], "c": 0, "e": "Der Schutz hängt nicht von einer besonderen Gruppe ab. Er gilt für alle, wenn der Betrieb mehr als zehn Arbeitnehmer hat und die Wartezeit erfüllt ist (§ 1 Abs. 1 KSchG)."}, {"q": "Mit welchem Faktor geht eine Beschäftigte mit 32 Stunden pro Woche in die Zählung nach § 23 Abs. 1 KSchG ein?", "o": ["Voll mit 1", "Mit 0,75", "Mit 0,5", "Gar nicht"], "c": 0, "e": "Bis 20 Stunden zählt eine Teilzeitkraft mit 0,5, bis 30 Stunden mit 0,75. Wer mehr als 30 Stunden arbeitet, zählt voll (§ 23 Abs. 1 KSchG)."}, {"q": "Welche Grenze gilt für Arbeitsverhältnisse, die schon vor dem 01.01.2004 begonnen haben?", "o": ["Mehr als fünf Arbeitnehmer", "Mehr als zehn Arbeitnehmer", "Mehr als zwanzig Arbeitnehmer", "Mehr als zwei Arbeitnehmer"], "c": 0, "e": "Für diese alten Arbeitsverhältnisse gilt die frühere Grenze von mehr als fünf Arbeitnehmern weiter. Für alle anderen gilt mehr als zehn (§ 23 Abs. 1 KSchG)."}, {"q": "Was kennzeichnet eine personenbedingte Kündigung?", "o": ["Der Beschäftigte kann nicht mehr leisten, ohne dass ihn ein Vorwurf trifft", "Der Beschäftigte verletzt bewusst und wiederholt seine Pflichten", "Der Betrieb braucht den Arbeitsplatz nach einer Umstellung nicht mehr", "Der Beschäftigte hat selbst schriftlich um die Beendigung gebeten"], "c": 0, "e": "Bei der personenbedingten Kündigung kann der Beschäftigte nicht mehr, ihm wird aber kein Vorwurf gemacht. Pflichtverletzungen sind verhaltensbedingt, ein Wegfall des Platzes betriebsbedingt."}, {"q": "Was bedeutet die Dokumentationsfunktion einer Abmahnung?", "o": ["Der Vorfall wird in der Personalakte festgehalten.", "Der Vorfall wird dem Arbeitsgericht gemeldet.", "Der Vorfall wird im Arbeitszeugnis genannt.", "Der Vorfall wird am schwarzen Brett ausgehängt."], "c": 0, "e": "Die Abmahnung hält den Vorfall schriftlich in der Personalakte fest. So kann der Arbeitgeber später beweisen, dass er gewarnt hat."}, {"q": "Worauf muss eine verhaltensbedingte Kündigung nach einer Abmahnung beruhen?", "o": ["Auf einem gleichartigen erneuten Verstoß", "Auf einem beliebigen anderen Vorfall", "Auf einer Beschwerde der Kollegen", "Auf einem Rückgang der Aufträge"], "c": 0, "e": "Die Abmahnung warnt vor einem bestimmten Verhalten. Nur wenn sich ein gleichartiger Verstoß wiederholt, ist die Kündigung meist sozial gerechtfertigt (§ 1 Abs. 2 KSchG)."}, {"q": "Womit beginnt eine betriebsbedingte Kündigung?", "o": ["Mit einer unternehmerischen Entscheidung", "Mit einer Abmahnung des Beschäftigten", "Mit einer Beschwerde der Kollegen", "Mit einem Antrag beim Arbeitsgericht"], "c": 0, "e": "Am Anfang steht eine Entscheidung des Unternehmens, etwa eine neue Maschine oder die Schließung einer Abteilung. Dadurch muss ein Arbeitsplatz dauerhaft wegfallen."}, {"q": "Was gilt, wenn ein Beschäftigter die Klagefrist versäumt, obwohl der Betriebsrat nicht angehört wurde?", "o": ["Die Kündigung gilt trotzdem als wirksam.", "Die Kündigung bleibt wegen des Fehlers unwirksam.", "Die Klagefrist beginnt dann von vorn.", "Der Betriebsrat kann die Klage nachholen."], "c": 0, "e": "Nach § 7 KSchG gilt eine Kündigung als von Anfang an wirksam, wenn nicht rechtzeitig geklagt wird. Das gilt auch für Fehler wie eine fehlende Anhörung."}, {"q": "Welche Aussage zum Einspruch beim Betriebsrat nach § 3 KSchG stimmt?", "o": ["Er ersetzt die Kündigungsschutzklage nicht.", "Er verlängert die Klagefrist auf sechs Wochen.", "Er macht die Kündigung sofort unwirksam.", "Er ist nur bei fristlosen Kündigungen möglich."], "c": 0, "e": "Der Einspruch ist innerhalb einer Woche möglich und kann eine Einigung fördern. Die Klagefrist von drei Wochen läuft aber unverändert weiter."}, {"q": "Wann kann ein Arbeitsgericht das Arbeitsverhältnis nach § 9 KSchG gegen eine Abfindung auflösen?", "o": ["Die Kündigung ist unwirksam, die Fortsetzung aber unzumutbar.", "Die Kündigung war wirksam, und der Betrieb stimmt zu.", "Der Beschäftigte hat die Klagefrist versäumt.", "Der Betriebsrat hat keine Bedenken geäußert."], "c": 0, "e": "Stellt das Gericht die Unwirksamkeit fest, ist die Fortsetzung aber nicht zumutbar, kann es auf Antrag gegen Abfindung auflösen. Diese beträgt in der Regel bis zu 12 Monatsverdienste (§ 10 KSchG)."}, {"q": "Welche Rolle hat der Betriebsrat bei einer gewöhnlichen Kündigung?", "o": ["Er muss gehört werden, entscheidet aber nicht.", "Er entscheidet allein über die Kündigung.", "Er muss jeder Kündigung schriftlich zustimmen.", "Er wird erst nach dem Zugang informiert."], "c": 0, "e": "Der Betriebsrat wird angehört und kann Bedenken oder Widerspruch äußern. Die Entscheidung trifft der Arbeitgeber, eine Zustimmung braucht es nur in Sonderfällen wie § 103 BetrVG."}, {"q": "Was gilt für den besonderen Kündigungsschutz häufig?", "o": ["Er gilt unabhängig von der Größe des Betriebs.", "Er gilt nur in Betrieben mit Betriebsrat.", "Er gilt nur in den ersten sechs Monaten.", "Er ersetzt den allgemeinen Kündigungsschutz."], "c": 0, "e": "Der besondere Schutz kommt zum allgemeinen Schutz hinzu und gilt oft auch in kleinen Betrieben, zum Beispiel für Schwangere nach § 17 MuSchG."}, {"q": "Wie lange ist eine Frau nach einer Fehlgeburt nach der zwölften Schwangerschaftswoche vor einer Kündigung geschützt?", "o": ["Bis vier Monate danach", "Bis zwei Wochen danach", "Bis acht Wochen danach", "Bis ein Jahr danach"], "c": 0, "e": "§ 17 MuSchG schützt auch nach einer Fehlgeburt nach der zwölften Woche, und zwar bis vier Monate danach."}, {"q": "Ab wann besteht der Kündigungsschutz bei einer Elternzeit zwischen dem dritten und achten Geburtstag frühestens?", "o": ["14 Wochen vor Beginn", "8 Wochen vor Beginn", "6 Monate vor Beginn", "Erst am ersten Tag"], "c": 0, "e": "Für diese Elternzeit beginnt der Schutz ab dem Verlangen, frühestens 14 Wochen vor Beginn. Bei Kindern unter drei Jahren sind es frühestens acht Wochen (§ 18 BEEG)."}, {"q": "Wer ist vor der Kündigung eines schwerbehinderten Menschen neben dem Integrationsamt zu beteiligen?", "o": ["Die Schwerbehindertenvertretung", "Die Industrie- und Handelskammer", "Die Berufsgenossenschaft", "Das Finanzamt"], "c": 0, "e": "Neben der vorherigen Zustimmung des Integrationsamts nach § 168 SGB IX ist die Schwerbehindertenvertretung vorher zu beteiligen. In einigen Ländern heißt das Amt Inklusionsamt."}, {"q": "Wer hat nach § 15 KSchG den gleichen Schutz wie Mitglieder des Betriebsrats?", "o": ["Mitglieder der Jugend- und Auszubildendenvertretung", "Alle Beschäftigten, die älter als 50 Jahre sind", "Alle Mitglieder der Geschäftsführung", "Alle Mitglieder einer Gewerkschaft"], "c": 0, "e": "Mitglieder von Betriebsrat und JAV können nicht ordentlich gekündigt werden. Der Schutz wirkt ein Jahr nach dem Ende der Amtszeit nach."}, {"q": "Was kann es bedeuten, wenn im Zeugnis einer Verkaufskraft jeder Hinweis auf den Umgang mit Kunden fehlt?", "o": ["Das Fehlen ist selbst eine versteckte Aussage.", "Das Zeugnis wird dadurch automatisch sehr gut.", "Der Umgang mit Kunden darf nie erwähnt werden.", "Das Zeugnis wird so zum einfachen Zeugnis."], "c": 0, "e": "Auch was fehlt, sagt etwas aus. Fehlt ein wichtiger Punkt der Tätigkeit, fällt das Lesern auf und wirkt wie eine schlechte Bewertung."}, {"q": "Wann kann ein Beschäftigter ein Zwischenzeugnis verlangen?", "o": ["Bei berechtigtem Interesse, etwa bei neuen Vorgesetzten", "Nur am Jahresende und ohne jeden besonderen Anlass", "Nur wenn er das Arbeitsverhältnis schon gekündigt hat", "Nur nach mindestens zehn Jahren im Betrieb"], "c": 0, "e": "Während des Arbeitsverhältnisses gibt es ein Zwischenzeugnis bei berechtigtem Interesse, zum Beispiel beim Wechsel der Vorgesetzten. Viele Tarifverträge regeln das ausdrücklich."}, {"q": "Welche Note drückt die Formulierung hat sich bemüht aus?", "o": ["ungenügend", "ausreichend", "befriedigend", "mangelhaft"], "c": 0, "e": "Hat sich bemüht steht in der Zeugnissprache für ungenügend. Gemeint ist, dass der Einsatz da war, der Erfolg aber fehlte."}, {"q": "Was bedeutet es, Resturlaub abzugelten?", "o": ["Ihn in Geld auszuzahlen", "Ihn ins nächste Jahr zu übertragen", "Ihn ersatzlos zu streichen", "Ihn mit Überstunden zu verrechnen"], "c": 0, "e": "Kann Urlaub wegen der Beendigung nicht mehr genommen werden, wird er in Geld ausgezahlt (§ 7 Abs. 4 BUrlG)."}, {"q": "Wie viel Urlaub erhält jemand für das Jahr, in dessen erster Hälfte er ausscheidet?", "o": ["Ein Zwölftel des Jahresurlaubs je vollem Monat", "Den vollen Jahresurlaub in jedem Fall", "Die Hälfte des Jahresurlaubs als Pauschale", "Ein Zwölftel je angefangener Woche"], "c": 0, "e": "Nach § 5 Abs. 1 BUrlG gibt es bei Ausscheiden in der ersten Jahreshälfte ein Zwölftel je vollem Monat. Bruchteile ab einem halben Tag werden aufgerundet (§ 5 Abs. 2 BUrlG)."}, {"q": "Womit rechnet das Gesetz bei der Urlaubsabgeltung genau?", "o": ["Mit dem Durchschnittsverdienst der letzten 13 Wochen", "Mit dem Grundentgelt des ersten Monats im Betrieb", "Mit dem gesetzlichen Mindestlohn des Jahres", "Mit dem Durchschnitt aller Gehälter im Betrieb"], "c": 0, "e": "Im Kurs wird vereinfacht mit dem Stundenlohn gerechnet. Genau zählt nach § 11 BUrlG der Durchschnittsverdienst der letzten 13 Wochen."}, {"q": "Bis wann muss der Arbeitgeber einen ausgeschiedenen Beschäftigten bei der Krankenkasse abmelden?", "o": ["Mit der nächsten Entgeltabrechnung, spätestens nach sechs Wochen", "Schon am ersten Tag nach dem Zugang der Kündigung", "Erst am Ende des Kalenderjahres mit der Jahresmeldung", "Nur dann, wenn der Beschäftigte es ausdrücklich verlangt"], "c": 0, "e": "Die Abmeldung erfolgt nach der DEÜV mit der nächsten Entgeltabrechnung, spätestens innerhalb von sechs Wochen nach dem Ende."}, {"q": "Welche Folge droht bei einer verspäteten Arbeitsuchendmeldung?", "o": ["Eine Sperrzeit von einer Woche", "Eine Sperrzeit von zwölf Wochen", "Der Verlust des Zeugnisanspruchs", "Eine Kürzung der Abfindung"], "c": 0, "e": "Wer sich zu spät meldet, riskiert eine Sperrzeit von einer Woche. Die Sperrzeit bis zu 12 Wochen betrifft dagegen die Mitwirkung an der eigenen Arbeitslosigkeit."}, {"q": "Frau Seidel aus dem Einkauf und Nordstern einigen sich mündlich auf ein Ende zum 31.03.2027. Malte Brandt bestätigt das am nächsten Tag per E-Mail. Was gilt?", "o": ["Der Aufhebungsvertrag ist mangels Schriftform unwirksam.", "Der Aufhebungsvertrag ist wirksam, weil eine E-Mail vorliegt.", "Der Aufhebungsvertrag wird wirksam, wenn der Betriebsrat zustimmt.", "Der Aufhebungsvertrag gilt als fristlose Kündigung."], "c": 0, "e": "Auch der Aufhebungsvertrag braucht nach § 623 BGB die Schriftform mit eigenhändiger Unterschrift beider Seiten. Mündliche Absprachen und E-Mails reichen nicht."}, {"q": "Ein Monteur hat 2026 mehrmals verspätet angefangen und wurde deshalb abgemahnt. Für welchen neuen Verstoß hat diese Abmahnung eine Warnwirkung?", "o": ["Erneutes Zuspätkommen zu Schichtbeginn", "Ein Streit mit einem Kunden am Telefon", "Ein Fehler in der Reisekostenabrechnung", "Rauchen an einem verbotenen Ort"], "c": 0, "e": "Die Kündigung muss auf einem gleichartigen Verstoß beruhen. Für ganz andere Pflichtverletzungen fehlt die Warnung, dafür wäre zuerst eine eigene Abmahnung nötig."}, {"q": "Ein Lagerleiter erfährt am Donnerstag, 07.01.2027, dass ein Mitarbeiter Akkus aus dem Lager mitgenommen hat. Bis wann muss die fristlose Kündigung zugehen?", "o": ["Donnerstag, 21.01.2027", "Donnerstag, 14.01.2027", "Donnerstag, 28.01.2027", "Sonntag, 31.01.2027"], "c": 0, "e": "Die Zweiwochenfrist nach § 626 Abs. 2 BGB beginnt mit der Kenntnis. Zwei Wochen nach dem 07.01.2027 ist der 21.01.2027."}, {"q": "Ein Monteur hat am 10.12.2026 Werkzeug entwendet. Die Personalleitung erfährt davon erst am Dienstag, 05.01.2027. Bis wann muss die fristlose Kündigung zugehen?", "o": ["Dienstag, 19.01.2027", "Donnerstag, 24.12.2026", "Dienstag, 12.01.2027", "Mittwoch, 10.02.2027"], "c": 0, "e": "Die Frist läuft ab Kenntnis der maßgebenden Tatsachen, nicht ab der Tat (§ 626 Abs. 2 BGB). Zwei Wochen nach dem 05.01.2027 ist der 19.01.2027."}, {"q": "Nordstern erfährt am Mittwoch, 09.12.2026, von einem Betrug bei der Zeiterfassung und kündigt erst am 28.12.2026 fristlos. Was gilt?", "o": ["Die Frist ist abgelaufen, möglich ist nur eine ordentliche Kündigung.", "Die fristlose Kündigung ist wirksam, weil Feiertage nicht zählen.", "Die fristlose Kündigung ist wirksam, wenn der Betriebsrat zustimmt.", "Die fristlose Kündigung wird automatisch zu einer Änderungskündigung."], "c": 0, "e": "Die Frist endete am Mittwoch, 23.12.2026. Danach ist eine fristlose Kündigung ausgeschlossen, Nordstern kann nur noch mit Frist kündigen."}, {"q": "Ein Lagerist ist seit 01.02.2023 beschäftigt. Die Arbeitgeberkündigung geht am Montag, 18.01.2027, zu. Wann endet das Arbeitsverhältnis?", "o": ["28.02.2027", "31.03.2027", "15.02.2027", "18.02.2027"], "c": 0, "e": "Er ist 3 Jahre und 11 Monate dabei, das ist die Stufe 2 Jahre mit 1 Monat zum Monatsende. Fristablauf 18.02.2027, Ende 28.02.2027."}, {"q": "Eine Sachbearbeiterin ist seit 01.04.2005 bei Nordstern. Die Arbeitgeberkündigung geht am Freitag, 29.01.2027, zu. Wann endet das Arbeitsverhältnis?", "o": ["31.08.2027", "31.07.2027", "29.08.2027", "30.09.2027"], "c": 0, "e": "Sie ist 21 Jahre und 9 Monate dabei, also gelten 7 Monate zum Monatsende. Die Frist läuft bis zum 29.08.2027, nächstes Monatsende ist der 31.08.2027."}, {"q": "Eine Monteurin will mit der Grundfrist zum 15.01.2027 ausscheiden. Bis wann muss ihre Kündigung spätestens zugehen?", "o": ["18.12.2026", "15.12.2026", "31.12.2026", "01.12.2026"], "c": 0, "e": "Vom Endtermin rechnet man vier Wochen zurück. Geht die Kündigung am Freitag, 18.12.2026, zu, laufen die vier Wochen genau am 15.01.2027 ab."}, {"q": "Nordstern möchte, dass das Arbeitsverhältnis eines Meisters mit 11 Jahren Betriebszugehörigkeit am 31.07.2027 endet. Bis wann muss die Kündigung spätestens zugehen?", "o": ["31.03.2027", "30.04.2027", "28.02.2027", "30.06.2027"], "c": 0, "e": "Bei 11 Jahren gelten 4 Monate zum Monatsende. Vom 31.07.2027 vier Monate zurück ergibt den 31.03.2027 als letzten Tag für den Zugang."}, {"q": "Eine Montageleiterin ist seit 15 Jahren bei Nordstern und kündigt selbst. Weder Arbeitsvertrag noch Tarifvertrag regeln etwas zur Frist. Welche Frist gilt für sie?", "o": ["4 Wochen zum 15. oder zum Monatsende", "6 Monate zum Ende eines Kalendermonats", "3 Monate zum Ende eines Quartals", "2 Wochen zu jedem beliebigen Tag"], "c": 0, "e": "Die verlängerten Fristen nach § 622 Abs. 2 BGB gelten nur bei Kündigung durch den Arbeitgeber. Für die Eigenkündigung bleibt es bei der Grundfrist."}, {"q": "Ein Monteur von Nordstern verliert seine Arbeitserlaubnis. Welcher Kündigungsgrund kommt in Betracht?", "o": ["Personenbedingt", "Verhaltensbedingt", "Betriebsbedingt", "Ein wichtiger Grund ohne Prüfung"], "c": 0, "e": "Er kann die Arbeit rechtlich nicht mehr leisten, ohne dass ihm ein Fehlverhalten vorgeworfen wird. Das ist ein Grund in der Person (§ 1 Abs. 2 KSchG)."}, {"q": "Eine Vertriebsmitarbeiterin rechnet trotz Abmahnung erneut private Fahrten als Dienstreisen ab. Welcher Kündigungsgrund liegt vor?", "o": ["Verhaltensbedingt", "Personenbedingt", "Betriebsbedingt", "Gar kein Grund im Sinne des KSchG"], "c": 0, "e": "Sie verletzt ihre Pflichten, obwohl sie sich anders verhalten könnte. Die Abmahnung hat sie gewarnt, der Verstoß ist gleichartig."}, {"q": "Muss Nordstern bei einer betriebsbedingten Kündigung in der Montage eine Buchhalterin in die Sozialauswahl einbeziehen?", "o": ["Nein, ihre Tätigkeit ist nicht austauschbar.", "Ja, alle Beschäftigten des Betriebs zählen.", "Ja, wenn sie älter als die Monteure ist.", "Nein, Frauen sind von der Auswahl ausgenommen."], "c": 0, "e": "In die Sozialauswahl kommen nur vergleichbare Beschäftigte, deren Tätigkeit austauschbar ist. Eine Buchhalterin kann nicht ohne Weiteres in der Montage arbeiten."}, {"q": "Ein angelernter Monteur in EG 5 mit 3.250 € ist 4 Jahre und 5 Monate beschäftigt. Wie hoch ist eine Abfindung nach § 1a KSchG?", "o": ["6.500,00 €", "8.125,00 €", "7.312,50 €", "13.000,00 €"], "c": 0, "e": "Fünf Monate sind nicht mehr als sechs Monate und werden nicht aufgerundet. 0,5 × 3.250 € × 4 = 6.500,00 €."}, {"q": "Thomas Albers fragt, ob ihm nach seiner Kündigung eine Abfindung nach § 1a KSchG zusteht. Was trifft zu?", "o": ["Nein, er wurde verhaltensbedingt und ohne Hinweis gekündigt.", "Ja, jede Kündigung nach zwölf Jahren löst den Anspruch aus.", "Ja, weil der Betriebsrat zur Kündigung geschwiegen hat.", "Nein, weil er älter als 45 Jahre alt ist und lange dabei war."], "c": 0, "e": "§ 1a KSchG setzt eine betriebsbedingte Kündigung mit Hinweis auf die Abfindung voraus. Albers wurde wegen unentschuldigten Fehlens verhaltensbedingt gekündigt."}, {"q": "Einer Lagerfachkraft geht die Kündigung am Montag, 18.01.2027, zu. Bis wann muss sie Kündigungsschutzklage erheben?", "o": ["Montag, 08.02.2027", "Montag, 01.02.2027", "Donnerstag, 18.02.2027", "Sonntag, 28.02.2027"], "c": 0, "e": "Die Klagefrist beträgt drei Wochen ab Zugang der schriftlichen Kündigung (§ 4 KSchG). Drei Wochen nach dem 18.01.2027 ist der 08.02.2027."}, {"q": "Herrn Kessler geht die Kündigung am Freitag, 15.01.2027, zu. Er reicht seine Klage am Montag, 08.02.2027, beim Arbeitsgericht ein. Was gilt?", "o": ["Die Klage ist zu spät, die Kündigung gilt als wirksam.", "Die Klage ist rechtzeitig, weil vier Wochen gelten.", "Die Klage ist rechtzeitig, weil das Wochenende nicht zählt.", "Die Klage hemmt die Kündigung bis zum Urteil."], "c": 0, "e": "Die drei Wochen endeten am Freitag, 05.02.2027. Wer die Frist versäumt, kann die Kündigung nicht mehr angreifen, sie gilt als von Anfang an wirksam (§ 7 KSchG)."}, {"q": "Zu einer fristlosen Kündigung wird der Betriebsrat am Dienstag, 12.01.2027, angehört. Bis wann muss er Bedenken spätestens mitteilen?", "o": ["Freitag, 15.01.2027", "Dienstag, 19.01.2027", "Mittwoch, 13.01.2027", "Dienstag, 26.01.2027"], "c": 0, "e": "Bei der außerordentlichen Kündigung muss der Betriebsrat Bedenken unverzüglich, spätestens innerhalb von drei Tagen mitteilen (§ 102 Abs. 2 BetrVG)."}, {"q": "Ein Monteur war bis 30.04.2026 Mitglied im Betriebsrat von Nordstern. Im Dezember 2026 soll ihm wegen einer Umorganisation ordentlich gekündigt werden. Was gilt?", "o": ["Die ordentliche Kündigung ist noch bis 30.04.2027 ausgeschlossen.", "Die ordentliche Kündigung ist zulässig, weil das Amt beendet ist.", "Die ordentliche Kündigung braucht nur die Zustimmung der IHK.", "Die ordentliche Kündigung ist erst nach drei Jahren wieder möglich."], "c": 0, "e": "Der Schutz nach § 15 KSchG wirkt ein Jahr nach dem Ende der Amtszeit nach. Bis zum 30.04.2027 ist eine ordentliche Kündigung ausgeschlossen."}, {"q": "Frau Krause erhält am Montag, 11.01.2027, eine Kündigung. Am 22.01.2027 teilt sie Nordstern mit, dass sie schwanger ist. Nordstern wusste davon nichts. Was gilt?", "o": ["Die Kündigung ist unzulässig, die Mitteilung kam rechtzeitig.", "Die Kündigung ist wirksam, weil Nordstern nichts wusste.", "Die Kündigung ist wirksam, wenn der Betriebsrat zustimmt.", "Die Kündigung ist nur bei Vollzeit unzulässig."], "c": 0, "e": "Die Frau kann die Schwangerschaft noch innerhalb von zwei Wochen nach Zugang mitteilen, hier bis 25.01.2027. Dann ist die Kündigung unzulässig (§ 17 MuSchG)."}, {"q": "Ein Vater kündigt am 15.02.2027 an, ab 01.06.2027 Elternzeit für sein einjähriges Kind zu nehmen. Ab wann besteht frühestens Kündigungsschutz nach § 18 BEEG?", "o": ["Ab Dienstag, 06.04.2027", "Ab Montag, 15.02.2027", "Ab Dienstag, 01.06.2027", "Ab Dienstag, 23.02.2027"], "c": 0, "e": "Der Schutz beginnt mit dem Verlangen, aber frühestens acht Wochen vor Beginn der Elternzeit, wenn das Kind jünger als drei Jahre ist. Acht Wochen vor dem 01.06.2027 ist der 06.04.2027."}, {"q": "Ein schwerbehinderter Lagerhelfer ist erst seit vier Monaten bei Nordstern. Braucht Nordstern für eine Kündigung die Zustimmung des Integrationsamts?", "o": ["Nein, der Schutz greift erst nach mehr als sechs Monaten.", "Ja, der Schutz gilt schon ab dem ersten Arbeitstag.", "Ja, aber erst nach dem Zugang der Kündigung.", "Nein, der Schutz gilt nur in kleinen Betrieben."], "c": 0, "e": "Der Sonderschutz nach § 168 SGB IX gilt, wenn das Arbeitsverhältnis länger als sechs Monate besteht. Die Anhörung des Betriebsrats bleibt trotzdem Pflicht."}, {"q": "Im Zeugnis eines Lageristen steht, er habe seine Aufgaben zu unserer vollen Zufriedenheit erledigt. Welche Note ist gemeint?", "o": ["befriedigend", "mangelhaft", "sehr gut", "ausreichend"], "c": 0, "e": "Ohne das Wort stets entspricht volle Zufriedenheit der Note befriedigend. Stets zu unserer vollen Zufriedenheit wäre gut, zu unserer Zufriedenheit nur ausreichend."}, {"q": "Das Zeugnis eines Monteurs mit guter Leistungsnote endet ohne Dank, Bedauern und gute Wünsche. Wie wirkt das auf Leser?", "o": ["Als negatives Signal trotz guter Note", "Als Zeichen einer sehr guten Bewertung", "Als neutrale und übliche Formulierung", "Als Hinweis auf eine fristlose Kündigung"], "c": 0, "e": "Die Schlussformel ist ein wichtiges Signal. Fehlen Dank und gute Wünsche, liest man das als Distanz, auch wenn die Leistung gut bewertet wurde."}, {"q": "Eine Monteurin scheidet am 28.02.2027 aus. Ihr Jahresurlaub beträgt vereinfacht 30 Tage. Wie viele Urlaubstage stehen ihr für 2027 zu?", "o": ["5 Tage", "2,5 Tage", "30 Tage", "6 Tage"], "c": 0, "e": "Sie scheidet in der ersten Jahreshälfte aus und hat zwei volle Monate (§ 5 Abs. 1 BUrlG). 2 ÷ 12 × 30 = 5 Tage."}, {"q": "Eine Sachbearbeiterin scheidet am 30.04.2027 aus, ihr Jahresurlaub beträgt 27 Tage. Wie viele Tage stehen ihr für 2027 zu?", "o": ["9 Tage", "8 Tage", "13,5 Tage", "27 Tage"], "c": 0, "e": "Für vier volle Monate gibt es vier Zwölftel des Jahresurlaubs. 4 ÷ 12 × 27 = 9 Tage, eine Rundung ist nicht nötig."}, {"q": "Herr Jensen unterschreibt am Montag, 01.03.2027, einen Aufhebungsvertrag zum 30.04.2027. Bis wann muss er sich arbeitsuchend melden?", "o": ["Donnerstag, 04.03.2027", "Freitag, 30.04.2027", "Montag, 01.02.2027", "Montag, 15.03.2027"], "c": 0, "e": "Zwischen Kenntnis und Ende liegen weniger als drei Monate. Dann gilt die Meldung innerhalb von drei Tagen nach Kenntnis (§ 38 Abs. 1 SGB III)."}], "lernen": [{"t": "Personalfreistellung", "x": "Alle Maßnahmen, mit denen ein Betrieb eine personelle Überdeckung abbaut."}, {"t": "Interne Freistellung", "x": "Abbau der Überdeckung, ohne dass jemand das Unternehmen verlässt, zum Beispiel Kurzarbeit oder Versetzung."}, {"t": "Externe Freistellung", "x": "Maßnahmen, die den Personalbestand senken, zum Beispiel Aufhebungsvertrag oder Kündigung."}, {"t": "Aufhebungsvertrag", "x": "Einvernehmliche, schriftliche Beendigung des Arbeitsverhältnisses zu einem vereinbarten Datum."}, {"t": "Ordentliche Kündigung", "x": "Kündigung mit Kündigungsfrist, zum Beispiel nach § 622 BGB."}, {"t": "Außerordentliche Kündigung", "x": "Meist fristlose Kündigung aus wichtigem Grund, sie muss binnen zwei Wochen ab Kenntnis zugehen."}, {"t": "Änderungskündigung", "x": "Kündigung mit dem gleichzeitigen Angebot, zu geänderten Bedingungen weiterzuarbeiten."}, {"t": "Zugang", "x": "Zeitpunkt, an dem die Kündigung so beim Empfänger ankommt, dass er sie lesen kann. Ab hier laufen die Fristen."}, {"t": "Sozialauswahl", "x": "Auswahl bei betriebsbedingter Kündigung nach Betriebszugehörigkeit, Lebensalter, Unterhaltspflichten und Schwerbehinderung."}, {"t": "Abmahnung", "x": "Rüge eines Fehlverhaltens mit Warnung vor der Kündigung im Wiederholungsfall."}, {"t": "Klagefrist", "x": "Drei Wochen ab Zugang, um Kündigungsschutzklage beim Arbeitsgericht zu erheben."}, {"t": "Qualifiziertes Zeugnis", "x": "Arbeitszeugnis mit Beurteilung von Leistung und Verhalten, nur auf Verlangen."}, {"t": "Urlaubsabgeltung", "x": "Auszahlung von Urlaub, der wegen der Beendigung nicht mehr genommen werden kann."}, {"t": "Arbeitsuchendmeldung", "x": "Pflicht, sich spätestens drei Monate vor dem Ende oder binnen drei Tagen bei der Agentur für Arbeit zu melden."}, {"t": "Güteverhandlung", "x": "Erster Termin vor dem Arbeitsgericht, in dem das Gericht eine Einigung der Parteien versucht, oft einen Vergleich mit Abfindung."}, {"t": "Zwischenzeugnis", "x": "Zeugnis während des laufenden Arbeitsverhältnisses, zum Beispiel bei einem Wechsel der Vorgesetzten. Das Endzeugnis gibt es bei der Beendigung."}, {"t": "Zeugnissprache", "x": "Wohlwollend klingende Formulierungen, hinter denen eine Bewertung steckt, etwa stets zu unserer vollen Zufriedenheit für gut. Versteckte Botschaften sind unzulässig."}, {"t": "Prüfschema Kündigung", "x": "Feste Reihenfolge der Prüfung, nämlich Form und Zugang, Betriebsrat, besonderer Schutz, sozialer Grund, Kündigungsfrist und Klagefrist."}, {"t": "Personalfreistellung", "x": "Personalfreistellung umfasst alle Maßnahmen, mit denen ein Betrieb eine personelle Überdeckung nach Menge, Zeit, Ort oder Qualifikation abbaut (Beiderwieden & Stickdorn, 2026)."}, {"t": "Der Prüfstein", "x": "Verringert eine Maßnahme den Personalbestand, ist sie extern. Bleiben alle im Betrieb, ist sie intern. Der Einstellungsstopp ist extern, wirkt aber nur indirekt."}, {"t": "Wichtiger Grund", "x": "Ein wichtiger Grund liegt vor, wenn die Fortsetzung des Arbeitsverhältnisses bis zum Ende der Kündigungsfrist unzumutbar ist. Es wird immer eine Interessenabwägung im Einzelfall vorgenommen (§ 626 Abs. 1 BGB)."}, {"t": "Schriftform", "x": "Kündigung und Aufhebungsvertrag nur auf Papier mit eigenhändiger Unterschrift. E-Mail, Fax und Messenger sind unwirksam."}, {"t": "Allgemeiner Kündigungsschutz", "x": "Schutz aller Arbeitnehmer in Betrieben mit mehr als zehn Arbeitnehmern nach einer Wartezeit von sechs Monaten. Eine Kündigung ist dann nur wirksam, wenn sie sozial gerechtfertigt ist (§ 1 Abs. 1 KSchG)."}, {"t": "Inhalt einer Abmahnung", "x": "Genaues Fehlverhalten mit Datum, klare Aufforderung zu vertragsgemäßem Verhalten, Androhung arbeitsrechtlicher Folgen bis zur Kündigung."}, {"t": "Ohne Anhörung keine wirksame Kündigung", "x": "Der Betriebsrat entscheidet nicht über die Kündigung, aber er muss vorher gehört werden. Schweigen gilt nur bei der ordentlichen Kündigung nach einer Woche als Zustimmung."}, {"t": "Besonderer Kündigungsschutz", "x": "Zusätzlicher Schutz für bestimmte Gruppen, bei denen eine Kündigung ganz ausgeschlossen ist oder nur mit Zustimmung einer Behörde oder des Betriebsrats wirksam wird (§ 168 SGB IX, § 17 MuSchG, § 18 BEEG, § 15 KSchG)."}, {"t": "Form, Inhalt, Frist", "x": "Erst Form, Zugang und Betriebsrat prüfen, dann besonderen Schutz und sozialen Grund, zuletzt Kündigungsfrist und Klagefrist. Wer in dieser Reihenfolge prüft, übersieht keinen Fehler."}, {"t": "Qualifiziertes Zeugnis", "x": "Zeugnis, das neben Art und Dauer der Tätigkeit auch Leistung und Verhalten beurteilt. Es wird nur auf Verlangen des Arbeitnehmers erteilt (§ 109 Abs. 1 GewO)."}], "sortier": [{"titel": "Ordentlich oder außerordentlich?", "auftrag": "Ordne jedes Merkmal und jeden Fall der ordentlichen oder der außerordentlichen Kündigung zu.", "kategorien": [{"id": "a", "name": "Ordentlich"}, {"id": "b", "name": "Außerordentlich"}], "items": [{"text": "Kündigung mit Frist nach § 622 BGB", "kat": "a", "expl": "Die ordentliche Kündigung hält eine Kündigungsfrist ein."}, {"text": "Albers erhält die Kündigung zum 31.05.2027", "kat": "a", "expl": "Bei 12 Jahren gelten 5 Monate zum Monatsende. Das ist eine ordentliche Kündigung mit Frist."}, {"text": "Grundfrist 4 Wochen zum 15. oder zum Monatsende", "kat": "a", "expl": "Das ist die gesetzliche Grundfrist für die ordentliche Kündigung (§ 622 Abs. 1 BGB)."}, {"text": "Betriebsrat hat eine Woche Zeit für Bedenken", "kat": "a", "expl": "Bei der ordentlichen Kündigung gilt eine Woche (§ 102 BetrVG)."}, {"text": "Schweigt der Betriebsrat, gilt die Zustimmung als erteilt", "kat": "a", "expl": "Diese Regel steht nur für die ordentliche Kündigung im Gesetz."}, {"text": "Widerspruch des Betriebsrats ist möglich", "kat": "a", "expl": "Ein Widerspruch ist nur gegen eine ordentliche Kündigung vorgesehen."}, {"text": "In der Probezeit mit einer Frist von 2 Wochen", "kat": "a", "expl": "Auch in der Probezeit gibt es eine Frist. Die Kündigung ist also ordentlich."}, {"text": "Meist fristlos nach § 626 BGB", "kat": "b", "expl": "Die außerordentliche Kündigung beendet das Arbeitsverhältnis meist sofort."}, {"text": "Nur aus wichtigem Grund nach Abwägung der Interessen", "kat": "b", "expl": "Ein wichtiger Grund muss die Weiterarbeit bis zum Fristende unzumutbar machen."}, {"text": "Zugang innerhalb von 2 Wochen ab Kenntnis des Grundes", "kat": "b", "expl": "Diese Frist gilt für die außerordentliche Kündigung (§ 626 Abs. 2 BGB)."}, {"text": "Diebstahl am 02.12. bemerkt, Kündigung bis 16.12.", "kat": "b", "expl": "Zwei Wochen ab Kenntnis enden am 16.12.2026. Danach ist die fristlose Kündigung zu spät."}, {"text": "Betriebsrat muss sich binnen 3 Tagen äußern", "kat": "b", "expl": "Bei der außerordentlichen Kündigung hat der Betriebsrat nur 3 Tage."}, {"text": "Betriebsratsmitglied, nur mit Zustimmung des Betriebsrats", "kat": "b", "expl": "Eine ordentliche Kündigung ist ausgeschlossen. Möglich ist nur die außerordentliche mit Zustimmung."}]}, {"titel": "Warum wird gekündigt?", "auftrag": "Bestimme für jeden Fall, welcher Grund nach dem KSchG vorliegt.", "kategorien": [{"id": "a", "name": "personenbedingt"}, {"id": "b", "name": "verhaltensbedingt"}, {"id": "c", "name": "betriebsbedingt"}], "items": [{"text": "Lang andauernde Krankheit mit negativer Prognose", "kat": "a", "expl": "Die Person kann nicht mehr arbeiten, ohne dass ihr ein Vorwurf gemacht wird."}, {"text": "Ein Berufskraftfahrer verliert seinen Führerschein", "kat": "a", "expl": "Ohne Führerschein kann er die Arbeit nicht leisten. Der Grund liegt in der Person."}, {"text": "Die Arbeitserlaubnis fehlt", "kat": "a", "expl": "Die Person darf nicht arbeiten. Das ist ein Grund in der Person."}, {"text": "Die Person kann die Arbeit nicht mehr leisten, ohne Schuld", "kat": "a", "expl": "Kann nicht heißt personenbedingt. Will nicht wäre verhaltensbedingt."}, {"text": "Albers fehlt nach zwei Abmahnungen wieder unentschuldigt", "kat": "b", "expl": "Er verletzt seine Pflichten, obwohl er anders könnte. Das ist verhaltensbedingt."}, {"text": "Ständige Unpünktlichkeit trotz Abmahnung", "kat": "b", "expl": "Zu spät kommen ist steuerbares Verhalten. Nach der Abmahnung droht die Kündigung."}, {"text": "Beleidigung von Kolleginnen und Kollegen", "kat": "b", "expl": "Eine Beleidigung ist eine Pflichtverletzung. Der Grund liegt im Verhalten."}, {"text": "Vorher ist in der Regel eine Abmahnung nötig", "kat": "b", "expl": "Die Abmahnung warnt vor der Kündigung. Sie gehört zum verhaltensbedingten Grund."}, {"text": "Die Person verletzt Pflichten, obwohl sie anders könnte", "kat": "b", "expl": "Will nicht heißt verhaltensbedingt."}, {"text": "Neue Software, eine Stelle im Rechnungswesen fällt weg", "kat": "c", "expl": "Eine unternehmerische Entscheidung lässt den Arbeitsplatz wegfallen."}, {"text": "Automatische Lackieranlage ersetzt Arbeitsplätze", "kat": "c", "expl": "Die Ursache liegt im Betrieb, nicht bei der Person."}, {"text": "Sozialauswahl unter vergleichbaren Beschäftigten", "kat": "c", "expl": "Die Sozialauswahl gibt es nur bei der betriebsbedingten Kündigung (§ 1 Abs. 3 KSchG)."}, {"text": "Auftragsmangel, ein Arbeitsplatz fällt dauerhaft weg", "kat": "c", "expl": "Fehlende Aufträge sind ein dringendes betriebliches Erfordernis."}, {"text": "Abfindung nach § 1a KSchG bei Verzicht auf Klage", "kat": "c", "expl": "Diesen gesetzlichen Anspruch gibt es nur bei betriebsbedingter Kündigung mit Hinweis."}]}]}, {"nr": 9, "title": "Personalcontrolling", "date": "03.12.2026", "quiz": [{"q": "Was bedeutet das englische Verb to control im Wort Controlling vor allem?", "o": ["Steuern und lenken", "Bestrafen und abmahnen", "Zählen und abheften", "Verbieten und sperren"], "c": 0, "e": "To control heißt in erster Linie steuern. Kontrolle im deutschen Sinn ist nur ein Teil des Controllings."}, {"q": "Welche Beschreibung passt am besten zum Personalcontrolling?", "o": ["Planung, Steuerung und Kontrolle der Personalarbeit mit Kennzahlen", "Überwachung einzelner Beschäftigter am Arbeitsplatz mit Kameras und Listen", "Abrechnung der monatlichen Löhne und Gehälter", "Auswahl neuer Beschäftigter im Vorstellungsgespräch"], "c": 0, "e": "Personalcontrolling plant, steuert und kontrolliert die Personalarbeit mit Informationen und Kennzahlen. Die Entgeltabrechnung liefert nur Daten dafür."}, {"q": "Was ist eine Kennzahl?", "o": ["Eine Zahl, die einen Sachverhalt kurz und vergleichbar ausdrückt", "Die Personalnummer einer beschäftigten Person", "Ein Passwort für die Personalsoftware", "Die Nummer eines Kontos im Industriekontenrahmen für Personalkosten"], "c": 0, "e": "Kennzahlen verdichten Informationen, zum Beispiel die Krankenquote in Prozent. So kann man Jahre und Betriebe vergleichen."}, {"q": "Dr. Katrin Lorenz möchte 2027 auf Grundlage von Zahlen planen. Welche Aufgabe übernimmt dabei das Personalcontrolling?", "o": ["Es liefert aufbereitete Daten als Grundlage für Entscheidungen", "Es trifft alle Personalentscheidungen anstelle der Geschäftsführung", "Es kündigt Beschäftigten mit vielen Fehltagen", "Es verhandelt den Tarifvertrag mit der Gewerkschaft"], "c": 0, "e": "Personalcontrolling unterstützt Entscheidungen. Entscheiden muss weiterhin die Geschäftsführung."}, {"q": "Welches Ziel ist ein soziales Ziel des Personalcontrollings?", "o": ["Zufriedenheit der Beschäftigten erhöhen", "Umsatz je Fahrrad steigern", "Materialkosten in der Montage dauerhaft senken", "Lagerbestand an Rahmen verringern"], "c": 0, "e": "Soziale Ziele betreffen die Menschen, also Zufriedenheit, Gesundheit und Entwicklung."}, {"q": "Was bedeutet Transparenz als Ziel des Personalcontrollings?", "o": ["Alle Beteiligten haben einen klaren Überblick über die Lage", "Alle Gehälter werden für jeden sichtbar am Schwarzen Brett ausgehängt", "Die Büros der Personalabteilung haben Glaswände", "Jeder darf jede Personalakte lesen"], "c": 0, "e": "Transparenz heißt Überblick und Klarheit. Datenschutz gilt trotzdem, Personalakten und Gehälter bleiben geschützt."}, {"q": "Mit welchem Schritt beginnt der Regelkreis des Personalcontrollings?", "o": ["Ziele planen", "Maßnahmen steuern", "Ursachen analysieren", "Soll und Ist vergleichen"], "c": 0, "e": "Zuerst werden Sollwerte geplant. Danach folgen Ist erfassen, vergleichen, Ursachen analysieren und steuern."}, {"q": "Woher kommen bei Nordstern viele Sollwerte für das Personalcontrolling?", "o": ["Aus der Personalplanung", "Aus dem Arbeitszeugnis", "Aus der Stellenanzeige", "Aus dem Ausbildungsvertrag"], "c": 0, "e": "Die Personalplanung legt fest, wie viel Personal mit welchen Kosten gebraucht wird. Diese Werte sind die Sollwerte."}, {"q": "Welche Aussage in einem Personalbericht ist eine Deutung und keine reine Tatsachenaussage?", "o": ["Vermutlich treibt die Schichtarbeit die Eigenkündigungen nach oben", "Die Fluktuationsquote 2025 beträgt 5,93 %", "Im Jahr 2025 haben 14 Beschäftigte selbst gekündigt", "Die Rücklaufquote der Befragung liegt bei 70 %"], "c": 0, "e": "Tatsachenaussagen beschreiben gemessene Zahlen. Eine Deutung nennt eine mögliche Ursache und muss als Vermutung erkennbar sein."}, {"q": "Welche Funktion des Personalcontrollings sammelt Daten und bereitet sie verständlich auf?", "o": ["Informationsfunktion", "Steuerungsfunktion", "Kontrollfunktion", "Planungsfunktion"], "c": 0, "e": "Die Informationsfunktion liefert und ordnet die Daten, zum Beispiel als Tabelle oder Diagramm."}, {"q": "Malte Brandt legt fest, dass die Krankenquote 2026 höchstens 5,5 % betragen soll. Welche Funktion ist das?", "o": ["Planungsfunktion", "Frühwarnfunktion", "Informationsfunktion", "Kontrollfunktion"], "c": 0, "e": "Ein Zielwert wird festgelegt. Das gehört zur Planung."}, {"q": "Nordstern stellt wegen hoher Überstunden zwei zusätzliche Monteure ein. Welche Funktion zeigt sich hier?", "o": ["Steuerungsfunktion", "Informationsfunktion", "Planungsfunktion", "Kontrollfunktion"], "c": 0, "e": "Eine Maßnahme wird umgesetzt, um ein Ziel zu erreichen. Das ist Steuerung."}, {"q": "Die Krankenquote im Lager steigt drei Monate hintereinander leicht an. Welche Funktion ist hier vor allem gefragt?", "o": ["Frühwarnfunktion", "Planungsfunktion", "Steuerungsfunktion", "Abrechnungsfunktion"], "c": 0, "e": "Ein Trend zeigt ein Risiko, bevor es groß wird. Das erkennt die Frühwarnung. Eine Abrechnungsfunktion gibt es im Personalcontrolling nicht."}, {"q": "Was unterscheidet absolute von relativen Personalkennzahlen?", "o": ["Absolute sind einfache Zahlen, relative setzen zwei Größen ins Verhältnis", "Absolute sind immer genauer als relative Kennzahlen", "Relative Kennzahlen gibt es nur für Personalkosten", "Absolute Kennzahlen sind immer Planwerte"], "c": 0, "e": "Der Personalbestand von 240 ist absolut. Die Teilzeitquote setzt Teilzeitkräfte und Bestand ins Verhältnis und ist relativ."}, {"q": "Welcher Unterschied besteht zwischen Kontrolle und Frühwarnung?", "o": ["Kontrolle schaut zurück, Frühwarnung schaut nach vorn", "Kontrolle nutzt Zahlen, Frühwarnung nur Gefühle", "Kontrolle macht der Betriebsrat, Frühwarnung die Hausbank des Betriebs", "Kontrolle gilt nur für Auszubildende"], "c": 0, "e": "Kontrolle vergleicht einen abgeschlossenen Zeitraum mit dem Plan. Frühwarnung erkennt Trends und künftige Risiken."}, {"q": "Welches Beispiel gehört zum operativen Personalcontrolling?", "o": ["Überstunden der Montage im Oktober auswerten", "Personalstrategie bis 2035 entwickeln", "Nachfolge für alle Führungskräfte bis 2032 planen", "Künftige Berufe in der E-Bike-Fertigung abschätzen"], "c": 0, "e": "Operativ heißt kurzfristig, vom Monat bis zum Jahr. Die anderen Beispiele schauen viele Jahre voraus."}, {"q": "Welcher Zeitraum passt typischerweise zum operativen Personalcontrolling?", "o": ["Monat bis ein Jahr", "Fünf bis zehn Jahre", "Zehn bis zwanzig Jahre", "Die gesamte Firmengeschichte"], "c": 0, "e": "Operatives Personalcontrolling ist kurzfristig und betrifft den laufenden Betrieb."}, {"q": "Was misst quantitatives Personalcontrolling?", "o": ["Mengen und Geldbeträge wie Kosten, Köpfe und Tage", "Nur Meinungen aus Gesprächen mit Führungskräften und Betriebsrat", "Nur die Stimmung in der Kantine", "Nur die Inhalte der Arbeitszeugnisse"], "c": 0, "e": "Quantitativ kommt von Quantität, also Menge. Es geht um zählbare Größen."}, {"q": "Wie macht man qualitative Größen wie Zufriedenheit messbar?", "o": ["Mit Befragungen und Bewertungsskalen", "Mit der Lohnsteuertabelle des laufenden Jahres", "Mit dem Kontenplan nach IKR", "Mit der Stempeluhr am Werkstor"], "c": 0, "e": "Befragungen mit Skalen, etwa von 1 bis 5, machen weiche Größen sichtbar und vergleichbar."}, {"q": "Die Altersstruktur von Nordstern bis 2035 wird ausgewertet. Wie ordnen Sie das ein?", "o": ["Strategisch und quantitativ", "Operativ und qualitativ", "Operativ und quantitativ", "Strategisch und qualitativ"], "c": 0, "e": "Der Blick geht viele Jahre nach vorn, also strategisch. Gezählt werden Köpfe je Altersgruppe, also quantitativ."}, {"q": "Die Zufriedenheit mit der Schichtplanung im letzten Quartal wird ausgewertet. Wie ordnen Sie das ein?", "o": ["Operativ und qualitativ", "Strategisch und quantitativ", "Strategisch und qualitativ", "Operativ und quantitativ"], "c": 0, "e": "Ein Quartal ist kurzfristig, also operativ. Zufriedenheit ist eine weiche Größe, also qualitativ."}, {"q": "Welche Frage stellt das Effizienzcontrolling?", "o": ["Stimmt das Verhältnis von Aufwand und Ergebnis?", "Wie hoch ist der gesamte Personalaufwand?", "Welche Strategie verfolgt das Unternehmen?", "Wie viele Beschäftigte sind über 50 Jahre alt und bald in Rente?"], "c": 0, "e": "Effizienz bedeutet Wirtschaftlichkeit. Man setzt Aufwand und Ergebnis ins Verhältnis, etwa Kosten je Weiterbildungstag."}, {"q": "Nordstern prüft, ob ein Führungstraining die Zahl der Eigenkündigungen gesenkt hat. Welche Ebene ist das?", "o": ["Effektivitätscontrolling", "Kostencontrolling", "Effizienzcontrolling", "Budgetcontrolling"], "c": 0, "e": "Gefragt ist die Wirkung einer Maßnahme auf ein Unternehmensziel. Das ist Effektivität."}, {"q": "Malte Brandt möchte die Entwicklung der Krankenquote von 2021 bis 2025 im Personalbericht zeigen. Welche Darstellung passt am besten?", "o": ["Liniendiagramm", "Kreisdiagramm", "Organigramm", "Netzplan"], "c": 0, "e": "Eine Linie zeigt die Entwicklung über die Zeit. Kreisdiagramme zeigen Anteile an einem Ganzen."}, {"q": "Nordstern schult 12 Beschäftigte der Lackiererei für 24.000 €. Wie hoch sind die Kosten je Teilnehmer?", "o": ["2.000 €", "1.200 €", "2.400 €", "288 €"], "c": 0, "e": "24.000 € ÷ 12 = 2.000 € je Teilnehmer. Das ist eine Effizienzkennzahl."}, {"q": "Welche Daten liefert vor allem die Zeiterfassung?", "o": ["Anwesenheit, Überstunden und Krankheitstage", "Steuerklasse, Konfession und Bankverbindung der Beschäftigten", "Noten aus dem Ausbildungszeugnis", "Umsatz je Fahrradmodell"], "c": 0, "e": "Die Zeiterfassung zeigt, wann gearbeitet wurde und wann jemand fehlte."}, {"q": "Was ist ein Austrittsgespräch?", "o": ["Ein Gespräch mit Ausscheidenden über ihre Gründe", "Ein Gespräch mit Bewerbern kurz vor dem Abschluss des Vertrags", "Ein Gespräch des Betriebsrats mit der Gewerkschaft", "Ein Gespräch über den Urlaubsantrag für den Sommer"], "c": 0, "e": "Im Austrittsgespräch erfährt das Unternehmen, warum Menschen gehen. Das hilft bei der Deutung der Fluktuation."}, {"q": "Was zeigt eine Bestandsstatistik?", "o": ["Wie viele Personen an einem Stichtag beschäftigt sind", "Wie viele Personen im Lauf des Jahres ein- und ausgetreten sind", "Wie hoch der Umsatz je Abteilung ist", "Wie viele Bewerbungen eingegangen sind"], "c": 0, "e": "Die Bestandsstatistik zeigt den Personalbestand zu einem Zeitpunkt. Zugänge und Abgänge zeigt die Bewegungsstatistik."}, {"q": "Welche Statistik gliedert den Personalbestand nach Alter, Geschlecht oder Teilzeit?", "o": ["Strukturstatistik", "Bewegungsstatistik", "Umsatzstatistik", "Lagerstatistik"], "c": 0, "e": "Die Strukturstatistik zeigt die Zusammensetzung des Bestands nach Merkmalen."}, {"q": "Bei Nordstern arbeiten am 31.12.2025 insgesamt 240 Personen, davon 72 Frauen. Wie hoch ist der Frauenanteil?", "o": ["30,0 %", "72,0 %", "42,9 %", "33,3 %"], "c": 0, "e": "72 ÷ 240 × 100 = 30,0 %. Die 42,9 % entstehen, wenn man fälschlich durch die 168 Männer teilt."}, {"q": "Von den 240 Beschäftigten bei Nordstern arbeiten 30 in Teilzeit. Wie hoch ist die Teilzeitquote?", "o": ["12,5 %", "8,0 %", "30,0 %", "14,3 %"], "c": 0, "e": "30 ÷ 240 × 100 = 12,5 %."}, {"q": "Wie berechnet man die absolute Abweichung im Soll-Ist-Vergleich?", "o": ["Ist minus Soll", "Soll geteilt durch Ist", "Soll plus Ist", "Ist mal Soll"], "c": 0, "e": "Die absolute Abweichung ist der Unterschied Ist minus Soll. Das Vorzeichen zeigt, ob der Plan über- oder unterschritten wurde."}, {"q": "Geplant waren 7.500 Überstunden, tatsächlich angefallen sind 9.440. Wie hoch ist die Abweichung in Prozent?", "o": ["+ 25,87 %", "+ 20,55 %", "+ 19,40 %", "+ 125,87 %"], "c": 0, "e": "Abweichung 9.440 − 7.500 = 1.940 Std. 1.940 ÷ 7.500 × 100 = 25,87 %. Wer durch das Ist teilt, erhält falsch 20,55 %."}, {"q": "Der Personalaufwand war mit 15,2 Mio. € geplant und betrug 15,6 Mio. €. Wie hoch ist die Abweichung in Prozent?", "o": ["+ 2,63 %", "+ 2,56 %", "+ 0,40 %", "+ 4,00 %"], "c": 0, "e": "0,4 ÷ 15,2 × 100 = 2,63 %. Bezugsgröße ist immer das Soll."}, {"q": "Was ist eine Toleranzgrenze im Soll-Ist-Vergleich?", "o": ["Eine Grenze, ab der eine Abweichung genauer untersucht wird", "Die gesetzliche Höchstgrenze für Überstunden je Monat und Person", "Die Zahl der erlaubten Krankheitstage je Person", "Der Mindestbetrag für eine Erfolgsprämie"], "c": 0, "e": "Kleine Abweichungen sind normal. Erst ab der Toleranzgrenze, bei Nordstern 2 %, folgt eine Abweichungsanalyse."}, {"q": "Der Personalaufwand bei Nordstern lag 2025 um 0,4 Mio. € über dem Plan. Welche Ursache zeigt einen Steuerungsbedarf in der Montage?", "o": ["Zusätzliche Überstunden wegen fehlender Kräfte", "Die bewusst beschlossene Erfolgsprämie für alle Beschäftigten", "Die Lackiererei hat neue Farbtöne bestellt", "Der Umsatz ist auf 48,0 Mio. € gestiegen"], "c": 0, "e": "Die Prämie war gewollt. Viele Überstunden zeigen dagegen, dass Personal fehlt, also muss gesteuert werden."}, {"q": "Was bedeutet Benchmarking im Personalcontrolling?", "o": ["Eigene Werte mit einem Maßstab vergleichen, um zu lernen", "Bewerbungen nach Notendurchschnitt und Berufserfahrung sortieren", "Arbeitsplätze mit neuen Bänken ausstatten", "Löhne im Betrieb geheim halten"], "c": 0, "e": "Beim Benchmarking vergleicht man sich mit früheren Jahren, anderen Betrieben oder Durchschnittswerten und lernt von den Besten."}, {"q": "Nordstern vergleicht die Fluktuation 2025 mit der Fluktuation 2024. Welche Vergleichsart ist das?", "o": ["Zeitvergleich", "Betriebsvergleich", "Branchenvergleich", "Soll-Ist-Vergleich"], "c": 0, "e": "Man vergleicht dieselbe Kennzahl desselben Betriebs in verschiedenen Jahren."}, {"q": "Bei Nordstern wurden 240 Beschäftigte befragt, 168 haben geantwortet. Wie hoch ist die Rücklaufquote?", "o": ["70 %", "168 %", "30 %", "71,2 %"], "c": 0, "e": "168 ÷ 240 × 100 = 70 %. Die 71,2 % entstehen, wenn man falsch durch 236 teilt."}, {"q": "Was ist ein Kennzahlen-Cockpit?", "o": ["Eine Übersicht wichtiger Kennzahlen mit Zielwerten und Ampel", "Ein Schulungsraum für Führungskräfte", "Ein Programm für die Berechnung der Lohnsteuer im Monat", "Eine Liste aller Personalnummern"], "c": 0, "e": "Ein Cockpit zeigt mehrere Kennzahlen auf einen Blick, meist mit Ampelfarben für die Zielerreichung."}, {"q": "Warum betrachtet man Kennzahlen besser in einem Kennzahlensystem als einzeln?", "o": ["Erst der Zusammenhang mehrerer Kennzahlen zeigt die Lage", "Einzelne Kennzahlen sind gesetzlich verboten", "Ein System braucht keine Zielwerte", "Ein System ersetzt jedes Gespräch mit Beschäftigten und Betriebsrat"], "c": 0, "e": "Steigen etwa Überstunden und Krankenquote gleichzeitig, deutet das auf Überlastung. Eine Zahl allein kann täuschen."}, {"q": "Nordstern möchte eine neue Software einführen, die Arbeitszeiten und Leistungen der Beschäftigten auswerten kann. Was gilt?", "o": ["Der Betriebsrat hat ein Mitbestimmungsrecht", "Die Software darf ohne Beteiligung eingeführt werden", "Nur die Krankenkasse muss zustimmen", "Die Beschäftigten müssen einzeln kündigen"], "c": 0, "e": "Bei technischen Einrichtungen, die Verhalten oder Leistung überwachen können, bestimmt der Betriebsrat mit (§ 87 Abs. 1 Nr. 6 BetrVG)."}, {"q": "Was versteht man bei einer Kennzahl unter der Bezugsgröße?", "o": ["Die Zahl, durch die man teilt", "Die Zahl, die man mit 100 malnimmt", "Das Ergebnis der Rechnung in Prozent", "Den Zielwert aus dem Cockpit"], "c": 0, "e": "Die Bezugsgröße steht im Nenner. Bei der Fluktuationsquote ist das der durchschnittliche Personalbestand."}, {"q": "Mit welchem Personalbestand rechnet Nordstern die meisten Kennzahlen für 2025?", "o": ["Mit dem durchschnittlichen Bestand von 236", "Mit dem Stichtagsbestand von 240", "Mit dem Bestand ohne Auszubildende von 230", "Mit dem Bestand der Montage am Jahresende von 100"], "c": 0, "e": "Kündigungen, Krankheitstage, Kosten und Überstunden fallen über das Jahr an. Darum teilt man durch den Durchschnitt 236."}, {"q": "Für welche Kennzahl nutzt Nordstern den Stichtagsbestand von 240 Beschäftigten?", "o": ["Ausbildungsquote", "Krankenquote", "Fluktuationsquote", "Überstundenquote"], "c": 0, "e": "Die Ausbildungsquote beschreibt einen Zustand am 31.12.2025 und nutzt deshalb den Stichtag 240."}, {"q": "Am 31.12.2024 hatte Nordstern 232 Beschäftigte, am 31.12.2025 genau 240. Wie hoch ist der durchschnittliche Personalbestand 2025?", "o": ["236", "240", "472", "234"], "c": 0, "e": "(232 + 240) ÷ 2 = 472 ÷ 2 = 236."}, {"q": "Warum teilt man die Zahl der Eigenkündigungen eines Jahres durch den durchschnittlichen Bestand?", "o": ["Kündigungen fallen über das ganze Jahr verteilt an", "Der Stichtag ist gesetzlich für Kündigungen verboten", "Der Durchschnitt ist immer größer als der Stichtag", "Der Durchschnitt enthält keine Auszubildenden"], "c": 0, "e": "Ereignisse, die sich über das Jahr verteilen, bezieht man auf den mittleren Bestand des Jahres."}, {"q": "Wie lautet die vereinfachte Formel der Fluktuationsquote im Kurs?", "o": ["Kündigungen durch Beschäftigte ÷ Ø Personalbestand × 100", "Alle Abgänge einschließlich Rente ÷ Stichtagsbestand × 100", "Neueinstellungen ÷ Ø Personalbestand × 100", "Kündigungen durch Arbeitgeber ÷ Umsatz × 100"], "c": 0, "e": "Im Kurs zählen nur Kündigungen durch die Beschäftigten, bezogen auf den durchschnittlichen Bestand."}, {"q": "Bei Nordstern haben 2025 genau 14 Beschäftigte selbst gekündigt. Wie hoch ist die Fluktuationsquote?", "o": ["5,93 %", "5,83 %", "6,09 %", "16,86 %"], "c": 0, "e": "14 ÷ 236 × 100 = 5,93 %. Wer durch 240 teilt, erhält falsch 5,83 %."}, {"q": "Nordstern hatte 2024 bei durchschnittlich 230 Beschäftigten 11 Eigenkündigungen. Wie hoch war die Fluktuationsquote 2024?", "o": ["4,78 %", "4,66 %", "4,74 %", "2,09 %"], "c": 0, "e": "11 ÷ 230 × 100 = 4,78 %."}, {"q": "Die Fluktuationsquote steigt von 4,78 % auf 5,93 %. Wie beschreibt man die Veränderung richtig?", "o": ["Anstieg um 1,15 Prozentpunkte", "Anstieg um 1,15 Prozent", "Anstieg um 5,93 Prozentpunkte", "Rückgang um 1,15 Prozentpunkte"], "c": 0, "e": "Der Abstand zwischen zwei Quoten wird in Prozentpunkten angegeben. 5,93 − 4,78 = 1,15 Prozentpunkte."}, {"q": "Welcher Vergleichswert für Eigenkündigungen in Deutschland ergibt sich als Näherung aus den Daten des Instituts der deutschen Wirtschaft?", "o": ["Etwa 4,9 % der Beschäftigten", "Etwa 9,4 % der Beschäftigten", "Etwa 52 % der Beschäftigten", "Etwa 14,6 % der Beschäftigten"], "c": 0, "e": "2022 schieden 9,4 % aus, davon 52 % durch Eigenkündigung. 9,4 × 0,52 ergibt rund 4,9 %. Das ist eine eigene Näherung."}, {"q": "Ein Lehrbuch zählt in der Fluktuationsquote alle Abgänge. Wie heißt dort die Quote, die nur Kündigungen durch Beschäftigte erfasst?", "o": ["Eigenkündigungsquote", "Einstellungsquote", "Ausbildungsquote", "Flexi-Quote"], "c": 0, "e": "Die Eigenkündigungsquote teilt die Kündigungen durch Beschäftigte durch den Personalbestand. Sie entspricht der vereinfachten Fluktuationsformel im Kurs."}, {"q": "Wie lautet die Formel der Krankenquote?", "o": ["Krankheitstage ÷ Soll-Arbeitstage × 100", "Krankheitstage ÷ Kalendertage × 100", "Krankheitstage ÷ Ø Personalbestand × 100", "Kranke Personen ÷ Urlaubstage × 100"], "c": 0, "e": "Die Krankenquote setzt die Krankheitstage ins Verhältnis zu den geplanten Arbeitstagen."}, {"q": "Wie viele Soll-Arbeitstage hat Nordstern 2025 insgesamt bei durchschnittlich 236 Beschäftigten und 220 Tagen je Person?", "o": ["51.920", "52.800", "86.140", "50.600"], "c": 0, "e": "236 × 220 = 51.920. Die 52.800 entstehen mit 240 Beschäftigten, die 86.140 mit 365 Kalendertagen."}, {"q": "Nordstern hatte 2025 genau 3.115 Krankheitstage bei 51.920 Soll-Arbeitstagen. Wie hoch ist die Krankenquote?", "o": ["6,00 %", "3,62 %", "13,20 %", "5,90 %"], "c": 0, "e": "3.115 ÷ 51.920 × 100 = 6,00 %. Die 3,62 % entstehen mit Kalendertagen, 13,2 ist die Zahl der Tage je Person."}, {"q": "Wie viele Krankheitstage entfallen 2025 im Durchschnitt auf jede beschäftigte Person bei Nordstern?", "o": ["13,2 Tage", "14,6 Tage", "12,9 Tage", "6,0 Tage"], "c": 0, "e": "3.115 ÷ 236 = 13,2 Tage. Die 14,6 Tage sind der Wert für Deutschland."}, {"q": "Ein Zulieferer hat Personalkosten von 12,0 Mio. € und Gesamtkosten von 40,0 Mio. €. Wie hoch ist die Personalkostenquote nach der Formel mit den Gesamtkosten?", "o": ["30,00 %", "33,33 %", "3,33 %", "70,00 %"], "c": 0, "e": "Personalkostenquote = Personalkosten ÷ Gesamtkosten × 100 = 12,0 ÷ 40,0 × 100 = 30,00 %."}, {"q": "Nordstern hatte 2024 bei durchschnittlich 230 Beschäftigten 2.900 Krankheitstage. Wie hoch war die Krankenquote bei 220 Soll-Arbeitstagen?", "o": ["5,73 %", "5,49 %", "12,61 %", "3,45 %"], "c": 0, "e": "230 × 220 = 50.600 Soll-Arbeitstage. 2.900 ÷ 50.600 × 100 = 5,73 %."}, {"q": "Wie lautet die Formel der Personalaufwandsquote?", "o": ["Personalaufwand ÷ Umsatz × 100", "Umsatz ÷ Personalaufwand × 100", "Personalaufwand ÷ Ø Personalbestand × 100", "Personalaufwand ÷ Gewinn × 100"], "c": 0, "e": "Die Quote zeigt, welcher Anteil des Umsatzes für das Personal ausgegeben wird."}, {"q": "Nordstern hatte 2025 einen Personalaufwand von 15,6 Mio. € und einen Umsatz von 48,0 Mio. €. Wie hoch ist die Personalaufwandsquote?", "o": ["32,5 %", "30,8 %", "307,7 %", "3,08 %"], "c": 0, "e": "15,6 ÷ 48,0 × 100 = 32,5 %."}, {"q": "Wie hoch ist der Personalaufwand je Beschäftigten bei Nordstern 2025?", "o": ["66.101,69 €", "65.000,00 €", "203.389,83 €", "47.400,00 €"], "c": 0, "e": "15.600.000 € ÷ 236 = 66.101,69 €. Mit 240 erhielte man 65.000 €, die 203.389,83 € sind der Umsatz je Beschäftigten."}, {"q": "Der Personalaufwand von Nordstern stieg von 2024 auf 2025 um 5,41 %, der Umsatz um 6,67 %. Was folgt für die Personalaufwandsquote?", "o": ["Sie sinkt, weil der Umsatz schneller wächst", "Sie steigt, weil der Personalaufwand wächst", "Sie bleibt gleich, weil Aufwand und Umsatz wachsen", "Sie lässt sich ohne Bestand nicht berechnen"], "c": 0, "e": "Wächst der Nenner Umsatz stärker als der Zähler Personalaufwand, sinkt die Quote. Bei Nordstern von 32,89 % auf 32,50 %."}, {"q": "Die Nordstern Service GmbH hat einen Personalaufwand von 0,92 Mio. € und einen Umsatz von 2,3 Mio. €. Wie hoch ist die Personalaufwandsquote?", "o": ["40,0 %", "25,0 %", "4,0 %", "250,0 %"], "c": 0, "e": "0,92 ÷ 2,3 × 100 = 40,0 %."}, {"q": "Wie lautet die Formel der Überstundenquote?", "o": ["Überstunden ÷ Soll-Arbeitsstunden × 100", "Überstunden ÷ durchschnittlicher Personalbestand × 100", "Soll-Arbeitsstunden ÷ Überstunden × 100", "Überstunden ÷ Krankheitstage × 100"], "c": 0, "e": "Die Überstunden werden ins Verhältnis zu den geplanten Arbeitsstunden gesetzt."}, {"q": "Wie kommt Nordstern auf 1.540 Soll-Arbeitsstunden je Person im Jahr?", "o": ["220 Soll-Arbeitstage × 7 Stunden", "220 Soll-Arbeitstage × 8 Stunden", "52 Wochen × 35 Stunden", "365 Tage × 4,2 Stunden"], "c": 0, "e": "Bei der 35-Stunden-Woche sind es 7 Stunden je Tag. 220 × 7 = 1.540."}, {"q": "Nordstern hatte 2025 genau 9.440 Überstunden bei 363.440 Soll-Arbeitsstunden. Wie hoch ist die Überstundenquote?", "o": ["2,60 %", "4,00 %", "2,55 %", "26,0 %"], "c": 0, "e": "9.440 ÷ 363.440 × 100 = 2,60 %. Die 2,55 % entstehen mit 240 statt 236 Beschäftigten."}, {"q": "Wie viele Überstunden leistete jede beschäftigte Person bei Nordstern 2025 im Durchschnitt?", "o": ["40 Stunden", "39 Stunden", "2,6 Stunden", "154 Stunden"], "c": 0, "e": "9.440 ÷ 236 = 40 Stunden. Das ist keine Quote, sondern ein Wert je Person."}, {"q": "Worin unterscheiden sich die 1.540 Soll-Stunden von den 1.500 produktiven Stunden aus der Personalplanung?", "o": ["Bei den produktiven Stunden sind Ausfallzeiten schon abgezogen", "Die produktiven Stunden gelten nur für die Auszubildenden", "Die Soll-Stunden enthalten auch die Überstunden", "Die zwei Werte meinen genau dasselbe"], "c": 0, "e": "Soll-Stunden sind die vertraglich geplante Zeit. Produktive Stunden ziehen Krankheit, Weiterbildung und andere Ausfälle ab."}, {"q": "Die Nordstern Service GmbH hat 18 Beschäftigte, je 1.760 Soll-Stunden und 950 Überstunden. Wie hoch ist die Überstundenquote?", "o": ["3,00 %", "3,37 %", "5,40 %", "52,78 %"], "c": 0, "e": "18 × 1.760 = 31.680 Soll-Stunden. 950 ÷ 31.680 × 100 = 3,00 %."}, {"q": "Wie lautet die Formel der Ausbildungsquote?", "o": ["Auszubildende ÷ Beschäftigte gesamt × 100", "Auszubildende ÷ Bewerbungen × 100", "Übernommene Auszubildende ÷ alle Auszubildenden × 100", "Ausbildende ÷ Auszubildende × 100"], "c": 0, "e": "Die Ausbildungsquote zeigt, wie viele Auszubildende auf 100 Beschäftigte kommen."}, {"q": "Bei Nordstern sind am 31.12.2025 genau 10 von 240 Personen in Ausbildung. Wie hoch ist die Ausbildungsquote?", "o": ["4,17 %", "4,24 %", "4,35 %", "10,00 %"], "c": 0, "e": "10 ÷ 240 × 100 = 4,17 %. Mit 236 ergäbe sich falsch 4,24 %, ohne Auszubildende im Nenner 4,35 %."}, {"q": "Nordstern hatte 2025 genau 708 Weiterbildungstage. Wie viele Tage sind das je Beschäftigten?", "o": ["3,0 Tage", "2,95 Tage", "3,5 Tage", "0,3 Tage"], "c": 0, "e": "708 ÷ 236 = 3,0 Tage. Mit 240 ergäbe sich falsch 2,95 Tage."}, {"q": "Bei Nordstern sind 80 von 240 Beschäftigten 50 Jahre oder älter. Wie hoch ist dieser Anteil?", "o": ["33,3 %", "30,0 %", "71,4 %", "33,9 %"], "c": 0, "e": "80 ÷ 240 × 100 = 33,3 %. Die Altersstruktur nutzt den Stichtag."}, {"q": "In den Austrittsgesprächen 2025 nannten 4 von 14 Personen die Schichtarbeit als Hauptgrund. Welche Maßnahme passt dazu am besten?", "o": ["Schichtplan mit Mitsprache der Beschäftigten", "Alle Schichten ersatzlos und ohne Ausgleich streichen", "Die Austrittsgespräche abschaffen", "Die Ausbildungsquote senken"], "c": 0, "e": "Eine bessere Schichtplanung setzt an der Ursache an. Auch die Befragung zeigte mit 2,8 von 5 Punkten Unzufriedenheit."}, {"q": "Ein Beschäftigter war innerhalb eines Jahres mehr als sechs Wochen arbeitsunfähig. Was muss der Arbeitgeber anbieten?", "o": ["Ein betriebliches Eingliederungsmanagement", "Eine sofortige Änderungskündigung mit kürzerer Arbeitszeit", "Eine Kürzung des Urlaubs", "Eine Versetzung in die Probezeit"], "c": 0, "e": "Nach § 167 Abs. 2 SGB IX klärt der Arbeitgeber mit der Person, wie die Arbeitsunfähigkeit überwunden werden kann."}, {"q": "Was ist die beste Maßnahme gegen dauerhaft hohe Überstunden in der Montage?", "o": ["Zusätzliche Monteure einstellen", "Die Zeiterfassung abschalten", "Die Überstundenzuschläge verdoppeln", "Die Weiterbildung streichen"], "c": 0, "e": "Dauerhafte Überstunden zeigen Personalmangel. Nur mehr Personal löst die Ursache."}, {"q": "Nach welcher Regel vergibt Nordstern im Cockpit die Ampelfarbe Rot?", "o": ["Mehr als 10 % schlechter als der Zielwert", "Bis 10 % schlechter als der festgelegte Zielwert", "Zielwert genau erreicht", "Mehr als 10 % besser als der Zielwert"], "c": 0, "e": "Grün heißt erreicht, Gelb bis 10 % schlechter, Rot mehr als 10 % schlechter als der Zielwert."}, {"q": "Die Fluktuationsquote liegt bei 5,93 %, der Zielwert bei höchstens 5,0 %. Welche Ampelfarbe ergibt sich?", "o": ["Rot, weil sie 18,6 % über dem Ziel liegt", "Gelb, weil sie 0,93 % über dem Ziel liegt", "Grün, weil sie unter 10 % liegt", "Gelb, weil sie 9,1 % über dem Ziel liegt"], "c": 0, "e": "0,93 ÷ 5,0 × 100 = 18,6 %. Das ist mehr als 10 % schlechter, also Rot."}, {"q": "Warum sollte man die verfehlten Kennzahlen von Nordstern im Zusammenhang betrachten?", "o": ["Personalmangel, Überstunden, Krankheit und Kündigungen verstärken sich", "Jede Kennzahl hat immer genau eine einzige, feste Ursache", "Kennzahlen dürfen nur einzeln berichtet werden", "Zusammenhänge sind nur für den Betriebsrat interessant"], "c": 0, "e": "Fehlt Personal, steigen Überstunden, dann Krankheit und Kündigungen. Wer an einer Stelle ansetzt, verbessert oft mehrere Werte."}, {"q": "In welcher Reihenfolge geht man bei der Deutung einer auffälligen Kennzahl sinnvoll vor?", "o": ["Wert berechnen, Ursache klären, Maßnahme ableiten", "Maßnahme ableiten, Wert berechnen, Ursache klären", "Ursache raten, Maßnahme umsetzen, Wert löschen", "Wert berechnen, Maßnahme umsetzen, nie mehr messen"], "c": 0, "e": "Die drei W der Deutung lauten Wert, Warum, Was tun. Danach misst man im Folgejahr die Wirkung."}, {"q": "Was versteht man unter einer Fehlbesetzung?", "o": ["Eine Person arbeitet auf einer Stelle, für die sie nicht geeignet ist", "Eine Stelle ist im Stellenplan doppelt eingetragen worden", "Eine Person arbeitet in einer falschen Schicht ohne Absprache", "Eine Stelle bleibt länger als ein Jahr unbesetzt im Betrieb"], "c": 0, "e": "Bei einer Fehlbesetzung passen Person und Stelle nicht zusammen. Das führt oft zu Fehlern, Unzufriedenheit und am Ende zu einer Kündigung, die wieder Kosten verursacht."}, {"q": "Was ist ein Sollwert im Personalcontrolling?", "o": ["Ein geplanter Wert, der erreicht werden soll", "Ein Wert, der tatsächlich gemessen wurde", "Ein Wert, den der Gesetzgeber für alle vorgibt", "Ein Wert, der nur für Auszubildende gilt"], "c": 0, "e": "Der Sollwert ist der Planwert oder Zielwert. Der Istwert ist der tatsächlich gemessene Wert. Im Soll-Ist-Vergleich stellt man beide gegenüber."}, {"q": "Im Merkbild schaut, wer nur kontrolliert, in den Rückspiegel. Wofür steht der Blick durch die Frontscheibe?", "o": ["Für den Blick nach vorn auf Ziele und Risiken", "Für das Prüfen der Abrechnung des Vormonats", "Für das Ablegen von Unterlagen in der Personalakte", "Für das Zählen der Beschäftigten am Stichtag"], "c": 0, "e": "Controlling schaut nicht nur zurück, sondern auch nach vorn. Es plant Ziele, steuert und warnt früh vor Risiken."}, {"q": "Zu welcher Funktion des Personalcontrollings passt die Leitfrage „Was tun wir?“", "o": ["Steuerungsfunktion", "Informationsfunktion", "Frühwarnfunktion", "Kontrollfunktion"], "c": 0, "e": "Die Steuerungsfunktion leitet Maßnahmen ein, wenn ein Ziel in Gefahr ist. Die Information fragt dagegen, was los ist, die Frühwarnung, was morgen droht."}, {"q": "Welche Funktion beantwortet die Frage „Haben wir es erreicht?“", "o": ["Kontrollfunktion", "Planungsfunktion", "Steuerungsfunktion", "Informationsfunktion"], "c": 0, "e": "Die Kontrollfunktion prüft nach einem Zeitraum, ob das geplante Ziel erreicht wurde. Dazu vergleicht sie Soll und Ist."}, {"q": "Im Bild vom Navi entspricht jede Anzeige einer Funktion. Was entspricht der Planungsfunktion?", "o": ["Das Ziel eingeben", "Vor dem Stau warnen", "Die Ankunft prüfen", "Das Abbiegen ansagen"], "c": 0, "e": "Wer das Ziel eingibt, plant. Die Warnung vor dem Stau ist Frühwarnung, die Ansage zum Abbiegen ist Steuerung und die Prüfung der Ankunft ist Kontrolle."}, {"q": "Im Merkbild steht der Stratege auf dem Berg. Wofür steht der Operateur im Maschinenraum?", "o": ["Für den kurzfristigen Blick auf die Werte von heute", "Für den Blick auf die Personalstrategie bis 2035", "Für die Frage nach der Zufriedenheit im Team", "Für den Vergleich mit Werten aus ganz Deutschland"], "c": 0, "e": "Der Operateur schaut auf die Anzeige von heute. Das steht für das operative Personalcontrolling mit Kosten, Budgets und Fehlzeiten vom Monat bis zum Jahr."}, {"q": "Welche Größe kann man nicht direkt zählen und macht sie deshalb mit einer Skala messbar?", "o": ["Die Motivation in einem Team", "Die Zahl der Überstunden", "Die Zahl der Auszubildenden", "Die Höhe der Gehälter im Monat"], "c": 0, "e": "Motivation ist eine qualitative Größe. Man erfasst sie mit Befragungen und Skalen, zum Beispiel mit Noten von 1 bis 5."}, {"q": "Im Merkbild mit der Leiter steht eine Person für Effektivität. Was macht diese Person?", "o": ["Sie stellt die Leiter vorher an die richtige Wand", "Sie steigt besonders schnell die Leiter hinauf", "Sie kauft die günstigste Leiter im Baumarkt", "Sie zählt die Sprossen der Leiter genau nach"], "c": 0, "e": "Effektiv heißt, die richtigen Dinge zu tun. Wer die Leiter an die richtige Wand stellt, arbeitet am richtigen Ziel. Schnell hochsteigen steht für Effizienz."}, {"q": "Woraus lassen sich die Personalkosten für das Kostencontrolling am leichtesten ablesen?", "o": ["Aus der Buchhaltung", "Aus dem Austrittsgespräch", "Aus der Mitarbeiterbefragung", "Aus der Stellenbeschreibung"], "c": 0, "e": "Kosten werden in der Buchhaltung und in der Entgeltabrechnung erfasst. Darum ist das Kostencontrolling die einfachste der drei Ebenen."}, {"q": "Welche Datenquelle liefert dem Personalcontrolling vor allem die Personalkosten?", "o": ["Die Entgeltabrechnung", "Das Bewerbermanagement", "Die Weiterbildungsplanung", "Das Austrittsgespräch"], "c": 0, "e": "Die Entgeltabrechnung liefert Löhne, Gehälter und Arbeitgeberanteile. Bei Nordstern erstellt sie Sven Krüger."}, {"q": "Woher bekommt das Personalcontrolling Zahlen zu Bewerbungen und Einstellungen?", "o": ["Aus dem Bewerbermanagement", "Aus der Zeiterfassung", "Aus der Entgeltabrechnung", "Aus der Krankenstatistik"], "c": 0, "e": "Im Bewerbermanagement werden Bewerbungen, Gespräche und Einstellungen erfasst. Daraus lassen sich zum Beispiel die Kosten je Einstellung berechnen."}, {"q": "Was erfasst die Bewegungsstatistik?", "o": ["Zugänge und Abgänge in einem Zeitraum", "Den Bestand an einem einzigen Stichtag", "Die Gliederung nach Alter und Geschlecht", "Die Wege der Beschäftigten zum Betrieb"], "c": 0, "e": "Die Bewegungsstatistik zeigt, wer in einem Zeitraum neu hinzukommt und wer ausscheidet. Die Bestandsstatistik zeigt den Stand am Stichtag, die Strukturstatistik die Gliederung nach Merkmalen."}, {"q": "In welcher Reihenfolge wird aus Daten eine Entscheidung?", "o": ["Datenquellen, Personalstatistik, Kennzahlen, Bericht", "Bericht, Kennzahlen, Datenquellen, Personalstatistik", "Kennzahlen, Datenquellen, Bericht, Personalstatistik", "Personalstatistik, Bericht, Datenquellen, Kennzahlen"], "c": 0, "e": "Zuerst sammelt man Daten, dann ordnet die Personalstatistik sie. Daraus berechnet man Kennzahlen, fasst sie im Bericht zusammen und entscheidet."}, {"q": "Ab welcher Abweichung untersucht Nordstern einen Wert im Soll-Ist-Vergleich genauer?", "o": ["Ab einer Abweichung über 2 %", "Ab einer Abweichung über 10 %", "Ab einer Abweichung über 25 %", "Ab einer Abweichung über 50 %"], "c": 0, "e": "Nordstern hat eine Toleranzgrenze von 2 % festgelegt. Jede Abweichung darüber wird auf ihre Ursachen untersucht."}, {"q": "Durch welchen Wert teilt man, wenn man die Abweichung in Prozent berechnet?", "o": ["Durch den Sollwert", "Durch den Istwert", "Durch die Summe aus Soll und Ist", "Durch die Zahl der Beschäftigten"], "c": 0, "e": "Die Abweichung in Prozent ist Ist minus Soll geteilt durch das Soll mal 100. Bezugsgröße ist also immer der Planwert."}, {"q": "Was zeigt die Rücklaufquote einer Mitarbeiterbefragung?", "o": ["Wie viele der Befragten geantwortet haben", "Wie viele Befragte zufrieden sind", "Wie viele Fragen der Bogen enthält", "Wie viele Befragte später kündigen"], "c": 0, "e": "Die Rücklaufquote ist die Zahl der Antworten geteilt durch die Zahl der Befragten mal 100. Eine hohe Quote macht die Ergebnisse aussagekräftiger."}, {"q": "Wie nennt man ein Kennzahlen-Cockpit mit Ampelfarben auch?", "o": ["Dashboard", "Stellenplan", "Lohnjournal", "Organigramm"], "c": 0, "e": "Ein Kennzahlen-Cockpit oder Dashboard zeigt wichtige Kennzahlen mit Zielwerten und Ampelfarben auf einen Blick."}, {"q": "Was bedeutet die Ampelfarbe Gelb im Kennzahlen-Cockpit?", "o": ["Ziel knapp verfehlt, Wert beobachten", "Ziel erreicht, nichts weiter tun", "Ziel deutlich verfehlt, sofort handeln", "Kein Zielwert vorhanden, nicht prüfen"], "c": 0, "e": "Grün heißt Ziel erreicht, Gelb heißt knapp verfehlt und beobachten, Rot heißt deutlich verfehlt und handeln."}, {"q": "Überstunden und Krankenquote steigen bei Nordstern gleichzeitig. Worauf deutet das am ehesten hin?", "o": ["Auf eine Überlastung der Beschäftigten", "Auf zu viele Auszubildende im Betrieb", "Auf eine zu hohe Rücklaufquote", "Auf zu niedrige Umsätze im Vertrieb"], "c": 0, "e": "Erst der Zusammenhang mehrerer Kennzahlen zeigt die Lage. Viele Überstunden und mehr Krankheit zusammen sprechen für Überlastung."}, {"q": "Nordstern möchte einen neuen Personalfragebogen einsetzen. Was ist dafür nötig?", "o": ["Die Zustimmung des Betriebsrats", "Die Zustimmung der Krankenkasse", "Die Unterschrift der Arbeitsagentur", "Die Genehmigung durch die IHK"], "c": 0, "e": "Personalfragebögen brauchen die Zustimmung des Betriebsrats (§ 94 BetrVG). Deshalb bindet Malte Brandt Petra Holm früh ein."}, {"q": "Welche Pflicht hat der Arbeitgeber gegenüber dem Betriebsrat nach § 80 Abs. 2 BetrVG?", "o": ["Ihn rechtzeitig und umfassend zu unterrichten", "Ihm jede Personalakte vollständig zu kopieren", "Ihm alle Diagnosen der Kranken zu nennen", "Ihn erst nach der Entscheidung zu informieren"], "c": 0, "e": "Der Arbeitgeber muss den Betriebsrat rechtzeitig und umfassend unterrichten (§ 80 Abs. 2 BetrVG). Gesundheitsdaten einzelner Personen gehören nicht in Berichte."}, {"q": "Jede Kennzahl ist ein Bruch. Was steht oben im Bruch?", "o": ["Das, was man zählt, etwa die Krankheitstage", "Die Bezugsgröße, etwa der Personalbestand", "Der Zielwert aus dem Kennzahlen-Cockpit", "Immer die Zahl 100 für die Prozentrechnung"], "c": 0, "e": "Oben steht, was man zählt, unten die Bezugsgröße, durch die man teilt. Erst danach nimmt man mal 100."}, {"q": "Was ist ein Stichtag?", "o": ["Ein festgelegtes Datum für eine Momentaufnahme", "Der Tag, an dem die Gehälter überwiesen werden", "Der letzte Tag der Probezeit im Arbeitsvertrag", "Ein Tag, an dem die Zeiterfassung ausfällt"], "c": 0, "e": "Ein Stichtag ist ein festgelegtes Datum, etwa der 31.12. Der Bestand an diesem Tag ist eine Momentaufnahme."}, {"q": "Wie lautet der zweite Teil des Reims zur Bezugsgröße „Was übers Jahr passiert, wird durch den Durchschnitt dividiert …“?", "o": ["Was am Stichtag steht, mit dem Stichtag geht", "Was am Jahresende steht, wird gar nicht gezählt", "Was im Sommer passiert, wird doppelt gerechnet", "Was im Plan steht, wird immer gestrichen"], "c": 0, "e": "Werte, die über das Jahr anfallen, teilt man durch den durchschnittlichen Bestand. Zustände an einem Stichtag bezieht man auf den Stichtagsbestand."}, {"q": "Was ist ein Prozentpunkt?", "o": ["Der Unterschied zwischen zwei Prozentwerten", "Ein Prozentwert, der auf ganze Zahlen gerundet ist", "Der Anteil einer Zahl an genau 1.000", "Ein Prozentwert, der immer über 100 liegt"], "c": 0, "e": "Steigt eine Quote von 4,78 % auf 5,93 %, beträgt der Unterschied 1,15 Prozentpunkte. Veränderungen von Quoten gibt man deshalb in Prozentpunkten an."}, {"q": "Was bedeutet das Wort Fluktuation?", "o": ["Wechsel", "Wachstum", "Wartezeit", "Wertung"], "c": 0, "e": "Fluktuation bedeutet Wechsel. Die Fluktuationsquote zeigt, wie viele Beschäftigte das Unternehmen von sich aus verlassen."}, {"q": "Warum zählen Renteneintritte in der vereinfachten Fluktuationsquote nicht mit?", "o": ["Sie sagen wenig über die Bindung an das Unternehmen aus", "Sie werden von der Rentenversicherung selbst gezählt", "Sie kommen in Industriebetrieben praktisch nie vor", "Sie gehören rechtlich zu den Kündigungen des Betriebs"], "c": 0, "e": "Die vereinfachte Formel zählt nur Kündigungen durch Beschäftigte. Diese zeigen, ob Menschen gern im Betrieb bleiben. Ein Renteneintritt hat damit wenig zu tun."}, {"q": "Es gibt auch Fluktuationsformeln, die alle Abgänge zählen. Worauf kommt es bei der Wahl der Formel vor allem an?", "o": ["Man verwendet immer dieselbe Formel", "Man wählt die Formel mit dem kleinsten Ergebnis", "Man wechselt die Formel jedes Jahr neu", "Man nimmt die Formel der Krankenkasse"], "c": 0, "e": "Nur mit derselben Formel lassen sich Jahre und Betriebe vergleichen. Im Kurs nutzen wir die vereinfachte Formel mit Eigenkündigungen."}, {"q": "Wer veröffentlicht jedes Jahr Werte zum Krankenstand in Deutschland, die Nordstern zum Vergleich nutzt?", "o": ["Das Statistische Bundesamt", "Die Bundesagentur für Arbeit", "Die Industrie- und Handelskammer", "Das Arbeitsgericht in Hamburg"], "c": 0, "e": "Das Statistische Bundesamt veröffentlicht Werte zum Krankenstand (Destatis, 2026). Auch Krankenkassen geben Berichte heraus, sie rechnen aber oft anders."}, {"q": "Mit wie vielen Soll-Arbeitstagen je Person rechnet Nordstern vereinfacht?", "o": ["220 Tage", "250 Tage", "260 Tage", "365 Tage"], "c": 0, "e": "Nordstern rechnet vereinfacht mit 220 Soll-Arbeitstagen je Person. Wochenenden, Feiertage und Urlaub sind dabei schon abgezogen."}, {"q": "Was sagt eine Personalaufwandsquote von 32,5 % in Worten aus?", "o": ["Von 100 € Umsatz gehen 32,50 € an das Personal", "Von 100 Beschäftigten sind 32,5 in Teilzeit tätig", "Der Gewinn beträgt 32,5 % vom gesamten Umsatz", "Die Gehälter steigen jährlich um 32,5 % an"], "c": 0, "e": "Die Personalaufwandsquote ist Personalaufwand geteilt durch Umsatz mal 100. Bei 32,5 % fließen von jedem Euro Umsatz 32,5 Cent in das Personal."}, {"q": "Durch welchen Wert teilt man den Personalaufwand, um den Personalaufwand je Beschäftigten zu erhalten?", "o": ["Durch den durchschnittlichen Personalbestand", "Durch den Umsatz des Geschäftsjahres", "Durch die Zahl der Soll-Arbeitsstunden", "Durch die Zahl der Auszubildenden"], "c": 0, "e": "Kosten fallen über das ganze Jahr an. Darum teilt man den Personalaufwand durch den durchschnittlichen Bestand, bei Nordstern 2025 durch 236."}, {"q": "Warum sind einige Überstunden in einem Industriebetrieb normal?", "o": ["Sie fangen Auftragsspitzen auf", "Sie sind im Tarifvertrag immer Pflicht", "Sie senken automatisch die Krankenquote", "Sie ersetzen die Weiterbildung"], "c": 0, "e": "Kurzfristige Auftragsspitzen lassen sich gut mit Überstunden auffangen. Bleiben die Überstunden aber dauerhaft hoch, fehlt Personal."}, {"q": "Wie berechnet man die Überstunden je Beschäftigten?", "o": ["Überstunden ÷ Ø Personalbestand", "Überstunden ÷ Soll-Arbeitstage", "Überstunden ÷ Umsatz × 100", "Überstunden × Ø Personalbestand"], "c": 0, "e": "Man teilt die Überstunden durch den durchschnittlichen Bestand. Bei Nordstern 2025 sind das 9.440 ÷ 236 = 40 Stunden je Person."}, {"q": "Womit sollte Nordstern die Ausbildungsquote vor allem vergleichen?", "o": ["Mit dem Vorjahr und dem eigenen Zielwert", "Mit dem Krankenstand der Techniker Krankenkasse", "Mit der Personalaufwandsquote des Vorjahres", "Mit der Fluktuationsquote der Montage"], "c": 0, "e": "Für die Ausbildungsquote liegt im Kursmaterial kein geprüfter Vergleichswert für Deutschland vor. Deshalb vergleicht man mit dem Vorjahr und dem Zielwert."}, {"q": "Wie prüft man, ob die Werte einer Altersstruktur vollständig sind?", "o": ["Die Gruppen ergeben zusammen den Gesamtbestand", "Jede Gruppe ist genau gleich groß", "Die jüngste Gruppe ist immer die größte", "Die Anteile ergeben zusammen 50 %"], "c": 0, "e": "Die Summe aller Altersgruppen muss den Bestand am Stichtag ergeben, bei Nordstern 48 + 112 + 80 = 240. Die Anteile ergeben zusammen 100 %."}, {"q": "Im Merkbild rollt bei Nordstern eine Rentenwelle auf den Strand zu. Was bedeutet es, jetzt Deiche zu bauen?", "o": ["Ausbilden und Wissen weitergeben", "Ältere Beschäftigte sofort entlassen", "Stellenanzeigen ganz einstellen", "Den Renteneintritt gesetzlich verschieben"], "c": 0, "e": "Die Gruppe ab 50 sieht man lange vorher kommen. Wer früh ausbildet und Wissen über Tandems weitergibt, verliert beim Renteneintritt kein Wissen."}, {"q": "Was ist das betriebliche Eingliederungsmanagement?", "o": ["Ein Verfahren zum Erhalt der Arbeitsfähigkeit nach längerer Krankheit", "Ein Verfahren zur Einarbeitung neuer Auszubildender im Betrieb", "Ein Programm zur Eingliederung neuer Abteilungen nach einem Kauf", "Eine Prüfung der Bewerbungen durch den Betriebsrat vor der Einstellung"], "c": 0, "e": "Arbeitgeber und Beschäftigte klären gemeinsam, wie die Arbeitsfähigkeit nach längerer Arbeitsunfähigkeit erhalten werden kann (§ 167 Abs. 2 SGB IX)."}, {"q": "Wie ergänzen sich Kennzahl und Austrittsgespräch?", "o": ["Die Kennzahl zeigt, dass etwas nicht stimmt, das Gespräch zeigt oft warum", "Das Gespräch ersetzt die Kennzahl, weil es genauer rechnet", "Die Kennzahl ist nur gültig, wenn jedes Gespräch protokolliert ist", "Das Gespräch zeigt den Wert, die Kennzahl zeigt die Gefühle"], "c": 0, "e": "Kennzahlen zeigen Auffälligkeiten. Die Ursachen erfährt man oft erst aus Gesprächen und Befragungen."}, {"q": "Wann weiß Nordstern, ob eine Maßnahme gegen die Fluktuation effektiv war?", "o": ["Wenn die Kennzahl danach erneut gemessen wurde", "Sobald die Maßnahme beschlossen worden ist", "Wenn der Betriebsrat der Maßnahme zustimmt", "Sobald die Kosten der Maßnahme verbucht sind"], "c": 0, "e": "Nach jeder Maßnahme schließt sich der Regelkreis. Erst die erneute Messung im nächsten Jahr zeigt, ob die Maßnahme gewirkt hat."}, {"q": "Wie berechnet man bei einem Höchstwert als Ziel den relativen Abstand des Istwerts zum Zielwert für die Ampel?", "o": ["(Istwert − Zielwert) ÷ Zielwert × 100", "(Zielwert − Istwert) ÷ Istwert × 100", "Istwert ÷ Zielwert ohne mal 100", "Istwert − Zielwert ohne weitere Rechnung"], "c": 0, "e": "Man teilt den Abstand durch den Zielwert und nimmt mal 100. Bei der Fluktuation sind das (5,93 − 5,0) ÷ 5,0 × 100 = 18,6 %."}, {"q": "Petra Holm erhält von der Personalabteilung jedes Quartal eine Übersicht der Überstunden je Abteilung. Welche Funktion des Personalcontrollings zeigt sich hier?", "o": ["Informationsfunktion", "Steuerungsfunktion", "Planungsfunktion", "Frühwarnfunktion"], "c": 0, "e": "Daten werden gesammelt und verständlich aufbereitet weitergegeben. Das ist die Informationsfunktion."}, {"q": "Im Januar 2027 vergleicht Malte Brandt die tatsächlichen Weiterbildungstage 2026 mit dem Ziel von 3,0 Tagen je Person. Welche Funktion ist das?", "o": ["Kontrollfunktion", "Planungsfunktion", "Steuerungsfunktion", "Frühwarnfunktion"], "c": 0, "e": "Nach Ablauf eines Zeitraums werden Ist und Soll verglichen. Das ist die Kontrollfunktion."}, {"q": "Für die Spätschicht in der Montage führt Nordstern einen Schichtplan mit Mitsprache ein, weil viele dort kündigen. Welche Funktion zeigt sich?", "o": ["Steuerungsfunktion", "Kontrollfunktion", "Frühwarnfunktion", "Informationsfunktion"], "c": 0, "e": "Eine Maßnahme wird umgesetzt, um ein gefährdetes Ziel zu erreichen. Das ist Steuerung."}, {"q": "Malte Brandt prüft ein Jahr nach Einführung des neuen Schichtmodells, ob die Zufriedenheit mit der Schichtplanung gestiegen ist. Welche Ebene ist das?", "o": ["Effektivitätscontrolling", "Kostencontrolling", "Effizienzcontrolling", "Budgetkontrolle der Personalabteilung"], "c": 0, "e": "Es wird geprüft, ob eine Maßnahme ihr Ziel erreicht hat. Das ist die Frage nach der Wirksamkeit, also Effektivität."}, {"q": "Die Schulung in der Lackiererei hatte ein Budget von 25.000 € und kostete 24.000 €. Wie hoch ist die Abweichung?", "o": ["− 1.000 € und − 4,00 %", "+ 1.000 € und + 4,17 %", "− 1.000 € und − 4,17 %", "+ 1.000 € und + 4,00 %"], "c": 0, "e": "Ist minus Soll ergibt 24.000 − 25.000 = − 1.000 €. In Prozent − 1.000 ÷ 25.000 × 100 = − 4,00 %. Bezugsgröße ist das Soll."}, {"q": "Geplant waren 2025 bei Nordstern 10 Eigenkündigungen, tatsächlich waren es 14. Wie hoch ist die Abweichung in Prozent?", "o": ["+ 40,00 %", "+ 28,57 %", "+ 4,00 %", "+ 140,00 %"], "c": 0, "e": "Abweichung 14 − 10 = 4. In Prozent 4 ÷ 10 × 100 = 40,00 %. Wer durch das Ist teilt, erhält fälschlich 28,57 %."}, {"q": "Der Personalaufwand lag 2025 um 0,4 Mio. € über dem Plan. Davon entfielen 0,25 Mio. € auf mehr Beschäftigte. Welcher Anteil der Abweichung ist das?", "o": ["62,5 %", "37,5 %", "25,0 %", "1,6 %"], "c": 0, "e": "0,25 ÷ 0,4 × 100 = 62,5 %. Der größte Teil der Abweichung kommt also daher, dass im Durchschnitt 236 statt 232 Personen beschäftigt waren."}, {"q": "In der Qualitätssicherung arbeiten 10 Personen, 3 haben an der Befragung teilgenommen. Die Abteilungsleitung möchte das Ergebnis ihrer Abteilung sehen. Was ist richtig?", "o": ["Das Ergebnis wird nicht gesondert gezeigt, weil die Gruppe zu klein ist", "Das Ergebnis wird mit den Namen der drei Personen gezeigt", "Das Ergebnis wird gezeigt, weil die Rücklaufquote 30 % beträgt", "Das Ergebnis wird gezeigt, wenn die Leitung es schriftlich verlangt"], "c": 0, "e": "Bei nur 3 Antworten könnte man einzelne Personen erkennen. Viele Betriebe werten deshalb erst ab etwa fünf Personen aus. Die Werte fließen dann nur in das Gesamtergebnis ein."}, {"q": "Ein Monteur war innerhalb der letzten zwölf Monate sieben Wochen am Stück arbeitsunfähig. Was muss Nordstern tun?", "o": ["Ihm ein betriebliches Eingliederungsmanagement anbieten", "Ihm sofort eine Kündigung wegen Krankheit aussprechen", "Seinen Namen in den Krankenbericht der Montage aufnehmen", "Ihm den Urlaub für das laufende Jahr anteilig kürzen"], "c": 0, "e": "Bei mehr als sechs Wochen Arbeitsunfähigkeit innerhalb eines Jahres muss der Arbeitgeber ein betriebliches Eingliederungsmanagement anbieten (§ 167 Abs. 2 SGB IX)."}, {"q": "Die Summe der zwölf Monatsbestände 2025 beträgt bei Nordstern 2.832 Beschäftigte. Wie hoch ist der durchschnittliche Personalbestand?", "o": ["236", "240", "232", "283"], "c": 0, "e": "2.832 ÷ 12 = 236. Die genauere Methode mit Monatswerten bestätigt hier den Wert aus Anfangs- und Endbestand."}, {"q": "Nordstern rechnet für 2026 mit 240 Beschäftigten am Jahresanfang und 248 am Jahresende. Wie hoch ist der durchschnittliche Personalbestand 2026?", "o": ["244", "248", "240", "488"], "c": 0, "e": "(240 + 248) ÷ 2 = 244. Mit diesem Wert würde Nordstern 2026 Fluktuation, Krankenquote und Überstundenquote berechnen."}, {"q": "Von den 240 Beschäftigten am 31.12.2025 sind 168 Männer. Wie hoch ist der Männeranteil?", "o": ["70,0 %", "71,2 %", "30,0 %", "68,0 %"], "c": 0, "e": "168 ÷ 240 × 100 = 70,0 %. Zusammen mit dem Frauenanteil von 30,0 % ergibt das 100 %. Das ist eine Strukturstatistik."}, {"q": "In der Montage arbeiten am 31.12.2025 genau 100 der 240 Beschäftigten. Wie hoch ist der Anteil der Montage an der Belegschaft?", "o": ["41,67 %", "42,37 %", "100,00 %", "58,33 %"], "c": 0, "e": "100 ÷ 240 × 100 = 41,67 %. Weil der Anteil am Stichtag gefragt ist, nimmt man den Stichtagsbestand 240."}, {"q": "Von den 10 Auszubildenden bei Nordstern lernen 4 den Beruf Industriekaufmann oder Industriekauffrau. Wie hoch ist ihr Anteil an allen Auszubildenden?", "o": ["40 %", "4 %", "1,67 %", "25 %"], "c": 0, "e": "4 ÷ 10 × 100 = 40 %. Die übrigen 6 lernen Industriemechanik oder Lagerlogistik."}, {"q": "2025 schieden bei Nordstern 20 Personen aus, der Bestand stieg von 232 auf 240. Wie viele Zugänge gab es?", "o": ["28", "8", "12", "20"], "c": 0, "e": "Endbestand = Anfangsbestand − Abgänge + Zugänge. 240 = 232 − 20 + Zugänge, also 28 Zugänge. Das zeigt die Bewegungsstatistik."}, {"q": "Von den 20 Abgängen 2025 waren 14 Eigenkündigungen, 4 Renteneintritte und 2 ausgelaufene Befristungen. Wie hoch ist die vereinfachte Fluktuationsquote?", "o": ["5,93 %", "8,47 %", "8,33 %", "7,63 %"], "c": 0, "e": "Es zählen nur die 14 Eigenkündigungen. 14 ÷ 236 × 100 = 5,93 %. Wer alle 20 Abgänge zählt, kommt auf 8,47 % und nutzt eine andere Formel."}, {"q": "Das Arbeitsverhältnis von Thomas Albers endet am 31.05.2027 durch eine Kündigung des Arbeitgebers. Wie wirkt sich das auf die vereinfachte Fluktuationsquote 2027 aus?", "o": ["Der Abgang zählt nicht mit", "Der Abgang zählt doppelt", "Der Abgang zählt nur zur Hälfte", "Der Abgang zählt voll mit"], "c": 0, "e": "Die vereinfachte Formel zählt nur Kündigungen durch Beschäftigte. Eine Kündigung durch den Arbeitgeber gehört nicht dazu."}, {"q": "Die Nordstern Service GmbH befragt ihre 18 Beschäftigten, 12 geben den Bogen ab. Wie hoch ist die Rücklaufquote?", "o": ["66,67 %", "150,00 %", "33,33 %", "60,00 %"], "c": 0, "e": "12 ÷ 18 × 100 = 66,67 %. Zwei Drittel der Befragten haben geantwortet."}, {"q": "Wie viele Krankheitstage dürfte Nordstern bei 51.920 Soll-Arbeitstagen höchstens haben, damit die Krankenquote den Zielwert von 5,5 % nicht überschreitet?", "o": ["2.855", "3.115", "2.990", "2.596"], "c": 0, "e": "5,5 % von 51.920 sind 2.855,6. Mit 2.855 Tagen liegt die Quote knapp unter 5,5 %. Gegenüber 3.115 Tagen wären das 260 Krankheitstage weniger."}, {"q": "Wie viele Krankheitstage entfielen 2024 bei 2.900 Krankheitstagen und durchschnittlich 230 Beschäftigten auf jede Person?", "o": ["12,6 Tage", "13,2 Tage", "12,1 Tage", "5,7 Tage"], "c": 0, "e": "2.900 ÷ 230 = 12,6 Tage je Person. 2025 waren es 13,2 Tage, also 0,6 Tage mehr."}, {"q": "Im Betriebsrat heißt es, die Fluktuation sei 2025 um rund 24 % gestiegen. Die Geschäftsführung spricht von 1,15 Prozentpunkten. Wer hat recht?", "o": ["Die Angaben stimmen, sie nutzen nur andere Maßstäbe", "Nur der Betriebsrat, weil Prozentpunkte keine Einheit sind", "Nur die Geschäftsführung, weil Prozent hier falsch gerechnet ist", "Keine Seite, weil die Quote 2025 gesunken ist"], "c": 0, "e": "Von 4,78 % auf 5,93 % sind es 1,15 Prozentpunkte. Bezogen auf den Ausgangswert sind das 1,15 ÷ 4,78 × 100 = 24,06 %. In Berichten nennt man bei Quoten die Prozentpunkte."}, {"q": "Im Vertrieb mit durchschnittlich 15 Beschäftigten hat 2025 eine Person selbst gekündigt. Wie hoch ist die Fluktuationsquote im Vertrieb?", "o": ["6,67 %", "0,42 %", "15,00 %", "1,50 %"], "c": 0, "e": "1 ÷ 15 × 100 = 6,67 %. Bei so kleinen Gruppen verändert schon eine einzige Kündigung die Quote stark, daher vorsichtig deuten."}, {"q": "Im Vertrieb mit durchschnittlich 15 Beschäftigten gab es 2025 genau 180 Krankheitstage bei 220 Soll-Arbeitstagen je Person. Wie hoch ist die Krankenquote?", "o": ["5,45 %", "12,00 %", "3,29 %", "8,18 %"], "c": 0, "e": "Soll-Arbeitstage 15 × 220 = 3.300. Krankenquote 180 ÷ 3.300 × 100 = 5,45 %. Das liegt unter dem Zielwert von 5,5 %."}, {"q": "Im Lager arbeiten im November 25 Personen an je 20 Soll-Arbeitstagen. Es gab 40 Krankheitstage. Wie hoch ist die Krankenquote im November?", "o": ["8,0 %", "1,6 %", "5,0 %", "6,25 %"], "c": 0, "e": "Soll-Arbeitstage 25 × 20 = 500. 40 ÷ 500 × 100 = 8,0 %. Steigt ein solcher Wert mehrere Monate, ist das ein Frühwarnsignal."}, {"q": "Nordstern liegt 2025 bei 13,2 Krankheitstagen je Person, das Statistische Bundesamt nennt 14,6 Arbeitstage. Wie groß ist der Unterschied?", "o": ["1,4 Tage weniger bei Nordstern", "1,4 Tage mehr bei Nordstern", "0,1 Tage weniger bei Nordstern", "14,6 Tage weniger bei Nordstern"], "c": 0, "e": "14,6 − 13,2 = 1,4 Tage. Nordstern liegt bei den Tagen leicht unter dem Bundeswert, die Krankenquote ist mit 6,00 % aber etwa gleich hoch."}, {"q": "Nordstern hatte 2025 einen Umsatz von 48,0 Mio. € bei durchschnittlich 236 Beschäftigten. Wie hoch ist der Umsatz je Beschäftigten?", "o": ["203.389,83 €", "200.000,00 €", "66.101,69 €", "49.166,67 €"], "c": 0, "e": "48.000.000 ÷ 236 = 203.389,83 €. Diese Kennzahl zeigt die Produktivität. Der Personalaufwand je Beschäftigten beträgt dagegen 66.101,69 €."}, {"q": "Der Umsatz je Beschäftigten lag 2024 bei 195.652,17 € und 2025 bei 203.389,83 €. Wie stark ist er gestiegen?", "o": ["Um 3,95 %", "Um 2,73 %", "Um 6,67 %", "Um 3,80 %"], "c": 0, "e": "(203.389,83 − 195.652,17) ÷ 195.652,17 × 100 = 3,95 %. Der Personalaufwand je Beschäftigten stieg nur um 2,73 %, die Produktivität also stärker."}, {"q": "Um wie viel Euro liegt der Personalaufwand je Beschäftigten bei Nordstern 2025 über dem Wert der Nordstern Service GmbH mit 51.111,11 €?", "o": ["14.990,58 €", "15.009,42 €", "14.680,00 €", "117.212,80 €"], "c": 0, "e": "66.101,69 − 51.111,11 = 14.990,58 €. Die Service GmbH hat trotzdem die höhere Personalaufwandsquote, weil ihr Umsatz vor allem aus Arbeitszeit besteht."}, {"q": "Die Nordstern Service GmbH erzielte 2025 mit durchschnittlich 18 Beschäftigten einen Umsatz von 2,3 Mio. €. Wie hoch ist der Umsatz je Beschäftigten?", "o": ["127.777,78 €", "51.111,11 €", "203.389,83 €", "12.777,78 €"], "c": 0, "e": "2.300.000 ÷ 18 = 127.777,78 €. Im Stammwerk sind es 203.389,83 €. Werkstatt und Verleih erzielen weniger Umsatz je Kopf, weil der Umsatz vor allem aus Arbeitszeit besteht."}, {"q": "Wie viele Krankheitstage je Person entsprechen bei 220 Soll-Arbeitstagen genau dem Zielwert der Krankenquote von 5,5 %?", "o": ["12,1 Tage", "13,2 Tage", "5,5 Tage", "20,1 Tage"], "c": 0, "e": "220 × 0,055 = 12,1 Tage. Nordstern lag 2025 mit 13,2 Tagen je Person darüber, deshalb verfehlt die Krankenquote das Ziel."}, {"q": "Nordstern hatte 2024 einen Personalaufwand von 14,8 Mio. € bei durchschnittlich 230 Beschäftigten. Wie hoch war der Personalaufwand je Beschäftigten?", "o": ["64.347,83 €", "62.711,86 €", "66.101,69 €", "6.434,78 €"], "c": 0, "e": "14.800.000 ÷ 230 = 64.347,83 €. 2025 waren es 66.101,69 €, also ein Anstieg um 2,73 %."}, {"q": "Wie viele Überstunden dürfte Nordstern bei 363.440 Soll-Arbeitsstunden höchstens haben, um die Zielvorgabe von 2,5 % einzuhalten?", "o": ["9.086 Stunden", "9.440 Stunden", "9.360 Stunden", "8.500 Stunden"], "c": 0, "e": "2,5 % von 363.440 sind 363.440 × 0,025 = 9.086 Stunden. 2025 waren es 9.440, also 354 Stunden zu viel."}, {"q": "Jonas Petersen aus der Montage hat 2025 insgesamt 52 Überstunden geleistet. Wie liegt er im Vergleich zum Durchschnitt von Nordstern?", "o": ["12 Stunden darüber, also 30 % mehr", "12 Stunden darunter, also 30 % weniger", "12 Stunden darüber, also 23 % mehr", "Genau im Durchschnitt des Betriebs"], "c": 0, "e": "Der Durchschnitt beträgt 9.440 ÷ 236 = 40 Stunden. 52 − 40 = 12 Stunden, 12 ÷ 40 × 100 = 30 % mehr."}, {"q": "Die Weiterbildungstage je Beschäftigten stiegen von 2,7 auf 3,0. Um wie viel Prozent ist das?", "o": ["11,11 %", "0,30 %", "10,00 %", "30,00 %"], "c": 0, "e": "(3,0 − 2,7) ÷ 2,7 × 100 = 11,11 %. Bezugsgröße ist der Ausgangswert 2,7."}, {"q": "In der Verwaltung arbeiten am 31.12.2025 genau 40 der 240 Beschäftigten. Wie hoch ist ihr Anteil?", "o": ["16,67 %", "16,95 %", "40,00 %", "6,00 %"], "c": 0, "e": "40 ÷ 240 × 100 = 16,67 %. Für einen Anteil am Stichtag nimmt man den Stichtagsbestand."}, {"q": "Angenommen, die Krankenquote läge bei 6,10 % und der Zielwert bei höchstens 5,5 %. Welche Ampelfarbe ergäbe sich?", "o": ["Rot, weil der Abstand 10,91 % beträgt", "Gelb, weil der Abstand 0,60 % beträgt", "Gelb, weil der Abstand 9,84 % beträgt", "Grün, weil 6,10 % unter 10 % liegt"], "c": 0, "e": "(6,10 − 5,5) ÷ 5,5 × 100 = 10,91 %. Das ist mehr als 10 % schlechter als das Ziel, also Rot."}, {"q": "Ab welcher Krankenquote würde die Ampel bei Nordstern bei einem Zielwert von höchstens 5,5 % auf Rot springen?", "o": ["Bei mehr als 6,05 %", "Bei mehr als 5,5 %", "Bei mehr als 6,5 %", "Bei mehr als 15,5 %"], "c": 0, "e": "Gelb reicht bis 10 % schlechter als der Zielwert. 5,5 × 1,10 = 6,05 %. Darüber ist die Ampel Rot. Mit 6,00 % liegt Nordstern knapp darunter."}, {"q": "Angenommen, die Weiterbildungstage lägen bei 2,8 je Person und der Zielwert bei mindestens 3,0. Welche Ampelfarbe ergäbe sich?", "o": ["Gelb, weil der Wert 6,67 % unter dem Ziel liegt", "Rot, weil der Wert unter dem Ziel liegt", "Grün, weil der Wert über 2,7 liegt", "Gelb, weil der Wert 0,2 % unter dem Ziel liegt"], "c": 0, "e": "(3,0 − 2,8) ÷ 3,0 × 100 = 6,67 %. Das ist bis 10 % schlechter als das Ziel, also Gelb."}, {"q": "Wie hätte die Ampel 2024 bei der Krankenquote von 5,73 % und dem Zielwert von höchstens 5,5 % ausgesehen?", "o": ["Gelb, Abstand rund 4,18 %", "Rot, Abstand rund 4,18 %", "Grün, Abstand rund 0,23 %", "Rot, Abstand rund 23 %"], "c": 0, "e": "(5,73 − 5,5) ÷ 5,5 × 100 = 4,18 %. Das ist schlechter als das Ziel, aber nicht mehr als 10 %, also Gelb."}, {"q": "Die Nordstern Service GmbH hat eine Personalaufwandsquote von 40,0 %. Welche Ampel ergäbe sich mit dem Zielwert des Stammwerks von höchstens 33,0 %?", "o": ["Rot, Abstand rund 21,2 %", "Gelb, Abstand rund 7,0 %", "Gelb, Abstand rund 9,1 %", "Grün, Abstand rund 17,5 %"], "c": 0, "e": "(40,0 − 33,0) ÷ 33,0 × 100 = 21,2 %, also Rot. Der Zielwert des Industriebetriebs passt aber nicht gut zu einer Werkstatt, deshalb braucht die Tochter eigene Zielwerte."}, {"q": "Dr. Katrin Lorenz sagt, der Personalaufwand sei von 14,8 auf 15,6 Mio. € gestiegen und das sei schlecht. Welche Antwort von Malte Brandt ist fachlich richtig?", "o": ["Die Personalaufwandsquote ist gesunken, weil der Umsatz schneller wuchs", "Der Personalaufwand ist gesunken, weil weniger Personen beschäftigt waren", "Die Personalaufwandsquote ist gestiegen, das Ziel ist also verfehlt", "Der Personalaufwand darf laut Gesetz nur um 5 % im Jahr steigen"], "c": 0, "e": "Der Personalaufwand stieg um 5,41 %, der Umsatz um 6,67 %. Deshalb sank die Quote von 32,89 % auf 32,50 % und liegt unter dem Zielwert von 33,0 %."}], "lernen": [{"t": "Personalcontrolling", "x": "Planung, Steuerung und Kontrolle der Personalarbeit mit Informationen und Kennzahlen."}, {"t": "Kennzahl", "x": "Zahl, die einen Sachverhalt kurz und vergleichbar ausdrückt, zum Beispiel die Krankenquote."}, {"t": "Frühwarnfunktion", "x": "Aufgabe des Personalcontrollings, Risiken zu erkennen, bevor sie zu Problemen werden."}, {"t": "Strategisches Personalcontrolling", "x": "Langfristiger Blick über mehrere Jahre, etwa auf Altersstruktur und Fachkräftebedarf."}, {"t": "Operatives Personalcontrolling", "x": "Kurzfristiger Blick vom Monat bis zum Jahr, etwa auf Budget und Überstunden."}, {"t": "Qualitatives Personalcontrolling", "x": "Erfasst Größen, die man nicht direkt zählen kann, etwa Zufriedenheit und Führungsqualität."}, {"t": "Effizienz", "x": "Wirtschaftlichkeit, also ein gutes Verhältnis von Aufwand und Ergebnis. Die Dinge richtig tun."}, {"t": "Effektivität", "x": "Wirksamkeit, also der Beitrag einer Maßnahme zum Ziel. Die richtigen Dinge tun."}, {"t": "Soll-Ist-Vergleich", "x": "Gegenüberstellung von geplanten und tatsächlichen Werten mit Berechnung der Abweichung."}, {"t": "Abweichungsanalyse", "x": "Suche nach den Ursachen einer Abweichung als Grundlage für Maßnahmen."}, {"t": "Benchmarking", "x": "Vergleich eigener Werte mit einem Maßstab, etwa Vorjahr, anderer Betrieb oder Durchschnitt für Deutschland."}, {"t": "Durchschnittlicher Personalbestand", "x": "Mittlere Zahl der Beschäftigten im Jahr, etwa (Anfangsbestand + Endbestand) ÷ 2. Bei Nordstern 2025 genau 236."}, {"t": "Stichtag", "x": "Festes Datum für eine Momentaufnahme, bei Nordstern der 31.12.2025 mit 240 Beschäftigten."}, {"t": "Fluktuationsquote", "x": "Kündigungen durch Beschäftigte geteilt durch den durchschnittlichen Personalbestand mal 100."}, {"t": "Krankenquote", "x": "Krankheitstage geteilt durch Soll-Arbeitstage mal 100."}, {"t": "Prozentpunkte", "x": "Abstand zwischen zwei Prozentwerten. Von 4,78 % auf 5,93 % sind es 1,15 Prozentpunkte."}, {"t": "Kennzahlen-Cockpit", "x": "Übersicht wichtiger Kennzahlen mit Vorjahr, Zielwert und Ampel."}, {"t": "Absolute und relative Kennzahl", "x": "Absolut ist eine einfache Zahl wie der Personalbestand. Relativ ist ein Verhältnis zweier Größen wie die Teilzeitquote."}, {"t": "Eigenkündigungsquote", "x": "Kündigungen durch Beschäftigte geteilt durch den Personalbestand mal 100. Sie entspricht der vereinfachten Fluktuationsquote im Kurs."}, {"t": "Personalkostenquote", "x": "Personalkosten geteilt durch Gesamtkosten mal 100. Im Kurs wird meist die Personalaufwandsquote mit dem Umsatz verwendet."}, {"t": "Branchenprimus", "x": "Das beste Unternehmen einer Branche. Sein Wert kann beim Benchmarking als Sollwert dienen."}, {"t": "Personalcontrolling", "x": "Personalcontrolling plant, steuert und kontrolliert die Personalarbeit mit Informationen und Kennzahlen. Es unterstützt Entscheidungen und verbindet Personalziele mit Unternehmenszielen (Beiderwieden & Stickdorn, 2026)."}, {"t": "Ziele ergänzen sich", "x": "Wirtschaftliche und soziale Ziele gehören zusammen. Gesunde und zufriedene Beschäftigte senken Fehlzeiten und Fluktuation und damit auch die Kosten."}, {"t": "Personalstatistik", "x": "Die Personalstatistik ordnet Personaldaten nach Bestand, Bewegung und Struktur. Sie ist die Grundlage für alle Kennzahlen (Beiderwieden & Stickdorn, 2026)."}, {"t": "Ampel im Cockpit", "x": "Grün heißt Ziel erreicht. Gelb heißt knapp verfehlt, beobachten. Rot heißt deutlich verfehlt, handeln."}, {"t": "Erst Fakten, dann Deutung", "x": "Zahlen beschreiben, Ursachen als Vermutung kennzeichnen, dann begründet empfehlen. Wer Deutungen als Tatsachen ausgibt, verliert an Glaubwürdigkeit."}, {"t": "Betriebliches Eingliederungsmanagement", "x": "Verfahren, mit dem Arbeitgeber und Beschäftigte nach längerer Arbeitsunfähigkeit gemeinsam klären, wie die Arbeitsfähigkeit erhalten werden kann (§ 167 Abs. 2 SGB IX)."}, {"t": "Kennzahlen hängen zusammen", "x": "Personalmangel führt zu Überstunden, Überstunden zu Krankheit, Überlastung zu Kündigungen. Darum betrachtet man Kennzahlen im System."}], "sortier": [{"titel": "Langfristig oder kurzfristig steuern?", "auftrag": "Ordne jede Aufgabe dem strategischen oder dem operativen Personalcontrolling zu.", "kategorien": [{"id": "a", "name": "Strategisch"}, {"id": "b", "name": "Operativ"}], "items": [{"text": "Altersstruktur bis zum Jahr 2035 auswerten", "kat": "a", "expl": "Der Blick geht viele Jahre nach vorn. Das ist strategisches Controlling."}, {"text": "Fachkräftebedarf der Montage bis 2032 abschätzen", "kat": "a", "expl": "Langfristige Fragen über mehrere Jahre gehören zum strategischen Controlling."}, {"text": "Führungskultur in den nächsten Jahren entwickeln", "kat": "a", "expl": "Kultur ändert sich nur langsam. Das ist eine strategische Aufgabe."}, {"text": "Nachfolge für die Renteneintritte der nächsten 15 Jahre", "kat": "a", "expl": "Ein Drittel ist 50 oder älter. Die Planung reicht weit in die Zukunft."}, {"text": "Ausbildungsplätze für die nächsten fünf Jahre festlegen", "kat": "a", "expl": "Ausbildung sichert die Fachkräfte von morgen. Das ist langfristig und strategisch."}, {"text": "Personalstrategie für die kommenden Jahre ausrichten", "kat": "a", "expl": "Die Strategie ist der Kern des strategischen Controllings."}, {"text": "Personalkostenbudget für Dezember prüfen", "kat": "b", "expl": "Ein Monat ist ein kurzer Zeitraum. Das ist operatives Controlling."}, {"text": "Überstunden je Abteilung im Monat auswerten", "kat": "b", "expl": "Monatswerte steuern das Tagesgeschäft. Das ist operativ."}, {"text": "Zufriedenheit im Quartal messen", "kat": "b", "expl": "Ein Quartal liegt im kurzen Zeitraum von Monat bis Jahr. Das ist operativ."}, {"text": "Krankenquote im Lager Monat für Monat verfolgen", "kat": "b", "expl": "Kurzfristige Werte im laufenden Jahr gehören zum operativen Controlling."}, {"text": "Ist-Personalaufwand 2025 mit dem Budget vergleichen", "kat": "b", "expl": "Der Soll-Ist-Vergleich eines Jahres ist operativ."}, {"text": "Weiterbildungstage 2025 mit dem Zielwert vergleichen", "kat": "b", "expl": "Hier wird ein Jahreswert kontrolliert. Das ist operatives Controlling."}]}, {"titel": "Kennzahlen richtig einsortieren", "auftrag": "Ordne jede Kennzahl von Nordstern ihrer Gruppe zu.", "kategorien": [{"id": "a", "name": "Strukturkennzahl"}, {"id": "b", "name": "Bewegungskennzahl"}, {"id": "c", "name": "Kostenkennzahl"}], "items": [{"text": "Ausbildungsquote 10 ÷ 240 × 100 = 4,17 %", "kat": "a", "expl": "Sie zeigt den Anteil der Azubis an der Belegschaft am Stichtag. Das ist die Zusammensetzung."}, {"text": "Frauenquote 72 ÷ 240 × 100 = 30,0 %", "kat": "a", "expl": "Die Frauenquote beschreibt die Zusammensetzung der Belegschaft."}, {"text": "Teilzeitquote 30 ÷ 240 × 100 = 12,5 %", "kat": "a", "expl": "Der Anteil der Teilzeitkräfte ist eine Strukturkennzahl."}, {"text": "Ein Drittel der Belegschaft ist 50 Jahre oder älter", "kat": "a", "expl": "Die Altersstruktur gliedert den Bestand nach dem Merkmal Alter."}, {"text": "Anteil der Führungskräfte an allen Beschäftigten", "kat": "a", "expl": "Die Führungskräftequote beschreibt die Struktur der Belegschaft."}, {"text": "Fluktuationsquote 14 ÷ 236 × 100 = 5,93 %", "kat": "b", "expl": "Sie misst Abgänge durch Eigenkündigung. Das ist eine Bewegung."}, {"text": "Einstellungsquote bei 1 Einstellung auf 64 Bewerbungen", "kat": "b", "expl": "Einstellungen sind Zugänge. Die Einstellungsquote ist eine Bewegungskennzahl."}, {"text": "Zugänge und Abgänge in einem Zeitraum erfassen", "kat": "b", "expl": "Genau das beschreibt eine Bewegungskennzahl."}, {"text": "Fluktuation 2024 mit 11 Eigenkündigungen bei 230 Beschäftigten", "kat": "b", "expl": "11 ÷ 230 × 100 = 4,78 %. Auch hier zählen Abgänge."}, {"text": "14 Eigenkündigungen im Jahr 2025", "kat": "b", "expl": "Eigenkündigungen sind Abgänge in einem Zeitraum."}, {"text": "Personalaufwandsquote 15,6 ÷ 48,0 × 100 = 32,5 %", "kat": "c", "expl": "Sie setzt den Personalaufwand ins Verhältnis zum Umsatz. Das ist eine Kostenkennzahl."}, {"text": "Personalaufwand je Beschäftigten 66.101,69 €", "kat": "c", "expl": "15.600.000 € ÷ 236 zeigt die Kosten je Kopf."}, {"text": "Personalkosten ÷ Gesamtkosten × 100", "kat": "c", "expl": "Das ist die Personalkostenquote, eine typische Kostenkennzahl."}, {"text": "Personalaufwand stieg von 14,8 auf 15,6 Mio. €", "kat": "c", "expl": "Hier geht es um die Entwicklung der Kosten."}, {"text": "Personalaufwandsquote der Service GmbH 40,0 %", "kat": "c", "expl": "0,92 ÷ 2,3 × 100 = 40,0 %. Auch das ist eine Kostenkennzahl."}]}]}, {"nr": 10, "title": "Gesamtwiederholung und Klausur", "date": "04.12.2026", "quiz": [{"q": "Wie lange darf die Probezeit in einem Berufsausbildungsverhältnis höchstens dauern?", "o": ["3 Monate", "4 Monate", "12 Monate", "6 Monate"], "c": 1, "e": "Die Probezeit beträgt mindestens einen und höchstens vier Monate (§ 20 BBiG). Sechs Monate sind die Grenze im normalen Arbeitsvertrag."}, {"q": "Mia Schulz ist 17 Jahre alt. Wie viele Stunden darf sie nach dem Jugendarbeitsschutzgesetz höchstens pro Woche arbeiten?", "o": ["40 Stunden", "48 Stunden", "45 Stunden", "35 Stunden"], "c": 0, "e": "Jugendliche dürfen höchstens 8 Stunden täglich und 40 Stunden wöchentlich arbeiten (§ 8 JArbSchG). Die 35 Stunden bei Nordstern stammen aus dem Tarifvertrag."}, {"q": "Was gilt, wenn Leon Becker nach bestandener Abschlussprüfung ohne besondere Vereinbarung einfach weiterarbeitet?", "o": ["Es entsteht ein auf ein Jahr befristetes Arbeitsverhältnis", "Er muss zuerst einen neuen Ausbildungsvertrag schließen", "Er bleibt bis zum Jahresende Auszubildender", "Es entsteht ein unbefristetes Arbeitsverhältnis"], "c": 3, "e": "Wer nach der Ausbildung ohne ausdrückliche Vereinbarung weiterbeschäftigt wird, steht in einem unbefristeten Arbeitsverhältnis (§ 24 BBiG)."}, {"q": "Wie viele Stunden Freizeit muss Mia zwischen zwei Arbeitstagen mindestens haben?", "o": ["8 Stunden", "10 Stunden", "12 Stunden", "11 Stunden"], "c": 2, "e": "Jugendliche brauchen nach Ende der täglichen Arbeitszeit mindestens 12 Stunden ununterbrochene Freizeit (§ 13 JArbSchG). Für Erwachsene gelten 11 Stunden Ruhezeit (§ 5 ArbZG)."}, {"q": "Wie hoch ist die Mindestausbildungsvergütung im ersten Ausbildungsjahr für Ausbildungen, die 2026 beginnen?", "o": ["724 €", "1.150 €", "682 €", "764 €"], "c": 0, "e": "Für einen Beginn im Jahr 2026 gilt im ersten Jahr mindestens 724 € (BBiMindVergFBek 2026). 682 € galten für 2025, 764 € gelten für 2027, 1.150 € zahlt Nordstern."}, {"q": "Wie berechnet man den Nettopersonalbedarf?", "o": ["Ist-Bestand minus sichere Abgänge", "Bruttopersonalbedarf plus Reservebedarf", "Neubedarf minus Ersatzbedarf", "Bruttopersonalbedarf minus fortgeschriebener Personalbestand"], "c": 3, "e": "Der Nettopersonalbedarf ist der Bruttobedarf minus dem Bestand, der sicher noch da sein wird. Positiv heißt beschaffen, negativ heißt freistellen (Beiderwieden & Stickdorn, 2026)."}, {"q": "Nordstern braucht 2027 in der Montage 180.000 Stunden. Eine Vollzeitkraft leistet 1.500 Stunden. Wie hoch ist der Bruttopersonalbedarf?", "o": ["95 Vollzeitkräfte", "125 Vollzeitkräfte", "100 Vollzeitkräfte", "120 Vollzeitkräfte"], "c": 3, "e": "180.000 Stunden geteilt durch 1.500 Stunden je Kraft ergibt 120 Vollzeitkräfte. 100 ist der heutige Ist-Bestand."}, {"q": "Ist-Bestand 100, sichere Abgänge 7, sichere Zugänge 2. Wie hoch ist der fortgeschriebene Personalbestand?", "o": ["93", "95", "91", "105"], "c": 1, "e": "Fortgeschriebener Bestand gleich Ist-Bestand minus sichere Abgänge plus sichere Zugänge, also 100 − 7 + 2 = 95. Wer die Zugänge vergisst, kommt auf 93."}, {"q": "Ein Sachbearbeiter in Gleitzeit arbeitet an einem Tag 9,5 Stunden. Wie lange muss seine Pause mindestens sein?", "o": ["45 Minuten", "15 Minuten", "60 Minuten", "30 Minuten"], "c": 0, "e": "Bei mehr als 6 bis 9 Stunden sind 30 Minuten, bei mehr als 9 Stunden 45 Minuten Pause vorgeschrieben (§ 4 ArbZG). 60 Minuten gelten für Jugendliche."}, {"q": "Was bedeutet die Kernzeit in der Gleitzeitregelung von Nordstern?", "o": ["Zeit mit Anwesenheitspflicht von 09:00 bis 14:00 Uhr", "Höchste erlaubte Arbeitszeit an einem Tag", "Zeit, in der Beginn und Ende frei wählbar sind", "Zeit, in der nur Überstunden gezählt werden"], "c": 0, "e": "In der Kernzeit müssen alle anwesend sein. In der Rahmenzeit von 06:30 bis 19:00 Uhr wählen die Beschäftigten Beginn und Ende, höchstens aber 10 Stunden Arbeit (§ 3 ArbZG)."}, {"q": "Welche Formulierung in einer Stellenanzeige von Nordstern ist AGG-konform?", "o": ["Junger Sachbearbeiter Personal gesucht", "Deutsch als Muttersprache erforderlich", "Sachbearbeitung Personal (m/w/d)", "Bewerbungen bis 30 Jahre bevorzugt"], "c": 2, "e": "Stellen dürfen nicht benachteiligend ausgeschrieben werden (§ 11 AGG). Junger, Muttersprache und Altersgrenzen benachteiligen wegen Geschlecht, Alter oder Herkunft."}, {"q": "Innerhalb welcher Frist muss eine benachteiligte Bewerberin ihren Anspruch nach dem AGG schriftlich geltend machen?", "o": ["4 Monate", "3 Wochen", "2 Monate", "6 Monate"], "c": 2, "e": "Die Frist beträgt zwei Monate (§ 15 Abs. 4 AGG). Eine Verlängerung auf vier Monate ist nur geplant und noch nicht beschlossen (Deutscher Bundestag, 2026)."}, {"q": "Ein Personalberater verlangt 20 % eines Jahresgehalts von 3.950 € × 12. Wie hoch ist sein Honorar?", "o": ["1.200 €", "7.900 €", "790 €", "9.480 €"], "c": 3, "e": "3.950 € × 12 = 47.400 €, davon 20 % sind 9.480 €. Die Online-Anzeige kostete nur 1.200 €."}, {"q": "Was kennzeichnet ein Assessment-Center?", "o": ["Ein einzelnes Gespräch mit der Personalleitung", "Mehrere Beobachter bewerten Bewerber in mehreren Übungen", "Eine bezahlte Probearbeit über zwei Wochen", "Ein schriftlicher Wissenstest ganz ohne Beobachter"], "c": 1, "e": "Im Assessment-Center bewerten mehrere Beobachter mehrere Bewerber in Übungen wie Postkorb, Rollenspiel und Präsentation nach festen Kriterien (Beiderwieden & Stickdorn, 2026)."}, {"q": "Welche Form braucht die Befristung eines Arbeitsvertrags?", "o": ["Schriftform mit eigenhändiger Unterschrift", "Textform, z. B. als PDF per E-Mail", "Eine mündliche Vereinbarung genügt", "Eine Beurkundung beim Notar"], "c": 0, "e": "Die Befristung bedarf der Schriftform (§ 14 Abs. 4 TzBfG). Fehlt sie, gilt der Vertrag als auf unbestimmte Zeit geschlossen."}, {"q": "Wie lange darf ein Arbeitsvertrag ohne Sachgrund höchstens befristet werden?", "o": ["3 Jahre", "2 Jahre", "1 Jahr", "18 Monate"], "c": 1, "e": "Ohne Sachgrund sind bis zu zwei Jahre mit höchstens drei Verlängerungen erlaubt (§ 14 Abs. 2 TzBfG). 18 Monate sind die Höchstdauer beim Personalleasing."}, {"q": "Was besagt das Günstigkeitsprinzip?", "o": ["Der Tarif gilt nur, wenn er günstiger als das Gesetz ist", "Abweichungen vom Tarif sind zugunsten der Beschäftigten erlaubt", "Der Arbeitgeber darf den für ihn günstigsten Tarif wählen", "Beschäftigte dürfen auf tarifliche Ansprüche verzichten"], "c": 1, "e": "Ein Tarifvertrag gilt unmittelbar und zwingend. Abweichen darf man nur, wenn der Tarif es erlaubt oder die Regelung für die Beschäftigten günstiger ist (§ 4 Abs. 3 TVG)."}, {"q": "Ab wann hat ein neuer Beschäftigter Anspruch auf Entgeltfortzahlung bei Krankheit?", "o": ["Erst nach Ablauf der Probezeit", "Nach 4 Wochen ununterbrochenem Arbeitsverhältnis", "Nach 6 Wochen Beschäftigung", "Ab dem ersten Arbeitstag ohne Wartezeit"], "c": 1, "e": "Der Anspruch entsteht nach vier Wochen ununterbrochenem Arbeitsverhältnis und gilt bis zu sechs Wochen (§ 3 EFZG)."}, {"q": "Welche Meldung muss Nordstern bei einer Neueinstellung abgeben?", "o": ["DEÜV-Anmeldung bei der Krankenkasse", "Meldung an die IHK zu Lübeck", "Anzeige beim Gewerbeamt", "Sofortmeldung vor Arbeitsaufnahme"], "c": 0, "e": "Die Anmeldung erfolgt mit der ersten Entgeltabrechnung, spätestens nach sechs Wochen (§ 6 DEÜV). Eine Sofortmeldung gilt nur für bestimmte Branchen wie Bau oder Gaststätten (§ 28a Abs. 4 SGB IV)."}, {"q": "Wie hoch ist der Akkordrichtsatz bei 20,00 € Grundlohn und 20 % Akkordzuschlag?", "o": ["22,00 € je Stunde", "20,00 € je Stunde", "25,00 € je Stunde", "24,00 € je Stunde"], "c": 3, "e": "Akkordrichtsatz gleich Grundlohn plus Akkordzuschlag, also 20,00 € + 4,00 € = 24,00 € (Beiderwieden & Stickdorn, 2026)."}, {"q": "Die Vorgabezeit beträgt 15 Minuten je Stück, der Akkordrichtsatz 24,00 €. Wie hoch ist das Stückgeld?", "o": ["4,00 €", "0,40 €", "1,60 €", "6,00 €"], "c": 3, "e": "Normalleistung 60 ÷ 15 = 4 Stück je Stunde. Stückgeld 24,00 € ÷ 4 = 6,00 €. 0,40 € ist der Minutenfaktor beim Zeitakkord."}, {"q": "Wer trägt den Kinderlosenzuschlag in der Pflegeversicherung?", "o": ["Der Arbeitgeber allein für alle Kinderlosen", "Kinderlose Beschäftigte ab 23 Jahren allein", "Alle Beschäftigten unter 23 Jahren", "Arbeitgeber und Beschäftigte je zur Hälfte"], "c": 1, "e": "Den Zuschlag von 0,6 Punkten zahlen nur kinderlose Beschäftigte ab dem vollendeten 23. Lebensjahr, der Arbeitgeber trägt nichts davon (§ 55 Abs. 3 SGB XI)."}, {"q": "Lisa Wagner hat 3.950,00 € brutto, 558,35 € Steuern und 859,13 € Abzüge zur Sozialversicherung. Wie hoch ist ihr Nettoentgelt?", "o": ["2.673,10 €", "3.090,87 €", "3.391,65 €", "2.532,52 €"], "c": 3, "e": "3.950,00 € − 558,35 € − 859,13 € = 2.532,52 €. Wer nur einen Abzug berücksichtigt, kommt auf 3.090,87 € oder 3.391,65 €."}, {"q": "Welche drei Bereiche umfasst die Personalentwicklung im weiten Sinn?", "o": ["Bildung, Förderung und Organisationsentwicklung", "Planung, Führung und Beurteilung", "Ausbildung, Entlohnung und Controlling", "Beschaffung, Einstellung und Freistellung"], "c": 0, "e": "Im Kurs gilt die weite Bedeutung mit Bildung, Förderung und Organisationsentwicklung (Beiderwieden & Stickdorn, 2026)."}, {"q": "Ein Monteur montiert künftig neben dem Rahmen auch die Lenker. Wie heißt diese Maßnahme?", "o": ["Job Enrichment", "Job Enlargement", "Job Rotation", "Coaching"], "c": 1, "e": "Er bekommt mehr Aufgaben auf gleichem Niveau, das ist eine horizontale Erweiterung. Mehr Verantwortung wäre Job Enrichment (Oechsler & Paul, 2019)."}, {"q": "Womit beginnt der Personalentwicklungsprozess?", "o": ["Mit dem Transfer", "Mit der Bedarfsanalyse", "Mit der Erfolgskontrolle", "Mit der Durchführung"], "c": 1, "e": "Zuerst vergleicht der Betrieb vorhandene und geforderte Qualifikationen. Danach folgen Ziele, Planung, Durchführung, Erfolgskontrolle und Transfer (Beiderwieden & Stickdorn, 2026)."}, {"q": "Nordstern hatte 2025 genau 708 Weiterbildungstage bei 236 Beschäftigten im Durchschnitt. Wie viele Tage sind das je Beschäftigten?", "o": ["2,0 Tage", "3,0 Tage", "3,5 Tage", "2,95 Tage"], "c": 1, "e": "708 ÷ 236 = 3,0 Tage. 2,95 Tage entstehen, wenn man fälschlich durch den Stichtagsbestand 240 teilt."}, {"q": "Welche Bedürfnisstufe steht bei Maslow ganz oben?", "o": ["Selbstverwirklichung", "Wertschätzung", "Soziale Bedürfnisse", "Sicherheit"], "c": 0, "e": "Maslow ordnet fünf Stufen von physiologischen Bedürfnissen über Sicherheit, soziale Bedürfnisse und Wertschätzung bis zur Selbstverwirklichung (Maslow, 1943)."}, {"q": "Was kennzeichnet die Theorie Y nach McGregor?", "o": ["Menschen wollen leisten und Verantwortung tragen", "Menschen sind arbeitsscheu und brauchen Kontrolle", "Menschen arbeiten ausschließlich für Geld", "Menschen meiden jede Form von Verantwortung"], "c": 0, "e": "Theorie Y sieht Menschen als leistungsbereit und selbstständig, Theorie X als arbeitsscheu (McGregor, 1960)."}, {"q": "Wonach richtet sich der Führungsstil beim situativen Führen nach Hersey und Blanchard?", "o": ["Nach dem Alter der Führungskraft", "Nach dem Reifegrad der Mitarbeitenden", "Nach der Höhe des Entgelts", "Nach der Größe des Unternehmens"], "c": 1, "e": "Der Reifegrad beschreibt Fähigkeit und Bereitschaft. Je höher er ist, desto mehr kann delegiert werden (Hersey & Blanchard, 1969)."}, {"q": "Malte Brandt vereinbart mit seinem Team Ziele und lässt den Weg dorthin offen. Welche Führungstechnik nutzt er?", "o": ["Management by Exception", "Management by Objectives", "Laissez-faire-Stil", "Management by Delegation"], "c": 1, "e": "Führen durch Zielvereinbarung heißt Management by Objectives. Bei Management by Exception greift die Führungskraft nur bei Abweichungen ein (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was kennzeichnet den autoritären Führungsstil?", "o": ["Die Mitarbeitenden werden immer beteiligt", "Die Führungskraft gibt keine Anweisungen", "Die Führungskraft entscheidet allein", "Die Gruppe entscheidet weitgehend selbst"], "c": 2, "e": "Beim autoritären Stil entscheidet und kontrolliert die Führungskraft allein. Beteiligung kennzeichnet den kooperativen Stil, Zurückhaltung den Laissez-faire-Stil (Lewin et al., 1939)."}, {"q": "Welche Form ist für eine Kündigung des Arbeitsverhältnisses vorgeschrieben?", "o": ["Textform als E-Mail mit Anhang", "Mündlich vor zwei Zeugen", "Schriftform mit eigenhändiger Unterschrift", "Nachricht über einen Messenger"], "c": 2, "e": "Kündigung und Auflösungsvertrag bedürfen der Schriftform, die elektronische Form ist ausgeschlossen (§ 623 BGB)."}, {"q": "Wie lautet die Grundkündigungsfrist für Arbeitnehmer und Arbeitgeber?", "o": ["3 Monate zum Ende eines Quartals", "1 Monat zum Ende eines Monats", "4 Wochen zum 15. oder zum Monatsende", "2 Wochen zu jedem beliebigen Tag"], "c": 2, "e": "Die Grundfrist beträgt vier Wochen zum 15. oder zum Ende eines Kalendermonats (§ 622 Abs. 1 BGB). Zwei Wochen gelten nur in der Probezeit."}, {"q": "Thomas Albers ist seit 01.03.2014 bei Nordstern. Die Kündigung durch den Arbeitgeber geht am 02.12.2026 zu. Wann endet das Arbeitsverhältnis?", "o": ["Am 31.03.2027", "Am 31.05.2027", "Am 30.04.2027", "Am 02.05.2027"], "c": 1, "e": "Nach 12 Jahren gelten 5 Monate zum Monatsende (§ 622 Abs. 2 BGB). 5 Monate ab Zugang enden am 02.05.2027, also endet das Arbeitsverhältnis am 31.05.2027."}, {"q": "Was gilt, wenn Nordstern den Betriebsrat vor einer Kündigung nicht anhört?", "o": ["Die Kündigung ist unwirksam", "Es wird nur ein Bußgeld fällig", "Die Kündigungsfrist verlängert sich um eine Woche", "Die Kündigung ist wirksam, aber anfechtbar"], "c": 0, "e": "Eine ohne Anhörung des Betriebsrats ausgesprochene Kündigung ist unwirksam (§ 102 Abs. 1 BetrVG)."}, {"q": "Wie lange hat ein Arbeitnehmer Zeit, eine Kündigungsschutzklage zu erheben?", "o": ["3 Monate nach Zugang der Kündigung", "2 Wochen nach Zugang der Kündigung", "1 Monat nach Ende des Arbeitsverhältnisses", "3 Wochen nach Zugang der Kündigung"], "c": 3, "e": "Die Klage muss innerhalb von drei Wochen nach Zugang der schriftlichen Kündigung erhoben werden, sonst gilt die Kündigung als wirksam (§ 4 KSchG, § 7 KSchG)."}, {"q": "Welche Formel gilt im Kurs für die Fluktuationsquote?", "o": ["Neueinstellungen ÷ Bewerbungen × 100", "Kündigungen durch Beschäftigte ÷ Ø Bestand × 100", "Krankheitstage ÷ Soll-Arbeitstage × 100", "Abgänge ÷ Stichtagsbestand × 1.000"], "c": 1, "e": "Die vereinfachte Formel teilt die Kündigungen durch Beschäftigte durch den durchschnittlichen Personalbestand, bei Nordstern 14 ÷ 236 × 100 = 5,93 % (Beiderwieden & Stickdorn, 2026)."}, {"q": "Wie hoch ist die Krankenquote von Nordstern 2025 bei 3.115 Krankheitstagen und 51.920 Soll-Arbeitstagen?", "o": ["13,2 %", "1,32 %", "6,00 %", "5,93 %"], "c": 2, "e": "3.115 ÷ 51.920 × 100 = 6,00 %. 5,93 % ist die Fluktuationsquote, 13,2 sind die Krankheitstage je Beschäftigten."}, {"q": "Mit welchem Personalbestand rechnet Nordstern die Ausbildungsquote?", "o": ["Mit 230 Beschäftigten ohne Azubis", "Mit dem Stichtagsbestand von 240", "Mit dem Durchschnittsbestand von 236", "Mit den 100 Beschäftigten der Montage"], "c": 1, "e": "Die Ausbildungsquote nutzt den Stand am 31.12.2025, also 10 ÷ 240 × 100 = 4,17 %. Alle anderen Quoten nutzen den Durchschnitt 236."}, {"q": "Nordstern hatte 2025 einen Personalaufwand von 15,6 Mio. € und einen Umsatz von 48,0 Mio. €. Wie hoch ist die Personalaufwandsquote?", "o": ["30,8 %", "48,0 %", "3,08 %", "32,5 %"], "c": 3, "e": "Personalaufwand ÷ Umsatz × 100, also 15,6 ÷ 48,0 × 100 = 32,5 %. Fast ein Drittel des Umsatzes fließt in das Personal."}, {"q": "Ein Betrieb ohne Tarifbindung zahlt eine Ausbildungsvergütung, die 25 % unter dem Tarif der Branche liegt. Wie ist das zu bewerten?", "o": ["Die Vergütung ist in der Regel nicht angemessen", "Die Vergütung ist immer angemessen, weil kein Tarif gilt", "Die Vergütung darf beliebig niedrig sein", "Die Vergütung muss genau dem Mindestlohn entsprechen"], "c": 0, "e": "Nach § 17 BBiG muss die Vergütung angemessen sein. Ohne Tarifbindung gilt sie in der Regel als unangemessen, wenn sie mehr als 20 % unter dem Branchentarif liegt. Der Mindestlohn gilt für Azubis nicht (§ 22 MiLoG)."}, {"q": "Welche Klausel in einem Ausbildungsvertrag ist nach § 12 BBiG nichtig?", "o": ["Eine Probezeit von drei Monaten", "Mehr Urlaub, als das Gesetz verlangt", "Eine Vertragsstrafe bei vorzeitigem Abbruch", "Ein elektronisch geführter Ausbildungsnachweis"], "c": 2, "e": "Vertragsstrafen, Zahlungen für die Ausbildung und Bindungen für die Zeit danach sind nach § 12 BBiG nichtig. Eine Probezeit von 1 bis 4 Monaten ist dagegen sogar Pflicht."}, {"q": "Nordstern lässt Mia an einzelnen Tagen mobil von zu Hause lernen. Wer stellt nach § 14 BBiG den Laptop dafür?", "o": ["Mia muss sich das Gerät selbst kaufen", "Der Betrieb stellt ihn kostenlos zur Verfügung", "Die Berufsschule leiht ihn gegen Gebühr aus", "Die IHK zu Lübeck stellt ihn für alle Azubis"], "c": 1, "e": "Ausbildungsmittel stellt der Ausbildende kostenlos. Dazu gehören nach § 14 BBiG auch Hard- und Software, wenn mobil ausgebildet wird."}, {"q": "In welcher Zeit gilt für Jugendliche grundsätzlich die Nachtruhe nach dem Jugendarbeitsschutzgesetz?", "o": ["Von 22 bis 5 Uhr", "Von 20 bis 6 Uhr", "Von 23 bis 6 Uhr", "Von 21 bis 7 Uhr"], "c": 1, "e": "Nach § 14 JArbSchG dürfen Jugendliche grundsätzlich nur zwischen 6 und 20 Uhr beschäftigt werden. Die Zeit von 23 bis 6 Uhr ist die Nachtzeit für Erwachsene nach dem ArbZG."}, {"q": "Was muss vorliegen, bevor ein Betrieb eine jugendliche Person beschäftigen darf?", "o": ["Eine ärztliche Bescheinigung über die Erstuntersuchung", "Eine schriftliche Zustimmung der Berufsschule", "Ein bestandener Einstellungstest der IHK", "Eine Bescheinigung der Agentur für Arbeit"], "c": 0, "e": "Nach § 32 JArbSchG darf eine jugendliche Person nur beschäftigt werden, wenn sie in den letzten 14 Monaten ärztlich untersucht wurde und die Bescheinigung dem Arbeitgeber vorliegt."}, {"q": "Was versteht man unter dem Reservebedarf in der Personalplanung?", "o": ["Den Zuschlag für Ausfälle durch Urlaub, Krankheit oder Weiterbildung", "Die Zahl der Stellen, die durch Wachstum neu entstehen", "Den Ersatz für Beschäftigte, die in Rente gehen", "Die Zahl der Bewerbungen, die auf Vorrat gesammelt werden"], "c": 0, "e": "Der Reservebedarf deckt Ausfallzeiten ab, damit die Arbeit trotz Urlaub oder Krankheit erledigt wird (Beiderwieden & Stickdorn, 2026). Bei Nordstern steckt er schon in den 1.500 produktiven Stunden je Vollzeitkraft."}, {"q": "Ein Betrieb ermittelt, welche Kenntnisse und Fähigkeiten eine neue Stelle verlangt. Um welche Planung geht es?", "o": ["Um die quantitative Bedarfsplanung", "Um die qualitative Bedarfsplanung", "Um die Planung der Personalkosten", "Um die Planung der Freistellung"], "c": 1, "e": "Die qualitative Planung fragt nach den Qualifikationen, zum Beispiel mit Stellenbeschreibung und Anforderungsprofil. Die quantitative Planung fragt, wie viele Kräfte wann und wo gebraucht werden."}, {"q": "Was beschreibt ein Anforderungsprofil?", "o": ["Die Aufgaben, Befugnisse und die Einordnung einer Stelle", "Die Kenntnisse und Eigenschaften, die eine Person für die Stelle braucht", "Die Noten, die eine Person in der Berufsschule hatte", "Den Weg der Stelle im Organigramm bis zur Geschäftsführung"], "c": 1, "e": "Das Anforderungsprofil leitet aus den Aufgaben ab, was eine Person können muss. Die Aufgaben und die Einordnung selbst stehen in der Stellenbeschreibung."}, {"q": "Bei welchem Verfahren ermitteln erfahrene Führungskräfte den Personalbedarf vor allem aus ihrer Einschätzung?", "o": ["Bei der Kennzahlenmethode", "Bei der Stellenplanmethode", "Beim Schätzverfahren", "Bei der Sozialauswahl"], "c": 2, "e": "Beim Schätzverfahren beruht der Bedarf auf der Erfahrung von Fachleuten, etwa durch Befragung der Abteilungsleitungen. Es ist einfach, aber ungenauer als eine Rechnung mit Kennzahlen."}, {"q": "Wie heißt ein Arbeitszeitmodell, bei dem sich zwei Beschäftigte einen Vollzeitarbeitsplatz teilen?", "o": ["Jobsharing", "Job Rotation", "Jahresarbeitszeit", "Schichtarbeit"], "c": 0, "e": "Beim Jobsharing teilen sich zwei oder mehr Personen einen Arbeitsplatz und stimmen ihre Zeiten ab (§ 13 TzBfG). Job Rotation ist dagegen ein Instrument der Personalentwicklung."}, {"q": "Was versteht man unter Employer Branding?", "o": ["Den Aufbau einer attraktiven Marke als Arbeitgeber", "Die Bewertung von Bewerbungen mit Punkten", "Die Werbung für ein neues Produkt auf Messen", "Die Überlassung von Personal durch einen Verleiher"], "c": 0, "e": "Employer Branding heißt, sich als guter Arbeitgeber zu zeigen, damit passende Fachkräfte sich bewerben und bleiben (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was bedeutet die Beweislastregel nach § 22 AGG?", "o": ["Die abgelehnte Person muss die Benachteiligung voll beweisen", "Indizien reichen, dann muss der Arbeitgeber das Gegenteil beweisen", "Der Betriebsrat entscheidet, wer recht hat", "Das Gericht darf nur schriftliche Zeugnisse prüfen"], "c": 1, "e": "Nach § 22 AGG genügen Indizien für eine Benachteiligung. Dann muss der Arbeitgeber beweisen, dass er nicht benachteiligt hat. Darum ist eine saubere Dokumentation der Auswahl wichtig."}, {"q": "In welcher Art von Tarifvertrag steht typischerweise die Höhe der Monatsentgelte je Entgeltgruppe?", "o": ["Im Entgelttarifvertrag", "Im Manteltarifvertrag", "Im Ausbildungsvertrag", "Im Überlassungsvertrag"], "c": 0, "e": "Der Entgelttarifvertrag regelt die Höhe der Entgelte und läuft meist kurz. Allgemeine Bedingungen wie Urlaub stehen im Manteltarifvertrag, die Eingruppierung im Rahmentarifvertrag."}, {"q": "Der Entgelttarifvertrag läuft noch bis Ende 2027. Die Gewerkschaft will schon jetzt für mehr Lohn streiken. Was steht dem entgegen?", "o": ["Die Friedenspflicht", "Das Günstigkeitsprinzip", "Die Allgemeinverbindlichkeit", "Die Nachwirkung"], "c": 0, "e": "Während der Laufzeit eines Tarifvertrags gilt die Friedenspflicht. Über dort geregelte Fragen darf nicht gestreikt werden. Nach dem Ende wirkt der Tarif nach, bis eine neue Regel gilt (§ 4 Abs. 5 TVG)."}, {"q": "Was bewirkt die Allgemeinverbindlicherklärung eines Tarifvertrags nach § 5 TVG?", "o": ["Er gilt auch für Arbeitgeber und Beschäftigte ohne Tarifbindung", "Er gilt nur noch für Mitglieder der Gewerkschaft", "Er verliert seine Wirkung nach einem Jahr", "Er ersetzt alle Gesetze zum Arbeitsrecht"], "c": 0, "e": "Erklärt das BMAS einen Tarifvertrag für allgemeinverbindlich, gilt er in seinem Bereich auch für Nichtgebundene (§ 5 TVG). Gesetze ersetzt er nicht."}, {"q": "Ein Arbeitsvertrag sieht weniger Urlaub vor, als das Bundesurlaubsgesetz verlangt. Was gilt?", "o": ["Es gilt mindestens der gesetzliche Urlaub", "Es gilt der kürzere Urlaub aus dem Vertrag", "Der Vertrag ist insgesamt nichtig", "Der Betriebsrat legt den Urlaub fest"], "c": 0, "e": "Das Gesetz ist ein Mindeststandard, von dem der Vertrag nicht nach unten abweichen darf. Es bleibt bei mindestens 24 Werktagen (§ 3 BUrlG), der übrige Vertrag bleibt wirksam."}, {"q": "Welche Rechte hat eine Beschäftigte bezogen auf ihre Personalakte?", "o": ["Sie darf Beurteilungen in der Akte selbst löschen", "Sie darf Einsicht in ihre Personalakte nehmen", "Sie bestimmt allein, wer im Betrieb Zugriff hat", "Sie darf die Akte dauerhaft mit nach Hause nehmen"], "c": 1, "e": "Beschäftigte haben ein Recht auf Einsicht (§ 83 BetrVG) und auf Auskunft über ihre Daten (Art. 15 DSGVO). Über den Zugriff entscheidet der Arbeitgeber und muss ihn auf das Nötige beschränken."}, {"q": "Was kennzeichnet den Prämienlohn?", "o": ["Fester Grundlohn plus Zuschlag für eine messbare Mehrleistung", "Bezahlung nur nach der Zahl der gefertigten Stücke", "Beteiligung aller Beschäftigten am Jahresgewinn", "Fester Monatsbetrag unabhängig von der Leistung"], "c": 0, "e": "Beim Prämienlohn bleibt der Grundlohn sicher. Dazu kommt eine Prämie zum Beispiel für Menge, Qualität, Ersparnis oder Termintreue (Beiderwieden & Stickdorn, 2026)."}, {"q": "Wie heißt die Form der Erfolgsbeteiligung, bei der Beschäftigte zum Beispiel Belegschaftsaktien erhalten?", "o": ["Kapitalbeteiligung", "Umsatzbeteiligung", "Qualitätsprämie", "Stückgeldakkord"], "c": 0, "e": "Bei der Kapitalbeteiligung werden Beschäftigte Miteigentümer, etwa über Belegschaftsaktien oder stille Beteiligungen. Gewinn- und Umsatzbeteiligung zahlen dagegen einen Anteil am Ergebnis aus (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was unterscheidet die analytische von der summarischen Arbeitsbewertung?", "o": ["Die Stelle wird in einzelne Anforderungsmerkmale zerlegt und bepunktet", "Die Stelle wird als Ganzes mit anderen Stellen verglichen", "Bewertet wird die persönliche Leistung der Person auf der Stelle", "Bewertet wird nur, wie lange die Person schon im Betrieb ist"], "c": 0, "e": "Analytisch zerlegt man die Stelle in Merkmale wie Können, Verantwortung und Belastung und vergibt Punkte. Summarisch betrachtet man die Stelle als Ganzes. Bewertet wird immer die Stelle, nicht der Mensch."}, {"q": "Was sind ELStAM?", "o": ["Die elektronischen Lohnsteuerabzugsmerkmale wie Steuerklasse und Kinderfreibeträge", "Die elektronischen Meldungen an die Krankenkasse bei Einstellung", "Die Entgeltgruppen aus dem Tarifvertrag der Metallindustrie", "Die Beitragssätze der Sozialversicherung für das laufende Jahr"], "c": 0, "e": "Der Arbeitgeber ruft die ELStAM beim Finanzamt ab. Sie bestimmen, welche Lohnsteuer aus der Tabelle abzulesen ist (EStG)."}, {"q": "Wie hoch ist die Kirchensteuer bei Nordstern in Schleswig-Holstein?", "o": ["9 % der Lohnsteuer", "8 % des Bruttoentgelts", "9 % des Bruttoentgelts", "5,5 % der Lohnsteuer"], "c": 0, "e": "In Schleswig-Holstein und Hamburg beträgt die Kirchensteuer 9 % der Lohnsteuer (Lohn-Info, 2026). 5,5 % ist der volle Satz des Solidaritätszuschlags."}, {"q": "Was bewirkt die Beitragsbemessungsgrenze in der Sozialversicherung?", "o": ["Beiträge werden nur bis zu dieser Entgelthöhe berechnet", "Bis zu dieser Grenze ist das Entgelt beitragsfrei", "Oberhalb dieser Grenze steigt der Beitragssatz", "Ab dieser Grenze zahlt nur noch der Arbeitgeber"], "c": 0, "e": "Entgelt über der Grenze ist beitragsfrei. 2026 liegt sie in der Kranken- und Pflegeversicherung bei 5.812,50 € im Monat, in der Renten- und Arbeitslosenversicherung bei 8.450,00 € (TK, 2026b)."}, {"q": "Was für ein Konto ist 2640 SV-Vorauszahlung im Industriekontenrahmen?", "o": ["Ein aktives Bestandskonto", "Ein Aufwandskonto", "Ein Ertragskonto", "Ein passives Bestandskonto"], "c": 0, "e": "Nordstern überweist die SV-Beiträge schon vor der Gehaltszahlung. Dadurch entsteht eine Forderung auf dem aktiven Bestandskonto 2640, die später mit den Anteilen von AN und AG ausgeglichen wird (Westermann Gruppe, 2021)."}, {"q": "Ein Lagerarbeiter lernt in zwei Jahren den neuen Beruf Industriekaufmann. Welche Art der beruflichen Bildung ist das?", "o": ["Umschulung", "Anpassungsfortbildung", "Aufstiegsfortbildung", "Berufsausbildungsvorbereitung"], "c": 0, "e": "Eine Umschulung befähigt zu einer anderen beruflichen Tätigkeit (BBiG). Fortbildung baut dagegen auf dem bisherigen Beruf auf, als Anpassung oder als Aufstieg."}, {"q": "Eine erfahrene Teamleiterin begleitet eine neue Führungskraft ein Jahr lang mit festen Treffen. Wie heißt diese Maßnahme?", "o": ["Mentoring", "Coaching durch einen externen Profi", "Job Enlargement", "Outplacement"], "c": 0, "e": "Beim Mentoring gibt eine erfahrene Person aus dem Betrieb Wissen und Kontakte weiter. Beim Coaching berät meist ein externer Coach (Beiderwieden & Stickdorn, 2026)."}, {"q": "Welche Ebene der Erfolgskontrolle prüft, ob jemand das Gelernte am Arbeitsplatz anwendet?", "o": ["Die Ebene Zufriedenheit", "Die Ebene Lernerfolg", "Die Ebene Verhalten", "Die Ebene Teilnahme"], "c": 2, "e": "Die vier Ebenen sind Zufriedenheit, Lernerfolg, Verhalten und Ergebnis (Oechsler & Paul, 2019). Das Verhalten am Arbeitsplatz beobachtet die Führungskraft einige Wochen nach der Maßnahme."}, {"q": "Der Betriebsrat hält eine Ausbilderin für fachlich ungeeignet. Was kann er nach § 98 BetrVG tun?", "o": ["Ihrer Bestellung widersprechen oder ihre Abberufung verlangen", "Ihr selbst fristlos kündigen", "Ihre Vergütung eigenständig kürzen", "Die Ausbildung im Betrieb sofort beenden"], "c": 0, "e": "§ 98 BetrVG gibt dem Betriebsrat Mitbestimmung bei der betrieblichen Bildung. Dazu gehört das Recht, ungeeigneten Ausbildenden zu widersprechen. Kündigen kann nur der Arbeitgeber."}, {"q": "Wie verändert sich der Spielraum der Mitarbeitenden auf dem Kontinuum von Tannenbaum und Schmidt nach rechts?", "o": ["Er wird größer", "Er wird kleiner", "Er bleibt immer gleich", "Er hängt nur vom Entgelt ab"], "c": 0, "e": "Links steht der vorgesetztenzentrierte, rechts der mitarbeiterzentrierte Stil. Nach rechts wächst mit jeder der sieben Stufen der Entscheidungsspielraum der Gruppe (Tannenbaum & Schmidt, 1958)."}, {"q": "Ein Monteur tüftelt in der Pause an einer besseren Lösung, weil ihn die Technik begeistert. Welche Art von Motivation zeigt er?", "o": ["Intrinsische Motivation", "Extrinsische Motivation", "Motivation durch einen Hygienefaktor", "Motivation durch Druck nach Theorie X"], "c": 0, "e": "Der Antrieb kommt aus der Tätigkeit selbst, also von innen. Das ist intrinsische Motivation. Extrinsisch wäre ein Antrieb durch Geld, Lob oder Druck von außen."}, {"q": "Zu welcher Art von Bedürfnissen zählt Maslow die Selbstverwirklichung?", "o": ["Zu den Wachstumsbedürfnissen", "Zu den Defizitbedürfnissen", "Zu den Hygienefaktoren", "Zu den Sicherheitsbedürfnissen"], "c": 0, "e": "Die unteren vier Stufen sind Defizitbedürfnisse. Die Selbstverwirklichung an der Spitze ist ein Wachstumsbedürfnis (Maslow, 1943). Hygienefaktoren stammen von Herzberg."}, {"q": "Wie arbeitet eine Führungskraft beim Management by Exception?", "o": ["Sie greift nur ein, wenn Abweichungen über festgelegte Grenzen gehen", "Sie vereinbart mit jeder Person ein jährliches Ziel", "Sie überträgt Aufgaben mit Kompetenz und Verantwortung dauerhaft", "Sie entscheidet jeden Einzelfall selbst und sofort"], "c": 0, "e": "Beim Management by Exception regeln die Mitarbeitenden den Normalfall selbst. Die Führungskraft wird nur bei Ausnahmen aktiv, das entlastet sie (Beiderwieden & Stickdorn, 2026)."}, {"q": "Was braucht Nordstern für die außerordentliche Kündigung eines Mitglieds des Betriebsrats?", "o": ["Die Zustimmung des Betriebsrats, die das Arbeitsgericht ersetzen kann", "Nur eine Anhörung mit einer Frist von einer Woche", "Die Zustimmung der Agentur für Arbeit", "Keine Beteiligung, weil der Grund wichtig ist"], "c": 0, "e": "Mitgliedern des Betriebsrats kann nicht ordentlich gekündigt werden (§ 15 KSchG). Für eine außerordentliche Kündigung braucht der Arbeitgeber die Zustimmung des Betriebsrats nach § 103 BetrVG, sonst entscheidet das Arbeitsgericht."}, {"q": "Innerhalb welcher Frist muss eine außerordentliche Kündigung erklärt werden?", "o": ["Innerhalb von 2 Wochen ab Kenntnis der Tatsachen", "Innerhalb von 4 Wochen zum 15. oder Monatsende", "Innerhalb von 3 Monaten nach dem Vorfall", "Innerhalb von 6 Monaten nach Beginn des Arbeitsverhältnisses"], "c": 0, "e": "Nach § 626 BGB muss die fristlose Kündigung innerhalb von 2 Wochen erfolgen, nachdem der Kündigende die maßgeblichen Tatsachen kennt."}, {"q": "Was braucht ein Arbeitgeber, bevor er einem schwerbehinderten Menschen kündigt?", "o": ["Die vorherige Zustimmung des Integrationsamts", "Die Zustimmung der IHK zu Lübeck", "Eine Genehmigung der Agentur für Arbeit", "Ein Urteil des Arbeitsgerichts"], "c": 0, "e": "Nach § 168 SGB IX ist die Kündigung eines schwerbehinderten Menschen nur mit vorheriger Zustimmung des Integrationsamts wirksam."}, {"q": "Wann muss sich ein gekündigter Arbeitnehmer spätestens arbeitsuchend melden?", "o": ["Spätestens 3 Monate vor dem Ende des Arbeitsverhältnisses", "Erst am ersten Tag ohne Arbeit", "Spätestens 3 Tage nach dem Ende des Arbeitsverhältnisses", "Erst nach dem Ende der Klagefrist"], "c": 0, "e": "Nach § 38 SGB III gilt die Meldung spätestens 3 Monate vor dem Ende. Liegen zwischen Kenntnis und Ende weniger als 3 Monate, muss die Meldung innerhalb von 3 Tagen nach Kenntnis erfolgen."}, {"q": "Welche Funktion erfüllt das Personalcontrolling, wenn es eine steigende Krankenquote früh meldet?", "o": ["Die Frühwarnfunktion", "Die Planungsfunktion", "Die Beschaffungsfunktion", "Die Ausbildungsfunktion"], "c": 0, "e": "Die Frühwarnfunktion zeigt Entwicklungen, bevor sie zum Problem werden. Weitere Funktionen sind Information, Planung, Steuerung und Kontrolle (Oechsler & Paul, 2019)."}, {"q": "Nordstern befragt alle Beschäftigten zur Zufriedenheit mit ihrer Führungskraft. Welche Art von Personalcontrolling ist das?", "o": ["Qualitatives Personalcontrolling", "Quantitatives Personalcontrolling", "Kostencontrolling", "Budgetcontrolling"], "c": 0, "e": "Zufriedenheit und Führungsqualität sind schwer in Euro oder Stück zu messen. Sie gehören zum qualitativen Personalcontrolling (Oechsler & Paul, 2019)."}, {"q": "Was versteht man im Personalcontrolling unter Benchmarking?", "o": ["Den Vergleich eigener Kennzahlen mit anderen Betrieben oder Bestwerten", "Die Prüfung von Bewerbungen nach einem Punkteschema", "Die Planung der Ausbildungsplätze für das nächste Jahr", "Die Erfassung der Arbeitszeit an einem Terminal"], "c": 0, "e": "Beim Benchmarking vergleicht der Betrieb seine Werte mit anderen, zum Beispiel die Krankenquote mit dem Durchschnitt in Deutschland (Destatis, 2026)."}, {"q": "Was bedeutet effektiv im Unterschied zu effizient?", "o": ["Effektiv heißt, die richtigen Dinge zu tun und das Ziel zu erreichen", "Effektiv heißt, möglichst wenig Geld für eine Maßnahme auszugeben", "Effektiv heißt, eine Maßnahme möglichst schnell zu beenden", "Effektiv heißt, alle Kosten genau in der Buchhaltung zu erfassen"], "c": 0, "e": "Effizient ist, wer die Dinge richtig tut, also mit wenig Aufwand. Effektiv ist, wer die richtigen Dinge tut, also wirklich zum Ziel beiträgt (Oechsler & Paul, 2019)."}, {"q": "Mia Schulz ist am 01.01.2027 schon 17 Jahre alt. Welcher Urlaub steht ihr 2027 nach § 19 JArbSchG mindestens zu?", "o": ["25 Werktage, also rund 20,83 Arbeitstage", "27 Werktage, also genau 22,5 Arbeitstage", "24 Werktage nach dem Bundesurlaubsgesetz", "30 Werktage, weil sie minderjährig ist"], "c": 0, "e": "Maßgeblich ist das Alter zu Beginn des Kalenderjahres. Wer dann noch nicht 18 ist, bekommt 25 Werktage (§ 19 JArbSchG). Umgerechnet sind das 25 ÷ 6 × 5 = 20,83 Arbeitstage."}, {"q": "Leon Becker (19) hat dienstags 6 Unterrichtsstunden zu je 45 Minuten. Der Teamleiter will, dass er danach noch in den Betrieb kommt. Was gilt?", "o": ["Nein, § 15 BBiG gilt auch für ihn", "Ja, weil er schon volljährig ist", "Ja, aber höchstens für 4 Stunden", "Nur freiwillig und ohne Anrechnung"], "c": 0, "e": "Einmal pro Woche ist ein Berufsschultag mit mehr als 5 Unterrichtsstunden zu je 45 Minuten frei. Diese Regel steht seit 2020 im BBiG und gilt damit für alle Azubis, auch für Erwachsene (§ 15 BBiG)."}, {"q": "Mia begann am 01.08.2026 mit einer Probezeit von 4 Monaten. Bis zu welchem Tag kann Nordstern ohne Frist und ohne Angabe von Gründen kündigen?", "o": ["Bis zum 30.11.2026", "Bis zum 31.10.2026", "Bis zum 31.01.2027", "Bis zum 01.12.2026"], "c": 0, "e": "Vier Monate ab dem 01.08.2026 enden am 30.11.2026. In der Probezeit ist eine schriftliche Kündigung jederzeit ohne Frist möglich (§ 22 Abs. 1 BBiG). Danach kann Nordstern nur noch aus wichtigem Grund kündigen."}, {"q": "Die produktive Jahresarbeitszeit je Monteur sinkt durch mehr Weiterbildung von 1.500 auf 1.440 Stunden. Wie hoch ist der Bruttobedarf für 180.000 Montagestunden?", "o": ["125 Vollzeitkräfte", "120 Vollzeitkräfte", "118 Vollzeitkräfte", "130 Vollzeitkräfte"], "c": 0, "e": "180.000 ÷ 1.440 = 125. Weniger produktive Stunden je Kraft erhöhen den Bedarf, obwohl die Produktion gleich bleibt. Mit 1.500 Stunden wären es 120."}, {"q": "Eine Sachbearbeiterin in Gleitzeit arbeitet von 07:00 bis 18:15 Uhr mit 45 Minuten Pause. Wie ist das nach dem ArbZG zu beurteilen?", "o": ["Unzulässig, weil sie 10,5 Stunden arbeitet", "Zulässig, weil sie innerhalb der Rahmenzeit bleibt", "Unzulässig, weil die Pause zu kurz ist", "Zulässig, wenn sie am Folgetag früher geht"], "c": 0, "e": "07:00 bis 18:15 Uhr sind 11,25 Stunden, minus 0,75 Stunden Pause ergibt 10,5 Stunden. Mehr als 10 Stunden sind nach § 3 ArbZG nie erlaubt. Die Pause von 45 Minuten reicht bei mehr als 9 Stunden aus (§ 4 ArbZG)."}, {"q": "Für eine Teamleitung in EG 11 (4.500 € im Monat) würde ein Personalberater 20 % eines Jahresgehalts verlangen. Wie viel teurer ist das als die Online-Anzeige für 1.200 €?", "o": ["9.600 €", "10.800 €", "8.280 €", "9.480 €"], "c": 0, "e": "Jahresgehalt vereinfacht 4.500 € × 12 = 54.000 €. Honorar 54.000 € × 20 % = 10.800 €. Unterschied 10.800 € − 1.200 € = 9.600 €."}, {"q": "Der Betriebsrat hat verlangt, dass Stellen vorher intern ausgeschrieben werden. Nordstern schreibt eine Stelle trotzdem nur extern aus. Was kann der Betriebsrat tun?", "o": ["Er kann die Zustimmung zur Einstellung verweigern", "Er kann die Bewerberin selbst einstellen", "Er kann die Anzeige auf eigene Kosten ändern", "Er hat keine Möglichkeit, weil intern freiwillig ist"], "c": 0, "e": "Nach § 93 BetrVG kann der Betriebsrat die interne Ausschreibung verlangen. Fehlt sie, ist das ein Grund, die Zustimmung zur Einstellung zu verweigern (§ 99 Abs. 2 BetrVG)."}, {"q": "Petra Holm erhält am Montag, 01.02.2027, alle Unterlagen zu einer geplanten Einstellung. Der Betriebsrat äußert sich nicht. Was gilt am Dienstag, 09.02.2027?", "o": ["Die Zustimmung gilt als erteilt", "Die Zustimmung gilt als verweigert", "Nordstern muss das Arbeitsgericht anrufen", "Die Frist läuft noch eine weitere Woche"], "c": 0, "e": "Der Betriebsrat muss eine Verweigerung schriftlich mit Gründen innerhalb einer Woche mitteilen. Die Woche endet am Montag, 08.02.2027. Danach gilt die Zustimmung als erteilt (§ 99 Abs. 3 BetrVG)."}, {"q": "Eine neue Lageristin in der Probezeit erhält am Freitag, 16.04.2027, die Kündigung. Wann endet ihr Arbeitsverhältnis?", "o": ["Am 30.04.2027", "Am 15.05.2027", "Am 31.05.2027", "Am 14.05.2027"], "c": 0, "e": "In der Probezeit gilt eine Frist von 2 Wochen zu jedem Tag (§ 622 Abs. 3 BGB). Die Frist beginnt am 17.04.2027 und endet am Freitag, 30.04.2027."}, {"q": "Wie hoch ist der Stundenlohn von Lisa Wagner in EG 9 nach dem Teiler von Nordstern?", "o": ["25,94 €", "23,65 €", "26,33 €", "22,70 €"], "c": 0, "e": "Stundenlohn = Monatsgrundentgelt ÷ 152,25 Stunden. 3.950 € ÷ 152,25 = 25,94 € (gerundet). 23,65 € ist der Stundenlohn in EG 7."}, {"q": "Ein neuer Monteur schafft in seiner ersten Schicht von 8 Stunden nur 25 Rahmen. Welcher Lohn wird gezahlt?", "o": ["160,00 €", "150,00 €", "192,00 €", "111,20 €"], "c": 0, "e": "Nach Stückzahl wären es 25 × 6,00 € = 150,00 €. Garantiert ist aber der Grundlohn von 20,00 € je Stunde, also 8 × 20,00 € = 160,00 €. 111,20 € wäre der gesetzliche Mindestlohn für 8 Stunden."}, {"q": "Im Zeitakkord gilt ein Minutenfaktor von 0,40 € und eine Vorgabezeit von 15 Minuten je Stück. Wie viel verdient ein Monteur für 36 Rahmen?", "o": ["216,00 €", "144,00 €", "240,00 €", "230,40 €"], "c": 0, "e": "Zeitakkord = Stückzahl × Vorgabezeit × Minutenfaktor. 36 × 15 × 0,40 € = 216,00 €. Im Stückgeldakkord ergibt sich dasselbe, 36 × 6,00 € = 216,00 €."}, {"q": "Wie viel Euro macht der Kinderlosenzuschlag zur Pflegeversicherung bei Lisa Wagner im November 2026 aus?", "o": ["23,70 €", "94,80 €", "71,10 €", "11,85 €"], "c": 0, "e": "Der Zuschlag beträgt 0,6 Prozentpunkte und trägt nur die Arbeitnehmerin (§ 55 SGB XI). 3.950 € × 0,6 % = 23,70 €. Ihr PV-Anteil steigt dadurch von 71,10 € auf 94,80 €."}, {"q": "Jonas Petersen (23,65 € je Stunde) leistet in einem Monat 6 Überstunden mit 25 % Zuschlag. Wie hoch ist die Vergütung dafür insgesamt?", "o": ["177,38 €", "141,90 €", "35,48 €", "295,63 €"], "c": 0, "e": "Überstundenvergütung 6 × 23,65 € = 141,90 €. Zuschlag 141,90 € × 25 % = 35,48 € (gerundet). Zusammen 177,38 €. Beides ist 2026 voll steuer- und beitragspflichtig."}, {"q": "Welche Kosten entstehen Nordstern im November 2026 für die Auszubildende Mia Schulz insgesamt?", "o": ["1.393,23 €", "1.150,00 €", "906,77 €", "1.636,46 €"], "c": 0, "e": "Arbeitgeberkosten im Kurs = Brutto + AG-Anteil zur Sozialversicherung. 1.150,00 € + 243,23 € = 1.393,23 €. 906,77 € ist ihr Nettoentgelt."}, {"q": "Lisa Wagner darf künftig Reklamationen bis 500 € selbst entscheiden und trägt dafür die Verantwortung. Welche Maßnahme ist das?", "o": ["Job Enrichment", "Job Enlargement", "Job Rotation", "Outplacement"], "c": 0, "e": "Mehr Entscheidung und Verantwortung ist eine Erweiterung nach oben, also Job Enrichment. Job Enlargement wären mehr gleichartige Aufgaben auf demselben Niveau."}, {"q": "Angenommen, Nordstern hat 2026 im Durchschnitt 238 Beschäftigte und 833 Weiterbildungstage. Wie viele Weiterbildungstage sind das je Beschäftigten?", "o": ["3,5 Tage", "3,0 Tage", "2,9 Tage", "4,0 Tage"], "c": 0, "e": "833 ÷ 238 = 3,5 Tage. 2025 waren es 708 ÷ 236 = 3,0 Tage, die Weiterbildung wäre also gestiegen."}, {"q": "Ein Meister gibt bei der Beurteilung allen Monteuren in jedem Kriterium die mittlere Stufe. Welcher Fehler liegt vor?", "o": ["Tendenz zur Mitte", "Halo-Effekt", "Nikolaus-Effekt", "Strengefehler"], "c": 0, "e": "Wer Extreme vermeidet und immer mittel bewertet, macht den Fehler Tendenz zur Mitte. Gute und schwache Leistungen werden so nicht mehr sichtbar."}, {"q": "Ein Monteur ist sehr erfahren, kann alle Aufgaben und arbeitet gern selbstständig. Welcher Stil passt nach Hersey und Blanchard?", "o": ["Delegieren", "Unterweisen", "Überzeugen", "Autoritär anweisen"], "c": 0, "e": "Bei hoher Fähigkeit und hoher Bereitschaft passt der Stil S4 Delegieren. Unterweisen passt für Mitarbeitende mit geringer Reife (Hersey & Blanchard, 1969)."}, {"q": "Ein Meister lässt sein Team die Abläufe selbst verbessern und vertraut auf Eigenverantwortung. Welches Menschenbild zeigt er?", "o": ["Theorie Y nach McGregor", "Theorie X nach McGregor", "Laissez-faire nach Lewin", "Hygienefaktor nach Herzberg"], "c": 0, "e": "Theorie Y geht davon aus, dass Menschen leisten wollen und Verantwortung übernehmen. Theorie X sieht Menschen als arbeitsscheu, die Kontrolle brauchen (McGregor, 1960)."}, {"q": "Aylin Demir überträgt Leon Becker die Planung der Azubi-Infotage mit eigener Entscheidung über Ablauf und Budget. Welche Führungstechnik ist das?", "o": ["Management by Delegation", "Management by Exception", "Management by Objectives", "Autoritäre Führung"], "c": 0, "e": "Bei Management by Delegation werden Aufgabe, Kompetenz und Verantwortung zusammen übertragen. Bekannte Ausprägung ist das Harzburger Modell (Beiderwieden & Stickdorn, 2026)."}, {"q": "Malte Brandt will mit der Montageleitung ein Ziel nach SMART vereinbaren. Welche Formulierung erfüllt die Regeln?", "o": ["Krankenquote Montage bis 31.12.2027 von 6,0 % auf 5,0 % senken", "Die Montage soll ab sofort gesünder und zufriedener arbeiten", "Die Krankenquote soll irgendwann in den nächsten Jahren sinken", "Kein Monteur soll in Zukunft jemals wieder krank sein"], "c": 0, "e": "Das Ziel ist spezifisch, messbar, realistisch und hat einen Termin. Die anderen Ziele sind unklar, ohne Termin oder nicht erreichbar."}, {"q": "Eine Sachbearbeiterin aus dem Vertrieb kündigt selbst. Ihre Kündigung geht Nordstern am Donnerstag, 10.12.2026, zu. Wann endet ihr Arbeitsverhältnis nach der Grundfrist?", "o": ["Am 15.01.2027", "Am 31.12.2026", "Am 07.01.2027", "Am 31.01.2027"], "c": 0, "e": "Die Grundfrist beträgt 4 Wochen zum 15. oder zum Monatsende (§ 622 Abs. 1 BGB). 4 Wochen nach dem 10.12.2026 sind der 07.01.2027. Der nächste zulässige Termin ist der 15.01.2027."}, {"q": "Eine Kündigung geht einer Monteurin am Freitag, 08.01.2027, zu. Bis wann muss sie spätestens Kündigungsschutzklage erheben?", "o": ["Bis Freitag, 29.01.2027", "Bis Freitag, 22.01.2027", "Bis Montag, 08.02.2027", "Bis Mittwoch, 31.03.2027"], "c": 0, "e": "Die Klagefrist beträgt 3 Wochen ab Zugang der schriftlichen Kündigung (§ 4 KSchG). Vom 08.01.2027 an gerechnet endet sie am Freitag, 29.01.2027. Danach gilt die Kündigung als wirksam (§ 7 KSchG)."}, {"q": "Nordstern will einem Lageristen wegen eines Diebstahls fristlos kündigen und hört den Betriebsrat an. Wie schnell muss der Betriebsrat Bedenken mitteilen?", "o": ["Spätestens innerhalb von 3 Tagen", "Schriftlich innerhalb von einer Woche", "Innerhalb von 2 Wochen nach Kenntnis", "Innerhalb von 3 Wochen nach Zugang"], "c": 0, "e": "Bei einer außerordentlichen Kündigung muss der Betriebsrat Bedenken unverzüglich, spätestens innerhalb von 3 Tagen schriftlich mitteilen. Eine Woche gilt bei der ordentlichen Kündigung (§ 102 Abs. 2 BetrVG)."}, {"q": "Ein Monteur verlangt am Montag, 01.03.2027, Elternzeit ab 01.04.2027 für sein Kind unter drei Jahren. Ab wann besteht der besondere Kündigungsschutz?", "o": ["Ab dem Verlangen am 01.03.2027", "Erst ab Beginn der Elternzeit am 01.04.2027", "Erst nach 6 Monaten Elternzeit", "Es besteht gar kein besonderer Kündigungsschutz"], "c": 0, "e": "Der Schutz beginnt mit dem Verlangen, frühestens 8 Wochen vor Beginn der Elternzeit (§ 18 BEEG). Der 01.03.2027 liegt innerhalb dieser 8 Wochen, also gilt der Schutz ab diesem Tag."}, {"q": "Angenommen, 2026 kündigen 12 Beschäftigte selbst, der durchschnittliche Personalbestand beträgt 238. Wie hoch ist die Fluktuationsquote?", "o": ["5,04 %", "5,93 %", "5,00 %", "4,20 %"], "c": 0, "e": "Fluktuationsquote = Kündigungen durch Beschäftigte ÷ durchschnittlicher Personalbestand × 100. 12 ÷ 238 × 100 = 5,04 %. Gegenüber 5,93 % im Jahr 2025 wäre das eine Verbesserung."}, {"q": "Der Vertrieb hat 15 Beschäftigte mit je 220 Soll-Arbeitstagen und 99 Krankheitstagen im Jahr. Wie hoch ist die Krankenquote im Vertrieb?", "o": ["3,00 %", "6,60 %", "4,50 %", "0,30 %"], "c": 0, "e": "Soll-Arbeitstage = 15 × 220 = 3.300. Krankenquote = 99 ÷ 3.300 × 100 = 3,00 %. Der Vertrieb liegt damit deutlich unter dem Wert von 6,00 % für ganz Nordstern."}, {"q": "Nordstern hatte 2025 genau 3.115 Krankheitstage bei durchschnittlich 236 Beschäftigten. Wie liegt Nordstern damit im Vergleich zu Deutschland mit 14,6 Tagen?", "o": ["Mit rund 13,2 Tagen je Beschäftigten leicht darunter", "Mit rund 15,8 Tagen je Beschäftigten deutlich darüber", "Mit genau 14,6 Tagen je Beschäftigten gleich auf", "Mit rund 6,0 Tagen je Beschäftigten weit darunter"], "c": 0, "e": "3.115 ÷ 236 = 13,2 Tage. Der Durchschnitt in Deutschland lag 2025 bei 14,6 Arbeitstagen (Destatis, 2026). 6,00 % ist die Krankenquote, keine Zahl von Tagen."}, {"q": "Angenommen, der Umsatz steigt 2026 auf 52,0 Mio. €, der Personalaufwand bleibt bei 15,6 Mio. €. Wie verändert sich die Personalaufwandsquote?", "o": ["Sie sinkt von 32,5 % auf 30,0 %", "Sie steigt von 32,5 % auf 33,3 %", "Sie bleibt bei 32,5 %", "Sie sinkt von 32,5 % auf 28,0 %"], "c": 0, "e": "Personalaufwandsquote = Personalaufwand ÷ Umsatz × 100. 15,6 ÷ 52,0 × 100 = 30,0 %. Bei gleichem Aufwand und mehr Umsatz sinkt der Anteil."}], "lernen": [{"t": "Duales System", "x": "Ausbildung an zwei Lernorten, im Betrieb nach der Ausbildungsordnung und in der Berufsschule nach dem Rahmenlehrplan."}, {"t": "Nettopersonalbedarf", "x": "Bruttopersonalbedarf minus fortgeschriebener Personalbestand. Positiv heißt einstellen, negativ heißt freistellen."}, {"t": "Günstigkeitsprinzip", "x": "Vom Tarifvertrag darf nur abgewichen werden, wenn die Abweichung für den Arbeitnehmer günstiger ist oder der Tarif sie erlaubt."}, {"t": "Akkordrichtsatz", "x": "Grundlohn plus Akkordzuschlag je Stunde. Bei Nordstern 20,00 € plus 20 % gleich 24,00 €."}, {"t": "Nettoentgelt", "x": "Bruttoentgelt minus Steuern minus Arbeitnehmeranteil zur Sozialversicherung."}, {"t": "Job Enrichment", "x": "Aufgabenbereicherung mit mehr Verantwortung und Entscheidung, also eine Erweiterung nach oben."}, {"t": "Hygienefaktoren", "x": "Faktoren wie Entgelt oder Arbeitsbedingungen, die Unzufriedenheit verhindern, aber nicht motivieren (Herzberg)."}, {"t": "Sozialauswahl", "x": "Auswahl bei betriebsbedingter Kündigung nach Betriebszugehörigkeit, Lebensalter, Unterhaltspflichten und Schwerbehinderung."}, {"t": "Fluktuationsquote", "x": "Kündigungen durch Beschäftigte geteilt durch den durchschnittlichen Personalbestand mal 100."}, {"t": "Operator", "x": "Arbeitsanweisung in einer Aufgabe, z. B. nennen, erklären, berechnen oder beurteilen. Er sagt, wie ausführlich die Antwort sein muss."}, {"t": "Duales System", "x": "Ausbildung an zwei Lernorten. Der Betrieb bildet nach der Ausbildungsordnung des Bundes aus, die Berufsschule unterrichtet nach dem Rahmenlehrplan der Länder (Beiderwieden & Stickdorn, 2026)."}, {"t": "Assessment-Center", "x": "Gruppenauswahlverfahren über einen oder mehrere Tage. Mehrere Beobachter bewerten mehrere Bewerber in mehreren Übungen wie Postkorb, Rollenspiel, Präsentation und Gruppendiskussion nach festen Kriterien (Beiderwieden & Stickdorn, 2026)."}, {"t": "Mindeststandards gelten für alle", "x": "Mindestlohn, Mindesturlaub, Entgeltfortzahlung, Arbeitszeitgesetz und AGG gelten in jedem Arbeitsverhältnis. Von Mindestlohn und gesetzlichem Mindesturlaub darf auch ein Tarifvertrag nicht nach unten abweichen."}, {"t": "Probe der Abrechnung", "x": "Netto plus Steuern plus Arbeitnehmeranteil zur Sozialversicherung muss wieder das Brutto ergeben. Bei Lisa 2.532,52 € + 558,35 € + 859,13 € = 3.950,00 €."}, {"t": "Personalentwicklung im weiten Sinn", "x": "Bildung (Ausbildung, Fortbildung, Umschulung) plus Förderung (z. B. Karriereplanung, Job Rotation, Coaching) plus Organisationsentwicklung (Beiderwieden & Stickdorn, 2026)."}, {"t": "SMART formulierte Ziele", "x": "Spezifisch, messbar, attraktiv, realistisch, terminiert. Beispiel für das Lager, die Fehlerquote beim Kommissionieren sinkt bis zum 30.06.2027 auf unter 1 %."}, {"t": "Situatives Führen", "x": "Die Führungskraft wählt den Stil nach dem Reifegrad der Mitarbeitenden, von unterweisen über überzeugen und beteiligen bis delegieren (Hersey & Blanchard, 1969)."}, {"t": "Längere Fristen nur für den Arbeitgeber", "x": "Kündigt Thomas Albers selbst, gilt für ihn die Grundfrist von vier Wochen zum 15. oder zum Monatsende, wenn Vertrag oder Tarif nichts anderes regeln."}], "sortier": [{"titel": "Faktencheck quer durch den Kurs", "auftrag": "Prüfe jede Aussage und bringe sie in das richtige Depot.", "kategorien": [{"id": "a", "name": "Stimmt"}, {"id": "b", "name": "Stimmt nicht"}], "items": [{"text": "Die Probezeit in der Ausbildung dauert 1 bis 4 Monate", "kat": "a", "expl": "So steht es in § 20 BBiG. Bei Mia dauert sie 4 Monate."}, {"text": "Nettobedarf Montage 2027 ist 120 − 95 = 25", "kat": "a", "expl": "Bruttobedarf 120 minus fortgeschriebener Bestand 95 ergibt 25."}, {"text": "Bei Nordstern braucht jede Einstellung die Zustimmung des Betriebsrats", "kat": "a", "expl": "Nordstern hat mehr als 20 wahlberechtigte Beschäftigte. Darum gilt § 99 BetrVG."}, {"text": "Ein Tarifvertrag darf zugunsten Beschäftigter überschritten werden", "kat": "a", "expl": "Das ist das Günstigkeitsprinzip nach § 4 Abs. 3 TVG."}, {"text": "Akkord, Stückgeld 24,00 € ÷ 4 = 6,00 € je Rahmen", "kat": "a", "expl": "Akkordrichtsatz geteilt durch Normalleistung ergibt das Stückgeld."}, {"text": "Gegen eine Kündigung muss man binnen 3 Wochen klagen", "kat": "a", "expl": "Sonst gilt die Kündigung als wirksam (§§ 4, 7 KSchG)."}, {"text": "Der Mindestlohn 2026 beträgt 13,90 € je Stunde", "kat": "a", "expl": "Das legt die Verordnung MiLoV5 fest. Ab 2027 sind es 14,60 €."}, {"text": "Eine Befristung per E-Mail ist wirksam", "kat": "b", "expl": "Eine Befristung braucht die Schriftform (§ 14 Abs. 4 TzBfG). Sonst gilt der Vertrag als unbefristet."}, {"text": "Auszubildende haben Anspruch auf den Mindestlohn", "kat": "b", "expl": "Azubis sind ausgenommen (§ 22 MiLoG). Für sie gilt die Mindestausbildungsvergütung."}, {"text": "Entgeltfortzahlung gibt es ab dem ersten Arbeitstag", "kat": "b", "expl": "Der Anspruch beginnt erst nach 4 Wochen Beschäftigung (§ 3 Abs. 3 EFZG)."}, {"text": "Eine Gehaltserhöhung ist nach Herzberg ein Motivator", "kat": "b", "expl": "Entgelt ist ein Hygienefaktor. Es verhindert Unzufriedenheit, motiviert aber nicht dauerhaft."}, {"text": "Eine Kündigung per E-Mail ist wirksam", "kat": "b", "expl": "Die Kündigung braucht Papier mit Unterschrift (§ 623 BGB). Per E-Mail ist sie nichtig."}, {"text": "Die Fluktuationsquote zählt auch Renteneintritte", "kat": "b", "expl": "Gezählt werden nur Kündigungen durch die Beschäftigten selbst."}, {"text": "Job Enlargement bedeutet mehr Verantwortung", "kat": "b", "expl": "Enlargement heißt mehr Aufgaben auf gleichem Niveau. Mehr Verantwortung ist Job Enrichment."}]}, {"titel": "Welcher Bereich der Personalarbeit?", "auftrag": "Ordne jede Maßnahme dem Aufgabenbereich der Personalabteilung zu, zu dem sie gehört.", "kategorien": [{"id": "a", "name": "Gewinnen"}, {"id": "b", "name": "Fördern und führen"}, {"id": "c", "name": "Trennen und steuern"}], "items": [{"text": "Stellenanzeige nach AIDA mit (m/w/d)", "kat": "a", "expl": "Die Anzeige wirbt um neue Beschäftigte. Das gehört zur Personalbeschaffung."}, {"text": "Nutzwertanalyse für die Endauswahl", "kat": "a", "expl": "Mit ihr wählt Nordstern Jana Hoffmann aus. Das ist Personalauswahl."}, {"text": "Ausbildungsvertrag mit Mia Schulz eintragen lassen", "kat": "a", "expl": "Die Ausbildung gewinnt den eigenen Nachwuchs."}, {"text": "Sachgrundlose Befristung bis zu 2 Jahren", "kat": "a", "expl": "Die Befristung regelt den Arbeitsvertrag bei der Einstellung."}, {"text": "Personalleasing für die Frühjahrsspitze", "kat": "a", "expl": "Leiharbeit ist ein externer Weg der Personalbeschaffung."}, {"text": "Job Enrichment für eine Lagerfachkraft", "kat": "b", "expl": "Mehr Verantwortung entwickelt die Person weiter. Das ist Personalentwicklung."}, {"text": "Mentoring für eine neue Teamleiterin", "kat": "b", "expl": "Eine erfahrene Person begleitet die Nachwuchskraft. Das ist Förderung."}, {"text": "Zielvereinbarung nach Management by Objectives", "kat": "b", "expl": "Führen über Ziele ist eine Führungstechnik."}, {"text": "Kritikgespräch mit Ich-Botschaften", "kat": "b", "expl": "Mitarbeitergespräche sind ein Werkzeug der Personalführung."}, {"text": "Führungsseminar für Jonas Petersen", "kat": "b", "expl": "Das Seminar bereitet Jonas auf die Teamleitung vor. Das ist Personalentwicklung."}, {"text": "Sozialauswahl im Rechnungswesen", "kat": "c", "expl": "Sie bestimmt, wem betriebsbedingt gekündigt wird. Das ist Personalfreistellung."}, {"text": "Kündigungsfrist für Thomas Albers berechnen", "kat": "c", "expl": "Die Frist gehört zur Beendigung des Arbeitsverhältnisses."}, {"text": "Aufhebungsvertrag mit Abfindung", "kat": "c", "expl": "Der Vertrag beendet das Arbeitsverhältnis einvernehmlich. Das ist externe Freistellung."}, {"text": "Kennzahlen-Cockpit mit Ampel", "kat": "c", "expl": "Das Cockpit zeigt die Lage auf einen Blick. Das ist Personalcontrolling."}, {"text": "Fluktuationsquote von 5,93 % berechnen", "kat": "c", "expl": "Kennzahlen berechnen und deuten gehört zum Personalcontrolling."}]}]}]};
